(window.GIM_TP=window.GIM_TP||{})["Z.Beshalach.0"]={"from":0,"a":[[["וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְלֹא נָחָם אֱלהִים דֶּרֶךְ אֶרֶץ פְּלִשְׁתִּים וְגוֹ'. רִבִּי שִׁמְעוֹן פָּתַח, (חבקוק ג׳:א׳) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא עַל שִׁגְיוֹנוֹת. הַאי קְרָא קַשְׁיָא, וְאִית לְאִסְתַּכְּלָא בֵּיהּ, מַאי שְׁנָא תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא, יַתִּיר מִכָּל שְׁאַר נְבִיאֵי עָלְמָא, דְּלָא כְּתִיב בְּהוּ תְּפִלָּה לִישַׁעְיָה הַנָּבִיא, אוֹ לְיִרְמִיָּה, אוֹ לִיחֶזְקֵאל, אוֹ לְהוֹשֵׁעַ, אוֹ לִשְׁאַר נְבִיאֵי עָלְמָא.","אֶלָּא הָכִי תָּנֵינָן, אֱלִישָׁע זָכָה בְּהַאי עָלְמָא מַה דְּלָא זָכָה נְבִיאָה אָחֳרָא, בַּר מִמֹּשֶׁה. (ועם כל דא לא בעא לאטרחא למריה) תָּא חֲזִי, מַאי כְּתִיב, (מלכים ב ד׳:ח׳) וַיְהִי הַיּוֹם וַיַּעֲבוֹר אֱלִישָׁע אֶל שׁוּנֵם וְשָׁם אִשָּׁה גְּדוֹלָה. מַאי אִשָּׁה גְּדוֹלָה. אֶלָּא גְּדוֹלָה בְּעוֹבָדָהָא, דְּכָל בְּנֵי (ס\"א דרא) בֵּיתָא, מִשְׁתַּבְּחִין בָּהּ, וְהִיא עִקָרָא דְּבֵיתָא, וּבְגִין דְּבַעֲלָהּ לָא הֲוָה שְׁכִיחַ בְּבֵיתָא, לְמֶהֱוֵי עִקָרָא, לָא הֲוָה אִדְכַּר הוּא, אֶלָּא הִיא.","וְתוּ, וְשָׁם אִשָּׁה גְּדוֹלָה: גְּדוֹלָה עַל כָּל שְׁאַר נְשֵׁי עָלְמָא, דְּהָא שְׁאַר נְשֵׁי עָלְמָא, כַּד חָמָאן אוּשְׁפִּיזָא בְּבֵיתָא, מִצְטַעֲרָן בֵּיהּ, וְדָחֲקָן בֵּיהּ כָּל שֶׁכֵּן לְאַפָּקָא עָלֵיהּ מָמוֹנָא, וְהִיא חֲדַת בֵּיהּ בְּאוּשְׁפִּיזָא, וּלְאַפָּקָא עָלֵיהּ מָמוֹנָא, כָּל שֶׁכֵּן כֵּיוָן דְּחָמַת לֵיהּ לֶאֱלִישָׁע חַדַת בֵּיהּ לַחֲדָּא. וְעַל דָּא, שְׁבָחָא דְּכֹלָּא דְּאִתְּתָא הִיא, דְּהָא אוּשְׁפִּיזָא דְּבֵיתָא דְּאִתְּתָא הִיא. וּבְגִין כַּךְ וְשָׁם אִשָּׁה גְּדוֹלָה, גְּדוֹלָה עַל שְׁאַר נָשִׁין.","וַתֹּאמֶר אֶל אִישָׁהּ הִנֵּה נָא יָדַעְתִּי כִּי אִישׁ אֱלהִים קָדוֹשׁ הוּא, בְּמָּה יַדְעָה. אֶלָּא הָא אוּקְמוּהָ חַבְרַיָּא, דְּשׁוּשִׁיפָא חִוָּורָא זְרִיקַת לֵיהּ בְּעַרְסֵיהּ. וְלָא חָמַת בֵּיהּ קֶרִי מֵעוֹלָם, וְלָא אַעְבָּר זְבוּבָא בְּפָתוֹרֵיהּ.","הָנֵי מִילֵי קַשְׁיָין, אִי תֵּימָא דְּלָא חָמַת בֵּיהּ קֶרִי, הָא סַגִּיאִין אִינּוּן בְּנֵי נָשָׁא הָכִי בְּעָלְמָא, מַה שִׁנּוּיָא הָכָא. וְאִי תֵּימָא דְּלָא עָבַר זְבוּבָא בְּפָתוֹרֵיהּ. אֲמַאי כְּתִיב, הִנֵּה נָא יָדַעְתִּי, וְכִי הִיא יַדְעַת, וְלָא אָחֳרָא, וְהָא כָּל אִינּוּן דְּחָמוּ לֵיהּ אָכִיל בְּפָתוֹרֵיהּ הֲווֹ יַדְעֵי.","אֶלָּא שַׁפִּיר קָאַמְרַת, אֲבָל הִנִּה נָא יָדַעְתִּי, הִיא יַדְעָה, וְלָא אָחֳרָא, בְּגִין דְּהִיא מְתַקְנַת עַרְסֵיהּ, בְּשַׁעֲתָא דְּשָׁכִיב בְּלֵילְיָא, וּבְשַׁעֲתָא דְּקָאִים בְּצַפְרָא. וְהַאי דְּקַאמְרֵי דְּשׁוּשִׁיפָא חִוָּורָא זְרִיקַת לֵיהּ בְּעַרְסֵיהּ, הָכִי הֲוָה, וּבָהּ יַדְעָה, דְּאָרְחָא דְּעָלְמָא, כֵּיוָן דְּקָאִים בַּר נָשׁ מֵעַרְסֵיהּ, סָלִיק שׁוּשִׁיפָא דְּנָאִים בָּהּ, רֵיחָא מְנוּוָלָא. וְהַאי, בְּשַׁעֲתָא דְּסַלְקַת הַהוּא שׁוּשִׁיפָא מֵעַרְסֵיהּ, הֲוָה סָלִיק רֵיחִין, (קכ\"ז) כְּרֵיחִין דְּגִנְתָּא דְּעֵדֶן. אָמְרָה אִי לָאו דְּקַדִּישָׁא הוּא, וּקְדוּשָׁה דְּמָרֵיהּ עָלֵיהּ, לָא סָלִיק רֵיחָא קַדִּישָׁא הָכִי.","בְּגִינֵי כַּךְ, בָּעֵי לְאִתְפָּרְשָׁא מִן בֵּיתָא, דְּלָא אִזְדְּהַר בַּר נָשׁ כָּל כַּךְ בְּבֵיתָא. אֲבָל אַמְרַת, (מלכים ב ד׳:י׳) נַעֲשֶׂה נָא עֲלִיַּית קִיר קְטַנָּה וְנָשִׂים לוֹ שָׁם מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, אַרְבַּע אִלֵּין לָמָּה. אֶלָּא בְּגִין דְּאִינּוּן תִּקּוּנָא דִּכְנֶסֶת יִשְׂרָאֵל, דְּאִתְקְרִיאַת עֲלִיַּית קִיר, וְהָכִי אִתְקַרְיא, כְּמָה דִּכְתִּיב, (ישעיהו ל״ח:ב׳) וַיַּסֵּב חִזְקִיָּה פָּנָיו אֶל הַקִּיר.","מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, לָאו אִינּוּן כְּתִיקוּן דְּשִׁמּוּשָׁא, דְּהָא כִּסֵּא קָא בָּעֵי בְּקַדְמִיתָא, וּלְבָתַר שֻׁלְחָן, לְבָתַר מְנוֹרָה, לְבָתַר מִטָּה, אֲמַאי אַקְדִּימַת מִטָּה. בְּגִין דְּהִיא חֲבִיבָה עָלֵיהּ יַתִּיר מִכֹּלָּא, וְאַקְדִּים בַּר נָשׁ מַה דְּחָבִיב עָלֵיהּ.","(מלכים ב ד׳:י׳-י״א) וַיְהִי הַיּוֹם וַיָּבוֹא שָׁמָּה. וַיְהִי הַיּוֹם, מַאן הוּא יוֹמָא דָּא. אֶלָּא כְּמָה דְּאוּקְמוּהָ. וְתָּא חֲזֵי. הַהוּא יוֹמָא, יוֹמָא טָבָא דְּרֹאשׁ הַשָּׁנָה הֲוָה, דְּאִתְפְּקָדוּ בֵּיהּ עֲקָרוֹת דְּעָלְמָא, וְאִתְפַּקְּדָן בֵּיהּ בְּנֵי עָלְמָא. קָרָא לַשּׁוּנַמִּית וְאָמַר, (מלכים ב ד׳:י״ג) הִנֵּה חָרַדְתְּ אֵלֵינוּ אֶת כָּל הַחֲרָדָה הַזֹּאת. בְּגִינֵי כַּךְ, אִצְטְרִיכְנָא לְעַיְּינָא יוֹמָא דָּא בְּדִינִי דְּעָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא דָּאִין בְּיוֹמָא דָּא לְעָלְמָא, וּבְגִין דְּאִתְפָּרַשְׁנָא בִּלְחוֹד בַּאֲתָר דָּא, אִצְטְרִיכְנָא לְאִסְתַּכְּלָא בִּרְגִיזוּ דְּעָלְמָא."],[[0,"ויהי בשלח פרעה וגו':","ר\"ש פתח תפלה לחבקוק הנביא על שגיונות. מקרא זה קשה, ויש להסתכל בו, מהו השינוי, שכתוב, תפלה לחבקוק הנביא יותר מכל שאר נביאי העולם, שלא כתוב בהם, תפלה לישעיהו הנביא, או לירמיה או ליחזקאל או להושע או לשאר נביאי העולם."],[1,"אלא הכי תנינן וכו':","ומשיב. אלא כך למדנו. אלישע זכה בעולם הזה מה שלא זכה נביא אחר, חוץ ממשה. בוא וראה, מה כתוב, ויהי היום ויעבור אלישע אל שונם ושם אשה גדולה. מהו אשה גדולה. אלא היא גדולה במעשים, שכל בני הבית משתבחים בה, והיא עקרת הבית. ומשום שבעלה לא היה נמצא בבית שיהיה עיקר הבית, לא היה נזכר הוא אלא היא."],[2,"ותו, ושם אשה גדולה:","ועוד יש לפרש, ושם אשה גדולה, שהיא גדולה על כל שאר נשים שבעולם. כי שאר נשי העולם כשרואים אורח בבית, מצטערות עליו ודוחקות אותו ומכל שכן להוציא עליו כסף, וזו, שמחה באורח, ומוציאה עליו כסף. כל שכן, כיון שראתה את אלישע, שמחה בו מאד. ועל כן, כל השבח היא לאשה, כי אורח הבית, של האשה הוא, ומשום זה כתוב, ושם אשה גדולה. שהיא גדולה על שאר הנשים."],[3,"ותאמר אל אישה הנה נא ידעתי וגו':","שואל. במה ידעה שהוא איש קדוש. ומשיב. אלא בארו החברים, שסדין לבן הטילה במטתו ולא ראתה בו קרי מעולם. גם לא עבר זבוב על שלחנו."],[4,"הני מילי קשיין וכו':","שואל. דברים אלו קשים. אם תאמר שלא ראתה בו קרי, הרי רבים הם האנשים בעולם כן, שאינם רואים קרי, ומהו השינוי שבכאן. ואם תאמר שלא עבר זבוב על שלחנו, למה כתוב, הנה נא ידעתי, וכי היא ידעה ולא אחר, הרי כל אלו שראו אותו אוכל על שלחנו היו יודעים כמוה."],[5,"אלא שפיר קאמרת וכו':","ומשיב. אלא יפה אמרה, אבל הנה נא ידעתי, היא ידעה ולא אחר, משום שהיא היתה מתקנה מטתו בשעה ששכב בה בלילה ובשעה שקם בבקר. ומה שאמרו, שסדין לבן הטילה במטתו, כן היה, ובו היתה יודעת, כי מדרך העולם הוא, שכיון שאדם קם ממטתו, מעלה הסדין שישן עליו, ריח מזוהם. וזה, בשעה שהעלתה הסדין ממטתו, היה מעלה ריחות כריחות שבגן עדן. אמרה, אם לא שהוא קדוש וקדושת אדונו עליו, לא היה עולה ריח קדוש מן הסדין."],[6,"בגיני כך בעי וכו':","משום זה, הוא צריך לפרוש מן הבית, כי אין אדם יכול להזהר כל כך בבית, אבל, אמרה, נעשה נא עליית קיר קטנה, ונשים לו שם מטה ושלחן וכסא ומנורה. שואל, ארבע אלו למה. ומשיב, אלא משום שהם תקון כנסת ישראל, שהיא מלכות, הנקראת עליית \u0003קיר.\u0004 וכן היא נקראת, שכתוב, ויסב חזקיה פניו אל \u0003הקיר.\u0004"],[7,"מטה ושלחן וכסא ומנורה:","שואל. סדר הכתוב אינו כסדר השמוש, שהרי כסא צריכים מתחילה, ואח\"כ שלחן, ואח\"כ מנורה ואח\"כ מטה, למה הקדימה מטה. ומשיב, משום שמטה חביבה עליה יותר מכל, ואדם מקדים מה שחביב עליו. כי במטה ראתה קדושה עליונה יותר מבכולם. (כמ\"ש להלן אות י\"ג)."],[8,"ויהי היום ויבא שמה:","שואל. ויהי היום, מי הוא יום זה. ומשיב, אלא כמו שבארוה, ובוא וראה, יום ההוא, יום טוב של ראש השנה היה, שנפקדו בו עקרות העולם ונפקדו בו בני העולם. קרא לשונמית ואמר, הנה חרדת אלינו את כל החרדה הזאת, בשביל זה אני צריך לעיין ביום הזה בדיני העולם, משום שהקב\"ה דן ביום הזה את העולם, ובשביל שנפרשתי לבדי במקום הזה בעלית קיר שעשיתי לי, אני צריך להסתכל בדיני העולם. דהיינו כמו שאומר להלן, שמי שנפרד לבדו ביום הדין, אע\"פ שהוא זכאי הוא נתפס מתחילה."]],[[0,"","וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְלֹא נָחָם אֱלֹהִים דֶּרֶךְ אֶרֶץ פְּלִשְׁתִּים וְגוֹ'. רַבִי שִׁמְעוֹן פָּתַח, (חבקוק ב) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא עַל שִׁגְינוֹת. פָּסוּק זֶה קָשֶׁה, וְיֵשׁ לְהִסְתַּכֵּל בּוֹ מַה שּׁוֹנָה תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא יוֹתֵר מִכָּל שְׁאָר נְבִיאֵי הָעוֹלָם שֶׁלֹּא כָתוּב בָּהֶם תְּפִלָּה לִישַׁעְיָה הַנָּבִיא, אוֹ לְיִרְמְיָה, אוֹ לִיחֶזְקֵאל, אוֹ לְהוֹשֵׁעַ, אוֹ לִשְׁאָר נְבִיאֵי הָעוֹלָם?"],[1,"","אֶלָּא כָּךְ שָׁנִינוּ, אֱלִישָׁע זָכָה בָּעוֹלָם הַזֶּה מַה שֶּׁלֹּא זָכָה נָבִיא אַחֵר, פְּרָט לְמֹשֶׁה. (ועם כל זה לא רצה להטריח את רבונו) בא ראה מה כתוב, (מלכים בד) ויהי היום ויעבר אלישע אל שונם ושם אשה גדולה. מה זה אשה גדולה? אלא גדולה במעשיה, שכל בני (הדּור) הבית משתבחים בה, והיא עקר הבית. ומשום שבעלה לא היה מצוי בבית להיות עקר, לא נזכר הוא, אלא היא."],[2,"","וְעוֹד, וְשָׁם אִשָּׁה גְדוֹלָה - גְּדוֹלָה עַל כָּל שְׁאָר נְשׁוֹת הָעוֹלָם. שֶׁהֲרֵי שְׁאָר נְשׁוֹת הָעוֹלָם, כְּשֶׁרוֹאוֹת אוֹרֵחַ בַּבַּיִת, מִצְטַעֲרוֹת בּוֹ וְדוֹחֲקוֹת אוֹתוֹ, וְכָל שֶׁכֵּן לְהוֹצִיא עָלָיו מָמוֹן, וְהִיא שָׂמְחָה בָּאוֹרֵחַ וּלְהוֹצִיא עָלָיו מָמוֹן, כָּל שֶׁכֵּן כֵּיוָן שֶׁרָאֲתָה אֶת אֱלִישָׁע, שָׂמְחָה בּוֹ מְאֹד. וְעַל כֵּן הַשֶּׁבַח שֶׁל הַכֹּל הוּא שֶׁל הָאִשָּׁה, שֶׁהֲרֵי הָאוֹרֵחַ שֶׁל הַבַּיִת הוּא שֶׁל הָאִשָּׁה, וְלָכֵן כָּתוּב וְשָׁם אִשָּׁה גְדוֹלָה, גְּדוֹלָה עַל שְׁאָר הַנָּשִׁים."],[3,"","וַתֹּאמֶר אֶל אִישָׁהּ הִנֵּה נָא יָדַעְתִּי כִּי אִישׁ אֱלֹהִים קָדוֹשׁ הוּא. בַּמֶּה יָדְעָה? אֶלָּא הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁסָּדִין לָבָן שָׂמָה לוֹ בְּמִטָּתוֹ, וְלֹא רָאֲתָה בּוֹ קֶרִי מֵעוֹלָם, וְלֹא עָבַר זְבוּב עַל שֻׁלְחָנוֹ."],[4,"","הַדְּבָרִים הַלָּלוּ קָשִׁים. אִם תֹּאמַר שֶׁלֹּא רָאֲתָה בּוֹ קֶרִי, הֲרֵי רַבִּים הֵם בְּנֵי אָדָם כָּאֵלֶּה בָּעוֹלָם. מָה הַשֹּׁנִי כָּאן? וְאִם תֹּאמַר שֶׁלֹּא עָבַר זְבוּב עַל שֻׁלְחָנוֹ, לָמָּה כָּתוּב הִנֵּה נָא יָדַעְתִּי? וְכִי הִיא יָדְעָה וְלֹא אַחֵר? וַהֲרֵי כָּל אֵלּוּ שֶׁרָאוּהוּ אוֹכֵל בְּשֻׁלְחָנוֹ הָיוּ יוֹדְעִים!"],[5,"","אֶלָּא יָפֶה אָמְרָה, אֲבָל הִנֵּה נָא יָדַעְתִּי - הִיא יָדְעָה וְלֹא אַחֵר, מִשּׁוּם שֶׁהִיא תִּקְנָה אֶת מִטָּתוֹ בְּשָׁעָה שֶׁשָּׁכַב בַּלַּיְלָה וּבְשָׁעָה שֶׁקָּם בַּבּקֶר. וְזֶה שֶׁאָמְרוּ שֶׁסָּדִין לָבָן שָׂמָה לוֹ בְּמִטָּתוֹ, כָּךְ הָיָה, וּבָזֶה הִיא יָדְעָה. שֶׁדֶּרֶךְ הָעוֹלָם, כֵּיוָן שֶׁעוֹמֵד אָדָם מִמִּטָּתוֹ, מַעֲלֶה הַסָּדִין שֶׁיָּשַׁן בּוֹ רֵיחַ מְנֻוָּל. וְזֶה, בְּשָׁעָה שֶׁלָּקְחָה אוֹתוֹ סָדִין מִמִּטָּתוֹ, הָיָה מַעֲלֶה רֵיחוֹת כְּרֵיחוֹת גַּן עֵדֶן. אָמְרָה, אִלּוּלֵי שֶׁקָּדוֹשׁ הוּא וּקְדֻשַּׁת אֲדוֹנוֹ עָלָיו, לֹא הָיָה מַעֲלֶה כָּזֶה רֵיחַ קָדוֹשׁ."],[6,"","מִשּׁוּם כָּךְ צָרִיךְ לִפְר!שׁ מִן הַבַּיִת, כִּי לֹא נִזְהָר אָדָם כָּל כָּךְ בַּבַּיִת. אֲבָל אָמְרָה, נַעֲשֶׂה נָּא עֲלִיַּת קִיר קְטַנָּה וְנָשִׂים לוֹ שָׁם מִטָּה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה. אַרְבָּעָה אֵלֶּה לָמָּה? אֶלָּא מִשּׁוּם שֶׁהֵם תִּקּוּן שֶׁל כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת עֲלִיַּת קִיר, וְכָךְ נִקְרֵאת, כְּמוֹ שֶׁכָּתוּב וַיַּסֵּב חִזְקִיָּה פָּנָיו אֶל הַקִּיר."],[7,"","מִטָה וְשֻׁלְחָן וְכִסֵּא וּמְנוֹרָה, הֵם אֵינָם כְּמוֹ תִּקּוּן הַשִּׁמּוּשׁ, שֶׁהֲרֵי צָרִיךְ בַּתְּחִלָּה כִּסֵּא, וְאַחַר כָּךְ שֻׁלְחָן, אַחַר כָּךְ מְנוֹרָה, אַחַר כָּךְ מִטָּה. לָמָּה הִקְדִּימָה מִטָּה? מִשּׁוּם שֶׁהִיא חֲבִיבָה עָלָיו יוֹתֵר מֵהַכֹּל, וּמַקְדִּים אָדָם מַה שֶּׁחָבִיב עָלָיו."],[8,"","וַיְהִי הַיּוֹם וַיָּבֹא שָׁמָּה. וַיְהִי הַיּוֹם, אֵיזֶהוּ יוֹם זֶה? אֶלָּא כְּמוֹ שֶׁבֵּאֲרוּהָ. וּבֹא רְאֵה, אוֹתוֹ יוֹם, יוֹם טוֹב שֶׁל רֹאשׁ הַשָּׁנָה הָיָה, שֶׁבּוֹ נִפְקְדוּ עַקְרוֹת הָעוֹלָם וְנִפְקָדִים בּוֹ בְּנֵי הָעוֹלָם, קָרָא לַשּׁוּנַמִּית וְאָמַר, הִנֵּה חָרַדְתְּ אֵלֵינוּ אֶת כָּל הַחֲרָדָה הַזֹּאת. מִשּׁוּם כָּךְ הִצְטַעַרְתִּי לְעַיֵּן הַיּוֹם הַזֶּה בְּדִינֵי הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן בַּיּוֹם הַזֶּה אֶת הָעוֹלָם. וּמִשּׁוּם שֶׁנִּפְרַדְתִּי לְבַד בְּמָקוֹם זֶה, הִצְטָרַכְתִּי לְהִסְתַּכֵּל בָּרֹגֶז שֶׁל הָעוֹלָם."]]],[["(מלכים ב ד׳:י״ג) וּמַה לַעֲשׂוֹת לָךְ הֲיֵשׁ לְדַבֵּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא. וְכִי מִלָּה דָּא לְמָה אִצְטְרִיכָא לְגַבֵּי אִתְּתָא, דְּלָא נַפְקַת וְלָא אַזְלַת וְלָא עָאלַת בְּהֵיכְלָא דְּמַלְכָּא. אֶלָּא, יוֹמָא דָּא הֲוָה גָּרִים, דְּכָל בְּנֵי עָלְמָא יַתְבִין (נ\"א קיימין) בְּדִינָא, וּבְהַהוּא יוֹמָא אִקְרֵי קוּדְשָׁא בְּרִיךְ הוּא מֶלֶךְ. הַמֶּלֶךְ הַמִּשְׁפָּט. אָמַר לָהּ, אִי אַתְּ אִצְטְרִיךְ לָךְ לְגַבֵּי מַלְכָּא עִלָּאָה, עַל עוֹבָדִין דִּי בִּידָךְ.","וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. מַאי קָאַמְרַת. אֶלָּא בְּשַׁעֲתָא (נ\"א בזמנא) דְּדִינָא תַּלְיָא בְּעָלְמָא, לָא יִתְפְּרַשׁ בַּר נָשׁ בִּלְחוֹדוֹי, וְלָא יִתְרְשִׁים לְעֵילָּא, וְלָא יִשְׁתְּמוֹדְעוּן בֵּיהּ בִּלְחוֹדוֹי, דְּהָא בְּזִמְנָא (אחרא) דְּדִינָא תַּלְיָא בְּעָלְמָא, אִינּוּן דְּאִשְׁתְּמוֹדְעוּן וּרְשִׁימִין בִּלְחוֹדַיְיהוּ, אַף עַל גַּב דְּזַכָּאִין אִינּוּן, אִינּוּן אִתָּפְסָן בְּקַדְמִיתָא. וְעַל דָּא, לָא לִבָעֵי לֵיהּ לְאִינִישׁ, לְאִתְפָּרְשָׁא מִבֵּין עַמָּא לְעָלַם, דִּבְכָל זִמְנָא רַחֲמֵי דְּקוּדְשָׁא בְּרִיךְ הוּא עַל עַמָּא כֻּלְּהוּ כְּחַד. (ולא לבעי ליה לאיניש לאתפרש מן עמא לעלם) וּבְגִינֵי כַּךְ אָמְרָה, בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת, וְלָא בְּעֵינָא לְאִתְפָּרְשָׁא מִנַּיְיהוּ, כְּמָה דְּעָבֵדְנָא עַד יוֹמָא דֵּין.","וַיֹּאמֶר גֵּחֲזִי אֲבָל בֵּן אֵין לָהּ וְגוֹ'. אָמַר לָהּ אֱלִישָׁע. הָא וַדַּאי שַׁעֲתָא קַיְּימָא, דְּהָא יוֹמָא גָּרִים. וַיֹּאמֶר לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אַתְּ חוֹבֶקֶת בֶּן. וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֶּן לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אֲשֶׁר דִּבֶּר אֵלֶיהָ אֱלִישָׁע. לַמּוֹעֵד וַדַּאי. לְבָתַר מִית. מַאי טַעֲמָא מִית. אֶלָּא בְּגִין דְּאִתְיְיהִב לָהּ, וְלָא לְבַעְלָהּ. וּמֵאֲתָר דְּנוּקְבָּא אִתְקָשָּׁר, וּמַאן דְּאִתְקָשָּׁר בְּנוּקְבָּא, מוֹתָא אִזְדַּמְּנַת קָמֵיהּ. מְנָא לָן דְּלָהּ אִתְיְהִיב, דִּכְתִּיב אַתְּ חוֹבֶקֶת בֵּן.","תָּא חֲזֵי, בְּאַבְרָהָם כְּתִיב (בראשית י״ח:י׳) שׁוֹב אָשׁוּב אֵלֶיךָ, וְלֹא אֵלֶיהָ, אֵלֶיךָ וַדַּאי, בָּךְ אִתְקָשָּׁר, וְלָא בְּנוּקְבָא. מַאן דְּאָתֵי מִסִּטְרָא דְּנוּקְבָּא, מוֹתָא אַקְדִּים לְרַגְלוֹי. וַתַּעַל וַתַּשְׁכִּיבֵהוּ עַל מִטַּת אִישׁ הָאֱלהִים, בְּגִין דְּתַמָּן חָמַת קְדוּשָׁה עִלָּאָה מִכֹּלָּא.","וַיֹּאמֶר לָהּ הֲשָׁלוֹם לָךְ הֲשָׁלוֹם לְאִישֵׁךְ הֲשָׁלוֹם לַיָּלֶד. מִכָּאן, דְּהִיא עִקָרָא דְּבֵיתָא, וְלֹא עוֹד אֶלָּא דְּאִיהִי אַזְלַת אֲבַתְרֵיהּ, וְלֹא בַּעְלָהּ. וַיִּגַּשׁ גֵּחֲזִי לְהָדְפָהּ הָא אוּקְמוּהָ.","וַיֹּאמֶר אִישׁ הָאֱלהִים הַרְפֵּה לָהּ. מַאי שְׁנָא הָכָא דְּאָמַר אִישׁ הָאֱלֹהִים, וְכַד הֲוָה בְּמָתָא אֱלִישָׁע. אֶלָּא הָכָא וַדַּאי אִישׁ הָאֱלהִים, דְּהָכָא (ס\"א הוא) חַזָא דּוּכְתֵּיהּ, וְלָא בְּמָתָא, וְלָא בְּשַׁעֲתָא דַּהֲווֹ בְּנִי נְבִיאֵי קָמֵיהּ.","וַיְיָ' הֶעְלִים מִמֶּנִּי וְגוֹ', כְּמָה דְּאַתְּ אָמֵר (בראשית י״ט:כ״ד) וַיְיָ' הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה, דָּא בֵּי דִּינָא דִּלְתַתָּא. וְלֹא הִגִּיד לִי, מַאי טַעֲמָא לֹא יָדַע אֱלִישָׁע. אֶלָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּמָה אֲנָא קָטִיל לְהַאי, אִי אֵימָא לֵיהּ, לא יָמוּת, דְּהָא נְבִזְבְּזָא דִּילֵיהּ הוּא. וַדַּאי אִית לֵיהּ לְמֵימָת, דְּהָא אִתְּמַר, דִּכְתִּיב אַתְּ חוֹבֶקֶת בֵּן, וּמֵאֲתָר דְּנוּקְבָּא גָּרִים מוֹתָא, וּבְגִינֵי כַּךְ לָא אָמַר לֵיהּ.","וַיֹּאמֶר לְגֵחֲזִי חֲגוֹר מָתְנֶיךָ וְקַח מִשְׁעַנְתִּי בְיָדְךָ וָלֵךְ. וְהָא אוּקְמוּהָ וְאִסְתְּלַק נִיסָא מִנֵּיהּ. חַי יְיָ' וְחֵי נַפְשְׁךָ אִם אֶעֶזְבֶךָּ, אֲמַאי כֵּיוָן דְּגֵיחֲזִי הֲוָה אָזִיל. אֶלָּא הִיא יַדְעַת אָרְחוֹי דְּהַהוּא רָשָׁע דְּגֵיחֲזִי, דְּלָאו אִיהוּ כְּדַאי דְּיִשְׁתְּכַח נִיסָא עַל יְדוֹי.","וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו וְגוֹ'. אֲמַאי, אֶלָּא דְּאַשְׁגַּח אֱלִישָׁע וְיָדַע דְּאַתְרָא (דאתתא הוא) דָּא הוּא דְּגָרִים, דְּאִתְקְשָׁר בֵּיהּ הַשְׁתָּא. וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו, לְקַשְּׁרָא לֵיהּ בְּאַתְרָא אָחֳרָא עִלָּאָה, אֲתָר דְּחַיִּין אִשְׁתְּכָחוּ בֵּיהּ.","וְלָא יָכִיל לְאַעְקְרָא לֵיהּ מֵאֲתָר דְּאִתְקַשָּׁר בֵּיהּ בְּקַדְמִיתָא, אֶלָּא אִתְּעַר רוּחָא חֲדָא מִלְּעֵילָּא, וְאִתְקְשַׁר בְּהַאי אֲתָר, וְאָתִיב לֵיהּ נַפְשֵׁיהּ. דְּאִי לָאו הָכִי לָא הֲוָה קָאִים לְעָלְמִין. וַיְזוֹרֵר הַנַּעַר עַד שֶׁבַע פְּעָמִים, וְלָא סָלִיק יַתִּיר, כְּמָה דְּאַתְּ אָמֵר (תהילים צ׳:י׳) יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה.","וְדָא הוּא חֲבַקּוּק נְבִיאָה, כְּמָה דְּאַתְּ אָמֵר אַתְּ חוֹבֶקֶת בֵּן. אִי הָכִי חָבוּק מִבָּעֵי לֵיהּ, אֲמַאי חֲבַקּוּק תְּרֵי. אֶלָּא, חַד דְּאִמֵּיהּ, וְחַד דְּאֱלִישָׁע, דְּאִתְחַבָּק עִמֵּיהּ. דָּבָר אַחֵר תְּרֵי חִבּוּקִין הֲווֹ בֵּיהּ, בֵּין לְהַאי סִטְרָא בֵּין לְהַאי סִטְרָא. חִבּוּקָא חֲדָא, הַהוּא אֲתָר דְּהֲוָה תָּלֵי בֵּיהּ בְּקַדְמִיתָא. חִבּוּקָא אַחֲרִינָא דְּסָלִיק לֵיהּ לְדַרְגִּין עִלָּאִין יַתִּיר, וּבְגִין כָּךְ חֲבַקּוּק תְּרֵי."],[[0,"ומה לעשות לך וגו':","שואל. וכי דבר זה נצרך אל אשה שאינה יוצאת ואינה הולכת בהיכל המלך. ומשיב. אלא יום זה היה גורם שכל בני העולם יושבים בדין, וביום ההוא נקרא הקב\"ה מלך: המלך המשפט. אמר לה, אם את צריכה למלך העליון, שיכפר לך על המעשים שבידך, אדבר ואבקש בעדך."],[1,"ותאמר בתוך עמי אנכי יושבת:","שואל. מה אומרת. ומשיב. אלא בשעה שהדין תולה על העולם, לא יפרד אדם, מן הכלל, בלבדו, ולא יצוין למעלה, ולא ידעו אותו בלבדו, כי בשעה שהדין תולה על העולם אלו שנודעו ונרשמו בלבדם, אע\"פ שצדיקים הם, הם נתפסים מתחילה. וע\"כ, אין אדם צריך לפרוש מן העם לעולם, כי רחמי הקב\"ה נמצאים תמיד על העם כולו ביחד. ומשום זה אמרה, בתוך עמי אנכי יושבת, ואיני רוצה להפרד מהם, כמו שעשיתי עד היום הזה."],[2,"ויאמר גחזי אבל בן אין לה וגו':","אמר לה אלישע. הרי ודאי השעה עומדת לך להושע בבן, כי היום גורם. כי בראש השנה נפקדו עקדות כנ\"ל. ויאמר למועד הזה וגו' ותהר האשה ותלד בן וגו', ואחר כך מת. שואל, מה הטעם שמת. ומשיב. אלא משום שהבן ניתן לה ולא לבעלה, וממקום הנקבה נקשר, ומי שנקשר בנקבה, מיתה נועדת לו. ומאין לנו שהוא ניתן לה, כי כתוב, את חובקת בן."],[3,"תא חזי באברהם וכו':","בוא וראה, באברהם כתוב, שוב אשוב אליך, ולא אליה. אליך ודאי, בך התקשר ולא בנקבה. כי מי שבא מצד הנקבה, המות מקדים אותו. ותעל ותשכיבהו על מטת איש האלקים, משום שראתה שם קדושה עליונה יותר מבכולם."],[4,"ויאמר לה השלום לך השלום לאישך וגו':","מכאן, שהיא עקרת הבית, שהקדים שלומה לשלום בעלה. ולא עוד, אלא שהיא הלכה אחריו, אחר הנביא, ולא בעלה. ויגש גחזי להדפה. כבר בארוה."],[5,"ויאמר איש האלקים וגו':","שואל. מה השינוי כאן שקראו הכתוב איש האלקים, וכאשר היה בעיר קראו אלישע. ומשיב. אלא כאן ודאי הוא איש האלקים, כי כאן הוא מקומו, ולא בעיר, ולא בשעה שהיו בני הנביאים לפניו. וע\"כ לא נקרא שם איש האלקים אלא אלישע."],[6,"וה' העלים ממני וגו':","הוא כמש\"א \u0003וה'\u0004 המטיר על סדום וגו', אשר \u0003וה'\u0004 פירושו, הוא ובית דינו, וזה בית דין שלמטה, דהיינו המלכות. \u0003ולא הגיד לי,\u0004 שואל, מה הטעם שלא ידע אלישע. ומשיב, אלא אמר הקב\"ה, ואיך אני הורג את זה, אם אומר לו, לא ימות, כי מתנה שלו הוא, ויתפלל עליו, ולא יתנו שימות. ויש לו למות ודאי, כי למדנו, שכתוב, את חובקת בן ונקשר במקום הנקבה, וממקום הנקבה נגרם המות. ומשום זה לא אמר לו."],[7,"ויאמר לגחזי חגור מתניך וגו':","ובארוה, שנסתלק ממנו מעשה הנס, שלא היה כדאי לזה. חי ה' וחי נפשך אם אעזבך. שואל, למה הפצירה בו כל כך שילך בעצמו כיון שגחזי היה הולך. ומשיב, אלא היא ידעה דרכיו של אותו רשע גחזי, שאינו כדאי שיהיה נעשה נס על ידו."],[8,"וישם פיו על פיו וגו':","שואל למה עשה כך. ומשיב, אלא שהסתכל אלישע וידע שמקום זה, של הנקבה, שנקשר בו עתה, הוא שגרם לו למות, וע\"כ וישם פיו על פיו ועיניו על עיניו כדי לקשר אותו במקום אחר עליון דהיינו במקום הזכר, מקום ששם נמצאים חיים."],[9,"ולא יכיל לאעקרא וכו':","ולא היה יכול לעקור אותו ממקום הנקבה שנקשר בו מתחילה, עד שהעיר רוח אחד מלמעלה, ונקשר במקום זה העליון, והשיב לו נפשו. ואם לא עשה כן לא היה קם לתחיה לעולם. \u0003ויזורר הנער עד שבע פעמים.\u0004 ולא עלה יותר משבע, שהוא כנגד שבעים שנות חייו, כמש\"א. ימי שנותינו בהם שבעים שנה."],[10,"ודא הוא חבקוק וכו':","וזה הוא חבקוק הנביא. כש\"א, את חובקת בן. וחבקוק הוא מלשון חיבוק, ושואל, אם כן חבוק היה צריך להקרא, ולמה נקרא חבקוק, שהמשמעות שני חיבוקים. ומשיב. אלא חיבוק אחד הוא דאמו, וחיבוק אחד של אלישע שנחבק עמו בשעה שהחיה אותו. פירוש אחר. שני חבוקים היה לו, בין מצד זה של אמו ובין מצד זה של הנביא. חבוק אחד, ממקום ההוא שהיה תלוי בו מתחילה, דהיינו מקום הנקבה כנ\"ל. חבוק אחר, שהעלה אותו יותר למדרגות העליונות. דהיינו למקום הזכר כנ\"ל. וב' חבוקים אלו נכללים בחבוק אמו, וכן בחבוק הנביא. ועל כן נקרא חבקוק שמשמעותו שני חבוקים."]],[[0,"","וּמֶה לַעֲשׂוֹת לָךְ הֲיֵשׁ לְדַבֶּר לָךְ אֶל הַמֶּלֶךְ אוֹ אֶל שַׂר הַצָּבָא, וְכִי דָבָר זֶה לְשֵׁם מָה הָאִשָּׁה צְרִיכָה, שֶׁהֲרֵי אֵינָהּ יוֹצֵאת וְלֹא הוֹלֶכֶת וְלֹא נִכְנֶסֶת לְהֵיכַל הַמֶּלֶךְ? אֶלָּא יוֹם זֶה הָיָה גּוֹרֵם, שֶׁכָּל בְּנֵי הָעוֹלָם יוֹשְׁבִים (עומדים) בְּדִין, וּבְאוֹתוֹ יוֹם נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא מֶלֶךְ. הַמֶּלֶךְ הַמִּשְׁפָּט. אָמַר לָהּ, אִם אַתְּ צְרִיכָה בִּשְׁבִילֵךְ אֵצֶל הַמֶּלֶךְ הָעֶלְיוֹן עַל הַמַּעֲשִׂים שֶׁבְּיָדַיִךְ?"],[1,"","וַתֹּאמֶר בְּתוֹךְ עַמִּי אָנֹכִי יֹשָׁבֶת. מָה אָמְרָה? אֶלָּא בְּשָׁעָה (בזמן) שֶׁהַדִּין תָּלוּי בָּעוֹלָם, שֶׁלֹּא יִפָּרֵד אָדָם לְבַדּוֹ, וְלֹא יִהְיֶה רָשׁוּם לְמַעְלָה וְלֹא יַכִּירוּ אוֹתוֹ לְבַדּוֹ, שֶׁהֲרֵי בִּזְמַן (אחר) שֶׁהַדִּין תָּלוּי בָּעוֹלָם, אוֹתָם שֶׁרְשׁוּמִים וְנוֹדָעִים לְבַדָּם - אַף עַל גַּב שֶׁהֵם צַדִּיקִים, הֵם נִתְפָּסִים בָּרִאשׁוֹנָה. וְעַל כָּךְ לֹא צָרִיךְ לָאָדָם לְהִפָּרֵד מִן הָעָם לְעוֹלָם, שֶׁבְּכָל זְמַן רַחֲמֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעָם כֻּלָּם כְּאֶחָד. (ואין צריך האדם לפרש מן העם לעולם) וְלָכֵן אָמְרָה בְּתוֹךְ עַמִּי אָנֹכִי ישָׁבֶת, וְלֹא רוֹצָה לְהִפָּרֵד מֵהֶם, כְּמוֹ שֶׁעָשִׂיתִי עַד הַיּוֹם הַזֶּה."],[2,"","וַיֹּאמֶר גֵּיחֲזִי אֲבָל בֵּן אֵין לָהּ וְגוֹ'. אָמַר לָהּ אֱלִישָׁע, הֲרֵי וַדַּאי שֶׁהַשָּׁעָה עוֹמֶדֶת, שֶׁהֲרֵי הַיּוֹם גּוֹרֵם. וַיֹּאמֶר לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אַתְּ חֹבֶקֶת בֵּן. וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן לַמּוֹעֵד הַזֶּה כָּעֵת חַיָּה אֲשֶׁר דִּבֶּר אֵלֶיהָ אֱלִישָׁע. לַמּוֹעֵד וַדַּאי. אַחַר כָּךְ מֵת. מָה הַטַּעַם מֵת? אֶלָּא מִשּׁוּם שֶׁנִּתַּן לָהּ וְלֹא לְבַעְלָהּ. וְנִקְשַׁר מִמָּקוֹם שֶׁל נְקֵבָה. וּמִי שֶׁמִּתְקַשֵּׁר בִּנְקֵבָה, הַמָּוֶת מְזֻמָּן לְפָנָיו. מִנַּיִן לָנוּ שֶׁלָּהּ הוּא נִתַּן? שֶׁכָּתוּב אַתְּ חֹבֶקֶת בֵּן."],[3,"","בֹּא רְאֵה, בְּאַבְרָהָם כָּתוּב (בראשית יח) שׁוֹב אָשׁוּב אֵלֶיךְ, וְלֹא אֵלֶיהָ. אֵלֶיךְ וַדַּאי, בְּךְ נִקְשַׁר, וְלֹא בִּנְקֵבָה. מִי שֶׁבָּא מִצַּד הַנְּקֵבָה, הַמָּוֶת מַקְדִּים לְרַגְלָיו. וַתַּעַל וַתַּשְׁכִּבֵהוּ עַל מִטַּת אִישׁ הָאֱלֹהִים, מִשּׁוּם שֶׁשָּׁם רָאֲתָה קְדֻשָּׁה עֶלְיוֹנָה מֵהַכֹּל."],[4,"","וֶאֱמָר לָהּ הֲשָׁלוֹם לָךְ הֲשָׁלוֹם לְאִישֵׁךְ הֲשָׁלוֹם לַיָּלֶד. מִכָּאן שֶׁהִיא עִקַּר הַבַּיִת, וְלֹא עוֹד, אֶלָּא שֶׁהִיא הָלְכָה אַחֲרָיו, וְלֹא בַּעְלָהּ. וַיִּגַּשׁ גֵּיחֲזִי לְהָדְפָהּ, הֲרֵי פֵּרְשׁוּהָ."],[5,"","וַיֹּאמֶר אִישׁ הָאֱלֹהִים הַרְפֵּה לָהּ. מַה שּׁוֹנֶה כָּאן שֶׁאָמַר אִישׁ הָאֱלֹהִים, וּכְשֶׁהָיָה בָּעִיר אֱלִישָׁע? אֶלָּא כָּאן וַדַּאי אִישׁ הָאֱלֹהִים, שֶׁכָּאן (הוא) מְקוֹמוֹ וְלֹא בָּעִיר, וְלֹא בְּשָׁעָה שֶׁהָיוּ בְּנֵי הַנְּבִיאִים לְפָנָיו."],[6,"","וַה' הֶעְלִים מִמֶּנִּי וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר (שם יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה, זֶה בֵּית דִּין שֶׁל מַטָּה. וְלֹא הִגִּיד לִי, מָה הַטַּעַם לֹא יָדַע אֱלִישָׁע? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמָה אֲנִי אֶהֱרֹג אֶת זֶה? אִם אֹמַר לוֹ - לֹא יָמוּת, כִּי הַמַּתָּנָה שֶׁלּוֹ הִיא. וַדַּאי שֶׁיֵּשׁ לוֹ לָמוּת, שֶׁהֲרֵי נֶאֱמַר, שֶׁכָּתוּב אַתְּ חֹבֶקֶת בֵּן, וּמִמְּקוֹם הַנְּקֵבָה גּוֹרֵם מָוֶת, וְלָכֵן לֹא אָמַר לוֹ."],[7,"","וַיֹּאמֶר לְגֵיחֲזִי חֲגֹר מָתְנֶיךְ וְקַח מִשְׁעַנְתִּי בְיָדְךְ וָלֵךְ. וַהֲרֵי פֵּרְשׁוּהָ שֶׁהִסְתַּלֵּק הַנֵּס מִמֶּנּוּ. חַי ה' וְחֵי נַפְשְׁךְ אִם אֶעֶזְבֶךָּ, לָמָּה? כֵּיוָן שֶׁגֵּיחֲזִי הָיָה הוֹלֵךְ. אֶלָּא שֶׁהִיא יָדְעָה אֶת דַּרְכֵי אוֹתוֹ גֵּיחֲזִי הָרָשָׁע, שֶׁאֵינוֹ כְּדָאִי שֶׁיִּמָּצֵא נֵס עַל יָדוֹ."],[8,"","וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו וְגוֹ', לָמָּה? אֶלָּא שֶׁאֱלִישָׁע הִשְׁגִּיחַ וְיָדַע שֶׁמָּקוֹם (שהאשה הוא) זֶה הוּא שֶׁגָּרַם, שֶׁנִּקְשָׁר בּוֹ כָּעֵת. וַיָּשֶׂם פִּיו עַל פִּיו וְעֵינָיו עַל עֵינָיו, לִקְשֹׁר אוֹתוֹ לְמָקוֹם אַחֵר עֶלְיוֹן, הַמָּקוֹם שֶׁנִּמְצָאִים בּוֹ חַיִּים."],[9,"","וְלֹא יָכֹל לַעֲקֹר אוֹתוֹ מִמָּקוֹם שֶׁנִּקְשַׁר בּוֹ בַּתְּחִלָּה, אֶלָּא עוֹרֵר רוּחַ אַחַת מִלְמַעְלָה, וְנִקְשַׁר בְּמָקוֹם זֶה וְהֵשִׁיב לוֹ אֶת נַפְשׁוֹ, שֶׁאִם לֹא כָּךְ, לֹא הָיָה עוֹמֵד לְעוֹלָמִים. וַיְזוֹרֵר הַנַּעַר עַד שֶׁבַע פְּעָמִים, וְלֹא עָלָה יוֹתֵר, כְּמוֹ שֶׁנֶּאֱמַר יְמֵי שְׁנוֹתֵינוּ בָּהֶם שִׁבְעִים שָׁנָה."],[10,"","וְזְהִ הוּא חֲבַקּוּק הַנָּבִיא, כְּמוֹ שֶׁנֶּאֱמַר אַתְּ חֹבֶקֶת בֵּן. אִם כָּךְ, הָיָה צָרִיךְ לִהְיוֹת חָבוּק, לָמָּה פַּעֲמַיִם - חֲבַקּוּק? אֶלָּא אֶחָד שֶׁל אִמּוֹ, וְאֶחָד שֶׁל אֱלִישָׁע שֶׁהִתְחַבֵּק עִמּוֹ. דָּבָר אַחֵר, שְׁנֵי חִבּוּקִים הָיוּ בוֹ, בֵּין לְצַד זֶה בֵּין לְצַד זֶה. חִבּוּק אֶחָד, אוֹתוֹ מָקוֹם שֶׁהָיָה תָּלוּי בּוֹ בַּתְּחִלָּה. חִבּוּר אַחֵר, שֶׁהֶעֱלָה אוֹתוֹ לִדְרָגוֹת יוֹתֵר עֶלְיוֹנוֹת, וְלָכֵן חֲבַקּוּק-שְׁנַיִם."]]],[["(חבקוק ג׳:א׳) תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא, מַאי תְּפִלָּה. אֶלָּא דָּא הוּא אֲתָר, דְּהֲוָה קָשִׁיר בֵּיהּ בְּקַדְמִיתָא, וְדָא הוּא תְּפִלָּה שֶׁל יָד. עַל שִׁגְיוֹנוֹת. דְּהַהוּא יוֹמָא דְּאִתְקְשָׁר בֵּיהּ, שִׁגְיוֹנוֹת דְּעָלְמָא הֲווֹ תַּלְיָין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּגְבוּרָה הֲוָה שָׁלִיט, וְעַל דָּא אִתְקְשַׁר בֵּיהּ הַאי תְּפִלָּה. (נ\"א בהאי תפלה)","דָּבָר אַחֵר תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא, תְּפִלָּה לַחֲבַקּוּק: בְּגִין חֲבַקּוּק, דְּאִיהוּ עָבִיד בְּגִינֵיהּ. יְיָ' שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי וְגוֹ', תָּא חֲזֵי, כַּד הֲוָה אִתְּעַר עָלֵיהּ רוּחָא דִּנְבוּאָה עַל אֲתָר דָּא דְּהוּא תְּפִלָּה, הֲוָה אָתֵי וַהֲוָה דָּחִיל וּמִזְדַּעְזִע. מַתְלָא אַמְרִי, מַאן דְּנָשִׁיךְ מִכַּלְבָּא, מִקָּלֵיהּ אִזְדַּעְזָע.","יְיָ' פָּעָלְךָ בְּקֶרֶב שָׁנִים חַיֵּיהוּ, מַאן פָּעָלְךָ. אֶלָּא, עָלֵיהּ קָאָמַר, דְּאִיהוּ פֹּעַל דִּילֵיהּ. בְּקֶרֶב שָׁנִים חַיֵּיהוּ. הָב לֵיהּ חַיִּין לְהַאי פָּעָלְךָ, בְּקֶרֶב שְׁנִין עִלָּאִין. דָּבָר אַחֵר, חַיֵּיהוּ דְּלָא יָמוּת כַּד בְּקַדְמִיתָא.","עַל שִׁגְיוֹנוֹת, מַאי עַל שִׁגְיוֹנוֹת, עַל שְׁגִיאוֹת מִבָּעֵי לֵיהּ. כְּמָה דְאַתְּ אָמֵר (תהילים י״ט:י״ג) שְׁגִיאוֹת מִי יָבִין. אֶלָּא (כלא הוא אבל) שִׁגְיוֹנוֹת, כְּמָה דְאַתְּ אָמֵר (תהילים ז׳:א׳) שִׁגָּיוֹן לְדָוִד. זִינִי תּוּשְׁבְּחָן הֲווֹ קָמַיְיהוּ דִּנְבִיאֵי, לְמִישְׁרֵי עָלַיְיהוּ רוּחַ נְבוּאָה, כְּמָה דְאַתְּ אָמֵר (שמואל א י׳:ה׳) וּפָגַעְתָּ חֶבֶל נְבִיאִים יוֹרְדִים מֵהַבָּמָה וְלִפְנֵיהֶם נֵבֶל וְתוֹף וְגוֹ', וּכְתִיב (מלכים ב ג׳:ט״ו) וְעַתָּה קְחוּ לִי מְנַגֵּן וְגוֹ'. וְכָל שֶׁכֵּן חֲבַקּוּק, דְּאִצְטְרִיךְ לֵיהּ יַתִּיר מִכֻּלְּהוֹן, לְנַיְיחָא דְּרוּחָא, וּלְבַסְּמָא לְהַהוּא אֲתָר, לְאַמְשָׁכָא עָלֵיהּ רוּחַ נְבוּאָה. וְכֵן כֻּלְּהוּ נְבִיאֵי כְּהַאי גַּוְונָא, בַּר מִמֹּשֶׁה דְּסָלִיק עַל כָּל שְׁאַר נְבִיאֵי דְּעָלְמָא, זַכָּאָה חוּלָקֵיהּ.","תָּא חֲזֵי, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, רוּחֵיהוֹן הֲוָה תָּבִיר בְּגַוַּויְיהוּ, וַהֲווּ שַׁמְעִין אִינּוּן תּוּשְׁבְּחָן, וְלָא יַכְלִין לְמֶחדֵי, וּבְשַׁעֲתָא דְּכֻלְּהוּ אוֹכְלֹסִין וּרְתִיכִין נַפְקוּ בִּשְׁכִינְתָּא, כֻּלְּהוּ אָרִימוּ תּוּשְׁבְּחָן וְשִׁירִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא רוּחֵיהוֹן דְּיִשְׂרָאֵל, וַהֲווּ שַׁמְעִין אִינּוּן תּוּשְׁבְּחָן, וְקָאִים רוּחֵיהוֹן בְּגַוַויְיהוּ דְּלָא פַּרְחָן.","בַּר נָשׁ כַּד אִיהוּ שָׁבִיק פּוּלְחָנָא, כְּדֵין יָדַע תְּבִירוּ דְּגַרְמוֹי, תְּבִירוּ דְּרוּחֵיהּ. כַּךְ יִשְׂרָאֵל, כַּד נַפְקוּ מִמִּצְרַיִם, כְּדֵין טָעִימוּ טַעֲמָא דְּמוֹתָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַסֵּי לוֹן, דִּכְתִּיב, (שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגוֹ'. וְכָל אוֹרְחִין, הֲווֹ סַלְּקִין רֵיחִין דְּאַסְוָתָא, וְעָאלִין לְגוּפַיְיהוּ וְאִתָּסְיָין, וְקַל תּוּשְׁבְּחָן דַּהֲווֹ שַׁמְעִין, הֲווֹ חַדָּאן וְנַיְיחִין בְּרוּחֵיהוֹן.","וּפַרְעֹה וְכָל אִינּוּן אוּכְלוֹסִין דִּילֵיהּ, הֲווֹ אַזְלֵי בַּתְרַיְיהוּ, לְאוֹזְפָא לוֹן, עַד דְּנַפְקוּ מֵאַרְעָא דְּמִצְרַיִם. וְכֵן כָּל אִינּוּן רַבְרְבִין דִּמְמָנָן עָלֵיהוֹן, וְעַל שְׁאַר עַמִּין, אוֹזִיפוּ לָהּ לִשְׁכִינְתָּא וּלְיִשְׂרָאֵל כֻּלְּהוּ, עַד דְּשָׁארוּ בְּאֵיתָם בִּקְצֵה הַמִּדְבָּר, הֲדָא הוּא דִכְתִיב, וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ'. כִּי קָרוֹב הוּא, כִּי קָרוֹב הוּא. הַהוּא אוֹמָאָה דְּאוֹמֵי אֲבִימֶלֶךְ לַאֲבָהָן, עַל הַהוּא טִיבוּ דְּעָבְדוּ פְּלִשְׁתִּים לַאֲבָהָן, דִּכְתִּיב (בראשית כ״א:כ״ג) כַּחֶסֶד אֲשֶׁר עָשִׂיתִי עִמְּךָ תַּעֲשֶׂה עִמָּדִי וְעִם הָאָרֶץ אֲשֶׁר גַּרְתָּה בָּהּ.","וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם, מַה כְּתִיב לְעֵילָּא, וַיָּקָם פַּרְעֹה לַיְלָה הוּא וְכָל עֲבָדָיו. תָּא חֲזֵי, נוּקְמָא עִלָּאָה דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם. תְּלַת מוֹתָנִי הֲווֹ. חַד, דְּעָבְדוּ בּוּכְרִין בְּמִצְרַיִם, דְּקָטִילוּ כָּל אִינּוּן דְּאַשְׁכָּחוּ. וְחַד, דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּפַלְגוּת לֵילְיָא. וְחַד, כַּד חָמָא פַּרְעֹה מוֹתָנָא בְּבֵיתֵיהּ בִּבְנוֹי וּבְעַבְדוֹי, קָם וְזָרִיז גַּרְמֵיהּ, וְקָטִיל אֲפַרְכִין וְסַרְכִין, וְכָל דְּאַמְלִיכוּ לֵיהּ לְסָרְבָא בְּעַמָּא עַד דְּאוֹרַיְיתָא אַסְהִידַת עָלֵיהּ דְּאִיהוּ קָם בְּלֵילְיָא מַמָּשׁ. כְּמָה (דקודשא בריך הוא בפלגות) דְּלֵילְיָא קָטַל בּוּכְרִין וְעָבִיד נוּקְמִין, הָכִי קָם פַּרְעֹה בְּאַרְעָא דְּמִצְרַיִם, וְקָטַל וְעָבִיד נוּקְמִין בְּסַרְכוֹי, וְאָפַרְכוֹי, וַאֲמַרְכְּלוֹי, וּבְכָל אִינּוּן רַבְרְבִין הֲדָא הוּא דִכְתִיב, (שמות י״ב:ל׳) וַיָּקָם פַּרְעֹה (לילה ממש), דְּקָם לְקַטָלָא וּלְשֵׁיצָאָה."],[[0,"תפלה לחבקוק וגו':","שואל. מהו תפלה שאומר כאן. ומשיב. אלא זהו המקום שהיה נקשר בו תחילה. מצד אמו, וזה הוא \u0003תפלה\u0004 של יד דהיינו הנוקבא דז\"א, שנקראת תפלה. \u0003על שגיונות.\u0004 פירושו, כי יום ההוא שנקשר בו, שגיונות העולם היו תלוים לפני הקב\"ה, שהיה ראש השנה כנ\"ל, וגבורה שהיא הנוקבא היתה שולטת, ועל כן נקשר בו תפלה הזו. שהיא הנוקבא."],[1,"ד\"א תפלה לחבקוק וגו':","פירוש אחר, תפלה לחבקוק הנביא. תפלה לחבקוק, פירושו, בשביל חבקוק, דהיינו בשביל ב' החיבוקים, שהוא, הנביא עשה בשבילו. \u0003ה' שמעתי שמעך יראתי\u0004 וגו'. בוא וראה. כשנתעורר עליו רוח הנביא, שהוא זכר, בשעת החיבוק שלו, על מקום זה, על רוח הנקבה, שהוא תפלה, שהיה לו מחיבוק של אמו, היה בא ומתירא ומזדעזע, שלא יחזרו עליו דינין של הנוקבא, וע\"כ אמר ה' שמעתי שמעך יראתי. משל אמרו. שהמנושך מכלב מזדעזע מקולו."],[2,"ה' פעלך בקרב שנים חייהו:","שואל, מי הוא, פעלך. ומשיב, אלא על עצמו אמר שהוא פעל שלו. בקרב שנים חייהו. פירושו, תן לו חיים לפעלך בקרב שנים העליונים, שהם הספירות. פירוש אחר, חייהו שלא ימות כבתחילה."],[3,"על שגיונות:","שואל. מהו על שגיונות, על שגיאות היה צריך לומר. כמש\"א, שגיאות מי יבין. ומשיב. אלא שגיונות פירושו, כש\"א שגיון לדוד, שהוא זמר ושבח, כי מיני תשבחות היו לפני הנביאים להשרות עליהם רוח הנבואה. כמש\"א, ופגעת חבל נביאים יורדים מהבמה ולפניהם תוף וחליל וגו'. וכתוב, ועתה קחו לי מנגן וגו' וכל שכן חבקוק, שהיה צריך יותר מכולם לנחת רוח, ולהמתיק אותו מקום שהיא הנוקבא, שהיה מקושר בה תחילה, כדי להמשיך עליו רוח הנבואה. וכן כעין זה כל הנביאים, חוץ ממשה, שעלה על כל נביאי העולם, אשרי חלקו."],[4,"ת\"ח, כד נפקו וכו':","בוא וראה, כשיצאו ישראל ממצרים, רוחם היה נשבר בקרבם והיו שומעים התשבחות, של המלאכים, ולא יכלו לשמוח. ובשעה שכל מחנות המלאכים והמרכבות יצאו עם השכינה, כולם הרימו קולם בתשבחות ושירים לפני הקב\"ה, והעיר הקב\"ה רוחם של ישראל והיו שומעים התשבחות, של המלאכים, ועמד רוחם בתוכם, שלא פרח מהם."],[5,"בר נש כד איהו וכו':","אדם אחר שעזב את עבודתו, אז ידע ומרגיש שבירת עצמותיו ושבירת רוחו. כך ישראל, כשיצאו ממצרים אז טעמו טעם המות, והקב\"ה הרפא אותם, שכתוב, וה' הולך לפניהם יומם וגו'. וכל הדרכים היו מעלים ריחות של רפואה, ובאו לגופם ונרפאו. ומקול של התשבחות שהיו שומעים, היו שמחים ונחים ברוחם."],[6,"ופרעה וכל אינון וכו':","ופרעה וכל האנשים שלו היו הולכים אחרי ישראל ללות אותם עד שיצאו מארץ מצרים. וכן כל השרים העליונים, הממונים עליהם ועל שאר העמים, לוו את השכינה וישראל כולם עד שחנו באיתם בקצה המדבר. ז\"ש, ויהי בשלח פרעה את העם וגו'. \u0003כי קרוב הוא,\u0004 פירושו, כי קרוב היא אותה השבועה שהשביע אבימלך את האבות, בשביל טוב ההוא שעשו הפלשתים אל האבות, שכתוב, כחסד אשר עשיתי עמך תעשה עמדי ועם הארץ אשר גרתה בה."],[7,"ויהי בשלח פרעה את העם:","מה כתוב למעלה, ויקם פרעה לילה וגו'. בוא וראה נקמה העליונה שעשה הקב\"ה במצרים. ג' מיתות היו. אחד, שעשו הבכורים במצרים, שהרגו כל אלו שמצאו. ואחד, שהרג הקב\"ה בחצות לילה. ואחד, כשראה פרעה את המות בביתו ובבניו ובעבדיו, קם וזירז עצמו והרג את השרים והמושלים, וכל שיעצו לו למאן לשלוח את העם, עד שהתורה העידה עליו, שהוא קם בלילה ממש. דהיינו בדיני הנוקבא הנקראת לילה. כמו שהלילה, שהוא הנוקבא, הרג בכורות ועשה נקמות, כך קם פרעה בארץ מצרים והרג ועשה נקמות בשליטיו ושריו ופקידיו ובכל מיני השרים. ז\"ש ויקם פרעה לילה, שקם להרוג ולהשחית."]],[[0,"","תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא (חבקוק ג) - אֵיזוֹ תְפִלָּה? אֶלָּא זֶהוּ מָקוֹם שֶׁהָיָה קָשׁוּר בּוֹ בַּתְּחִלָּה, וְזֶהוּ תְּפִלָּה שֶׁל יָד. עַל שִׁגְיֹנוֹת - שֶׁאוֹתוֹ יוֹם שֶׁנִּקְשַׁר בּוֹ, הָיוּ תְלוּיִים שִׁגְיוֹנוֹת הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּגְבוּרָה הָיְתָה שׁוֹלֶטֶת, וְלָכֵן נִקְשְׁרָה בּוֹ תְּפִלָּה זוֹ (בזו התפלה)."],[1,"","דָּבָר אַחֵר תְּפִלָּה לַחֲבַקּוּק הַנָּבִיא - תְּפִלָּה לַחֲבַקּוּק, מִשּׁוּם חֲבַקּוּק שֶׁהוּא עָשָׂה בִּשְׁבִילוֹ. ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי וְגוֹ', בּא רְאֵה, כְּשֶׁמִּתְעוֹרֶרֶת עָלָיו רוּחַ נְבוּאָה עַל מָקוֹם זֶה שֶׁהוּא תְּפִלָּה, הָיָה בָּא וְהָיָה פּוֹחֵד וּמִזְדַּעֲזֵעַ. מָשָׁל אוֹמְרִים, מִי שֶׁנִּנְשַׁךְ מִכֶּלֶב, מִקּוֹלוֹ הוּא מִזְדַּעֲזֵעַ."],[2,"","ה' פָּעָלְךְ בְּקֶרֶב שָׁנִים חַיֵּיהוּ, מִי זֶה פָּעָלְךְ? אֶלָּא עָלָיו אָמַר, שֶׁהוּא פֹּעַל שֶׁלּוֹ. בְּקֶרֶב שָׁנִים חַיֵּיהוּ, תֵּן לוֹ חַיִּים לְפָעָלְךְ זֶה בְּקֶרֶב שָׁנִים עֶלְיוֹנוֹת. דָּבָר אַחֵר חַיֵּיהוּ - שֶׁלֹּא יָמוּת כְּמוֹ שֶׁבַּתְּחִלָּה."],[3,"","עַל שִׁגְינוֹת, מַה זֶּה עַל שִׁגְינוֹת? עַל שְׁגִיאוֹת הָיָה צָרִיךְ (לכתב), כְּמוֹ שֶׁנֶּאֱמַר (תהלים יט) שְׁגִיאוֹת מִי יָבִין. אֶלָּא (הכל הוא. אבל) שִׁגְיֹנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שם ז) שִׁגָּיוֹן לְדָוִד. מִינֵי תִשְׁבָּחוֹת הָיוּ לִפְנֵי הַנְּבִיאִים לְהַשְׁרוֹת עֲלֵיהֶם רוּחַ נְבוּאָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א י) וּפָגַעְתָּ חֶבֶל נְבִיאִים יֹרְדִים מֵהַבָּמָה וְלִפְנֵיהֶם נֵבֶל וְתֹף וְגוֹ', וְכָתוּב וְעַתָּה קְחוּ לִי מְנַגֵּן וְגוֹ'. וְכָל שֶׁכֵּן חֲבַקּוּק שֶׁהִצְטָרֵךְ לוֹ יוֹתֵר מִכֻּלָּם, לְנַחַת הָרוּחַ, וּלְבַשֵּׂם אֶת אוֹתוֹ מָקוֹם, לְהַמְשִׁיךְ עָלָיו רוּחַ נְבוּאָה. וְכֵן כְּמוֹ כָּךְ כָּל הַנְּבִיאִים, פְּרָט לְמֹשֶׁה שֶׁעָלָה עַל כָּל שְׁאָר נְבִיאֵי הָעוֹלָם. אַשְׁרֵי חֶלְקוֹ!"],[4,"","בֹּא רְאֵה, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, רוּחָם הָיְתָה שְׁבוּרָה בְתוֹכָם, וְהָיוּ שׁוֹמְעִים אוֹתָם תִּשְׁבָּחוֹת וְלֹא יְכוֹלִים לִשְׂמֹחַ. וּבְשָׁעָה שֶׁכָּל הָאוּכְלוּסִין וְהַמֶּרְכָּבוֹת יָצְאוּ עִם הַשְּׁכִינָה, כֻּלָּם הֵרִימוּ שִׁירִים וְתִשְׁבָּחוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת רוּחָם שֶׁל יִשְׂרָאֵל, וְהָיוּ שׁוֹמְעִים אֶת אוֹתָם תִּשְׁבָּחוֹת, וְעָמְדָה רוּחָם בְּתוֹכָם שֶׁלֹּא פָרְחוּ."],[5,"","כְּשֶׁאָדָם עוֹזֵב עֲבוֹדָה, אָז יוֹדֵעַ אֶת שִׁבְרוֹן הָעֲצָמוֹת וְשִׁבְרוֹן הָרוּחַ. כָּךְ יִשְׂרָאֵל, כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, אָז טָעֲמוּ טַעַם הַמָּוֶת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רִפֵּא אוֹתָם, שֶׁכָּתוּב (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם וְגוֹ'. וְכָל הַדְּרָכִים הָיוּ מַעֲלוֹת רֵיחוֹת שֶׁל רְפוּאָה, וְנִכְנָסִים לְגוּפָם וּמִתְרַפְּאִים, וְקוֹל הַתִּשְׁבָּחוֹת שֶׁהיוּ שׁוֹמְעִים, הָיוּ שְׂמֵחִים וְנָחִים בְּרוּחָם."],[6,"","וּפַרְעֹה וְכָל אוֹתָם הָאוּכְלוּסִים שֶׁלּוֹ הָיוּ הוֹלְכִים אַחֲרֵיהֶם לְלַוּוֹת אוֹתָם עַד שֶׁיָּצְאוּ מֵאֶרֶץ מִצְרַיִם, וְכָל כָּל אוֹתָם גְּדוֹלִים שָׂרִים הַמְמֻנִּים עֲלֵיהֶם וְעַל שְׁאָר הָעַמִּים, לִוּוּ אֶת הַשְּׁכִינָה וְאֶת יִשְׂרָאֵל כֻּלָּם, עַד שֶׁחָנוּ בְּאֵיתָם בִּקְצֵה הַמִּדְבָּר. זֶהוּ שֶׁכָּתוּב וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ', כִּי קָרוֹב הוּא. כִּי קָרוֹב הוּא, אוֹתָהּ שְׁבוּעָה שֶׁנִּשְׁבַּע אֲבִימֶלֶךְ לָאָבוֹת עַל אוֹתוֹ טוֹב שֶׁעָשׂוּ הַפְּלִשְׁתִּים לָאָבוֹת, שֶׁכָּתוּב (בראשית כא) כַּחֶסֶד אֲשֶׁר עָשִׂיתִי עִמְּךְ תַּעֲשֶׂה עִמָּדִי וְעִם הָאָרֶץ אֲשֶׁר גַּרְתָּה בָּהּ."],[7,"","וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם. מַה כָּתוּב לְמַעְלָה? וַיָּקָם פַּרְעֹה לַיְלָה הוּא וְכָל עֲבָדָיו. בֹּא רְאֵה, הַנְּקָמָה הָעֶלְיוֹנָה שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, שְׁלֹשָׁה סוּגֵי מָוֶת הָיוּ: אֶחָד שֶׁעָשׂוּ הַבְּכוֹרִים בְּמִצְרַיִם, שֶׁהָרְגוּ כָּל אוֹתָם שֶׁנִּמְצְאוּ. וְאֶחָד שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בַּחֲצוֹת הַלַּיְלָה. וְאֶחָד כְּשֶׁרָאָה פַרְעֹה אֶת הַמָּוֶת בְּבֵיתוֹ בְּבָנָיו וּבַעֲבָדָיו, קָם וְזֵרַז אֶת עַצְמוֹ, וְהָרַג שָׂרִים וּמוֹשְׁלִים וְכָל מִי שֶׁיָּעַץ לוֹ לְסָרֵב לָעָם, עַד שֶׁהַתּוֹרָה מְעִידָה עָלָיו שֶׁהוּא קָם בַּלַּיְלָה מַמָּשׁ, כְּמוֹ (שהקדושברוך הואבחצות) שֶׁהַלַּיְלָה הָרַג בְּכוֹרוֹת וְעָשָׂה נְקָמוֹת, כָּךְ קָם פַּרְעֹה בְּאֶרֶץ מִצְרַיִם וְהָרַג וְעָשָּׂה נְקָמוֹת בְּשָׂרָיו וּמוֹשְׁלָיו וַאֲמַרְכְּלָיו וּבְכָל אוֹתָם גְּדוֹלִים. זֶהוּ שֶׁכָּתוּב (שמות יב) וַיָּקָם פַּרְעֹה לַיְלָה (לילה ממש), שֶׁקָּם לַהֲרֹג וּלְהַשְׁמִיד."]]],[["אוֹרְחוֹי דְּכַלְבָּא, כַּד מַחְיָין לֵיהּ בְּאַבְנָא, אִיהוּ אָתֵי וְנָשִׁיךְ לְחַבְרֵיהּ, כַּךְ פַּרְעֹה, לְבָתַר אִיהוּ הֲוָה אָזִיל בַּשְּׁוָקֵי, וַהֲוָה מַכְרִיז וְאָמַר, קוּמוּ צְּאוּ מִתּוֹךְ עַמִּי, אַתּוּן קָטַלְתּוּן לְכָל בְּנִי מָתָא, אַתּוּן קָטַלְתּוּן סַרְכֵי וְאָפַרְכֵי וְכָל בְּנֵי בֵּיתִי, הֲדָא הוּא דִכְתִיב וַיִּקְרָא לְמֹשֶׁה וּלְאַהֲרֹן לַיְלָה. כֵּיוָן דְּבִידְכוֹן הֲוָה כֹּלָּא, וּבֵרַכְתֶּם גַּם אוֹתִי, דְּלָא תִּקְטְלוּן לִי. לְבָתַר אִיהוּ בְּגַרְמֵיהּ אוֹזִיף לוֹן, וְאַפִּיק לוֹן מֵאַרְעָא, הֲדָא הוּא דִכְתִיב וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ'.","(שמות י״ג:י״ח) וַיַּסֵּב אֱלֹהִים אֶת הָעָם דֶּרֶךְ הַמִּדְבָּר יַם סוּף לְתַקְּנָא אָרְחָא לְאַתְרֵיהּ. ר' יְהוּדָה אָמַר, מַאי שְׁנָא כַּד הֲווֹ יִשְׂרָאֵל בְּמִצְרַיִם, דִּכְתִּיב, (שמות ה׳:א׳) שַׁלַּח אֶת עַמִּי, (שמות ט׳:ב׳) כִּי אִם מָאֵן אַתָּה לְשַׁלֵּחַ אֶת עַמִּי, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל, וּבְהַהוּא זִמְנָא לָא הֲווֹ גְּזִירִין, וְלָא אִתְקַשָּׁרוּ בֵּיהּ כְּדְקָא יֵאוֹת. וְהָכָא דַּהֲווֹ גְּזִירִין, וְעָבְדוּ פִּסְחָא, וְאִתְקַשָּׁרוּ בֵּיהּ, קָרֵי לוֹן אֶת הָעָם.","אֶלָּא בְּגִין הַהוּא עֵרֶב רַב, דְּאִתְדְּבָקוּ בְּהוּ, וְאִתְעָרְבוּ בַּהֲדַיְיהוּ, קָרֵי לוֹן אֶת הָעָם סְתָם. כְּמָה דְאַתְּ אָמֵר, (שמות לכ) וַיִּגּוֹף יְיָ' אֶת הָעָם עַל אֲשֶׁר עָשׂוּ אֶת הָעֵגֶל. וַיִּקָּהֵל הָעָם עַל אַהֲרֹן. וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה. וְכֵן כֻּלְּהוּ.","ר' יִצְחָק ור' יְהוּדָה הֲווֹ אַזְלֵי מֵאוּשָׁא לְלוּד, וַהֲוָה עִמְּהוֹן יוֹסֵי טַיָּיעָא, בִּקְטִירָא דְּגַמָּלֵי עֲטוּפִירָא בְּכַתְפַיְיהוּ. עַד דַּהֲווֹ אַזְלֵי, אַשְׁכַּח הַהוּא יוֹסֵי טַיָּיעָא אִנְתּוּ חֲדָא דִּשְׁאַר עַמִּין, דְּקָטִיר בִּירוֹקֵי חַקְלָא, אִשְׁתְּמִיט מִנַּיְיהוּ וְאַתְקִיף בָּהּ, וְאָתָא עָלָּה. תַּוְוהוּ ר' יִצְחָק ור' יְהוּדָה, אָמְרוּ נֵיתוּב מֵאָרְחָא דָּא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאַחְזָאָה לָן, דְּלָא נִתְחַבַּר בַּהֲדֵיהּ. תָּבוּ מֵאָרְחָא, בָּדְקוּ בַּתְרֵיהּ, וְאַשְׁכָּחוּ דִּבְרֵיהּ דְּבַת אֵל נִכָר הֲוָה, וַאֲבוּהָ פָּסִיל זַרְעָא הֲוָה. אָמְרוּ, בְּרִיךְ רַחֲמָנָא דְּשֵׁזִיב לָן.","פָּתַח ר' יִצְחָק וְאָמַר (תהילים ל״ז:א׳) אַל תִּתְחַר בַּמְּרֵעִים. מַאן אִינּוּן מְרֵעִים, דְּלָא כְּתִיב חַטָּאִים, אוֹ רְשָׁעִים. אֶלָּא מְרִעִים, דְּאַבְאִישִׁין לְגַרְמַיְיהוּ, וּלְהָנִי דְּמִתְחַבְּרָן בַּהֲדַיְיהוּ. ר' יְהוּדָה אָמַר, מְרֵעִים: אַרְחֵיק גַּרְמָךְ מִמְּרֵעִים דְּלָא תֶּהווֹן רֵעִים וַחֲבֵרִים כַּחֲדָא, דְּלָא יַבְאִישׁוּ לָךְ עוֹבָדוֹי, וְתִתְפַּס בְּחֶטְאוֹי.","תָּא חֲזֵי, אִי לָא הֲווֹ אִינּוּן עֵרֶב רַב דְּאִתְחַבְּרוּ בְּהוֹן יִשְׂרָאֵל, לָא אִתְעָבִיד הַהוּא עוֹבָדָא, וְלָא מִיתוּ מִיִּשְׂרָאֵל, כָּל אִינּוּן דְּמִיתוּ, וְלָא גָּרִים לוֹן לְיִשְׂרָאֵל כָּל מַה דְּגָרִים. וְתָּא חֲזֵי, הַהוּא עוֹבָדָא, וְהַהוּא חוֹבָה מַמָּשׁ, גָּרִים גָּלוּתְהוֹן דְּיִשְׂרָאֵל.","דְּתָנֵינָן, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא, דְּיִשְׁתַּכְּחוּן יִשְׂרָאֵל בְּהַהוּא שַׁעֲתָא כְּמַלְאֲכֵי עִלָּאֵי, וּלְמֶעְבַּד לוֹן חֵירִין מִכֹּלָּא, חֵירִין מִמּוֹתָא, וּלְמֶהֱוֵי חֵירִין מִן שִׁעְבּוּדָא דִּשְׁאַר עַמִּין, כְּמָה דְאַתְּ אָמֵר, (שמות ל״ב:ט״ז) חָרוּת עַל הַלּוּחוֹת, אַל תִּקְרֵי חָרוּת, אֶלָּא חֵירוּת.","כֵּיוָן דְּאִתְעָבִיד הַהוּא עוֹבָדָא, גָּרִימוּ כֹּלָּא. גָּרִימוּ מוֹתָא, גָּרִימוּ שִׁעְבּוּד מַלְכְּוָון, גָּרִימוּ דְּאִתְּבָּרוּ אִינּוּן לוּחֵי קַדְמָאֵי, גָּרִימוּ דְּמִיתוּ מִיִּשְׂרָאֵל, כַּמָּה אַלְפִין מִנַּיְיהוּ. וְכָל דָּא, בְּגִין אִתְחַבְּרוּתָא דְּאִינּוּן עֵרֶב רַב, דְּאִתְחַבְּרוּ בְּהוּ.","אוּף הָכָא, בְּגִינֵיהוֹן, לָא אִתְקְרוּן בְּנִי יִשְׂרָאֵל, וְלָא יִשְׂרָאֵל, וְלָא עַמִּי, אֶלָּא הָעָם סְתָם. וְאִי תֵּימָא וַחֲמוּשִׁים עָלוּ בְּנֵי יִשְׂרָאֵל. כַּד הֲווֹ סַלְּקִין מִמִּצְרַיִם, וְלָא אִתְחַבְּרוּ בַּהֲדַיְיהוּ אִינּוּן עֵרֶב רַב, קָרֵי לוֹן בְּנֵי יִשְׂרָאֵל, כֵּיוָן דְּאִתְחַבְּרוּ בַּהֲדַיְיהוּ, דִּכְתִּיב וְגַם עֵרֶב רַב עָלָה אִתָּם, קָרֵי לוֹן הָעָם.","רִבִּי יוֹסֵי אַקְשֵׁי וְאָמַר, כְּתִיב כִּי אַשֶׁר רְאִיתֶם אֶת מִצְרַיִם הַיּוֹם לא תּוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם. אִי הָכִי, כָּל יוֹמָא הֲווֹ חָמָאן לְהַהוּא עֵרֶב רַב. אָמַר רִבִּי יְהוּדָה, עֵרֶב רַב כְּתִיב, וְלֹא מִצְרַיִם, דְּהָא כַּמָּה שְׁאַר עַמִּין הֲווֹ דַּיְּירֵי בְּמִצְרַיִם. וְלֹא עוֹד אֶלָּא דְּכֻלְּהוּ אִתְגְּזָרוּ, וְכֵיוָן דְּאִתְגְּזָרוּ, לָא אִקְרוּן מִצְרָאֵי."],[[0,"אורחוי דכלבא וכו':","מדרך הכלב, כשמכים אותו באבן, הוא בא ונושך את חבירו. כך עשה פרעה. אחר כך היה הולך בשוקים והיה מכריז ואמר, קומו צאו מתוך עמי, אתם הרגתם לכל בני העיר, אתם הרגתם המושלים והשרים וכל בני ביתי. ז\"ש, ויקרא למשה ואהרן לילה. כיון שעל ידכם היה הכל. וברכתם גם אותי, שלא תהרגו אותי. ואח\"כ הוא בעצמו ליווה אותם והוציאם מארץ. ז\"ש, ויהי בשלח פרעה וגו'."],[1,"ויסב אלקים את העם דרך המדבר וגו':","היינו לתקן את הדרך אל מקומו. כלומר, כדי לעשות קריעת ים סוף. שאם לא כן. היה מספיק לנחותם דרך המדבר לבד, ולא דרך ים סוף."],[1,"רבי יהודה אמר וכו':","שואל, מה השינוי, כשהיו ישראל במצרים, כתוב, שלח את \u0003עמי.\u0004 כי אם מאן אתה לשלח את \u0003עמי. בני\u0004 בכרי ישראל, אע\"פ שבעת ההוא לא היו נמולים ולא נקשרו בו, בהקב\"ה, כראוי, וכאן שהיו נמולים, ועשו הפסח, ונקשרו בו, קורא אותם את \u0003העם,\u0004 ולא עמי."],[2,"אלא בגין ההוא וכו':","ומשיב. אלא משום ערב רב ההוא שנדבקו בהם ונתערבו עמהם, קורא אותם את העם סתם. ולא עמי. כמו שאתה אומר, ויגוף ה' את העם וגו'. ויקהל העם על אהרן. וירא העם כי בשש משה. וכן כולם, בעת שישראל היו במצב גרוע, קורא אותם עם סתם, ולא עמי."],[3,"ר' יצחק ור' יהודה וכו':","ר\"י ור\"י היו הולכים מאושא ללוד, והיה עמהם יוסי הסוחר, עם גמלים מקושרים זה בזה בשורה, ומשא על כתפיהם. בעוד שהיו הולכים, מצא יוסי הסוחר אשה אחת של שאר העמים, שהיתה מלקטת בעשבי השדה, פנה מהם ואנס אותה ובא עליה. תמהו ר' יצחק ור' יהודה, אמרו, נשוב מדרך הזה, שהרי הקב\"ה רצה להראות לנו, שלא נתחבר עמו. שבו מן הדרך. בדקו אחריו, ומצאו שהוא בנה של בת אל נכר, ואביו זרע פסול היה. אמרו ברוך הרחמן שהציל אותנו."],[4,"פתח ר' יצחק וכו':","פר\"י ואמר, אל תתחר במרעים. שואל. מי המה מרעים, שלא כתוב, חטאים או רשעים. ומשיב, אלא מרעים הם שמריעים לעצמם ולאותם שמתחברים עמהם. ר' יהודה אמר, אל תתחר במרעים פירושו, הרחק עצמך ממרעים, שלא תהיו חברים ורעים עמהם יחד, שלא יזיקו לך מעשיו ולא תתפוש בחטאיו."],[5,"ת\"ח אי לא וכו':","בוא וראה, אם לא היו אלו ערב רב שנתחברו בישראל, לא היה נעשה אותו המעשה, של העגל, ולא מתו מישראל אלו שמתו, ולא גרמו לישראל כל מה שגרמו. ובוא וראה, מעשה הזה ועון הזה גרם הגלות לישראל."],[6,"דתנינן בעא וכו':","שלמדנו, הקב\"ה רצה שימצאו ישראל באותה שעה, בקבלת התורה, כמלאכים העליונים ולעשות אותם חירות מכל, חירות ממות, ושיהיו בני חורין משעבוד שאר העמים. כש\"א חרות על הלוחות, אל תקרי חרות עם חית קמוצה, אלא חירות עם ח' צרויה."],[7,"כיון דאתעביד וכו':","כיון שנעשה אותו המעשה, גרמו הכל, גרמו מות, גרמו שעבוד מלכיות, גרמו שנשברו לוחות הראשונות, גרמו שמתו מישראל כמה אלפים מהם. וכל זה משום התחברות הערב רב שהתחברו בהם."],[8,"אוף הכא בגיניהון וכו':","אף כאן בשביל הערב רב, לא נקראו, בני ישראל, ולא ישראל, ולא עמי, אלא העם סתם. ואם תאמר, שכתוב, וחמושים עלו בני ישראל. הוא כשעלו ממצרים ועוד לא נתחבר עמהם הערב רב קורא אותם בני ישראל, כיון שנתחברו עמהם, שכתוב, וגם ערב רב עלה אתם, קורא אותם העם."],[9,"ר' יוסי אקשי וכו':","ר\"י הקשה ואמר, כתוב, כי אשר ראיתם את מצרים היום לא תוסיפו לראותם עד עולם. אם כן, הרי בכל יום היו רואים את הערב רב, שהיו מצרים. אמר ר' יהודה ערב רב כתוב, ולא מצרים, כי כמה עמים אחרים היו במצרים, ומהם היו הערב רב. ולא עוד. אלא שכולם נמולו, וכיון שנמולו לא נקראו מצרים."]],[[0,"","דֶּרֶךָ הַכֶּלֶב, כְּשֶׁמַּכִּים אוֹתוֹ בְּאֶבֶן, הוּא בָּא וְנוֹשֵׁךְ אֶת חֲבֵרוֹ. כָּךְ פַּרְעֹה, אַחַר הוּא הָיָה הוֹלֵךְ בַּשְּׁוָקִים, וְהָיָה מַכְרִיז וְאוֹמֵר: קוּמוּ צְּאוּ מִתּוֹךְ עַמִּי, אַתֶּם הֲרַגְתֶּם לְכָל בְּנֵי הָעִיר, אַתֶּם הֲרַגְתֶּם הַשָּׂרִים וְהַמּוֹשְׁלִים וְכָל בְּנֵי בֵיתִי. זֶהוּ שֶׁכָּתוּב וַיִּקְרָא לְמֹשֶׁה וּלְאַהֲרֹן לַיְלָה. כֵּיוָן שֶׁבְּיֶדְכֶם הָיָה הַכֹּל - וּבֵרַכְתֶּם גַּם אֹתִי, שֶׁלֹּא תַהַרְגוּ אוֹתִי. אַחַר כָּךְ הוּא בְּעַצְמוֹ לִוָּה אוֹתָם וְהוֹצִיא אוֹתָם מֵהָאָרֶץ. זֶהוּ שֶׁכָּתוּב וַיְהִי בְּשַׁלַּח פַּרְעֹה אֶת הָעָם וְגוֹ'."],[1,"","וַיַּסֵּב אֱלֹהִים אֶת הָעָם דֶּרֶךְ הַמִּדְבָּר יַם סוּף, לְתַקֵּן דֶּרֶךְ לִמְקוֹמָהּ. רַבִּי יְהוּדָה אָמַר, מַה שּׁוֹנֶה כְּשֶׁהָיוּ יִשְׂרָאֵל בְּמִצְרַיִם, שֶׁכָּתוּב (שם ה) שַׁלַּח אֶת עַמִּי, (שם ט) כִּי אִם מָאֵן אַתָּה לְשַׁלֵּחַ אֶת עַמִּי, (שם ד) בְּנִי בְכֹרִי יִשְׂרָאֵל, וּבְאוֹתוֹ זְמַן לֹא הָיוּ מְהוּלִים וְלֹא נִקְשְׁרוּ בוֹ כָּרָאוּי, וְכָאן, שֶׁהָיוּ מְהוּלִים וְעָשׂוּ פֶסַח וְנִקְשְׁרוּ בוֹ, קָרָא לָהֶם אֶת הָעָם?"],[2,"","אֶלָּא מִשּׁוּם עֵרֶב רַב שֶׁנִּדְבְּקוּ בָהֶם וְהִתְעָרְבוּ עִמָּהֶם, קָרָא לָהֶם אֶת הָעָם סְתָם, כְּמוֹ שֶׁנֶּאֱמַר (שם לג) וַיִּגֹּף ה' אֶת הָעָם עַל אֲשֶׁר עָשׂוּ אֶת הָעֵגֶל. וַיִּקָּהֵל הָעָם עַל אַהֲרֹן. וַיַּרְא הָעָם כִּי בֹשֵׁשׁ מֹשֶׁה. וְכֵן כֻּלָּם."],[3,"","רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד, וְהָיָה עִמָּהֶם יוֹסֵי הַסּוֹחֵר עִם גְּמַלִּים קְשׁוּרִים וּמַשָּׂאוֹת עַל כִּתְפֵיהֶם. עַד שֶׁהָיוּ הוֹלְכִים, מָצָא יוֹסֵי הַסּוֹחֵר אִשָּׁה אַחַת מִשְּׁאָר הָעַמִּים שֶׁלִּקְּטָה יְרָקוֹת בַּשָּׂדֶה. נִשְׁמַט מֵהֶם וְהֶחֱזִיק בָּהּ וּבָא עָלֶיהָ. תָּמְהוּ רַבִּי יִצְחָק וְרַבִּי יְהוּדָה. אָמְרוּ, נָשׁוּב מֵהַדֶּרֶךְ הַזּוֹ, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהַרְאוֹת לָנוּ שֶׁלֹּא נִתְחַבֵּר עִמּוֹ. שָׁבוּ מֵהַדֶּרֶךְ, בָּדְקוּ אַחֲרָיו, וּמָצְאוּ שֶׁהָיָה בֵּן שֶׁל בַּת אֵל נֵכָר, וְאָבִיו זֶרַע פָּסוּל הָיָה. אָמְרוּ: בָּרוּךְ הָרַחֲמָן שֶׁהִצִּילָנוּ."],[4,"","פָּתַח רַבִּי יִצְחָק וְאָמַר, (תהלים לז) אַל תִּתְחַר בַּמְּרֵעִים. מִי הֵם הַמְּרֵעִים, שֶׁלֹּא כָתוּב חַטָּאִים אוֹ רְשָׁעִים? אֶלָּא מְרֵעִים, שֶׁמְּרֵעִים לְעַצְמָם וּלְאוֹתָם שֶׁמִּתְחַבְּרִים עִמָּם. רַבִּי יְהוּדָה אָמַר, מְרֵעִים - הַרְחֵק עַצְמְךְ מִמְּרֵעִים, שֶׁלֹּא תִהְיוּ רֵעִים וַחֲבֵרִים כְּאֶחָד, שֶׁלֹּא יָרֵעוּ לְךְ מַעֲשָׂיו וְתִתָּפֵס בַּחֲטָאָיו."],[5,"","בֹּא רְאֵה, אִלּוּלֵי הָיוּ אוֹתָם עֵרֶב רַב שֶׁהִתְחַבְּרוּ עִם יִשְׂרָאֵל, לֹא נַעֲשֶׂה הָיָה אוֹתוֹ מַעֲשֶׂה, וְלֹא מֵתוּ מִיִּשְׂרָאֵל כָּל אוֹתָם שֶׁמֵּתוּ, וְלֹא גָרַם לְיִשְׂרָאֵל מַה שֶּׁגָּרַם. וּבֹא רְאֵה, אוֹתוֹ מַעֲשֶׂה וְאוֹתוֹ חֵטְא מַמָּשׁ גָּרַם לְגָלוּת יִשְׂרָאֵל."],[6,"","שֶׁשָּׁנִינוּ, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּמָּצְאוּ יִשְׂרָאֵל בְּאוֹתָהּ שָׁעָה כְּמוֹ מַלְאָכִים עֶלְיוֹנִים וְלַעֲשׂוֹת אוֹתָם חוֹרִין מֵהַכֹּל, בְּנֵי חֵרוּת מִמָּוֶת, וְלִהְיוֹת בְּנֵי חוֹרִין מִשִּׁעְבּוּד שֶׁל שְׁאָר הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (שמות לב) חָרוּת עַל הַלֻּחֹת. אַל תִּקְרֵי חָרוּת אֶלָּא חֵרוּת."],[7,"","כֵּיוָן שֶׁנַּעֲשָׂה אוֹתוֹ מַעֲשֶׂה - גָּרְמוּ הַכֹּל. גָּרְמוּ מָוֶת, גָּרְמוּ שִׁעְבּוּד מַלְכֻיּוֹת, גָּרְמוּ שֶׁנִּשְׁבְּרוּ אוֹתָם לוּחוֹת רִאשׁוֹנִים, גָּרְמוּ שֶׁמֵּתוּ מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים מֵהֶם. וְכָל זֶה מִשּׁוּם הַהִתְחַבְּרוּת שֶׁל אוֹתָם עֵרֶב רַב שֶׁהִתְחַבְּרוּ בָהֶם."],[8,"","אַף כָּאן בִּגְלָלָם לֹא נִקְרְאוּ בְּנֵי יִשְׂרָאֵל, וְלֹא יִשְׂרָאֵל, וְלֹא עַמִּי, אֶלָּא הָעָם סְתָם. וְאִם תֹּאמַר, וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל? כְּשֶׁהָיוּ עוֹלִים מִמִּצְרַיִם וְלֹא הִתְחַבְּרוּ עִמָּם אוֹתָם עֵרֶב רַב, קָרָא לָהֶם בְּנֵי יִשְׂרָאֵל. כֵּיוָן שֶׁהִתְחַבְּרוּ עִמָּם, שֶׁכָּתוּב וְגַם עֵרֶב רַב עָלָה עִמָּם, קָרָא לָהֶם הָעָם."],[9,"","רַבִּי יוֹסֵי הִקְשָׁה וְאָמַר, כָּתוּב כִּי אֲשֶׁר רְאִיתֶם אֶת מִצְרַיִם הַיּוֹם לֹא תוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם. אִם כָּךְ, כָּל יוֹם הָיוּ רוֹאִים אֶת אוֹתוֹ עֵרֶב רַב? אָמַר רַבִּי יְהוּדָה, עֵרֶב רַב כָּתוּב, וְלֹא מִצְרַיִם, שֶׁהֲרֵי כַּמָּה שְׁאָר עַמִּים הָיוּ דָרִים בְּמִצְרַיִם, וְלֹא עוֹד, אֶלָּא שֶׁכֻּלָּם נִמּוֹלוּ, וְכֵיוָן שֶׁנִּמּוֹלוּ, יוֹתֵר לֹא נִקְרְאוּ מִצְרִים."]]],[["וְעַל פּוּמָא דְּמֹשֶׁה קַבִּילוּ לוֹן. וְהַיְינוּ מַה דְּאָמַר הַכָּתוּב, (שמות ל״ב:ח׳) לֶךְ רֵד כִּי שִׁחֵת עַמְּךָ סָרוּ מַהֵר מִן הַדֶּרֶךְ אֲשֶׁר צִוִּיתִם. צִוִּיתָם כְּתִיב. וַחֲמֻשִׁים עָלוּ בְּנִי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם, חַד מֵחֲמִשָּׁה הֲווֹ. וְר' יוֹסֵי אוֹמֵר חֲמִשָּׁה מִיִּשְׂרָאֵל, וְחַד מִנַּיְיהוּ. רִבִּי יְהוּדָה אוֹמֵר, וַחֲמֻשִׁים: אֶחָד מֵחֲמִשִּׁים.","אָמַר רַבִּי שִׁמְעוֹן, בְּגִין (בראשית נ\"א ע\"ב) דְּהַהוּא יוֹבְלָא סָלִיק לוֹן מִמִּצְרַיִם, בְּגִין כָּךְ וַחֲמֻשִׁים עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם. וְאִי לָאו, לָא סְלִיקוּ, וְעַל דָּא אִתְעַכְּבוּ חַמְשִׁין יוֹמִין לְקַבְּלָא אוֹרַיְיתָא. וּמֵהַהוּא אֲתָר נַפְקַת אוֹרַיְיתָא, וְאִתְיְהִיבַת, וְעַל דָּא וַחֲמֻשִׁים חָסֵר. דִּבְגִין דָּא עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם.","(שמות י״ג:י״ט) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף וְגוֹ'. אֲמַאי סָלִיק גַּרְמוֹי. אֶלָּא, בְּגִין דְּהֲוָה רֵישָׁא לְנַחְתָּא לְגָלוּתָא. וְלֹא עוֹד, אֶלָּא דְּאִיהוּ סִימָנָא דִּגְאוּלָה הֲוָה לֵיהּ וְאוּמֵי לְהוּ לְיִשְׂרָאֵל עַל דָּא, הֲדָא הוּא דִכְתִיב כִּי הַשְׁבֵּעַ הִשְׁבִּיעַ אֶת בְּנֵי יִשְׂרָאֵל, וְהָא אִתְּמַר.","זַכָּאָה חוּלָקָא דְּמֹשֶׁה, דְּיִשְׂרָאֵל הֲווֹ עַסְקֵי לְמִשְׁאַל מָמוֹנָא מִמִּצְרָאֵי, וּמֹשֶׁה הֲוָה עָסִיק בְּאוּמָאָה דְּיוֹסֵף. וְאִית דְּאַמְרֵי אֲרוֹנָא בְּנִילוּס הֲוָה, וּבִשְׁמָא קַדִּישָׁא סָלִיק לֵיהּ, וְעוֹד אָמַר מֹשֶׁה, יוֹסֵף, הִגִיעַ זְמַן פּוּרְקָנָא דְּיִשְׂרָאֵל, וְאָמַר עֲלֵה שׁוֹר. וְסָלִיק. וְאִית דְּאַמְרֵי, בֵּין מַלְכֵי מִצְרָאֵי הֲוָה, וּמִתַּמָּן סָלִיק (ס\"א ליה). וְאִית דְּאַמְרֵי, בְּגִין דְּלָא יַעַבְדוּן לֵיהּ עֲבוֹדָה זָרָה, שָׁווֹ בְּנִילוּס וְסֶרַח בַּת אָשֵׁר חַוִּיאַת לֵיהּ לְמֹשֶׁה.","(שמות י״ג:כ״א) וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם. רִבִּי יוֹסֵי פָּתַח, (תהילים כ״ב:א׳) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר מִזְמוֹר לְדָוִד. כַּמָּה חֲבִיבָא אוֹרַיְיתָא קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, רָחִים הוּא לְעֵילָּא, רָחִים הוּא לְתַתָּא, קוּדְשָׁא בְּרִיךְ הוּא אָצִית לֵיהּ לְמִלוּלוֹי, לָא שָׁבִיק לֵיהּ בְּהַאי עָלְמָא וְלָא שָׁבִיק לֵיהּ בְּעָלְמָא דְּאָתֵי.","וְאוֹרַיְיתָא בָּעֵי לְמִלְעֵי בָּהּ בִּימָמָא וּבְלֵילְיָא, דִּכְתִּיב, (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וּכְתִיב (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגוֹ'. תִּינַח בִּימָמָא, בְּלֵילְיָא אֲמַאי. בְּגִין דִּיְהֵא שְׁכִיחַ לְגַבֵּי שְׁמָא קַדִּישָׁא שְׁלִים. כְּמָה דְּלֵית יוֹמָם בְּלָא לֵילְיָא, וְלָאו אִיהוּ שְׁלִים, אֶלָּא דָּא עִם דָּא, כַּךְ בָּעֵי אוֹרַיְיתָא, לְאִשְׁתַּכְּחָא עִמֵּיהּ דְּבַּר נָשׁ יוֹמָא וְלֵילְיָא, לְמֶהֱוֵי שְׁלֵימוּתָא לְגַבֵּי דְּבַּר נָשׁ יוֹמָם וָלַיְלָה.","וְהָא אִתְּמַר, דְעִקָרָא דְּלֵילְיָא, מִפַּלְגוּתָא וְאִילָךְ. וְאַף עַל גַּב דְּפָלְגוּ קַדְמִיתָא בִּכְלָלָא דְּלֵילְיָא הוּא, אֲבָל בְּפַלְגוּת לֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא עָאל בְּגִנְתָּא דְּעֵדֶן, לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּא, וּכְדֵין, בָּעֵי לֵיהּ לְבַר נָשׁ לְמֵיקָם, וּלְמִלְעֵי בְּאוֹרַיְיתָא.","וְהָא אִתְּמַר, דְּקוּדְשָׁא בְּרִיךְ הוּא וְכָל צַדִּיקַיָּא דִּבְגִּנְתָּא דְּעֵדֶן, כֻּלְּהוּ צַיְיתִין לְקָלֵּיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי, וְהָא אוּקְמוּהָ, הַיּוֹשֶׁבֶת בַּגַּנִּים: דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי מְשַׁבָּחַת לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בִּשְׁבָחָא דְּאוֹרַיְיתָא, בְּלֵילְיָא. זַכָּאָה חוּלָקֵיהּ, מַאן דְּאִשְׁתַּתַּף בַּהֲדָהּ, לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, בִּשְׁבָחָא דְּאוֹרַיְיתָא.","וְכַד אָתֵי צַפְרָא, כְּנֶסֶת יִשְׂרָאֵל אַתְיָא וּמִשְׁתַּעְשְׁעָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְאוֹשִׁיט לָהּ לְגַבָּהּ שַׁרְבִיטָא דְּחֶסֶד, וְלָא עַלָּה בִּלְחוֹדָהָא, אֶלָּא עַלָּה, וְעַל אִינּוּן דְּמִשְׁתַּתְּפִין בַּהֲדָהּ, וְהָא אִתְּמַר דִּכְתִּיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוְּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה וְגוֹ'. וְעַל דָּא אַיֶּלֶת הַשַּׁחַר אִקְרֵי.","וְאָמַר רַבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּבָעֵי לְאִתְנַהֲרָא צַפְרָא, אִתְחֲשָׁךְ וְאִתְקַדַּר נְהוֹרָא, וְקַדְרוּתָא אִשְׁתְּכַח. כְּדֵין אִתְחַבְּרַת אִתְּתָא בְּבַעְלָהּ, דְּתָנֵינָן, אִשָּׁה מְסַפֶּרֶת עִם בַּעְלָהּ, לְמִשְׁתָּעֵי בַּהֲדֵיהּ, וְעָאלַת לְהֵיכְלֵיהּ.","לְבָתַר כַּד בָּעֵי שִׁמְשָׁא לְמֵיעַל, אִתְנְהִיר וְאָתַת לֵילְיָא, וְנָטִיל לֵיהּ. כְּדֵין כָּל תַּרְעִין סְתִימִין, וְחַמְרִין נַעֲרִין, וְכַלְבִּין נַבְחִין, כַּד אִתְפְּלַג לֵילְיָא, שָׁאֲרִי מַלְכָּא (למקרי) לְמֵיקָם, וּמַטְרוֹנִיתָא לְזַמְּרָא, וְאָתֵי מַלְכָּא וְאָקִישׁ לְתַרְעָא דְּהֵיכְלָא, וְאָמַר (שיר השירים ה׳:ב׳) פִּתְחִי לִי אֲחוֹתִי רַעְיָתִי וְגוֹ'. וּכְדֵין מִשְׁתַּעֲשָׁע בְּנִשְׁמַתְהוֹן דְּצַדִּיקַיָּא.","זַכָּאָה חוּלָקֵיהּ דְּהַהוּא, דְּאִתְּעַר הַהוּא זִמְנָא בְּמִלֵּי דְּאוֹרַיְיתָא, בְּגִין דָּא, כָּל אִינּוּן דִּבְנֵי הֵיכְלָא דְּמַטְרוֹנִיתָא, כֻּלְּהוּ בַּעְיָין לְמֵיקָם בְּהַהוּא זִמְנָא, לְשַׁבְּחָא לְמַלְכָּא וְכֻלְּהוּ מְשַׁבְּחָן קָמֵיהּ, וּשְׁבָחָא דְּסָלִיק מֵהַאי עָלְמָא, דָּא דְּאִיהוּ רָחִיק, (יתיר) דָּא נִיחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא מִכֹּלָּא.","כַּד אִסְתְּלִיק לֵילְיָא, וְאָתֵי צַפְרָא, (נ\"א ואיתחשיך) וְאִתְקָדַּר, כְּדֵין מַלְכָּא וּמַטְרוֹנִיתָא בְּרָזָא בְּחֶדְוָה, וְיָהִיב לָהּ מַתְּנָן, וּלְכָל בְּנֵי הֵיכְלָהּ. זַכָּאָה חוּלָקֵיהּ מַאן דְּאִיהוּ בְּמִנְיָינָא."],[[0,"ועל פומא דמשה וכו':","ועל פי משה קבלו אותם. והיינו מה שאמר הכתוב, לך רד כי שחת עמך סרו מהר מן הדרך אשר ציותם. ציותם כתוב, דהיינו שמשה ציוה אותם שיקבלו הערב רב. וחמושים עלו בני ישראל מארץ מצרים. פירושו אחד מחמשה היו ישראל. ור' יוסי אומר, חמשה היו מישראל ואחד מערב רב. ר' יהודה אומר, וחמושים, אחד מחמשים היו הערב רב."],[1,"אר\"ש בגין וכו':","אמר ר' שמעון, משום שהיובל, שהוא בינה, העלה אותם מארץ מצרים, משום זה כתוב, וחמשים עלו בני ישראל מארץ מצרים, שהיא בינה הנקראת יובל, שיש בה חמשים שערים, ואם לא היובל לא היו עולים. ועל כן נתעכבו חמשים יום לקבל התורה. וממקום ההוא מיובל יצאה התורה וניתנה. ועל כן, וחמשים חסר. כלומר, אם פירושו מזוינים, היה צריך לומר חמושים עם \u0003ו'.\u0004 אלא יורה על מספר חמשים שה\"ס יובל. שבשביל זה עלו בני ישראל ממצרים."],[2,"ויקח משה את עצמות יוסף וגו':","שואל. למה העלה משה עצמותיו. ומשיב. אלא משום שהיה הראשון לרדת לגלות. ולא עוד אלא שהיה לו סימן הגאולה, דהיינו פקוד יפקוד, (רש\"י שמות ג' י\"ח) והשביע לישראל על זה, ז\"ש, כי השבע השביע את בני ישראל. והוא נתבאר."],[3,"זכאה חולקא דמשה וכו':","אשרי חלקו של משה, שישראל היו עוסקים לשאל כסף ממצרים, ומשה היה עסוק בשבועה של יוסף. ויש אומרים, שהארון שלו בנילוס היה ועל ידי שם הקדוש העלה אותו. ועוד אמר משה, יוסף, הגיע הזמן של גאולת ישראל. ואמר עלה שור, ועלה. כי יוסף נקרא שור כמ\"ש בכור שורו הדר לו וגו'. ויש שאמרו, בין מלכי מצרים היה, ומשם עלה. ויש אומרים, שכדי שלא יעשוהו עבודה זרה, שמו אותו בנילוס, וסרח בת אשר, שהיתה חיה בשעת המעשה, הראתה למשה מקומו."],[4,"וה' הולך לפניהם יומם:","ר' יוסי פתח למנצח על אילת השחר מזמור לדוד. כמה אהובה התורה לפני הקב\"ה, שכל מי שעוסק בתורה אהוב הוא למעלה, אהוב הוא למטה, והקב\"ה מקשיב לדיבוריו, ואינו עוזב אותו בעולם הזה ואינו עוזב אותו לעולם הבא."],[5,"ואורייתא בעי וכו':","והתורה, צריכים לעסוק בה ביום ובלילה, שכתוב, והגית בו יומם ולילה. וכתוב, אם לא בריתי יומם ולילה. שואל, יצדק ביום, שהוא זמן עבודה לכל, אבל בלילה, שהוא זמן מנוחה, למה צריכים לעסוק בתורה. ומשיב. כדי שיהיה נמצא אצלו שם שלם, כי כמו שאין יום בלי לילה. ואינו שלם אלא זה עם זה, כך צריכה התורה להמצא עם האדם יום ולילה, ויהיה השלמות אצל האדם יום ולילה. פירוש. יום הוא ז\"א ולילה הוא הנוקבא, וכשעוסק בתורה יום ולילה נמצא מיחד ז\"א ונוקבא, שזהו כל השלמות, בסו\"ה ויהי ערב ויהי בקר יום אחד."],[6,"והא אתמר דעקרא וכו':","והרי למדנו, שעיקר הלילה הוא מחצות ואילך, ואע\"פ שחצי לילה הראשונה הוא בכלל הלילה, אבל בחצות לילה, הקב\"ה בא בגן עדן להשתעשע עם הצדיקים אשר שם, ואז צריך האדם לקום ולעסוק בתורה."],[7,"והא אתמר דקב\"ה וכו':","והרי למדנו, שהקב\"ה וכל הצדיקים שבגן עדן, כולם מקשיבים לקולו, ז\"ש, היושבת בגנים חברים מקשיבים לקולך השמיעני וכבר בארוה, \u0003היושבת בגנים,\u0004 זו היא כנסת ישראל, דהיינו המלכות, שהיא משבחת אל הקב\"ה, בשבח התורה, בלילה. אשרי חלקו של מי שמשתתף עמה לשבח אל הקב\"ה בשבח התורה."],[8,"וכד אתי צפרא וכו':","וכשבא הבוקר, באה כנסת ישראל, שהיא המלכות, ומשתעשעת בהקב\"ה, והוא מושיט לה שרביט החסד, ולא לה בלבד, אלא לה, וכל אלו שמשתתפים עמה. והרי למדנו, שכתוב, יומם יצוה ה' חסדו ובלילה שירה עמי וגו', שפירושו, מי שעוסק בתורה בלילה, הקב\"ה מושך לו חוט של חסד ביום ועל כן נקראת המלכות אילת השחר. דהיינו על שם שמשבחת להקב\"ה בלילה בשבח התורה."],[9,"ואמר ר' שמעון וכו':","ואר\"ש, בשעה שצריך להאיר הבוקר, נחשך ונשחר האור, והשחורת נמצא. אז מתחברת אשה בבעלה, שלמדנו, משמורה ג' אשה מספרת עם בעלה, דהיינו זו\"ן, לספר עמו, ובאה בהיכלו."],[10,"לבתר כד בעי וכו':","אחר כך כשצריך השמש לבא, הלילה מאיר ובא ולוקח אותו, ואז כל השערים סתומים, וחמורים נוערים, וכלבים נובחים. וכשנחלק הלילה מתחיל המלך לקום, והמטרוניתא שהיא המלכות, מתחילה לזמר, והמלך, שהוא ז\"א, בא ודופק על שער ההיכל, ואמר, פתחי לי אחותי רעיתי וגו'. ואז משתעשע עם נשמות הצדיקים."],[11,"זכאה חולקיה דההוא וכו':","אשרי חלקו של ההוא, שהעיר בזמן ההוא בדברי תורה, משום זה, כל בני היכל המטרוניתא, כולם צריכים לקום בזמן ההוא לשבח את המלך, וכולם משבחים לפניו, והשבח העולה מעולם הזה, שהוא רחוק ממנו, זה מרוצה להקב\"ה יותר מכל."],[12,"כד אסתליק וכו':","כשמסתלק הלילה ובא הבוקר, ונשחר, אז המלך והמטרוניתא בסוד החדוה, דהיינו בזווג, ונותן לה מתנות ולכל בני ההיכל. אשרי חלקו של מי שהוא במספר בני ההיכל."]],[[0,"","וְעַל פִּי מֹשֶׁה קִבְּלוּ אוֹתָם, וְהַיְנוּ מַה שֶּׁאָמַר הַכָּתוּב לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ סָרוּ מַהֵר מִן הַדֶּרֶךְ אֲשֶׁר צִוִּיתִם. צִוִּיתָם כָּתוּב. וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם - אֶחָד מֵחֲמִשָּׁה הָיוּ. וְרַבִּי יוֹסֵי אוֹמֵר, חֲמִשָּׁה מִיִּשְׂרָאֵל, וְאֶחָד מֵהֶם. רַבִּי יְהוּדָה אוֹמֵר, וַחֲמֻשִׁים - אֶחָד מֵחֲמִשִּׁים."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם שֶׁאוֹתוֹ יוֹבֵל הֶעֱלָה אוֹתָם מִמִּצְרַיִם, מִשּׁוּם כָּךְ וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם, וְאִם לֹא - לֹא עָלוּ, וְלָכֵן הִתְעַכְּבוּ חֲמִשִּׁים יוֹם לְקַבֵּל תּוֹרָה. וּמֵאוֹתוֹ מָקוֹם יוֹצֵאת תּוֹרָה וְנִתְּנָה, וְעַל זֶה וַחֲמֻשִׁים חָסֵר, שֶׁבִּגְלַל זֶה עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרַיִם."],[2,"","וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף וְגוֹ'. לָמָּה הֶעֱלָה עַצְמוֹתָיו? אֶלָּא מִשּׁוּם שֶׁהָיָה רֹאשׁ לָרֶדֶת לַגָּלוּת, וְלֹא עוֹד, אֶלָּא שֶׁהוּא סִימַן הַגְּאֻלָּה הָיָה לוֹ, וְהִשְׁבִּיעַ אֶת יִשְׂרָאֵל עַל זֶה. זֶהוּ שֶׁכָּתוּב כִּי הַשְׁבֵּעַ הִשְׁבִּיעַ אֶת בְּנֵי יִשְׂרָאֵל, וַהֲרֵי נִתְבָּאֵר."],[3,"","אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁיִּשְׂרָאֵל הָיוּ עוֹסְקִים לְבַקֵּשׁ מָמוֹן מִן הַמִּצְרִים, וּמֹשֶׁה הָיָה עָסוּק בִּשְׁבוּעַת יוֹסֵף. וְיֵשׁ אוֹמְרִים שֶׁהָאָרוֹן הָיָה בַּנִּילוּס, וְהֶעֱלָה אוֹתוֹ בַּשֵּׁם הַקָּדוֹשׁ. וְעוֹד אָמַר מֹשֶׁה: יוֹסֵף, הִגִּיעַ זְמַן גְּאֻלַּת יִשְׂרָאֵל. וְאָמַר: עֲלֵה שׁוֹר. וְעָלָה. וְיֵשׁ שֶׁאוֹמְרִים שֶׁהָיָה בֵּין מַלְכֵי מִצְרַיִם, וּמִשָּׁם הֶעֱלָה (אותו). וְיֵשׁ אוֹמְרִים, כְּדֵי שֶׁלֹּא יַעֲשׂוּ אוֹתוֹ עֲבוֹדָה זָרָה שָׂמוּ אוֹתוֹ בַּנִּילוּס, וְשֶׂרַח בַּת אָשֵׁר הֶרְאֲתָה לְמֹשֶׁה."],[4,"","וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם. רַבִּי יוֹסֵי פָּתַח, (תהלים כב) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר מִזְמוֹר לְדָוִד. כַּמָּה חֲבִיבָה הַתּוֹרָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, אָהוּב הוּא לְמַעְלָה וְאָהוּב הוּא לְמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב לִדְבָרָיו, וְלֹא עוֹזֵב אוֹתוֹ בָּעוֹלָם הַזֶּה, וְלֹא עוֹזֵב אוֹתוֹ לָעוֹלָם הַבָּא."],[5,"","וּבַתּוֹרָה צָרִיךְ לַעֲסֹק בַּיּוֹם וּבַלַּיְלָה, שֶׁכָּתוּב (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. וְכָתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלַיְלָה וְגוֹ'. מֵילָא בַּיּוֹם, אֲבָל לָמָּה בַּלַּיְלָה? כְּדֵי שֶׁיִּהְיֶה מָצוּי אֶל הַשֵּׁם הַקָּדוֹשׁ שָׁלֵם. כְּמוֹ שֶׁאֵין יוֹם בְּלִי לַיְלָה, וְאֵינוֹ שָׁלֵם אֶלָּא זֶה עִם זֶה, כָּךְ צָרִיךְ בַּתּוֹרָה לְהִמָּצֵא עִם הָאָדָם יוֹם וָלַיְלָה, לִהְיוֹת שְׁלֵמוּת לָאָדָם יוֹמָם וָלַיְלָה."],[6,"","וַהֲרֵי נֶאֱמַר שֶׁעִקַּר הַלַּיְלָה מֵחֲצוֹת וְאֵילָךְ, וְאַף עַל גַּב שֶׁמַּחֲצִית הָרִאשׁוֹנָה בִּכְלַל הַלַּיְלָה הִיא, אֲבָל בַּחֲצוֹת הַלַּיְלָה נִכְנָס הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, וְאָז צָרִיךְ לָאָדָם לָקוּם וְלַעֲסֹק בַּתּוֹרָה."],[7,"","וַהֲרֵי נֶאֱמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא וְכָל הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, כֻּלָּם מַקְשִׁיבִים לְקוֹלוֹ. זֶהוּ שֶׁכּתוּב (שיר ח) הַיּוֹשֶׁבֶת בַּגַּנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וַהֲרֵי פֵּרְשׁוּהָ, הַיּוֹשֶׁבֶת בַּגַּנִּים - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁמְּשַׁבַּחַת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֶׁבַח הַתּוֹרָה בַּלַּיְלָה. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּשְׁתַּתֵּף עִמָּהּ לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בְּשֶׁבַח הַתּוֹרָה."],[8,"","וּכְשֶׁבָּא הַבֹּקֶר, כְּנֶסֶת יִשְׂרָאֵל בָּאָה וּמִשְׁתַּעֲשֵׁעַ בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמוֹשִׁיט לָהּ שַׁרְבִיט שֶׁל חֶסֶד, וְלֹא רַק עָלֶיהָ לְבַדָּהּ, אֶלָּא עָלֶיהָ וְעַל אֵלּוּ שֶׁמִּשְׁתַּתְּפִים עִמָּהּ, וַהֲרֵי נֶאֱמַר שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה וְגוֹ'. וְעַל זֶה נִקְרֵאת אַיֶּלֶת הַשַּׁחַר."],[9,"","וְאָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁרוֹצֶה לְהָאִיר הַבּקֶר, נֶחְשָׁךְ, וְהָאוֹר נִהְיָה קוֹדֵר, וְקַדְרוּת נִמְצֵאת. אָז מִתְחַבֶּרֶת אִשָּׁה בְּבַעְלָהּ, שֶׁשָּׁנִינוּ, אִשָּׁה מְסַפֶּרֶת עִם בַּעְלָהּ לְדַבֵּר עִמּוֹ וְנִכְנֶסֶת לְהֵיכָלוֹ."],[10,"","אַחַר כָּךְ כְּשֶׁרוֹצָה הַשֶּׁמֶשׁ לְהִכָּנֵס, מֵאִיר וּבָא הַלַּיְלָה, וְנוֹטֵל אוֹתוֹ. אָז כָּל הַשְּׁעָרִים סְתוּמִים, וַחֲמוֹרִים נוֹעֲרִים, וּכְלָבִים נוֹבְחִים. כְּשֶׁנֶּחֱצֶה הַלַּיְלָה מַתְחִיל הַמֶּלֶךְ (לקרא) לָקוּם וְהַגְּבִירָה לְזַמֵּר, וּבָא הַמֶּלֶךְ וּמַקִּישׁ עַל שַׁעַר הַהֵיכָל, וְאוֹמֵר פִּתְחִי לִי אֲחוֹתִי רַעְיָתִי וְגוֹ'. וְאָז מִשְׁתַּעֲשֵׁעַ בְּנִשְׁמוֹת הַצַּדִּיקִים."],[11,"","אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ שֶׁמִּתְעוֹרֵר בְּאוֹתוֹ זְמַן בְּדִבְרֵי תוֹרָה. וְלָכֵן כָּל אוֹתָם בְּנֵי הֵיכַל הַגְּבִירָה, כֻּלָּם צְרִיכִים לָקוּם בְּאוֹתוֹ זְמַן לְשַׁבֵּחַ אֶת הַמֶּלֶךְ, וְכֻלָּם מְשַׁבְּחִים לְפָנָיו. וְהַשֶּׁבַח שֶׁעוֹלֶה מֵהָעוֹלָם הַזֶּה, זֶה שֶׁהוּא רָחוֹק, (יותר) זֶה נַחַת רוּחַ לַקָּדוֹשׁ-בָּרוּךְ-הוּא מֵהַכֹּל."],[12,"","כְּשֶׁמִּסְתַּלֵּק הַלַּיְלָה וּבָא הַבֹּקֶר (ומחשיך) וְהִתְקַדֵּר, אָז הַמֶּלֶךְ וְהַגְּבִירָה בְּסוֹד בְּחֶדְוָה, וְנוֹתֵן לָהּ מַתָּנוֹת וּלְכָל בְּנֵי הֵיכָלָהּ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁהוּא בְּמִנְיָן."]]],[["וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם. קוּדְשָׁא בְּרִיךְ הוּא, וּבֵית דִּינֵיהּ. אָמַר רִבִּי יִצְחָק, הַיְינוּ דְּתָנֵינָן, שְׁכִינְתָּא בַּאֲבָהָתָא נַטְלָא. הוֹלֵךְ לִפְנֵיהֶם יוֹמָם: דָּא אַבְרָהָם. בְּעַמּוּד עָנָן: דָּא יִצְחָק. לַנְחוֹתָם הַדֶּרֶךְ: דָּא יַעֲקֹב. דִּכְתִּיב בֵּיהּ (בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ. וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם: דָּא דָּוִד מַלְכָּא.","וְכֻלְּהוּ רְתִיכָא עִלָּאָה קַדִּישָׁא, לְמֵהַךְ יִשְׂרָאֵל בִּשְׁלִימוּתָא דְּכֹלָּא, בְּגִין דְּיֶחזוּן אֲבָהָן פּוּרְקָנָא (ס\"א דבינייהו) דִּלְהוֹן, דִּכְתִּיב, (בראשית מ״ו:ד׳) וְאָנֹכִי אֲעַלְךָ גַּם עָלה, עִם הַמֶּרְכָּבָה. וּכְתִיב וַיְיָ' הוֹלֵךְ וְגוֹ', לָלֶכֶת יוֹמָם וְלָיְלָה. וְכִי אֲמַאי הֲווֹ אַזְלֵי יוֹמָם וְלַיְלָה, יַהֲכוּן בִּימָמָא, וְלָא יַהֲכוּן בְּלֵילְיָא, כִּבְנִי אֱנָשָׁא דְּעַרְקִין, כֵּיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן, אֲמַאי אַזְלִין בִּימָמָא וּבְלֵילְיָא. אֶלָּא, לְאִשְׁתַּכְּחָא בְּהוּ שְׁלֵימוּתָא דְּכֹלָּא, דְּלֵית שְׁלִימוּ אֶלָּא יוֹם וְלַיְלָה.","אָמַר רִבִּי אַבָּא, הָכִי אוֹקִימְנָא, וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן: דָּא אַבְרָהָם. וְלַיְלָה בְּעַמּוּד אֵשׁ: דָּא יִצְחָק. וְאִי הָכִי יַעֲקֹב אָן הוּא. אֶלָּא בְּמִלָּה קַדְמָאָה אִתְּמַר, וְתַמָּן שָׁאֲרִי, כְּמָה דִּכְתִּיב וַיְיָ'.","וְלַיְלָה בְּעַמּוּד אֵשׁ, הֲוָה נָהִיר, בְּסִטְרָא דָּא וּבְדָא. בְּגִין דְּיִרְדְּפוּן מִצְרָאֵי בַּתְרֵיהוֹן, לְאִתְיַיקְרָא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, בִּרְתִּיכוֹי וּפָרָשׁוֹי. בְּגִין לְמֵיזַל יְמָמָא וְלֵילְיָא, אַסְפָּקָלַרְיָא דְּנָהֲרָא, וּדְלָא נָהֲרָא. וְתוּ, בְּגִין לְאַטְעָאָה לְמִצְרָאֵי דְּיֵמְרוּן מִקְרֶה הוּא, דִּכְתִּיב, (ישעיהו י״ט:י״ג) נוֹאֲלוּ שָׂרֵי צוֹעַן, וּכְתִיב (ישעיה מה) מֵשִׁיב חֲכָמִים אָחוֹר, וְעַל דָּא אַזְלֵי בִּימָמָא וּבְלֵילְיָא.","רִבִּי אַבָּא אָמַר, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לוֹן מִמִּצְרַיִם, לְמֶהֱוֵי חוּלָקֵיהּ וְאַחֲסַנְתֵּיהּ. וְתָּא חֲזֵי, בְּסִטְרָא דְּיוֹבְלָא, אִשְׁתְּכַח חֵירוּ לְיִשְׂרָאֵל. וְכֵן לְזִמְנָא דְּאָתֵי, דִּכְתִּיב, (ישעיהו כ״ז:י״ג) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וְגוֹ'.","וּבְגִין הַהוּא יוֹבְלָא עִלָּאָה, אִתְעַכְּבוּ חַמְשִׁין יוֹמִין, לְקַבְּלָא אוֹרַיְיתָא, וּלְמִקְרַב לְטוּרָא דְּסִינַי. וְכֵיוָן דְּאָזְלֵי בִּיְמָמָא, אָזְלֵי בְּלֵילְיָא, לְמֶהוֵי כֹּלָּא חַד יוֹמָא, בֵּין יְמָמָא וְלֵילְיָא, וְלָא אִשְׁתְּכַח פְּרִישׁוּ.","וְלֹא עוֹד, אֶלָּא דְּכֻלְּהוּ בְּנַיְיחָא אַזְלִין, לִרְעוּתָא דְּנַפְשַׁיְיהוּ, בְּיוֹמָא דְּקַבִּילוּ אוֹרַיְיתָא, הֲווֹ חַמְשִׁין יוֹמִין שְׁלֵמִין, יוֹמֵי וְלֵילֵי כְּדְקָא יֵאוֹת, דְּלֵית יוֹם בְּלֹא לַיְלָה, וְלֵית לַיְלָה בְּלא יוֹם, וְלַיְלָה וְיוֹם אִקְרֵי יוֹם אֶחָד. וְכֵיוָן דְּאָזְלוּ חַמְשִׁין יוֹמִין שְׁלֵימִין, כְּדֵין (לקבל נ' דיובלא וכמה) שָׁארוּ עָלַיְיהוּ אִינּוּן נ' יוֹמִין דְּיוֹבְלָא, וּמִסִּטְרָא דְּיוֹבְלָא אִתְיְיהִיב לְהוּ אוֹרַיְיתָא, וּבְגִין כָּךְ אַזְלִין יוֹמָא וְלֵילְיָא.","וְאָמַר רִבִּי אַבָּא, כְּתִיב (בראשית כ״ז:א׳) וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶיןָ עֵינָיו, אֲמַאי. הָא אוֹקִימְנָא, מַאן דְּרָחִים לַחַיָּיבָא, הָכִי הוּא. וְתָּא חֲזֵי, בְּיִצְחָק אִתְכְּלִיל לֵילְיָא, וְלֵילְיָא לא בָּהִיר, וְעַל דָּא וַתִּכְהֶיןָ עֵינָיו, וְכֹלָּא חַד.","ר' יִצְחָק פָּתַח וְאָמַר, (שמות י״ד:ה׳) וַיֻּגַּד לְמֶלֶךְ מִצְרַיִם כִּי בָּרַח הָעָם, וַיֻּגַּד, מַאן קָאָמַר לֵיהּ. אֶלָּא, הָא אוּקְמוּהָ. אֲבָל חַכְמוֹי וְחַרְשׁוֹי אִתְכְּנָשׁוּ לְגַבֵּיהּ, וְאוֹדְעוּהוּ כִּי בָּרַח הָעָם. וַאֲמַאי קַאמְרוּ דָּא. אֶלָּא חָמוּ בְּחָכְמְתָא דִּלְהוֹן, דַּהֲווֹ אַזְלֵי יְמָמָא וְלֵילְיָא, אָמְרוּ וַדַּאי עַרְקִין אִינּוּן. וְלא עוֹד אֶלָּא דְּחָמוּ דְּלָא הֲווֹ אַזְלֵי בְּאוֹרַח מֵישָׁר, כְּמָה דִּכְתִּיב וְיָּשׁוּבוּ וְיַּחֲנוּ לִפְנֵי פִּי הַחִירוֹת.","(שמות י״ד:ז׳) וַיִּקַּח שֵׁשׁ מֵאוֹת וְגוֹ'. שֵׁשׁ מֵאוֹת אֲמַאי. אָמַר רִבִּי יוֹסֵי, לָקֳבֵל מִנְיָינָא דְּיִשְׂרָאֵל, דִּכְתִּיב כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי. בָּחוּר: לָקֳבֵל הַגְּבָרִים דְּאִינּוּן עִקָרָא דְּכָל יִשְׂרָאֵל. וְכָל רֶכֶב מִצְרָיִם: שְׁאַר רְתִיכִין, דְּאִינּוּן טְפָלִין לַאֲחוֹרֵי, (נ\"א לאחרנין) לָקֳבֵל הַטַּף דִּכְתִּיב לְבַד מִטָּף. וְכֹלָּא עָבִיד בְּעֵיטָא דְּחַרְשׁוֹי וְחַכְמוֹי. וְשָׁלִישִׁים עַל כֻּלּוֹ, כֹּלָּא בְּחָכְמְתָא, לָקֳבֵל דַּרְגִּין עִלָּאִין, תְּרֵין וְחָד. ר' יִצְחָק אָמַר, כְּתַרְגּוּמוֹ, וּמְזָרְזִין. זְרִיזִין הֲווֹ בְּכֹלָּא.","וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר. ר' חִיָּיא אָמַר, כְּתִיב (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה. בְּזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהִיב שֻׁלְטָנוּתָא לְרַבְרְבֵי עַמִּין לְעֵילָּא, יָהִיב לְהוּ לְעַמָּא דִּלְהוֹן לְתַתָּא. וּבְשַׁעֲתָא דְּנָחִית לוֹן מִדַּרְגֵּיהוֹן דִּלְעֵילָּא, נָחִית לוֹן לְעַמָּא לְתַתָּא, וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר, הָא מְמָנָא דִּלְהוֹן, וְאוּקְמוּהָ, דְּדָבַר רְתִיכִין דִּשְׁאַר עַמִּין, וְכֻלְּהוּ נָפְלוּ בְּמַשְׁרִיתָא דְּסִיסְרָא לְבָתַר וְהַיְינוּ בָּחוּר (נ\"א ולבתר) וְכֹל רֶכֶב מִצְרָיִם.","כְּתִיב (שיר השירים א׳:ט׳) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. תָּא חֲזֵי, כְּדוּגְמַת סוּסְיָא נוּקְבָּא, אִתְחָזֵי לְהוֹן לְסוּסֵיהוֹן דְּפַרְעֹה, וְאוּקְמוּהָ. אֶלָּא לְסוּסָּתִי בְּרִכְבֵי פַרְעֹה, תָּא חֲזֵי, פַּרְעֹה בְּשַׁעֲתָא דְּהֲוָה רָדִיף אֲבָתְרַיְיהוּ דְּיִשְׂרָאֵל, מַה עָבֵד, נָטַל סוּסְוָון נוּקְבָן, וְכָפַת לוֹן בִּרְתִּיכוֹי בְּקַדְמִיתָא, וְסוּסִין דּוּכְרָאֵי כָּפַת לוֹן לַאֲחוֹרֵיהוֹן, וַהֲווּ מְזַיְּינִין דּוּכְרֵי לָקֳבֵל נוּקְבֵי, וְנוּקְבֵי לָא בָּעָאן, וְאוֹחָן לְמֵיזָל. כֵּיוָן דְּקָרִיב (נ\"א וכד אדביק) לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, נָטַל נוּקְבֵי וְשַׁוֵּי לוֹן לַאֲחוֹרֵי, וְסוּסְוָון דּוּכְרִין לְקַדְמִין, לְאַבְאָשָׁא לְיִשְׂרָאֵל, וּלְאַגָּחָא בְּהוּ קְרָבָא."],[[0,"וה' הולך לפניהם יומם:","וה' פירושו, הקב\"ה ובית דינו, שהיא המלכות. כי הו' של והוי\"ה מרבה את המלכות. אמר ר' יצחק היינו שלמדנו, שהשכינה נוסעת עם האבות. כי \u0003הולך לפניהם יומם,\u0004 זהו אברהם. \u0003בעמוד ענן,\u0004 זהו יצחק. \u0003לנחותם הדרך,\u0004 זהו יעקב, שכתוב בו, ויעקב הלך לדרכו. \u0003ולילה בעמוד אש להאיר להם,\u0004 זהו דוד המלך."],[1,"וכלהו רתיכא עלאה וכו':","וכולם, הם מרכבה העליונה הקדושה, כי אברהם יצחק יעקב הם חג\"ת ג' רגלי הכסא, ודוד המלך הוא רגל רביעי. כדי שילכו ישראל בשלמות הכל, וכדי שיראו האבות הגאולה שלהם, שכתוב, ואנכי אעלך גם עלה, עם המרכבה. וכתוב, וה' הולך וגו' ללכת יומם ולילה, שואל, למה הלכו יומם ולילה, ילכו ביום, ולא ילכו בלילה כאנשים הבורחים, כי כיון שהקב\"ה שמר אותם ולא פחדו, למה הלכו ביום ובלילה. כבורחים. ומשיב. אלא שימצא בהם שלימות הכל, כי אין שלמות אלא יומם ולילה. כי יום הוא מדת ז\"א ולילה מדת הנוקבא, וכל השלימות הוא בהתחברותם יחד, בסו\"ה ויהי ערב ויהי בקר יום אחד כנ\"ל (בראשית א' דף קי\"ח ד\"ה וביאור)."],[2,"א\"ר אבא הכי וכו':","אר\"א כך העמדנו, וה' הולך לפניהם יומם בעמוד ענן, זהו אברהם, שהוא חסד. ולילה בעמוד אש, זהו יצחק, שהוא גבורה. ואם כן יש לשאול, איפה הוא יעקב, שהוא ת\"ת. ומשיב, אלא במלה הראשונה הוא נאמר, ושם הוא שורה, כמו שכתוב, \u0003וה',\u0004 שהוא ת\"ת ומלכות, ויעקב הוא ת\"ת."],[3,"ולילה בעמוד אש וכו':","ולילה בעמוד אש היה מאיר, כדי להאיר בצד זה ביום, בחסד, ובזה, בלילה בגבורה. כדי שירדפו מצרים אחריהם ברכבו ופרשיו, לכבד שמו של הקב\"ה, שיטבעו ולא ישאר מהם עד אחד. ועל זה היה צריך למדת הגבורה. כדי ללכת יומם ולילה, פירושו מראה המאירה, שהוא ז\"א שנק' יום. ומראה שאינה מאירה, שהיא המלכות הנקראת לילה. ועוד. כדי להטעות את המצרים, שיאמרו מקרה הוא, ולא ה' הוציאם, כי ע\"כ ילכו יום ולילה כמו בורחים, שכתוב נואלו שרי צוען. וכתוב, משיב חכמים אחור. וע\"כ הלכו ביום ובלילה."],[4,"ר' אבא אמר וכו':","רא\"א, אשרי חלקם של ישראל, שהקדוש ברוך הוא הוציאם ממצרים כדי שיהיו חלקו ונחלתו. ובוא וראה, מצד היובל, שהיא בינה, נמצא החירות לישראל. וכן לעתיד לבא, שכתוב, ביום ההוא יתקע בשופר גדול וגו'."],[5,"ובגין ההוא יובלא וכו':","ומשום יובל ההוא נתעכבו חמשים יום אחר יציאת מצרים כדי לקבל התורה, ולקרב להר סיני. כי יש ביובל חמשים שערים, וכדי להתתקן בהם היו צריכים חמשים יום. וכיון שהלכו ביום הלכו ג\"כ בלילה, שיהיה הכל יום אחד, ולא ימצא פירוד בין יום ולילה. שהם זו\"ן."],[6,"ולא עוד אלא וכו':","ולא עוד, אלא שכולם הלכו בנחת לרצון עצמם. כדי ליחד יום ולילה, שהם זו\"ן. וביום שקבלו התורה היו חמשים יום שלמים יום ולילה, כראוי. כי אין יום בלי לילה ואין לילה בלי יום, שאין שלמות לז\"א בלי המלכות, ואין שלמות למלכות בלי ז\"א. ולילה ויום נקראים יום אחד. כמש\"כ ויהי ערב ויהי בקר יום אחד. וכיון שהלכו חמשים יום שלמים אז שרו עליהם אלו חמשים יום של יובל, שהם חמשים שערי בינה, ואז מצד היובל ניתנה להם התורה. ומשום זה הלכו יום ולילה."],[7,"אמר ר' אבא וכו':","ואר\"א, כתוב, ויהי כי זקן יצחק ותכהין עיניו. ולמה. הנה בארנו, מי שאוהב את הרשע, כך הוא, שתכהנה עיניו. ובוא וראה. ביצחק, שהוא גבורה, נכלל לילה שהוא מלכות, והלילה אינו בהיר, ועל כן ותכהין עיניו מראות. והכל אחד. כי התכללות הלילה ביצחק הוא ענין אחד עם אהבת יצחק את עשו."],[8,"ר' יצחק פתח וכו':","ר\"י פתח ואמר, ויגד למלך מצרים כי ברח העם. שואל. \u0003ויגד,\u0004 מי אמר לו. ומשיב. אלא בארנו, אבל חכמנו ומכשפיו נתקבצו אליו והודיעו לו, כי ברח העם. ולמה אמרו זה. אלא שראו בחכמתם, שהיו ישראל הולכים יום ולילה, אמרו, ודאי שבורחים הם ולא עוד, אלא שראו, שלא היו הולכים בדרך הישר. כמ\"ש, וישובו ויחנו לפני פי החירות. והודיעו לו גם זה, וע\"כ רדף אחריהם."],[9,"ויקח שש מאות:","שואל. שש מאות למה. אמר ר' יוסי, שהוא כנגד מספר ישראל, שכתוב, כשש מאות אלף רגלי. \u0003בחור,\u0004 כנגד הגברים שבישראל, שהם עיקר כל ישראל. \u0003וכל רכב מצרים,\u0004 הם שאר המרכבות שהם טפלים לאחורי שש מאות הנ\"ל, שהם כנגד הטף שבישראל, שאינם בחשבון שש מאות אלף רגלי, אלא טפלים להם, שנאמר, לבד מטף. והכל עשה בעצת מכשפיו וחכמיו. \u0003ושלישים על כלו,\u0004 הכל עשה בחכמה, שהם כנגד מדרגות העליונות, הבאות, שתים, ואחד עליהן. ר' יצחק אמר כתרגומו, ומזרזין. כי זריזים היו בכל דבר."],[10,"ויקח שש מאות רכב בחור:","ר' חייא אמר, כתוב, יפקוד ה' על צבא המרום במרום ועל מלכי האדמה וגו'. בזמן שהקב\"ה נותן ממשלה לשרי העמים למעלה, נותן לעמים שלהם למטה, ובשעה שמוריד אותם מדרגתם למעלה, מוריד העמים שלהם למטה. ויקח שש מאות רכב בחור, הוא הממונה שלהם שלקח אותם. והעמדנו, שנהג המרכבות של שאר העמים, שאלו שש מאות רכב לא היו ממצרים אלא משאר העמים. וכולם נפלו במחנה של סיסרא. והיינו שש מאות רכב בחור, ואחר כך, וכל רכב מצרים. כי כיון שכתוב, וכל רכב מצרים, א\"כ שש מאות רכב בחור מיותר, אלא ודאי שש מאות רכב בחור הוא משאר העמים, וע\"כ אומר אח\"כ וכל רכב מצרים."],[11,"כתיב לסוסתי וגו':","כתוב, לסוסתי ברכבי פרעה דמיתיך רעיתי. בוא וראה, כדמיון סוסה נקבה נראה לסוסי פרעה, וע\"כ רדפו אחריה אל הים, ובארוהו. אלא לססתי ברכבי פרעה, בוא וראה, פרעה, בשעה שהיה רודף אחרי ישראל, מה עשה, לקח סוסות נקבות ואסר אותן במרכבה תחילה, וסוסים זכרים אסר לאחוריהן, והיו הזכרים מתחממים כנגד הנקבות, והנקבות לא רצו, ומיהרו לרוץ. כיון שקרב לישראל, לקח הנקבות ושם אותם לאחור וסוסים הזכרים מתחילה, כדי להרע לישראל ולעשות בהם מלחמה. כי למלחמה, סוסים הזכרים חזקים מן הנקבות."]],[[0,"","וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם - הַקָּדוֹשׁ בָּרוּךְ הוּא וּבֵית דִּינוֹ. אָמַר רַבִּי יִצְחָק, הַיְנוּ שֶׁשָּׁנִינוּ, שְׁכִינָה נוֹסַעַת בָּאָבוֹת. הֹלֵךְ לִפְנֵיהֶם יוֹמָם - זֶה אַבְרָהָם. בְּעַמּוּד עָנָן - זֶה יִצְחָק. לַנְחֹתָם הַדֶּרֶךְ - זֶה יַעֲקֹב, שֶׁכָּתוּב בּוֹ (בראשית לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ. וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם - זֶה דָּוִד הַמֶּלֶךְ."],[1,"","וְכֻלָּם מֶרְכָּבָה עֶלְיוֹנָה קְדוֹשָׁה לָלֶכֶת עִם יִשְׂרָאֵל בִּשְׁלֵמוּת הַכֹּל, כְּדֵי שֶׁהָאָבוֹת יִרְאוּ אֶת גְּאֻלָּתָם, שֶׁכָּתוּב וְאָנֹכִי אֲעַלְךְ גַּם עָלֹה, עִם הַמֶּרְכָּבָה. וְכָתוּב וַה' הֹלֵךְ וְגוֹ' לָלֶכֶת יוֹמָם וָלָיְלָה. וְכִי לָמָּה הָיוּ הוֹלְכִים יוֹמָם וָלַיְלָה? יֵלְכוּ בַּיּוֹם, וְלֹא יֵלְכוּ בַּלַּיְלָה כַּאֲנָשִׁים שֶׁבּוֹרְחִים, כֵּיוָן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁמַר אוֹתָם, לָמָּה הָלְכוּ בַּיּוֹם וּבַלַּיְלָה? אֶלָּא כְּדֵי לְהִמָּצֵא בָהֶם שְׁלֵמוּת הַכֹּל, שֶׁאֵין שְׁלֵמוּת אֶלָּא יוֹם וָלַיְלָה."],[2,"","אָמַר רַבִּי אַבָּא, כָּךְ בֵּאַרְנוּ, וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן - זֶה אַבְרָהָם. וְלַיְלָה בְּעַמּוּד אֵשׁ - זֶה יִצְחָק. וְאִם כָּךְ, אֵיפֹה יַעֲקֹב? אֶלָּא שֶׁנֶּאֱמַר בַּדִּבּוּר הָרִאשׁוֹן, וְשָׁם הִתְחִיל, כְּמוֹ שֶׁכָּתוּב וַה'."],[3,"","וְלַיְלָה בְּעַמּוּד אֵשׁ, הָיָה מֵאִיר בְּצַד זֶה וּבָזֶה, כְּדֵי שֶׁהַמִּצְרִים יִרְדְּפוּ אַחֲרֵיהֶם, שֶׁיִּתְכַּבֵּד שֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַרְכְּבוֹתָיו וּפָרָשָׁיו. כְּדֵי לָלֶכֶת יוֹמָם וָלַיְלָה, אַסְפַּקְלַרְיָה הַמְּאִירָה, וְשֶׁלֹּא מְאִירָה. וְעוֹד, כְּדֵי לְהַטְעוֹת אֶת הַמִּצְרִים, שֶׁיֹּאמְרוּ מִקְרֶה הוּא, שֶׁכָּתוּב (ישעיה יט) נוֹאֲלוּ שָׂרֵי צוֹעַן, וְכָתוּב (שם מד) מֵשִׁיב חֲכָמִים אָחוֹר, וְעַל כֵּן הָלְכוּ בַּיּוֹם וּבַלַּיְלָה."],[4,"","רַבִּי אַבָּא אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אוֹתָם מִמִּצְרַיִם לִהְיוֹת חֶלְקוֹ וְנַחֲלָתוֹ. וּבֹא רְאֵה, בְּצַד הַיּוֹבֵל נִמְצְאָה חֵרוּת לְיִשְׂרָאֵל, וְכֵן לֶעָתִיד לָבא, שֶׁכָּתוּב (ישעיה כז) וְהָיָה בַּיּוֹם הַהוּא יִתָּקַע בְּשׁוֹפָר גָּדוֹל וְגוֹ'."],[5,"","וּמִשּׁוּם אוֹתוֹ יוֹבֵל עֶלְיוֹן, הִתְעַכְּבוּ חֲמִשִּׁים יוֹם לְקַבֵּל הַתּוֹרָה וְלִקְרַב לְהַר סִינַי. וְכֵיוָן שֶׁהָלְכוּ בַּיּוֹם, הָלְכוּ בַּלַּיְלָה, לִהְיוֹת הַכֹּל יוֹם אֶחָד בֵּין יוֹם וָלַיְלָה, וְלֹא נִמְצֵאת הַפְרָדָה."],[6,"","וְלֹא עוֹד, אֶלָּא שֶׁכֻּלָּם הָלְכוּ בִמְנוּחָה לִרְצוֹן נַפְשָׁם, בַּיּוֹם שֶׁקִּבְּלוּ הַתּוֹרָה, הָיוּ חֲמִשִּׁים יָמִים שְׁלֵמִים, יָמִים וְלֵילוֹת כָּרָאוּי, שֶׁאֵין יוֹם בְּלִי לַיְלָה, וְאֵין לַיְלָה בְּלִי יוֹם, וְלַיְלָה וָיוֹם נִקְרָא יוֹם אֶחָד. וְכֵיוָן שֶׁהָלְכוּ חֲמִשִּׁים יָמִים שְׁלֵמִים, אָז שָׁרוּ עֲלֵיהֶם אוֹתָם חֲמִשִּׁים יְמֵי הַיּוֹבֵל, וּמִצַּד שֶׁל הַיּוֹבֵל (בינה) נִתְּנָה לָהֶם תּוֹרָה, וְלָכֵן הָלְכוּ יוֹמָם וָלַיְלָה."],[7,"","וְאָמַר רַבִּי אַבָּא, כָּתוּב וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶיןָ עֵינָיו, לָמָּה? הֲרֵי בֵּאַרְנוּ, שֶׁמִּי שֶׁאוֹהֵב רְשָׁעִים, כָּךְ הוּא. וּבא רְאֵה, בְּיִצְחָק נִכְלָל הַלַּיְלָה, וְלַיְלָה לֹא בָהִיר, וְעַל זֶה וַתִּכְהֶיןָ עֵינָיו, וְהַכֹּל אֶחָד."],[8,"","רַבִּי יִצְחָק פָּתַח וְאָמַר, וַיֵּגּד לְמֶלֶךְ מִצְרַיִם כִּי בָרַח הָעָם. וַיֵּגּד - מִי אָמַר לוֹ? אֶלָּא כָּךְ פֵּרְשׁוּהָ. אֲבָל חֲכָמָיו וּמְכַשְּׁפָיו הִתְכַּנְּסוּ אֵלָיו וְהוֹדִיעוּהוּ כִּי בָרַח הָעָם. וְלָמָּה אָמְרוּ אֶת זֶה? אֶלָּא רָאוּ בַּחָכְמָה שֶׁלָּהֶם שֶׁהָיוּ הוֹלְכִים יוֹמָם וָלַיִל, אָמְרוּ וַדַּאי שֶׁהֵם בּוֹרְחִים. וְלֹא עוֹד, אֶלָּא שֶׁרָאוּ שֶׁאֵינָם הוֹלְכִים בְּדֶרֶךְ יְשָׁרָה, כְּמוֹ שֶׁכָּתוּב וְיָשֻׁבוּ וְיַחֲנוּ לִפְנֵי פִּי הַחִירֹת."],[9,"","וַיִּקַּח שֵׁשׁ מֵאוֹת וְגוֹ'. שֵׁשׁ מֵאוֹת לָמָּה? אָמַר רַבִּי יוֹסֵי, כְּנֶגֶד הַמִּנְיָן שֶׁל יִשְׂרָאֵל, שֶׁכָּתוּב כְּשֵׁשׁ מֵאוֹת אֶלֶף רַגְלִי. בָּחוּר - כְּנֶגֶד הַגְּבָרִים שֶׁהֵם הָעִקָּר שֶׁל כָּל יִשְׂרָאֵל. וְכֹל רֶכֶב מִצְרָיִם - שְׁאָר הַמֶּרְכָּבוֹת, שֶׁהֵם טְפֵלִים לַאֲחוֹרַיִם (לאחרים), כְּנֶגֶד הַטַּף, שֶׁכָּתוּב לְבַד מִטָּף. וְהַכֹּל עָשָׂה בַּעֲצַת מְכַשְּׁפָיו וַחֲכָמָיו. וְשָׁלִשִׁם עַל כֻּלּוֹ - הַכֹּל בְּחָכְמָה, כְּנֶגֶד דְּרָגוֹת הָעֶלְיוֹנוֹת שְׁנַיִם וְאֶחָד. רַבִּי יִצְחָק אָמַר, כְּתַרְגּוּמוֹ - וּמְזָרְזִין. שֶׁהָיוּ זְרִיזִים בַּכֹּל."],[10,"","וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר. רַבִּי חִיָּיא אָמַר, כָּתוּב יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה. בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן שִׁלְטוֹן לִגְדוֹלֵי הָעַמִּים לְמַעְלָה, נוֹתֵן לָהֶם לָעָם שֶׁלָּהֶם לְמַטָּה. וּבְשָׁעָה שֶׁמּוֹרִיד אוֹתָם מִדַּרְגָּתָם שֶׁלְּמַעְלָה, מוֹרִיד אֶת הָעָם לְמַטָּה. וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר - הֲרֵי הַמְמֻנֶּה שֶׁלָּהֶם, וּפֵרְשׁוּהָ, שֶׁהִנְהִיג אֶת מַרְכְּבוֹת שְׁאָר הָעַמִּים, וְכֻלָּם נָפְלוּ בְּמַחֲנֵה סִיסְרָא אַחַר כָּךְ, וְהַיְנוּ בָּחוּר (ואחר כך) וְכֹל רֶכֶב מִצְרָיִם."],[11,"","כָּתוּב (שיר א) לְסֻסָתִי בְּרִכְבֵי פַרְעֹה דִּמִּיתִיךְ רַעְיָתִי. בּא רְאֵה, כְּדֻגְמַת סוּסָה נְקֵבָה נִרְאֲתָה לַסּוּסִים שֶׁל פַּרְעֹה, וּפֵרְשׁוּהָ. אֶלָּא לְסֻסָתִי בְּרִכְבֵי פַרְעֹה - בֹּא רְאֵה, בְּשָׁעָה שֶׁפַּרְעֹה הָיָה רוֹדֵף אַחַר יִשְׂרָאֵל, מֶה עָשָׂה? נָטַל סוּסוֹת נְקֵבוֹת, וְכָפַת אוֹתָן בְּמַרְכְּבוֹתָיו בַּתְּחִלָּה, וְאֶת הַסּוּסִים הַזְּכָרִים כָּפַת מֵאָחוֹר, וְהָיוּ הַזְּכָרִים מִתְחַמְּמִים כְּנֶגֶד הַנְּקֵבוֹת, וְהַנְּקֵבוֹת מְסָרְבוֹת, וּמִהֲרוּ לָרוּץ. כֵּיוָן שֶׁקָּרַב (וכאשר הדביק) אֶל יִשְׂרָאֵל, נָטַל אֶת הַנְּקֵבוֹת וְשָׂם אוֹתָם לְאָחוֹר, וְהַסּוּסִים הַזְּכָרִים לְפָנִים, כְּדֵי לְהָרַע לְיִשְׂרָאֵל וְלַעֲרֹךְ בָּהֶם קְרָב."]]],[["כְּגַוְונָא דָּא, וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם, וּבָתַר חָזְרָה שְׁכִינְתָּא לַאֲחוֹרֵיהוֹן דְּיִשְׂרָאֵל, דִּכְתִּיב וַיִּסַּע מַלְאַךְ הָאֱלהִים וְגוֹ'. בְּגִינֵי כַּךְ דִּמִּיתִיךְ רַעְיָתִי.","(שמות י״ד:י׳) וּפַרְעֹה הִקְרִיב, וְהַאי קְרָא הָא אוּקְמוּהָ. דְּאַקְרִיב לְכָל חֵילוֹי וּרְתִיכוֹי, לְאַגָּחָא קְרָבָא. וְתוּ וּפַרְעֹה הִקְרִיב. רִבִּי יוֹסֵי אָמַר, הָא אִתְּמַר דְּקָרִיב לוֹן לִתְשׁוּבָה. וּפַרְעֹה הִקְרִיב.","כְּתִיב (ישעיהו כ״ו:ט״ז) יְיָ' בַּצַּר פְּקָדוּךָ צָקוּן לַחַשׁ וְגוֹ'. בַּצַּר פְּקָדוּךָ: לָא פַּקְדִין יִשְׂרָאֵל לְקוּדְשָׁא בְּרִיךְ הוּא, בְּשַׁעֲתָא דְּנַיְיחָא, אֶלָּא בְּשַׁעֲתָא דְּעָקִין לְהוּ, וּכְדֵין כֻּלְּהוּ פַּקְדִין לֵיהּ. צָקוּן לַחַשׁ: וְכֻלְּהוּ צַלָּאן בִּצְלוֹתִין וּבְבָעוּתִין, וְאָרִיקוּ קָמֵיהּ צְלוֹתִין. אֵימָתַי. (ישעיהו כ״ו:ט״ז) מוּסָרְךָ לָמוֹ, בְּשַׁעֲתָא דְּפָקִיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא בִּרְצוּעוֹי. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא קָאִים עָלַיְיהוּ בְּרַחֲמֵי, וְנִיחָא קָמֵיהּ הַהוּא קָלָא דִּלְהוֹן, בְּגִין לְאִתְפָּרְעָא מִן שַׂנְאֵיהוֹן, וְאִתְמְלֵי עָלַיְיהוּ בְּרַחֲמֵי.","כְּמָה דְּאוֹקִימְנָא, מְתָל לְיוֹנָה עִם הַנִּץ וְכוּ', כַּךְ יִשְׂרָאֵל הֲווֹ קְרִיבִין לְיַמָּא, וַהֲווּ חָמָאן לְיַמָּא קָמַיְיהוּ, אָזִיל וְסָעִיר וְגַלְגַּלּוֹהִי זַקְפִין לְעֵילָּא, הֲווֹ דְּחִילִין. זָקְפוּ עֵינַיְיהוּ וְחָמוּ לְפַרְעֹה וּלְמַשִׁירְיָיתֵיהּ, וְאַבְנֵי גִּירִין וּבַלִּסְטְרָאִין, כְּדֵין וַיִּירְאוּ מְאֹד. מַה עָבְדוּ, וַיִּצְעֲקוּ בְּנֵי יִשְׂרָאֵל מַאן גָּרִים הַאי דְּקָרִיבוּ יִשְׂרָאֵל לְגַבֵּי אֲבוּהוֹן דִּלְעֵילָּא, פַּרְעֹה. הֲדָא הוּא דִּכְתִּיב וּפַרְעֹה הִקְרִיב וְהָא אִתְּמַר.","(שמות י״ד:י״ג) וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ אֶת יְשׁוּעַת יְיָ'. אָמַר רִבִּי שִׁמְעוֹן זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּהָא רַעְיָא כְּמֹּשֶׁה אָזִיל בְּגַוַּויְיהוּ. כְּתִיב (ישעיהו ס״ג:י״א) וַיִּזְכּוֹר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ. וַיִּזְכּוֹר יְמֵי עוֹלָם: דָּא קוּדְשָׁא בְּרִיךְ הוּא. מֹשֶׁה עַמּוֹ (מכאן שלי הוא) שָׁקִיל הֲוָה מֹשֶׁה כְּכָל יִשְׂרָאֵל. וְאוֹלִיפְנָא מֵהָא, כִּי רַעְיָא דְּעַמָּא הוּא מַמָּשׁ עַמָּא כֻּלְּהוּ, אִי אִיהוּ זָכֵי, עַמָּא כֻּלְּהוּ זָכָאן. וְאִי אִיהוּ לָא זָכֵי, עַמָּא כֻּלְּהוּ לָא זָכָאן וְאִתְעֲנָשׁוּ בְּגִינֵיהּ, וְהָא אוּקְמוּהָ.","הִתְיַצְּבוּ וּרְאוּ, לֵית לְכוּ לְאַגָּחָא קְרָבָא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא, יַגִּיחַ קְרָבָא בְּגִינֵיכוֹן, כְּמָה דְּאַתְּ אָמֵר, יְיָ' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. תָּא חֲזֵי, הַהוּא לֵילְיָא, כָּנַשׁ קוּדְשָׁא בְּרִיךְ הוּא לְפָּמַלְיָא דִּילֵיהּ, וְדָאִין דִּינַיְיהוּ דְּיִשְׂרָאֵל, וְאִלְמָלֵא דְּאַקְדִּימוּ אֲבָהָן עָלַיְיהוּ דְּיִשְׂרָאֵל, לָא אִשְׁתֵּזִיבוּ מִן דִּינָא. רִבִּי יְהוּדָה אָמַר, זְכוּתָא דְּיַעֲקֹב אַגִּין עָלַיְיהוּ דְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (תהילים קכ״ד:א׳) לוּלֵי יְיָ' שֶׁהָיָה לָנוּ יֹאמַר נָא יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא.","(שמות י״ד:י״ד) יְיָ יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. רִבִּי אַבָּא פָּתַח (ישעיהו נ״ח:י״ג) אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶיךָ עֲשׂוֹת חֲפָצֶיךָ בְּיוֹם קָדְשִׁי. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוֹן, לְאִתְדַּבְּקָא בְּהוּ, מִכָּל שְׁאַר עַמִּין דְּעָלְמָא, וּמִגּוֹ רְחִימוּתָא דִּלְהוֹן, קָרִיב לוֹן לְגַבֵּיהּ, וְיָהַב לוֹן אוֹרַיְיתָא, וְיָהַב לוֹן שַׁבָּת, דְּאִיהוּ קַדִּישָׁא מִכָּל שְׁאַר יוֹמִין, וְנַיְיחָא מִכֹּלָּא, וְחֶדְוָה דְּכֹלָּא, וְשָׁקִיל שַׁבָּת, לָקֳבֵל אוֹרַיְיתָא כְּלָּא, וּמַאן דְּנָטִיר שַׁבָּת, כְּאִילּוּ נָטִיר אוֹרַיְיתָא כֻּלָּא.","וְקָרָאתָ לַשַּׁבָּת עוֹנֶג, עִנּוּגָא דְּכֹלָּא, עִנּוּגָא דְּנַפְשָׁא וְגוּפָא עִנּוּגָא דְּעִלָּאִין וְתַתָּאִין. וְקָרָאתָ לַשַּׁבָּת, מַאי וְקָרָאתָ. דְּיַזְמִין לֵיהּ. כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ג:ב׳) מִקְרָאֵי קֹדֶשׁ, כְּלוֹמַר, זְמִינִין, כְּמָה דִּמְזַמִּין אוּשְׁפִּיזָא לְבֵיתֵיהּ. וְעַל דָּא וְקָרָאתָ לַשַּׁבָּת עֹנֶג, דְּיַזְמִין לֵיהּ, כְּמָה דִּמְזַמְנִין אוּשְׁפִּיזָא, בְּפָתוֹרָא מְתַקְּנָא, בְּבֵיתָא מְתַקְּנָא כְּדְקָא יֵאוֹת, בְּמֵיכְלָא וּבְמִשְׁתְּיָא כְּדְקָא יֵאוֹת, יַתִּיר עַל שְׁאַר יוֹמִין. וְקָרָאתָ לַשַּׁבָּת מִבְּעוֹד יוֹם. (אמור כ\"ב ע\"א) לִקְדוֹשׁ יְיָ' מְכוּבָּד: דָּא יוֹם כִּפּוּרִים. תְּרֵי דְּאִינּוּן חַד. וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךָ, כְּמָה דְּאוֹקִימְנָא."],[[0,"כגוונא דא וה' וגו':","כעין זה, וה' הולך לפניהם יומם. ואח\"כ חזרה השכינה לאחורי ישראל, שכתוב, ויסע מלאך האלקים וגו'. משום זה דמיתיך רעיתי. פירוש. מובא לעיל כי וה' ה\"ס ת\"ת ומלכות, דהיינו הוא ובית דינו. (כנ\"ל אות נ\"ב) ואח\"כ כתוב ויסע מלאך האלקים וגו', שהוא מלכות, וילך מאחריהם. ונשאר ת\"ת הולך לפניהם, כדי להלחם עם המצרים. ועל זה כתוב \u0003דמיתיך רעיתי,\u0004 מלשון דממה, כי העמידה מאחורי ישראל כדי להלחם לבדו עם המצרים ולכלותם שלא ישאר מהם עד אחד."],[1,"ופרעה הקריב וגו':","מקרא זה כבר העמידוהו, שהקריב כל חילו ורכביו לעשות מלחמה. ועוד ופרעה הקריב, ר' יוסי אמר, הרי למדנו שהקריבם לתשובה, וע\"כ כתוב ופרעה הקריב, ולא ופרעה קרב."],[2,"כתיב, ה' בצר פקדוך צקון לחש:","בצר פקדוך, פירושו, אין ישראל פוקדים להקב\"ה בשעת נחת, אלא בשעה שצר להם, אז כולם פוקדים לו. \u0003צקון לחש,\u0004 שכולם מתפללים בתפלות ובקשות, ושופכים לפניו תפילות. מתי, \u0003מוסרך למו,\u0004 בשעה שפקד אותם הקב\"ה ברצועה שלו. אז הקב\"ה עומד עליהם ברחמים, ורצוי לפניו הקול שלהם, כדי להפרע מאויביהם ומתמלא עליהם רחמים."],[3,"כמה דאוקימנא וכו':","כמו שבארנו משל ליונה עם הנץ וכו' (מד\"ר שה\"ש פ\"ב) כך ישראל, היו קרבים אל הים, והיו רואים הים לפניהם הולך וסוער, וגליו זקופים למעלה, היו יראים. נשאו עיניהם וראו את פרעה וחילו ואבני גירין וחצים, אז ויראו מאד. מה עשו, ויצעקו בני ישראל. מי גרם זה שקרבו ישראל לאביהם של מעלה, פרעה. ז\"ש ופרעה הקריב. והרי נתבאר."],[4,"ויאמר משה אל העם אל תיראו וגו':","אמר ר\"ש, אשרי חלקם של ישראל שרועה כמו משה הולך בתוכם. כתוב ויזכור ימי עולם משה עמו. ויזכור ימי עולם זהו הקב\"ה. משה עמו, כי שקול היה משה כנגד כל ישראל. ולמדנו מזה, כי רועה העם הוא ממש כל העם, אם הוא זכה כל העם צדיקים ואם הוא לא זכה כל העם אינם זוכים ונענשים בשבילו. וכבר בארוהו."],[5,"התיצבו וראו:","אין לכם לעשות מלחמה, כי הקב\"ה יעשה מלחמה בשבילכם. כש\"א, ה' ילחם לכם ואתם תחרישון. בוא וראה בלילה ההוא אסף הקב\"ה את הפמליא שלו ודן דינם של ישראל, ואם לא הקדימו האבות להתפלל על ישראל, לא היו נצולים מן הדין. ר' יהודה אמר, זכותו של יעקב הגין עליהם, על ישראל, ז\"ש לולי ה' שהיה לנו יאמר נא ישראל, הוא ישראל סבא, דהיינו יעקב."],[6,"ה' ילחם לכם ואתם תחרישון:","ר' אבא פתח. אם תשיב משבת רגלך עשות חפציך ביום קדשי. אשריהם ישראל, שהקב\"ה חפץ בהם להתדבק בהם, מכל שאר אומות העולם. ומתוך האהבה אליהם, קרב אותם אצלו, ונתן להם התורה, ונתן להם השבת שהוא קדוש מכל שאר הימים, ובו מנוחה מכל, ושמחת כל. ושקול שבת כנגד התורה כלה, ומי ששומר שבת, כאילו שמר התורה כלה."],[7,"וקראת לשבת ענג:","היינו ענג כל, ענג של הנפש והגוף, ענג של העליונים והתחתונים. \u0003וקראת לשבת,\u0004 שואל, מהו וקראת. ומשיב, שפירשו, שיזמין אותו. כש\"א מקראי קדש, שפירושו מוזמנים מן הקדש, כמו שמזמנים ארח לביתו. ועל זה, וקראת לשבת ענג, שיזמין אותה כמו שמזמינים ארח: בשלחן הערוך, בבית מסודר כראוי, באכילה ושתיה כראוי, יותר מבכל שאר הימים. \u0003וקראת לשבת,\u0004 היינו מבעוד יום, שיוסיף מחול על הקדש. \u0003לקדוש ה' מכובד,\u0004 זהו יום הכפורים. והם שנים שהם אחד, כי יום הכפורים ושבת הם אחד. וע\"כ נאמר אחריהם, וכבדתו מעשות דרכיך, דהיינו בלשון יחיד. כמו שהעמדנו."]],[[0,"","כְּמוֹ זֶה, וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם, וְאַחַר כָּךְ חָזְרָה הַשְּׁכִינָה לַאֲחוֹרֵי יִשְׂרָאֵל, שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים וְגוֹ'. מִשּׁוּם כָּךְ דִּמִּיתִיךְ רַעְיָתִי."],[1,"","וּפָסוּק זֶה הֲרֵי פֵּרְשׁוּהוּ, שֶׁהִקְרִיב אֶת כָּל חֵילוֹתָיו וּמַרְכְּבוֹתָיו לַעֲרֹךְ קְרָב. וְעוֹד וּפַרְעֹה הִקְרִיב, רַבִּי יוֹסֵי אָמַר, הֲרֵי נִתְבָּאֵר שֶׁהִקְרִיב אוֹתָם לִתְשׁוּבָה. וּפַרְעֹה הִקְרִיב."],[2,"","כָּתוּב (ישעיה כו) ה' בַּצַּר פְּקָדוּךְ צָקוּן לַחַשׁ וְגוֹ'. בַּצַּר פְּקָדוּךְ - לֹא פוֹקְדִים יִשְׂרָאֵל אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁעַת מְנוּחָה, אֶלָּא בְּשָׁעָה שֶׁמְּצִיקִים לָהֶם, וְאָז כֻּלָּם פּוֹקְדִים אוֹתוֹ. צָקוּן לַחַשׁ - וְכֻלָּם מִתְפַּלְלִים בִּתְפִלּוֹת וּבְבַקָּשׁוֹת, וּמְרִיקִים לְפָנָיו תְּפִלּוֹת. אֵימָתַי? מוּסָרְךְ לָמוֹ. בְּשָׁעָה שֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא בִּרְצוּעָתוֹ, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד עֲלֵיהֶם בְּרַחֲמִים, וְאוֹתוֹ הַקּוֹל שֶׁלָּהֶם נוֹחַ לְפָנָיו כְּדֵי לְהִפָּרַע מִשּׂוֹנְאֵיהֶם, וּמִתְמַלֵּא עֲלֵיהֶם בְּרַחֲמִים."],[3,"","כְּמוֹ שֶׁפֵּרַשְׁנוּ, מָשָׁל לְיוֹנָה עִם הַנֵּץ וְכוּ', כָּךְ יִשְׂרָאֵל הָיוּ קְרֵבִים לַיָּם, וְהָיוּ רוֹאִים אֶת הַיָּם לִפְנֵיהֶם הוֹלֵךְ וְסוֹעֵר וְגַלָּיו עוֹלִים לְמַעְלָה, הָיוּ פּוֹחֲדִים. זָקְפוּ עֵינֵיהֶם וְרָאוּ אֶת פַּרְעֹה וּמַרְכְּבוֹתָיו, וַאֲבָנִים, חִצִּים וּבַלִּיסְטְרָאוֹת, וְאָז וַיִּירְאוּ מְאֹד. מֶה עָשׂוּ? וַיִּצְעֲקוּ בְנֵי יִשְׂרָאֵל. מִי גָרַם אֶת זֶה שֶׁקָּרְבוּ יִשְׂרָאֵל לַאֲבִיהֶם שֶׁל מַעְלָה? פַּרְעֹה. זֶהוּ שֶׁכָּתוּב וּפַרְעֹה הִקְרִיב, וַהֲרֵי זֶה נִתְבָּאֵר."],[4,"","וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ אֶת יְשׁוּעַת ה'. אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי רוֹעֶה כְּמוֹ מֹשֶׁה הָלַךְ בְּתוֹכָם. כָּתוּב (שם סג) וַיִּזְכֹּר יְמֵי עוֹלָם מֹשֶׁה עַמּוֹ. וַיִּזְכֹּר יְמֵי עוֹלָם - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. מֹשֶׁה עַמּוֹ - (מכאן למדנו) שֶׁמֹּשֶׁה הָיָה שָׁקוּל כְּכָל יִשְׂרָאֵל. וְלָמַדְנוּ מִזֶּה כִּי רוֹעֵה הָעָם הוּא מַמָּשׁ הָעָם כֻּלּוֹ. אִם הוּא זוֹכֶה - כָּל הָעָם זוֹכִים, וְאִם אֵינוֹ זוֹכֶה - כָּל הָעָם לֹא זוֹכִים וְנֶעֱנָשִׁים בִּגְלָלוֹ, וַהֲרֵי פֵּרְשׁוּהָ."],[5,"","הִתְיַצְבוּ וּרְאוּ - אֵין לָכֶם לַעֲרֹךְ קְרָב, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא יַעֲרֹךְ קְרָב בִּשְׁבִילְכֶם, כְּמוֹ שֶׁנֶּאֱמַר ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. בֹּא רְאֵה, בְּאוֹתוֹ לַיְלָה כִּנֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַפָּמַלְיָא שֶׁלּוֹ וְדָן אֶת דִּינֵי יִשְׂרָאֵל, וְאִלְמָלֵא שֶׁהִקְדִּימוּ הָאָבוֹת עַל יִשְׂרָאֵל, לֹא הָיוּ נִצּוֹלִים מִן הַדִּין. רַבִּי יְהוּדָה אָמַר, זְכוּת יַעֲקֹב הֵגֵנָּה עַל יִשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב (תהלים קכד) לוּלֵי ה' שֶׁהָיָה לָנוּ יֹאמַר נָא יִשְׂרָאֵל, יִשְׂרָאֵל סָבָא."],[6,"","ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. רַבִּי אַבָּא פָּתַח, (ישעיהנח) אִם תָּשִׁיב מִשַּׁבָּת רַגְלֶךְ עֲשׂוֹת חֲפָצֶךְ בְּיוֹם קָדְשִׁי. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם לְהִדָּבֵק בָּהֶם מִכָּל שְׁאָר עַמֵּי הָעוֹלָם, וּמִתּוֹךְ אַהֲבָתָם קֵרַב אוֹתָם אֵלָיו, וְנָתַן לָהֶם תּוֹרָה, וְנָתַן לָהֶם שַׁבָּת שֶׁהִיא קֹדֶשׁ מִכָּל שְׁאָר הַיָּמִים, וּמְנוּחָה מֵהַכֹּל, וְחֶדְוָה שֶׁל הַכֹּל, וּשְׁקוּלָה שַׁבָּת כְּנֶגֶד כָּל הַתּוֹרָה, וּמִי שֶׁשּׁוֹמֵר שַׁבָּת כְּאִלּוּ שָׁמַר אֶת כָּל הַתּוֹרָה."],[7,"","וְקָרָאתָ לַשַּׁבָּת עֹנֶג - עִנּוּג שֶׁל הַכֹּל, עִנּוּג הַנֶּפֶשׁ וְהַגּוּף, עִנּוּג לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. וְקָרָאתָ לַשַּׁבָּת, מַה זֶּה וְקָרָאתָ? שֶׁיַּזְמִין אוֹתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כג) מִקְרָאֵי קֹדֶשׁ, כְּלוֹמַר מְזֻמָּנִים, כְּמוֹ מִי שֶׁמַּזְמִין אוֹרֵחַ לְבֵיתוֹ. וְעַל זֶה וְקָרָאתָ לַשַּׁבָּת עֹנֶג, שֶׁיַּזְמִין אוֹתָהּ כְּמוֹ שֶׁמַּזְמִינִים אוֹרֵחַ, בְּשֻׁלְחָן מְתֻקָּן וּבְבַיִת מְתֻקָּן כָּרָאוּי בְּמַאֲכָל וּבְמִשְׁתֶּה כָּרָאוּי יוֹתֵר עַל שְׁאָר הַיָּמִים. וְקָרָאתָ לַשַּׁבָּת עֹנֶג - מִבְּעוֹד יוֹם. לִקְדוֹשׁ ה' מְכֻבָּד - זֶה יוֹם הַכִּפּוּרִים, שְׁנַיִם שֶׁהֵם אֶחָד. וְכִבַּדְתּוֹ מֵעֲשׂוֹת דְּרָכֶיךְ - כְּמוֹ שֶׁבֵּאַרְנוּ."]]],[["מִמְּצוֹא חֶפְצְךָ וְדַבֵּר דָּבָר, וְהָא אִתְּמַר, בְּגִין דְּהַהִיא מִלָּה סַלְּקָא, וְאִתְּעַר מִלָּה דְּחוֹל לְעֵילָּא. מַאן דִּמְזַמִּין אוּשְׁפִּיזָא, בֵּיהּ בָּעֵי לְאִשְׁתַּדְּלָא, וְלָא בָּאָחֳרָא.","תָּא חֲזִיִ הַהוּא מִלָּה דְּנָפִיק מִפּוּמֵיהּ דְּבַר נָשׁ, סַלְּקָא וְאִתְּעַר אִתְעָרוּתָא לְעֵילָּא, אִי לְטָב, אִי לְבִישׁ. וּמַאן דְּיָתִיב בְּעִנּוּגָא דְּשַׁבְּתָא, אָסִיר לֵיהּ לְאִתְּעָרָא מִלָּה (מ\"ג ב') דְּחוֹל, דְּהָא פָּגִים פְּגִימוּ בְּיוֹמָא קַדִּישָׁא. מַאן דְּיָתִיב בְּהִילּוּלָא דְּמַלְכָּא, לָא יִתְחָזֵי לְמִשְׁבַּק לְמַלְכָּא, וְיִתְעַסֵּק בְּאַחֲרָא.","וּבְכָל יוֹמָא בָּעֵי לְאַחֲזָאָה עוֹבָדָא, וּלְאִתְעֲרָא אַתְעָרוּתָא מִמָּה דְּאִצְטְרִיךְ. וּבְשַׁבָּת, בְּמִלֵּי דִּשְׁמַיָּא, וּבִקְדוּשָּׁה דְּיוֹמָא בָּעֵי לְאִתְּעָרָא, וְלָא בְּמִלָּה אַחֲרָא.","תָּא חֲזֵי, הָכָא כַּד אִתְקְרִיב פַּרְעֹה לְאַגָּחָא קְרָבָא בְּהוּ בְּיִשְׂרָאֵל, בְּהַהִיא זִמְנָא, לָא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּיִתְּעֲרוּן יִשְׂרָאֵל אִתְעָרוּתָא לְתַתָּא כְּלָל, דְּהָא אִתְעָרוּתָא לְעֵילָּא הוּא, דְּהָא אֲבָהָן אַקְדִּימוּ וְאַתְּעֲרוּ אִתְעָרוּתָא דָּא לְעֵילָּא, וּזְכוּתָא דִּלְהוֹן קָאִים קָמֵיהּ, (ואתערו אתערותא דא) וְלָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִשְׂרָאֵל יִתְּעָרוּן לְתַתָּא כְּלָל. (דהא באתרה לעילא הוה) הֲדָא הוּא דִּכְתִּיב יְיָ' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. תַּחֲרִישׁוּן וַדַּאי, וְלָא תִּתְעֲרוּן מִלָּה, דְּלָא אִצְטְרִיךְ לְכוּ, וְהָכָא אִתְכְּלִיל שְׁמָא קַדִּישָׁא בְּאַתְוָון רְשִׁימָן, וְהָא אִתְעֲרוּ בֵּיהּ חַבְרַיָּיא.","רִבִּי יוֹסֵי וְרִבִּי יְהוּדָה הֲווֹ אַזְלֵי בְּאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי יְהוּדָה, וַדַּאי תָּנִּינָא, יְיָ', בְּכָל אֲתָר רַחֲמֵי, וְאַף עַל גַּב דְּאַגָּח קְרָבָא, וְעָבִיד דִּינָא, הַהוּא דִּינָא בִּרְחִימוּתָא הוּא. וְהָכָא חֲמֵינָא, דִּכְתִּיב יְיָ' יִלָּחֵם לָכֶם, וְלָא אִתְחָזֵי בְּהַהוּא דִּינָא רַחֲמֵי כְּלָל, דְּהָא כְּתִיב לא נִשְׁאַר בָּהֶם עַד אֶחָד.","אָמַר לֵיהּ, מִלָּה דָּא שְׁמַעְנָא מֵרִבִּי שִׁמְעוֹן דְּאָמַר, דְּאֲפִילּוּ הָכָא דִּינָא בְּרַחֲמֵי הֲוָה, דְּחָפָא עָלֵיהוֹן יַמָּא וּמִיתוּ, וּלְבָתַר אַפִּיק לוֹן יַמָּא, וְקוּדְשָׁא בְּרִיךְ הוּא בָּעָא בִּיקָרֵיהוֹן, וְאִתְקְבָרוּ בְּאַרְעָא, וְלָא בָּעָאת אַרְעָא לְקַבְּלָא לוֹן, עַד דְּאוֹשִׁיט לָהּ קוּדְשָׁא בְּרִיךְ הוּא יְמִינֵיהּ, וְקַבִּילַת לוֹן, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:י״ב) נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ. וּבְגִין דָּא, (הוה) הַאי דִּינָא בְּרַחֲמֵי הֲוָה.","וְעַל דָּא, לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְּעָרוּן יִשְׂרָאֵל מִלָּה בְּעָלְמָא, דְּאִי יִתְעָרוּן יִשְׂרָאֵל מִלָּה, לָא יִתְעָרוּן שְׁמָא דְּרַחֲמֵי, וְלָא יִתְעֲבִיד דִּינָא בְּרַחֲמֵי, הֲדָא הוּא דִּכְתִּיב יְיָ' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן, דְּלָא תִּתְעֲרוּן מִידִי. דְּהָא שְׁמָא דְּרַחֲמֵי בָּעֵי לְאִתְּעָרָא עָלַיְיהוּ, לְמֶעְבַּד דִּינָא בְּרַחֲמֵי. וְעַל דָּא בָּעֵי, דְּלָא תַּעַבְדוּן פְּגִימוּ, וְתִתְעֲרוּן מִלָּה אַחֲרָא.","אָמַר לֵיהּ, וְהָא כְּתִיב, (זכריה י״ד:ג׳) וְיָצָא יְיָ' וְנִלְחַם בַּגּוֹיִם הָהֵם. אִי הָכִי דָּא דִּינָא בְּרַחֲמֵי הֲוָה. אָמַר לֵיהּ, הָכִי הֲוָה וַדַּאי, דִּינָא הוּא בְּרַחֲמֵי, דְּמוֹתָא דִּלְהוֹן לָא אִשְׁתְּכַח כְּמוֹתָנָא דִּשְׁאַר בְּנֵי עָלְמָא, אֶלָּא חָס עָלַיְיהוּ קוּדְשָׁא בְּרִיךְ הוּא, דְּלָא יְהוֹן כְּמוֹתָנָא דִּשְׁאַר בְּנֵי עָלְמָא, דְּקָטִילוּ לוֹן, אֶלָּא בְּנַחַת בְּלא צַעֲרָא, הָא דִּינָא בְּרַחֲמֵי אִיהוּ.","וּבְכָל אֲתָר, שְׁמָא דָּא, דִּינָא בְּרַחֲמֵי אִיהוּ, בַּר אֲתָר חַד, דִּכְתִּיב, (ישעיהו מ״ב:י״ג) יְיָ' כַּגִבּוֹר יֵצֵא וְגוֹ'. וְכִי כַּגִבּוֹר וְלֹא גִּבּוֹר. אֶלָּא יְשַׁנֵּי לְבוּשׁוֹי, וְיִלְבַּשׁ לְבוּשִׁין אַחֲרָנִין. כְּאִישׁ מִלְחָמוֹת, יְשַׁנֵּי זִינֵיהּ.","וְעִם כָּל דָּא, דִּינָא הוּא יַתִּיר, אֲבָל רַחֲמֵי בֵּיהּ, כְּמָה דִּכְתִּיב, כַּגִבּוֹר, וְלֹא גִּבּוֹר. כְּאִישׁ מִלְחָמוֹת, וְלֹא אִישׁ מִלְחָמוֹת. דְּוַדַּאי אַף עַל גַּב דְּעָבִיד דִּינָא, חָס עַל עוֹבָדוֹי, וְעַל דָּא, יְיָ' יִלָּחֵם לָכֶם וַדַּאי וְאַתֶּם תַּחֲרִישׁוּן. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרִיר לוֹן לְחוּלָקֵיהּ וְאַחֲסָנְתֵּיהּ, דִּכְתִּיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.","(שמות י״ד:ט״ו) וַיֹּאמֶר (קע\"ח ע\"ב) יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. מִלָּה דָּא הָא אוּקְמוּהָ בְּסִפְרָא דִּצְנִיעוּתָא, וְתַמָּן הוּא רָזָא דִּילֵיהּ, וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה. ר' יְהוּדָה פָּתַח וְאָמַר, (יונה ב׳:ב׳) וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ' אֱלֹהָיו מִמְּעֵי הַדָּגָה, מַה כְּתִיב לְעֵילָּא, וַיְמַן יְיָ' דָּג גָּדוֹל. וַיְמַן: כְּמָה דְאַתְּ אָמֵר (דניאל א׳:ה׳) וַיְמַן לָהֶם הַמֶּלֶךְ דְּבַר יוֹם בְּיוֹמוֹ. אֲשֶׁר מִנָּהּ אֶת מַאֲכַלְכֶם."],[[0,"ממצוא חפצך ודבר דבר:","והוא נתבאר, שלא יהיה דיבורך של שבת כדיבורך של חול. משום שמלה ההוא של חול שמדברים בשבת, עולה ומעוררת מלה של חול למעלה. ונפגם השבת. מי שמזמין אורח, בו הוא צריך להשתדל, ולא באחר."],[1,"תא חזי ההוא וכו':","בוא וראה, מלה ההיא היוצאת מפי האדם, עולה ומעוררת התעוררות של מעלה, אם לטוב אם לרע. ומי שיושב בתענוג שבת אסור לו לעורר מלה של חול. כי פוגם פגם ביום הקדוש. מי שיושב בשמחת המלך אינו ראוי שיעזוב את המלך ויעסוק באחר."],[2,"ובכל יומא בעי וכו':","ובכל יום, צריכים להראות מעשה ולעורר התעוררות של מטה ממה שצריך לעורר. אבל בשבת, רק בדברי השם ובקדושת היום צריכים להתעורר ולא בדבר אחר. כי בשבת אין צריכים אל התעוררות מלמטה."],[3,"תא חזי הכא וכו':","בוא וראה כאן, כשקרב פרעה לעשות מלחמה עם ישראל, בעת ההוא לא רצה הקב\"ה שיעוררו ישראל התעוררות מלמטה כלל, כי התעוררות מלמעלה היה, כי האבות הקדימו ועוררו התעוררות זה מלמעלה, וזכותם עמד לפניו, ולא רצה הקב\"ה שישראל יתעוררו למטה כלל. ז\"ש ה' ילחם לכם ואתם תחרישון. תחרישון ודאי, ולא תעוררו דבר שלא צריך לכם. והטעם מובא להלן (אות ע\"ח) וכאן נכלל השם הקדוש באותיות רשומות הוי\"ה, שהוא רחמים, שנאמר הויה ילחם לכם. ואע\"פ שהוי\"ה הוא רחמים והמלחמה הוא דין. וכבר העירו בזה החברים. כמו שאומר לפנינו."],[4,"ר' יוסי ור' יהודה וכו':","ר' יוסי ור' יהודה היו הולכים בדרך, א\"ר יוסי לר' יהודה ודאי למדנו, שהוי\"ה, בכל מקום הוא רחמים, ואע\"פ שעושה מלחמות ועושה דין, דין ההוא הוא ברחמים, וכאן ראינו, שכתוב, הויה ילחם לכם, ולא נראה בדין ההוא רהמים כלל, שהרי כתוב, לא נשאר מהם עד אחד."],[5,"א\"ל מלה דא וכו':","אמר לו, דבר זה שמעתי מרבי שמעון, שאמר, שאפילו כאן היה דין ברחמים, כי כסה עליהם הים ומתו, ואח\"כ הוציאם הים, והקב\"ה רצה בכבודם ונקברו בארץ, ולא רצתה הארץ לקבלם עד שהושיט לה הקב\"ה ימינו, וקבלה אותם. ז\"ש, נטית ימינך תבלעמו ארץ. ומשום זה, היה דין הזה ברחמים."],[6,"וע\"ד לא בעא וכו':","ועל כן, לא רצה הקב\"ה שיעוררו ישראל דבר בעולם, מלמטה. כי אם היו מעוררים ישראל דבר מלמטה, לא היה מתעורר שם הרחמים, ולא נעשה הדין ברחמים. ז\"ש ה' ילחם לכם ואתם תחרישון. שלא תעוררו כלום, כי השם של רחמים צריך להתעורר עליהם, כדי לעשות הדין ברחמים, וע\"כ צריך שלא תעשו פגם ותעוררו דבר אחר. דהיינו דין בלי רחמים. כי התעוררות שלמטה, היה מפעיל רק דין בלבד."],[7,"א\"ל והא כתיב וכו':","אמר לו והרי כתוב, ויצא הויה ונלחם בגוים ההם, וכי דין הזה ברחמים היה. א\"ל כן היה ודאי, הדין הוא ברחמים, כי המיתה שלהם לא היתה כמיתת שאר בני העולם, אלא ריחם עליהם הקב\"ה, שלא יהיו כמיתת שאר בני העולם, שהרגו אותם רק בנחת בלי צער. דהיינו המק בשרו והוא עומד על רגליו. (זכריה י\"ד) הרי שהדין היה ברחמים."],[8,"ובכל אתר שמא וכו':","ובכל מקום, שם הזה הוא דין ברחמים, חוץ ממקום אחד, שכתוב, הויה כגבור יצא וגו', שואל, וכי כגבור הוא ה' ולא גבור ממש. ואומר, אלא שישנה את לבושיו וילבש לבושים אחרים. דהיינו שישנה מדת הרחמים שלו וילבש לבושי דין. כאיש מלחמות, ישנה כלי זיין שלו. מרחמים לדין. הרי, שבמקום הזה נשתנה הרחמים להיות דין."],[9,"ועם כל דא וכו':","ועם כל זה, רק הדין הוא כאן יותר מרחמים, אבל רחמים יש בו, כמו שכתוב, כגבור, ולא גבור ממש שכולו דין, כאיש מלחמות, ולא איש מלחמות ממש שכולו דין. כי ודאי אע\"פ שעושה דין הוא מרחם על מעשיו. וע\"כ ה' ילחם לכם ודאי, ואתם תחרישון. כדי שלא תעוררו דין בלבד, כנ\"ל. אשרי חלקם של ישראל, שהקב\"ה בחר אותם לחלקו ונחלתו, שכתוב, כי חלק ה' עמו יעקב חבל נחלתו."],[10,"ויאמר ה' אל משה מה תצעק אלי:","דבר זה בארוהו בספרא דצנעותא, (תרומה קע\"ח ע\"ב ד\"י) ושם הוא סוד שלו. ויאמר ה' אל משה וגו'. ר' יהודה פתח ואמר. ויתפלל יונה אל ה' אלהיו ממעי הדגה. מה כתוב למעלה וימן ה' דג גדול. \u0003וימן,\u0004 פירושו כמו שאתה אומר \u0003וימן\u0004 להם המלך דבר יום ביומו. וכן אשר \u0003מנה\u0004 את מאכלכם, שהוא לשון נתינת מנה."]],[[0,"","מִמְּצוֹא חֶפְצְךְ וְדַבֵּר דָּבָר, וַהֲרֵי נִתְבָּאֵר, מִשּׁוּם שֶׁאוֹתוֹ דָּבָר עוֹלֶה וּמְעוֹרֵר דִּבּוּר שֶׁל חֹל לְמַעְלָה. מִי שֶׁמַּזְמִין אוֹרֵחַ, צָרִיךְ לְהִשְׁתַּדֵּל בּוֹ וְלֹא בְּאַחֵר."],[1,"","בֹּא רְאֵה, אוֹתוֹ הַדִּבּוּר שֶׁיּוֹצֵא מִפִּי הָאָדָם, עוֹלֶה וּמְעוֹרֵר הִתְעוֹרְרוּת עֶלְיוֹנָה, אִם לְטוֹב אִם לְרַע. וּמִי שֶׁיּוֹשֵׁב בְּעֹנֶג שַׁבָּת, אָסוּר לוֹ לְעוֹרֵר דִּבּוּר שֶׁל חֹל, שֶׁהֲרֵי הוּא פּוֹגֵם פְּגָם בַּיּוֹם הַקָּדוֹשׁ. מִי שֶׁיּוֹשֵׁב בְּהִלּוּלַת הַמֶּלֶךְ, לֹא רָאוּי שֶׁיַּעֲזֹב אֶת הַמֶּלֶךְ וְיִתְעַסֵּק בְּאַחֵר."],[2,"","וּבְכָל יוֹם צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה וּלְעוֹרֵר הִתְעוֹרְרוּת מִמַּה שֶּׁצָּרִיךְ, וּבְשַׁבָּת בְּדִבְרֵי שָׁמַיִם וּבִקְדֻשַּׁת הַיּוֹם צָרִיךְ לְהִתְעוֹרֵר, וְלֹא בְּדָבָר אַחֵר."],[3,"","בֹּא רְאֵה, כָּאן כְּשֶׁקָּרַב פַּרְעֹה לַעֲרֹךְ קְרָב עִם יִשְׂרָאֵל, בְּאוֹתוֹ זְמַן לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיְּעוֹרְרוּ יִשְׂרָאֵל הִתְעוֹרְרוּת לְמַטָּה כְּלָל, שֶׁהֲרֵי הַהִתְעוֹרְרוּת הִיא לְמַעְלָה, שֶׁהֲרֵי הָאָבוֹת הִקְדִּימוּ הִתְעוֹרְרוּת זֹאת לְמַעְלָה, וּזְכוּתָם עוֹמֶדֶת לְפָנָיו, (ועוררו התעוררות זו) וְלֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּשְׂרָאֵל יִתְעוֹרְרוּ לְמַטָּה כְּלָל. (שהרי במקום של מעלה היה) זֶהוּ שֶׁכָּתוּב ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִשׁוּן. וַדַּאי תַּחֲרִישׁוּן וְלֹא תְעוֹרְרוּ דָבָר, שֶׁלֹּא צָרִיךְ לָכֶם. וְכָאן נִכְלָל הַשֵּׁם הַקָּדוֹשׁ בְּאוֹתִיּוֹת רְשׁוּמוֹת, וַהֲרֵי הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים."],[4,"","רַבִּי יוֹסֵי וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי יְהוּדָה, וַדַּאי שָׁנִינוּ, ה' בְּכָל מָקוֹם זֶה רַחֲמִים, וְאַף עַל גַּב שֶׁעוֹרֵךְ קְרָב וְעוֹשֶׂה דִין, אוֹתוֹ דִין הוּא בְּאַהֲבָה. וְכָךְ רָאִינוּ, שֶׁכָּתוּב ה' יִלָּחֵם לָכֶם, וְלֹא נִרְאָה בְּאוֹתוֹ דִין רַחֲמִים כְּלָל, שֶׁהֲרֵי כָּתוּב לֹא נִשְׁאַר בָּהֶם עַד אֶחָד."],[5,"","אָמַר לוֹ, דָּבָר זֶה שָׁמַעְתִּי מֵרַבִּי שִׁמְעוֹן שֶׁאָמַר, שֶׁאֲפִלּוּ כָּאן הָיָה הַדִּין בְּרַחֲמִים, שֶׁהַיָּם כִּסָּה עֲלֵיהֶם וּמֵתוּ, וְאַחַר כָּךְ הוֹצִיא אוֹתָם הַיָּם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בִּכְבוֹדָם וְנִקְבְּרוּ בָּאָרֶץ, וְלֹא רָצְתָה הָאָרֶץ לְקַבֵּל אוֹתָם, עַד שֶׁהוֹשִׁיט לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְמִינוֹ, וְקִבְּלָה אוֹתָם. זֶהוּ שֶׁכָּתוּב נָטִיתָ יְמִינְךְ תִּבְלָעֵמוֹ אָרֶץ, וְלָכֵן (היה) זֶה הַדִּין בְּרַחֲמִים הָיָה."],[6,"","וְלָכֵן לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיְּעוֹרְרוּ יִשְׂרָאֵל דָּבָר בָּעוֹלָם, שֶׁאִם יְעוֹרְרוּ יִשְׂרָאֵל דָּבָר, לֹא יְעוֹרְרוּ אֶת שֵׁם הָרַחֲמִים, וְלֹא יַעֲשֶׂה דִּין בְּרַחֲמִים. זֶהוּ שֶׁכָּתוּב ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִשׁוּן, שֶׁלֹּא תְעוֹרְרוּ דָבָר. שֶׁהֲרֵי שֵׁם הָרַחֲמִים צָרִיךְ לְעוֹרֵר עֲלֵיהֶם לַעֲשׂוֹת דִּין בְּרַחֲמִים. וְעַל זֶה בִּקֵּשׁ שֶׁלֹּא תַעֲשׂוּ פְגָם וּתְעוֹרְרוּ דָבָר אַחֵר."],[7,"","אָמַר לוֹ, וַהֲרֵי כָּתוּב (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם. אִם כָּךְ, זֶה דִּין שֶׁהָיָה בְּרַחֲמִים. אָמַר לוֹ, כָּךְ הָיָה וַדַּאי הַדִּין בְּרַחֲמִים, שֶׁמּוֹתָם לֹא נִמְצָא כִּשְׁאָר מוֹת בְּנֵי הָעוֹלָם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם שֶׁלֹּא יִהְיוּ כְּמוֹת שְׁאָר בְּנֵי הָעוֹלָם שֶׁהָרְגוּ אוֹתָם, אֶלָּא בְּנַחַת בְּלֹא צַעַר. זֶהוּ דִּין בְּרַחֲמִים."],[8,"","וּבְכָל מָקוֹם שֵׁם זֶה הוּא דִּין בְּרַחֲמִים, פְּרָט לְמָקוֹם אֶחָד, שֶׁכָּתוּב (ישעיהמב) ה' כַּגִּבּוֹר יֵצֵא וְגוֹ'. וְכִי כַּגִּבּוֹר וְלֹא גִבּוֹר? אֶלָּא יְשַׁנֶּה לְבוּשׁוֹ וְיִלְבַּשׁ לְבוּשִׁים אֲחֵרִים. כְּאִישׁ מִלְחָמוֹת, יְשַׁנֶּה מִינוֹ."],[9,"","וְעִם כָּל זֶה, הַדִּין הוּא יָתֵר, אֲבָל יֵשׁ בּוֹ רַחֲמִים, כַּכָּתוּב כַּגִּבּוֹר, וְלֹא גִבּוֹר. כְּאִישׁ מִלְחָמוֹת, וְלֹא אִישׁ מִלְחָמוֹת. שֶׁוַּדַּאי אַף עַל גַּב שֶׁעוֹשֶׂה דִּין, חָס עַל מַעֲשָׂיו. וְלָכֵן ה' יִלָּחֵם לָכֶם וְאַתֶּם תַּחֲרִישׁוּן. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּחַר בָּהֶם לְחֶלְקוֹ וְלִירֻשָּׁתוֹ, שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ."],[10,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. דָּבָר זֶה נִתְבָּאֵר בְּסִפְרָא דִצְנִיעוּתָא, וְשָׁם הוּא הַסּוֹד שֶׁלּוֹ, וַיֹּאמֶר ה' אֶל מֹשֶׁה. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (יונה א) וַיִּתְפַּלֵּל יוֹנָה אֶל ה' אֱלֹהָיו מִמְּעֵי הַדָּגָה. מַה כָּתוּב לְמַעְלָה? וַיְמַן ה' דָּג גָּדוֹל. וַיְמַן - כְּמוֹ שֶׁנֶּאֱמַר (דניאל א) וַיְמַן לָהֶם הַמֶּלֶךְ דְּבַר יוֹם בְּיוֹמוֹ. אֲשֶׁר מִנָּה אֶת מַאֲכַלְכֶם."]]],[["אֲבָל הַאי קְרָא הָכִי מִבָּעֵי לֵיהּ, וַיְמַן יְיָ' אֶת יוֹנָה לַדָּג, דְּהוּא מָנָה הוּא דִּמְשַׁדֵּר לֵיהּ. אֶלָּא וַדַּאי, הַהוּא דָּג הוּא הֲוָה מָנָה לְיוֹנָה, לְנַטְרָא לֵיהּ מִן שְׁאַר נוּנִי יַמָּא, וְיֶהוֵי גָּנִיז בְּגַוֵּיהּ. וְכֵיוָן דְּאַעֲלֵיהּ בְּגַוֵּיהּ, חָמָא יוֹנָה בְּמֵעוֹי, פּוּתְיָא דַּאֲתָר יַמָּא (נ\"א פותיא דאתר דמעוי) כְּמוֹ הֵיכְלָא רַבְרְבָא, וּתְרֵין עֵינוֹי דְּהַהוּא נוּנָא, דְּנָהֲרִין כְּשִׁמְשָׁא, וְאֶבֶן טָבָא הֲוָה בְּמֵעוֹי, דְּנָהִיר לֵיהּ, וַהֲוָה חָמֵי כָּל מַה דִּי בְּיַמָּא וּבִתְהוֹמוֹי.","וְאִי תֵּימָא, אִי הָכִי, מַאי דִּכְתִּיב, (יונה ב׳:ג׳) קָרָאתִי מִצָּרָה לִי, הָא לָא אִתְחָזֵי, דְּכָל הַאי רְוָוחָא הֲוָה לֵיהּ. אֶלָּא וַדַּאי, כֵּיוָן דְּאַחְמֵי לֵיהּ הַהוּא נוּנָא, כָּל מַה דִּי בְּיַמָּא וּבִתְהוֹמוֹי, מִית, דְּלָא יָכִיל תְּלַת יוֹמִין לְמִסְבַּל. כְּדֵין עָקַת לֵיהּ לְיוֹנָה.","דְּאָמַר רִבִּי אֶלְעָזָר, כֵּיוָן דְּחָמָא יוֹנָה כָּל הַהוּא רְוָוחָא, הֲוָה חַדֵּי. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּמַה תִּבְעֵי יַתִּיר, לְהָא אֲעִילְנָא לָךְ הָכָא. מָה עֲבַד, קָטַל לְהַהוּא נוּנָא וּמִית, וְכָל שְׁאַר נוּנֵי יַמָּא, הֲווֹ סַחֲרֵי סַחֲרָנִיהּ דְּהַהוּא נוּנָא, דָּא נָשִׁיךְ לֵיהּ מֵהַאי גִּיסָא, וְדָא נָשִׁיךְ לֵיהּ מֵהַאי גִּיסָא. כְּדֵין חָמָא יוֹנָה גַּרְמוֹי בְּעָקוּ, מִיַּד וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ'.","בְּקַדְמִיתָא דָּג, וְהַשְׁתָּא דָּגָה. כְּמָה דְאַתְּ אָמֵר, (שמות ז׳:כ״א) וְהַדָּגָה אֲשֶׁר בַּיְאוֹר מֵתָה. וּכְדֵין כְּתִיב, קָרָאתִי מִצָּרָה לִי. וְלָא כְּתִיב הָיִיתִי בַּצָּרָה, אוֹ יָשַׁבְתִּי בַּצָּרָה, אֶלָּא קָרָאתִי, מֵהַהוּא עָקוּ דְּעָאקִין לִי נוּנִי יַמָּא. מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי, דְּהָא מִית. וְלָא כְּתִיב מִבֶּטֶן חַי, אוֹ מִבֶּטֶן דָּג, אֶלָּא דְּוַדַּאי הֲוָה מִית.","כֵּיוָן דְּצַלֵּי צְלוֹתֵיהּ, קַבִּיל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַחְיֵיהּ לֵיהּ לְהַאי נוּנָא, וְאַפִּיק לֵיהּ לְיַבֶּשְׁתָּא לְעֵינֵיהוֹן דְּכֹלָּא. דִּכְתִּיב, וַיֹּאמֶר יְיָ' לַדָּג וַיָּקֵא אֶת יוֹנָה. וְחָמוּ כֻּלְּהוּ, עֲבִידְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא.","מַה כְּתִיב, וַיִּתְפַּלֵּל יוֹנָה אֶל יְיָ' אֱלֹהָיו מִמְּעֵי הַדָּגָה, לַאֲתָר דְּהֲוָה קָשִׁיר בֵּיהּ, מַשְׁמַע דִּכְתִּיב יְיָ' אֱלהָיו, וְלָא כְּתִיב וַיִּתְפַּלֵּל אֶל יְיָ' וְלָא יַתִּיר, אֶלָּא יְיָ' אֱלהָיו. אוּף הָכָא, וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. אֵלָי דַּיְיקָא.","דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִּסָעוּ. וְיִּסָעוּ מִלְּאַסְגָּאָה מִלִּין, לָאו עִידָנָא דִּצְלוֹתָא הַשְׁתָּא. וְיִּסָעוּ, וְכִי לְאָן אֲתָר פָּקִד לוֹן דְּיִנְטְלוּן, דְּהָא עַל יַמָּא הֲווֹ שָׁרָאן. אֶלָּא אַהְדָּר לְעֵילָּא, דִּכְתִּיב מַה תִּצְעַק אֵלָי, דְּהָא כֻּלְּהוּ בַּאֲתָר דָּא קַיְימֵי. וְעַל דָּא וַיִּסְעוּ, יִנְטְלוּן מִן דָּא, דְּלָאו עִדָנָא הוּא.","(ס\"א אלא בעתיקא תלייא מלתא) (שמות י״ד:ט״ז) וְאַתָּה הָרֵם אֶת מַטְּךָ וְגוֹ'. הָרֵם אֶת מַטְּךָ, דִּי בֵּיהּ רָשִׁים שְׁמָא קַדִּישָׁא, אַרְכִּין יְדָךְ בְּסִטְרָא דִּשְׁמָא קַדִּישָׁא, וְכֵיוָן דִּיֶחמוּן מַיָּא שְׁמָא קַדִּישָׁא, יָעַרְקוּן מִנֵּיהּ. וּמִקַמֵיה (נ\"א קמיה) וְעַל דָּא, וּנְטֵה אֶת יָדְךָ, לְסִטְרָא חֲדָא, דְּסִטְרִין אַחֲרָנִין דְּהַהוּא מַטֶּה, אִצְטְרִיךְ לָךְ לְמַיִּין (נ\"א ליה למלין) אַחֲרָנִין.","אָמַר רִבִּי אֶלְעָזָר, חֲמֵינָא, דְּזִמְנִין אִתְקְרֵי הַאי מַטֶּה, מַטֵּה הָאֱלהִים, וּלְזִמְנִין אִתְקְרֵי מַטֵּה דְּמֹשֶׁה. אָמַר ר' שִׁמְעוֹן (תרי הוו והכי אוקימנא) בְּסִפְרָא דְּרַב הַמְנוּנָא סָבָא, שַׁפִּיר קָאָמַר, דְּכֻלְּהוּ חַד, בֵּין תֵּימָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבֵין תֵּימָא דְּמֹשֶׁה, וְהַאי מַטֶה, לְאַתְעֲרָא סִטְרָא דִּגְבוּרָה. וְעַל דָּא, וּנְטֵה אֶת יָדְךָ, יְדָא דִּשְׂמָאלָא, דְּאִיהוּ בְּסִטְרָא דִּגְבוּרָה.","אָמַר רִבִּי שִׁמְעוֹן, וַוי לְאִינוּן דְּלָא חָמָאן, וְלָא מִסְתַּכְּלִין בְּאוֹרַיְיתָא, וְאוֹרַיְיתָא קָארֵי קָמַיְיהוּ בְּכָל יוֹמָא, (ס\"א ולא ידעין) וְלָא מַשְׁגִּיחִין. תָּא חֲזֵי, בְּסִטְרָא דִּגְבוּרָה מִתְעָרֵי מַיָּא בְּעָלְמָא, וְנַפְקֵי מַיָּא, וְהַשְׁתָּא בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְנַגְבָא מַיָּא, אֲמַאי וּנְטֵה אֶת יָדְךָ, דְּאִיהוּ שְׂמָאלָא.","אֶלָּא הָרֵם אֶת מַטְּךָ, לְנַגְבָא מַיָּא. וּנְטֵה אֶת יָדְךָ, לְאָתָבָא מַיָּא, לְאַתְעֲרָא סִטְרָא דִּגְבוּרָה, וּלְאָתָבָא מַיָּא עַל מִצְרַיִם. וּבְגִין כַּךְ, תְּרֵין מִלִּין הָכָא, דִּכְתִּיב הָרֵם אֶת מַטְּךָ, וּנְטֵה אֶת יָדְךָ עַל הַיָּם וּבְקָעֵהוּ.","וְהָא תְּהוֹמֵי הֲווֹ. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, עָבֵד נִיסָא גּוֹ נִיסָא, כְּמָה דְאַתְּ אָמֵר (שמות ט״ו:ח׳) קָפְאוּ תְהוֹמוֹת בְּלֶב יָם. וַהֲוָה אַזְלִין בְּיַבֶּשְׁתָּא בְּגוֹ יַמָּא, הֲדָא הוּא דִכְתִיב וַיָּבֹאוּ בְּנֵי יִשְׂרָאֵל בְּתוֹךְ הַיָּם בַּיַּבָּשָׁה."],[[0,"אבל האי קרא וכו':","אבל מקרא זה כך היה צריך לומר, וימן ה' את יונה לדג, שהוא המנה ששלח ה' לדג. ומשיב, אלא ודאי, שדג הזה היה מנה ליונה, לשמור אותו מכל שאר דגי הים, ויהיה גנוז בו. וכיון שהביאו ה' בתוכו, ראה יונה במעיו, את הרוחב של מקום מעיו שהוא כמו היכל גדול, ושתי עיניו של אותו הדג היו מאירות כשמש, ואבן טובה היתה במעיו, שהאירה לו, והיה רואה כל מה שיש בים ובתהומות."],[1,"ואי תימא וכו':","ואם תאמר, אם כן, מהו שכתוב, קראתי מצרה לי, שלא נראה מזה, שהיה לו שם כל הרוחה הזאת. ומשיב. אלא ודאי, שאחר, שהדג הזה הראה לו כל מה שבים ובתהומות, מת. שלא יכול לסובלו שלשה ימים. ואז נעשה צר ליונה."],[2,"דא\"ר אלעזר כיון וכו':","שאמר ר\"א, כיון שראה יונה את כל הרוחה ההיא, היה שמח. אמר הקב\"ה, ומה אתה צריך יותר, וכי לכך הבאתי אותך כאן. מה עשה הקב\"ה, הרג את דג ההוא ומת, וכל שאר דגי הים היו מסבבים סביב הדג, זה נשך אותו מצד ההוא וזה נשך אותו מצד ההוא. אז ראה יונה את עצמו בצרה, מיד ויתפלל יונה אל ה'."],[3,"בקדמיתא דג והשתא וכו':","שואל. מתחילה קראו הכתוב דג ועתה קוראו דגה. ומשיב. שהוא מטעם שכבר מת. כש\"א, והדגה אשר ביאור מתה. ואז כתוב, קראתי מצרה לי, ולא כתוב, הייתי בצרה או ישבתי בצרה, אלא קראתי מתוך הצרה שהצירו לי דגי הים. \u0003מבטן שאול שועתי,\u0004 שמת, ולא כתוב מבטן חי, או מבטן דג, אלא ודאי שהיה מת. וע\"כ נקרא שאול."],[4,"כיון דצלי צלותיה וכו':","כיון שהתפלל תפלתו, קבל אותו הקב\"ה, והחיה לאותו הדג, והוציאו ליבשה לעיני כל, שכתוב, ויאמר ה' לדג ויקא את יונה. וראו כולם מעשה הקב\"ה."],[5,"מה כתיב ויתפלל וגו':","מה כתוב, ויתפלל יונה אל ה' אלקיו וגו', היינו שהתפלל למקום שהיה קשור בו, דהיינו למדת המלכות, זה משמע, משכתוב, ה' אלקיו, ולא כתוב, ויתפלל אל ה' ולא יותר, אלא ה' אלקיו רומז למדה שהיה קשור בה. אף כאן, ויאמר הוי\"ה אל משה מה תצעק אלי, אלי, הוא בדיוק, דהיינו למדתי, שהיא ת\"ת. שבה היה משה קשור. אלא במזלא תלוי הדבר. כמ\"ש להלן (בספרא דצניעותא, תרומה קע\"ח:) כי קריעת ים סוף נמשכה ממזלא, שה\"ס הדיקנא קדישא, כמ\"ש במקומו."],[6,"דבר אל בני ישראל ויסעו:","היינו, שיסעו מלהרבות דברים, כי אין זמן לתפלה עתה. שואל, \u0003ויסעו,\u0004 לאיזה מקום צוה אותם שיסעו, הרי על הים היו שורים. ומשיב, אלא סובב למעלה, שכתוב, מה תצעק אלי, שפירושו לת\"ת כנ\"ל, והרי כולם עמדו במקום במקום הזה, בת\"ת, שכל ישראל היו קשורים בת\"ת, ועל כן אמר \u0003ויסעו\u0004 שישראל יסעו מכאן מת\"ת, ויבואו להתקשר במזלא, שהיא הדיקנא, כנ\"ל. שאין עתה הזמן לת\"ת, אלא במזלא תלוי הדבר. כנ\"ל."],[7,"ואתה הרם את מטך וגו':","הרם את מטך, שבו רשום השם הקדוש, ונטה ידך בצד השם הקדוש, וכיון שיראו המים את השם הקדוש, יברחו ממנו. וע\"כ ונטה את ידך לצד אחד של המטה, כי הצדדים האחרים של המטה, יהיו נחוצים לך לדברים אחרים. דהיינו להכאת הסלע."],[8,"א\"ר אלעזר חמינא וכו':","אר\"א רואה אני שלפעמים נקרא מטה הזה מטה האלקים, ולפעמים נקרא מטה משה. אר\"ש, בספרו של רב המנונא סבא, יפה אומר שכולו אחד, בין שתאמר מטהו של הקב\"ה בין שתאמר מטהו של משה. ומטה הזה הוא לעורר צד הגבורה, ועל כן אוה\"כ, נטה את ידך, שפירושו יד שמאל, שהוא בצד הגבורה."],[9,"אמר ר' שמעון וכו':","אר\"ש, אוי לאלו שאינם רואים ואינם מסתכלים בתורה, והתורה קוראה לפניהם בכל יום ואינם משגיחים. בוא וראה, מצד הגבורה, מתעוררים מים בעולם, ויוצאים מים, ועתה רצה הקב\"ה ליבש המים, למה אוה\"כ, ונטה את ידך שהוא יד שמאל, דהיינו גבורה."],[10,"אלא הרם וכו':","ומשיב, אלא הרם את מטך, הוא ליבש המים. ונטה את ידך, הוא להשיב המים, לעורר צד הגבורה ולהשיב המים על המצרים. ועל כן הם שני דברים כאן, שכתוב, הרם את מטך, ונטה את ידך על הים ובקעהו. זה ליבש המים, וזה להשיב המים על המצרים."],[11,"והא תהומי הוו וכו':","שואל. איך נעשה יבשה בתוך הים, הרי היו שם תהומות. ומשיב. אלא הקב\"ה עשה נס בתוך נס, כש\"א קפאו תהומות בלב ים. והיו הולכים ביבשה תוך הים, ז\"ש ויבואו בני ישראל בתוך הים ביבשה."]],[[0,"","וַיְמַן ה' אֶת יוֹנָה לַדָּג, שֶׁהוּא מָנָה, הוּא שָׁלַח אוֹתוֹ. אֶלָּא וַדַּאי אוֹתוֹ דָג הָיָה מָנָה לְיוֹנָה לִשְׁמֹר אוֹתוֹ מִשְּׁאָר דְּגֵי הַיָּם וְיִהְיֶה גָנוּז בְּתוֹכוֹ. וְכֵיוָן שֶׁהִכְנִיסוֹ לְתוֹכוֹ, רָאָה יוֹנָה בְּמֵעָיו רֹחַב שֶׁל מְקוֹם הַיָּם (רחב של מקום מעיו) כְּמוֹ הֵיכָל גָּדוֹל, וּשְׁנֵי עֵינֵי אוֹתוֹ דָג שֶׁמְּאִירִים כַּשֶּׁמֶשׁ, וְאֶבֶן טוֹבָה הָיְתָה בְּמֵעָיו שֶׁמְּאִירָה לוֹ, וְהָיָה רוֹאֶה כָּל מַה שֶּׁבַּיָּם וּבִתְהוֹמָיו."],[1,"","וְאִם תֹּאמַר, אִם כָּךְ, מַה שֶּׁכָּתוּב קָרָאתִי מִצָּרָה לִי, הֲרֵי לֹא נִרְאֶה שֶׁכָּל הָרְוָחָה הַזּוֹ הָיְתָה לוֹ? אֶלָּא וַדַּאי, כֵּיוָן שֶׁהֶרְאָה לוֹ אוֹתוֹ הַדָּג כָּל מַה שֶּׁבַּיָּם וּבִתְהוֹמָיו - מֵת, שֶׁלֹּא יָכֹל שְׁלֹשָׁה יָמִים לִסְבֹּל, וְאָז הָיְתָה לְיוֹנָה מְצוּקָה."],[2,"","שֶׁאָמַר רַבִּי אֶלְעָזָר, כֵּיוָן שֶׁרָאָה יוֹנָה אֶת כָּל אוֹתָהּ רְוָחָה, הָיָה שָׂמֵחַ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמַה תִּרְצֶה יוֹתֵר? וְכִי לָזֶה הִכְנַסְתִּי אוֹתְךְ כָּאן?. מֶה עָשָׂה? הָרַג אֶת אוֹתוֹ דָג וּמֵת, וְכָל שְׁאָר דְּגֵי הַיָּם הָיוּ סְבִיב אוֹתוֹ דָג. זֶה נוֹשֵׁךְ אוֹתוֹ מִצַּד זֶה, וְזֶה נוֹשֵׁךְ אוֹתוֹ מִצַּד זֶה, וְאָז רָאָה יוֹנָה אֶת עַצְמוֹ בְּצָרָה. מִיָּד - וַיִּתְפַּלֵּל יוֹנָה אֶל ה'."],[3,"","בַּתְּחִלָּה דָּג, וְכָעֵת דָּגָה, כַּנֶּאֱמַר וְהַדָּגָה אֲשֶׁר בַּיְאֹר מֵתָה. וְאָז כָּתוּב קָרָאתִי מִצָּרָה לִי, וְלֹא כָתוּב הָיִיתִי בְצָרָה אוֹ יָשַׁבְתִּי בְצָרָה, אֶלָּא קָרָאתִי, מֵאוֹתָהּ צָרָה שֶׁהֵצִיקוּ לִי דְּגֵי הַיָּם. מִבֶּטֶן שְׁאוֹל שִׁוַּעְתִּי, שֶׁהֲרֵי מֵת. וְלֹא כָתוּב מִבֶּטֶן חַי אוֹ מִבֶּטֶן דָּג, אֶלָּא שֶׁהָיָה וַדַּאי מֵת."],[4,"","כֵּיוָן שֶׁהִתְפַּלֵּל תְּפִלָּתוֹ, קִבֵּל אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהֶחֱיָה אֶת הַדָּג הַזֶּה, וְהוֹצִיאוֹ לַיַּבָּשָׁה לְעֵין כֹּל, שֶׁכָּתוּב וַיֹּאמֶר ה' לַדָּג וַיָּקֵא אֶת יוֹנָה. וְכֻלָּם רָאוּ אֶת מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","מַה כָּתוּב? וַיִּתְפַּלֵּל יוֹנָה אֶל ה' אֱלֹהָיו מִמְּעֵי הַדָּגָה, לַמָּקוֹם שֶׁהָיָה קָשׁוּר בּוֹ. מַשְׁמָע שֶׁכָּתוּב ה' אֱלֹהָיו, וְלֹא כָתוּב וַיִתְפַּלֵּל אֶל ה' וְלֹא יוֹתֵר, אֶלָּא ה' אֱלֹהָיו. אַף כָּאן, וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. אֵלַי דַּוְקָא."],[6,"","דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִסָּעוּ. וְיִסָּעוּ מִלְּהַרְבּוֹת בִּדְבָרִים. זֶה לֹא זְמַן תְּפִלָּה כָּעֵת. וְיִסָּעוּ, וְכִי לְאֵיזֶה מָקוֹם צִוָּה אוֹתוֹ שֶׁיִּסְעוּ, שֶׁהֲרֵי עַל הַיָּם הֵם הָיוּ שְׁרוּיִים? אֶלָּא חָזַר לְמַעְלָה, שֶׁכָּתוּב מַה תִּצְעַק אֵלָי, שֶׁהֲרֵי כֻּלָּם בְּמָקוֹם זֶה עוֹמְדִים. וְעַל זֶה וְיִסָּעוּ, יִסְעוּ מִזֶּה, שֶׁזֶּה אֵינוֹ הַזְּמַן (אלא בעתיק תלוי הדבר)."],[7,"","וְאַתָּה הָרֵם אֶת מַטְּךְ וְגוֹ'. הָרֵם אֶת מַטְּךְ, שֶׁבּוֹ רָשׁוּם הַשֵּׁם הַקָּדוֹשׁ. נְטֵה יָדְךְ בַּצַּד שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וְכֵיוָן שֶׁהַמַּיִם יִרְאוּ אֶת הַשֵּׁם הַקָּדוֹשׁ, הֵם יִבְרְחוּ מִמֶּנּוּ וּמִלְּפָנָיו (לפניו). וְעַל זֶה וּנְטֵה אֶת יָדְךְ, לְצַד אֶחָד, שֶׁאֶת הַצְּדָדִים הָאֲחֵרִים שֶׁל אוֹתוֹ הַמַּטֶּה הִצְטָרֵךְ אוֹתוֹ לְמַיִם (לדברים) אֲחֵרִים."],[8,"","אָמַר רַבִּי אֶלְעָזָר, רָאִיתִי שֶׁלִּפְעָמִים הַמַּטֶּה הַזֶּה נִקְרָא מַטֵּה הָאֱלֹהִים, וְלִפְעָמִים נִקְרָא מַטֵּה מֹשֶׁה. אָמַר רַבִּי שִׁמְעוֹן (שנים היו, וכך בארנו) בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, יָפֶה אָמַר, שֶׁכֻּלָּם אֶחָד, בֵּין שֶׁתֹּאמַר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בֵּין שֶׁתֹּאמַר שֶׁל מֹשֶׁה. וְהַמַּטֶּה הַזֶּה, לְעוֹרֵר צַד הַגְּבוּרָה. וְעַל זֶה וּנְטֵה אֶת יָדְךְ, יַד שְׂמֹאל, שֶׁהִיא מִצַּד הַגְּבוּרָה."],[9,"","אָמַר רַבִּי שִׁמְעוֹן, אוֹי לְאוֹתָם שֶׁלֹּא רוֹאִים וְלֹא מִסְתַּכְּלִים בַּתּוֹרָה, וְהַתּוֹרָה קוֹרֵאת לִפְנֵיהֶם בְּכָל יוֹם, (ולאיודעים) וְלֹא מַשְׁגִּיחִים. בֹּא רְאֵה, מִצַּד הַגְּבוּרָה מִתְעוֹרְרִים הַמַּיִם בָּעוֹלָם, וְיוֹצְאִים מַיִם, וְכָעֵת רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַבֵּשׁ אֶת הַמַּיִם, לָמָּה וּנְטֵה אֶת יָדְךְ, שֶׁהוּא שְׂמֹאל?"],[10,"","אֶלָּא הָרֵם אֶת מַטְּךְ לְיַבֵּשׁ אֶת הַמַּיִם, וּנְטֵה אֶת יָדְךְ לְהָשִׁיב אֶת הַמַּיִם, לְעוֹרֵר אֶת צַד הַגְּבוּרָה וּלְהָשִׁיב הַמַּיִם עַל הַמִּצְרִים. וּמִשּׁוּם כָּךְ שְׁנֵי דְבָרִים כָּאן, שֶׁכָּתוּב הָרֵם אֶת מַטְּךְ, וּנְטֵה אֶת יָדְךְ עַל הַיָּם וּבְקָעֵהוּ."],[11,"","וַהֲרֵי הַתְּהוֹמוֹת הָיוּ? אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה נֵס בְּתוֹךְ נֵס, כַּנֶּאֱמַר קָפְאוּ תְהֹמֹת בְּלֶב יָם. וְהָיוּ הוֹלְכִים בַּיַּבָּשָׁה בְּתוֹךְ הַיָּם. זֶהוּ שֶׁכָּתוּב וַיָּבאוּ בְנֵי יִשְׂרָאֵל בְּתוֹךְ הַיָּם בַּיַּבָּשָׁה."]]],[["(שמות י״ד:כ״ה) וַיָּסַר אֶת אוֹפַן מַרְכְּבוֹתָיו. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א׳:ט״ו) וָאֵרֶא הַחַיּוֹת וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ אֵצֶל הַחַיּוֹת. הַאי קְרָא אוּקְמוּהָ וְאִתְּמַר, אֲבָל תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא בְּכוֹלָּא אִתְחָזֵי שֻׁלְטָנוּתָא דִּילֵיהּ, וְשֻׁלְטָנֵיהּ דִּי לָא תַּעְדֵּי לְעָלַם וּלְעָלְמֵי עָלְמִין.","וְעָבִיד שׁוּלְטָנוּתָא בַּאֲבָהָן, נָטַל לְאַבְרָהָם, וְקִיֵּים בֵּיהּ עָלְמָא, דִּכְתִּיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְאוּקְמוּהָ. נָטִיל יִצְחָק, וְשָׁתִיל בֵּיהּ עָלְמָא, דְּאִיהוּ קַיָּים לְעָלְמִין, הֲדָא הוּא דִכְתִיב, (בראשית י״ז:כ״א) וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק. נָטַל יַעֲקֹב, וְאוֹתְבֵיהּ קָמֵיהּ, וְאִשְׁתַּעֲשַׁע בַּהֲדֵיהּ, וְאִתְפָּאַר בֵּיהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","וְתָּא חֲזֵי, יַעֲקֹב אָחִיד בְּאִילָנָא דְּחַיֵּי, דְּלֵית בֵּיהּ מוֹתָא לְעָלְמִין, דְּכָל חַיִּין בְּהַהוּא אִילָנָא אִשְׁתָּכְלָלוּ, וְיָהַב חַיִּין לְכָל אִינּוּן דַּאֲחִידָן בֵּיהּ. וּבְגִין כָּךְ, יַעֲקֹב לָא מִית. וְאֵימָתַי מִית, בְּשַׁעֲתָא דִּכְתִּיב, (בראשית מ״ט:ל״ג) וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה. הַמִּטָּה. כְּמָה דְאַתְּ אָמֵר (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, בְּגִין דִּבְהַאי מִטָּה כְּתִיב, (משלי ה׳:ה׳) רַגְלֶיהָ יוֹרְדוֹת מָוְת, וּבְגִין כָּךְ וַיֶּאֱסוֹף רַגְלָיו אֶל הַמִּטָּה כְּתִיב, כְּדֵין וַיִּגְוַע וַיֵּאָסֶף אֶל עַמָּיו. וְעָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב שְׁלִימוּ דַּאֲבָהָן, הֲדָא הוּא דִכְתִיב, (ישעיהו מ״א:ח׳) יַעֲקֹב אֲשֶׁר בְּחַרְתִּיךָ.","תָּא חֲזֵי, כָּל מַשִׁרְיָין דִּלְעֵילָּא, וְכָל אִינּוּן רְתִיכִין, כֻּלְּהוּ אֲחִידָן אִלֵּין בְּאִלֵּין, דַּרְגִּין בְּדַרְגִּין, אִלֵּין עִלָּאִין וְאִלֵּין תַּתָּאִין. וְחֵיוָותָא קַדִּישָׁא עָלַיְיהוּ, וְכֻלְּהוּ אוֹכְלוֹסִין וּמַשִׁרְיָין, כֻּלְּהוּ נַטְלִין תְּחוֹת יְדָהָא, עַל מֵימְרָהָא נַטְלִין, וְעַל מֵימְרָהָא שָׁרָאן.","וְדָא הוּא חֵיוָתָא, (ס\"א עילא קדישא) דְּכָל שְׁאַר חֵיוָתָא, אֲחִידָן בָּהּ וְאִשְׁתַּלְשָׁלוּ (ס\"א ואשתכללו) בְּגִינָהּ כַּמָּה חֵיוָן לְחֵיוָן (ס\"א אלין סלקין ואלין נחתין) וְאִתְאַחֲדָן דַּרְגִּין בְּדַרְגִּין, וְכֻלְּהוּ עִלָּאִין וְתַתָּאִין אַזְלִין וְשָׁאטִין בְּיַמָּא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר וְגוֹ'.","וְכַד סָלִיק יַמָּא גַּלְגַּלּוֹי, כֻּלְּהוּ אַרְבִּין סַלְּקִין נַחְתִּין, וְזַעְפָּא אִשְׁתְּכַח, וְרוּחָא תַּקִּיפָא אַזְלָא עָלֵיהּ בִּתְקִיפוּ. וְנוּנֵי יַמָּא מִתְבַּדְּרִין לְכָל סְטַר, אִלֵּין לְמִזְרָח, וְאִלֵּין לְמַעֲרָב, אִלֵּין לַצָּפוֹן, וְאִלֵּין לַדָּרוֹם. וְכָל אִינּוּן בְּנִי עָלְמָא, דְּחָמָאן רְשִׁימָא עָלַיְיהוּ, נַטְלִין לוֹן, וּבַלְעִין לוֹן בְּקַפְטִיִרִי עַפְרָא.","וְכָל אַרְבִּין לָא נַטְלִין מֵאַתְרַיְיהוּ, וְלָא סַלְּקִין וְנַחְתִּין, בַּר מֵהַהוּא שַׁעֲתָא, דְּאָתֵי חַד דַּבְּרָא בְּיַמָּא, וְיָדַע לְאַשְׁלְמָא רוּחָא דְּזַעְפָּא דְּיַמָּא, כֵּיוָן דְּסָלִיק דָּא עָלֵיהּ דְּיַמָּא, שָׁכִיךְ מֵרוּגְזָא, וְנַיְיחָא אִשְׁתְּכַח, וּכְדֵין כֻּלְּהוּ אַרְבִּין אַזְלִין בְּאֹרַח מֵישָׁר, וְלָא סָטָאן לִימִינָא וּשְׂמָאלָא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:כ״ו) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. זֶה דַּיְיקָא. וְכָל נוּנֵי יַמָּא מִתְכַּנְּשִׁין לְאַתְרַיְיהוּ. וְכָל אִינּוּן חֵיוָון חַדָּאן עָלָהּ, וְחֵיוָון חַקְלָא עִלָּאָה חַדָּאן, הֲדָא הוּא דִכְתִיב, (איוב מ׳:כ׳) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם.","תָּא חֲזֵי, כְּגַוְונָא דִּלְעֵילָּא, אִית לְתַתָּא. כְּגַוְונָא דִּלְתַתָּא, אִית בְּיַמָּא. כְּגַוְונָא דִּלְעֵילָּא, אִית לְעֵילָּא בְּיַמָּא עִלָּאָה. כְּגַוְונָא דִּלְעֵילָּא אִית לְתַתָּא. כְּגַוְונָא דִּלְתַתָּא, אִית בְּיַמָּא תַּתָּאָה.","גּוּפָא דְּהַהוּא יַמָּא, הָא אִתְעַרְנָא לְחַבְרָנָא, אוֹרְכָא וּפוּתְיָא, רֵישָׁא וּדְרֹעִין וְשַׂעֲרֵי גוּפָא, כֹּלָּא כְּמָה דְּאִצְטְרִיךְ, וְכֹלָּא בִּשְׁמֵיהּ (ויחי רמ\"ה) אִתְקְרֵי. וּכְגַוְונָא דָּא לְתַתָּא לְיַמָּא דִּלְתַתָּא, הָכִי נָמֵי רֵישָׁא דְּיַמָּא, וּדְרוֹעִין דְּיַמָּא, וְגוּפָא דְּיַמָּא.","כְּתִיב (בראשית מ״ט:י״ג) זְבוּלוּן לְחוֹף יַמִים יִשְׁכּוֹן. וְהָא יַמָּא חַד הֲוָה בְּעַדְבֵיהּ אֶלָּא מַאי לְחוֹף יַמִים, וַדַּאי אוּקְמוּהָ חַבְרַיָּיא בְּרָזָא עִלָּאָה. וְיַרְכָתוֹ עַל צִידוֹן, כְּמָה דְאַתְּ אָמֵר (שמות א׳:ה׳) יוֹצְאֵי יֶרֶךְ יַעֲקֹב. זְבוּלוּן שׁוֹקָא דִּימִינָא דְּגוּפָא הֲוָה, וְיַם כִּנֶּרֶת הֲוָה בְּעַדְבֵיהּ, וּמֵהָכָא אִשְׁתְּכַח חִלָּזוֹן לִתְכֶלְתָּא.","תָּא חֲזֵי, כַּמָּה רְתִיכִין עַל רְתִיכִין אִשְׁתְּכָחוּ, וְגַלְגַּלּוֹי דִּרְתִּיכָא רָהֲטִין בִּבְהִילוּ, וְלָא מִתְעַכְּבֵי אִינּוּן סַמְכֵי רְתִיכָא, לְנַטְלָא עֲלֵיהוֹן. וְכֵן כֻּלְּהוּ. (נ\"א והכא שנהגו בכבדות בבהילו) תָּא חֲזֵי, רְתִיכָא דִּי מְמָנָא עַל מִצְרָאֵי, (אי תימא) אוּקְמוּהָ, רְתִיכָא שְׁלֵימָתָא לָא אִשְׁתְּכַח, דְּהָא כְּתִיב וַיָּסַר אֵת אוֹפַן מַרְכְּבוֹתָיו, כַּמָּה רְתִיכִין הֲווֹ, דַּהֲווֹ נַטְלִין עַל חַד סָמִיךְ גַּלְגַּלָּא, דְּאִתְפָּקְדוּ עֲלַיְיהוּ, כֵּיוָן דְּאִתְעֲבָר הַאי מִשּׁוּלְטָנוּתָא דִּילֵיהּ, כֻּלְּהוּ רְתִיכִין אִתְעֲבָרוּ מִשּׁוּלְטָנִיהוֹן, וְלָא נַטְלוּ. כְּדֵין כֻּלְּהוּ לְתַתָּא אִתְעֲבָרוּ מְשּׁוּלְטָנוּתָא, דִּכְתִּיב, (ירמיהו מ״ו:כ״ה) עַל מִצְרַיִם וְעַל פַּרְעֹה וְעַל הַבּוֹטְחִים בוֹ."],[[0,"ויסר את אופן מרכבותיו:","ר' שמעון פתח, וארא החיות והנה אופן אחד בארץ אצל החיות. מקרא זה בארוהו, ולמדנו. אבל בוא וראה, הקב\"ה מראה בכל דבר את הממשלה שלו, וממשלתו לא תסור לעולם ולעולמי עולמים."],[1,"ועביד שולטנותא באבהן וכו':","ועושה ממשלה בהאבות. לקח את אברהם וקיים בו את העולם, שכתוב, אלה תולדות השמים והארץ בהבראם, ובארוהו, אל תקרי בהבראם אלא באברהם, שבו נתקימו שמים וארץ. לקח את יצחק ושתל בו את העולם, שיהיה קיים תמיד. ז\"ש ואת בריתי אקים את יצחק. לקח את יעקב והושיבו לפניו, והשתעשע עמו, והתפאר בו, ז\"ש ישראל אשר בך אתפאר."],[2,"ות\"ח, יעקב אחיד וכו':","ובוא וראה, יעקב אחוז בעץ החיים, שאין בו מות לעולם, שכל החיים נשתכללו באילן הזה, והוא נותן חיים לכל אלו שהם נאחזים בו. ומשום זה, יעקב לא מת. ומתי מת, הוא בשעה שכתוב, ויאסוף רגליו על המטה. \u0003המטה,\u0004 הוא כמו שאתה אומר הנה \u0003מטתו\u0004 שלשלמה, שהיא המלכות, ומשום שבמטה הזו כתוב, רגליה יורדות מות, וע\"כ ויאסוף רגליו אל המטה כתוב, ואז ויגוע ויאסוף אל עמיו. אבל כל עוד שהיה נאחז בעץ החיים, שהוא ז\"א, לא מת. כי אין מיתה אלא מצד המלכות, כמבואר. ועשה הקב\"ה את יעקב לבחיר האבות. זהו שכתוב, יעקב אשר בחרתיך."],[2,"","ביאור הדברים. ותחלה נבאר הכתוב, וארא החיות והנה אופן אחד בארץ אצל החיות, שר\"ש פתח בו, שלכאורה תמוה, איזה יחס יש להכתוב הזה עם הכתוב ויסר את אופן מרכבותיו. ולא עוד אלא שר\"ש אינו מזכירו עוד בכל המשך המאמר. והענין הוא, כי אחר הכתוב הנ\"ל, כתוב, ומראיהם ומעשיהם כאשר יהיה האופן בתוך האופן. והפירוש הוא, כי החיות הם בחג\"ת דז\"א עד החזה, והאופנים הם מחזה ולמטה בנה\"י דז\"א, ששם הנוקבא דז\"א. ובנוקבא דז\"א יש ב' נקודות א' נקודה הממותקת בבינה שהוא רחמים. ב' נקודה דמדת הדין דצמצום א' הבלתי ממותקת. הראשונה נקראת מפתחא, והשניה מנעולא (כנ\"ל בהק' סה\"ז דף מ\"ז ד\"ה גו אינון) ע\"ש. ומצד הנקודה השניה אין המלכות ראויה לאור עליון כי הצמצום רוכבת עליה. וכל המוחין שמקבלת הוא רק בבחינת הנקודה הראשונה הנקראת מפתחא, כמ\"ש שם. ולפיכך נגנזה נקודה השניה בתוך הראשונה, ונקודה הראשונה היא מגולה, והיא שולטת. וע\"י תקון זה המלכות ראויה לקבל מוחין עש\"ה."],[2,"","וזסו\"ה והנה אופן אחד בארץ אצל החיות. כלומר שאע\"פ שיש ב' נקודות במלכות, כמ\"ש להלן ומראיהם ומעשיהם כאשר יהיה האופן בתוך האופן, שאופן דמנעולא גנוזה בתוך אופן דמפתחא, מ\"מ אינה משמש בה רק אופן א', שהוא מפתחא ואופן השני אינו ניכר כלל."],[2,"","וז\"ש ר\"ש פתח, וארא החיות והנה אופן אחד בארץ, ופתח בזה את המקרא, ויסר את אופן מרכבותיו, שבאיזה אופן אמור, היינו באופן דמפתחא, שבתקונו תלוים כל המוחין דמלכות, ומכ\"ש הס\"א המקבלת ממנה, וכשרצה לאבד את המצרים, הסיר את תקון הזה. וז\"ש ויסר את אופן מרכבותיו. ובזה פירש הכתוב בדרך כלל. ואח\"כ הולך ומפרש הדברים בפרטיות."],[2,"","ותחילה מבאר סוד המרכבה העליונה שהיא שורש כל המרכבות, שהם חג\"ת דז\"א והמלכות שמחזה ולמעלה דז\"א. שה\"ס האבות הם המרכבה. וז\"ש \u0003ועביד שולטנותא באבהן,\u0004 דהיינו הבינה, עשתה ממשלה בחג\"ת דז\"א. שהם רגלי המרכבה שלה. וז\"ש \u0003נטל לאברהם וקיים ביה עלמא.\u0004 כי אברהם, ה\"ס קו ימין, שה\"ס החסד דז\"א, שבו מתקיים העולם שהוא המלכות, כי כל עוד שהחכמה שבה אינה מתלבשת בחסד דז\"א אין לה קיום, כנודע. \u0003נטל ליצחק ושתיל ביה עלמא,\u0004 כי יצחק הוא קו שמאל שה\"ס גבורה דז\"א שממנו נבנה המלכות, כי המלכות נבנה מקו שמאל דז\"א, הרי שיצחק שתל אותה ואברהם רק קיים אותה, שהלבישה בחסדים. \u0003נטל יעקב ואותביה קמיה,\u0004 לפניו באמצע, כי יעקב הוא קו האמצעי, ת\"ת דז\"א, המכריע בין ב' הקוין ימין ושמאל ומקיים הארת שניהם. וז\"ש, \u0003ואשתעשע בהדיה ואתפאר ביה.\u0004 כי לולא קו האמצעי לא היה אור בבינה (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת)."],[2,"","ועתה מבאר הנוקבא וההפרש בינה לקו אמצעי, שהוא יעקב, וז\"ש, \u0003יעקב אחיד באילנא דחיי,\u0004 כי הוא אחוז בבינה ששם החיים, והוא נקרא עץ החיים. \u0003ובגין כך יעקב לא מית,\u0004 שאין אחיזה בו לס\"א, לבד כשיתחבר עם הנוקבא, יש אחיזה בו מחמת הנוקבא שנתחברה עמו. וז\"ש, \u0003ואימתי מית בשעתא דכתיב, ויאסוף רגליו אל המטה,\u0004 דהיינו שנתחבר עם המטה שהיא המלכות, ואז מת. \u0003בגין דבהאי מטה כתיב, רגליה יורדות מות.\u0004 כי מפרנסת הס\"א שהם מות. שכל מה שיש לס\"א מקבלים מן המלכות, שהיא הנוקבא דז\"א. ונתבאר בזה ד' רגלי המרכבה העליונה, שהיא בינה, שהם חג\"ת דז\"א, והנוקבא המקבלת מהם. והם נקראים ג\"כ ד' חיות. וד' רגלי המרכבה התחתונה שמחזה ולמטה, הם נהי\"מ, ונקראים אופנים, מחמת האופן בתוך האופן המתוקן בהם. כי כל החלק שלמטה מחזה דז\"א שייכת להנוקבא, המתוקנת באופן."],[3,"ת\"ח כל משריין דלעילא וכו':","בוא וראה, כל המחנות של מעלה, שנמשכות מד' מחנות שכינה, שהם האופנים, וכל המרכבות כולן, אחוזות אלו באלו, מדרגות במדרגות, אלו העליונות ואלו התחתונות, משתלשלות זו מזו ונכללות זו בזו, וחיה קדושה עליהן, שהיא הנוקבא שמחזה ולמעלה דז\"א, ששם ד' חיות כנ\"ל, והנוקבא היא חיה הד', וכל ההמון והמחנות כולן נוסעות תחת ידה, דהיינו רשותה, על פיה תסענה ועל פיה תחנינה. כי כל המרכבות והחיות והאופנים אין להם אלא מה שמקבלים מחיה העליונה הזו."],[4,"ודא הוא חיותא וכו':","וזו היא חיה, שכל שאר החיות נאחזות בה, והשתלשלו ממנה כמה חיות לחיות, כלומר שהרבה חיות נשתלשלו זה מזה, ונכללו מדרגות במדרגות. וכל העליונים והתחתונים הולכים ושטים בים, שהוא הנוקבא, שהעליונים נכללים בה שמשפיעים לה, והתחתונים נכללים בה שמקבלים ממנה. ז\"ש זה הים גדול ורחב ידים וגו'."],[5,"וכד סליק ימא גלגלוי וכו':","וכשהים מעלה גליו, שהם הדינין, כל האניות עולות ויורדות, דהיינו יעלו שמים ירדו תהומות, וסערה נמצאת, ורוח חזק הולך עליו בחזקה. ודגי הים מתפזרים לכל צד, אלו למזרח ואלו למערב, אלו לצפון ואלו לדרום. וכל בני העולם, שדגי הים האלו רואים רשימה עליהם מחמת חטאם, לוקחים אותם ובולעים אותם במערות העפר."],[5,"","פירוש. כשהתחתונים חוטאים מתקלקל בשבילם התקון הנ\"ל של גניזת אופן בתוך האופן, ומתגלה המלכות דמדת הדין, שמצדה אין המלכות שהיא הים ראויה לקבלת אורות, ועל כן \u0003האניות\u0004 שבים, שהם כמו המרכבות שביבשה, עולות ויורדות, וחושבות להשבר. ודגי הים, שהם המלאכים שבמלכות, שהיו מקושרים בד' רוחות, שהם חו\"ג תו\"מ, כיון שנסתלק האור הזה, הותר הקשר הזה של חו\"ג תו\"מ, ומתפזרים כל אחד לצדו שנמשך משם, ובני העולם שקלקלו מעשיהם וגרמו את זה, שמחמת זה מתרשם חטאם בהם, בולעים אותם במערות העפר. דהיינו במלכות דמדת הדין. \u0003עפר\u0004 היא שם המלכות ומדת הדין שנגלה בה מכונה מערה."],[6,"וכל ארבין לא וכו':","וכל האניות אינן זזות ממקומן, ואינן עולות ויורדות, חוץ מאותה שעה שבא מנהיג אחד של הים, וידע להשלים את רוח הסערה של הים, וכיון שעולה זה על הים, הוא נח מזעפו, ומנוחה נמצאת. ואז כל האניות הולכות בדרך הישר, ואינן סרות לימין ולשמאל. ז\"ש שם אניות יהלכון לויתן \u0003זה\u0004 יצרת לשחק בו. \u0003זה\u0004 הוא בדיוק, שה\"ס יסוד דז\"א הנקרא \u0003זה,\u0004 שה\"ס קו האמצעי. וכל דגי הים מתקבצים למקומם, וכל החיות שמחים עליו, וחיות השדה העליון שמחים. ז\"ש. וכל חיות השדה ישחקו שם."],[6,"","פירוש. כי ענין רוח סערה שבא בים והאניות עולות ויורדות, כבר הוא התחלת תקון, כי בעת הדינין, נעשה הים בסוד ימא דקאפו, (כנ\"ל בראשית א' דף רמ\"ז ד\"ה ימא) וז\"ש, \u0003וכל ארבין לא נטלי מאתרייהו ולא סלקין ונחתין\u0004 כי בשעת הדינים נקפא הים והאניות שבו אינן יכולות לזוז ממקומן, \u0003בר מההיא שעתא דאתי חד דברא דימא,\u0004 שה\"ס קו האמצעי, שמעלה המסך דחירק, אז מתגלה תחילה אותו רוח סערה שאז האניות עולות ויורדות, שה\"ס מלכות דמדת הדין. ואח\"כ ממתיק אותה במדת הרחמים עד שראויה לקבל אור. (כמ\"ש לעיל פרשת לך דף י\"ג ד\"ה ונתבאר) וז\"ש וידע לאשלמא רוחא דזעפא. דהיינו שידע להמתיקו במדת הרחמים, ואז מיחד הקוין ימין ושמאל זב\"ז, וז\"ש, \u0003וכדין כלהו ארבין אזלין באורח מישר ולא סטאן לימינא ושמאלא,\u0004 אלא בדרך קו האמצעי."],[7,"ת\"ח כגוונא דלעילא וכו':","בוא וראה כעין של מעלה בחג\"ת דז\"א, יש למטה, בנה\"י דז\"א. וכעין של מטה יש בים התחתון, שהוא המלכות. (גרסא אחרת) כעין של מעלה בחג\"ת דז\"א יש בים העליון. שהוא בינה. וכעין של מעלה יש למטה בנה\"י דז\"א. וכעין של מטה יש בים התחתון, שהוא מלכות."],[8,"גופא דההוא ימא וכו':","הגוף של ים ההוא העליון, שהוא בינה, כבר הערתי לחברים: האורך והרוחב שלו, הראש והזרועות, והגוף, הכל כמו שצריך, וכולם בשמו נקרא. וכעין זה למטה בים שלמטה, שהוא המלכות, יש גם כן ראש של הים וזרועות של הים והגוף של הים."],[8,"","פירוש, סובב על מ\"ש למעלה, \u0003כגוונא דלעילא אית בימא עלאה,\u0004 שפירושו, שכמו שיש בז\"א ד' גלגלי המרכבה, שהם חג\"ת דז\"א והנוקבא, כן הם נכללים בים העליון בבינה, וחג\"ת אשר שם, מכונים זרועות, שהם חו\"ג, וגופא שהוא ת\"ת, והג\"ר מכונים ראש. וז\"ש \u0003גופא דההוא ימא וכו' לימא דתתא הכי נמי רישא דימא וכו'.\u0004"],[9,"כתיב, זבולון וכו':","כתוב, זבולון לחוף ימים ישכון. שואל. והרי ים אחד היה בנחלתו ולמה אומר לחוף ימים. ומשיב. אלא מהו חוף ימים, ודאי בארוהו החברים בסוד העליון. וירכתו על צדון. הוא כמש\"א יוצאי ירך יעקב, כי זבולון שוק הימין של הגוף היה, שהוא נצח, וע\"כ אוה\"כ וירכתו. וים כנרת היה בנחלתו, ומכאן נמצא חלזון לתכלת."],[10,"ת\"ח, כמה רתיכין וכו':","בוא וראה, כמה מרכבות על מרכבות נמצאים, וגלגלי המרכבה רצים במהירות, וסומכי המרכבה אינם מתעכבים מנסוע עליהם. וכן כולם. בוא וראה המרכבה של הממונה על מצרים. שבארוה, שמרכבה שלמה לא נמצא, כי כתוב, ויסר את אופן מרכבותיו. כמה מרכבות היו שהיו נוסעות על סומך גלגל אחד, שנתמנה עליהם, כיון שזה הוסר משליטתו, כל המרכבות נעברו משליטתם ולא נסעו. אז כולם שלמטה בעולם הזה, נעברו משליטתם. שכתוב, על מצרים ועל פרעה ועל הבוטחים בו."],[10,"","פירוש. אחר שביאר ר\"ש ענין המרכבות והים, והדינים הנוהגים בים, חוזר לבאר הכתוב, ויסר את אופן מרכבותיו עם הפסוק, וארא החיות והנה אופן אחד בארץ. כמו שבארנו לעיל, ועתה מכנה את האופן ההוא בשם, \u0003סמיך גלגלא.\u0004 וז\"ש, \u0003כמה רתיכין הוו דנטלי על חד סמיך גלגלא,\u0004 דהיינו על אופן אחד הנ\"ל, שהוא נקודת המלכות המתוקנת במדת הרחמים, שזולתה לא היו ראוים לקבלת אור כנ\"ל, וז\"ש, \u0003כיון דאתעבר האי משלטנותא דיליה, כלהו רתיכין אתעברו משלטניהון, ולא נטלו.\u0004 כי אחר שהוסר התקון של מלכות הממותקת במדת הרחמים, כבר אינם ראוים לקבלת אור, וע\"כ הוסרה השליטה שלהם, וע\"כ ולא יכלו לנסוע."]],[[0,"","וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) וָאֵרֶא הַחַיּוֹת וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ אֵצֶל הַחַיּוֹת. פָּסוּק זֶה פֵּרְשׁוּהוּ וְנִתְבָּאֵר, אֲבָל בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא בַּכֹּל מַרְאֶה אֶת שִׁלְטוֹנוֹ, וְשִׁלְטוֹנוֹ זֶה לֹא יַעֲבֹר לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[1,"","וְעָשָׂה שִׁלְטוֹן בָּאָבוֹת. נָטַל אֶת אַבְרָהָם וְהֶעֱמִיד בּוֹ אֶת הָעוֹלָם, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וּפֵרְשׁוּהָ. נָטַל אֶת יִצְחָק וְשָׁתַל בּוֹ אֶת הָעוֹלָם, שֶׁהוּא קַיָּם לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב וְאֶת בְּרִיתִי אָקִים אֶת יִצְחָק. נָטַל אֶת יַעֲקֹב, וְהוֹשִׁיבוֹ לְפָנָיו וְהִשְׁתַּעֲשַׁע עִמּוֹ, וְהִתְפָּאֵר בּוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[2,"","וּבֹא רְאֵה, יַעֲקֹב אָחַז בְּעֵץ הַחַיִּים שֶׁאֵין בּוֹ מָוֶת לְעוֹלָמִים, שֶׁכָּל הַחַיִּים נִתְקְנוּ בְּאוֹתוֹ הָעֵץ, וְנוֹתֵן חַיִּים לְכָל אוֹתָם שֶׁאֲחוּזִים בּוֹ, וְלָכֵן יַעֲקֹב לֹא מֵת. וּמָתַי מֵת? בְּשָׁעָה שֶׁכָּתוּב (בראשית מט) וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה. הַמִּטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, מִשּׁוּם שֶׁבְּמִטָּה זוֹ כָּתוּב רַגְלֶיהָ יֹרְדוֹת מָוֶת, וְלָכֵן כָּתוּב וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָּה, וְאָז וַיִּגְוַע וַיֵּאָסֶף אֶל עַמָּיו. וְעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יַעֲקֹב לִבְחִיר הָאָבוֹת, זֶהוּ שֶׁכָּתוּב (ישעיה מא) יַעֲקֹב אֲשֶׁר בְּחַרְתִּיךְ."],[3,"","בֹּא רְאֵה, כָּל הַמַּחֲנוֹת שֶׁלְּמַעְלָה וְכָל אוֹתָן הַמֶּרְכָּבוֹת, כֻּלָּם אֲחוּזִים אֵלֶּה בְּאֵלֶּה, דְּרָגוֹת בִּדְרָגוֹת. אֵלֶּה עֶלְיוֹנִים וְאֵלֶּה תַחְתּוֹנִים, וְחַיּוֹת ל ל הַקֹּדֶשׁ עֲלֵיהֶם, וְכָל הָאוּכְלוּסִים וְהַמַּחֲנוֹת, כֻּלָּם נוֹסְעִים תַּחַת יָדֶיהָ. עַל מַאֲמָרָהּ נוֹסְעִים וְעַל מַאֲמָרָהּ חוֹנִים."],[4,"","וְזוֹהִי הַחַיָּה (העליונה הקדושה) שֶׁכָּל שְׁאָר הַחַיּוֹת אֲחוּזוֹת בָּהּ, וְהִשְׁתַּלְשְׁלוּ (ונתקנו) בִּשְׁבִילָהּ כַּמָּה חַיּוֹת לְחַיּוֹת (אלו יורדות ואלו יורדות). וְנֶאֱחָזוֹת דְּרָגוֹת בִּדְרָגוֹת, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים הוֹלְכִים וְשָׁטִים בַּיָּם. זֶהוּ שֶׁכָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֵמֶשׂ וְאֵין מִסְפָּר וְגוֹ'."],[5,"","וּכְשֶׁמַּעָֹלֶה הַיָּם אֶת גַּלָּיו, כָּל הָאֳנִיּוֹת עוֹלוֹת וְיוֹרְדוֹת, וְנִמְצָא זַעַף, וְרוּחַ קָשָׁה הוֹלֶכֶת עָלָיו בְּחֹזֶק, וּדְגֵי הַיָּם מִתְפַּזְּרִים לְכָל צַד, אֵלֶּה לַמִּזְרָח וְאֵלֶּה לַמַּעֲרָב, אֵלֶּה לַצָּפוֹן וְאֵלֶּה לַדָּרוֹם. וְכָל אוֹתָם בְּנֵי הָעוֹלָם שֶׁרוֹאִים אֶת הָרֹשֶׁם עֲלֵיהֶם, לוֹקְחִים אוֹתָם וּבוֹלְעִים אוֹתָם בִּמְעָרוֹת הֶעָפָר."],[6,"","וְכָל הָאֳנִיּוֹת לֹא נוֹסְעוֹת מִמְּקוֹמָם, וְלֹא עוֹלוֹת וְיוֹרְדוֹת, פְּרָט לְאוֹתָהּ שָׁעָה שֶׁבָּא מַנְהִיג אֶחָד שֶׁל הַיָּם וְיוֹצֵא לְהַשְׁלִים רוּחַ שֶׁל זַעַף הַיָּם. כֵּיוָן שֶׁזֶּה עוֹלֶה עַל הַיָּם, שׁוֹכֵךְ מֵרָגְזוֹ, וְנִמְצֵאת מְנוּחָה. וְאָז כָּל הָאֳנִיּוֹת הוֹלְכוֹת בְּדֶרֶךְ יָשָׁר, וְלֹא סוֹטוֹת לְיָמִין וְלִשְׂמֹאל. זֶהוּ שֶׁכָּתוּב שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. זֶה דַּוְקָא. וְכָל דְּגֵי הַיָּם מִתְכַּנְּסִים לִמְקוֹמָם, וְכָל אוֹתָן הַחַיּוֹת שְׂמֵחוֹת עָלֶיהָ, וְחַיּוֹת הַשָּׂדֶה הָעֶלְיוֹנוֹת שְׂמֵחוֹת. זֶהוּ שֶׁכָּתוּב (איוב מ) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם."],[7,"","בֹּא רְאֵה, כְּמוֹ שֶׁלְּמַעְלָה יֵשׁ לְמַטָּה, כְּמוֹ שֶׁלְּמַטָּה יֵשׁ בַּיָּם. כְּמוֹ שֶׁלְּמַעְלָה יֵשׁ לְמַעְלָה בַּיָּם הָעֶלְיוֹן. כְּגוֹן שֶׁלְּמַעְלָה יֵשׁ לְמַטָּה. כְּגוֹן שֶׁלְּמַטָּה יֵשׁ בַּיָּם הַתַּחְתּוֹן."],[8,"","הַגּוּף שֶׁל אוֹתוֹ הַיָּם, הֲרֵי הִתְעוֹרַרְנוּ לַחֲבֵרֵינוּ, אֹרֶךְ וָרֹחַב, רֹאשׁ וּזְרוֹעוֹת וְשַּׂעֲרוֹת הַגּוּף, הַכֹּל כְּמוֹ שֶׁצָּרִיךְ, וְהַכֹּל נִקְרָא בִשְׁמוֹ. וּכְמוֹ זֶה לְמַטָּה לַיָּם שֶׁלְּמַטָּה, כָּךְ גַּם הָרֹאשׁ שֶׁל הַיָּם וּזְרוֹעוֹת הַיָּם וְגוּף הַיָּם."],[9,"","כָּתוּב (בראשית מט) זְבוּלֻן לְחוֹף יַמִּים יִשְׁכֹּן. וַהֲרֵי יָם אֶחָד הָיָה בְּגוֹרָלוֹ, אֶלָּא מַה זֶּה לְחוֹף יַמִּים? וַדַּאי שֶׁבֵּאֲרוּהָ הַחֲבֵרִים בְּסוֹד עֶלְיוֹן. וְיַרְכָתוֹ עַל צִידן, כַּנֶּאֱמַר (שמות א) יצְאֵי יֶרֶךְ יַעֲקֹב. זְבוּלוּן הָיָה שׁוֹק הַיָּמִין שֶׁל הַגּוּף, וְיָם כִּנֶּרֶת הָיָה בְּגוֹרָלוֹ, וּמִכָּאן נִמְצָא הַחִלָּזוֹן שֶׁל הַתְּכֵלֶת."],[10,"","בֹּא רְאֵה, כַּמָּה מֶרְכָּבוֹת עַל מֶרְכָּבוֹת נִמְצְאוּ, וְגַלְגַּלֵּי הַמֶּרְכָּבָה רָצִים בְּחִפָּזוֹן, וְלֹא מִתְעַכְּבִים אוֹתָם תּוֹמְכֵי הַמֶּרְכָּבָה לִנְסֹעַ עֲלֵיהֶם, וְכֵן כֻּלָּם (וכאן וינהגהו בכבדת, בחפזון). בֹּא רְאֵה, הַמֶּרְכָּבָה הַמְמֻנָּה עַל הַמִּצְרִים, (אם תאמר) פֵּרְשׁוּהָ, לֹא נִמְצֵאת מֶרְכָּבָה שְׁלֵמָה, שֶׁהֲרֵי כָּתוּב וַיָּסַר אֶת אֹפַן מַרְכְּבֹתָיו. כַּמָּה מֶרְכָּבוֹת הָיוּ שֶׁהָיוּ נוֹסְעִים עַל תּוֹמֵךְ גַּלְגַּל אֶחָד, שֶׁנִּפְקְדוּ עֲלֵיהֶם. כֵּיוָן שֶׁזֶּה הָעֳבַר מִשִּׁלְטוֹנוֹ, כָּל הַמֶּרְכָּבוֹת הָעָבְרוּ מִשִּׁלְטוֹנָם וְלֹא נָסְעוּ. אָז כֻּלָּם לְמַטָּה הָעָבְרוּ מִשִּׁלְטוֹנָם, שֶׁכָּתוּב עַל מִצְרַיִם (ירמיה מו) וְעַל פַּרְעֹה וְעַל הַבּטְחִים בּוֹ."]]],[["וּבְהַהוּא זִמְנָא, שֻׁלְטָנוּתָא דְּמִצְרַיִם שָׁלִיט עַל כָּל שְׁאַר עַמִּין, כֵּיוָן דְּאִתְבַּר חֵילָא דְּמִצְרַיִם, אִתְּבַר חֵילָא דִּשְׁאַר עַמִּין. מְנָלָן, דִּכְתִּיב, (שמות ט״ו:ט״ו) אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם וְגוֹ'. וּכְתִיב (שמות ט״ו:י״ד) שָׁמְעוּ עַמִּים יִרְגָּזוּן וְגוֹ'. בְּגִין דְּכֻלְּהוּ הֲווֹ אֲחִידָן בְּפוּלְחָנָא דְּמִצְרַיִם, וַאֲחִידָן בְּמִצְרַיִם לְסִיּוּעָא דִּלְהוֹן. וּבְהַהוּא זִמְנָא, כֻּלְּהוּ בָּעָאן לְסִיּוּעָא דְּמִצְרַיִם, לְאִתַּתְקְפָא. וְעַל דָּא, כֵּיוָן דְּשָׁמְעוּ גְּבוּרָן דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, רָפוּ יְדֵיהוֹן, וְלָא יָכִילוּ לְמֵיקָם, וְאִזְדַּעֲזָעוּ כֻּלְּהוּ, וְאִתְּבָּרוּ (משולשליהון) מִשּׁוּלְטָנַתְהוֹן.","וַדַּאי כַּד אִתְּבַר חֵילָא דִּלְהוֹן לְעֵילָּא, אִתְּבַר חֵילָא דְּכָל אִינּוּן דַּאֲחִידָן בֵּיהּ, כֵּיוָן דְּאִתְבַּר חֵילָא דְּכֻלְּהוּ לְעֵילָּא, כָּל הָנֵי דִּלְתַתָּא אִתְּבָּרוּ, בְּגִין (ההוא) הַאי חֵילָא דְּאִתְבַּר בְּקַדְמִיתָא. וּבְגִין כָּךְ וַיָּסַר אֵת אֹפַן מַרְכְּבוֹתָיו כְּתִיב. וַיְנַהֲגֵהוּ בִּכְבֵדוּת, דְּהָא כַּד דָּא אִתְּבַר, לָא הֲווֹ אַזְלִין.","תָּא חֲזֵי דְּהָכִי הוּא, דְּלָא כְּתִיב וַיָּסַר אֵת אוֹפַנִּי מַרְכְּבוֹתָיו, אוֹ אוֹפַן מֶרְכַּבְתּוֹ, אֶלָּא וַיָּסַר אֵת אוֹפַן מַרְכְּבוֹתָיו. בְּגִין הַאי חֵילָא, דְּכֻלְּהוּ הֲווֹ מִתְדַבְּקָן בֵּיהּ. (הכי אקרון)","וְתוּ, וַיָּסַר אֵת אוֹפַן מַרְכְּבוֹתָיו, תָּא חֲזֵי, (ויסר את אופן מרכבותיו) זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, לְאִתְדַּבְּקָא בְּהוּ, וּלְמֶהֱוֵי לְהוּ חוּלָק, וּלְמֶהוֵי אִינּוּן חוּלָקֵיהּ. הֲדָא הוּא דִּכְתִּיב, (דברים יג) וּבוֹ תִדְבָּקוּן. וּכְתִיב (דברים ד׳:ד׳) וְאַתֶּם הַדְּבֵקִים בַּיְיָ' אֱלֹהֵיכֶם, בַּיְיָ' מַמָּשׁ. וּכְתִיב (תהילים קל״ה:ד׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. וּכְתִיב (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. דְּאַפִּיק לוֹן מִזַּרְעָא קַדִּישָׁא, לְמֶהֱוֵי חוּלָקֵיהּ, וְעַל דָּא יָהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא עִלָּאָה, גְּנִיזָא תְּרֵי אַלְפִין שְׁנִין, עַד לָא יִתְבְּרֵי עָלְמָא, וְהָא אִתְּמַר. וּבְגִין רְחִימוּתָא דִּילֵיהּ יָהֲבָא לְיִשְׂרָאֵל, לְמֵהַךְ אֲבַתְרָהּ, וּלְאִתְדַּבְּקָא בָּהּ.","תָּא חֲזֵי, כָּל מַשִׁירְיָין דִּלְעֵילָּא, וְכָל אִינּוּן רְתִיכִין, כֻּלְּהוּ אֲחִידָן אִלֵּין בְּאִלֵּין, דַּרְגִּין בְּדַרְגִּין, אִלֵּין עִלָּאִין, וְאִלֵּין תַּתָּאִין, וְהָא אוּקְמוּהָ, דִּכְתִּיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל. וְחֵיוָתָא קַדִּישָׁא עָלֵיהּ, וְכֻלְּהוּ אוּכְלוֹסִין וּמַשִּׁרְיָין, כֻּלְּהוּ נַטְלִין תְּחוֹת יְדָהּ, עַל מֵימְרָהּ נַטְלִין, וְעַל מֵימְרָהּ שָׁרָאן. בְּעִדָנָא דְּהִיא נַטְלָא, כֻּלְּהוּ נְטִילִין, בְּגִין דְּכֻלְּהוּ אֲחִידָן בָּהּ. (אמר ר' יצחק)","וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא, לְאַעְבְּרָא לְאוּכְלוֹסִין דְּפַרְעֹה לְתַתָּא, אַעְבַּר בְּקַדְמִיתָא לְהַהוּא חֵילָא דִּלְהוֹן, כְּמָה דְּאוֹקִימְנָא. מַה עָבֵד. אַעְבָּר וְסָלִיק הַהוּא אֲתָר קַדִּישָׁא עִלָּאָה, דְּהֲוָה מַדְבָּר (פי' מנהיג) לְכָל אִינּוּן רְתִיכִין, כֵּיוָן דְּהַאי אִסְתְּלִיק, הַנְהוּ כֻּלְּהוּ מַשִּׁירְיָין לָא יָכִילוּ לְדַבְּרָא, כֵּיוָן דְּאִינּוּן לָא יָכִילוּ, הַהוּא מְמָנָא דְּמִצְרָאֵי אַעְבְּרוּ לֵיהּ מִשּׁוּלְטָנֵיהּ, וְאַעְבַּר (י' ע\"ב) בְּנוּרָא דְּדָלִיק, וּכְדֵין שֻׁלְטָנוּתָא דְּמִצְרָאֵי אִתְעָדֵי. וְעַל דָּא, אָנוּסָה מִפְּנִי יִשְׂרָאֵל. מַאי טַעְמָא, בְּגִין דְּחָמוּ מְמָנָא דְּמִצְרַיִם אִתּוֹקַד בְּנוּרָא.","ר' יִצְחָק אָמַר, בְּשַׁעֲתָא דְּקָרִיבוּ יִשְׂרָאֵל לְיַמָּא, קָרָא קוּדְשָׁא בְּרִיךְ הוּא לַמְמָנָא רַבְרְבָא דְּעַל יַמָּא, אָמַר לֵיהּ, בְּשַׁעֲתָא דַּעֲבָדִית אֲנָא עָלְמָא, מָנִיתִי לָךְ עַל יַמָּא, וּתְנַאי אִית לִי עַל יַמָּא, דִּי יִבְזַע מֵימוֹי מִקָּמֵי בָּנַי. הַשְׁתָּא מָטָא עִדָנָא, דְּיָעַבְרוּן בָּנַי בְּגוֹ יַמָּא. לְבָתַר מַה כְּתִיב, וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. מַאי לְאֵיתָנוֹ, לִתְנָאוֹ דְּהֲוָה לֵיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא.","וַהֲווּ יִשְׂרָאֵל שָׁרָאן עַל יַמָּא, וַהֲווּ יִשְׂרָאֵל חָמָאן, גַּלְגַּלֵּי יַמָּא סַלְּקִין וְנַחְתִּין, זָקְפוּ עֵינַיְיהוּ, וְחָמוּ לְפַרְעֹה וּלְאוּכְלוֹסִין דִּילֵיהּ, דְּחִילוּ וְצָעֲקוּ. וְהָא אִתְּמַר. הַיָּם רָאָה, מָה חָמָא יַמָּא. אֲרוֹנָא דְּיוֹסֵף קָא חָמָא, וְעָרַק מִקָּמֵיהּ. מַאי טַעְמָא, (בגין) דִּכְתִּיב, (בראשית ל״ט:י״ב) וַיָּנָס וַיֵּצֵא הַחוּצָה. וְעַל דָּא הַיָּם רָאָה וַיָּנוֹס, וּכְתִיב וַיָּסַר אֶת אוֹפַן מַרְכְּבוֹתָיו וְגוֹ' אָנוּסָה מִפְּנֵי יִשְׂרָאֵל. מַאי טַעֲמָא. בְּגִין דְּחָמוּ אַרְעָא דְּמִצְרַיִם, כְּאִלּוּ אִתּוֹקַד בְּנוּרָא, כְּדֵין אָמְרוּ אָנוּסָה מִפְּנִי יִשְׂרָאֵל.","רִבִּי חִיָּיא וְרִבִּי יוֹסֵי, הֲווֹ אַזְלֵי בְּמַדְבְּרָא, אָמַר רִבִּי חִיָּיא לְרִבִּי יוֹסֵי, תָּא וְאֵימָא לָךְ, דְּכַד קוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְאַעְבְּרָא שׁוּלְטָנוּתָא דְּאַרְעָא, לָא עָבִיד, עַד דְּאַעְבַּר שֻׁלְטָנוּתָא דִּלְהוֹן בִּרְקִיעָא, וְלָא אַעְבָּר שֻׁלְטָנָא דִּלְהוֹן, עַד דְּמָנֵי אַחֲרָא בְּאַתְרֵיהּ, בְּגִין דְּלָא יִגְרַע (שולטנותא) שִׁמּוּשָׁא דִּלְהוֹן בִּרְקִיעָא, בְּגִין לְקַיְּימָא מַה דִּכְתִּיב, (דניאלד) וּלְמַן דִּי יִצְבֵּא יִתְּנִינַּהּ. אָמַר רִבִּי יוֹסֵי, ודַּאי הָכִי הוּא."],[[0,"ובההוא זמנא וכו':","ובזמן ההוא, ממשלת מצרים היתה מושלת על כל שאר העמים, כיון שנשבר הכח של המצרים, דהיינו הכח של מלכות הממותקת הנ\"ל, שממנה ינקו המצרים כל הכח שלהם. נשבר הכח של שאר העמים, מאין לנו, שכתוב, אז נבהלו אלופי אדום וגו', וכתוב, שמעו עמים ירגזון, משום שכולם היו נאחזים בעבודת מצרים ונאחזים במצרים שיושיעו להם, ובזמן ההוא, בקשו כולם עזרה ממצרים להתחזק, וע\"כ כיון ששמעו הגבורות שעשה הקב\"ה במצרים, רפו ידיהם, ולא יכלו לעמוד, וכולם הזדעזעו ונשברו משליטתם."],[1,"ודאי כד אתבר וכו':","ודאי, כשנשבר הכח שלהם למעלה, ונשבר הכח של כל אלו הנאחזים בו, כי כיון שנשבר הכח של כולם למעלה, נשברו כל אלו שלמטה, משום הכח ההוא שנשבר תחילה. ומשום זה ויסר את אופן מרכבותיו. דהיינו הכח של מעלה, כמ\"ש לעיל. וינהגהו בכבדות. כי כשזה נשבר, לא היו הולכים."],[2,"ת\"ח דהכי הוא וכו':","בוא וראה שכן הוא, כי לא כתוב, ויסר את אופני מרכבותיו, או אופן מרכבתו, דהיינו או שניהם בלשון רבים או שניהם בלשון יחיד. אלא כתוב ויסר את אופן מרכבותיו, שאופן הוא בלשון יחיד, ומרכבותיו בלשון רבים, והוא משום שאופן, הוא הכח שכולם היו מתדבקים בו. כמ\"ש לעיל, וע\"כ נאמר בלשון יחיד."],[3,"ותו, ויסר את וגו':","ועוד יש לפרש ויסר את אופן מרכבותיו. בוא וראה, אשרי חלקם של ישראל, שהקב\"ה רצה בהם להתדבק בהם, ולהיות להם חלק, והם יהיו חלקו. ז\"ש ובו תדבקון. וכתוב, ואתם הדבקים בה' אלקיכם. בה' ממש. וכתוב כי יעקב בחר לו יה. וכתוב, כי חלק ה' עמו יעקב חבל נחלתו, שהוציאם מזרע קודש, להיות חלקו. משא\"כ הס\"א ואומות העולם, אין להם שום אחיזה בז\"א. ועל כן נתן להם תורה הקדושה העליונה, שהיתה גנוזה שני אלפים שנה מטרם שנברא העולם. וכבר נתבאר. ובשביל אהבתו נתן אותה לישראל ללכת אחריה ולהדבק בה."],[4,"תא חזי, כל וכו':","בוא וראה, כל המחנות של מעלה, וכל המרכבות כולם אחוזים זה בזה מדרגות במדרגות, אלו העליונים ואלו התחתונים קשורים יחד. ובארוהו, שכתוב, זה הים גדול. והחיה הקדושה עליהם, שהיא הנוקבא שמחזה ולמעלה, דז\"א המקבלת מג' חיות דז\"א, והיא חיה הרביעית, שהכל מקבלים ממנה, ואפילו המרכבות דס\"א, ואומות העולם. וכל ההמון והמחנות כולם נוסעים תחת ידה על פיה יסעו ועל פיה יחנו. בעת שהיא נוסעת כולם נוסעים. משום שכולם אחוזים בה."],[5,"ות\"ח, בשעתא דבעי וכו':","ובוא וראה, בשעה שרצה הקב\"ה להעביר המוניו של פרעה למטה, העביר תחילה אותו הכח שלהם כמו שבארנו למעלה (באות ק\"ז). מה עשה העביר והסיר אותו מקום הקדוש העליון דהיינו נקודת המלכות הממותקת בבינה המתוקן בחיה הקדושה, שהיתה מנהיגה לכל אלו המרכבות של שר מצרים למעלה. כי כל המרכבות ברשותה היא (כנ\"ל אות צ\"ח) ואפילו דס\"א, כיון שזו הסתלקה, כל המחנות והמרכבות לא יכלו לנהג, וכיון שלא יכלו, הוסר הממונה של מצרים מממשלתו, והעבירו אותו באש דולק, ואז הוסר ממשלת מצרים. וע\"כ אמרו, אנוסה מפני בני ישראל. מה הטעם, משום שראו את הממונה של מצרים שנשרף באש."],[6,"ר' יצחק אמר וכו':","רי\"א, בשעה שקרבו ישראל אל הים, קרא הקב\"ה את השר הממונה על הים, אמר לו בשעה שעשיתי את העולם, פקדתי אותך על הים, ויש לי תנאי עם הים, שיבקעו מימיו לפני בני. עתה הגיע הזמן שיעברו בני בתוך הים. ואחר כך מה כתוב, וישב הים לפנות בוקר לאיתנו, מהו לאיתנו, לתנאו שהיה לו עם הקב\"ה כשברא את העולם. כי לאיתנו הוא אותיות לתנאו."],[7,"והוו ישראל שראן וכו':","והיו ישראל שורים על הים, וישראל היו רואים גלי הים עולים ויורדים, נשאו עיניהם, וראו פרעה והמונו, יראו וצעקו. וכבר נתבאר. \u0003הים ראה,\u0004 שואל, מה ראה הים, ומשיב, ארונו של יוסף ראה וברח מלפניו. מה הטעם. משום שכתוב ביוסף, וינס ויצא החוצה. ועל כן בזכות הזה הים ראה וינס. וכתוב, ויסר את אופן מרכבותיו וגו' אנוסה מפני ישראל. מה הטעם. הוא משום שראו את ארץ מצרים כאלו היא נשרפת באש, אז אמרו, אנוסה מפני בני ישראל."],[8,"רבי חייא ור' יוסי וכו':","ר\"ח ור\"י היו הולכים במדבר. אמר ר' חייא לר' יוסי, בוא ואומר לך, כאשר הקב\"ה רוצה להעביר ממשלה בארץ, אינו עושה עד שמעביר הממשלה שלה ברקיע. ואינו מעביר הממשלה ברקיע, עד שממנה אחר במקומה, מטעם, שלא יחסר השמוש שלהם ברקיע. כדי לקיים מה שכתוב, ולמאן די יצבא יתנינה. אמר רבי יוסי, ודאי כן הוא."]],[[0,"","וּבְאוֹתוֹ זְמַן הַשַּׁלִּיט שֶׁל מִצְרַיִם שָׁלַט עַל כָּל שְׁאָר הָעַמִּים. כֵּיוָן שֶׁהָעֳבַר כֹּחַ מִצְרַיִם, נִשְׁבַּר כֹּחַ שְׁאָר הָעַמִּים. מִנַּיִן לָנוּ? שֶׁכָּתוּב אָז נִבְהֲלוּ אַלּוּפֵי אֱדוֹם וְגוֹ', וְכָתוּב שָׁמְעוּ עַמִּים יִרְגָּזוּן וְגוֹ'. מִשּׁוּם שֶׁכֻּלָּם הָיוּ אֲחוּזִים בַּפֻּלְחָן שֶׁל הַמִּצְרִים, וַאֲחוּזִים בְּמִצְרַיִם לַסִּיּוּעַ שֶׁלָּהֶם. וּבְאוֹתוֹ זְמַן כֻּלָּם בִּקְשׁוּ אֶת הַסִּיּוּעַ שֶׁל מִצְרַיִם לְהִתְחַזֵּק. וְעַל זֶה, כֵּיוָן שֶׁשָּׁמְעוּ אֶת הַגְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, רָפוּ יְדֵיהֶם וְלֹא יָכְלוּ לַעֲמֹד, וְכֻלָּם הִזְדַּעְזְעוּ וְנִשְׁבְּרוּ מִשִּׁלְטוֹנָם."],[1,"","וַדַּאי שֶׁכְּשֶׁנִּשְׁבַּר כֹּחָם לְמַעְלָה, שֶׁנִּשְׁבַּר כֹּחַ שֶׁל כָּל אוֹתָם שֶׁאֲחוּזִים בּוֹ. כֵּיוָן שֶׁנִּשְׁבַּר הַכֹּחַ שֶׁל כֻּלָּם לְמַעְלָה, כָּל אֵלֶּה שֶׁלְּמַטָּה נִשְׁבְּרוּ מִשּׁוּם (אותו) הַכֹּחַ הַזֶּה שֶׁנִּשְׁבַּר בַּתְּחִלָּה, וּמִשּׁוּם כָּךְ וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו כָּתוּב. וַיְנַהֲגֵגוּ בִּכְבֵדוּת, שֶׁהֲרֵי כְּשֶׁזֶּה נִשְׁבַּר, לֹא הָיוּ הוֹלְכִים."],[2,"","בֹּא וּרְאֶה שֶׁכָּךְ הוּא, שֶׁלֹּא כָתוּב וַיָּסַר אֵת אוֹפַנֵּי מַרְכְּבוֹתָיו, אוֹ אוֹפַן מֶרְכַּבְתּוֹ, אֶלָּא וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו, מִשּׁוּם שֶׁכֹּחַ זֶה שֶׁכֻּלָּם הָיוּ נִדְבָּקִים בּוֹ."],[3,"","וְעוֹד וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו - בֹּא רְאֵה, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם לְהִדָּבֵק בָּהֶם וְלִהְיוֹת לָהֶם חֵלֶק, וְשֶׁהֵם יִהְיוּ בְחֶלְקוֹ. זֶהוּ שֶׁכָּתוּב (דברים יג) וּבוֹ תִדְבָּקוּן. וְכָתוּב (שם ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם. בַּה' מַמָּשׁ. וְכָתוּב (תהלים קלה) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ. וְכָתוּב כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. שֶׁהוֹצִיא אוֹתָם מִזֶּרַע קָדוֹשׁ לִהְיוֹת חֶלְקוֹ, וְעַל זֶה נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה עֶלְיוֹנָה גְּנוּזָה אַלְפַּיִם שָׁנִים עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, וַהֲרֵי זֶה נֶאֱמַר. וּמִשּׁוּם אַהֲבָתוֹ נָתַן אוֹתָהּ לְיִשְׂרָאֵל לָלֶכֶת אַחֲרֶיהָ וְלִדְבּק בָּהּ."],[4,"","בֹּא רְאֵה, כָּל הַמַּחֲנוֹת הָעֶלְיוֹנִים, וְכָל אוֹתָן מֶרְכָּבוֹת, כֻּלָּם אֲחוּזִים אֵלֶּה בְּאֵלֶּה, דְּרָגוֹת בִּדְרָגוֹת. אֵלּוּ עֶלְיוֹנִים, וְאֵלּוּ תַחְתּוֹנִים, וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל. וְחַיָּה קְדוֹשָׁה עָלָיו, וְכָל הָאוּכְלוּסִים וְהַמַּחֲנוֹת, כֻּלָּם נוֹסְעִים תַּחַת יָדֶיה. עַל מַאֲמָרָהּ נוֹסְעִים וְעַל מַאֲמָרָהּ חוֹנִים. בִּזְמַן שֶׁהִיא נוֹסַעַת, כֻּלָּם נוֹסְעִים, מִשּׁוּם שֶׁכֻּלָּם אֲחוּזִים בָּהּ."],[5,"","וּבֹא רְאֵה, בְּשָׁעָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר אֶת אוּכְלוּסֵי פַרְעֹה לְמַטָּה, הֶעֱבִיר בַּתְּחִלָּה אֶת אוֹתוֹ כֹּחַ שֶׁלָּהֶם כְּמוֹ שֶׁהֵקַמְנוּ. מֶה עָשָׂה? הֶעֱבִיר וְסִלֵּק אוֹתוֹ מָקוֹם קָדוֹשׁ עֶלְיוֹן שֶׁהָיָה מַנְהִיג אֶת כָּל אוֹתָן הַמֶּרְכָּבוֹת. כֵּיוָן שֶׁזֶּה הִסְתַּלֵּק, כָּל הַמַּחֲנוֹת הַלָּלוּ לֹא יָכְלוּ לְהִתְנַהֵג. וְכֵיוָן שֶׁלֹּא יָכְלוּ, הָעֳבַר מִשִּׁלְטוֹנוֹ אוֹתוֹ הַמְמֻנֶּה שֶׁל מִצְרַיִם וְהָעֳבַר בְּאֵשׁ דּוֹלֶקֶת, וְאָז הַשַּׁלִּיט שֶׁל הַמִּצְרִים הוּזַז, וְעַל זֶה אָנוּסָה מִפְּנֵי יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאוּ אֶת הַמְמֻנֶּה שֶׁל מִצְרַיִם נִשְׂרָף בָּאֵשׁ."],[6,"","רַבִּי יִצְחָק אָמַר, בְּשָׁעָה שֶׁקָּרְבוּ יִשְׂרָאֵל לַיָּם, קָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לַמְמֻנֶּה הַגָּדוֹל שֶׁעַל הַיָּם וְאָמַר לוֹ: בְּשָׁעָה שֶׁעָשִׂיתִי אֶת הָעוֹלָם, מִנִּיתִי אוֹתְךְ עַל הַיָּם, וּתְנַאי יֵשׁ לִי עַל הַיָּם - שֶׁיִּקְרַע אֶת מֵימָיו מִלִּפְנֵי בָנַי, הִגִּיעַ הַזְּמַן עַכְשָׁו שֶׁיַּעַבְרוּ בָנַי בְּתוֹךְ הַיָּם. מַה כָּתוּב אַחַר כָּךְ? וַיָּשָׁב הַיָּם לִפְנוֹת בֹּקֶר לְאֵיתָנוֹ. מַה זֶּה לְאֵיתָנוֹ? לִתְנָאוֹ שֶׁהָיָה לוֹ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁבָּרָא אֶת הָעוֹלָם."],[7,"","וְהָיוּ יִשְׂרָאֵל חוֹנִים עַל הַיָּם, וְהָיוּ יִשְׂרָאֵל רוֹאִים אֶת גַּלֵּי הַיָּם עוֹלִים וְיוֹרְדִים. הֵרִימוּ עֵינֵיהֶם, וְרָאוּ אֶת פַּרְעֹה וְהָאוּכְלוּסִים שֶׁלּוֹ, וּפָחֲדוּ וְצָעֲקוּ, וַהֲרֵי נִתְבָּאֵר. הַיָּם רָאָה - מָה רָאָה הַיָּם? הוּא רָאָה אֶת אֲרוֹנוֹ שֶׁל יוֹסֵף, וּבָרַח מִלְּפָנָיו. מָה הַטַּעַם? (משום) שֶׁכָּתוּב (בראשית לט) וַיָּנָס וַיֵּצֵא הַחוּצָה, וְעַל זֶה הַיָּם רָאָה וַיָּנָס, וְכָתוּב וַיָּסַר אֵת אֹפַן מַרְכְּבֹתָיו וְגוֹ' אָנוּסָה מִפְּנֵי יִשְׂרָאֵל. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאוּ אֶת אֶרֶץ מִצְרַיִם כְּאִלּוּ עוֹלָה בָּאֵשׁ, וְאָז אָמְרוּ אָנוּסָה מִפְּנֵי יִשְׂרָאֵל."],[8,"","רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּמִּדְבָּר. אָמַר רַבִּי חִיָּיא לְרַבִּי יוֹסֵי, בּא וְאֹמַר לְךְ, שֶׁכְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִיר שִׁלְטוֹן שֶׁל הָאָרֶץ, אֵינוֹ עוֹשֶׂה עַד שֶׁמַּעֲבִיר הַשַּׁלִּיט שֶׁלָּהֶם בָּרָקִיעַ, וְלֹא מַעֲבִיר אֶת הַשַּׁלִּיט שֶׁלָּהֶם עַד שֶׁמְּמַנֶּה אַחֵר בִּמְקוֹמוֹ, כְּדֵי שֶׁלֹּא יִגָּרַע (השלטון) הַשִּׁמּוּשׁ שֶׁלָּהֶם בָּרָקִיעַ, כְּדֵי לְקַיֵּם מַה שֶּׁכָּתוּב (דניאל ד) וּלְמִי שֶׁיַּחְפֹּץ יִתְּנֶנָּה. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא."]]],[["פָּתַח ר' יוֹסֵי וְאָמַר, (תהילים ח׳:ב׳) יְיָ' אֲדוֹנֵינוּ מַה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. יְיָ' אֲדוֹנִינוּ: כַּד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְתַבְרָא חֵילָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אַתְקִיף דִּינֵיהּ עָלַיְיהוּ, וְתָבַר לוֹן, וְאַעְבָּר מִקָּמֵיהּ שׁוּלְטָנוּתָא דִּלְהוֹן.","אֲשֶׁר תְּנָה הוֹדְךָ עַל הַשָּׁמָיִם, אֲשֶׁר נָתַתָּ מִבָּעֵי לֵיהּ, אוֹ תְּנָה הוֹדְךָ, מַהוּ אֲשֶׁר תְּנָה הוֹדְךָ. אֶלָּא דָּא הוּא רָזָא דְּנָהֲרָא עֲמִיקָא דְּכֹלָּא, וְדָוִד בָּעָא בָּעוּתֵיהּ, לְמִנְגַּד מִנֵּיהּ עַל הַשָּׁמַיִם, וְדָא הוּא (ויקרא ס\"ה ע\"ב) אֲשֶׁר. כְּמָה דְאַתְּ אָמֵר, (שמות ג׳:י״ד) אֶהְיֶה אֲשֶׁר אֶהְיֶה.","בְּשַׁעֲתָא דְּהַאי נָהֲרָא (ס\"ג ע\"ב, בראשית רכ\"א ע\"א) עֲמִיקְתָא דְּכֹלָּא, נָגִיד וְנָפִיק עַל הַשָּׁמַיִם, כְּדִין כֹּלָּא בְּחִידוּ, וּמַטְרוֹנִיתָא אִתְעַטְּרָת בְּמַלְכָּא, וְכָל עָלְמִין כֻּלְּהוּ בְּחִידוּ, וְשֻׁלְטָנוּתָא דְּעַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אִתְעֲבָר מִקָּמֵי מַטְרוֹנִיתָא, וּכְדֵין זַקְפִין רֵישָׁא כָּל מַאן דַאֲחִידוּ בָּהּ.","אַדְּהָכִי חָמוּ חַד בַּר נָשׁ, דְּהֲוָה אָתֵי, וְחַד מָטוּלָא קָמֵיהּ. אָמַר רִבִּי חִיָּיא, נֵזִיל, דִּלְמָא הַאי בַּר נָשׁ עוֹבֵד עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת הוּא, אוֹ עַם הָאָרֶץ הוּא, וְאָסִיר לְאִשְׁתַּתְּפָא בַּהֲדֵיהּ בְּאָרְחָא. אָמַר רִבִּי יוֹסֵי, נֵיתִיב הָכָא, וְנֶחמֵי, דִּלְמָא גַּבְרָא רַבָּא הוּא.","אַדְּהָכִי, אַעְבָּר קָמַיְיהוּ, אֲמַר לֵיהּ, בְּדוּקְפָא דִּמַעְבָּרָא דְּקוֹטִיפָא דְּהַאי, חַבְרוּתָא אִבָעֵי, וַאֲנָא יְדַעְנָא אָרְחָא אַחֲרָא, וְנִסְטֵי מֵהַאי, וַאֲנָא בָּעִינָא דְּאֵימָא לְכוּ, וְלָא אִתְחַיַּיבְנָא בְּכוּ, וְלָא אַעְבָּר עַל מַה דִּכְתִּיב, (ויקרא י״ט:י״ד) וְלִפְנִי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, וְאַתּוּן כְּסוּמִין בְּאָרְחָא דָּא, וְלָא תִּסְתַּכְּנוּ בְּנַפְשַׁיְיכוּ. אָמַר רִבִּי יוֹסֵי, בְּרִיךְ רַחֲמָנָא דְּאוֹרִיכְנָא הָכָא, אִתְחַבְּרוּ בַּהֲדֵיהּ. אָמַר לוֹן, לָא תִּשְׁתָּעוּ מִידִי הָכָא, עַד דְּנַעֲבֹר בְּהַאי. סָטוּ בְּאָרְחָא אַחֲרָא.","בָּתַר דְּנָפְקוּ מֵהַהוּא אֲתָר, אָמַר לוֹן, בְּהַהוּא אָרְחָא אַחֲרָא, הֲווֹ אַזְלֵי זִמְנָא חֲדָא, חַד כֹּהֵן חָכָם, וְחַד כֹּהֵן עַם הָאָרֶץ בַּהֲדֵיהּ, קָם הַהוּא עַם הָאָרֶץ בְּהַהוּא אֲתָר עָלֵיהּ וְקַטְלֵיהּ. מֵהַהוּא יוֹמָא כָּל מַאן דְּאַעְבָּר בְּהַהוּא אֲתָר, מִסְתַּכֵּן בְּנַפְשֵׁיהּ. וְהָא מִתְחַבְּרִין תַּמָן מְשַׁדְּדֵי טוּרַיָא, וְקַטְלִין וְקַפְּחִין לִבְנֵי נָשָׁא, וְאִינּוּן דְּיַדְעֵי לָא עַבְרֵי תַּמָּן, וּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא דָּמָא דְּהַהוּא כַּהֲנָא כָּל יוֹמָא.","פָּתַח וְאָמַר, (ישעיהו י׳:ל״ב) עוֹד הַיּוֹם בְּנוֹב לַעֲמוֹד וְגוֹ' הָא אוּקְמוּהָ אִינּוּן מָארֵי מְתִיבְתָּא. אֲבָל אֲנָא לָא אֲמֵינָא לְכוּ הָכִי, אֶלָּא דְרָזָא דְּמִלָּה אוֹלִיפְנָא. עוֹד הַיּוֹם, מַאן יוֹמָא דֵּין. אֶלָּא, הָכִי כְּתִיב, (שמות ו׳:כ״ג) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע בַּת עֲמִּינָדָב. וְרָזָא הוּא, עַל כְּנֶסֶת יִשְׂרָאֵל, דְּאַהֲרֹן הוּא שׁוֹשְׁבִינָא דִּילָהּ, לְתַקְּנָא בֵּיתָה וּלְשַׁמְּשָׁא לָהּ, וּלְמֵיעַל לָהּ לְמַלְכָּא לְאִזְדַּוְּוגָא כַּחֲדָא, מִכָּאן וּלְהָלְאָה, כָּל כֹּהֵן דִּמְשַׁמֵּשׁ בְּמַקְדְּשָׁא, כְּגַוְונָא דְּאַהֲרֹן.","אֲחִימֶלֶךָ כַּהֲנָא רַבָּא עִלָּאָה הֲוָה, וְכָל אִינּוּן כַּהֲנִי בַּהֲדֵיהּ, כֻּלְּהוּ הֲווֹ שׁוּשְׁבִינִין דְּמַטְרוֹנִיתָא, כֵּיוָן דְּאִתְקָטִילוּ, אִשְׁתַּאָרַת מַטְרוֹנִיתָא בִּלְחוֹדָהָא, וְאִתְאֲבִיד שׁוֹשְׁבִינָא דִּילָהּ, וְלָא אִשְׁתְּכַח מַאן דִּמְשַׁמֵּשׁ קָמָהּ, וִיתַקֵּן בֵּיתָה, וִיחַדֵּי לָהּ לְאִזְדַּוְּוגָא עִם מַלְכָּא. כְּדֵין מֵהַהוּא יוֹמָא, אִתְעַבְּרָא לִשְׂמָאלָא, וְקַיְּימָא עַל עָלְמָא, כָּמִין עַל כֹּלָּא, קָטִיל לְשָׁאוּל וְלִבְנוֹי, אִתְאֲבִיד מִינַיְיהוּ מַלְכוּ, מִיתוּ מִיִּשְׂרָאֵל כַּמָּה אַלְפִין וְכַמָּה רִבְוָון. וְעַד כְּעַן, הַהוּא חוֹבָה הֲוָה תָּלֵי, עַד דְּאָתָא סַנְחֵרִיב וְאַרְגִּיז כֹּלָּא.","וְדָא הוּא עוֹד הַיּוֹם בְּנוֹב, דָּא הוּא יוֹמָא עִלָּאָה, וּמַאן אִיהוּ. דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאַבְדַת שׁוּשְׁבִינִין דִּילָהּ, הַהִיא דְּאִשְׁתְּאָרַת בְּלא יְמִינָא, (דהוי ליה) לְאִתְדַּבְּקָא בִּשְׂמָאלָא. דְּכַהֲנָא יְמִינָא הוּא. (אמר ליה לאתדבקא בשמאלא) וּבְגִין כַּךְ, עוֹד הַיּוֹם בְּנוֹב לַעֲמוֹד.","תָּא חֲזֵי, כְּתִיב גִּבְעַת שָׁאוּל נָסָה, שָׁאוּל אֲמַאי הָכָא. אֶלָּא בְּגִין דְּהוּא קָטִיל לְכַהֲנֵי, וְגָרִים דְּרוֹעָא יְמִינָא, לְאִתְעַקְרָא מֵעָלְמָא. אוּף הָכָא, מֵהַהוּא יוֹמָא, לָא אַעְבָּר בַּר נָשׁ בְּהַהוּא דּוּכְתָּא, בְּגִין דְּלָא אִסְתַּכֵּן בְּנַפְשֵׁיהּ. אָמַר לֵיהּ רִבִּי יוֹסֵי לְרִבִּי חִיָּיא, וְלָא אֲמָרִית לָךְ דִּלְמָא גַּבְרָא רַבָּא הוּא."],[[0,"פתח ר' יוסי וכו':","פר\"י ואמר. ה' אדוננו מה אדיר שמך בכל הארץ. ה' אדוננו. היינו, כשרוצה הקב\"ה לשבר כח העמים עכו\"ם, מגביר דינו עליהם ומשבר אותם, ומעביר מלפניו הממשלה שלהם."],[1,"אשר תנה הודך על השמים:","שואל. אשר נתת, היה צריך לומר, או תנה הודך, מהו \u0003אשר\u0004 תנה הודך. ומשיב. אלא זה הוא סוד הנהר העמוק מכל, שהוא בינה, ודוד התפלל תפלתו להמשיך ממנו על השמים, שהוא ז\"א. וזהו \u0003אשר\u0004 שהוא שם הבינה, כמש\"א, אהיה אשר אהיה."],[2,"בשעתא דהאי נהרא וכו':","בשעה שנהר הזה, העמוק מכל, שהוא בינה, נמשך ויוצא על השמים, שהוא ז\"א, אז הכל בשמחה, והמטרוניתא שהיא מלכות, מתעטרת במלך, שהוא ז\"א, וכל העולמות כולם הם בשמחה, וממשלת העמים עכו\"ם הוסרה מפני המטרוניתא, ואז זוקפים ראשים כל מי שנאחז בה."],[3,"אדהכי חמו חד וכו':","בינתים, ראו אדם אחד, בא, ומשא לפניו. א\"ר חייא נלך, אולי אדם זה עכו\"ם הוא, או עם הארץ הוא, ואסור להשתתף עמו בדרך. א\"ר יוסי, נשב כאן ונראה אולי אדם גדול הוא."],[4,"אדהכי אעבר קמייהו וכו':","בתוך כך עבר לפניהם, אמר להם, במקום המעבר הזה של סכנה, אני צריך לחברותא. שאני מפחד ללכת יחידי. ואני יודע דרך אחר, ונסור מדרך הזה, ואני בקשתי לומר לכם, ולא אחטא בכם, ולא אעבר על מה שכתוב, לפני עור לא תתן מכשול, כי אתם כעורים בדרך הזה, ולא תסתכנו בעצמכם. א\"ר יוסי, ברוך הרחמן שחכינו כאן. התחברו עמו. אמר להם לא תדברו כלום כאן, עד שנעבור מזה. סרו בדרך אחר."],[5,"בתר דנפקו מההוא וכו':","אחר שיצאו ממקום ההוא, אמר להם, בדרך ההוא האחר, המסוכן, היו הולכים פעם אחת, כהן אחד חכם וכהן אחד עם הארץ עמו. קם עליו כהן העם הארץ במקום ההוא והרגו. מיום ההוא והלאה, כל מי שעובר במקום ההוא, מסתכן בעצמו, ומתחברים שם שודדי הרים, והורגים ומקפחים בני אדם. ואלו היודעים מזה אינם עוברים שם. ומבקש הקב\"ה את הדם של כהן ההוא בכל יום."],[6,"פתח ואמר, עוד וכו':","פתח ואמר, עוד היום בנוב לעמוד וגו'. כבר בארוהו בעלי הישיבה. אבל אני איני אומר לכם כך, אלא סוד הדבר למדתי. \u0003עוד היום,\u0004 מי הוא יום הזה. אלא כך כתוב, ויקח אהרן את אלישבע בת עמינדב, והוא סוד על כנסת ישראל שהיא המלכות, המכונה אלישבע, על שם שבע ספירות שבה, שאהרן הוא השושבין שלה, לתקן ביתה ולשמש אותה, ולהביאה אל המלך, שהוא ז\"א, להתחבר יחד. מכאן ולהלאה, כל כהן המשמש במקדש, הוא שושבין של המלכות, כמו אהרן."],[7,"אחימלך כהנא רבא וכו':","אחימלך, כהן גדול עליון היה, וכל אלו הכהנים שעמו, כולם היו שושבינים של המטרוניתא, שהיא המלכות. כיון שנהרגו, נשארה המטרוניתא לבדה בלי זווג עם ז\"א, ונאבד השושבין שלה, ולא נמצא מי שישמש לפניה ויתקן ביתה וישמח אותה להזדווג עם המלך. אז מיום ההוא, עברה לצד שמאל, ועומדת על העולם אורבת על כל, הרג לשאול ולבניו, ומתו מישראל כמה אלפים וכמה רבבות, ועד עתה אותו החטא תלוי, עד שבא סנחריב, והחריד הכל."],[8,"ודא הוא עוד וכו':","וזה הוא, עוד היום בנוב, זה הוא יום העליון, ומי הוא, זו כנסת ישראל, שהיא המלכות, שאבדה השושבין שלה, ההיא, שנשארה בלי ימין, להתדבק בשמאל כי הכהן הוא ימין. ומשום זה עוד היום בנוב לעמוד, לתבוע דין על הריגת נוב עיר הכהנים, עד שבחטא ההוא, מסיים שם הכתוב, והלבנון באדיר יפול."],[9,"ת\"ח, כתיב וכו':","בוא וראה, כתוב, גבעת שאול נסה. (ישעיה יוד). שואל. שאול למה הוא כאן. ומשיב. אלא משום שהוא הרג הכהנים שבנוב, וגרם שזרוע הימין יעקר מן העולם, כנ\"ל. ומחמת חטאו זה, נסו בני מקומו, גבעת שאול, בפני מלך אשור. אף כאן, מיום ההוא לא עבר אדם באותו מקום כדי שלא יסכן את עצמו. אמר לו ר' יוסי לר' חייא, ולא אמרתי לך אולי אדם גדול הוא."]],[[0,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (תהלים ח) ה' אֲדנֵינוּ מָה אַדִּיר שִׁמְךְ בְּכָל הָאָרֶץ. ה' אֲדנֵינוּ - כְּשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לִשְׁבֹּר אֶת כֹּחַ הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, מְחַזֵּק דִּינוֹ עֲלֵיהֶם וְשׁוֹבֵר אוֹתָם, וּמַעֲבִיר מִלְּפָנָיו אֶת הַשַּׁלִּיט שֶׁלָּהֶם."],[1,"","אַשֶׁר תְּנָה הוֹדְךְ עַל הַשָּׁמָיִם, אֲשֶׁר נָתַתָּ הָיָה צָרִיךְ, אוֹ תְּנָה הוֹדְךְ. מַהוּ אֲשֶׁר תְּנָה הוֹדְךְ? אֶלָּא זֶהוּ סוֹד שֶׁל הַנָּהָר הֶעָמֹק שֶׁל הַכֹּל, וְדָוִד בִּקֵּשׁ בַּקָּשָׁתוֹ לְהַשְׁפִּיעַ מִמֶּנּוּ עַל הַשָּׁמַיִם, וְזֶהוּ אֲשֶׁר, כַּנֶּאֱמַר (שמות ג) אֶהְיֶה אֲשֶׁר אֶהְיֶה."],[2,"","בְּשָׁעָה שֶׁהַנָּהָר הַזֶּה הֶעָמֹק שֶׁל הַכֹּל שׁוֹפֵעַ וְיוֹצֵא עַל הַשָּׁמַיִם, אָז הַכֹּל בְּשִׂמְחָה, וְהַגְּבִירָה מִתְעַטֶּרֶת בַּמֶּלֶךְ, וְכָל הָעוֹלָמוֹת בְּשִׂמְחָה. וְהַשִּׁלְטוֹן שֶׁל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת מָעֳבָר מִלִּפְנֵי הַגְּבִירָה, וְאָז זוֹקְפִים רֹאשׁ כָּל הָאֲחוּזִים בָּהּ."],[3,"","בֵּין כָּךְ רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא, וּמַשָּׂא אֶחָד לְפָנָיו. אָמַר רַבִּי חִיָּיא, נֵלֵךְ, אוּלַי הָאִישׁ הַזֶּה עוֹבֵד עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת הוּא, אוֹ עַם הָאָרֶץ הוּא, וְאָסוּר לְהִשְׁתַּתֵּף עִמּוֹ בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי, נֵשֵׁב כָּאן וְנִרְאֶה, אוּלַי הוּא אִישׁ גָּדוֹל."],[4,"","בֵּין כָּךְ עָבַר לִפְנֵיהֶם, וְאָמַר לָהֶם, בַּסִּבּוּב שֶׁל הַמַּעֲבָר הַמְסֻכָּן הַזֶּה צָרִיךְ לִוּוּי, וַאֲנִי יוֹדֵעַ דֶּרֶךְ אַחֶרֶת, וְנִסְטֶה מִכָּאן, וַאֲנִי רָצִיתִי לוֹמַר לָכֶם, שֶׁלֹּא אֶחֱטָא בָכֶם וְלֹא אֶעֱבר עַל מַה שֶּׁכָּתוּב (ויקרא יט) וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל, וְאַתֶּם כְּמוֹ סוּמִים בַּדֶּרֶךְ הַזּוֹ, וְלֹא תִסְתַּכְּנוּ בְנַפְשְׁכֶם. אָמַר רַבִּי יוֹסֵי, בָּרוּךְ הָרַחֲמָן שֶׁחִכִּינוּ כָּאן. הִתְחַבְּרוּ עִמּוֹ. אָמַר לָהֶם, לֹא לְדַבֵּר שׁוּם דָּבָר כָּאן עַד שֶׁנַּעֲבֹר בָּזֶה. סָטוּ לְדֶרֶךְ אַחֶרֶת."],[5,"","אַחַר שֶׁיָּצְאוּ מֵאוֹתוֹ מָקוֹם, אָמַר לָהֶם, בְּאוֹתָהּ הַדֶּרֶךְ הָאַחֶרֶת הָיוּ הוֹלְכִים פַּעַם אֶחָד כֹּהֵן חָכָם, וְכֹהֵן עַם הָאָרֶץ אֶחָד עִמּוֹ. קָם אוֹתוֹ עַם הָאָרֶץ עָלָיו בְּאוֹתוֹ מָקוֹם וַהֲרָגוֹ. מֵאוֹתוֹ יוֹם, כָּל מִי שֶׁעוֹבֵר בְּאוֹתוֹ מָקוֹם, מְסַכֵּן אֶת נַפְשׁוֹ, וַהֲרֵי מִתְחַבְּרִים שָׁם שׁוֹדְדֵי הָרִים וְהוֹרְגִים וּמְקַפְּחִים אֶת בְּנֵי הָאָדָם, וְאֵלֶּה שֶׁיּוֹדְעִים לֹא עוֹבְרִים שָׁם, וּמְבַקֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא דַּם אוֹתוֹ הַכֹּהֵן בְּכָל יוֹם."],[6,"","פָּתַח (ישעיה י) וְאָמַר, עוֹד הַיּוֹם בְּנֹב לַעֲמֹד וְגוֹ'. הֲרֵי בֵּאֲרוּהָ אוֹתָם רָאשֵׁי הַיְשִׁיבָה, אֲבָל אֲנִי לֹא אוֹמֵר לָכֶם כָּךְ, אֶלָּא שֶׁסּוֹד הַדָּבָר לָמַדְנוּ. עוֹד הַיּוֹם - אֵיזֶה יוֹם זֶה? אֶלָּא כָּךְ כָּתוּב, (שמות ו) וַיִּקַּח אַהֲרֹן אֶת אֱלִישֶׁבַע בַּת עַמִּינָדָב. וְסוֹד הוּא עַל כְּנֶסֶת יִשְׂרָאֵל, שֶׁאַהֲרֹן הוּא שׁוֹשְׁבִינָהּ, לְתַקֵּן אֶת בֵּיתָהּ וּלְשַׁמֵּשׁ אוֹתָהּ וּלְהַכְנִיסָהּ לַמֶּלֶךְ לְהִזְדַּוֵּג כְּאֶחָד. מִכָּאן וָהָלְאָה, כָּל כֹּהֵן שֶׁמְּשַׁמֵּשׁ בַּמִּקְדָּשׁ, הוּא כְּמוֹ אַהֲרֹן."],[7,"","אֲחִימֶלֶךָ הָיָה כֹּהֵן גָּדוֹל עֶלְיוֹן, וְכָל אוֹתָם הַכֹּהֲנִים עִמּוֹ הָיוּ שׁוֹשְׁבִינֵי הַגְּבִירָה. כֵּיוָן שֶׁנֶּהֶרְגוּ, נִשְׁאֲרָה הַגְּבִירָה לְבַדָּהּ, וְאָבַד הַשּׁוֹשְׁבִין שֶׁלָּהּ, וְלֹא נִמְצָא מִי שֶׁמְּשַׁמֵּשׁ לְפָנֶיהָ וִיתַקֵּן בֵּיתָהּ וִישַׂמַּח אוֹתָהּ לְהִזְדַּוֵּג עִם הַמֶּלֶךְ. וְאָז מֵאוֹתוֹ יוֹם הִיא עָבְרָה לִשְׂמֹאל, וְעוֹמֶדֶת עַל הָעוֹלָם, אוֹרֶבֶת לַכֹּל. הָרְגָה אֶת שָׁאוּל וּבָנָיו, וְאִבְּדָה מֵהֶם אֶת הַמְּלוּכָה, מֵתוּ מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים וְכַמָּה רְבָבוֹת. וְעַד עַכְשָׁו הָיָה אוֹתוֹ הַחֵטְא תָּלוּי, עַד שֶׁבָּא סַנְחֵרִיב וְהִרְגִּיז אֶת הַכֹּל."],[8,"","וְזְהִוּ עוֹד הַיּוֹם בְּנֹב, זֶהוּ יוֹם עֶלְיוֹן, וּמִיהוּ? זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁאִבְּדָה אֶת הַשּׁוֹשְׁבִינִים שֶׁלָּהּ, אוֹתָהּ שֶׁנִּשְׁאֲרָה לְלֹא יָמִין (שהיה לו) לְהִדָּבֵק בַּשְּׂמֹאל, שֶׁהַכֹּהֵן הוּא יָמִין, (ומשום כך היה לו להתדבק בשמאל) וּמִשּׁוּם כָּךְ עוֹד הַיּוֹם בְּנֹב לַעֲמֹד."],[9,"","בֹּא רְאֵה, כָּתוּב גִּבְעַת שָׁאוּל נָסָה. לָמָּה כָּאן שָׁאוּל? אֶלָּא מִשּׁוּם שֶׁהוּא הָרַג אֶת הַכֹּהֲנִים וְגָרַם שֶׁתֵּעָקֵר מִן הָעוֹלָם זְרוֹעַ יָמִין - אַף כָּאן מֵאוֹתוֹ יוֹם לֹא עָבַר אִישׁ בְּאוֹתוֹ מָקוֹם, כְּדֵי שֶׁלֹּא יִסְתַּכֵּן בְּנַפְשׁוֹ. אָמַר לוֹ רַבִּי יוֹסֵי לְרַבִּי חִיָּיא, וְלֹא אָמַרְתִּי לְךְ אוּלַי הוּא אִישׁ גָּדוֹל?"]]],[["פָּתַח וְאָמַר, (משלי ג׳:י״ג) אַשְׁרֵי אָדָם מָצָא חָכְמָה. אַשְׁרֵי אָדָם, כְּגוֹן אֲנָן, דְּאַשְׁכַּחְנָא לָךְ, וְיָדַעְנָא מִינָךְ מִלָּה דְּחָכְמְתָא. וְאָדָם יָפִיק תְּבוּנָה, כְּגוֹן אֲנָן, דְּאוֹרִיכְנָא לָךְ לְאִתְחַבְּרָא בַּהֲדָךְ. וְדָא הוּא בַּר נָשׁ דְּזַמִּין לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא נְבִזְבְּזָא בְּאָרְחָא, אַנְפּוֹי דִּשְׁכִינְתָּא, וְעַל דָּא כְּתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. אָזְלוּ.","פָּתַח הַהוּא גַּבְרָא וְאָמַר (תהילים כ״ד:א׳) לְדָוִד מִזְמוֹר לַיְיָ' הָאָרֶץ וּמְלוֹאָהּ וְגוֹ'. לְדָוִד מִזְמוֹר בַּאֲתָר חַד, וּבַאֲתַר אַחֲרָא מִזְמוֹר לְדָוִד, מַה בֵּין הַאי (ק\"ע ע\"א) לְהַאי. אֶלָּא לְדָוִד מִזְמוֹר, שִׁירָתָא דְּקָאָמַר דָּוִד, עַל כְּנֶסֶת יִשְׂרָאֵל. מִזְמוֹר לְדָוִד, שִׁירָתָא דְּקָאָמַר דָּוִד, עַל גַּרְמֵיהּ.","לַיְיָ' (כ\"ב ע\"ב) הָאָרֶץ וּמְלוֹאָהּ. לַיְיָ': דָּא קוּדְשָׁא בְּרִיךְ הוּא. הָאָרֶץ וּמְלוֹאָהּ: דָּא כְּנֶסֶת יִשְׂרָאֵל, וְכָל אוּכְלוֹסִין דִּילָהּ, דְּמִתְחַבְּרָן בַּהֲדָהּ, וְאִקְרוּן מְלוֹאָהּ וַדַּאי הוּא. כְּמָה דְּאַתְּ אָמֵר, (ישעיהו ו׳:ג׳) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ תֵּבֵל וְיוֹשְׁבֵי בָהּ: דָּא הוּא אַרְעָא דִּלְתַתָּא, דְּאִקְרֵי תֵּבֵל, וַאֲחִידַת בְּדִינָא (דעלמא) דִּלְעֵילָּא, הֲדָא הוּא דִּכְתִּיב, (תהילים ט׳:ט׳) וְהוּא יִשְׁפוֹט תֵּבֵל בְּצֶדֶק, בֵּין לְחָד, בֵּין לְעַמָּא חַד, בֵּין לְכָל עָלְמָא, מֵהַאי דִּינָא הוּא אִתְּדָן.","תָּא חֲזֵי, פַּרְעֹה מֵהַאי דִּינָא יָנִיק, עַד דְּאִתְאֲבִידוּ הוּא וְכָל עַמֵּיהּ. כֵּיוָן דְּהַאי דִּינָא אִתְּעַר עָלֵיהּ, הַהוּא מְמָנָא דְּאִתְמָנָא עֲלַיְיהוּ בְּשֻׁלְטָנוּתָא, אִתְעָדֵי וְאִתְעֲבָר, כְּדֵין כֻּלְּהוּ דִּלְתַתָּא, אִתְאֲבִידוּ, דִּכְתִּיב וַיָּסַר אֶת אוֹפַן מַרְכְּבוֹתָיו. מַאי אוֹפַן מַרְכְּבוֹתָיו. מַרְכְּבוֹתָיו דְּפַרְעֹה. וּמַאן אִיהוּ הַהוּא אוֹפַן דִּלְהוֹן, הַהוּא מְמָנָא דְּשָׁלִיט עֲלַיְיהוּ. וְעַל דָּא מִיתוּ כֻּלְּהוּ בְּיַמָּא. אֲמַאי בְּיַמָּא, אֶלָּא יַמָּא עִלָּאָה אִתְּעַר עֲלַיְיהוּ, וְאִתְמְחוּ (נ\"א ואתמסרו) בִּידָהָא. וּבְגִין כַּךְ טֻבְּעוּ בַּיָּם סוֹף כְּתִיב. אָמַר רִבִּי יוֹסֵי וַדַּאי הָכִי הוּא, וְעַל דָּא כְּתִיב, טֻבְּעוּ בְּיַם סוּף. סוֹפָא דְּדַרְגִּין.","רִבִּי חִיָּיא אָמַר, וַיְנַהֲגֵהוּ בִּכְבֵדוּת. בִּכְבֵדוּת מַהוּ. אֶלָּא מִכָּאן אוֹלִיפְנָא, דִּבְהַהוּא דַּבְּרוּתָא דְּאִתְדָּבַּר בֵּיהּ בַּר נָשׁ, מְדַבְּרִין לֵיהּ. בְּפַרְעֹה כְּתִיב (שמות ט׳:ז׳) וַיִּכְבַּד לֵב פַּרְעֹה. בְּהַהוּא מִלָּה, דָּבַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בִּכְבֵדוּת מַמָּשׁ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע, אַתְּ אוֹקִיר לִבָּךְ. אֲנָא אַדְבַּר לָךְ בְּהַאי, עַל דָּא וַיְנַהֲגֵהוּ בִּכְבֵדוּת.","וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל וְגוֹ'. וַיֹּאמֶר מִצְרַיִם, דָּא מְמָנָא דְּאִתְמְנֵי עַל מִצְרָאֵי. אָמַר רִבִּי יוֹסֵי, הַאי מִלָּה קַשְׁיָא, כֵּיוָן דְּאַעְבְּרוּ לֵיהּ מִשּׁוּלְטָנוּתֵיה, הֵיךְ יָכִיל הוּא לְמִרְדַּף אֲבַתְרַיְיהוּ דְּיִשְׂרָאֵל.","אֶלָּא וַדַּאי הָכִי הוּא. אֲבָל דָּא וַיֹּאמֶר מִצְרַיִם, מִצְרַיִם דִּלְתַתָּא. כִּי יְיָ' נִלְחָם לָהֶם בְמִצְרָיִם, מִצְרַיִם דִּלְעֵילָּא, דְּכֵיוָן דְּאִתְבַּר חֵילֵהוֹן מִלְּעֵילָּא, כְּדֵין אִתְּבַר חֵילָא וְתּוּקְפָּא דִּלְהוֹן לְתַתָּא, הֲדָא הוּא דִּכְתִּיב כִּי יְיָ' נִלְחָם לָהֶם בְמִצְרָיִם. בְּמִצְרַיִם דַּיְקָא. דָּא הוּא תּוּקְפָּא דִּלְהוֹן דִּלְעֵילָּא. וְדָא הוּא דְּאוּקְמוּהָ מֶלֶךְ מִצְרַיִם סְתָם. הָכָא, וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל, דְּחָמוּ דְּהָא אִתְּבַר חֵילֵיהוֹן, וְתּוּקְפָּא דִּלְהוֹן, דִּלְעֵילָּא.","תָּא חֲזֵי, כַּד אִתְּעָרַת הַאי כְּנֶסֶת יִשְׂרָאֵל, אִתְעֲרוּ כָּל אינון דאחידן בה, וכלהו אחרנין דלתתא, וישראל לעילא מכלהו, דהא אינון נטלי לה בגופא דאילנא, והא אוקמוה. ובגיני כך ישראל אחידן בה, יתיר מכל עובדי כוכבים ומזלות. וכד אינון מתערין, (כל עמים עכו\"ם) אתבר תוקפהון מאינון דשלטי עלייהו.","תָּא חֲזִי, הַאי מְמָנָא שֻׁלְטָנָא דְּמִצְרָאֵי, דָּחִיק לוֹן לְיִשְׂרָאֵל, בְּכַמָּה שִׁעְבּוּדִין, כְּמָה דְּאוּקְמוּהָ. לְבָתַר דְּאִתְבַּר הוּא בְּקַדְמִיתָא, אִתְּבָּרוּ אִינּוּן מַלְכְּוָותָא (ס\"א מלתתא), הֲדָא הוּא דִכְתִיב כִּי יְיָ' נִלְחָם לָהֶם בְּמִצְרַיִם. נִלְחָם לָהֶם ודַּאי.","\u0003ס\"א תוספתא\u0004 (שמות י״ד:י״ט) ויִּסַּע מַלְאַךְ הָאֱלהִים וגוֹ'. (מתניתין) עַד לָא (ס\"א אשתקע) אִשְׁתְּכַח אֲוִירָא דַּכְיָא, וְלָא נְהִירִין, אֲבָנִין נְקִיבָן הֲווֹ סְתִימָאן. תְּלַת רוּחִין דִּכְלִילָן בִּתְלַת, הֲווֹ שְׁקִיעָן. וּמַיִין סְתִימָן תְּחוֹת נוּקְבֵי. בְּשִׁבְעִין וּתְרֵין אַתְוָון אִתְהַדָּרוּ לְאַתְרַיְיהוּ אִינּוּן אֲבָנִין (ס\"א דרין)."],[[0,"פתח ואמר אשרי וכו':","פתח ואמר, אשרי אדם מצא חכמה. \u0003אשרי אדם,\u0004 היינו כמו אנחנו שמצאנו אותך, וידענו ממך דבר חכמה. \u0003ואדם יפיק תבונה,\u0004 כמו אנו שחכינו לך להתחבר עמך. וזה הוא אדם, שהזמין לו הקב\"ה אוצר בדרך, פני השכינה, ועל זה כתוב, ואורח צדיקים כאור נגה. הלכו."],[1,"פתח ההוא גברא וכו':","פתח איש ההוא ואמר, לדוד מזמור לה' הארץ ומלואה וגו'. שואל, לדוד מזמור, כתוב במקום אחד, ובמקום אחר כתוב, מזמור לדוד, מה בין זה לזה. ומשיב, אלא לדוד מזמור, יורה על השירה שאמר דוד על כנסת ישראל, שהיא המלכות, מזמור לדוד יורה על השירה שאמר דוד על עצמו."],[2,"לה' הארץ ומלואה: לה'","זה הקב\"ה, דהיינו ז\"א, \u0003הארץ ומלואה,\u0004 זה כנסת ישראל, שהיא המלכות, וכל ההמון שלה המתחבר עמה, ונקראים מלואה, ודאי הוא כן, כמש\"א מלא כל הארץ כבודו. \u0003תבל ויושבי בה,\u0004 זה הוא ארץ שלמטה שנקרא תבל, ונאחזת בדין של מעלה, דהיינו של המלכות, ז\"ש, והוא ישפוט תבל בצדק. בין ליחיד, בין לעם אחד, בין לכל העולם, מדין הזה הוא נידון. דהיינו מדין המלכות שנקראת צדק."],[3,"תא חזי פרעה וכו':","בוא וראה, פרעה ינק מדין הזה, עד שנאבדו הוא וכל עמו. כיון שדין הזה של המלכות, התעורר עליהם, ממונה ההיא, שנתמנה עליהם לשלוט, הוסר ונעבר, ואז, כולם שלמטה נאבדו, שכתוב, ויסר את אופן מרכבותיו. מי הוא אופן מרכבותיו, היינו מרכבותיו של פרעה. ומי הוא האופן שלהם. היינו ממונה ההיא השולט עליהם. וע\"כ מתו כולם בים. ולמה בים. אלא ים העליון, שהוא המלכות, התעורר עליהם, ונמחו על ידו. וע\"כ טבעו בים סוף כתוב. א\"ר יוסי, ודאי כן הוא. וע\"כ כתוב, טבעו בים סוף, שפירושו, סוף המדרגות, דהיינו המלכות, שנמחו על ידה."],[4,"רבי חייא אמר וכו':","רח\"א, וינהגהו בכבדות, מהו בכבדות. אלא מכאן למדנו, שבדרך שהאדם הולך מוליכים אותו. בפרעה כתוב, \u0003ויכבד\u0004 לב פרעה, בדבר הזה הוליך אותו הקב\"ה, \u0003בכבדות\u0004 ממש. אמר לו הקב\"ה אתה הכבדת את לבך אני מוליך אותך בזה, וע\"כ וינהגהו בכבדות."],[5,"ויאמר מצרים אנוסה וגו':","ויאמר מצרים, זהו הממונה שנתמנה על מצרים, דהיינו השר שלהם במרום, א\"ר יוסי, דבר זה קשה, כיון שהעבירו אותו מממשלתו, איך היה יכול לרדוף אחרי ישראל."],[6,"אלא ודאי הכי וכו':","ומשיב, אלא ודאי כן הוא, אבל הכתוב, ויאמר מצרים אינו הממונה שלהם, אלא מצרים של מטה, כי ה' נלחם להם במצרים, היינו מצרים של מעלה, הממונה שלהם. כי כיון שנשבר כחם מלמעלה, נשבר כחם וגבורתם למטה, ז\"ש, כי ה' נלחם להם במצרים, במצרים בדיוק, זה הוא תוקפם של מעלה. דהיינו הממונה שלהם. וזה שהעמדנו, לעיל (שמות אות רצ\"ה) שבמקום שנאמר מלך מצרים סתם, דהיינו שלא נאמר פרעה, הכונה הוא על שר הממונה על מצרים. אף כאן במצרים הוא הממונה על מצרים. וכאן שנאמר ויאמר מצרים אנוסה מפני בני ישראל, היינו מצרים שלמטה, שראו שנשבר כוחם וגבורתם שלמעלה, דהיינו הממונה שלהם."],[7,"תא חזי כד וכו':","בוא וראה, כשמתעוררת כנסת ישראל זו, שהיא המלכות, מתעוררים כל אלו האחוזים בה וכל האחרים של מטה, דהיינו כל האומות, וישראל למעלה מכולם, משום שהם לוקחים אותה בגוף האילן, דהיינו, כשהיא מחוברת בז\"א, שנקרא עץ החיים, ומשום זה ישראל נאחזים בה יותר מכל אומות העולם. וכשהם מתעוררים להרע לישראל, נשבר תוקפם של השולטים עליהם, דהיינו הממונים שלהם של מעלה."],[8,"תא חזי, האי וכו':","בוא וראה, ממונה ההוא המושל של מצרים, הצר לישראל בכמה שעבודים, כמו שהעמדנו. ולאחר שהוא נשבר מתחילה, נשברו הממלכות של מטה. ז\"ש כי ה' נלחם להם במצרים. נלחם להם ודאי."],[9,"ויסע מלאך האלקים וגו':","(מתניתין) מטרם שנמצא אויר הטהור, ולא האיר, היו האבנים הנקובות, סתומות. ג' רוחות הכלולים בג' היו שקועים. ומים היו סתומים תחת הנקבים. בשבעים ושתים אותיות חוזרות למקומם אלו האבנים."],[9,"","ביאור הדברים. כבר ידעת סדר יציאת האורות בסוד ג' נקודות חולם שורק חירק, (כמ\"ש לעיל דף ט\"ו ד\"ה ההוא) שמתחילה עולה המלכות לבינה, מתחת החכמה שלה, ואז נופלים בינה ותו\"מ שלה למטה ממדרגתה, דהיינו לז\"א, והיא נשארת רק בב' ספירות כו\"ח, ובב' אורות רוח נפש, שזה נבחן שנתנקבה הבינה, שלא נשאר בה אלא אור נקבה המאיר ממטה למעלה, וע\"כ מכונות הספירות שלה בשם \u0003אבנין נקובין.\u0004 וז\"ס נקודת החולם."],[9,"","ואח\"כ, ע\"י הארת ע\"ב ס\"ג דא\"ק, חוזרת המלכות ויורדת מן הבינה למקומה, ואז חוזרים הבינה ותו\"מ ועולים מז\"א אל הבינה, ושוב נשלמה הבינה בה' ספירות כח\"ב תו\"מ, ובה' אורות נרנח\"י, ונסתמו הנקבים, כי נתבטלה הנוקביות שבה, אבל האורות סתומים, מחמת חסרון חסדים, שאין החכמה יכולה להאיר בלי התלבשות החסדים. וז\"ס נקודת השורק."],[9,"","וז\"ש \u0003עד לא אשתכח אוירא דכיא ולא נהיר,\u0004 דהיינו מטרם שנגלו החסדים השלמים המכונים אוירא דכיא, להלביש את החכמה שבקו השמאל של הבינה, \u0003אבנין נקיבן הוו סתימאן,\u0004 דהיינו שנסתמו הנקבים, מחמת חזרת הבינה ותו\"מ למדרגתם, וכבר היתה יכולת להאיר ממעלה למטה בבחינת אור זכר, אבל גם האורות נסתמו בה, כי אין החכמה מאירה בלי חסדים."],[9,"","ונודע, שבעת שהבינה מעלה אליה את הבינה ותו\"מ שלה מתוך ז\"א, עולים עמהם אליה, גם חג\"ת דז\"א המלבישים בינה ותו\"מ האלו. ואז כשז\"א היא בבינה, נבחן ז\"א, \u0003לג' רוחין דכליל בג',\u0004 ג' רוחין, היינו חג\"ת דז\"א, שספירותיו בסוד רוח. דכליל בג', היינו בבינה ותו\"מ דבינה שהם מלבושים עליהם וז\"ש, \u0003תלת רוחין דכלילן בתלת הוו שקיען,\u0004 שהארתם לא היתה ניכרת, כי אם היתה ניכרת הארת החסדים שבז\"א, אז היתה החכמה מתלבשת בחסדים, והאבנין דבינה לא היו סתומים. וז\"ש \u0003ומיין סתימן,\u0004 שהחסדים דז\"א היו סתומים \u0003תחות נוקבי\u0004, כלומר, אע\"פ שיש בז\"א בחינת נוקבא, דהיינו המסך דחירק, שעליו מתגלה אח\"כ אור החסדים אבל עתה היו המים סתומים, כי כל בחינת ז\"א היתה שקועה כנ\"ל. אלא אח\"כ מתעורר ז\"א עם מסך דחירק שבו ומעלה מ\"ן, ומוציא החסדים להלביש את החכמה. וז\"ש \u0003בשבעין ותרין אתוון אתהדרו לאתרייהו אינון אבנין,\u0004 שבע\"ב אותיות שבפסוק ויסע, שה\"ס קו ימין (כמ\"ש להלן אות קל\"ה) שהן גילוי החסדים, מתלבשת החכמה שבקו שמאל דבינה בחסדים האלו, ואבנין סתימאן שבה, חוזרים למקומם, דהיינו שנפתחה הארתם."]],[[0,"","פָּתַח וְאָמַר, (משלי ג) אַשְׁרֵי אָדָם מָצָא חָכְמָה. אַשְׁרֵי אָדָם - כְּמוֹ אָנוּ שֶׁמָּצָאנוּ אוֹתְךְ וְיָדַעְנוּ מִמְּךְ דְּבַר חָכְמָה. וְאָדָם יָפִיק תְּבוּנָה - כְּמוֹ אָנוּ שֶׁחִכִּינוּ לְךְ לְהִתְחַבֵּר עִמְּךְ, וְזֶהוּ אָדָם שֶׁמְּזַמֵּן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מַתָּנָה בַּדֶּרֶךְ, פְּנֵי הַשְּׁכִינָה, וְעַל זֶה כָּתוּב (משלי ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ. הָלְכוּ."],[1,"","פָּתַח אוֹתוֹ הָאִישׁ וְאָמַר, (תהלים כב) לְדָוִד מִזְמוֹר לַה' הָאָרֶץ וּמְלֹאָהּ וְגוֹ'. לְדָוִד מִזְמוֹר בְּמָקוֹם אֶחָד, וּבְמָקוֹם אַחֵר מִזְמוֹר לְדָוִד. מַה בֵּין זֶה לָזֶה? אֶלָּא לְדָוִד מִזְמוֹר - הַשִּׁירָה שֶׁאָמַר דָּוִד עַל כְּנֶסֶת יִשְׂרָאֵל. מִזְמוֹר לְדָוִד - הַשִּׁירָה שֶׁדָּוִד אָמַר עַל עַצְמוֹ."],[2,"","לַה' הָאָרֶץ וּמְלֹאָהּ. לַה' - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. הָאָרֶץ וּמְלֹאָהּ - זוֹ כְּנֶסֶת יִשְׂרָאֵל וְכָל הָאוּכְלוּסִין שֶׁלָּהּ שֶׁמִּתְחַבְּרִים עִמָּהּ, וְנִקְרָאִים מְלֹאָהּ וַדַּאי הוּא, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ו) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. תֵּבֵל וְיֹשְׁבֵי בָהּ - זוֹהִי אֶרֶץ שֶׁל מַטָּה שֶׁנִּקְרֵאת תֵּבֵל, וַאֲחוּזָה בַּדִּין (של עולם) שֶׁל מַעְלָה. זֶהוּ שֶׁכָּתוּב (תהלים ט) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. בֵּין לְאֶחָד, בֵּין לְעַם אֶחָד, בֵּין לְכָל הָעוֹלָם - מֵהַדִּין הַזֶּה הוּא נִדּוֹן."],[3,"","בֹּא רְאֵה, פַּרְעֹה יָנַק מֵהַדִּין הַזֶּה עַד שֶׁאָבְדוּ הוּא וְכָל עַמּוֹ. כֵּיוָן שֶׁדִּין זֶה הִתְעוֹרֵר עָלָיו, אוֹתוֹ מְמֻנֶּה שֶׁהִתְמַנָּה עֲלֵיהֶם בַּשִּׁלְטוֹן, הוּזַז וְהָעֳבַר, וְאָז כָּל אֵלֶּה שֶׁלְּמַטָּה נֶאֶבְדוּ, שֶׁכָּתוּב וַיָּסַר אֵת אֹפַן מַרְכְּבתָיו. מַה זֶּה אֹפַן מַרְכְּבֹתָיו? מֶרְכְּבוֹתָיו שֶׁל פַּרְעֹה. וּמִי הוּא אוֹתוֹ אוֹפַן שֶׁלָּהֶם? אוֹתוֹ מְמֻנֶּה שֶׁשּׁוֹלֵט עֲלֵיהֶם, וְעַל זֶה מֵתוּ כֻלָּם בַּיָּם. לָמָּה בַּיָּם? אֶלָּא הַיָּם הָעֶלְיוֹן הִתְעוֹרֵר עֲלֵיהֶם וְנִמְחוּ (ונמסרו) בְּיָדֶיהָ, וְלָכֵן כָּתוּב טֻבְּעוּ בְּיַם סוּף. אָמַר רַבִּי יוֹסֵי, וַדַּאי כָּךְ הוּא! וְעַל זֶה כָּתוּב טֻבְּעוּ בְּיַם סוּף, סוֹף כָּל הַדְּרָגוֹת."],[4,"","רַבִּי חִיָּיא אָמַר, וַיְנַהֲגֵהוּ בִּכְבֵדֻת, מַה זֶּה בִּכְבֵדֻת? אֶלָּא מִכָּאן לָמַדְנוּ, שֶׁבְּדֶרֶךְ שֶׁאָדָם הוֹלֵךְ מוֹלִיכִים אוֹתוֹ. כָּתוּב בְּפַרְעֹה וַיִּכְבַּד לֵב פַּרְעֹה, וּבְאוֹתוֹ דָבָר הִנְהִיג אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבֵדוּת מַמָּשׁ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: רָשָׁע, אַתָּה מַכְבִּיד אֶת לִבְּךְ? אֲנִי אַנְהִיג אוֹתְךְ בָּזֶה. וְעַל כָּךְ וַיְנַהֲגֵהוּ בִּכְבֵדֻת."],[5,"","וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל וְגוֹ'. וַיֹּאמֶר מִצְרַיִם - זֶהוּ הַמְמֻנֶּה שֶׁהִתְמַנָּה עַל הַמִּצְרִים. אָמַר רַבִּי יוֹסֵי, דָּבָר זֶה קָשֶׁה, כֵּיוָן שֶׁהֶעֱבִירוּ אוֹתוֹ מִשִּׁלְטוֹנוֹ, אֵיךְ יָכֹל הוּא לִרְדֹּף אַחֲרֵי יִשְׂרָאֵל?"],[6,"","אֶלָּא וַדַּאי הוּא כָּךְ! אֲבָל זֶה וַיֹּאמֶר מִצְרַיִם - מִצְרַיִם שֶׁלְּמַטָּה. כִּי ה' נִלְחָם לָהֶם בְּמִצְרָיִם - מִצְרַיִם שֶׁלְּמַעְלָה. שֶׁכֵּיוָן שֶׁנִּשְׁבָּר כֹּחָם מִלְמַעְלָה, אָז נִשְׁבָּר הַכֹּחַ וְהַתֹּקֶף שֶׁלָּהֶם לְמַטָּה. זֶהוּ שֶׁכָּתוּב כִּי ה' נִלְחָם לָהֶם בְּמִצְרָיִם. בְּמִצְרַיִם דַּוְקָא. זֶהוּ הַתֹּקֶף שֶׁלָּהֶם שֶׁלְּמַעְלָה. וְזֶהוּ שֶׁבֵּאֲרוּהָ מֶלֶךְ מִצְרַיִם סְתָם. כָּאן וַיֹּאמֶר מִצְרַיִם אָנוּסָה מִפְּנֵי יִשְׂרָאֵל, שֶׁרָאוּ שֶׁהֲרֵי נִשְׁבַּר כֹּחָם וְהַתֹּקֶף שֶׁלָּהֶם שֶׁלְּמַעְלָה."],[7,"","בֹּא רְאֵה, כְּשֶׁמִּתְעוֹרֶרֶת כְּנֶסֶת יִשְׂרָאֵל הַזּוֹ, מִתְעוֹרְרִים כָּל אוֹתָם שֶׁאֲחוּזִים בָּהּ, וְכָל הָאֲחֵרִים שֶׁלְּמַטָּה, וְיִשְׂרָאֵל מֵעַל כֻּלָּם, שֶׁהֲרֵי הֵם נוֹטְלִים אוֹתָהּ בְּגוּף הָאִילָן, וַהֲרֵי פֵּרְשׁוּהָ. וְלָכֵן יִשְׂרָאֵל אֲחוּזִים בָּהּ יוֹתֵר מִכָּל עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. וּכְשֶׁהֵם מִתְעוֹרְרִים, (כל עמים עכו\"ם) נִשְׁבָּר תָּקְפָּם מֵאוֹתָם שֶׁשּׁוֹלְטִים עֲלֵיהֶם."],[8,"","בֹּא רְאֵה, הַמְמֻנֶּה הַזֶּה הַשַּׁלִּיט עַל הַמִּצְרִים, דָּחַק אֶת יִשְׂרָאֵל בְּכַמָּה שִׁעְבּוּדִים, כְּמוֹ שֶׁבֵּאֲרוּהָ. אַחַר שֶׁהוּא נִשְׁבַּר בַּתְּחִלָּה, נִשְׁבְּרוּ אוֹתָן מַלְכֻיּוֹת (מלמטה). זֶהוּ שֶׁכָּתוּב כִּי ה' נִלְחָם לָהֶם בְּמִצְרָיִם. נִלְחָם לָהֶם וַדַּאי."],[9,"","וַיִּסַּע מַלְאַךְ הָאֱלֹהִים וְגוֹ'. (משנה) טֶרֶם (שנשקע) שֶׁנִּמְצָא אֲוִיר טָהוֹר, וְלֹא מְאִירִים, הָאֲבָנִים הַנְּקוּבוֹת הָיוּ סְתוּמוֹת. שָׁלֹשׁ רוּחוֹת שֶׁכְּלוּלוֹת בְּשָׁלֹשׁ הָיוּ שְׁקוּעוֹת, וּמַיִם סְתוּמִים תַּחַת הַנְּקָבִים בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת חָזְרוּ לִמְקוֹמָם אוֹתָם אֲבָנִים (דורות)."]]],[["בָּתַר שִׁבְעִין וּתְרֵין דַּרְגִּין, וְכֵן תְּלַת זִמְנִין, אִתְבָּקָעוּ ואִתְנְקִיבוּ אֲבָנֵי, תְּחוֹת צְרוֹרָא דְּהֲוָה חָקִיק, וְאִתְכְּנָפוּ דַּרְגִּין, וְאִתְעָבִידוּ כְּנוּפְיָא חֲדָא. (ס\"א אתפלג ואתעבידו כנופיא חד)","לְבָתַר אִתְפְּלָגוּ, וְאִתְעָבִידוּ תְּרֵין דַּרְגִּין, פַּלְגּוּתָא מַיָּא אַגְלִידוּ, וּפַלְגּוּתָא אִשְׁתְּקָעוּ. אִלֵּין סְלִיקוּ, וְאִלֵּין נַחְתּוּ, מֵהָכָא שָׁרָא עָלְמָא לְאִתְפַּלְגָא.","צְרוֹרָא אַחֲרָא (נ\"א חדא) אִית לְעֵילָּא, (לעילא) וְהוּא גְּלִיפָא בע\"ב חֲתִימָן דְּגוּשְׁפַּנְקָא תַּקִּיפָא, וּבְהוּ שְׁקִיעַן גַּלְגַּלּוֹי דְּיַמָּא. כַּד נַטְלִין, אִתְפְּלָגוּ לְאַרְבַּע זַוְּיָין. פַּלְגּוּ חֲדָא סָלִיק, וּפַלְגּוּ חֲדָא נָחִית, פַּלְגּוּ חֲדָא לִסְטַר צָפוֹן, וּפַלְגּוּ חֲדָא לִסְטַר דָּרוֹם. כַּד מִתְחַבְּרָן כַּחֲדָא, גּוּמְרִין דְּלַהֲטִין קַיְימִין, בְּלַהַט שִׁנָּנָא דְּחַרְבָּא דְּמִתְהַפְּכָא.","חַד קַיְּימָא נָעִיץ בְּגוֹ יַמָּא, דַּרְגָּא שְׁלִיחָא דְּאָפַרְכָא עִלָּאָה, סָלִיק בְּהַהוּא קַיָימָא לְעֵילָּא לְעֵילָּא, אִשְׁתֶכְלָל (נ\"א אסתכל) לְמֵרָחִיק, קְטוּרָא דְּאַרְבִּין דְּשָׁאטִין בְּיַמָּא. מַאן חָמֵי גַּלְגַּלִּין דְּסַלְּקִין וְנַחְתִּין וְרוּחָא דְּנָשִׁיב בְּהוּ, וְנוּנֵי יַמָּא נַגְדִּין כָּל אִינּוּן אַרְבִּין לְכָל סִטְרֵי עָלְמָא.","הַהוּא דַּרְגָּא, כַּד נָחִית מֵהַהוּא, קַיְימֵי אֶלֶף מִימִינֵיהּ, וְאֶלֶף מִשְּׂמָאלֵיהּ, הֲוָה תָּב וְיָתִיב בְּאַתְרֵיהּ, כְּמַלְכָּא בְּכוּרְסְיֵהּ, הַהוּא דַּרְגָּא דְּכַד שָׁאטֵי יַמָּא לְאַרְבַּע סִטְרֵי עָלְמָא, עִמֵּיהּ נַפְקַת, בֵּיהּ תֵּבַת, הוּא תָּב בְּקִיּוּמָא דְּמַלְכָּא.","כְּדֵין כָרוֹזִין נָפְקִין, מַאן מָארֵי דְּעַיְינִין, יִזְדַּקְפָאן לוֹן לְעֵילָּא לְעֵילָּא. מָארֵיהוֹן דְּגַדְפִּין יְקוּמוּן בְּקִיּוּמַיְיהוּ. מָארֵי דְּאַנְפִּין, חַפְיָין לוֹן, עַד דְּנָטִיל בְּמַטְלָנוֹי. כְּדֵין וַיִּסַּע מַלְאַךְ הָאֱלהִים. (עד כאן).","רִבִּי חִיָּיא פָּתַח, (משלי ל״א:י״ד) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. הָיְתָה כָּאֳנִיּוֹת סוֹחֵר, דָּא כְנֶסֶת יִשְׂרָאֵל. מִמֶּרְחָק תָּבִיא לַחְמָהּ, כְּמָה דְּאַתְּ אָמֵר, (ישעיהו ל׳:כ״ז) הִנֵּה שֵׁם יְיָ' בָּא מִמֶּרְחָק. תָּבִיא לַחְמָהּ, בְּחַד דַּרְגָּא דְּשָׁארִי עָלָהּ, וּבֵיהּ אִתְמְשָׁכוּ כָּל אִלֵּין נְחָלִין וּמַבּוּעִין דְּאַזְלִין בְּיַמָּא, כְּמָה דְּאַתְּ אָמֵר, (קהלת א׳:ז׳) כָּל (ויקרא נ\"ח ע\"א) הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'.","אֶל מָקוֹם שֶׁהַנְּחָלִים הוֹלְכִים, אַף עַל גַּב דְּכֻלְּהוּ נְחָלִין אִתְמַשְּׁכָן בְּהַהוּא דַּרְגָּא, וְהַהוּא דַּרְגָּא נָחִית (נ\"א נגיד) לוֹן לְהַהוּא יַמָּא, לָא תֵּימָא. דְּהָא אָרִיק לוֹן, וְהָא לָא שַׁרְיָין בֵּיהּ אַחֲרָנִין, וְלָא נַגְדִּין בֵּיהּ כְּמִלְקַדְּמִין, אַהְדָּר וְאָמַר אֶל מָקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים, אֶל מָקוֹם דְּהַהוּא דַּרְגָּא דְּנַחֲלִין אַזְלִין זִמְנָא חֲדָא, שָׁם הֵם שָׁבִים לָלָכֶת, תַּמָּן אִינּוּן תַּיְיבִין מֵהַהוּא אֲתָר עִלָּאָה, וְלָא פַּסְקִין לְעָלְמִין, וּמִתְכַּנְּשֵׁי כֻּלְּהוּ בְּהַהוּא אֲתָר. וְלָמָּה. לָלָכֶת. לְמֵהַךְ לְהַהוּא אֲתָר דְּיַמָּא, כְּמָה דְּאִתְּמַר, מַה שְׁמֵיהּ דְּהַהוּא דַּרְגָּא. צַדִּיק אִקְרֵי.","רִבִּי יְהוּדָה אָמַר, כְּתִיב (תהילים ק״ד:כ״ו) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. שָׁם אֳנִיּוֹת יְהַלֵּכוּן, בְּהַהוּא יַמָּא דְּאַזְלִין וְשָׁאטִין, עַד דְּאַתְיָין לְאִתְחַבְּרָא בְּהַהוּא דַּרְגָּא, כְּדֵין כְּתִיב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.","רִבִּי יִצְחָק אָמַר, לְעֵילָּא לְעֵילָּא יַתִּיר, אִית זִוּוּגָא אַחֲרָא, דְּשָׁארִי בַּחֲבִיבוּתָא, וְלָא (ויקרא ס\"א ע\"ב, ע\"ז ע\"ב, נ\"ה ע\"א, כ\"ו ע\"א) מִתְפְּרַשׁ לְעָלְמִין. אָמַר רִבִּי יְהוּדָה, מַאן זָכֵי לְהַהוּא זִוּוּגָא. אָמַר לֵיהּ, מַאן דְּאִית לֵיהּ חוּלָקָא בְּעָלְמָא דְּאָתֵי. בְּעָלְמָא דְּאָתֵי דַּיְקָא.","אָמַר לֵיהּ, וְהָא מֵהָכָא אוֹלִיפְנָא, דִּכְתִּיב, (תהילים ק״ד:כ״ו) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, מַשְׁמַע דְּקָאָמַר זֶה, וְזֶה וְזֹאת יְדִיעָן אִינּוּן. אָמַר רִבִּי אַבָּא, תַּרְוַויְיכוּ שַׁפִּיר קָאָמְרִיתּוּ, וְהָא דְּרִבִּי יְהוּדָה שַׁפִּיר דַּיְקָא, וְכֹלָּא זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְעַנְגָּא בְּהוּ לְצַדִּיקַיָּיא, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ'.","אָמַר רִבִּי אַבָּא, כַּמָּה אַלְפִין, כַּמָּה רִבְּבָן דְּמַשִּׁירְיָין קַדִּישִׁין, אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, מָארֵי דְּאַנְפִּין עִלָּאִין, מָארֵי דְּעַיְינִין, מָארֵי דְּזַיְינִין, מָארֵי דִּילָלָה, מָארֵי דִּיבָבָא, מָארֵי דְּרַחֲמֵי, מָארֵי דְּדִינָא, וְעֵילָּא מִנַּיְיהוּ אַפְקַד לְמַטְרוֹנִיתָא לְשַׁמְשָׁא בְּהֵיכְלָא קָמֵיהּ.","לָקֳבֵיל אִלֵּין, אִית לָהּ לְמַטְרוֹנִיתָא, מַשִׁירְיָן מְזְיָּינִין. בְּשִׁתִּין (בשתא) אַנְפִּין מִשְׁתַּכְחוּ מַשְׁרְיָין מְזוּיָינִין. וְכֻלְּהוּ חֲגִירָן חֲרְבָּא, קַיְּימָאן בְּסַחֲרָנָהָא, כַּמָה נָפְקִין, כַּמָה עַיְילִין. בְּשִׁית גַּדְפִּין טָאסִין כָּל עָלְמָא. קַמֵי כָּל חַד וְחַד גּוּמָרִין דְּנוּר דָּלִיק. לְבוּשׁוֹי, מִתְלָהֲטָא אֶשָּׁא. בְּגַבּוֹי, שִׁנָּנָא דְּחַרְבָּא מִתְלָהֲטָא בְּכָל עָלְמָא, לְנַטְרָא קָמָהּ. הֲדָא הוּא דִכְתִיב, (בראשית ג׳:כ״ד) וְאֵת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמוֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים."],[[0,"בתר שבעין ותרין וכו':","אחר ע\"ב מדרגות, שהן ג' פעמים ע\"ב אתוון, התבקעו והתנקבו האבנים תחת צרור שהיה חקוק, והתקבצו המדרגות ונעשו קבוצה אחת."],[0,"","פירוש. סוד ע\"ב אתוון, היינו ע\"ב אותיות שיש בכל פסוק מג' הפסוקים, ויסע, ויבא, ויט. (כמ\"ש להלן אות קס\"ב) והם סוד ג' קוין, כי ע\"ב אותיות שבפסוק ויסע הן קו ימין, וע\"ב אותיות שבפסוק ויבא, הן קו שמאל, וע\"ב אותיות שבפסוק ויט, הן קו אמצעי. ומ\"ש לעיל, בע\"ב אתוון אתהדרו לאתרייהו אינון אבנין, הכונה היא על ע\"ב אתוון שבפסוק ויסע, שהן קו ימין וחסדים. ויש ע\"ב צירופים של ג' ג' אותיות, דהיינו מצירוף כל ג' הפסוקים, (כמ\"ש להלן אות קס\"ב) והן נקראות ע\"ב מדרגות, מטעם היות בכל צירוף ג' קוין, וג' קוין נחשבים למדרגה."],[0,"","גם נודע, שע\"י מסך דחירק שבקו האמצעי, מתמעט הקו שמאל דבינה מג\"ר לו\"ק דג\"ר, דהיינו שחוזר ומעלה את המלכות לבינה והבינה מתבקעת שוב ונעשית ו\"ק שהיא אור נקבה. (כמ\"ש לך דף י\"ג ד\"ה ונתבאר) וז\"ש, \u0003בתר שבעין ותרין דרגין\u0004 והן ג' זמנין, דהיינו אחר שיוצאים ג' קוין שהן ע\"ב מדרגות המרומזים בפסוקים ויסע ויבא ויט, הנה ע\"י קו האמצעי שבהם, \u0003אתבקעו ואתנקיבו אבני תחות צרורא דהוה חקיק,\u0004 שמסבת הצרור שהיה חקוק בדינים, שה\"ס המסך דחירק שבקו האמצעי, חזרו והתבקעו ואתנקיבו הספירות דבינה שנקראות אבנים. ואז, \u0003ואתכנפו דרגין ואתעב כנופיא חדא,\u0004 שע\"י המסך הזה שהמעיט את קו השמאל לו\"ק דג\"ר, נתקבצו ונתיחדו ג' הקוין לקבוצה אחת, באפן שאינם מאירים זה בלי זה. ומטעם זה מכנה את המסך בשם \u0003צרורא,\u0004 מטעם היותו צורר כל ג' הקוין לאגודה אחת."],[1,"לבתר אתפלגו וכו':","אחר כך נתחלקו ונעשו ב' מדרגות של מים, מחצית המים נקפאו, ומחציתם נשקעו, אלו עלו ואלו ירדו. מכאן התחיל העולם להתחלק."],[1,"","פירוש. נודע, שבשעת שליטת קו שמאל, נקפאים המים שבים, משום שהחכמה אינה מאירה בלי חסדים. ואח\"כ על ידי החסדים הם נפתחים וחוזרים לנוזלים, דהיינו שחוזרים להאיר. (כנ\"ל ב\"א דף רצ\"א ד\"ה ואלמלא) אמנם לא כל החכמה חוזרת להאיר אלא רק הו\"ק שבחכמה, והג\"ר שבה נעלמים. ולפיכך נבחן כאן שמי החכמה נחלקו לב' מדרגות: ו\"ק וג\"ר, שהו\"ק נקפאו בעת שליטת השמאל, ואח\"כ ע\"י גילוי החסדים חוזרים להאיר. והג\"ר לא נקפאו, אלא נעלמו לגמרי, שהרי אינם מאירים אפילו אחר גילוי החסדים. וז\"ש \u0003אתפלגו ואתעבידו תרין דרגין\u0004 דהיינו ג\"ר וו\"ק. \u0003פלגותא מיא אגלידו,\u0004 היינו הו\"ק דחכמה. שהם חוזרים להגלות ע\"י החסדים. \u0003ופלגותא עשתקעו,\u0004 היינו הג\"ר, שנעלמו לגמרי. ומפרש יותר, \u0003אלין סליקו,\u0004 היינו אותם שנגלדו, היו מאירים ממטה למעלה, שהוא בחי' ו\"ק. ואלין נחתו, היינו אותם שהשתקעו, היו מאירים ממעלה למטה, שהוא בחי' ג\"ר. \u0003מהכא שרא עלמא לאתפלגא,\u0004 דהיינו שלא נשארה בעולם אלא מחצית התחתון של החכמה שהוא בחי' ו\"ק."],[2,"צרורא אחרא אית וכו':","צרור אחר יש למעלה והוא חקוק בע\"ב חתימות מטבעת התקיפה, ובהם שקועים גלי הים. כשנוסעים נחלקים לד' זויות, חלק אחד עולה, שמאיר ממטה למעלה דהיינו הנוקבא שה\"ס מערב. וחלק אחד יורד, שמאיר ממעלה למטה, עם אור החסדים, והיינו ז\"א, שה\"ס מזרח. חלק אחד לצד צפון, שהוא קו שמאל, גבורה. וחלק אחד לצד דרום, שהוא קו ימין חסד, כשמתחברים יחד, גחלות לוהטות עומדות בלהט החרב המתהפכת."],[2,"","פירוש. כמו שנתבאר לעיל, ענין המסך, שבקו אמצעי הנקרא צרורא, המשמש במקום בינה, וכן הוא משמש מחזה ולמעלה דז\"א, להיותם מדרגה אחת, כן יש צרורא המשמש מחזה ולמטה דז\"א, שבכחו מכריע בין ב' הקוין אשר שם. וההפרש ביניהם הוא רב, כי אותו הצרור, המשמש מחזה ולמעלה דז\"א, אינה מגלה שם הדינים שבו, להיותו נמצא בסיום הקוין, ואין הדינים יכולים לפגום למעלה ממקום מציאותם. מה שאין כן הצרור שמחזה ולמטה דז\"א, כבר כלול בו הדינים מצרור העליון העומד למעלה ממנו במקום החזה. והנה ג' הקוין חג\"ת שלמעלה מחזה, נקראים ע\"ב דרגין, כנ\"ל, שה\"ס ג' הפסוקים ויסע ויבא ויט. וע\"כ מכונים הדינים אשר בצרור העליון העומדים בסיום ע\"ב דרגין, בשם, \u0003ע\"ב חתימן דגושפנקא תקיפא, ע\"ב,\u0004 על שם הארתו, \u0003חתימן\u0004 פירושו סיומים, משום, שנמצאים בסיום המדרגות, \u0003גושפנקא תקיפא\u0004 היינו הצרור עצמו, שהוא המסך דחזה, שבו הדינים."],[2,"","וז\"ש \u0003צרורא אחרא אית לעילא,\u0004 היינו הצרור שבקו האמצעי שמחזה ולמטה. \u0003והוא גליפא בע\"ב חתימן דגושפנקא,\u0004 דהיינו הדינים שבצרור העליון העומד במקום החזה, המכונים כן, המשפיעים לצרור התחתון. אמנם עם כל זה אינם נחשבים לדינים שיפגמו משהו את המדרגה, שהוא מטעם, \u0003ובהו שקיען גלגלוי דימא,\u0004 שהדינים המתגלים בים, המכונים גלי הים, ישתוקו על ידי הדינים שבקו אמצעי שלמטה מחזה, ולולא הדינים הללו שבצרור התחתון לא היו הגלים נשתקים, והים, שהוא המלכות, לא היתה יכולה להאיר. וע\"כ אינם נחשבים לדינים אלא לתקונים."],[2,"","וג' הקוין הללו, אינם מגלים חכמה אלא בסוד נסיעתם, דהיינו שהארת כל אחד מתגלה במיוחד בזה אחר זה, בסוד ג' נקודות: חולם, ואח\"כ שורק, ואח\"כ חירק. ואז מקבלת המלכות את גילוי החכמה מהם. אבל כשגמרו הארתם בזה אחר זה, המכונה נסיעה, אז הם נחים. דהיינו שהארתם מתחברת ביחד תחת שליטת אור החסדים, והחכמה אינה מתגלה עוד."],[2,"","וז\"ש, \u0003כד נטלין,\u0004 כשהם נוסעים, כדי לגלות הארת החכמה, \u0003אתפלגו לארבע זוויין\u0004 הם נחלקים לד' זוית, דהיינו שכל אחד מג' הקוין מגלה הארתו במיוחד, מתחילה הימין ואח\"כ אחר שנגמרה הארת הימין מאיר השמאל, ואח\"כ כאשר נגמרה הארת השמאל, מאיר האמצעי, שהם מכונים, דרום, צפון, מזרח. ואח\"כ המערב שהיא המלכות מקבלת מהם החכמה. וז\"ש \u0003פלגו חדא סליק\u0004 וכו'. אבל \u0003כד מתחברים כחדא,\u0004 דהיינו אחר שגמרו נסיעתם שמאירים כולם ביחד, \u0003גומרין דלהטין קיימין בלהט שננא דחרבא,\u0004 גחלות לוהטות עומדות בקו השמאל בסוד להט החרב המתהפכת, שהם שומרים את החכמה שלא תגלה שלא בשעת נסיעה. וע\"כ אין גילוי אז אלא לאור החסדים בלבד."],[3,"חד קיימא נעיץ וכו':","עמוד אחד תקוע בתוך הים. מדרגה, שהיא שליח של חלק המדינה העליונה, שהיא המלכות שמחזה ולמעלה, עולה בעמוד הזה למעלה למעלה, ומסתכל למרחוק לראות קשר של אניות השטות בים. מי ראה הגלים עולים ויורדים, מחמת הדינים שבהם, ורוח, שהוא קו אמצעי, נושב בהם ומשתיקם, ודגי הים, שהם המלאכים, מושכים את כל אלו האניות לכל רוחות העולם. שבדרך זה נגלה החכמה."],[3,"","ביאור הדברים. כבר ידעת שע\"י עלית המלכות לבינה, נבקעות כל המדרגות לשתים, שכו\"ח נשארים במדרגה ובינה ותו\"מ נופלים ממנה ויורדים ומתלבשים במדרגה התחתונה אליה (כמ\"ש ב\"א דף ד' ד\"ה ביאור) ולעת גדלות יורדת המלכות מבינה למקומה, ואז עולים בינה ותו\"מ דכל מדרגה מן התחתון, וחוזרים כל אחד למדרגתו (ב\"א דף ר\"צ ד\"ה בגין) ויחד עם עליתם מן התחתון לוקחים עמהם גם את התחתון, ומעלים ואתו למקום העליון, (כמ\"ש בהקסה\"ז דף כ' ד\"ה ואמא) ומתוך שאין העדר ברוחני, הם נמצאים תמיד במקום התחתון, גם אחר שעלו למדרגתם, שבדרך זה עולה כל תחתון אל העליון שלו, כמ\"ש שם. וע\"כ נבחנים בינה ותו\"מ הללו לבחינת \u0003עמוד\u0004, שיש בכל מדרגה, שעל ידו עולה למדרגה עליונה שלה. (כמ\"ש בראשית ב' דף י\"ד ד\"ה ביאור ע\"ש)."],[3,"","וז\"ש, \u0003חד קיימא נעיץ גו ימא.\u0004 כי הים שהוא הנוקבא הוא מחזה ולמטה דז\"א, ואותם בינה ותו\"מ דמדרגת מחזה ולמעלה דז\"א היורדות שמה, נבחנים לעמוד, שדרך בו עולים כל הבחינות שמחזה ולמטה דז\"א אל מדרגת מחזה ולמעלה דז\"א."],[3,"","והנה תחילה היתה המלכות למעלה מחזה דז\"א בסוד רביעי לאבות, ששם מקום גילוי החכמה, ואחר זה נתמעטה וירדה למטה מחזה דז\"א, (כנ\"ל ב\"א ק\"י ד\"ה מלכותא דדוד) וכיון שכל מקור גילוי החכמה היא למעלה מחזה דז\"א, ע\"כ יש לה \u0003שליח,\u0004 שהוא המלאך מטטרון, שעולה למעלה מחזה וממשיך החכמה למחזה ולמטה, לסוד ד' החיות של מרכבה התחתונה המכונים אלפי שנאן. (כנ\"ל ב\"א דף פ\"ה ד\"ה ומניה)."],[3,"","וז\"ש \u0003דרגא שליחא דאפרכא עלאה,\u0004 דהיינו מטטרון שהוא שליח להמשיך ולקבל חכמה ממלכות העליונה שמחזה ולמעלה בשביל המלכות שמחזה ולמטה, כנ\"ל, \u0003אסתכל למרחיק,\u0004 היינו שמקבל חכמה שנקרא הסתכלות מרחוק, בסו\"ה מרחוק ה' נראה לי (כנ\"ל וירא דף י\"ד ד\"ה הורמנותא) \u0003קטורא דארבין דשאטין בימא,\u0004 דהיינו ששטים לד' רוחות העולם, ומגלים חכמה על ידי מטטרון. כמו שמפרש והולך \u0003מאן חמי גלגלין\u0004 וכו'."],[4,"ההוא דרגא כד וכו':","מדרגה ההוא, דהיינו מטטרון, כשירד מלמעלה מחזה, עומדים אלף מימינו ואלף משמאלו, דהיינו שממשיך חכמה המרומזת במספר אלף בין בימינו ובין בשמאלו. והוא שב למחזה ולמטה, ויושב במקומו כמלך על הכסא שלו. מדרגה ההיא בעת שהים, שהוא מלכות, שט לד' רוחות העולם, עמו יוצא בו שב, הוא שב בקיומו של המלך."],[4,"","פירוש. כבר נתבאר (באות קל\"ז) שאין הקוין מגלים החכמה רק בדרך נסיעה על תלת דוכתי בזה אחר זה, בסוד חולם שורק חירק, שה\"ס \u0003רצוא,\u0004 אבל כשגמרו נסיעתם ומתחברים בהארתם בסוד המנוחה, שה\"ס ושוב, אז יש להט החרב המתהפכת בקו שמאל, השומר שלא יגלה חכמה לחוץ. וז\"ש \u0003ההוא דרגא\u0004 שהוא מטטרון, דכד \u0003שטי ימא לד' סטרי עלמא,\u0004 ומגלה חכמה בעת נסיעתו, \u0003עמיה נפקת,\u0004 עמו היא יוצאת לנסיעה בסוד \u0003רצוא, ביה תבת,\u0004 עמו היא שבה מנסיעתה בסוד \u0003ושוב הוא תב בקיומא דמלכא,\u0004 הוא שב, כדי לקיים המוחין של המלך, דהיינו בבחינת הארת החסדים, שבו מתקיימים המוחין."],[5,"כדין כרוזין נפקין וכו':","ואז כשהים הוא בבחינת \u0003ושוב,\u0004 יוצאים כרוזים, מי שהוא מבעלי העינים, יזקוף אותם למעלה למעלה. בעלי כנפים יקומו בקיומם. בעלי הפנים, יכסו פניהם עד שנוסע במסעיו, אז ויסע מלאך האלקים."],[5,"","פירוש. עינים ופנים הם חכמה, עינים הם ג\"ר, והפנים הם ו\"ק. שז\"ס חכמת אדם תאיר פניו. וז\"ש, \u0003מאן מארי דעיינין, יזדקפאן לון לעילא לעילא,\u0004 שיאירו למעלה למעלה בבינה ולא ימשיך אותם למטה, מטעם היותם ג\"ר דחכמה, שאינם מאירים אפילו בעת נסיעה. \u0003מארי דגדפין\u0004 דהיינו המדרגות של חסדים מכוסים, \u0003יקומון בקיומייהו,\u0004 שימשיכו הארתם, כי בעת \u0003ושוב,\u0004 מאירים רק אור החסדים, שהם הארת מארי דגדפין. \u0003מארי דאנפין חפיין לון,\u0004 שיכסו הארת הפנים בעת המנוחה, שבסוד ושוב, כי אינם מאירים רק בשעת נסיעה, כנ\"ל. וז\"ש, \u0003עד דנטיל במטלנוי,\u0004 ואז מתגלה אור הפנים. שזסו\"ה, ויסע מלאך האלקים. כמ\"ש להלן. (ע\"כ תוספתא)"],[6,"ר' חייא פתח וכו':","רח\"פ, היתה כאניות סוחר ממרחק תביא לחמה. \u0003היתה כאניות סוחר,\u0004 היא כנסת ישראל, דהיינו המלכות. \u0003ממרחק תביא לחמה,\u0004 כמש\"א, הנה שם ה' בא ממרחק. דהיינו ע\"י הארת קו האמצעי במסך דחירק, שהוא מרחיק הג\"ר דחכמה ואינו מאיר אלא בו\"ק. (כמ\"ש באורך לעיל וירא ט\"ז ד\"ה וזה). \u0003תביא לחמה,\u0004 היינו על ידי מדרגה אחת השורה עליה, שהוא קו האמצעי, שה\"ס היסוד דז\"א, ובו נמשכים כל אלו הנחלים והמעיינות ההולכים בים. כמש\"א, כל הנחלים הולכים אל הים."],[7,"אל מקום שהנחלים הולכים:","פירושו, אע\"פ שכל הנחלים נמשכים ע\"י מדרגה ההיא, שהיא יסוד, ומדרגה ההיא מוריד אותם לתוך הים, שהיא מלכות, אל תאמר, שהוא שפך אותם הנחלים לים, ואחרים אינם שורים בו, ואין נמשכים בו עוד כבתחילה, ע\"כ חזר ואמר, אל מקום שהנחלים הולכים שם הם שבים, ששבים למקום מדרגה ההיא שהנחלים הלכו משם פעם אחת, \u0003שם הם שבים ללכת,\u0004 שם הם שבים ממקום ההוא העליון, דהיינו מבינה באים שוב ליסוד, שהשפע אינו פוסק משם לעולם ומתקבצים כולם במקום ההוא ביסוד, ולמה, \u0003ללכת.\u0004 ללכת למקום ההוא של הים. שהוא המלכות. כמו שלמדנו. ומה שמה של אותה המדרגה. הוא נקרא צדיק, דהיינו יסוד דז\"א."],[8,"ר' יהודה אמר וכו':","רי\"א, כתוב, שם אניות יהלכון לויתן זה יצרת לשחק בו. \u0003שם אניות יהלכון,\u0004 פירושו, שבים ההוא הולכים ושטים האניות, עד שבאים להתחבר באותה המדרגה, שהיא יסוד, אז כתוב לויתן זה יצרת לשחק בו. כי לויתן הוא יסוד דז\"א."],[9,"רבי יצחק אמר וכו':","רי\"א, למעלה למעלה ביותר, יש זווג אחר השורה ברעות, ואינם נפרדים לעולם. שה\"ס זווג או\"א עלאין, שהם בחינת ג\"ר דבינה. אמר ר' יהודה, מי זוכה לזווג ההוא. אמר לו, מי שיש לו חלק לעולם הבא. שהוא בינה, ובדיוק הוא עולם הבא. שמי שלא זכה לעולם הבא שהוא בינה לא יזכה לאותו הזווג."],[10,"אמר ליה והא וכו':","אמר לו ר' יהודה, והרי מכאן למדנו, שכתוב, לויתן זה יצרת לשחק בו. משמע שאמר \u0003זה,\u0004 שהוא יסוד, וזה וזאת ידועים הם, שהם יסוד ומלכות. הרי שאפילו לא יזכה לבינה זוכה ג\"כ לקבל מזווג העליון. אמר ר' אבא, שניכם אומרים יפה, וזה של ר' יהודה יפה היא בדיוק. והכל הכין הקב\"ה לענג בהם את הצדיקים. ז\"ש, אז תתענג על ה'."],[11,"אמר ר' אבא וכו':","אר\"א, כמה אלפים וכמה רבבות של מחנות קדושות, יש לו להקב\"ה, דהיינו, בעלי פנים העליון, בעלי עינים בעלי כלי זיין, בעלי יללה, בעלי יבבא, בעלי רחמים, בעלי דין, ולמעלה מהם פקד את המטרוניתא, שהיא המלכות, לשמש לפניו בהיכלו."],[12,"לקבל אלין אית וכו':","כנגד אלו יש לה למטרוניתא, שהיא המלכות, מחנות מלאכים מזוינות. בששים פנים נמצאות המחנות המזוינות. וכולן חגורי חרב עומדים מסביב המלכות. כמה יוצאים, כמה באים. בשש כנפים מעופפים כל העולם. לפני כל אחד ואחד גחלות אש דולקות, לבושיו אש לוהט, בגבו להט החרב הלוהטת בכל העולם לשמור לפניה. ז\"ש, ואת להט החרב המתהפכת לשמור את דרך עץ החיים."]],[[0,"","אַחַר שִׁבְעִים וּשְׁתַּיִם דְּרָגוֹת, וְכֵן שָׁלֹשׁ פְּעָמִים, הִתְבַּקְּעוּ וְנִנְקְבוּ הָאֲבָנִים תַּחַת צְרוֹר שֶׁהָיָה חָקוּק, וְהִתְכַּנְּסוּ הַדְּרָגוֹת וְנַעֲשׂוּ כִנּוּס אֶחָד. (נחלק ונעשו כגוס אחד)."],[1,"","אַחַר כָּךְ הִתְחַלְּקוּ וְנַעֲשׂוּ שְׁתֵּי דְרָגוֹת, חֲצִי מַיִם קָפְאוּ, וַחֲצִי שָׁקְעוּ. אֵלֶּה עָלוּ וְאֵלֶּה יָרְדוּ. מִכָּאן הִתְחִיל הָעוֹלָם לְהִתְחַלֵּק."],[2,"","צְרוֹר אַחֵר (אחד) יֵשׁ לְמַעְלָה (למעלה), וְהוּא חָקוּק בְּשִׁבְעִים וּשְׁתַּיִם חוֹתָמוֹת שֶׁל חוֹתֶמֶת תַּקִּיפָה, וּבָהֶם שְׁקוּעִים גַּלֵּי הַיָּם. כְּשֶׁנּוֹסְעִים, נֶחֱלָקִים לְאַרְבַּע זָוִיּוֹת. מַחֲצִית אַחַת עוֹלָה, וּמַחֲצִית שְׁנִיָּה יוֹרֶדֶת. מַחֲצִית אַחַת לְצַד צָפוֹן, וּמַחֲצִית אַחַת לְצַד דָּרוֹם. כְּשֶׁמִּתְחַבְּרִים כְּאֶחָד, גֶּחָלִים שֶׁלּוֹהֲטִים קַיָּמִים בְּלַהַט שְׁנִינוּת הַחֶרֶב הַמִּתְהַפֶּכֶת."],[3,"","עַמּוּד אֶחָד נָעוּץ בְּתוֹךְ הַיָּם, דַּרְגָּה שֶׁשְּׁלוּחָה שֶׁל שַׂר עֶלְיוֹן עוֹלֶה בְּאוֹתוֹ עַמּוּד לְמַעְלָה מַעְלָה, נִתְקָן (מסתכל) לְמֵרָחוֹק עַל קִיטוֹר הָאֳנִיּוֹת שֶׁשָּׁטוֹת בַּיָּם. מִי רָאָה אֵיזֶה גַלִּים שֶׁעוֹלִים וְיוֹרְדִים וְהָרוּחַ נוֹשֶׁבֶת בָּהֶם, וּדְגֵי הַיָּם מוֹשְׁכִים אֶת כָּל הָאֳנִיּוֹת הַלָּלוּ לְכָל צִדְדֵי הָעוֹלָם."],[4,"","אוֹתָהּ דַּרְגָּה, כְּשֶׁיּוֹרֶדֶת מֵהַהוּא, עוֹמְדִים אֶלֶף מִימִינוֹ וְאֶלֶף מִשְּׂמֹאלוֹ. הָיָה שָׁב וְיוֹשֵׁב בִּמְקוֹמוֹ כְּמֶלֶךְ בְּכִסְאוֹ, אוֹתָהּ דַּרְגָּה שֶׁכְּשֶׁשָּׁט הַיָּם לְאַרְבָּעָה צִדְדֵי הָעוֹלָם, יוֹצֵאת עִמּוֹ, בּוֹ חוֹזֶרֶת, וְהוּא שָׁב בְּקִיּוּם הַמֶּלֶךְ."],[5,"","וְאָז יוֹצְאִים הַכָּרוֹזִים: מִי מִבַּעֲלֵי הָעֵינַיִם יִזְקֹף אוֹתָם לְמַעְלָה לְמַעְלָה. בַּעֲלֵי הַכְּנָפַיִם יַעַמְדוּ בְקִיּוּמָם. בַּעֲלֵי הַפָּנִים מְכַסִּים אוֹתָם, עַד שֶׁנּוֹסֵעַ בְּמַסְעוֹתָיו. וְאָז וַיִּסַּע מַלְאַךְ הָאֱלֹהִים."],[6,"","רַבִּי חִיָּיא פָּתַח, (משלי לא) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. הָיְתָה כָּאֳנִיּוֹת סוֹחֵר - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִמֶּרְחָק תָבִיא לַחְמָהּ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ל) הִנֵּה שֵׁם ה' בָּא מִמֶּרְחָק. תָּבִיא לַחְמָהּ - בְּדַרְגָּה אַחַת שֶׁשּׁוֹרָה עָלֶיהָ, וּבָהּ נִמְשְׁכוּ כָּל הַנְּחָלִים וְהַמַּעְיָנוֹת הַלָּלוּ שֶׁהוֹלְכִים לַיָּם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'."],[7,"","אֶל מְקוֹם שֶׁהַנְּחָלִים הֹלְכִים. אַף עַל גַּב שֶׁכָּל הַנְּחָלִים נִמְשָׁכִים לְאוֹתָהּ דַּרְגָּהּ, וְאוֹתָהּ דַּרְגָּה מוֹרִידָה (מושכת) אוֹתוֹ לְאוֹתוֹ יָם - אַל תֹּאמַר, שֶׁהֲרֵי הֵרִיק אוֹתָם, וְלֹא שׁוֹרִים בּוֹ אֲחֵרִים, וְלֹא שׁוֹפְעִים בּוֹ כְּבַתְּחִלָּה, חָזַר וְאָמַר אֶל מְקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים. אֶלָּא מְקוֹם אוֹתָהּ דַּרְגָּה שֶׁהַנְּחָלִים הוֹלְכִים פַּעַם אַחַת, שָׁם הֵם שָׁבִים לָלֶכֶת - שָׁם הֵם שָׁבִים מֵאוֹתוֹ מָקוֹם עֶלְיוֹן, וְלֹא פוֹסְקִים לְעוֹלָמִים, וְכֻלָּם מִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם. וְלָמָּה? לָלֶכֶת. לָלֶכֶת לְאוֹתוֹ מָקוֹם שֶׁל הַיָּם, כְּמוֹ שֶׁנֶּאֱמַר. מַה שֵּׁם אוֹתָהּ הַדַּרְגָּה? נִקְרֵאת צַדִּיק."],[8,"","רַבִּי יְהוּדָה אָמַר, כָּתוּב (תהלים קד) שָׁם אֳנִיּוֹת יְהַלֵּכוּן לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ. שָׁם אֳנִיּוֹת יְהַלֵּכוּן - בְּאוֹתוֹ הַיָּם שֶׁהוֹלְכִים וְשָׁטִים עַד שֶׁבָּאִים לְהִתְחַבֵּר בְּאוֹתָהּ דַּרְגָּה, אָז כָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ."],[9,"","רַבִּי יִצְחָק אָמַר, לְמַעְלָה לְמַעְלָה יוֹתֵר, יֵשׁ זִוּוּג אַחֵר שֶׁשּׁוֹרֶה בַּחֲבִיבוּת וְלֹא נִפְרָד לְעוֹלָמִים. אָמַר רַבִּי יְהוּדָה, מִי זוֹכֶה לְאוֹתוֹ זִוּוּג? אָמַר לוֹ, מִי שֶׁיֵּשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא. דַּוְקָא בָּעוֹלָם הַבָּא. אָמַר לוֹ, וַהֲרֵי מִכָּאן לָמַדְנוּ, שֶׁכָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ,"],[10,"","אָמַר לוֹ, וַהֲרֵי מִכָּאן לָמַדְנוּ, שֶׁכָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, מַשְׁמָע שֶׁאָמַר זֶה, וְזֶה וְזֹּאת הֵם יְדוּעִים. אָמַר רַבִּי אַבָּא, שְׁנֵיכֶם יָפֶה אֲמַרְתֶּם, וְזֶה שֶׁל רַבִּי יְהוּדָה דַּוְקָא יָפֶה, וְהַכֹּל עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְעַנֵּג בָּהֶם לַצַּדִּיקִים. זֶהוּ שֶׁכָּתוּב (ישעיה נח) אָז תִּתְעַנַּג עַל ה'."],[11,"","אָמַר רַבִּי אַבָּא, כַּמָּה אֲלָפִים וְכַמָּה רְבָבוֹת שֶׁל מַחֲנוֹת קְדוֹשִׁים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא: בַּעֲלֵי פָּנִים עֶלְיוֹנִים, בַּעֲלֵי עֵינַיִם, בַּעֲלֵי כְּלֵי זַיִן, בַּעֲלֵי הַיְלָלָה, בַּעֲלֵי הַיְבָבָה, בַּעֲלֵי רַחֲמִים, בַּעֲלֵי דִין, וּמֵעַל כֻּלָּם הִפְקִיד אֶת הַגְּבִירָה לְשַׁמֵּשׁ בַּהֵיכָל שֶׁלְּפָנָיו."],[12,"","כְּנֶגֶד אֵלֶּה יֵשׁ לַגְּבִירָה מַחֲנוֹת מְזֻיָּנִים. בְּשִׁשִּׁים (בששה) פָּנִים נִמְצָאִים מַחֲנוֹת מְזֻיָּנִים, וְכֻלָּם חֲגוּרֵי חֶרֶב עוֹמְדִים סְבִיבָהּ. כַּמָּה יוֹצְאִים וְכַמָּה נִכְנָסִים. בְּשֵׁשׁ כְּנָפַיִם טָסִים אֶת כָּל הָעוֹלָם. לִפְנֵי כָּל אֶחָד וְאֶחָד גַּחֲלֵי אֵשׁ בּוֹעֵר. לְבוּשׁוֹ אֵשׁ לוֹהֵט. בְּגַבּוֹ חֶרֶב שְׁנוּנָה לוֹהֶטֶת בְּכָל הָעוֹלָם לִשְׁמֹר לְפָנֶיהָ. זֶהוּ שֶׁכָּתוּב (בראשית ג) וְאֶת לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת לִשְׁמֹר אֶת דֶּרֶךְ עֵץ הַחַיִּים."]]],[["מַאן דֶּרֶךְ עֵץ הַחַיִּים. דָּא הִיא מַטְרוֹנִיתָא רַבְּתָא, דְּהִיא אָרְחָא, לְהַהוּא אִילָנָא רַבְרְבָא תַּקִּיף, אִילָנָא דְּחַיֵּי. דִּכְתִּיב, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ מִגִּבּוֹרֵי יִשְׂרָאֵל. יִשְׂרָאֵל דִּלְעֵילָּא, כֻּלָּם אֲחוּזֵי חֶרֶב.","כַּד נַטְלָא מַטְרוֹנִיתָא, כֻּלְּהוּ נַטְלִין בַּהֲדָהּ, הֲדָא הוּא דִכְתִיב וַיִּסַּע מַלְאַךְ הָאֱלהִים. וְכִי מַלְאַךְ הָאֱלֹהִים אִתְקְרֵי. אָמַר רִבִּי אַבָּא אִין. תָּא חֲזֵי, הָכִי אָמַר רִבִּי שִׁמְעוֹן, אַתְקִין קוּדְשָׁא בְּרִיךְ הוּא קָמֵיהּ, הֵיכָלָא קַדִּישָׁא, הֵיכָלָא עִלָּאָה, (קדישא) קַרְתָּא קַדִּישָׁא, קַרְתָּא עִלָּאָה. יְרוּשְׁלֵים עִיר הַקֹּדֶשׁ אִקְרֵי, מַאן דְּעָאל לְמַלְכָּא, לָא עָאל אֶלָּא מֵהַהוּא קַרְתָּא קַדִּישָׁא, נָטִיל אָרְחָא לְמַלְכָּא, דְּאָרְחָא מֵהָכָא אִתָּתְקָן.","הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַיְיָ' צַדִּיקִים יָבוֹאוּ בוֹ. כָּל שְׁלִיחוּתָא דְּבָעֵי מַלְכָּא מִבֵּי מַטְרוֹנִיתָא נָפְקָא, וְכָל שְׁלִיחוּתָא מִתַּתָּא לְמַלְכָּא, (נ\"א דבעי מלכא) לְבֵי מַטְרוֹנִיתָא עָיִיִל בְּקַדְמִיתָא, וּמִתַּמָּן לְמַלְכָּא. אִשְׁתְּכַח דְּמַטְרוֹנִיתָא אִיהִי שְׁלִיחָא דְּכֹלָּא, מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. וְעַל דָּא, אִיהִי שְׁלִיחָא דְּכֹלָּא, הֲדָא הוּא דִכְתִיב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל, יִשְׂרָאֵל דִּלְעֵילָּא. מַלְאַךְ הָאֱלהִים, הֲדָא הוּא דִכְתִיב בֵּיהּ, וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם וְגוֹ', וְהַאי לָלֶכֶת יוֹמָם וְלַיְלָה, כְּמָה דְּאוּקְמוּהָ.","וְכִי יְקָרָא הוּא דְּמַלְכָּא, דְּמַטְרוֹנִיתָא תֵּזִּיל, וְהִיא תִּגַּח קְרָבָא, וְהִיא אַזְלַת שְׁלִיחָא. אֶלָּא, לְמַלְכָּא דְּאִזְדָּוַּוג בְּמַטְרוֹנִיתָא עִלָּאָה, חָמָא מַלְכָּא יְקִירוּ דִּילָהּ, עַל כָּל שְׁאַר מַטְרוֹנִיתָא דְּעָלְמָא, אָמַר כֻּלְּהוּ מִשְׁתַּכְּחִין לְחֵינָתָא (נ\"א לחופתא), לָקֳבֵל הַאי מַטְרוֹנִיתָא דִּילִי. הִיא סַלְּקָא עַל כֹּלָּא, מַה אַעְבִיד לָהּ. אֶלָּא כָּל בֵּיתָא דִּילִי יְהֵא בִּידָהָא, אַפִּיק מַלְכָּא כָּרוֹזָא, מֵהָכָא כָּל מִלִּין דְּמַלְכָּא בִּידָא דְּמַטְרוֹנִיתָא יִתְמַסְּרוּן. מַה עָבִיד. אַפְקִיד מַלְכָּא בִּידָהָא כָּל זַיְינִין דִּילֵיהּ, כָּל אִינּוּן מָארֵי מַגִּיחִין קְרָבָא, כָּל אִינּוּן אֲבָנִין יְקִרִין דְּמַלְכָּא, כָּל גִּנְזַיָּיא דְּמַלְכָּא. אָמַר, מֵהָכָא, כָּל מַאן דְּיִצְטְרִיךְ לְמַלְּלָא עִמִּי, לָא יָכִיל לְמַלְּלָא עִמִּי, עַד דְּאוֹדַע לָהּ מַטְרוֹנִיתָא.","כַּךָ קוּדְשָׁא בְּרִיךְ הוּא, מִסְּגִיאוּת חֲבִיבוּתָא וּרְחִימוּתָא דִּילֵיהּ בְּכְּנְסֶת יִשְׂרָאֵל, אַפְקִיד כֹּלָּא בִּרְשׁוּתָהּ, אָמַר, הָא כָּל שָׁאֲרִי, לָא מִשְׁתַּכְּחֵי כְּלוּם לְגַבָּהָא. אָמַר, (שיר השירים ו׳:ט׳) שִׁשִּׁים הֵמָּה מְלָכוֹת וְגוֹ', אַחַת הִיא יוֹנָתִי תַמָּתִי. מַה אַעְבִיד לָהּ, אֶלָּא, הָא כָּל בֵּיתָא דִּילִי בִּידָהָא. אַפִּיק מַלְכָּא כָּרוֹזָא, מֵהָכָא כָּל מִלִּין דְּמַלְכָּא, בִּידָא דְּמַטְרוֹנִיתָא יִתְמַסְּרוּן. אַפְקִיד בִּידָהָא כָּל זַיְינִין דִּילֵיהּ, רוֹמְחִין, וְסַיְיפִין, קַשְׁתִּין, חִצִּין, וַחֲרָבִין, בַּלִסְטְרִין. קַסְטִירָאִין, אָעִין, אֲבָנִין, כָּל אִינּוּן מָארֵי (נ\"א מאני) מַגִּיחֵי קְרָבָא. הֲדָא הוּא דִכְתִיב, הִנִּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים וְגוֹ' כֻּלָּם אֲחוּזִיִ חֶרֶב מְלוּמְּדֵי וְגוֹ'.","אָמַר מַלְכָּא, מִכָּאן וּלְהָלְאָה, קְרָבָא דִּילִי אִתְמְסַר בִּידָךְ, זַיְינִין דִּילִי, מָארֵי מַגִּיחֵי קְרָבָא בִּידָךְ. מִכָּאן וּלְהָלְאָה אַתְּ הֲוֵי נַטְרָא לִי, הֲדָא הוּא דִכְתִיב, (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל. מִכָּאן וּלְהָלְאָה, מַאן דְּאִצְטְרִיךְ לִי, לָא יָכִיל לְמַלְּלָא עִמִּי, עַד דְּאוֹדַע לְמַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. שְׁלִיחָא דְּמַלְכָּא בְּכֹלָּא, כְּמָה דְּאוֹקִימְנָא. אִשְׁתְּכַח דְּכֹלָּא בִּידָהָא, וְדָא הוּא יְקָרָא דְּמַטְרוֹנִיתָא. הֲדָא הוּא דִּכְתִּיב, וַיִּסַּע מַלְאַךְ הָאֱלהִים וְגוֹ', כְּמָה דְּאִתְּמַר.","וַיֵּלֶךָ מֵאַחֲרֵיהֶם, מַאי טַעְמָא מֵאַחֲרֵיהֶם. בְּגִין דְּיִשְׁתְּכָחוּ לְקַמָהָא (נ\"א לגבהא) מָארֵי מַגִּיחֵי קְרָבָא, מָארֵי בַּלִּסְטְרָאוֹת, מָארֵי רוֹמְחִין וְסַיְיפִין, וְאִתְגְּלוּן קַמָהָא, דְּהָא הֲווֹ אַתְיָין מַשִׁירְיָין אַחֲרָנִין, לְאַגָּחָא קְרָבָא בְּיִשְׂרָאֵל מִלְּעֵילָּא, וְעַל דָּא וַיֵּלֶךְ מֵאַחֲרֵיהֶם.","וְתָאנָא, בְּהַהִיא שַׁעֲתָא, אָתָא רַבְרְבָא שֻׁלְטָנָא דִּמְמָנָא עַל מִצְרָאֵי, וְכָנַשׁ שִׁית מֵאָה (רבוון) רְתִיכִין מְקַטְרְגִין, וְעַל כָּל רְתִיכָא וּרְתִיכָא, שִׁית מֵאָה שָׁלְטָנִין מְמָנָן קַטֵיגוֹרִין, הֲדָא הוּא דִכְתִיב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְגוֹ'. וְכִי שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר, לָא הֲווֹ רִכְבֵי מִצְרַיִם, מַאי טַעְמָא וְכֹל רֶכֶב מִצְרָיִם. אֶלָּא הָכִי תָּאנָא, הֲוָה סָמָאֵ\"ל אוֹזִיף לֵיהּ, שִׁית מֵאָה רְתִיכִין מְקַטְרְגִין לְסַיְּיעָא לֵיהּ. הֲדָא הוּא דִכְתִיב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר."],[[0,"מאן דרך עץ החיים:","שואל מי הוא שנקרא דרך עץ החיים. ומשיב, זו היא מטרוניתא הגדולה, שהיא המלכות, שהיא דרך לאילן הגדול והחזק, שהוא ז\"א, הנקרא עץ החיים. שכתוב, הנה מטתו שלשלמה ששים גבורים סביב לה מגבורי ישראל. שהוא ישראל של מעלה שהוא ז\"א. כולם אחוזי חרב."],[1,"כד נטלא מטרוניתא וכו':","כשהמטרוניתא נוסעת כולם נוסעים עמה, ז\"ש, ויסע מלאך האלקים. שואל, וכי המלכות מלאך האלקים נקראת. אמר ר' אבא, כן. בוא וראה, כך אמר ר\"ש, התקין הקב\"ה לפניו, היכל הקודש, היכל עליון, עיר קדושה, עיר עליונה, ירושלים עיר הקדושה נקראת, כל אלו הם שמות של המלכות, מי שבא אל המלך, אינו נכנס, אלא מעיר הקדושה ההוא, שהיא המלכות, ממנה לוקח הדרך אל המלך, כי הדרך מתתקן מכאן."],[2,"הה\"ד זה השער וגו':","ז\"ש, זה השער לה' צדיקים יבואו בו. כל שליחות, שהמלך, שהוא ז\"א, רוצה, יוצאת מבית המטרוניתא, שהיא המלכות. וכל שליחות הבאה מלמטה מן המלך, שהוא ז\"א, נכנסת תחילה אל המטרוניתא, ומשם אל המלך. נמצא שהמטרוניתא היא שליח של כל, הן ממטה למעלה והן ממעלה למטה. ועל כן היא שליח כל, ז\"ש, ויסע מלאך האלקים לפני מחנה ישראל. היינו ישראל של מעלה, שהוא ז\"א, מלאך האלקים, הוא המלכות, ז\"ש בו, והויה הולך לפניהם וגו' להאיר להם ללכת יומם ולילה, וללכת יומם ולילה, הוא כמו שהעמדנו לעיל (אות ס\"ד) שפירושו ז\"א ומלכות, הרי שהמלכות הלכה לפני ישראל. וז\"ש ויסע מלאך האלקים ההולך לפני מחנה ישראל."],[3,"וכי יקרא הוא:","שואל, וכי כבוד הוא למלך, שהוא ז\"א, שהמטרוניתא, שהיא מלכות, תלך ותעשה מלחמה, ותלך בשליחות. ומשיב. אלא בדומה למלך שהזדווג במטרוניתא עליונה, ראה המלך היקר שלה. שהיא עולה על כל שאר המטרוניתות שבעולם, אמר, כולן נחשבות לפלגשים כלפי מטרוניתא הזו שלי, היא עולה על כולן. מה אעשה לה. אלא כל הבית שלי יהיה בידיה. הוציא המלך כרוז, מעתה כל דברי המלך יהיו נמסרים ביד המטרוניתא. מה עשה. הפקיד המלך בידיה כל כלי זיין שלו, כל בעלי המלחמה, כל אבני יקר של המלך, כל אוצרות המלך. אמר, מעתה, כל מי שיבקש לדבר עמי, לא יוכל לדבר עמי, עד שיודיע אל המטרוניתא."],[4,"כך קב\"ה מסגיאות וכו':","כך הקב\"ה מרוב החביבות והאהבה שלו בכנסת ישראל שהיא המלכות, הפקיד הכל ברשותה. אמר, הרי כל השאר, אינן נחשבות אצלה לכלום. אמר, ששים המה מלכות וגו', אחת היא יונתי תמתי. מה אעשה לה, אלא, כל הבית שלי יהיה בידיה. הוציא המלך כרוז, מעתה כל דברי המלך יהיו נמסרים ביד המטרוניתא. הפקיד בידיה כל כלי זיין שלו: רמחים, חרבות, קשתות, חצים, סכינים, אבני בליסטראות, קסטיראין, עצים, ואבנים, וכל בעלי המלחמה. ז\"ש, הנה מטתו שלשלמה ששים גבורים וגו' כלם אחוזי חרב מלומדי מלחמה וגו'."],[5,"אמר מלכא מכאן וכו':","אמר המלך מכאן והלאה, המלחמות שלי תמסרנה בידך, הכלי זיין שלי, ובעלי המלחמה יהיו בידך, מכאן ולהלאה, את תהיי שומרת לי. ז\"ש שומר ישראל, שהוא ז\"א הנק' ישראל. מכאן ולהלאה, מי שצריך לי לא יוכל לדבר עמי עד שמודיע למטרוניתא, ז\"ש ב \u0003זאת\u0004 יבא אהרן אל הקדש. ו \u0003זאת,\u0004 היא המלכות. היא שליח המלך לכל, כמו שהעמדנו, נמצא שהכל הוא בידיה, וזה הוא כבוד המטרוניתא. ז\"ש ויסע מלאך האלקים. כמו שלמדנו."],[6,"וילך מאחריהם:","שואל, מה הטעם שהלך מאחריהם. ומשיב. שהוא כדי שימצא לפניהם, בעלי המלחמה, בעלי בליסטראות, בעלי רמחים וחרבות, ויהיו נגלים לפניהם. כי מחנות אחרות היו באות מלמעלה לעשות מלחמה עם ישראל. וע\"כ וילך מאחריהם. כדי לתת מקום לבעלי המלחמה שמצד ישראל ללחום עמהם."],[7,"ותאנא בההיא שעתא וכו':","ולמדנו. באותה שעה בא שר המושל הממונה על מצרים, ואסף שש מאות מרכבות מקטרגים, ועל כל מרכבה ומרכבה שש מאות שליטים ממונים מקטרגים. ז\"ש ויקח שש מאות רכב בחור וגו'. שואל, וכי שש מאות רכב בחור לא היו רכבי מצרים, ומה הטעם אומר אח\"כ וכל רכבי מצרים. ומשיב, אלא כך למדנו, שסמאל היה משאיל לשר מצרים שש מאות מרכבות מקטרגים לעזור אותו. ז\"ש ויקח שש מאות רכב בחור. שלא היו של מצרים."]],[[0,"","מַה זֶּה דֶּרֶךְ עֵץ הַחַיִּים? זוֹהִי הַגְּבִירָה הַגְּדוֹלָה, שֶׁהִיא דֶרֶךְ לְאוֹתוֹ עֵץ גָּדוֹל חָזָק, עֵץ הַחַיִּים, שֶׁכָּתוּב (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ מִגִּבֹּרֵי יִשְׂרָאֵל. יִשְׂרָאֵל שֶׁלְּמַעְלָה, כֻּלָּם אֲחֻזֵי חֶרֶב."],[1,"","כְּשֶׁנּוֹסַעַת הַגְּבִירָה, כֻּלָּם נוֹסְעִים עִמָּהּ, זֶהוּ שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. וְכִי מַלְאַךְ הָאֱלֹהִים הוּא נִקְרָא? אָמַר רַבִּי אַבָּא, כֵּן. בֹּא רְאֵה, כָּךְ אָמַר רַבִּי שִׁמְעוֹן, הִתְקִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְפָנָיו הֵיכָל קָדוֹשׁ, הֵיכָל עֶלְיוֹן (קדוש), קִרְיָה קְדוֹשָׁה, קִרְיָה עֶלְיוֹנָה, שֶׁנִּקְרֵאת יְרוּשָׁלַיִם עִיר הַקֹּדֶשׁ. מִי שֶׁנִּכְנָס לַמֶּלֶךְ - לֹא נִכְנָס אֶלָּא מֵאוֹתָהּ קִרְיָה קְדוֹשָׁה, נוֹטֵל דֶּרֶךְ לַמֶּלֶךְ, שֶׁהַדֶּרֶךְ מְתֻקֶּנֶת מִכָּאן."],[2,"","זֶהוּ שֶׁכָּתוּב (תהלים קיח) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבֹאוּ בוֹ. כָּל שְׁלִיחוּת שֶׁרוֹצֶה הַמֶּלֶךְ, יוֹצֵאת מִבֵּית הַגְּבִירָה. וְכָל שְׁלִיחוּת מִלְּמַטָּה לַמֶּלֶךְ, (שרוצה המלך) נִכְנֶסֶת קֹדֶם לְבֵית הַגְּבִירָה, וּמִשָּׁם לַמֶּלֶךְ. נִמְצָא שֶׁהַגְּבִירָה הִיא הַשְּׁלִיחָה שֶׁל הַכֹּל, מִלְמַעְלָה לְמַטָּה, וּמִלְּמַטָּה לְמַעְלָה. וְעַל זֶה הִיא שְׁלִיחָה שֶׁל הַכֹּל. זֶהוּ שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל - יִשְׂרָאֵל שֶׁלְּמַעְלָה. מַלְאַךְ הָאֱלֹהִים - זֶהוּ שֶׁכָּתוּב בּוֹ וַה' הֹלֵךְ לִפְנֵיהֶם וְגוֹ'. וְזֶה לָלֶכֶת יוֹמָם וָלַיְלָה, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[3,"","וְכִי כְּבוֹד הַמֶּלֶךְ הוּא שֶׁהַגְּבִירָה תֵּלֵךְ, וְהִיא תַּעֲרֹךְ קְרָב, וְהִיא הוֹלֶכֶת כְּשָׁלִיחַ? אֶלָּא לְמֶלֶךְ שֶׁהִזְדַּוֵּג בִּגְבִירָה עֶלְיוֹנָה. רָאָה הַמֶּלֶךְ אֶת כְּבוֹדָהּ עַל כָּל שְׁאָר גְּבִירוֹת הָעוֹלָם, וְאָמַר: כֻּלָּם נֶחְשָׁבוֹת לְפִילַגְשִׁים (לחפה) כְּנֶגֶד הַגְּבִירָה הַזּוֹ שֶׁלִּי, הִיא עוֹלָה עַל כֻּלָּן, מָה אֶעֱשֶׂה לָהּ? אֶלָּא כָּל הַבַּיִת שֶׁלִּי יִהְיֶה בְּיָדֶיהָ. הוֹצִיא הַמֶּלֶךְ כְּרוּז: מִכָּאן כָּל דִּבְרֵי הַמֶּלֶךְ יִמָּסְרוּ בִּידֵי הַגְּבִירָה. מֶה עָשָׂה? הִפְקִיד הַמֶּלֶךְ בְּיָדֶיהָ כָּל כְּלֵי זֵינוֹ, כָּל אוֹתָם בַּעֲלֵי עוֹרְכֵי קְרָבוֹת, וְכָל אוֹתָם אֲבָנִים יְקָרוֹת שֶׁל הַמֶּלֶךְ וְכָל גִּנְזֵי הַמֶּלֶךְ. אָמַר: מִכָּאן, כָּל מִי שֶׁיִּצְטָרֵךְ לְדַבֵּר עִמִּי, לֹא יוּכַל לְדַבֵּר עִמִּי עַד שֶׁיּוֹדִיעַ לַגְּבִירָה."],[4,"","כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֵרֹב חֲבִיבוּתוֹ וְאַהֲבָתוֹ לִכְנֶסֶת יִשְׂרָאֵל הִפְקִיד הַכֹּל בִּרְשׁוּתָהּ. אָמַר: כָּל הַשְּׁאָר לֹא נֶחְשָׁבִים כְּלוּם לְפָנֶיהָ. אָמַר: (שיר ו) שִׁשִּׁים הֵמָּה מְלָכוֹת וְגוֹ', אַחַת הִיא יוֹנָתִי תַמָּתִי. מָה אֶעֱשֶׂה לָהּ? אֶלָּא הֲרֵי כָּל בֵּיתִי בְּיָדֶיהָ. הוֹצִיא הַמֶּלֶךְ כְּרוּז: מִכָּאן וָהָלְאָה כָּל דִּבְרֵי הַמֶּלֶךְ יִמָּסְרוּ בִּידֵי הַגְּבִירָה. הִפְקִיד בְּיָדֶיהָ כָּל כְּלֵי זֵינוֹ, רְמָחִים, סְיָפִים, קְשָׁתוֹת, חִצִּים וַחֲרָבוֹת, בַּלִּיסְטְרָאוֹת, מוֹשְׁלִים, עֵצִים, אֲבָנִים, וְכָל אוֹתָם בַּעֲלֵי (כלי) עֲרִיכַת קְרָב (לוחמים). זֶהוּ שֶׁכָּתוּב הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים וְגוֹ', כֻּלָּם אֲחֻזֵי חֶרֶב מְלֻמְּדֵי וְגוֹ'."],[5,"","אָמַר הַמֶּלֶךְ, מִכָּאן וָהָלְאָה הַקְּרָב שֶׁלִּי נִמְסָר בְּיָדֵךְ, כְּלֵי הַזַּיִן שֶׁלִּי, בַּעֲלֵי עֲרִיכַת קְרָב בְּיָדֵךְ. מִכָּאן וָהָלְאָה אַתְּ תִּהְיִי שׁוֹמֶרֶת שֶׁלִּי. זֶהוּ שֶׁכָּתוּב (תהלים קכא) שׁוֹמֵר יִשְׂרָאֵל. מִכָּאן וָהָלְאָה, כָּל מִי שֶׁצָּרִיךְ אוֹתִי, לֹא יָכוֹל לְדַבֵּר עִמִּי עַד שֶׁמּוֹדִיעַ לַגְּבִירָה. זֶהוּ שֶׁכָּתוּב (ויקרא טז) בְּזאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. שְׁלִיחַ הַמֶּלֶךְ בַּכֹּל, כְּמוֹ שֶׁבֵּאַרְנוּ. נִמְצָא שֶׁהַכֹּל בְּיָדֶיהָ, וְזֶהוּ כְּבוֹד הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר."],[6,"","וַיֵּלֶךָ מֵאַחֲרֵיהֶם. מָה הַטַּעַם מֵאַחֲרֵיהֶם? כְּדֵי שֶׁיִּמָּצְאוּ לְפָנֶיהָ (אצלה) בַּעֲלֵי עֲרִיכַת הַקְּרָב, בַּעֲלֵי בַלִּיסְטְרָאוֹת, בַּעֲלֵי רְמָחִים וַחֲרָבוֹת, וְנִתְגַּלִּים לְפָנֶיהָ, שֶׁהֲרֵי הָיוּ בָאִים מַחֲנוֹת אֲחֵרִים לַעֲרֹךְ קְרָב בְּיִשְׂרָאֵל מִלְמַעְלָה, וְעַל כֵּן וַיֵּלֶךְ מֵאַחֲ רֵיהֶם."],[7,"","וְשָׁנִינוּ, שֶׁבְּאוֹתָהּ שָׁעָה בָּא שַׁלִּיט הַמְמֻנֶּה עַל הַמִּצְרִים, וְכִנֵּס שֵׁשׁ מֵאוֹת (רבבות) מֶרְכְּבוֹת מְקַטְרְגִים, וְעַל כָּל מֶרְכָּבָה וּמֶרְכָּבָה שֵׁשׁ מֵאוֹת שַׁלִּיטִים מְמֻנִּים קָטֵגוֹרִים. זֶהוּ שֶׁכָּתוּב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר וְגוֹ'. וְכִי שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר לֹא הָיוּ רִכְבֵי מִצְרַיִם? מָה הַטַּעַם וְכֹל רֶכֶב מִצְרָיִם? אֶלָּא כָּךְ שָׁנִינוּ, הָיָה סמא\"ל מַלְוֶה לוֹ שֵׁשׁ מֵאוֹת מֶרְכָּבוֹת שֶׁל מְקַטְרְגִים לְסַיֵּעַ לוֹ. זֶהוּ שֶׁכָּתוּב וַיִּקַּח שֵׁשׁ מֵאוֹת רֶכֶב בָּחוּר."]]],[["אֵימָתַי אַשְׁלִים קוּדְשָׁא בְּרִיךְ הוּא לְסָמָאֵ\"ל. בִּקְרָבָא דְּסִיסְרָא, דְּעִקֵּר קוּדְשָׁא בְּרִיךְ הוּא לְכָל אִינּוּן רְתִיכִין, וְאִתְמְסָרוּ בִּידָא דְּמַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב, (שופטים ה׳:כ״א) נַחַל קִישׁוֹן גְּרָפָם נַחַל קְדוּמִים וְגוֹ'. וּלְזִמְנָא דְּאָתֵי, יִתְמְסָרוּ כֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאָדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'. וְעַל דָּא וַיֵּלֶךְ מֵאַחֲרֵיהֶם, דִּזְמִינָא שְׁכִינְתָּא בְּסוֹף יוֹמַיָּא לְאַעְקְרָא לוֹן מִן עָלְמָא.","וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם, מַאן עַמּוּד הֶעָנָן דָּא. רִבִּי יוֹסֵי אָמַר, דָּא הוּא עֲנָנָא דְּאִתְחָזֵי תָּדִיר עִם שְׁכִינְתָּא. וְדָא הוּא עֲנָנָא דְּעָאל מֹשֶׁה בְּגַוֵּיהּ. רִבִּי אַבָּא אָמַר, כְּתִיב וַיְיָ' הוֹלֵךְ לִפְנֵיהֶם יוֹמָם, אֶלָּא סִיוּעָא דְּצַדִּיק הוּא, וּפְרִישׂוּ דִּרְשִׁימוּ דִּילֵיהּ, וְעַל דָּא אָזִיל הַאי עָנָן יוֹמָם, וּכְתִיב (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ' חַסְדּוֹ. וּמִסִּטְרָא דְּחֶסֶ\"ד אָתָא עֲנָנָא דָּא, וְדָא חֶסֶד אִתְקְרֵי, וַעֲנָנָא אַחֲרָא אָזִיל בְּלֵילְיָא, וְאִתְקְרֵי עַמּוּד אֵשׁ.","רִבִּי שִׁמְעוֹן אָמַר, עַמּוּד הֶעָנָן יוֹמָם: דָּא אַבְרָהָם. וְעַמּוּד הָאֵשׁ לַיְלָה: דָּא יִצְחָק. וְתַרְוַויְיהוּ אִשְׁתְּכָחוּ בִּשְׁכִינְתָּא, וּמַה דְּאָמַר רִבִּי אַבָּא, הָכִי הוּא וַדַּאי, דְּעַל יְדָא דְּהַאי (נ\"א דבהאי) דַּרְגָּא, אִשְׁתְּכָחוּ.","וְהַאי וַיִּסַּע מַלְאַךְ הָאֱלהִים הַהוֹלֵךְ לִפְנִי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע: דְּנָטִיל מִסִּטְרָא דְּחֶסֶ\"ד, וְאִתְדְּבַק בְּסִטְרָא דִּגְבוּרָה, בְּגִין דְּהָא מָטָא שַׁעֲתָא לְאִתְלַבְּשָׁא בְּדִינָא.","תָּא חֲזֵי, בְּהַהִיא שַׁעֲתָא אִשְׁתְּלִים סִיהֲרָא מִכֹּלָּא, וְיָרְתָא שִׁבְעִין וּתְרֵין שְׁמָהָן קַדִּישִׁין, בִּתְלַת סִטְרִין. סִטְרָא חֲדָא אִתְלַבְּשָׁא בְּעִטְרוֹי דְּחֶסֶד עִלָּאָה, בְּשִׁבְעִין גְּלִיפִין דִּנְהִירוּ דְּאַבָּא עִלָּאָה, דְּאַנְהִיר לָהּ.","סִטְרָא תִּנְיָינָא, אִתְלַבְּשַׁת בְּרוֹמְחֵי דִּגְבוּרָ\"ה, בְּשִׁתִין פּוּלְסֵי דְּנוּרָא, וַעֲשָׂרָה דִּילָהּ דִּנְחַתוּ מִסִּטְרָא דְּאִמָא עִלָּאָה בְּנִימוּסֵי גְּלִיפִין.","סִטְרָא תְּלַתָאֵי, אִתְלַבְּשַׁת בִּלְבוּשֵׁי אַרְגְוָנָא, דְּלָבִישׁ מַלְכָּא עִלָּאָה קַדִּישָׁא, דְּאִקְרוּן תִּפְאֶרֶ\"ת, דְּיָרִית בְּרָא קַדִּישָׁא, בְּשִׁבְעִין עִטְרִין עִלָּאִין, מִסִּטְרָא דְּאַבָּא וְאִמָא, וְהוּא כָּלִיל לְהַאי סִטְרָא וּלְהַאי סִטְרָא.","(ס\"א ותרין עטרין מסטרא דאבא ואימא, ואינון שבעין ותרין שמהן.) וְתָנֵינָן מִסִּטְרָא דְּחֶסֶ\"ד שִׁבְעִין וּתְרֵין סָהֲדִין. מִסִּטְרָא דִּגְבוּרָא שִׁבְעִין וּתְרֵין סוֹפְרִין. מִסִּטְרָא דְּת\"ת שִׁבְעִין וּתְרֵין גַּוְונִין לְאִתְפָּאַרָא.","וּבְהַאי אֲתָר, אִתְגְּלִיף חַד בְּחַד, וְאִסְתְּלִיק שְׁמָא קַדִּישָׁא, רָזָא דִּרְתִּיכָא, וְהָכָא אִתְגְּלִיפוּ אֲבָהָתָא, לְאִתְחַבְּרָא בְּחַד, וְהוּא שְׁמָא קַדִּישָׁא גְּלִיפָא בְּאַתווֹי.","צֵרוּפָא דְּאַתְוָון אִלֵּין, אַתְוָון קַדְמָאֵי, רְשִׁימִין כְּסִדְרָן בְּאֹרַח מֵישָׁר, בְּגִין דְּכֻלְּהוּ אַתְוָון קַדְמָאֵי אִשְׁתְּכָחוּ בְּחֶסֶ\"ד, לְמֵהַךְ בְּאֹרַח מֵישָׁר, בְּסִדּוּרָא מִתְתְּקָן.","אַתְוָון תִּנְיָינֵי, רְשִׁימִין בְּגִלְגּוּלָא לְמַפְרֵעַ, בְּגִין דְּכֻלְּהוּ אַתְוָון תִּנְיָינֵי, מִשְׁתַּכְחוּ בִּגְבוּרָה, (ס\"א מגבורה) לְגַלָּאָה דִּינִין וְּזִינִין דְּאַתְיָין מִסִּטְרָא דִּשְׂמָאלָא.","אַתְוָון תְּלִיתָאֵי, אִינּוּן אַתְוָון רְשִׁימָן, לְאַחֲזָאָה גַּוְונִין, לְאִתְעַטְּרָא בְּמַלְכָּא קַדִּישָׁא. וְכֹלָּא בֵּיהּ מִתְחַבְּרָן וּמִתְקַשְּׁרָן, וְהוּא אִתְעַטָּר בְּעִטְּרוֹי בְּאֹרַח מֵישָׁר, וְרָשִׁים לְהַאי סִטְרָא וּלְהַאי סִטְרָא, כְּמַלְכָּא דְּאִתְעַטָּר בְּכֹלָּא.","הָכָא אִתְרְשִׁים שְׁמָא קַדִּישָׁא גְּלִיפָא בְּע\"ב תֵּיבִין, דְּמִתְעַטְּרֵי בַּאֲבָהָתָא, רְתִיכָא קַדִּישָׁא עִלָּאָה. וְאִי תֵּימָא, הָנֵי אַתְוָון תְּלִיתָאֵי, מַאי טַעְמָא לָאו אִינּוּן כְּתִיבִין, מִנְּהוֹן בְּאֹרַח מֵישָׁר כְּסִדּוּרָן, וּמִנְהוֹן לְמַפְרֵעַ, לְיַשְּׁרָא לְהַאי סִטְרָא, וּלְהַאי סִטְרָא, דְּהָא תָּנֵינָן, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד מֵישָׁרִים לִתְרֵי סִטְרֵי, וּכְתִיב (שמותכו) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים וְגוֹ', דָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי יִצְחָק אָמַר, דָּא יַעֲקֹב, וְכֹלָּא חַד.","אֶלָּא לְמַלְכָּא דְּאִיהוּ שְׁלִים מִכֹּלָּא, דַּעְתֵּיהּ שְׁלִים מִכֹּלָּא, מָה אָרְחֵיהּ דְּהַהוּא מַלְכָּא. אַנְפּוֹי נְהִירִין כְּשִׁמְשָׁא תָּדִיר, בְּגִין דְּאִיהוּ שְׁלִים. וְכַד דָּאִין, דָּאִין לְטָב וְדָאִין לְבִישׁ. וְעַל דָּא בָּעֵי לְאִסְתַּמְּרָא מִינֵּיהּ. מַאן דְּאִיהוּ טִפְּשָׁא, חָמֵי אַנְפּוֹי דְּמַלְכָּא נְהִירִין וְחַיְּיכָן, וְלָא אִסִתְּמַר מִינֵּיהּ. וּמַאן דְּאִיהוּ חַכִּימָא, אַף עַל גַּב דְּחָמֵי אַנְפּוֹי דְּמַלְכָּא נְהִירִין, אָמַר מַלְכָּא וַדַּאי שְׁלִים הוּא, שְׁלִים הוּא מִכֹּלָּא, דַּעְתֵּיהּ שְׁלִים, אֲנָא חָמֵי דִּבְהַהוּא נְהִירוּ, דִּינָא יָתִיב וְאִתְכַּסְיָא, אַף עַל גַּב דְּלָא אִתְחַזְיָא, דְּאִי לָאו הָכִי, לָא יְהֵא מַלְכָּא שְׁלִים, וְעַל דָּא בָּעֵי לְאִסְתַּמְּרָא."],[[0,"אימתי אשלים קב\"ה וכו':","מתי שילם הקב\"ה לסמאל. הוא, במלחמת סיסרא, שעקר הקב\"ה לכל אלו המרכבות ונמסרו ביד המטרוניתא. ז\"ש נחל קישון גרפם נחל קדומים וגו'. ולעתיד לבא יהיו נמסרים כולם. ז\"ש מי זה בא מאדום וגו'. ועל כן, \u0003וילך מאחריהם,\u0004 פירושו, שעתידה השכינה \u0003באחרית\u0004 הימים לעקור אותם מן העולם."],[1,"ויסע עמוד הענן וגו':","שואל מי הוא עמוד הענן הזה. ר' יוסי אמר, זה הוא ענן הנראה תמיד עם השכינה, שהוא מלאך מיכאל. וזה הוא הענן שנכנס בו משה. ר' אבא אמר, כתוב, וה' הולך לפניהם יומם בעמוד ענן, הרי שאינו מיכאל שהיא בחינת השכינה, אלא עזרת הצדיק הוא, שהוא יסוד דז\"א, ומפרש חסדים של הרשימה שלו, שהוא המסך, כי היסוד פורש החסדים על החכמה שבמלכות, ואז היא יכולה להאיר. וע\"כ הולך ענן הזה יומם, שהוא זמן הארת החסדים, שכתוב, יומם יצוה ה' חסדו. כי מצד החסד בא ענן הזה, והוא נקרא חסד. וענן אחר הולך בלילה, ונקרא עמוד אש. שהוא מצד המלכות."],[2,"ר' שמעון אמר וכו':","רש\"א, עמוד הענן יומם, זה אברהם, שהוא חסד. ועמוד אש לילה זה יצחק, שהוא גבורה. ושניהם נמצאים בהשכינה. ומה שאמר ר' אבא, שעזרת הצדיק הוא, כן הוא ודאי, שעל ידי מדרגה ההוא, הם נמצאים בהשכינה."],[3,"והאי ויסע מלאך וגו':","ופסוק הזה, ויסע מלאך האלקים ההולך לפני מחנה ישראל וילך מאחריהם, פירושו, \u0003ויסע,\u0004 שנסע מצד החסד והתדבק בצד הגבורה, כי חסד הוא פנים וגבורה היא אחורים. משום שהגיעה השעה להתלבש בדין."],[4,"תא חזי בההיא וכו':","בוא וראה באותה שעה נשלמה הלבנה, שהיא המלכות, מכל הבחינות, וירשה שבעים ושנים שמות קדושים בשלשה צדדים, דהיינו ג' קוין, צד אחד, התלבשה המלכות. בעטרותיו של החסד העליון, בע' חקיקות של אור אבא עלאה שהאיר לה. שה\"ס ויסע וגו'."],[5,"סטרא תנינא וכו':","צד השני, התלבשה המלכות ברמחים של הגבורה, דהיינו הדינים שבה, בששים הכאות של אש, ועשרה הכאות שלה עצמה, שיורדים מצד אמא עלאה, בדינים חקוקים. וה\"ס קו שמאל והפסוק ויבא וגו'."],[6,"סטרא תליתאי וכו':","צד השלישי, התלבשה המלכות בלבוש ארגמן, שלבש מלך העליון הקדוש הנקרא תפארת, שירש בן הקדוש שהוא תפארת בע' עטרות עליונות מצד אבא ואמא, והוא כולל לצד זה ולצד זה. דהיינו לימין שהוא חסד, ולשמאל שהוא גבורה. שה\"ס ויט."],[6,"","ביאור הדברים. כי שורש הקוין הם בבינה, וקו ימין שבה מכונה אבא עלאה, וקו שמאל שבה מכונה אמא עלאה. וקו אמצעי שבה הוא תפארת המכריע ביניהם. שז\"ס \u0003תלת נפקי מחד,\u0004 (כנ\"ל ב\"א אות שס\"ג ע\"ש) וכל הגדלות שגרם התחתון אל העליון, זוכה בו גם התחתון, לפיכך, \u0003חד בתלת קיימא,\u0004 וזכה גם הת\"ת בב' האורות ימין ושמאל של אבא ואמא. (עש\"ה) ואחר כך, כשהשיג הת\"ת ג' הקוין, ב' מאו\"א, ואחד משל עצמו, הוא משפיע אותם אל המלכות."],[6,"","וז\"ש \u0003אשתלים סיהרא מכלא, וירתא שבעין ותרין שמהן קדישין\u0004 (באות ק\"ס) כי ג' קוין אלו ה\"ס ג' הפסוקים: ויסע, ויבא, ויט, שבכל אחד יש ע\"ב אותיות, וצרופם יחד עושה ע\"ב שמות קדושים, שבכל אחד ג' אותיות מג' הפסוקים. וז\"ש \u0003סטרא חדא\u0004 וכו' \u0003דנהירו דאבא עלאה\u0004 שהוא קו ימין שבבינה המאיר לחסד דת\"ת, והיא אתלבשא בעטרוי דחסד העליון הזה דת\"ת וה\"ס הפסוק, ויסע. וכן מקבלת מגבורה דת\"ת הארת קו שמאל מאמא עלאה, המכונה \u0003שתין פולסי דנורא,\u0004 בסו\"ה ששים גבורים סביב לה. וז\"ש, \u0003אתלבשת ברומחי דגבורה,\u0004 דהיינו גבורה שבת\"ת. \u0003בשתין פולסי\u0004 וכו' \u0003מסטרא דאמא עלאה,\u0004 כי ת\"ת מקבלם מקו שמאל דאמא עלאה. וה\"ס הפסוק ויבא. וכן מקבלת מת\"ת דת\"ת, דהיינו בחינתו עצמו של קו אמצעי, וז\"ש \u0003סטרא תליתאי אתלבשת בלבושי ארגוונא\u0004 וכו'. כי להיותו קו אמצעי הוא כולל בתוכו ב' הגוונים לבן ואדום, שהתכללותם ה\"ס הגוון ארגמן. \u0003דירית ברא קדישא\u0004 וכו': \u0003מסטרא דאבא ואמא,\u0004 שהם ב' קוין דבינה, שירש אותם בסוד תלת מחד נפקי חד בתלת קיימא, כנ\"ל."],[6,"","ודע, שבאמת מכונים ב' קוים ימין ושמאל שבבינה בשם חכמה ובינה. אלא שנשתנה שמם לאבא ואמא. ויש להבין זה, למה נשתנה שמם לאבא ואמא. וכן יש להבין למה מכונה ת\"ת, שהוא קו אמצעי לבן שלהם. שמדרך האורות להשתלשל זה מזה בסוד עילה ועלול כסדר המדרגה. וכאן יצאו האורות שלא בסדר המדרגה, כי תקון אחד נעשה שעלתה המלכות לבינה, וקבלה בינה, צורת מלכות המצומצמת. וירדו בינה ותו\"מ שלה למדרגת ז\"א. ועי\"ז, בעת גדלות כשבינה העלתה הבינה ותו\"מ שלה ממדרגת ז\"א עלה גם ז\"א עמהם למקום בינה, ועי\"ז נעשה שם קו אמצעי, וקבל האורות דבינה, אע\"פ שבסדר המדרגה אין ז\"א ראוי כלל לקבל ולהאיר כמו הבינה. ומתוך שאור הזה הגיע לז\"א שלא בסדר המדרגה, אלא ע\"י ירידת בינה ותו\"מ דבינה, והעלתם את הז\"א למקום בינה, וכן ע\"י ענין תלת בחד קיימא, לפיכך מכונה אור הזה בשם אור של תולדה, ולא בדרך השתלשלות עילה ועלול. ולפיכך מכונה ז\"א בשם בן, כלומר אור של תולדה. ולפיכך מכונים החכמה ובינה בשם או\"א, כי הם הולידו את אור הזה שנקרא ז\"א."],[7,"ותרין עטרין מסטרא וכו':","ושתי עטרות מצד אבא ואמא, והם ע\"ב שמות. ולמדנו מצד החסד הם שבעים, ושנים עדים. מצד הגבורה שבעים, ושנים סופרים. מצד הת\"ת שבעים, ושנים צבעים להתפאר."],[7,"","פירוש. כי נתבאר בדבור הסמוך, שת\"ת, שהוא ז\"א, משפיע אל המלכות, \u0003שבעים עטרות\u0004 מכל קו. והטעם הוא, כי אע\"פ שז\"א מקבל ג' קוין דבינה, עם כל זה, אינו מקבל מעצם הג\"ר דב' קוין שבבינה, המכונים או\"א, אלא מז\"ת שלהם, שכל אחד כלול מעשרה, והם ג\"פ \u0003שבעים עטרות.\u0004 אמנם לפי\"ז למה נקרא ע\"ב שמות, היה לו להקרא ע' שמות. וז\"ש \u0003ותרין עטרין מסטרא דאבא ואמא, ואינון שבעין ותרין שמהן.\u0004 כי מלבד ע' עטרין, שה\"ס ז\"ס תחתוניות שהוא מקבל מב' הקוין שבבינה שנקראים אבא ואמא, הוא מקבל עוד ב' עטרין מבח' ג\"ר דאבא ואמא, בסוד חד בתלת קיימא ומטעם זה עלה הת\"ת שהיא בחינת ז\"ת, ונעשה לדעת שהיא בחינת ג\"ר. ומטעם תוספת ב' עטרין דג\"ר הללו הוא נקרא \u0003ע\"ב שמות.\u0004 ותוספת זה יש בכל אחד מג' קוין שלו, שבחסד הם מכונים שנים עדים. ובגבורה שנים סופרים. ובת\"ת שנים צבעים."],[7,"","וטעם היותם מכונים כן, הוא בדמיון לשטר מתנה, שיש שם כתב סופר וחתימת עדים. והנה עיקר כח שטר המתנה, הוא ודאי כתב הסופר, שכותב ופורט כל הערכים שהנותן מקנה אל המקבל. ועם כל זה, אם לא היה שם חתימת העדים, לא היה השטר שוה כלום. ואין צריך לומר, אם היה שם חתימת עדים לבד בלי כתב הסופר, שלא היה שוה כלום."],[7,"","והנה השם ע\"ב כאן, הוא בעיקר להמשיך חכמה אל הנוקבא, בסו\"ה ויסע ויבא ויט. וכבר ידעת, שהחכמה נמשכת רק מקו שמאל, אבל בלי התלבשותה בחסדים שבקו ימין אינה יכולה להאיר. ולפיכך מדמה ב' עטרין שבקו שמאל, לב' סופרים, שכתב סופר הוא העיקר שבשטר, וב' עטרין שבקו ימין מדמה לב' עדים, שאע\"פ שאינם מוסיפים משהו על כתב הסופר, אמנם הם מקיימים לכל השטר, שזולתם אין השטר שוה כלום. אף כאן, בלי החסדים אין הארת החכמה שוה כלום כי אינה יכולה להאיר בלי חסדים, וע\"כ הם מכונים ב' עדים. וב' עטרין שבקו אמצעי הוא מדמה לב' גוונין, והוא מטעם שגוונים מורים על דינים, ומקו האמצעי נמשכים דינים בסוד המסך דחירק, כנודע. אבל אם הם דינים איזה יחס יש להם אל הג\"ר, להקרא ב' עטרין. וז\"ש, \u0003שבעין, ותרין גווני לאתפארא,\u0004 כי דינים האלו, מלבד, שאינם פוגמים כלום את האורות אלא להיפך, שהם \u0003מפארים\u0004 אותם, כי זולתם לא היה יחוד בין ב' הקוין, כנודע."],[8,"ובהאי אתר אתגליף וכו':","ובמקום זה, דהיינו במלכות, נחקק אחד באחד, שהע\"ב עטרין שבכל קו נכללים זה בזה, ועולה מהם השם הקדוש, סוד המרכבה. כי נעשים ע\"ב שמות, שבכל אחד מהם ג' אותיות. וכאן נחקקו האבות, שהם חג\"ת, ג' הקוין. להתחבר יחד. והוא השם הקדוש ע\"ב חקוק באותיותיו."],[9,"צרופא דאתוון אלין וכו':","הצירוף של אותיות האלו הם כך. אותיות הראשונות, שהם ע\"ב אותיות של הפסוק ויסע, רשומים כסדרם \u0003בדרך יושר,\u0004 כי היושר יורה על חסד, משום שכל האותיות הראשונות נמצאות בחסד, דהיינו בקו ימין, ללכת בדרך יושר, בסדור מתוקן."],[10,"אתוון תנייני רשימין וכו':","אותיות השניות, דהיינו ע\"ב אותיות שבהכתוב, ויבא, רשומים בגלגול \u0003למפרע,\u0004 דהיינו שנרשמות ממטה למעלה. כמ\"ש להלן בציור ב'. משום שכל ע\"ב אותיות השניות נמצאות בגבורה, לגלות דינים, וכלי זיין, הבאים מצד השמאל. וכשהן למפרע, רומזות על דינים."],[11,"אתוון תליתאי אינון וכו':","אותיות השלישיות, דהיינו ע\"ב אותיות שבהכתוב, ויט, הן אותיות הרשומות להראות הגוונים, שהם הדינים, להתעטר במלך הקדוש. שה\"ס ע\"ב גוונים לאתפארא (כנ\"ל באות ס\"ג) וכולם מתחברים ומתקשרים בו מטעם היותו קו האמצעי, והוא מתעטר בעטרותיו \u0003בדרך יושר\u0004 ורושם לצד זה ולצד זה, דהיינו לקו ימין ולקו שמאל, כי מקיים הארת שניהם, כמלך שמתעטר מכל."],[12,"הכא אתרשים שמא וכו':","כאן נרשם השם הקדוש. חקוק \u0003בע\"ב תיבות,\u0004 דהיינו שהג' פעמים ע\"ב אותיות, שבכל קו מג' קוים, מתחברים ומשתלבים יחד, ואז עושים ע\"ב תיבות שבכל תיבה ג' אותיות מן ג' הקוין. המתעטרים באבות, דהיינו חג\"ת, שהם מרכבה קדושה העליונה."],[12,"ואי תימא הני וכו':","שואל, ואם תאמר, אלו אותיות השלישיות למה אינם כתובים בב' דרכים, חלקם בדרך יושר כסדרם, וחלקם בדרך למפרע, כדי לישר לצד זה ולצד זה, דהיינו לקו ימין ולקו שמאל, להיותו מקיים הארת שניהם. כי למדנו, אתה כוננת מישרים, פירושו, שהקב\"ה עושה מישרים, ומקיים לב' הצדדים. וכתוב, והבריח התיכון בתוך הקרשים שהוא הקב\"ה, דהיינו קו האמצעי המקיים ב' הצדדים, וא\"כ היה צריך להרשם חציו ביושר כקו ימין, וחציו למפרע כקו שמאל. ר' יצחק אמר זה יעקב. והכל אחד. כי גם יעקב יורה על קו האמצעי."],[13,"אלא למלכא דאיהו וכו':","ומשיב זה דומה, למלך שהוא שלם מכל ודעתו שלם מכל מה דרכו של אותו המלך, פניו מאירים תמיד כשמש. משום שהוא שלם. וכשהוא דן, הוא דן לטוב ודן לרע. ועל כן צריכים להשמר ממנו. מי שהוא טפש, רואה פני המלך מאירים וצוחקים, ואינו נשמר ממנו. ומי שהוא חכם, אע\"פ שרואה פני המלך מאירים, אומר, המלך ודאי שלם הוא, שלם הוא מכל, דעתו שלם, אני רואה שבמאור ההיא יושב דין, והתכסה, אע\"פ שאינו נראה, שאם לא כן לא יהיה המלך שלם, ועל כן צריכים להשמר."]],[[0,"","מָתַי הִשְׁלִים הַקָּדוֹשׁ בָּרוּךְ הוּא לְסמא\"ל? בַּקְּרָב עִם סִיסְרָא, שֶׁעִקֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כָּל אוֹתָן מֶרְכָּבוֹת, וְנִמְסְרוּ בִּידֵי הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב (שופטיםה) נַחַל קִישׁוֹן גְּרָפָם נַחַל קְדוּמִים וְגוֹ'. וְלֶעָתִיד לָבֹא כֻּלָּם יִמָּסְרוּ. זֶהוּ שֶׁכָּתוּב (ישעיהסג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'. וְעַל זֶה וַיֵּלֶךְ מֵאַחֲרֵיהֶם, שֶׁעֲתִידָה הַשְּׁכִינָה בְּסוֹף הַיָּמִים לַעֲקֹר אוֹתָם מִן הָעוֹלָם."],[1,"","וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם, מִי זֶה עַמוּד הֶעָנָן? רַבִּי יוֹסֵי אָמַר, זֶהוּ הֶעָנָן שֶׁנִּרְאֶה תָמִיד עִם הַשְּׁכִינָה, וְזֶהוּ הֶעָנָן שֶׁנִּכְנַס מֹשֶׁה לְתוֹכוֹ. רַבִּי אַבָּא אָמַר, כָּתוּב וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם. אֶלָּא סִיּוּעַ שֶׁל הַצַּדִּיק הוּא, וּפְרִישָׁה שֶׁל הָרֹשֶׁם שֶׁלּוֹ, וְעַל זֶה הָלַךְ הֶעָנָן הַזֶּה יוֹמָם, וְכָתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. וּמִצַּד שֶׁל חֶסֶ\"ד בָּא הֶעָנָן הַזֶּה, וְזֶה נִקְרָא חֶסֶד, וְעָנָן אַחֵר הוֹלֵךְ בַּלַּיְלָה, וְנִקְרָא עַמּוּד אֵשׁ."],[2,"","רַבִּי שִׁמְעוֹן אָמַר, עַמּוּד הֶעָנָן יוֹמָם - זֶה אַבְרָהָם. וְעַמּוּד הָאֵשׁ לַיְלָה - זֶה יִצְחָק. וּשְׁנֵיהֶם נִמְצְאוּ בַּשְּׁכִינָה. וּמַה שֶּׁאָמַר רַבִּי אַבָּא, כָּךְ הוּא וַדַּאי, שֶׁעַל יְדֵי זוֹ (שבזו) הַדַּרְגָּה נִמְצְאוּ."],[3,"","וְזְהִ וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע - שֶׁנָּסַע מִצַּד שֶׁל חֶסֶ\"ד, וְנִדְבַּק בְּצַד הַגְּבוּרָה, מִשּׁוּם שֶׁהֲרֵי הִגִּיעַ הַזְּמַן לְהִתְלַבֵּשׁ בְּדִין."],[4,"","בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה נִשְׁלְמָה הַלְּבָנָה מֵהַכֹּל, וְיָרְשָׁה שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת קְדוֹשִׁים בִּשְׁלֹשָׁה צְדָדִים. צַד אֶחָד הִתְלַבֵּשׁ בַּעֲטֶרֶת הַחֶסֶד הָעֶלְיוֹן בְּשִׁבְעִים חֲקִיקוֹת שֶׁל אוֹר שֶׁל הָאַבָּא הָעֶלְיוֹן שֶׁמֵּאִיר לָהּ."],[5,"","הַצַד הַשֵּׁנִי הִתְלַבֵּשׁ בְּרָמְחֵי הַגְּבוּרָ\"ה, בְּשִׁשִּׁים מַכּוֹת אֵשׁ, וַעֲשָׂרָה שֶׁלָּהּ שֶׁיָּרְדוּ מִצַּד הָאִמָּא הָעֶלְיוֹנָה בְּמִנְהָגִים חֲקוּקִים."],[6,"","צַד שְׁלִישִׁי הִתְלַבֵּשׁ בִּלְבוּשֵׁי אַרְגָּמָן שֶׁלּוֹבֵשׁ הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, שֶׁנִּקְרָאִים תִּפְאֶרֶ\"ת, שֶׁיּוֹרֵשׁ הַבֵּן הַקָּדוֹשׁ בְּשִׁבְעִים עֲטָרוֹת עֶלְיוֹנוֹת מִצַּד שֶׁל הָאָב וְהָאֵם, וְהוּא כּוֹלֵל אֶת הַצַּד הַזֶּה וְהַצַּד הַזֶּה."],[7,"","(ושתי עטרות מצד של אבא ואמא, והם שבעים ושנים שמות.) וְשָׁנִינוּ, מִצַּד הַחֶסֶ\"ד שִׁבְעִים וּשְׁנַיִם עֵדִים. מִצַּד הַגְּבוּרָה שִׁבְעִים וּשְׁנַיִם סוֹפְרִים. מִצַּד הַתִּפְאֶרֶת שִׁבְעִים וּשְׁנַיִם גְוָנִים לְהִתְפָּאֵר."],[8,"","וּבְמָקוֹם זֶה נֶחְקַק אֶחָד בְּאֶחָד, וְהִתְעַלָּה הַשֵּׁם הַקָּדוֹשׁ, סוֹד הַמֶּרְכָּבָה, וְכָאן נֶחְקְקוּ הָאָבוֹת לְהִתְחַבֵּר בְּאֶחָד, וְהוּא הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּאוֹתִיּוֹתָיו."],[9,"","צֵרוּף הָאוֹתִיּוֹת הַלָּלוּ, אוֹתִיּוֹת רִאשׁוֹנוֹת, רְשׁוּמוֹת כַּסְּדָרִים בְּסֵדֶר יָשָׁר, מִשּׁוּם שֶׁכָּל הָאוֹתִיּוֹת הָרִאשׁוֹנוֹת נִמְצְאוּ בְּחֶסֶ\"ד, לָלֶכֶת בְּדֶרֶךְ יָשָׁר בְּסִדּוּר מְתֻקָּן."],[10,"","אוֹתִיּוֹת שְׁנִיּוֹת רְשׁוּמוֹת בְּגִלְגּוּל לְמַפְרֵעַ, מִשּׁוּם שֶׁכָּל הָאוֹתִיּוֹת הַשְּׁנִיּוֹת נִמְצָאוֹת בִּגְבוּרָה (מגבורה), לְגַלּוֹת דִּינִים וּמִינִים שֶׁבָּאִים מִצַּד הַשְּׂמֹאל."],[11,"","אוֹתִיּוֹת שְׁלִישִׁיּוֹת הֵן אוֹתִיּוֹת רְשׁוּמוֹת, לְהַרְאוֹת גְּוָנִים, לְהִתְעַטֵּר בַּמֶּלֶךְ הַקָּדוֹשׁ. וְהַכֹּל מִתְחַבְּרִים וְנִקְשָׁרִים בּוֹ, וְהוּא מִתְעַטֵּר בְּעַטְרוֹתָיו בְּדֶרֶךְ יָשָׁר, וְרוֹשֵׁם אֶת הַצַּד הַזֶּה וְאֶת הַצַּד הַזֶּה, כְּמוֹ מֶלֶךְ שֶׁמִּתְעַטֵּר בַּכֹּל."],[12,"","כָּאן נִרְשָׁם הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּשִׁבְעִים וּשְׁתַּיִם תֵּבוֹת שֶׁמִּתְעַטְּרוֹת בָּאָבוֹת, הַמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה. וְאִם תֹּאמַר, מָה הַטַּעַם אֵינָן כְּתוּבוֹת הָאוֹתִיּוֹת הַשְּׁלִישִׁיּוֹת הַלָּלוּ, מֵהֶם בְּסֵדֶר יָשָׁר כְּסִדְרָם, וּמֵהֶם לְמַפְרֵעַ, לְיַשֵּׁר אֶת הַצַּד הַזֶּה וְאֶת הַצַּד הַזֶּה, שֶׁהֲרֵי שָׁנִינוּ, אַתָּה כּוֹנַנְתָּ מֵישָׁרִים - הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה מֵישָׁרִים לִשְׁנֵי הַצְּדָדִים, וְכָתוּב (שמות כו) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים וְגוֹ', זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי יִצְחָק אָמַר, זֶה יַעֲקֹב. וְהַכֹּל אֶחָד."],[13,"","הַמֶּלֶךְ וַדַּאי הוּא שָׁלֵם, שָׁלֵם מֵהַכֹּל, שָׁלֵם בְּדַעְתּוֹ, אֲנִי רוֹאֶה שֶׁבְּאוֹתוֹ הָאוֹר יוֹשֵׁב בְּדִין וְנִתְכַּסֶּה, אַף עַל גַּב שֶׁלֹּא נִרְאֶה, שֶׁאִם לֹא כָּךְ, לֹא יִהְיֶה מֶלֶךְ שָׁלֵם, וְלָכֵן צָרִיךְ לְהִשָּׁמֵר."]]],[["כַּךָ קוּדְשָׁא בְּרִיךְ הוּא, שְׁלִים תָּדִיר בְּהַאי גַּוְונָא וּבְהַאי גַּוְונָא, אֲבָל לָא אִתְחַזְיָא, אֶלָּא בִּנְהִירוּ דְּאַפִּין. וּבְגִין כַּךְ, אִינּוּן טִפְּשִׁין חַיָּיבִין לָא אִסְתַּמְּרָן מִנֵּיהּ. אִינּוּן חַכִּימִין זַכָּאִין, אַמְרִין, מַלְכָּא שְׁלִים הוּא, אַף עַל גַּב [אָמְרוּ הַמָגִיהִים כָּאן מָצָאנוּ כָּתוּב פָּסוּק וַיִסָע כָּסֶדֶר כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זה בָּעֵי לְאִסְתַּמְּרָא מִנֵּיהּ.","אָמַר רִבִּי יְהוּדָה, מֵהָכָא, (מלאכי ג׳:ו׳) אֲנִי יְיָ' לֹא שָׁנִיתִי. לָא דָּלִיגְנָא לַאֲתָר אַחֲרָא, בִּי אִתְכְּלִיל כֹּלָּא. הָנִי תְּרֵי גַּוְונֵי בִּי אִתְּכְּלִילָן, בְּגִין כַּךְ כֹּלָּא בְּאֹרַח מֵישָׁר אִתְחַזְיָא, וְאַף עַל גַּב דְּאַתְוָון אֲחִידָן לְהַאי סִטְרָא וּלְהַאי סִטְרָא, כְּסִדְרָן כְּתִיבִין.","(שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם וַיַּעֲמוֹד מֵאַחֲרֵיהֶם. עַד כָּאן סִטְרָא חַד, חֶסֶד לְאַבְרָהָם. אָמַר רִבִּי שִׁמְעוֹן, אֶלְעָזָר בְּרִי, תָּא חֲזֵי רָזָא דָּא. כַּד עַתִּיקָא קַדִּישָׁא אַנְהִיר לְמַלְכָּא, אַנְהִיר לֵיהּ, (ס\"א עטר ליה ואחסין ליה, בכתרין וכו') וְעִטְּרִין לֵיהּ, בְּכִתְרִין קַדִּישִׁין עִלָּאִין, כַּד מָטָאן לְגַבֵּיהּ מִתְעַטְּרֵי אֲבָהָתָא, בְּשַׁעֲתָה דְּמִתְעַטְּרֵי אֲבָהָתָא, כְּדֵין הוּא שְׁלִימוּ דְּכֹלָּא. כְּדֵין מַטְרוֹנִיתָא, נַטְלָא בְּמַטְלָנָהָא, (בההוא) (נ\"א בשולטנא בההיא) שְׁלִימוּ דַּאֲבָהָתָא. וְכַד מִתְעַטְּרָא מִכֻּלְּהוֹן, כְּדֵין אִתְבָּרְכָא, וּרְשׁוּתָא דְּכֹלָּא בִּידָהָא.","כְּגַוונָא דָּא שְׁמָא קַדִּישָׁא גְּלִיפָא בְּאַתווֹי רְשִׁימִין בִּרְתִיכָא עִלָּאָה קַדִּישָׁא עִטּוּרָא דַּאֲבָהָן. אָמְרוּ הַמָגִיהִים כָּאן מָצָאנוּ כָּתוּב פָּסוּק וַיִסָע כָּסֶדֶר כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זה הַלָּשׁוֹן עַד כָּאן אִתְתְקַנוּ טוּרִין כְּסִדְרָן בְּרָזָא דְחֶסֶד לָא סַטָאן לִימִּינָא וּשְׂמָאלָא. אַחַר כֵּן מָצָאנוּ פָּסוּק וַיָּבֹא לְמַפְרֵעַ כּמוֹ כֵן כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זְהִ הַלָּשׁוֹן עַד כָּאן אִתְתְקַנוּ טוּרִין לְמפרֵעַ בְּרָזָא דִּגְבוּרָה כֻּלְהוּ שְׂמֹאלָא כְּלִילָן בִּימִינָא. אַחַר כָּךְ מָצָאנוּ פָּסוּק וָיֵט כַּסֶדֶר כְּמוֹ כֵן כָּל אוֹת וְאוֹת בְּבַיִת אֶחָד בִּמְרוּבָּע עִם זה הַלָּשׁוֹן עַד כָּאן כְּלִילָן טוּרִין דִּשְׁמָא קַדִּישָׁא בְּתִפְאֶרֶת לְבַתָר מִתְחֲבְּרָן אֲבָהָן וְאִתְעַבִידוּ שֶׁמָּא קַדִּישָׁא. וְאַחַר כָּךְ מָצָאנוּ הע\"ב שְׁמוֹת הַיוֹצְאִים מִשלשָׁה פְּסוּקִים אֵלּוּ בִּמְרוּבָּע כָּל שםׁ וְשֵׁם מִשלשָׁה אוֹתִיּוֹת הַיוֹצְאִים מִשְׁלשָׁה פְּסוּקִים אֵלּוּ יָשָׁר הָפוּךְ יָשָׁר וְהַסִימָן יה\"י אוֹר עִם זֶהּ הַלָּשׁוֹן הָא כְּגַוְנָא דָא שֶׁמָּא קַדִּישָׁא גְלִיפָא בְּאַתְווֹי רְשִׁימִין בִּרְתִיכָא עִלָּאָה קַדִּישָׁא עִטוּרָא דְאֲבַהָן. ולא הדפסנו אותו כאן מפני יקר תפארת גדולתו. (והודפס בסוף הספר)","(אמר רבי ייסא, אשכחנא ברזא דא בתקיעותא (ס\"א דרב בבבל) דרב המנונא סבא, תלת ובכן ובכן ובכן, לקבלי הני תלת. וכך הוא סדורא. אמר רבי יוסי, כלא אתכליל בהאי שמא (נ\"א שליחא) קדישא, ואסתיים ביה, אשתכח דשלימו דרתיכא קדישא אית ביה.)","אָמַר רִבִּי שִׁמְעוֹן, הַאי הוּא שְׁמָא קַדִּישָׁא, עִטּוּרָא דַּאֲבָהָן, דְּמִתְעַטְרָא בְּגִלּוּפַיְיהוּ, בְּחִבּוּרָא כַּחֲדָא. שְׁלִימוּ דִּרְתִיכָא קַדִּישָׁא. וְאִתְכְּלִיל בְּאַרְבְּעִין וּתְמַנְיָא תֵּיבוּתָא, דְּאִיהוּ שְׁלִימוּ דְּכֹלָּא, וְעִקָרָא דְּשָׁרָשִׁין.","תָּא חֲזֵי, גּוּפָא דְּאִילָנָא, אֲנִ\"י אָלֶ\"ף (ויקרא קנ\"א) נוּ\"ן יוֹ\"ד. רֵישָׁא דְּכָל עַנְפֵי אִילָנָא, וָה\"וּ. (וה\"ו) וְהָא אִתְּעֲרוּ חַבְרַיָּא, כְּלָלָא דַּעֲנָפִין וְנוֹפָא וְשָׁרָשָׁא, בְּאַרְבְּעִין וּתְמַנְיָא תֵּיבִין. וְהָא אִתְרְשִׁים בִּתְלַת עָלְמִין עִלָּאִין, ובג' עָלְמִין תַּתָּאִין.","לָקֳבְלֵיהּ, קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת. קָדוֹשׁ לְעֵילָּא. קָדוֹשׁ בְּאֶמְצָעִיתָא. קָדוֹשׁ לְתַתָּא. קָדוֹשׁ חֶסֶד. קָדוֹשׁ גְּבוּרָה. קָדוֹשׁ תִּפְאֶרֶת. וְכֻלְּהוּ בְּשִׁבְעִין וּתְרֵין אִתְגְּלִיפוּ, כְּמָה דְּאִתְּמַר. בְּרִיךְ הוּא, בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין אָמֵן.","אָמַר רִבִּי יִצְחָק, בְּשַׁעֲתָא דְּשָׁרוּ יִשְׂרָאֵל עַל יַמָּא, חָמוּ לְכַמָּה אֹכְלוֹסִין, לְכַמָּה חַיָּילִין, לְכַמָּה מַשִּׁירְיָין, מֵעֵילָּא וְתַתָּא, וְכֻלְּהוּ בִּכְנוּפְיָא עֲלַיְיהוּ דְּיִשְׂרָאֵל, שָׁרִיאוּ בִּצְלּוֹ מִגּוֹ עָאקוּ דִּלְהוֹן."],[[0,"כך קודשא בריך הוא וכו':","כך הקב\"ה, הוא תמיד שלם באפן זה ובאפן זה, דהיינו בצד ימין ובצד שמאל, אבל אינו נראה אלא בפנים מאירות, ומשום זה, אלו כסילים הרשעים אינם נשמרים ממנו. אבל אלו חכמים הצדיקים אומרים, המלך שלם הוא, ואע\"פ שפניו נראים מאירות, הדין מתכסה בתוכם. משום זה צריכים להשמר ממנו. פירוש, שבזה מיושב הקושיא, למה לא נרשמו ע\"ב אותיות שבקו אמצעי, חציים ביושר וחציים למפרע, כדי לכלול בתוכו גם הדינים שבשמאל. שהוא מטעם שהדינים שבשמאל מכוסים בו, ופניו שמחים ומאירים תמיד כמו אורות הימין, וע\"כ אותיותיו רשומות ביושר לבד, כמו הימין."],[1,"אמר ר' יהודה וכו':","אר\"י, מכאן, יש לישב הקושיא למה לא נרשמו ע\"ב אותיות דקו האמצעי, מחציתם ביושר ומחציתם למפרע. שכתוב, אני הוי\"ה לא שניתי. שפירושו, לא דלגתי למקום אחר. שאע\"פ שב' הקוין נכללים כי מכל מקום לא שניתי עצמי משום זה לדלוג לבחינת השמאל, אלא נשארתי בבחינת הימין. כי בי נכלל הכל, ואלו ב' גוונים לבן ואדום, בי דהיינו בחסדים שלי, נכללו. ואין הארת השמאל נראה בי אלא במלכות. ומשום זה כל האותיות שבקו האמצעי נראות בדרך יושר, ואע\"פ שהאותיות אחוזים לצד זה ולצד זה, דהיינו לימין ושמאל, מכל מקום, כתובים כסדרם ביושר."],[2,"ויסע מלאך האלקים וגו':","עד כאן צד אחד, חסד לאברהם, קו ימין. אמר ר' שמעון, אלעזר בני, בוא וראה סוד הזה. כשעתיקא קדישא האיר אל המלך, שהוא ז\"א, האיר לו והעטיר אותו בכתרים קדושים העליונים, שהם אור החסדים דאו\"א עלאין, שהם ג\"ר, וכשמגיעים אצלו החסדים מתעטרים האבות, שהם ג' קוין חג\"ת, ובשעה שמתעטרים האבות, אז הוא שלמות הכל. אז המטרוניתא נוסעת במסעיה, עם השלמות ההיא של האבות. וכשהיא מתעטרת מכולם, מכל ג' האבות, שהם ג' קוין, אז היא מתחברת ורשות הכל היא בידיה."],[3,"כגוונא דא שמא וכו':","כעין זה, השם הקדוש חקוק באותיות הרשומות במרכבה העליונה שהם העטור של האבות."],[4,"אמר ר' ייסא וכו':","אר\"י, מצאנו בסוד הזה בתקיעת שופר של ר' המנונא סבא ג' פעמים, ובכן ובכן ובכן, דהיינו ובכן יתגדל, ובכן תן פחדך, ובכן תן כבוד. ואינו גורס, ובכן צדיקים, שהם כנגד אלו השלשה פסוקים ויסע ויבא ויט. וכך הוא הסדר. ג' ולא יותר. פירוש. כי בכן בגימטריא ע\"ב, וע\"כ רומזים ג\"פ ובכן על ג' קוין של שם ע\"ב. אמר ר' יוסי, הכל נכלל בשם הקדוש הזה, ונסתם בו, דהיינו שכל ג' הקוין של השם ע\"ב, נכללים בהמלכות, ונמצא ששלימות המרכבה הקדושה יש בו, במלכות. וע\"כ יש ד' פעמים ע\"ב, ג' הקוין חסד גבורה ות\"ת, ומלכות. ולפיכך יש ג\"כ ד\"פ ובכן. דהיינו שגורס גם, ובכן צדיקים."],[5,"אמר ר' שמעון וכו':","אר\"ש, זה הוא שם הקדוש, העטור של האבות, שהם חג\"ת, שמתעטרים בחקיקתם בחיבורם יחד. והם השלימות של מרכבה הקדושה. ונכלל בארבעים ושמונה תיבות, שהוא שלמות הכל, והעיקר של השרשים."],[5,"","פירוש. הע\"ב שמות, שהם ע\"ב תיבות של שלשה אותיות, נחלקות לג' שלישים, לפי ג' קוין שבו. שליש הא' הוא חסד, קו ימין. שליש הב' הוא גבורה, קו שמאל. שליש הג', הוא תפארת, קו האמצעי. ונודע, שעיקר הקוין הם, הימין והשמאל, והם בחי' הג\"ר, אבל קו האמצעי אינו אלא שמקיים הארתם, והוא בחי' ו\"ק. ובב' השלישים של חסד וגבורה יש ארבעים ושמונה תבות. וז\"ש \u0003ואיתכליל בארבעין ותמניא תיבותא,\u0004 שכל האורות של השם הזה נכללים בב' שלישים הראשונים שהם ארבעים ושמונה תיבות. \u0003דאיהו שלימו דכלא ועקרא דשרשין.\u0004 כי ב' הקוין ימין ושמאל הם שלמות כל השם ועיקר השרשים. כי כל השרשים נמצאים בהם, ושליש התחתון, דהיינו כ\"ד אותיות של קו הג' הם רק ענפים לעליונים, שמקבל מהם, בסוד חד בתלת קיימא תלת בחד יתיב, (כנ\"ל ב\"א דף רפ\"ז ד\"ה תלת)."],[6,"תא חזי, גופא וכו':","בוא וראה, גוף האילן הוא השם \u0003אנ\"י\u0004 הנמצא באמצעם של הע\"ב שמות, דהיינו שם הל\"ז, הראש של כל ענפי האילן הוא השם \u0003וה\"ו,\u0004 שהוא השם הראשון של הע\"ב שמות. וכבר העירו החברים, שכלל הענפים והגוף והשורש נמצאים בארבעים ושמונה תיבות, דהיינו בב' שלישים הראשונים של הע\"ב תיבות, כמ\"ש בדבור הסמוך. וכך נרשם בג' עולמות העליונים, שהם חב\"ד הכלולים בכ\"ד תיבות הראשונות, שהם חסד, וקו ימין. ובג' עולמות התחתונים, שהם חג\"ת הכלולים בכ\"ד תיבות השניות, שהם גבורה וקו שמאל. פירוש. כי ג' הקוין חסד גבורה ת\"ת נכללים זה מזה, ויש בכל אחד ג', ואז נבחן קו הימין לחב\"ד, וקו השמאל לחג\"ת, וקו האמצעי לנה\"י. וע\"כ נמצאים ב' שלישים הראשונים של הע\"ב תיבות שהם בחב\"ד חג\"ת."],[7,"לקבליה, קדוש וכו':","כנגדו חג\"ת אלו שבג' קוין של השם ע\"ב, הוא קדוש קדוש קדוש ה' צבאות. קדוש למעלה, בחב\"ד, קדוש באמצע, בחג\"ת, קדוש למטה, בנה\"י וכן קדוש הא' הוא חסד, קדוש הב' גבורה, קדוש הג' ת\"ת. דהיינו כמ\"ש לעיל בסמוך, שחג\"ת ה\"ס חב\"ד חג\"ת נה\"י. וכולם נחקקו בע\"ב, כמו שנתבאר. ברוך הוא ברוך שמו לעולם ולעולמי עולמים אמן."],[8,"אמר ר' יצחק וכו':","אר\"י, בשעה שישראל חנו על הים, ראו כמה המונים, כמה חיילים, וכמה מחנות מלמעלה ומלמטה, וכולם באו בקיבוץ על ישראל. התחילו ישראל בתפלה מתוך צרתם."]],[[0,"","כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלֵם תָּמִיד בְּגָוֶן זֶה וּבְגָוֶן זֶה, אֲבָל לֹא נִרְאֶה, אֶלָּא בְּפָנִים מְאִירוֹת. וְלָכֵן אוֹתָם רְשָׁעִים הַטִּפְּשִׁים לֹא נִשְׁמָרִים מִמֶּנּוּ. אוֹתָם חֲכָמִים צַדִּיקִים אוֹמְרִים: מֶלֶךְ שָׁלֵם הוּא. אַף עַל פִּי שֶׁפָּנָיו נִרְאִים מְאִירוֹת, הַדִּין מְכֻסֶּה בְתוֹכוֹ, וְלָכֵן צָרִיךְ לְהִשָּׁמֵר מִמֶּנּוּ."],[1,"","אָמַר רַבִּי יְהוּדָה, מִכָּאן (מלאכי ג) אֲנִי ה' לֹא שָׁנִיתִי. לֹא דִלַּגְתִּי לְמָקוֹם אַחֵר, בִּי נִכְלָל הַכֹּל. שְׁנֵי הַגְּוָנִים הַלָּלוּ נִכְלְלוּ בִי. מִשּׁוּם כָּךְ הַכֹּל נִרְאֶה בְּדֶרֶךְ יָשָׁר, וְאַף עַל גַּב שֶׁהָאוֹתִיּוֹת אֲחוּזוֹת לְצַד זֶה וּלְצַד זֶה, הֵן כְּתוּבוֹת כְּסִדְרָן."],[2,"","וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם וַיִּסַּע עַמּוּד הֶעָנָן מִפְּנֵיהֶם וַיַּעֲמֹד מֵאַחֲרֵיהֶם. עַד כָּאן צַד אֶחָד, חֶסֶד לְאַבְרָהָם. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּנִי, בֹּא רְאֵה הַסּוֹד הַזֶּה. כְּשֶׁהָעַתִּיק הַקָּדוֹשׁ מֵאִיר לַמֶּלֶךְ, מֵאִיר לוֹ (מעטר אותו ומוריש לו בכתרים וכו') וּמְעַטֵּר אוֹתוֹ בִּכְתָרִים קְדוֹשִׁים עֶלְיוֹנִים. כְּשֶׁמַּגִּיעִים אֵלָיו, מִתְעַטְּרִים הָאָבוֹת. וּבְשָׁעָה שֶׁהָאָבוֹת מִתְעַטְּרִים, אָז הוּא שְׁלֵמוּת הַכֹּל, אָז הַגְּבִירָה נוֹסַעַת בְּמַסָּעֶיהָ (באותה) (בשלטון בזה) שְׁלֵמוּת שֶׁל הָאָבוֹת. וּכְשֶׁמִּתְעַטֶּרֶת מִכֻּלָּם, אָז מִתְבָּרֶכֶת, וּרְשׁוּת שֶׁל הַכֹּל בְּיָדֶיהָ."],[3,"","וְסָתוּם בּוֹ כְּמוֹ זֶה הַשֵּׁם הַקָּדוֹשׁ חָקוּק בְּאוֹתִיּוֹת רְשׁוּמוֹת בַּמֶּרְכָּבָה הַקְּדוֹשָׁה הָעֶלְיוֹנָה, עִטּוּר הָאָבוֹת."],[4,"","אָמַר רַבִּי יֵיסָא, מָצָאנוּ בְּסוֹד זֶה בִּתְקִיעַת הַשּׁוֹפָר (של רב בבבל) שֶׁל רַב הַמְנוּנָא סָבָא שָׁלֹשׁ וּבְכֵן וּבְכֵן וּבְכֵן, כְּנֶגֶד שָׁלֹשׁ אֵלֶּה, וְכָךְ הַסֵּדֶר. אָמַר רַבִּי יוֹסֵי, הַכֹּל נִכְלָל בַּשֵּׁם (שליח) הַקָּדוֹשׁ הַזֶּה וּמִסְתַּיֵּם בּוֹ, נִמְצָא שֶׁשְּׁלֵמוּת הַמֶּרְכָּבָה הַקְּדוֹשָׁה יֵשׁ בּוֹ."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, זֶהוּ הַשֵּׁם הַקָּדוֹשׁ, עִטּוּר שֶׁל הָאָבוֹת שֶׁמִּתְעַטְּרִים בַּחֲקִיקוֹתֵיהֶם בְּחִבּוּר כְּאֶחָד. שְׁלֵמוּת הַמֶּרְכָּבָה הַקְּדוֹשָׁה. וְנִכְלָל בְּאַרְבָּעִים וּשְׁמוֹנֶה תֵבוֹת, שֶׁהוּא שְׁלֵמוּת הַכֹּל וְעִקַּר הַשָּׁרָשִׁים."],[6,"","בֹּא רְאֵה, גּוּף הָעֵץ - אֲנִ\"י, אָלֶ\"ף נוּ\"ן יוֹ\"ד. רֹאשׁ שֶׁל כָּל עַנְפֵי הָעֵץ - וָה\"וּ. וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, כְּלָל שֶׁל עֲנָפִים וְנוֹף וְשֹׁרֶשׁ בְּאַרְבָּעִים וּשְׁמוֹנֶה תֵבוֹת. וַהֲרֵי נִרְשָׁם בִּשְׁלֹשָׁה עוֹלָמוֹת עֶלְיוֹנִים וּבִשְׁלֹשָׁה עוֹלָמוֹת תַּחְתּוֹנִים."],[7,"","כְּנֶגְדּוֹ - קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ ה' צְבָאוֹת. קָדוֹשׁ לְמַעְלָה, קָדוֹשׁ בָּאֶמְצַע, קָדוֹשׁ לְמַטָּה. קָדוֹשׁ חֶסֶד, קָדוֹשׁ גְּבוּרָה, קָדוֹשׁ תִּפְאֶרֶת. וְכֻלָּם נֶחְקְקוּ בְּשִׁבְעִים וּשְׁתַּיִם, כְּמוֹ שֶׁנֶּאֱמַר. בָּרוּךְ הוּא, בָּרוּךְ שְׁמוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים אָמֵן."],[8,"","אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהָיוּ יִשְׂרָאֵל שְׁרוּיִים עַל הַיָּם, רָאוּ כַּמָּה אוּכְלוּסִים, כַּמָּה חֲיָלוֹת, וְכַמָּה מַחֲנוֹת מִלְמַעְלָה וּמִלְּמַטָּה, וְכֻלָּם בְּכִנּוּס עַל יִשְׂרָאֵל. הִתְחִילוּ בִּתְפִלָּה מִתּוֹךְ צָרָתָם."]]],[["בֵּיהּ שַׁעֲתָא, חָמוּ יִשְׂרָאֵל עָאקוּ מִכָּל סִטְרִין, יַמָּא בְּגַלּוֹהִי דְּזַקְפָן קָמַיְיהוּ. בַּתְרַיְיהוּ, כָּל אִינּוּן אֹכְלוֹסִין, כָּל אִינּוּן מַשִּׁירְיָין דְּמִצְרַיִם, לְעֵילָּא עֲלַיְיהוּ כַּמָּה קַטֵיגוֹרִין. שָׁרִיאוּ צַוְוחִין לְקוּדְשָׁא בְּרִיךְ הוּא.","כְּדֵין כְּתִיב, וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. וְתָאנָא בְּסִפְרָא דִּצְנִיעוּתָא, אֵלַי, (כ\"א ע\"א) דַּיְיקָא, בְּעַתִּיקָא תַּלְיָא כֹּלָּא. בֵּיהּ שַׁעֲתָא אִתְגְּלֵי עַתִּיקָא קַדִּישָׁא, וְאִשְׁתְּכַח רַעֲוָא בְּכֻלְּהוּ עָלְמִין עִלָּאִין, כְּדֵין נְהִירוּ דְּכֹלָּא, אִתְנְהִיר.","אָמַר רִבִּי יִצְחָק, כְּדֵין, כַּד אִתְנְהִיר כֹּלָּא כַּחֲדָא, וְעָבִיד יַמָּא נִימּוּסִין עִלָּאִין, וְאִתְמְסָרוּ בִּידוֹי עִלָּאִין וְתַתָּאִין. וּבְגִינֵי כַּךְ, קַשְׁיָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא כֹּלָּא, כִּקְרִיעַת יָם סוֹף, וְכֹלָּא הָכִי אוּקְמוּהָ. מַאי טַעֲמָא. בְּגִין דִּקְרִיעַת יָם (בראשית ר\"ס ע\"א) סוּף בְּעַתִּיקָא תַּלְיָיא.","אָמַר רִבִּי שִׁמְעוֹן, חַד אַיַּילְתָּא אִית בְּאַרְעָא, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד סַגְיָא בְּגִינָהּ, בְּשַׁעֲתָא דְּהִיא צוֹוַחַת, קוּדְשָׁא בְּרִיךְ הוּא שָׁמַע עָאקוּ דִּילָהּ, וְקָבִּיל קַלָהּ. וְכַד אִצְטְרִיךְ עָלְמָא לְרַחֲמֵי לְמַיָּיא, הִיא יָהָבַת קָלִין, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁמַע קַלָהּ, וּכְדֵין חַיִּיס עַל עָלְמָא, הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם.","וְכַד בַּעְיָא לְאוֹלָדָא, הִיא סְתִימָא מִכָּל סִטְרִין, כְּדֵין אַתְיָיא וְשַׁוִּיאַת רֵישָׁא בֵּין בִּרְכָּהָא, וְצוֹוַחַת וְרָמַת קַלִין, וְקוּדְשָׁא בְּרִיךְ הוּא חַיִּיס עָלָּה, (רי\"ט ע\"ב) וְזַמִּין לְקַבְּלָהּ חַד נָחָשׁ, וְנָשִׁיךְ בְּעַרְיָיתָא דִּילָהּ, וּפָתַח לָהּ, וְקָרַע לָהּ הַהוּא אֲתָר, וְאוֹלִידַת מִיָּד. אָמַר רַבִּי שִׁמְעוֹן בְּהַאי מִלָּה, לָא תִּשְׁאַל וְלָא תְּנַסֶּה אֶת יְיָ', וְהָכִי דַּיְיקָא.","(שמות י״ד:ל׳) וַיּוֹשַע יְיָ' בְּיוֹם הַהוּא אֶת יִשְׂרָאֵל וְגוֹ', וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, הַהוּא שֻׁלְטָנָא מְמָנָא דְּמִצְרָאֵי, אַחְמֵי לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דְּאַעְבַּר לֵיהּ, בִּנְהַר (ז' ע\"א, רכ\"ב ע\"ב) דִּינוּר, דְּהֲוָה בִּשְׂפָתָא דְּיַמָּא רַבָּא. מֵת, מַאי טַעֲמָא מֵת. כְּמָה דְּאוּקְמוּהָ, דְּאַעְבְּרוּ לֵיהּ, מֵהַהוּא שֻׁלְטָנוּתָא דִּילֵיהּ.","(שמות י״ד:ל״א) וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְגוֹ'. רִבִּי חִיָּיא אָמַר, הָכָא אִשְׁתְּלִים יְדָא, וְכֻלְּהוּ אֶצְבְּעָן, וְאִשְׁתְּלִים יְדָא, דְּאִתְכְּלִיל בֵּיהּ בִּימִינָא, דְּהָכִי תָּנִינָן, כֹּלָּא בִּימִינָא אִתְכְּלִיל, וּבִימִינָא תַּלְיָא, הֲדָא הוּא דִּכְתִּיב, יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.","וְאָמַר רִבִּי יִצְחָק, לָא אַשְׁכַּחְנָא, מַאן דְּאַתְקִיף לִבֵּיהּ, לְגַבֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, כְּפַרְעֹה. אָמַר רִבִּי יוֹסֵי, סִיחוֹן וְעוֹג הָכִי נַמֵּי. אָמַר לֵיהּ, לָאו הָכִי. אִינּוּן לְגַבֵּיהּ דְּיִשְׂרָאֵל אִתְתְּקָפוּ, אֲבָל לְגַבֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא, כְּמָה דְּאִתְּקַף פַּרְעֹה רוּחֵיהּ לָקֳבְלֵיהּ, וַהֲוָה חָמֵי כָּל יוֹמָא גְּבוּרָאן דִּילֵיהּ, וְלָא הֲוָה תָּב.","אָמַר רִבִּי יְהוּדָה אָמַר רִבִּי יִצְחָק, פַּרְעֹה חַכִּים מִכָּל חֲרָשׁוֹי הֲוָה, וּבְכָל אִינּוּן כִּתְרִין, וּבְכָל אִינּוּן יְדִיעָן, אִסְתָּכַּל. וּבְכָל סִטְרָא דִּלְהוֹן, לָא חָמָא פּוּרְקָנָא דִּלְהוֹן יִשְׂרָאֵל, וְלָא הֲוָה תָּלֵי בְּחַד מִנַּיְיהוּ. וְעוֹד, דְּהָא בְּכֻלְּהוּ קְשִׁירוּ קִשְׁרָא עֲלַיְיהוּ דְּיִשְׂרָאֵל, וּפַרְעֹה לָא סָבַר דְּאִית קִשְׁרָא אַחֲרָא דִּמְהֵימָנוּתָא, דְּאִיהוּ שַׁלִיט עַל כֹּלָּא. וְעַל דָּא הֲוָה אַתְקִיף לִבֵּיהּ.","רִבִּי אַבָּא אָמַר, לָא אַתְקִיף לִבָּא דְּפַרְעֹה, אֶלָּא שְׁמָא דָּא. דְּכַד הֲוָה אָמַר מֹשֶׁה, כֹּה אָמַר יְיָ', דָּא מִלָּה מַמָּשׁ, אַתְקִיף לִבֵּיהּ, הֲדָא הוּא דִּכְתִּיב, (שמות ט׳:י״ב) וַיְחַזֵּק יְיָ' אֶת לֵב פַּרְעֹה. דְּהָא בְּכָל חָכְמְתָא דִּילֵיהּ, לָא אִשְׁתְּכַח, דִּשְׁמָא דָּא שָׁלִיט בְּאַרְעָא. וְעַל דָּא אָמַר, מִי יְיָ'. וּלְבָתַר אָמַר, יְיָ' הַצַּדִּיק. אָמַר רִבִּי יוֹסֵי, לְבָתַר אָמַר, (שמות י) חָטָאתִי לַיְיָ' הַהוּא פּוּמָא דְּאָמַר דָּא, אָמַר דָּא.","רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (איוב ט׳:כ״ב) אַחַת הִיא עַל כֵּן אָמַרְתִּי תָּם וְרָשָׁע הוּא מְכַלֶּה. הַאי קְרָא, אוּקְמוּהָ בְּרָזָא דְּחָכְמְתָא. אַחַת הִיא, מַאי אַחַת הִיא. הֲדָא הוּא דִּכְתִּיב, (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. וּבְהַאי, קוּדְשָׁא בְּרִיךְ הוּא דָּאִין דִּינוֹי לְתַתָּא, וְדָאִין דִּינוֹי לְעֵילָּא בְּכֹלָּא."],[[0,"ביה שעתא חמו וכו':","בה בשעה, ראו ישראל מצוקה מכל הצדדים, הים עם גליו המתרוממים היה לפניהם, ואחריהם, כל אלו הממונים וכל המחנות של מצרים, ולמעלה, היו עליהם כמה מקטריגים. התחילו צועקים אל הקב\"ה."],[1,"כדין כתיב, ויאמר וגו':","אז כתוב, ויאמר ה' אל משה מה תצעק אלי. ולמדנו בספרא דצניעותא, אלי, הוא בדיוק, שהוא מדת ז\"א, כי הכל תלוי בעתיק, בה בשעה נגלה עתיקא קדישא ונמצא הרצון בכל עולמות העליונים, ואז האיר האור של הכל."],[1,"","פירוש. נודע שחכמת המצרים היתה מצד שמאל, בסוד התנין הגדול הרובץ בתוך יאוריו (כנ\"ל פ' בא אות ל\"ח) וחכמה זו יש לה שורש בבינה דא\"א שיצאה לחוץ מראשו. ולקריעת ים סוף ולהטביע את המצרים, היה צריך מתחילה לבטל את שורשם הגבוה שבקדושה, שבא\"א. וזה לא היה אפשר זולת באור הגדול של עתיקא קדישא שהיא שורש הכל."],[1,"","וז\"ש, שז\"א אמר, מה תצעק אלי, \u0003בעתיקא תלייא כלא,\u0004 אשר אורו הגדול יכול לבטל שורש המצרים שבבינה דא\"א, כהתבטל הנר בפני האבוקה, וז\"ש, \u0003כדין נהירו דכלא אתנהיר,\u0004 כי אור עתיקא הוא אור של הכל, והכל בטלים לאורו, ובזה נתבטל לשעתו שורש הגבוה של המצרים."],[2,"אמר ר' יצחק וכו':","אר\"י, אז כשהאיר הכל יחד, כי אור עתיקא אע\"פ שהוא חסדים מכוסים, עם כל זה כולל בתוכו גם חכמה משום שהחכמה שבא\"א מקובלת ממנו בהכרח, וע\"כ החסדים דעתיק חשובים מחכמה דא\"א, ונחשב שכולל אותו, והחכמה וחסדים מאירים בו יחד. וע\"כ עשה הים החוקים העליונים, דהיינו להטביע את המצרים ולהציל את ישראל שנמסרו בידו העליונים ותחתונים. ומשום זה אמרינן, שבני חיי ומזוני הכל קשה לפני הקב\"ה כמו קריעת ים סוף. והכל אומרים כך. מהו הטעם. משום שקריעת ים סוף נתלה בעתיקא. כמ\"ש בדבור הסמוך."],[3,"אמר ר' שמעון וכו':","אר\"ש, אילה אחת יש בארץ, והקב\"ה עושה הרבה בשבילה, בשעה שהיא צועקת הקב\"ה שומע צרתה ומקבל קולה. וכשהעולם צריכים לרחמים על מים, היא נותנת קולות, והקב\"ה שומע קולה, ואז מרחם הקב\"ה על העולם. ז\"ש, כאיל תערוג על אפיקי מים."],[4,"וכד בעיא לאולדא וכו':","וכשצריכה לילד היא סתומה מכל הצדדים, ומשימה ראשה בין ברכיה, וצועקת ומרימה קולות, והקב\"ה מרחם עליה, ומזמין לה נחש אחד, שנושך בערותה ופותח אותה וקורע לה אותו מקום, ומולידה מיד. אמר ר\"ש בדבר זה לא תשאל ולא תנסה את ה'. וכך הוא דוקא."],[5,"ויושע וגו' את מצרים מת:","הראה אותם הקב\"ה את השר הממונה על המצרים, שהעביר אותו בנהר דינור שהיה בשפת ים העליון, שהיא מלכות. \u0003מת,\u0004 מהו הטעם שמת. הלא אין מיתה במלאכים. הוא כמו שהעמדנו שהעבירו אותו מן הממשלה שלו, שנחשב לו כמיתה."],[6,"וירא וגו' היד הגדולה:","ר' חייא אמר, כאן, ביד הגדולה, נשלם יד השמאל, שהוא גבורה וכל האצבעות שהן חג\"ת נ\"ה שבה. ונשלם היד שמאל, מטעם שנכלל בימין, וכך למדנו, הכל נכלל בימין ותלוי בימין. ז\"ש ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב. ואע\"פ שזה שייך לגבורה מ\"מ כיון שתלוי ביד ימין, ע\"כ נקרא על שמו."],[7,"ואמר ר' יצחק וכו':","לא מצאנו מי שחיזק את לבו לפני הקב\"ה, כפרעה. אמר ר' יוסי הרי סיחון ועוג חזקו ג\"כ את לבם. אמר לו, אינו כן הם חזקו את לבם כנגד ישראל, אבל כנגד הקב\"ה לא חזקו את לבם כמו שחיזק פרעה את רוחו כנגדו, שהיה רואה גבורותיו ולא היה שב."],[8,"א\"ר יהודה וכו':","אר\"י א\"ר יצחק. פרעה, היה חכם יותר מכל מכשפיו. ובכל אלו הכתרים ובכל אלו הידיעות של הס\"א הסתכל. ובכל הצד שלהם לא ראה שיהיה גאולה לישראל, ולא היתה תלויה באחד מהכתרים שלהם. ועוד, כי בכל הכחות העליונים של הס\"א קשרו קשר על ישראל, שלא יוכלו לצאת מתחת ידיהם, ופרעה לא חשב, שיש קשר אחר של אמונה, השולט על כל הכחות של הס\"א. וע\"כ היה מחזק את לבו."],[9,"ר' אבא אמר וכו':","רא\"א, לא חיזק פרעה את לבו אלא על השם הזה, הוי\"ה. כי כשהיה אומר משה כה אמר הויה, מלה זו ממש, דהיינו הוי\"ה, חיזק את לבו, ז\"ש ויחזק \u0003הויה\u0004 את לב פרעה. כי בכל החכמה שלו לא מצא ששם הזה ישלוט בארץ, ועל כן אמר \u0003מי הויה.\u0004 ואח\"כ כשחשב לשוב, אמר, \u0003הויה הצדיק.\u0004 אמר ר' יוסי, אח\"כ אמר \u0003חטאתי להוי\"ה,\u0004 פה הזה שאמר, זה, מי הויה. אמר זה, חטאתי להויה."],[10,"ר' חזקיה פתח וכו':","רח\"פ ואמר, אחת היא על כן אמרתי תם ורשע הוא מכלה. מקרא זה העמידהו בסוד החכמה. \u0003אחת היא,\u0004 מהו אחת היא. ומשיב, ז\"ש אחת היא יונתי תמתי אחת היא לאמה. שהיא המלכות. ובזו דן הקב\"ה דיניו למטה, ודן דיניו למעלה בכל."]],[[0,"","בְּאוֹתָהּ הַשָּׁעָה רָאוּ יִשְׂרָאֵל צָרוֹת מִכָּל הַצְּדָדִים: הַיָּם בְּגַלָּיו שֶׁעוֹלִים לִפְנֵיהֶם. מֵאֲחוֹרֵיהֶם כָּל אוֹתָם אוּכְלוּסִים, כָּל אוֹתָם מַחֲנוֹת מִצְרַיִם. מֵעֲלֵיהֶם כַּמָּה קָטֵגוֹרִים. הִתְחִילוּ צוֹוְחִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא."],[1,"","אָז כָּתוּב, וַיֹּאמֶר ה' אֶל מֹשֶׁה מַה תִּצְעַק אֵלָי. וְשָׁנִינוּ בְּסִפְרָא דִצְנִיעוּתָא, אֵלַי דַּוְקָא, הַכֹּל תָּלוּי בָּעַתִּיק. בְּאוֹתָהּ הַשָּׁעָה נִגְלָה הָעַתִּיק הַקָּדוֹשׁ, וְנִמְצָא רָצוֹן בְּכָל הָעוֹלָמוֹת הָעֶלְיוֹנִים, וְאָז הָאוֹר שֶׁל הַכֹּל הֵאִיר."],[2,"","אָמַר רַבִּי יִצְחָק, אָז, כְּשֶׁהַכֹּל מֵאִיר כְּאֶחָד, וְעָשָׂה הַיָּם מִנְהָגִים עֶלְיוֹנִים, וְנִמְסְרוּ בְיָדוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים. וְלָכֵן קָשֶׁה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הַכֹּל כְּמוֹ קְרִיעַת יַם סוּף. וְהַכֹּל כָּךְ פֵּרְשׁוּהָ. מָה הַטַּעַם? מִשּׁוּם שֶׁקְּרִיעַת יַם סוּף תְּלוּיָה בָּעַתִּיק."],[3,"","אָמַר רַבִּי שִׁמְעוֹן, יֵשׁ אַיֶּלֶת אַחַת בָּרָקִיעַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה הַרְבֵּה בִּשְׁבִילָהּ. בְּשָׁעָה שֶׁהִיא צוֹוַחַת, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ אֶת הַצָּרָה שֶׁלָּהּ וּמְקַבֵּל קוֹלָהּ, וּכְשֶׁהָעוֹלָם צָרִיךְ לְרַחֲמִים, הִיא נוֹתֶנֶת קוֹלוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵעַ אֶת קוֹלָהּ, וְאָז חָס עַל הָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם."],[4,"","וּכְשֶׁרוֹצָה לְהוֹלִיד, הִיא נִסְתֶּרֶת מִכָּל הַצְּדָדִים, וְאָז בָּאָה וְשָׂמָה רֹאשָׁהּ בֵּין בִּרְכֶּיהָ, וְצוֹוַחַת וּמְרִימָה קוֹלוֹת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלֶיהָ, וּמְזַמֵּן כְּנֶגְדָּהּ אוֹתָהּ נָחָשׁ אֶחָד, וְנוֹשֵׁךְ בְּעֶרְוָתָהּ, וּפוֹתֵחַ אוֹתָהּ וְקוֹרֵעַ לָהּ אוֹתוֹ מָקוֹם, וּמוֹלִידָה מִיָּד. אָמַר רַבִּי שִׁמְעוֹן, בַּדָּבָר הַזֶּה אַל תִּשְׁאַל וְאַל תְּנַסֶּה אֶת ה', וְכָךְ דַּוְקָא."],[5,"","וַיּוֹשַׁע ה' בַּיּוֹם הַהוּא אֶת יִשְׂרָאֵל וְגוֹ', וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת. אוֹתוֹ שַׁלִּיט מְמֻנֶּה עַל הַמִּצְרִים הֶרְאָה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמַּעֲבִיר אוֹתוֹ בִּנְהַר דִּינוּר, שֶׁהָיָה בִּשְׂפַת הַיָּם הַגָּדוֹל. מֵת, מָה הַטַּעַם מֵת? כְּמוֹ שֶׁבֵּאֲרוּהוּ, שֶׁהֶעֱבִירוּ אוֹתוֹ מִשִּׁלְטוֹנוֹ."],[6,"","וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ'. רַבִּי חִיָּיא אָמַר, כָּאן הִשְׁתַּלְּמָה הַיָּד וְכָל הָאֶצְבָּעוֹת, וְנִשְׁתַּלְּמָה הַיָּד, שֶׁנִּכְלְלָה בּוֹ בַּיָּמִין. שֶׁכָּךְ שָׁנִינוּ, הַכֹּל נִכְלָל בַּיָּמִין וְתָלוּי בַּיָּמִין, זֶהוּ שֶׁכָּתוּב יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב."],[7,"","וְאָמַר רַבִּי יִצְחָק, לֹא מָצָאתִי מִי חִזֵּק לִבּוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ פַרְעֹה. אָמַר רַבִּי יוֹסֵי, סִיחוֹן וְעוֹג גַּם כָּךְ. אָמַר לוֹ, לֹא כָּךְ! הֵם הִתְחַזְּקוּ כְּנֶגֶד יִשְׂרָאֵל, אֲבָל לְגַבֵּי הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא כְּמוֹ שֶׁפַּרְעֹה חִזֵּק אֶת רוּחוֹ כְּנֶגְדּוֹ, וְהָיָה רוֹאֶה כָּל יוֹם אֶת הַגְּבוּרוֹת שֶׁלּוֹ וְלֹא הָיָה שָׁב."],[8,"","אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יִצְחָק, פַּרְעֹה הָיָה חָכָם מִכָּל מְכַשְּׁפָיו וּבְכָל אוֹתָם הַכְּתָרִים, וּבְכָל אוֹתָן הַיְדִיעוֹת הִסְתַּכֵּל. וּבְכָל הַצַּד שֶׁלָּהֶם לֹא רָאָה אֶת גְּאֻלַּת יִשְׂרָאֵל, וְלֹא הָיָה תּוֹלֶה בְּאֶחָד מֵהֶם. וְעוֹד, שֶׁהֲרֵי בְּכֻלָּם קָשְׁרוּ קֶשֶׁר עַל יִשְׂרָאֵל, וּפַרְעֹה לֹא סָבַר שֶׁיֵּשׁ קֶשֶׁר אֱמוּנָה אַחֵר שֶׁשּׁוֹלֵט עַל הַכֹּל, וְלָכֵן הָיָה מְחַזֵּק אֶת לִבּוֹ."],[9,"","רַבִּי אַבָּא אָמַר, רַק הַשֵּׁם הַזֶּה חִזֵּק אֶת לֵב פַּרְעֹה. שֶׁכְּשֶׁהָיָה מֹשֶׁה אוֹמֵר כֹּה אָמַר ה' - הַדָּבָר הַזֶּה מַמָּשׁ חִזֵּק אֶת לִבּוֹ. זֶהוּ שֶׁכָּתוּב וַיְחַזֵּק ה' אֶת לֵב פַּרְעֹה. שֶׁהֲרֵי בְּכָל הַחָכְמָה שֶׁלּוֹ לֹא נִמְצָא שֶׁהַשֵּׁם הַזֶּה שׁוֹלֵט בָּאָרֶץ. וְעַל זֶה אָמַר, מִי ה'? וְאַחַר כָּךְ אָמַר, ה' הַצַּדִּיק. אָמַר רַבִּי יוֹסֵי, אַחַר כָּךְ אָמַר (שמות י) חָטָאתִי לַה'. אוֹתוֹ פֶּה שֶׁאָמַר זֶה - אָמַר זֶה."],[10,"","רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (איוב ט) אַחַת הִיא עַל כֵּן אָמַרְתִּי תָּם וְרָשָׁע הוּא מְכַלֶּה. פָּסוּק זֶה הִתְבָּאֵר בְּסוֹד הַחָכְמָה. אַחַת הִיא, מַה זֶּה אַחַת הִיא? זֶהוּ שֶׁכָּתוּב (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. וּבָזֶה הַקָּדוֹשׁ בָּרוּךְ הוּא דָּן דִּינָיו לְמַטָּה, וְדָן דִּינָיו לְמַעְלָה בַּכֹּל."]]],[["וְכַד קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר דִּינוֹי, דָּאִין דִּינוֹי בְּהַאי כִּתְרָא, כְּדֵין כְּתִיב, תָּם וְרָשָׁע הוּא מְכַלֶּה. בְּגִין דְּאִינּוּן צַדִּיקַיָּיא, מִתַּפְסָאן בְּחוֹבֵיהוֹן דְּרַשִׁיעַיָּא, דִּכְתִּיב, (שמואל ב כ״ד:ט״ז) וַיֹּאמֶר יְיָ' לַמַּלְאָךְ הַמַּשְׁחִית בָּעָם רַב וְגוֹ', וְעַל דָּא אָמַר (ר' יוסי) אִיּוֹב מִלָּה דָּא, (אמר) וְלא אַגְמָר מִלָּה, וְאוֹקְמוּהָ טוֹל הַרָב, רִבִּי יֵיסָא אָמַר, אַחַת הִיא: דָּא כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא דְּמִצְרַיִם, דִּבְגִינָהּ קָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרָאֵי, וְעָבִיד בְּהוּ נוּקְמִין, הֲדָא הוּא דִכְתִיב תָּם וְרָשָׁע הוּא מְכַלֶּה.","ר' חִיָּיא אָמַר, אִיּוֹב לָא אַלְקֵי, אֶלָּא בְּזִמְנָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם. אָמַר אִיּוֹב, אִי הָכִי, כָּל אַפַּיָּיא שָׁוִין, תָּם וְרָשָׁע הוּא מְכַלֶּה, פַּרְעֹה אַתְקִיף בְּהוּ בְּיִשְׂרָאֵל, וְאָמַר (שמות ה׳:ב׳) מִי יְיָ' אֲשֶׁר אֶשְׁמַע בְּקוֹלוֹ. וַאֲנָא לָא אַתְקִיפְנָא בְּהוּ, וְלָא עֲבִידְנָא מִידִי, תָּם וְרָשָׁע הוּא מְכַלֶּה. הֲדָא הוּא דִכְתִיב, (שמות ט׳:כ׳) הַיָּרֵא אֶת דְּבַר יְיָ' מֵעַבְדֵי פַּרְעֹה, זֶה אִיּוֹב.","ר' יְהוּדָה אָמַר, אִינּוּן אַבְנֵי בַּרְדָּא, דַּהֲווֹ נַחְתִּין, אִתְעַכְּבוּ עַל יְדוֹי דְּמֹשֶׁה, לְבָתַר עָבְדוּ נוּקְמִין, בְּיוֹמֵי דִּיהוֹשֻׁעַ. וּלְזִמְנָא דְּאָתֵי, זְמִינִין לְאַחֲתָא אִינּוּן דְּאִשְׁתָּאָרוּ, עַל אֱדוֹם וּבְנוֹתֶיהָ. אָמַר רִבִּי יוֹסֵי, הֲדָא הוּא דִכְתִיב, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת.","דָּבָר אַחֵר וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְגוֹ', הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. בְּקַדְמִיתָא וַיַּרְא יִשְׂרָאֵל, וּבָתַר וַיִּירְאוּ הָעָם אֶת יְיָ'. אֶלָּא אָמַר רִבִּי יְהוּדָה, הַהוּא סָבָא דְּנָחַת עִם בְּנוֹי בְּגָלוּתָא, וְסָבִיל עָלֵיהּ גָּלוּתָא, וְאָעִיל לִבְנוֹי בְּגָלוּתָא, הוּא מַמָּשׁ חָמָא, כָּל אִינּוּן נוּקְמִין, וְכָל גְּבוּרָאן, דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, הֲדָא הוּא דִכְתִיב וַיַּרְא יִשְׂרָאֵל, יִשְׂרָאֵל מַמָּשׁ.","וְאָמַר רִבִּי יְהוּדָה, סָלִיק קוּדְשָׁא בְּרִיךְ הוּא לְהַאי סָבָא, וְאֲמַר לֵיהּ, קוּם חָמֵי בְּנָיךְ דְּנָפְקִין מִגּוֹ עַמָּא תַּקִּיפָא. קוּם חָמֵי גְּבוּרָן דַּעֲבָדִית, בְּגִין בְּנָיךְ בְּמִצְרַיִם.","וְהַיְינוּ דְּאָמַר רִבִּי יֵיסָא, בְּשַׁעֲתָא דְּנַטְלֵי יִשְׂרָאֵל לְנַחְתָּא בְּגָלוּתָא דְּמִצְרַיִם, דְּחִילוּ וְאֵימָתָא תַּקִּיפָא נָפַל עֲלוֹי. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב, אֲמַאי אַתְּ דָּחִיל, (בראשית מ״ו:ג׳) אַל תִּירָא מֵרְדָה מִצְרַיְמָה. מִמַּה דִּכְתִּיב אַל תִּירָא, מַשְׁמַע דְּחִילוּ הֲוָה דָּחִיל.","אָמַר לֵיהּ כִּי לְגוֹי גָּדוֹל אֲשִׂימְךָ שָׁם. אָמַר לֵיהּ, דָּחִילְנָא דִּי יְשִׁיצוּן בָּנַי. אָמַר לֵיהּ, אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה. אָמַר לֵיהּ תּוּ דָּחִילְנָא, דְּלָא אַזְכֵּי לְאִתְקַבְּרָא בֵּינִי אֲבָהָתַי, וְלָא אַחְמֵי פּוּרְקָנָא דְּבָנַי, וּגְבוּרָאן דְּתַעְבִיד לְהוּ. אָמַר לֵיהּ, וְאָנֹכִי אֲעַלְךָ גַּם עָלה, אַעַלְךָ לְאִתְקַבְּרָא בְּקִבְרֵי אֲבָהָתָךְ. גַּם עָלֹה, לְמֵחֱמֵי פּוּרְקָנָא דִבְרָךְ, וּגְבוּרָאן דְּאַעֲבִיד לְהוּ.","וְהַהוּא יוֹמָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, סָלִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב, וְאָמַר לֵיהּ, קוּם, חָמֵי בְּפוּרְקָנָא דִבְרָךְ, דְּכַמָּה חֵילִין וּגְבוּרָאן עֲבָדִית לְהוּ, וְיַעֲקֹב הֲוָה תַּמָן, וְחָמָא כֹּלָּא, הֲדָא הוּא דִכְתִיב וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה.","ר' יִצְחָק אָמַר, מֵהָכָא, (דברים ד׳:ל״ז) וַיּוֹצִיאֲךָ בְּפָנָיו בְּכֹחוֹ הַגָּדוֹל מִמִּצְרַיִם. מַאי בְּפָנָיו. בְּפָנָיו דָּא יַעֲקֹב, דְּאָעִיל לְכֻלְּהוּ תַּמָּן. רִבִּי חִזְקִיָּה אָמַר, וַיּוֹצִיאֲךָ בְּפָנָיו, בְּפָנָיו: דָּא אַבְרָהָם. דִּכְתִּיב, (בראשית י״ז:י״ז) וַיִּפֹּל אַבְרָהָם עַל פָּנָיו.","תָּא חֲזֵי, אַבְרָהָם אָמַר, הַלְּבֶן מֵאָה שָׁנָה יִוָּלֵד וְגוֹ', אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, חַיֶּיךָ, אַתְּ תֶּחמֵי כַּמָּה אֹכְלוֹסִין, וְכַמָּה חַיָּילִין דְּיִפְקוּן מִמְּךָ. בְּשַׁעֲתָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, כָּל אִינּוּן שְׁבָטִין, כָּל אִינּוּן רִבְוָון, סָלִיק קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם, וְחָמָא לוֹן, הֲדָא הוּא דִכְתִיב וַיּוֹצִיאֲךָ בְּפָנָיו. רִבִּי אַבָּא אָמַר כֻּלְּהוּ אֲבָהָתָא אִזְדְּמָנוּ תַּמָּן בְּכָל הַהוּא פּוּרְקָנָא. הֲדָא הוּא דִּכְתִּיב וַיּוֹצִיאֲךָ בְּפָנָיו. מַאי בְּפָנָיו אִלֵּין אֲבָהָתָא.","רִבִּי אֶלְעָזָר אָמַר, וַיּוֹצִיאֲךָ בְּפָנָיו: דָּא יַעֲקֹב. בְּכֹחוֹ: דָּא יִצְחָק. הַגָּדוֹל: דָּא אַבְרָהָם. אָמַר רִבִּי שִׁמְעוֹן, וְכֵן בְּגִינֵיהוֹן דַּאֲבָהָתָא, אִזְדָּמַן פּוּרְקָנָא תָּדִיר לְיִשְׂרָאֵל, דִּכְתִּיב (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכּוֹר וְהָאָרֶץ אֶזְכּוֹר. אֲבָהָתָא תִּינַח, מַהוּ וְהָאָרֶץ אֶזְכּוֹר. אֶלָּא, לְאַכְלְלָא עִמְּהוֹן דָּוִד מַלְכָּא, דְּאִיהוּ רְתִיכָא בַּאֲבָהָתָא וְאִינּוּן מִתְעָרִין פּוּרְקָנָא תָּדִיר לְיִשְׂרָאֵל."],[[0,"וכד קודשא בריך הוא וכו':","וכשהקב\"ה מעורר דיניו, דן דיניו בכתר זה, שהוא המלכות, אז כתוב, תם ורשע הוא מכלה, משום שהצדיקים נתפשים בעונות הרשעים, שכתוב, ויאמר ה' למלאך המשחית בעם \u0003רב\u0004 וגו'. שפירושו קח הרב שבהם. ועל כן אמר איוב דבר זה, תם ורשע הוא מכלה, ולא פירש הדבר, שהכונה על הצדיקים הנתפשים בעונות הרשעים. ר' ייסא אמר, \u0003אחת היא,\u0004 זו כנסת ישראל בגלות מצרים, שבשבילה הרג הקב\"ה במצרים ועשה בהם נקמות. ז\"ש, תם ורשע הוא מכלה. שהרי גם תמימים היו שם, שלא שעבדו את ישראל, ונהרגו יחד עם הרשעים שבהם."],[1,"ר' חייא אמר וכו':","רח\"א, איוב לא נלקה אלא בזמן שיצאו ישראל ממצרים. אמר איוב, אם כן כל הפנים שוים, תם ורשע הוא מכלה, פרעה התקיף את ישראל, ואמר, מי ה' אשר אשמע בקולו. ואני לא התקפתי אותם, ולא עשיתי כלום, תם ורשע הוא מכלה. ז\"ש, הירא את דבר ה' מעבדי פרעה, זהו איוב. כי היה בזמן יציאת מצרים."],[2,"ר' יהודה אמר וכו':","רי\"א, אבני ברד האלו שהיו יורדים על המצרים ונעכבו על ידי משה, עשו אח\"כ נקמות בימי יהושע, ולעתיד לבא עתידים לרדת הנשארים, על אדום ובנותיה. א\"ר יוסי, ז\"ש כימי צאתך מארץ מצרים אראנו נפלאות."],[3,"דבר אחר וירא וגו':","פירוש אחר, על וירא ישראל את היד הגדולה וגו'. מקרא זה אין ראשו קשור לסופו ואין סופו קשור לראשו, שמתחילה כתוב וירא ישראל את היד הגדולה ואח\"כ וייראו העם את ה'. וכי וירא ישראל הוא סיבה אל וייראו העם את ה', ומלפני כן לא יראו את ה'. אלא אמר ר' יהודה, זקן ההוא שירד עם בניו לגלות, וסבל עליו הגלות, והכניס את בניו בגלות, הוא ממש ראה כל אלו הנקמות וכל הגבורות שעשה הקב\"ה במצרים. ז\"ש וירא \u0003ישראל\u0004, ישראל ממש, דהיינו יעקב."],[4,"ואמר ר' יהודה וכו':","ואר\"י, העלה הקב\"ה לאותו זקן, ואמר לו, קום ראה את בניך היוצאים מתוך עם חזק, קום ראה הגבורות שעשיתי בשביל בניך במצרים."],[5,"והיינו דאמר ר' ייסא וכו':","והיינו שאר\"י, בשעה שנסעו ישראל לרדת בגלות מצרים, יראה ואימה חזקה נפלה עליו, אמר לו הקב\"ה ליעקב, למה אתה מתירא, אל תירא מרדה מצרימה. ממה שכתוב, אל תירא, משמע שהיה מתירא."],[6,"אמר ליה כי לגוי גדול וגו':","אמר לו מתירא אני שיכלו את בני. אמר לו אנכי ארד עמך מצרימה. אמר לו שוב, מתירא אני שלא אזכה להקבר בין אבותי ולא אראה הגאולה של בני, והגבורות שתעשה להם. אמר לו, ואנכי אעלך גם עלה. \u0003אעלך,\u0004 להקבר בקבר אבותיך, \u0003גם עלה,\u0004 לראות הגאולה של בניך, והגבורות שאעשה להם."],[7,"וההוא יומא דנפקו וכו':","וביום ההוא שיצאו ישראל ממצרים, העלה הקדוש ב\"ה את יעקב ואמר לו, קום ראה בגאולה של בניך, שכמה כחות וגבורות עשיתי להם. ויעקב היה שם וראה הכל. ז\"ש, וירא \u0003ישראל\u0004 את היד הגדולה."],[8,"ר' יצחק אמר וכו':","רי\"א מכאן נשמע שיעקב היה בעת הגאולה, שכתוב, ויוציאך \u0003בפניו\u0004 בכחו הגדול ממצרים. מהו בפניו. בפניו זה יעקב. כי הביא כל האבות שמה. ר' חזקיה אמר, ויוציאך בפניו, \u0003בפניו\u0004 זה אברהם. שכתוב, ויפול אברהם על פניו."],[9,"תא חזי אברהם וכו':","בוא וראה, אברהם אמר, הלבן מאה שנה יולד. אמר לו הקב\"ה, חייך, אתה תראה כמה המונים וכמה מחנות שיצאו ממך. בשעה שיצאו ישראל ממצרים כל אלו השבטים וכל אלו הרבבות העלה הקב\"ה אל אברהם וראה אותם, ז\"ש ויוציאך בפניו. ר' אבא אמר כל האבות נזדמנו שם בכל גאולה ההיא. ז\"ש ויוציאך בפניו. מהו בפניו אלו האבות."],[10,"ר' אלעזר אמר וכו':","רא\"א, ויוציאך בפניו, זהו יעקב. בכחו, זהו יצחק. הגדול, זהו אברהם. אר\"ש וכן בשביל האבות מזדמן תמיד גאולה לישראל. שכתוב, וזכרתי את בריתי יעקב ואף את בריתי יצחק ואף את בריתי אברהם אזכור והארץ אזכור. שואל, האבות ראוים שיזכור, אבל מהו והארץ אזכור. ומשיב, אלא לכלול עמהם את דוד, דהיינו המלכות. שנקראת הארץ, שהיא מרכבה עם האבות, שהם חג\"ת. והם מעוררים תמיד גאולה לישראל."]],[[0,"","וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא מְעוֹרֵר דִּינָיו, הוּא דָּן אֶת דִּינָיו בַּכֶּתֶר הַזֶּה, וְאָז כָּתוּב תָּם וְרָשָׁע הוּא מְכַלֶּה. מִשּׁוּם שֶׁאוֹתָם הַצַּדִּיקִים נִתְפָּסִים בַּחֲטָאֵי הָרְשָׁעִים, שֶׁכָּתוּב וַיֹּאמֶר ה' לַמַּלְאָךְ הַמַּשְׁחִית בָּעָם רַב וְגוֹ'. וְעַל זֶה אָמַר (ר' יוסי) אִיּוֹב אֶת הַדָּבָר הַזֶּה, (אמר) וְלֹא פֵרַשׁ אֶת הַדָּבָר, וּפֵרְשׁוּהָ - טֹל הָרַב. רַבִּי יֵיסָא אָמַר, אַחַת הִיא - זוֹ כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּת מִצְרַיִם, שֶׁבִּשְׁבִילָה הָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם וְעָשָׂה בָהֶם נְקָמוֹת. זֶהוּ שֶׁכָּתוּב תָּם וְרָשָׁע הוּא מְכַלֶּה."],[1,"","רַבִּי חִיָּיא אָמַר, אִיּוֹב לֹא נִלְקָה, אֶלָּא בִּזְמַן שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם. אָמַר אִיּוֹב, אִם כָּךְ, כָּל הַפָּנִים שָׁוִים, תָּם וְרָשָׁע הוּא מְכַלֶּה. פַּרְעֹה הֶחֱזִיק בְּיִשְׂרָאֵל וְאָמַר (שמות ה) מִי ה' אֲשֶׁר אֶשְׁמַע בְּקֹלוֹ, וַאֲנִי לֹא הֶחֱזַקְתִּי בָהֶם וְלֹא עָשִׂיתִי דָבָר - תָּם וְרָשָׁע הוּא מְכַלֶּה?! זֶהוּ שֶׁכָּתוּב (שם ט) הַיָּרֵא אֶת דְּבַר ה' מֵעַבְדֵי פַּרְעֹה, זֶה אִיּוֹב."],[2,"","רַבִּי יְהוּדָה אָמַר, אוֹתָם אַבְנֵי בָרָד שֶׁהָיוּ יוֹרְדִים, הִתְעַכְּבוּ עַל יְדֵי מֹשֶׁה, וְאַחַר כָּךְ עָשׂוּ נְקָמוֹת בִּימוֹת יְהוֹשֻׁעַ, וְלֶעָתִיד לָבֹא עֲתִידִים לָרֶדֶת אוֹתָם שֶׁנִּשְׁאֲרוּ עַל אֱדוֹם וּבְנוֹתֶיהָ. אָמַר רַבִּי יוֹסֵי, זֶהוּ שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרָיִם אַרְאֶנּוּ נִפְלָאוֹת."],[3,"","דָּבָר אַחֵר וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ' - פָּסוּק זֶה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. בַּתְּחִלָּה וַיַּרְא יִשְׂרָאֵל, וְאַחַר כָּךְ וַיִּירְאוּ הָעָם אֶת ה'. אֶלָּא אָמַר רַבִּי יְהוּדָה, אוֹתוֹ זָקֵן שֶׁיָּרַד עִם בָּנָיו לַגָּלוּת וְסָבַל עָלָיו אֶת הַגָּלוּת וְהִכְנִיס אֶת בָּנָיו לַגָּלוּת, הוּא רָאָה מַמָּשׁ אֶת כָּל אוֹתָן נְקָמוֹת וּגְבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם. זֶהוּ שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל, יִשְׂרָאֵל מַמָּשׁ."],[4,"","וְאָמַר רַבִּי יְהוּדָה, הֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתוֹ זָקֵן וְאָמַר לוֹ, קוּם תִּרְאֶה אֶת בָּנֶיךְ יוֹצְאִים מִתּוֹךְ עַם חָזָק. קוּם תִּרְאֶה אֶת הַגְּבוּרוֹת שֶׁעָשִׂיתִי בִּשְׁבִיל בָּנֶיךְ בְּמִצְרַיִם."],[5,"","וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי יֵיסָא, בְּשָׁעָה שֶׁנָּסְעוּ יִשְׂרָאֵל לָרֶדֶת לְגָלוּת מִצְרַיִם, פַּחַד וְאֵימָה חֲזָקָה נָפְלוּ עָלָיו. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַעֲקֹב, לָמָּה אַתָּה פּוֹחֵד? (בראשית מו) אַל תִּירָא מֵרְדָה מִצְרַיְמָה. מִמַּה שֶּׁכָּתוּב אַל תִּירָא, מַשְׁמָע שֶׁפַּחַד הָיָה פּוֹחֵד."],[6,"","אָמַר לוֹ, כִּי לְגוֹי גָּדוֹל אֲשִׂימְךְ שָׁם. אָמַר לוֹ, אֲנִי פּוֹחֵד שֶׁיִּכְלוּ בָנַי. אָמַר לוֹ, אָנֹכִי אֵרֵד עִמְּךְ מִצְרַיְמָה. אָמַר לוֹ, עוֹד אֲנִי פּוֹחֵד - שֶׁלֹּא אֶזְכֶּה לְהִקָּבֵר בֵּין אֲבוֹתַי וְלֹא אֶרְאֶה אֶת גְּאֻלַּת בָּנַי וְהַגְּבוּרוֹת שֶׁתַּעֲשֶׂה לָהֶם. אָמַר לוֹ, וְאָנֹכִי אַעַלְךְ גַם עָלֹה. אַעַלְךְ - לְהִקָּבֵר בְּקִבְרֵי אֲבוֹתֶיךְ. גַם עָלֹה - לִרְאוֹת אֶת גְּאֻלַּת בָּנֶיךְ וְהַגְּבוּרוֹת שֶׁאֶעֱשֶׂה לָהֶם."],[7,"","וְאוֹתוֹ יוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, הֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יַעֲקֹב וְאָמַר לוֹ, קוּם תִּרְאֶה בִּגְאֻלַּת בָּנֶיךְ, שֶׁכַּמָּה חֲיָלוֹת וּגְבוּרוֹת עָשִׂיתִי לָהֶם. וְיַעֲקֹב הָיָה שָׁם וְרָאָה אֶת הַכֹּל. זֶהוּ שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדֹלָה."],[8,"","רַבִּי יִצְחָק אָמַר, מִכָּאן, (דברים ד) וַיּוֹצִאֲךְ בְּפָנָיו בְּכֹחוֹ הַגָּדֹל מִמִּצְרָיִם. מַה זֶּה בְּפָנָיו? בְּפָנָיו זֶה יַעֲקֹב, שֶׁהִכְנִיס לְשָׁם אֶת כֻּלָּם. רַבִּי חִזְקִיָּה אָמַר, וַיּוֹצִאֲךְ בְּפָנָיו - בְּפָנָיו זֶה אַבְרָהָם, שֶׁכָּתוּב (בראשית יז) וַיִּפֹּל אַבְרָהָם עַל פָּנָיו."],[9,"","בֹּא רְאֵה, אַבְרָהָם אָמַר, הַלְּבֶן מֵאָה שָׁנָה יִוָּלֵד וְגוֹ'. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, חַיֶּיךְ, אַתָּה תִּרְאֶה כַּמָּה אוּכְלוּסִים וְכַמָּה חֲיָלוֹת שֶׁיֵּצְאוּ מִמְּךְ. בְּשָׁעָה שֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, כָּל אוֹתָם שְׁבָטִים, כָּל אוֹתָם רְבָבוֹת, הֶעֱלָה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אַבְרָהָם וְרָאָה אוֹתָם. זֶהוּ שֶׁכָּתוּב וַיּוֹצִאֲךְ בְּפָנָיו. רַבִּי אַבָּא אָמַר, כָּל הָאָבוֹת הִזְדַּמְּנוּ לְשָׁם בְּכָל אוֹתָהּ הַגְּאֻלָּה. זֶהוּ שֶׁכָּתוּב וַיּוֹצִאֲךְ בְּפָנָיו. מַה זֶּה בְּפָנָיו? אֵלּוּ הָאָבוֹת."],[10,"","רַבִּי אֶלְעָזָר אָמַר, וַיּוֹצִאֲךְ בְּפָנָיו - זֶה יַעֲקֹב. בְּכֹחוֹ - זֶה יִצְחָק. הַגָּדֹל - זֶה אַבְרָהָם. אָמַר רַבִּי שִׁמְעוֹן, וְכֵן בִּשְׁבִיל הָאָבוֹת מִזְדַּמֶּנֶת תָּמִיד גְּאֻלָּה לְיִשְׂרָאֵל, שֶׁכָּתוּב (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְאַף אֶת בְּרִיתִי אַבְרָהָם אֶזְכֹּר וְהָאָרֶץ אֶזְכֹּר. הָאָבוֹת מֵילָא, אֲבָל מַה זֶּה וְהָאָרֶץ אֶזְכֹּר? אֶלָּא לְהַכְלִיל עִמָּם אֶת דָּוִד הַמֶּלֶךְ, שֶׁהוּא מֶרְכָּבָה עִם הָאָבוֹת, וְהֵם מְעוֹרְרִים תָּמִיד גְּאֻלָּה לְיִשְׂרָאֵל."]]],[["וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה אֲשֶׁר עָשָׂה יְיָ' בְּמִצְרַיִם. וְכִי הַשְׁתָּא עָשָׂה, וְהָא מִקַּדְמַת דְּנָא אִתְעָבִיד, מַאי אֶת הַיָּד הַגְּדוֹלָה אֲשֶׁר עָשָׂה יְיָ'. אֶלָּא, יַד לָא אִקְרֵי פָּחוּת מֵחָמֵשׁ אֶצְבְּעָאן. הַגְּדוֹלָה: דִּכְלִילָן בָּהּ חָמֵשׁ אֶצְבְּעָאן אַחֲרָנִין, וְאִתְקְרוּן כְּדֵין גְּדוֹלָה. וְכָל אֶצְבְּעָא וְאֶצְבְּעָא, סָלִיק לְחוּשְׁבָּנָא רַבָּא, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד בְּהוּ (ס\"א השתא ניסין) נִיסִּין וּגְבוּרָן, וּבְהַאי אִתְעַקְּרוּ כֻּלְּהוּ דַּרְגִּין מִשִּׁלְשׁוּלֵיהוֹן.","מִכָּאן אוֹלִיפְנָא דָּא, דִּבְחָמֵשׁ אֶצְבְּעָאן קָמָאי, כְּתִיב, וַיְחַזֵּק לֵב פַּרְעֹה, כֵּיוָן דְּאִשְׁתְּלָמוּ אִינּוּן חָמֵשׁ, תּוּ לָא הֲוָה מִלָּה בִּרְשׁוּתֵיהּ דְּפַרְעֹה, כְּדֵין כְּתִיב וַיְחַזֵּק יְיָ' אֶת לֵב פַּרְעֹה.","וְעַל דָּא וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדוֹלָה וְגוֹ', וַיַּאֲמִינוּ בַּיְיָ'. וְכִי עַד הַשְׁתָּא לָא הֶאֱמִינוּ בַּיְיָ', וְהָא כְּתִיב (שמות ד׳:ל״א) וַיַּאֲמֵן הָעָם וַיִּשְׁמְעוּ וְגוֹ'. וְהָא חָמוּ כָּל אִינּוּן גְּבוּרָאן דְּעָבַד לְהוּ קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם. אֶלָּא מַאי וַיַּאֲמִינוּ, הַהוּא מִלָּה דְּאָמַר וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ וְגוֹ'.","ר' יֵיסָא שָׁאִיל וְאָמַר, כְּתִיב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, וּכְתִיב לא תּוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם. אָמַר רִבִּי יוֹסֵי, מֵתִין חָמוּ לְהוּ. אָמַר לֵיהּ, אִי כְּתִיב לא תּוֹסִיפוּ לִרְאוֹתָם חַיִּים, הֲוָה אֲמֵינָא הָכִי. אָמַר לֵיהּ ר' אַבָּא יֵאוֹת שָׁאִילְתָּא.","אֶלָּא תָּא חֲזֵי, כְּתִיב (דברי הימים א ט״ז:ל״ו) מִן הָעוֹלָם וְעַד הָעוֹלָם, וְתָנֵינָן, עוֹלָם לְעֵילָּא, וְעוֹלָם לְתַתָּא. עוֹלָם דִּלְעֵילָּא, מִתַּמָּן הוּא שֵׁירוּתָא לְאַדְלְקָא בּוּצִינִין. עוֹלָם דִּלְתַתָּא, תַּמָּן הוּא סִיּוּמָא, וְאִתְכְּלִיל מִכֹּלָּא, וּמֵהַאי עוֹלָם דִּלְתַתָּא, מִתְעֲרָן גְּבוּרָן לְתַתָּאֵי.","וּבְהַאי עוֹלָם, עָבִיד קוּדְשָׁא בְּרִיךְ הוּא אָתִין לְיִשְׂרָאֵל, וְרָחִישׁ לוֹן נִיסָא. וְכַד אִתְּעַר הַאי עוֹלָם לְמֶעְבַּד נִסִּין, כֻּלְּהוּ מִצְרָאֵי אִשְׁתְּקָעוּ בְּיַמָּא, עַל יְדָא דְּהַאי עוֹלָם, וְאִתְרְחִישׁ לוֹן לְיִשְׂרָאֵל נִיסָא בְּהַאי עוֹלָם. וְעַל דָּא כְּתִיב, לֹא תּוֹסִיפוּ לִרְאוֹתָם עוֹד עַד עוֹלָם, עַד דְּיִתְּעַר הַהוּא עוֹלָם, וְיִתְמַסְּרוּן בְּדִינוֹי, וְכֵיוָן דְּאִתְמְסָרוּ בֵּיהּ לְמִתְּדָן, כְּדֵין כְּתִיב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם, הֲדָא הוּא דִכְתִיב מִן הָעוֹלָם וְעַד הָעוֹלָם, עַד הָעוֹלָם דַּיְקָא. כְּדֵין כְּתִיב, וַיַּאֲמִינוּ בַּיְיָ' וּבְמֹשֶׁה עַבְדּוֹ.","(שמות ט״ו:א׳) אָז יָשִׁיר מֹשֶׁה. ר' יְהוּדָה פָּתַח, (ירמיהו א׳:ה׳) בְּטֶרֶם אֶצָּרְךָ בַבֶּטֶן יְדַעְתִּיךָ וְגוֹ'. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ יַתִּיר מִכָּל שְׁאַר עַמִּין. וּמִסְּגִיאוּת רְחִימוּתָא דְּרָחִים לְהוּ, אוֹקִים עָלַיְיהוּ נְבִיאָה דִּקְשׁוֹט, וְרַעְיָא מְהֵימָנָא. וְאִתְּעַר עָלֵיהּ רוּחָא קַדִּישָׁא, יַתִּיר מִכָּל שְׁאַר נְבִיאֵי מְהֵימְנֵי, וְאַפִּיק לֵיהּ מֵחוּלָקֵיהּ מַמָּשׁ, מִמַּה דְּאַפְרִישׁ יַעֲקֹב מִבְּנוֹי לְקוּדְשָׁא בְּרִיךְ הוּא, שִׁבְטָא דְּלֵוִי, וְכֵיוָן דְּהֲוָה לֵוִי דִּילֵיהּ, נָטַל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַעְטַר לֵיהּ בְּכַמָּה עִטְרִין, וּמָשַׁח לֵיהּ בִּמְשַׁח רְבוּת קַדִּישָׁא דִּלְעֵילָּא, וּכְדֵין אַפִּיק מִבְּנוֹי, רוּחָא קַדִּישָׁא לְעָלְמָא, וְזָרִיז לֵיהּ בְּהֵימְנוֹיֵי קַדִּישֵׁי, מְהֵימָנוּתָא רַבָּא.","תָּנָא, בְּהַהִיא שַׁעֲתָא דְּמָטָא זִמְנֵיהּ דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא לְאַחֲתָא לְעָלְמָא, אַפִּיק קוּדְשָׁא בְּרִיךְ הוּא רוּחָא קַדִּישָׁא מִגִּזְרָא דִּסַפִּירוּ דְּאֶבֶן טָבָא, דְּהֲוָה גָּנִיז בְּמָאתַן וְאַרְבְּעִין וּתְמַנְיָא (נהורין, ואתנהיר עליה. ואעטריה בשס\"ה) עִטְּרִין, קַיְימֵי קָמֵיהּ, וְאַפְקִיד לֵיהּ בְּכָל דִּילֵיהּ. (נ\"א ביתיה) וְיָהַב לֵיהּ מֵאָה וְשִׁבְעִין וּתְלַת מַפְתְּחִין. (נ\"א גניז תמן ואעטריה בתלת מאה ושתין וחמש עטרי ואנהיר עליה מאתן וארבעין ותמניא נהורין וקאים קמיה ואפקיד ליה בכל ביתא דיליה ויהב ליה מאה ושבעין ותלת מפתחן. (נ\"א מאתן ושבעין וחמש)) וְאַעְטַר לֵיהּ בְּחָמֵשׁ עִטְרִין, וְכָל עִטְרָא וְעִטְרָא סָלִיק וְאַנְהִיר בְּאֶלֶף עָלְמִין דְּנַהֲרִין, וּבוּצִינִין דּגְנִיזִין בְּגִנְזַיָּיא דְּמַלְכָּא קַדִּישָׁא עִלָּאָה.","כְּדֵין אַעְבְּרֵיהּ בְּכָל בּוּצִינִין (נ\"א בוסמין) דִּבְגִּנְתָּא דְּעֵדֶן, וְאַעֲלֵיהּ בְּהֵיכָלֵיהּ, וְאַעְבְּרֵיהּ בְּכָל חַיָּילִין וְגַיָּיסִין דִּילֵיהּ. כְּדֵין אִזְדַּעְזְעוּ כֻּלְּהוּ, פָּתְחוּ וְאָמְרוּ, אִסְתָּלָקוּ מִסַּחֲרָנֵיהּ, (סטרא דסטרין) דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר רוּחָא לְשַׁלְּטָאָה לְמִרְגַּז עָלְמִין. קָלָא נָפַק וְאָמַר, מַאן הוּא דֵּין, דְּכָל מַפְתְּחָן אִלֵּין בִּידוֹי. פָּתַח קָלָא אַחֲרָא וְאָמַר, קַבִּילוּ לֵיהּ בְּגַוַּויְיכוּ, דָּא הוּא דְּזַמִּין לְנַחְתָּא בֵּין בְּנִי נָשָׁא, וּזְמִינָא אוֹרַיְיתָא, גְּנִיזָא דְּגִנְזַיָּיא, לְאִתְמַסְּרָא בִּידוֹי, וּלְאַרְעֲשָׁא עָלְמִין דִּלְעֵילָּא וְתַתָּא עַל יְדָא דְּדֵין. בֵּיהּ שַׁעֲתָא אִתְרְגִישׁו כֻּלְּהוּ, וְנַטְלִין אֲבַתְרֵיהּ, פָּתְחוּ וְאָמְרוּ, (תהילים ס״ו:י״ב) הִרְכַּבְתָּ אֱנוֹשׁ לְרֹאשֵׁנוּ בָּאנוּ בָּאֵשׁ וּבַמַּיִם."],[[0,"וירא וגו' אשר עשה ה' במצרים:","שואל. וכי עתה עשה, והרי מקודם לכן נעשה, מהו את היד הגדולה אשר \u0003עשה\u0004 ה'. ומשיב. אלא \u0003יד\u0004 אינו נקרא פחות מחמשה אצבעות. \u0003הגדולה,\u0004 היינו שכלולות בה חמש אצבעות אחרות מיד השמאל. ואז נקרא גדולה. כי בחינת ג\"ר נוטלת יד ימין מהתכללות בקו שמאל. וכל אצבע ואצבע עולה לחשבון גדול, והקב\"ה עושה בהם ניסים וגבורות. ובזה נעקרו כל המדרגות מהשתלשלותם."],[1,"מכאן אוליפנא דא וכו':","מכאן למדנו. שבחמש אצבעות הראשונות, דהיינו ה' מכות הראשונות כתוב, ויחזק לב פרעה. כיון שנשלמו אלו חמש אצבעות, דיד שמאל, לא היה עוד דבר ברשות פרעה שיחזק לבו, אז כתוב, ויחזק הויה את לב פרעה."],[2,"וע\"ד וירא ישראל וגו':","ועל כן, וירא ישראל את היד הגדולה וגו' ויאמינו בה'. שואל, וכי עד עתה לא האמינו בה', והרי כתוב, ויאמן העם וישמעו, והרי ראו כל הגבורות שעשה להם הקב\"ה במצרים. ומשיב. אלא מהו ויאמינו, שהאמינו בדבר ההוא שאמר, ויאמר משה אל העם אל תיראו התיצבו וראו את ישועת ה'."],[3,"ר' ייסא שאיל וכו':","ר' ייסא שאל ואמר, כתוב, וירא ישראל את מצרים מת, וכתוב, לא תוסיפו לראותם עוד עד עולם. אמר ר' יוסי מתים ראו אותם. אמר לו, אם היה כתוב, לא תוסיפו לראותם חיים, הייתי אומר כך. אמר לו ר' אבא, יפה שאלת."],[4,"אלא תא חזי וכו':","אלא בוא וראה. כתוב, מן העולם ועד העולם. ולמדנו, עולם למעלה עולם למטה, עולם שלמעלה, משם הוא ההתחלה להדליק הנרות, שהיא הבינה שהיא שורש כל המוחין, המכונים נרות. עולם שלמטה, שם הוא הסיום, דהיינו המלכות המסיימת כל הספירות, והוא נכלל מכולם, ומעולם שלמטה הזה, מתעוררות הגבורות לתחתונים."],[5,"ובהאי עולם עביד וכו':","ובעולם הזה שלמטה, עושה הקב\"ה אותות לישראל, ויקרו להם נסים. וכשמתעורר עולם הזה לעשות נסים, כל המצרים צללו בים על ידי עולם הזה, וקרה לישראל נס בעולם הזה. וע\"כ כתוב, לא תוסיפו לראותם עוד עד \u0003עולם,\u0004 דהיינו עד שיתעורר עולם ההוא ויהיו נמסרים בדיניו, וכיון שנמסרו לו להיות נדונים, אז כתוב, וירא ישראל את מצרים מת על שפת הים. ז\"ש, מן העולם ועד העולם. עד העולם בדיוק, דהיינו עד שיתעורר העולם שלמטה. אז כתוב, ויאמינו בה' ובמשה עבדו."],[6,"אז ישיר משה:","ר' יהודה פתח, בטרם אצרך בבטן ידעתיך וגו'. אשרי חלקם של ישראל, שהקב\"ה רצה בהם יותר מבכל שאר העמים, ומרוב האהבה שאהב אותם הקים להם נביא אמת ורועה נאמן, והעיר עליו רוח הקודש יותר מכל שאר נביאים הנאמנים והוציאו מחלקו ממש, דהיינו ממה שהפריש יעקב מעשר מבניו להקב\"ה, שהוא שבט לוי, וכיון שהיה לוי שלו, לקחו הקב\"ה ועטר אותו בכמה עטרות, ומשח אותו בשמן המשחה הקדוש שלמעלה, ואז הוציא מבניו רוח קדוש אל העולם וחגר אותו באבנטיו הקדושים של האמונה הגדולה, שהיא בינה."],[7,"תנא בההיא שעתא וכו':","למדנו, בשעה ההיא שהגיע זמנו של משה הנביא הנאמן לרדת לעולם, הוציא הקב\"ה רוח קדוש ממחצבת של ספיר האבן הטוב, שהיא המלכות, שהיה גנוז ברמ\"ח אורות והאיר עליו. ועטר אותו בשס\"ה עטרות ועמדו לפניו, והפקיד אותו על כל אשר לו. ונתן לו מאה ושבעים ושלשה מפתחות. ועטר לו בחמש עטרות, וכל עטרה ועטרה עולה ומאירה באלף עולמות המאירים ונרות הגנוזים באוצרות מלך הקדוש העליון."],[7,"","ביאור הדברים. שהזהר הולך ומבאר המוחין, שזכה בהם משה מטרם שירד לארץ. ונודע שסדר המוחין הוא בדרך כלל, הוא שמתחילה מקבל ו\"ק בלי ראש, שה\"ס חסדים חסרי ג\"ר. ואח\"כ מקבל ג\"ר בבחינת נשמה. ואח\"כ בבחינת חיה. ואח\"כ בבחינת יחידה. גם נודע שרמ\"ח הוא בחי' ו\"ק ושס\"ה הוא בחי' ג\"ר. (כמ\"ש ב\"א דף קע\"ה ד\"ה ביאור)."],[7,"","וז\"ש, \u0003אפיק קב\"ה רוחא קדישא וכו': דהוה גניז ברמ\"ח נהורין,\u0004 שבזה השיג משה מוחין דו\"ק. \u0003ואעטריה בשס\"ה עטרין\u0004 היינו מוחין דג\"ר. \u0003ויהב ליה מאה ושבעין ותלת מפתחין,\u0004 היינו האורות דקו האמצעי המכונים מפתחות, מטעם שאין הקוים ימין ושמאל יכולים להאיר עד שבא קו האמצעי ופותח אותם, ואז מקבל קו האמצעי כל שיעור האורות שגרם לצאת בב' קוים העליונים (כנ\"ל ב\"א אות שס\"ג) ומקו ימין הוא מקבל מאה אורות, דהיינו כל הע\"ס שלו. מטעם היותם אור החסדים. ומקו השמאל, ששם אור החכמה אינו מקבל רק ע' עטרות לבד ולא הג\"ר דחכמה, וע\"כ חסר שלשים. אמנם יש לו התכללות מג\"ר, ונחשבים רק למספר ג' לבד, וע\"כ הם \u0003מאה ושבעים ותלת מפתחן.\u0004 ואח\"כ מבאר מוחין דחיה. וז\"ש, \u0003ואעטר ליה בחמש עטרין,\u0004 שהם חג\"ת נ\"ה, \u0003וכל עטרא ועטרא סליק ואנהיר באלף עלמין,\u0004 שהם ספירות דאו\"א שכל ספירה וספירה עולה במספר אלף. ואח\"כ מבאר מוחין דיחידה, וז\"ש \u0003ובוצינין דגניזין בגנזייא דמלכא קדישא עלאה,\u0004 דהיינו שהם נעלמים ומלובשים באבא עלאה, שנקרא, מלך העליון הקדוש. והיינו, האורות דא\"א, שה\"ס יחידה."],[8,"כדין אעבריה בכל וכו':","אז העבירו בכל האורות שבגן עדן, והכניסו להיכלו והעבירו בכל הצבאות והמחנות שלו. אז נזדעזעו כולם, פתחו ואמרו, הסתלקו מסביבתו, כי הקב\"ה העיר רוח לשלוט להרגיז העולמות. יצא קול ואמר, מי הוא זה שכל מפתחות הללו בידיו. פתח קול אחר ואמר, קבלו אותו בתוככם, זהו שעתיד לרדת בין בני אדם ועתידה התורה, הגנוזה מכל גנוז, להתמסר בידיו, ולהרעיש העולמות שלמעלה ושלמטה על ידי זה. בה בשעה התרגשו כולם ונסעו אחריו. פתחו ואמרו, הרכבת אנוש לראשנו באנו באש ובמים."]],[[0,"","וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה אֲשֶׁר עָשָׂה ה' בְּמִצְרַיִם. וְכִי עַכְשָׁו עָשָׂה, וַהֲרֵי מִקֹּדֶם לָכֵן זֶה נַעֲשָׂה? מַה זֶּה אֶת הַיָּד הַגְּדֹלָה אֲשֶׁר עָשָׂה ה'? אֶלָּא יָד לֹא נִקְרֵאת פָּחוֹת מֵחָמֵשׁ אֶצְבָּעוֹת. הַגְּדלָה - שֶׁכְּלוּלִים בָּהּ חָמֵשׁ אֶצְבָּעוֹת אֲחֵרוֹת, וְאָז נִקְרָאִים גְּדוֹלָה. וְכָל אֶצְבַּע וְאֶצְבַּע עוֹלָה לְחֶשְׁבּוֹן גָּדוֹל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה בָהֶם (כעת נסים) נִסִּים וּגְבוּרוֹת, וּבָזֶה נֶעֶקְרוּ כָּל הַדְּרָגוֹת מֵהִשְׁתַּלְשְׁלוּתָם."],[1,"","מִכָּאן לָמַדְנוּ זֶה, שֶׁבַּחֲמֵשׁ הָאֶצְבָּעוֹת הָרִאשׁוֹנוֹת כָּתוּב וַיֶּחֱזַק לֵב פַּרְעֹה. כֵּיוָן שֶׁנִּשְׁלְמוּ אוֹתָן חָמֵשׁ, שׁוּב לֹא הָיָה דָּבָר בִּרְשׁוּת פַּרְעֹה, וְאָז כָּתוּב וַיְחַזֵּק ה' אֶת לֵב פַּרְעֹה."],[2,"","וְעַל זֶה וַיַּרְא יִשְׂרָאֵל אֶת הַיָּד הַגְּדלָה וְגוֹ', וַיַּאֲמִינוּ בַּה'. וְכִי עַד עַכְשָׁו לֹא הֶאֱמִינוּ בַּה', וַהֲרֵי כָּתוּב (שמות ד) וַיַּאֲמֵן הָעָם וַיִּשְׁמְעוּ וְגוֹ'? וַהֲרֵי רָאוּ כָּל אוֹתָם גְּבוּרוֹת שֶׁעָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם. אֶלָּא מַה זֶּה וַיַּאֲמִינוּ? אוֹתוֹ הַדָּבָר שֶׁאָמַר, וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ הִתְיַצְּבוּ וּרְאוּ וְגוֹ'."],[3,"","רַבִּי יֵיסָא שָׁאַל וְאָמַר, כָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, וְכָתוּב לֹא תֹסִפוּ לִרְאֹתָם עוֹד עַד עוֹלָם. אָמַר רַבִּי יוֹסֵי, רָאוּ אוֹתָם מֵתִים. אָמַר לוֹ, אִם כָּתוּב לֹא תוֹסִיפוּ לִרְאוֹתָם חַיִּים - הָיִיתִי אוֹמֵר כָּךְ. אָמַר לוֹ רַבִּי אַבָּא, יָפֶה שָׁאַלְתָּ."],[4,"","אֶלָּא בּא רְאֵה, כָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם, וְשָׁנִינוּ - עוֹלָם לְמַעְלָה וְעוֹלָם לְמַטָּה. עוֹלָם שֶׁלְּמַעְלָה - מִשָּׁם הִיא הָרֵאשִׁית לְהַדְלִיק מְנוֹרוֹת. הָעוֹלָם שֶׁלְּמַטָּה - שָׁם הַסִּיּוּם, וְנִכְלָל מֵהַכֹּל. וּמֵעוֹלָם הַזֶּה שֶׁלְּמַטָּה מִתְעוֹרְרוֹת גְּבוּרוֹת לַתַּחְתּוֹנִים."],[5,"","וּבְעוֹלָם זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹת לְיִשְׂרָאֵל וְהִרְחִישׁ לָהֶם נִסִּים, וּכְשֶׁהִתְעוֹרֵר עוֹלָם זֶה לַעֲשׂוֹת לָהֶם נִסִּים, כָּל הַמִּצְרִים נִשְׁקְעוּ בַיָּם עַל יְדֵי עוֹלָם זֶה, וְהִתְרַחֵשׁ לָהֶם לְיִשְׂרָאֵל נִסִּים בְּעוֹלָם זֶה. וְעַל זֶה כָּתוּב לֹא תֹסִפוּ לִרְאֹתָם עוֹד עַד עוֹלָם, עַד שֶׁיִּתְעוֹרֵר אוֹתוֹ עוֹלָם וְיִמָּסְרוּ לְדִינָיו. וְכֵיוָן שֶׁנִּמְסְרוּ לוֹ לִדּוֹן, אָז כָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת עַל שְׂפַת הַיָּם. זֶהוּ שֶׁכָּתוּב מִן הָעוֹלָם וְעַד הָעוֹלָם. עַד הָעוֹלָם דַּוְקָא. וְאָז כָּתוּב וַיַּאֲמִינוּ בַּה' וּבְמֹשֶׁה עַבְדּוֹ."],[6,"","אָז יָשִׁיר מֹשֶׁה. רַבִּי יְהוּדָה פָּתַח, (ירמיה א) בְּטֶרֶם אֶצָּרְךְ בַבֶּטֶן יְדַעְתִּיךְ וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם יוֹתֵר מִכָּל שְׁאָר הָעַמִּים, וּמֵרֹב הָאַהֲבָה שֶׁהוּא אוֹהֵב אוֹתָם, הֵקִים עֲלֵיהֶם נְבִיא אֱמֶת וְרוֹעֶה נֶאֱמָן, וְעוֹרֵר עָלָיו רוּחַ הַקֹּדֶשׁ יוֹתֵר מִכָּל שְׁאָר הַנְּבִיאִים הַנֶּאֱמָנִים. וְהוֹצִיאוֹ מֵחֶלְקוֹ מַמָּשׁ מִמַּה שֶּׁהִפְרִישׁ יַעֲקֹב מִבָּנָיו לְהַקָּדוֹשׁ בָּרוּךְ הוּא - שֵׁבֶט לֵוִי. וְכֵיוָן שֶׁהָיָה לֵוִי שֶׁלּוֹ, לָקַח אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְעִטֵּר אוֹתוֹ בְּכַמָּה עֲטָרוֹת, וּמָשַׁח אוֹתוֹ בְּשֶׁמֶן מִשְׁחַת קֹדֶשׁ הָעֶלְיוֹן, וְאָז הוֹצִיא מִבָּנָיו רוּחַ קֹדֶשׁ לַעוֹלָם, וְזֵרַז אוֹתוֹ בְּאַבְנֵטָיו הַקְּדוֹשִׁים, הָאֱמוּנָה הַגְּדוֹלָה."],[7,"","לָמַדְנוּ, בְּאוֹתָהּ הַשָּׁעָה שֶׁהִגִּיעַ זְמַנּוֹ שֶׁל מֹשֶׁה הַנָּבִיא הַנֶּאֱמָן לָרֶדֶת לָעוֹלָם, הוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ קֹדֶשׁ מִמַּחְצַב הַסַּפִּיר שֶׁל אֶבֶן טוֹבָה, שֶׁהָיָה גָּנוּז בְּמָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה (אורות, והאיר עליו. ועטרו בשס\"ה) עֲטָרוֹת שֶׁעוֹמְדוֹת לְפָנָיו, וְהִפְקִיד אוֹתוֹ עַל כָּל אֲשֶׁר לוֹ, וְנָתַן לוֹ מֵאָה וְשִׁבְעִים וּשְׁלֹשָׁה מַפְתְּחוֹת. (גנוז שם, ועטר אותו בשלש מאות וששים וחמש עטרות, והאיר עליו מאתים ארבעים ושמונה אורות, והעמיד לפניו, והפקיד אותו בכל ביתו, ונתן לו מאה ושבעים ושלשה מפתחות. נ\"א מאתים ושבעים וחמשה) וְעִטְּרוֹ בְּחָמֵשׁ עֲטָרוֹת, וְכָל עֲטָרָה וַעֲטָרָה עוֹלָה וּמְאִירָה בְּאֶלֶף עוֹלָמוֹת שֶׁמְּאִירִים, וּמְנוֹרוֹת שֶׁגְּנוּזִים בְּגִנְזֵי הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן."],[8,"","וְאָז הֶעֱבִיר אוֹתוֹ בְּכָל הַמְּנוֹרוֹת (הבשמים) שֶׁבְּגַן עֵדֶן, וְהִכְנִיסוֹ לְהֵיכָלוֹ, וְהֶעֱבִירוֹ בְּכָל חֵילוֹתָיו וְגֵיסוֹתָיו. אָז כֻּלָּם הִזְדַּעְזְעוּ, פָּתְחוּ וְאָמְרוּ: הִסְתַּלְּקוּ מִסְּבִיבוֹ (צד הצדדים), שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵר רוּחַ לִשְׁלֹט לְהַרְגִּיז עוֹלָמוֹת. יָצָא קוֹל וְאָמַר: מִי הוּא זֶה שֶׁכָּל הַמַּפְתְּחוֹת הַלָּלוּ בְּיָדוֹ? פָּתַח קוֹל אַחֵר וְאָמַר: קַבְּלוּ אוֹתוֹ בְּתוֹכֲכֶם! זֶהוּ שֶׁעָתִיד לָרֶדֶת בֵּין בְּנֵי אָדָם, וַעֲתִידָה תוֹרָה, גְּנִיזַת הַגְּנִיזוֹת, לְהִמָּסֵר בְּיָדוֹ, וּלְהַרְעִישׁ עוֹלָמוֹת שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה עַל יָדוֹ שֶׁל זֶה. בְּאוֹתָהּ שָׁעָה כֻּלָּם הִתְרַגְּשׁוּ וְנָסְעוּ אַחֲרָיו. פָּתְחוּ וְאָמְרוּ, (תהלים סו) הִרְכַּבְתָּ אֱנוֹשׁ לְרֹאשֵׁנוּ בָּאנוּ בָּאֵשׁ וּבַמַּיִם."]]],[["כְּדֵין סַלְּקָא הַהוּא רוּחָא, וְקַיְּימָא קָמֵי מַלְכָּא. מ פְּתִיחָא, סָלִיק וְאִתְעַטָּר בְּעִטְּרוֹי, וְאַעְטְרֵיהּ בִּתְלַת מְאָה וְעֶשְׂרִין וְחָמֵשׁ עִטְּרִין, וְאַפְקִיד מַפְתְּחוֹי בִּידוֹי. ש דַּאֲבָהָתָא, אַעְטְרוּ לֵיהּ בִּתְלַת עִטְּרִין קַדִּישִׁין, וְאַפְקִידוּ כָּל מַפְתְּחָן דְּמַלְכָּא בִּידֵיהּ, וְאַפְקִידוּ לֵיהּ בְּהֵימְנוּתָא, מְהֵימָנָא דְּבֵיתָא. ה סַלְּקָא וְאִתְעַטְּרָא בְּעִטְּרוֹי, וְקַבִּילַת לֵיהּ מִן מַלְכָּא.","כְּדֵין, נָחַת הַהוּא רוּחָא בְּאַרְבִּין דְּשָׁאטָן, בְּהַהוּא יַמָּא רַבָּא, וְקַבִּילַת לֵיהּ לְגַדְּלָא לֵיהּ לְמַלְכָּא, וְהִיא יָהָבַת לֵיהּ מִתַּמָּן זִיּוּנִין, לְאַלְקָאָה לְפַרְעֹה וּלְכָל אַרְעֵיהּ. וּבְשַׁבְּתָא וּבְרֵישֵׁי יַרְחֵי, סַלְקַת לֵיהּ לְמַלְכָּא, כְּדֵין אִקְרֵי שְׁמֵיהּ, בְּאִלֵּין אַתְוָון רְשִׁימִין.","וּבְהַהִיא שַׁעֲתָא, דְּנָפַק לְנַחְתָּא לְאַרְעָא, בְזַרְעָא דְּלֵוִי, אִתְתָּקָנוּ אַרְבַּע מְאָה וְעֶשְׂרִין וְחָמֵשׁ בּוּצִינִין לְמַלְכָּא, וְאַרְבַּע מְאָה וְעֶשְׂרִין וְחָמֵשׁ גְּלִיפִין מְמָנָן, אוֹזְפוּהָ לְהַהוּא רוּחָא לְאַתְרֵיהּ, כַּד נָפַק לְעָלְמָא, אִתְנַהֲרָא בְּאַנְפּוֹי, וּבֵיתָא אִתְמַלְיָיא מִזִּיוְתֵיהּ. בֵּיהּ שַׁעֲתָא, קָרָא עָלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּטֶרְם אֶצָּרְךָ בַבֶּטֶן יְדַעְתִּיךָ וּבְטֶרֶם תֵּצֵא מֵרֶחֶם הִקְדַּשְׁתִּיךָ נָבִיא לַגּוֹיִם נְתַתִּיךָ.","רִבִּי יִצְחָק אָמַר, בֵּיהּ שַׁעֲתָא קָטַל (נ\"א אפיל) קוּדְשָׁא בְּרִיךְ הוּא לְרַבְרְבָא מְמָנָא דְּמִצְרָאֵי, וְחָמוּ לֵיהּ מֹשֶׁה וּבְנִי יִשְׂרָאֵל, כְּדֵין אָמְרוּ שִׁירָה. הֲדָא הוּא דִכְתִיב, וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל.","(שמות ט״ו:א׳) אָז יָשִׁיר מֹשֶׁה וּבְנִי יִשְׂרָאֵל וְגוֹ'. רִבִּי אַבָּא פָּתַח וְאָמַר, אִסְתַּכַּלְנָא בְּכָל תּוּשְׁבְּחָן דְּשַׁבְּחוּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְכוּלָּם פָּתְחוּ בְּאָז. (מלכים א ח׳:י״ב) אָז אָמַר שְׁלֹמֹה. (יהושע י׳:י״ב) אָז יְדַבֵּר יְהוֹשֻׁעַ, (במדבר כ״א:י״ז) אָז יָשִׁיר יִשְׂרָאֵל. מַאי טַעְמָא.","אֶלָּא הָכִי תָּאנָא, כָּל נִסִּין וְכָל גְּבוּרָן דְּאִתְעָבֵידוּ לְהוּ לְיִשְׂרָאֵל, כַּד אִתְנְהִיר נְהִירוּ דְּעַתִּיקָא קַדִּישָׁא בְּעִטְּרוֹי, גְּלִיפִין רְשִׁימִין בְּאָז, בא', וא', בד, אַנְקִיב בַּחֲשׁוֹכֵי, וְנָהִיר לְכָל עִיבָר. וְכַד אִתְחַבָּר נְהִירוּ דְּאָלֶ\"ף וּמָטֵי לְזַיִי\"ן, מַאן זַיִי\"ן, דָּא (ישעיה לה) חֶרֶב לַיְיָ' מָלְאָה דָּם. כְּדֵין עָבִיד נִסִּין וּגְבוּרָאן, בְּגִין דְּאִתְחֲבָּר א' עִם ז'. וְדָא הוּא שִׁירָתָא. שִׁירָתָא הִיא דְּכָל סִטְרִין, וְדָא הוּא אָז יָשִׁיר.","יָשִׁיר, שַׂר מִבָּעֵי לֵיהּ. אֶלָּא מִלָּה דָּא תַּלְיָא, וְאַשְׁלִים לְהַהוּא זִמְנָא, וְאַשְׁלִים לְזִמְנָא דְּאָתֵי, דִּזְמִינִין יִשְׂרָאֵל לְשַׁבְּחָא שִׁירָתָא דָּא מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, מִכָּאן אוֹלִיפְנָא, דְּצַדִּיקַיָּיא קַדְמָאֵי, אַף עַל גַּב דְּאִסְתָּלָקוּ בְּדַרְגִּין עִלָּאִין דִּלְעֵילָּא, וְאִתְקַשָּׁרוּ בְּקִשּׁוּרָא דִּצְרוֹרָא דְּחַיֵּי, זְמִינִין כֻּלְּהוּ לְאַחֲיָיא בְּגוּפָא, וּלְמֶחמֵי אַתְיָין וּגְבוּרָן דְּקָא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל. וּלְמֵימָר שִׁירָתָא דָּא, הֲדָא הוּא דִכְתִיב אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל.","ר' שִׁמְעוֹן אָמַר מֵהָכָא, (ישעיהו י״א:י״א) יוֹסִיף יְיָ' שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאַר עַמּוֹ. לִקְנוֹת: כְּמָה דְאַתְּ אָמֵר, (משלי ח׳:כ״ב) יְיָ' קָנָנִי רֵאשִׁית דַּרְכּוֹ. אֶת שְׁאַר עַמּוֹ: אִלֵּין אִינּוּן צַדִּיקַיָּיא דִּבְּהוֹן, דְּאִקְרוּן שְׁאַר, כְּמָה דְאַתְּ אָמֵר (במדבר י״א:כ״ו) וַיִּשָּׁאֲרוּ שְׁנֵי אֲנָשִׁים בְּמַּחֲנֶה. וְתָנֵינָן, לֵית עָלְמָא מִתְקַיְּימָא אֶלָּא עַל אִינּוּן דְּעַבְדֵי גַּרְמַיְיהוּ שִׁירַיִים.","וְאִי תֵּימָא, הוֹאִיל וְאִתְקַשָּׁרוּ בִּצְרוֹרָא דְּחַיֵּי, וּמִתְעַנְּגֵי בְּעִנּוּגָא עִלָּאָה, אֲמַאי יָחִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְאַרְעָא. פּוּק וְאוֹלִיף מִזִּמְנָא קַדְמָאָה, דְּכָל אִינּוּן רוּחִין וְנִשְׁמָתִין, דַּהֲווֹ בְּדַרְגָּא עִלָּאָה דִּלְעֵילָּא וְקוּדְשָׁא בְּרִיךְ הוּא אָחִית לְהוּ לְאַרְעָא לְתַתָּא. כָּל שֶׁכֵּן הַשְׁתָּא, דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא לְיַשְּׁרָא לַעֲקִימָא, כְּמָה דְאַתְּ אָמֵר (קהלת ז׳:כ׳) כִּי אָדָם אֵין צַדִּיק בָּאָרֶץ אֲשֶׁר יַעֲשֶׂה טוֹב וְלא יֶחטָא. וְאִי תֵּימָא, אִינּוּן דְּמִיתוּ בְּעֶטְיוֹ דְּנָחָשׁ. אֲפִילוּ אִינּוּן יְקוּמוּן, וִיהוֹן מָארֵי דְּעֵיטָא, לְמַלְכָּא מְשִׁיחָא.","וְעַל דָּא תָּנֵינָן, מֹשֶׁה זַמִּין לְמֵימָר שִׁירָתָא לְזִמְנָא דְּאָתֵי. מַאי טַעְמָא. בְּגִין דִּכְתִּיב, (מיכה ז׳:ט״ו) כִּימֵי צֵאתְךָ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת. אַרְאֶנּוּ, אַרְאֶךָ מִבָּעֵי לֵיהּ. אֶלָּא אַרְאֶנּוּ מַמָּשׁ, לְמַאן דְּחָמָא בְּקַדְמִיתָא, יֶחמֵי לֵיהּ תִּנְיָינוּת, וְדָא הוּא אַרְאֶנּוּ, וּכְתִיב (תהילים נ׳:כ״ג) אַרְאֶנּוּ בְּיֵשַׁע אֱלהִים, וְאַרְאֵהוּ בִּישׁוּעָתִי. וּכְדֵין אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַזֹּאת לַיְיָ'."],[[0,"כדין סלקא ההוא וכו':","אז עלה רוח ההוא דמשה, ועמד לפני המלך. \u0003מ'\u0004 פתוחה עלתה והתעטרה בעטרותיה, ועטר אותו, את הרוח, בשכ\"ה עטרות, והפקיד מפתחותיו בידיו. \u0003ש'\u0004 הרומזת לג' אבות, העטירו אותו בג' עטרות קדושות, והפקידו כל מפתחות המלך בידיו, ומינו אותו בנאמנות, להיות נאמן הבית. \u0003ה'\u0004 עלתה והתעטרה בעטרותיה, וקבלה אותו מן המלך."],[0,"","פירוש. נודע סוד כרסיא עלאה שמחזה ולמעלה דז\"א, שחג\"ת דז\"א הם ג' רגלי הכסא. והמלכות אשר שם, ה\"ס רגל רביעי. והכסא עצמו ה\"ס בינה. וז\"ס ג' אותיות \u0003מ' ש' ה',\u0004 אשר \u0003מ'\u0004, ה\"ס הכסא עצמו. \u0003ש'\u0004, ה\"ס ג' רגלי הכסא חג\"ת. \u0003ה'\u0004 ה\"ס המלכות, רגל רביעי. ומשה היה מרכבה לקו האמצעי, שה\"ס ז\"א. וז\"ס משה זכה לבינה, משום שהיה מרכבה לקו האמצעי המכריע בימין ושמאל דבינה."],[0,"","וז\"ש, \u0003סלקא ההוא רוחא וקיימא קמי מלכא,\u0004 דהיינו שהיה מרכבה למלכא, שהוא ז\"א. ואז השפיעו עליו ג' אותיות, \u0003מ' ש' ה'.\u0004 וז\"ש \u0003מ' פתיחא סליק ואתעטר בעטרוי,\u0004 שהכסא עלתה ונתעטרה במוחין שלה שיצאו ונתגלו ע\"י קו האמצעי, בסוד \u0003תלת נפקי מחד\u0004 ואז, \u0003ואעטריה בשכ\"ה עטרין,\u0004 בסוד חד בתלת קיימא, (כנ\"ל ב\"א אות שס\"ג ע\"ש) ומה שנקרא שכ\"ה עטרין, הוא מלשון וחמת המלך שככה, כי מטרם שקו האמצעי הכריע בין ב' קוי הבינה, היתה מחלוקת בין ימין ושמאל ועל ידי הכרעתו \u0003שכ\"ה\u0004 שקטה המחלוקת. (עי' ב\"א נ\"ז ד\"ה וזה) וכיון ששכ\"ה, היתה כל הסבה למוחין דז\"א שמקבל מבינה, ע\"כ מכנה אותם שכ\"ה עטרין. \u0003ואפקיד מפתחוי בידוי,\u0004 כבר נתבאר שהאורות דקו אמצעי מכונה מפתחות (לעיל אות ר\"ח)."],[0,"","וז\"ש, \u0003ש' דאבהתא, אעטרו ליה בתלת עטרין קדישין,\u0004 שהם ג' קוין חג\"ת דז\"א שלמעלה מחזה, המכונים ג' רגלי הכסא. \u0003ואפקידו כל מפתחין דמלכא בידיה,\u0004 דהיינו כל מוחין דז\"א, שמבחינת קו אמצעי מכונים מפתחות כנ\"ל. \u0003ואפקידו ליה בהימנותא מהימנא דביתא.\u0004 הנוקבא הכוללת דז\"א מכונה \u0003בית,\u0004 ולהיותו קבל כל מוחין דז\"א, נעשה \u0003נאמן,\u0004 דהיינו להשפיע אל ה \u0003בית\u0004 שהיא הנוקבא."],[0,"","וז\"ש, \u0003ה' סלקא,\u0004 שהיא המלכות שעלתה למעלה מחזה. \u0003ואתעטרא בעטרוי,\u0004 שמקבלת ג' קוין חג\"ת דז\"א ונעשתה רגל רביעי אל הכסא, \u0003וקבילת ליה מן מלכא,\u0004 שמקבלת נשמת משה מן המלך."],[1,"כדין נחת ההוא וכו':","אז כשקבלו המלכות, ירד רוח ההוא, דמשה, באניות השטות בים הגדול ההוא, שהוא המלכות, וקבלה המלכות אותו, כדי לגדלו אל המלך שיוכל להלביש את ז\"א, והיינו על ידי שיקבל ממנה הארת החכמה והגדלות, והיא נתנה לו משם, מבחינת הים הגדול שבה, שה\"ס הארת שמאל, כלי זיין להכות את פרעה ולכל ארצו. ובשבת ובראשי חדשים, היא מעלהו אל המלך, שהוא ז\"א, ואז נקרא שמו באלו אותיות הרשומות, שהם מ' ש' ה'. כמ\"ש לעיל."],[2,"ובההיא שעתא דנפק וכו':","ובשעה ההיא שיצא לרדת לארץ להתלבש בגוף בזרע לוי, התתקנו תכ\"ה נרות למלך, שהוא ז\"א, ותכ\"ה חקיקות ממונים לוו את רוח ההוא דמשה למקומו. כשיצא לעולם האירה \u0003ה',\u0004 שהיא השכינה, בפניו, והבית נתמלא מן הזיו שלה. בה בשעה קרא עליו הקב\"ה בטרם אצרך בבטן וכו'."],[2,"","פירוש. השם תכ\"ה, הוא יוצא בזווג על מסך הממעט את הרוח העליון שיוכל להתגשם ולהתלבש בגוף ברחם אמו. ונבחן בו שיעור קומה של אור היוצא בזווג הזה, וה\"ס תכ\"ה נרות שנתתקנו למלך. וכחות המיעוט היוצאים מן המסך, מכונים תכ\"ה חקיקות, שהן נעשו ממונים להוריד את הרוח לרחם אמו. וז\"ש \u0003אוזפוה לההוא רוחא לאתריה.\u0004 ואחר שנתקן בז' חדשי עבור, האירה עליו השכינה. וז\"ש \u0003אתנהרא ה' באנפוי.\u0004"],[3,"ר' יצחק אמר וכו':","רי\"א, בה בשעה הרג הקב\"ה לשר הממונה של מצרים, וראו אותו משה ובני ישראל אז אמרו שירה. ז\"ש וירא ישראל את מצרים מת אז ישיר משה ובני ישראל."],[4,"אז ישיר משה וגו':","ר' אבא פתח ואמר. הסתכלתי בכל התשבחות ששבחו להקב\"ה וכולם פתחו באז. \u0003אז\u0004 אמר שלמה. \u0003אז\u0004 ידבר יהושע. \u0003אז\u0004 ישיר ישראל. מהו הטעם."],[5,"אלא הכי תאנא וכו':","ומשיב. אלא כך למדנו. כל הנסים וכל הגבורות שנעשו להם לישראל. הוא, כשהאיר אור עתיקא קדישא, דהיינו א\"א, בעטרותיו, דהיינו הארת ג\"ר, בעת שמחזיר בינה ותו\"מ לראשו, הם חקוקים ורשומים ב \u0003א'\u0004 אשר י' העליונה של הא' הוא קו ימין, וקו תחתונה שבא' היא קו שמאל, והקו שביניהם הוא קו האמצעי המכריע ב \u0003א'\u0004 נוקב בחושך, דהיינו קו אמצעי שבא' שנוקב וממעט קו שמאל, שהוא חושך, לבחינת ו\"ק דג\"ר ואז ומאיר לכל צד, דהיינו בין בחכמה בין בחסדים. וכשמתחבר אור של ה \u0003א'\u0004 ומגיע אל ה \u0003ז',\u0004 מי הוא ז' זו היא חרב לה' מלאה דם, דהיינו המלכות בשעה שהיא נטויה לשמאל. אז עושה ניסים וגבורות, משום שנתחבר \u0003א'\u0004 עם \u0003ז'\u0004. וזה הוא שירה. שירה היא המאירה לכל הצדדים. בין לחכמה בין לחסדים. וזה הוא אז ישיר."],[6,"ישיר, שר מבעי וכו':","שואל, כתוב ישיר משה, הלא שר משה היה צריך לומר ומשיב. אלא דבר זה תלוי לעתיד לבא, שהשלים לאותו זמן והשלים לעתיד לבא, שעתידים ישראל לשבח שירה זו לעתיד לבא. \u0003משה ובני ישראל,\u0004 מכאן למדנו, שצדיקים הראשונים, אע\"פ שנסתלקו במדרגות העליונות שלמעלה ונקשרו בקשר של צרור החיים, הם עתידים כולם לעמוד לתחיה בגוף ולראות ולומר שירה זו, ז\"ש אז ישיר משה ובני ישראל."],[7,"ר' שמעון אמר וכו':","רש\"א, מכאן, יוסיף ה' שנית ידו לקנות את שאר עמו. \u0003לקנות\u0004 פירושו, כש\"א, ה' קנני ראשית דרכו. \u0003את שאר עמו,\u0004 אלו הם הצדיקים שבהם הנקראים \u0003שאר.\u0004 כמש\"א, \u0003וישארו\u0004 שני אנשים במחנה. ולמדנו, למה נקראים שאר, משום שאין העולם מתקיים אלא על אלו שמשימים עצמם \u0003שירים.\u0004 וע\"כ נקראים הצדיקים שאר, מלשון שירים."],[8,"ואי תימא הואיל וכו':","ואם תאמר, כיון שנקשרו בצרור החיים, ומתענגים בעונג העליון, למה יוריד אותם הקב\"ה לארץ. צא ולמד מפעם הראשון, דהיינו מעת שנולדו ויצאו לאויר העזלם, שכל אלו הרוחות והנשמות שהיו במדרגה העליונה של מעלה, והקב\"ה הוריד אותם לארץ למטה. כל שכן עתה, שהקב\"ה רוצה ליישר את העקום, בזה שיראה להם האותות והמופתים שיעשה לישראל, ואע\"פ שצדיקים הם מכל מקום כתוב, כי אדם אין צדיק בארץ אשר יעשה טוב ולא יחטא. ואם תאמר, אלו שמתו בעצת הנחש, שלא היה בהם שום חטא (עי' שבת נ\"ה ע\"ב) למה יקומו הם. ומשיב, אפילו הם יקומו, ויהיו בעלי עצה למלך המשיח."],[9,"ועל דא תנינן וכו':","ועל כן למדנו, משה עתיד לומר שירה לעתיד לבא. מהו הטעם. משום שכתוב, כימי צאתך מארץ מצרים אראנו נפלאות. שואל. אראנו, אראך היה צריך לומר. ומשיב. אלא אראנו ממש, שמי שראה בתחילה, דהיינו משה, יראה שנית, וזה הוא אראנו. וכתוב, אראנו בישע אלקים. ואז, אז ישיר משה ובני ישראל וגו'."]],[[0,"","אָז עָלְתָה אוֹתָהּ רוּחַ וְעָמְדָה לִפְנֵי הַמֶּלֶךְ. מ' פְּתוּחָה עָלְתָה וְהִתְעַטְּרָה בְּעַטְרוֹתֶיהָ, וְעִטְּרָה אוֹתוֹ בִּשְׁלֹשׁ מֵאוֹת וְעֶשְׂרִים וְחָמֵשׁ עֲטָרוֹת, וְהִפְקִיד מַפְתְּחוֹת בְּיָדוֹ. ש' שֶׁל הָאָבוֹת עִטְּרוּ אוֹתוֹ בְּשָׁלֹשׁ עֲטָרוֹת קְדוֹשׁוֹת, וְהִפְקִידוּ בְיָדוֹ אֶת כָּל מַפְתְּחוֹת הַמֶּלֶךְ, וְהִפְקִידוּ אוֹתוֹ בֶּאֱמוּנָה, לִהְיוֹת נֶאֱמַן הַבַּיִת. ה' עָלְתָה וְעִטְּרָה אוֹתוֹ בְּעַטְרוֹתֶיהָ, וְקִבְּלָה אוֹתוֹ מֵהַמֶּלֶךְ."],[1,"","וְאָז יָרַד אוֹתוֹ הָרוּחַ לָאֳנִיּוֹת שֶׁשָּׁטוֹת בְּאוֹת הַיָּם הַגָּדוֹל, וְקִבְּלָה אוֹתוֹ לְגַדֵּל אוֹתוֹ לַמֶּלֶךְ, וְנָתְנָה לוֹ מִשָּׁם כְּלֵי זַיִן לְהַלְקוֹת אֶת פַּרְעֹה וְאֶת כָּל אַרְצוֹ. וּבְשַׁבָּתוֹת וּבְרָאשֵׁי חֳדָשִׁים מַעֲלָה אוֹתוֹ אֶל הַמֶּלֶךְ, וְאָז נִקְרָא שְׁמוֹ בָּאוֹתִיּוֹת הָרְשׁוּמוֹת הַלָּלוּ."],[2,"","וּבְאוֹתָהּ שָׁעָה שֶׁיָּצָא לָרֶדֶת לָאָרֶץ בַּזֶּרַע שֶׁל לֵוִי, נִתְקְנוּ אַרְבַּע מֵאוֹת וְעֶשְׂרִים וְחָמֵשׁ מְנוֹרוֹת לַמֶּלֶךְ, וְאַרְבַּע מֵאוֹת וְעֶשְׂרִים וְחָמֵשׁ חֲקִיקוֹת מְמֻנִּים לִוּוּ אֶת אוֹתָהּ רוּחַ לִמְקוֹמָהּ. כְּשֶׁיָּצָא לָעוֹלָם, הֵאִירָה ה' בְּפָנָיו, וְהַבַּיִת הִתְמַלֵּא מִזִּיווֹ. בְּאוֹתָהּ שָׁעָה קָרָא עָלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּטֶרֶם אֶצָּרְךְ בַבֶּטֶן יְדַעְתִּיךְ וּבְטֶרֶם תֵּצֵא מֵרֶחֶם הִקְדַּשְׁתִּיךְ נָבִיא לַגּוֹיִם נְתַתִּיךְ."],[3,"","רַבִּי יִצְחָק אָמַר, בְּאוֹתָהּ שָׁעָה הָרַג (הפיל) הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַשַּׂר הַמְמֻנֶּה הַגָּדוֹל שֶׁל מִצְרַיִם, וְרָאוּ אוֹתוֹ מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, וְאָז אָמְרוּ שִׁירָה. זֶהוּ שֶׁכָּתוּב וַיַּרְא יִשְׂרָאֵל אֶת מִצְרַיִם מֵת, אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל."],[4,"","אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל וְגוֹ'. רַבִּי אַבָּא פָּתַח וְאָמַר, הִסְתַּכַּלְתִּי בְּכָל הַתִּשְׁבָּחוֹת שֶׁשִּׁבְּחוּ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם פָּתְחוּ בְּאָז. (מלכים א ח) אָז אָמַר שְׁלֹמֹה. (יהושע י) אָז יְדַבֵּר יְהוֹשֻׁעַ. אָז יָשִׁיר יִשְׂרָאֵל. מָה הַטַּעַם?"],[5,"","אֶלָּא כָּךְ שָׁנִינוּ, כָּל הַנִּסִּים וְהַגְּבוּרוֹת שֶׁנַּעֲשׂוּ לְיִשְׂרָאֵל, כְּשֶׁהֵאִיר אוֹר הָעַתִּיק הַקָּדוֹשׁ בְּעַטְרוֹתָיו, חֲקוּקִים רְשׁוּמִים בְּאָז, בְּא', וְא' בְּז', נָקַב בַּחֲשֵׁכָה וְהֵאִיר לְכָל עֵבֶר. וּכְשֶׁהִתְחַבֵּר הָאוֹר שֶׁל אָלֶ\"ף וְהִגִּיעַ לְזַיִ\"ן, מִי זוֹ זַיִ\"ן? זוֹ (ישעיה לד) חֶרֶב לַה' מָלְאָה דָּם. אָז עָשָׂה נִסִּים וּגְבוּרוֹת, מִשּׁוּם שֶׁהִתְחַבְּרָה א' בְּז'. וְזוֹ הִיא הַשִּׁירָה. שִׁירָה הִיא שֶׁל כָּל הַצְּדָדִים, וְזֶהוּ אָז יָשִׁיר."],[6,"","יָשִׁיר? שָׁר הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא דָּבָר זֶה תָּלוּי וּמַשְׁלִים אֶת אוֹתוֹ הַזְּמַן, וּמַשְׁלִים לֶעָתִיד לָבֹא, שֶׁעֲתִידִים יִשְׂרָאֵל לְשַׁבֵּחַ בַּשִּׁירָה הַזּוֹ מֹשֶׁה וּבְנֵי יִשְׂרָאֵל. מִכָּאן לָמַדְנוּ, שֶׁהַצַּדִּיקִים הָרִאשׁוֹנִים, אַף עַל גַּב שֶׁהִתְעַלּוּ לִדְרָגוֹת עֶלְיוֹנוֹת שֶׁלְּמַעְלָה, וְנִקְשְׁרוּ בַּקֶּשֶׁר שֶׁל צְרוֹר הַחַיִּים - עֲתִידִים כֻּלָּם לְהֵחָיוֹת בְּגוּף וְלִרְאוֹת אוֹתוֹת וּגְבוּרוֹת שֶׁיַּעֲשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל וְלוֹמַר שִׁירָה זוֹ. זֶהוּ שֶׁכָּתוּב אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל."],[7,"","רַבִּי שִׁמְעוֹן אָמַר מִכָּאן, (ישעיה יא) יוֹסִיף ה' שֵׁנִית יָדוֹ לִקְנוֹת אֶת שְׁאָר עַמּוֹ. לִקְנוֹת - כְּמוֹ שֶׁנֶּאֱמַר (משלי ח) ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ. אֶת שְׁאָר עַמּוֹ - אֵלּוּ הֵם הַצַּדִּיקִים שֶׁבָּהֶם שֶׁנִּקְרָאִים שְׁאַר, כְּמוֹ שֶׁנֶּאֱמַר (במדבר יא) וַיִּשָּׁאֲרוּ שְׁנֵי אֲנָשִׁים בַּמַּחֲנֶה. וְשָׁנִינוּ, אֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא עַל אוֹתָם שֶׁעוֹשִׂים עַצְמָם שִׁירַיִם."],[8,"","וְאִם תֹּאמַר, הוֹאִיל וְנִקְשְׁרוּ בִּצְרוֹר הַחַיִּים וּמִתְעַנְּגִים בָּעֹנֶג הָעֶלְיוֹן, לָמָּה יוֹרִיד אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָרֶץ? צֵא וּלְמַד מִזְּמַן רִאשׁוֹן, שֶׁכָּל אוֹתָם רוּחוֹת וּנְשָׁמוֹת שֶׁהָיוּ בַּדַּרְגָּה הָעֶלְיוֹנָה שֶׁלְּמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִיד אוֹתָם לָאָרֶץ לְמַטָּה. כָּל שֶׁכֵּן עַכְשָׁו, שֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַשֵּׁר אֶת הֶעָקֹם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ז) כִּי אָדָם אֵין צַדִּיק בָּאָרֶץ אֲשֶׁר יַעֲשֶׂה טוֹב וְלֹא יֶחֱטָא. וְאִם תֹּאמַר, אוֹתָם שֶׁמֵּתוּ בְּעֶטְיוֹ שֶׁל נָחָשׁ, אֲפִלּוּ הֵם יָקוּמוּ וְיִהְיֶה בַּעֲלֵי עֵצָה לְמֶלֶךְ הַמָּשִׁיחַ."],[9,"","וְעַל זֶה שָׁנִינוּ, מֹשֶׁה עָתִיד לוֹמַר שִׁירָה לֶעָתִיד לָבֹא. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (מיכה ז) כִּימֵי צֵאתְךְ מֵאֶרֶץ מִצְרַיִם אַרְאֶנּוּ נִפְלָאוֹת. אַרְאֶנּוּ? אַרְאֶךְ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא אַרְאֶנּוּ מַמָּשׁ, לְמִי שֶׁרָאָה בַּתְּחִלָּה - אַרְאֶנּוּ פַּעַם שְׁנִיָּה. וְזֶהוּ אַרְאֶנּוּ. וְכָתוּב (תהלים נ) אַרְאֶנּוּ בְּיֵשַׁע אֱלֹהִים, וְאַרְאֵהוּ בִּישׁוּעָתִי. וְאָז, אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל אֶת הַשִּׁירָה הַ את לַה'."]]],[["שִׁירָתָא דְּמַטְרוֹנִיתָא לְקוּדְשָׁא בְּרִיךְ הוּא. תָּנֵינָן, כָּל בַּר נָשׁ דְּאָמַר שִׁירָתָא דָּא בְּכָל יוֹמָא, וּמְכַוֵּון בָּהּ, זָכֵי לְמֵימְרָא לְזִמְנָא דְּאָתֵי. דְּהָא אִית בָּהּ עָלְמָא דְּעָבַר, וְאִית בָּהּ עָלְמָא דְּאָתֵי, וְאִית בָּהּ קִשְׁרֵי מְהֵימָנוּתָא, וְאִית בָּהּ יוֹמֵי דְּמַלְכָּא מְשִׁיחָא. (נ\"א את לעילא כל אינון וכו') וְתָלֵי עָלָהּ, כָּל אִינּוּן תּוּשְׁבְּחָאן אַחֲרָנִין, דְּקַאמְרֵי עִלָּאֵי וְתַתָּאֵי.","הַשִּׁירָה שִׁיר זֶה מִבָּעֵי לֵיהּ. אֶלָּא שִׁירָתָא, דְּקָא מְשַׁבָּחַת מַטְרוֹנִיתָא לְמַלְכָּא. וּמֹשֶׁה מִתַּתָּא לְעֵילָּא קָאָמַר, וְהָא אוּקְמוּהָ. לַיְיָ': בְּגִין דְּאַנְהִיר לָהּ מַלְכָּא אַנְפָּהָא, (נ\"א דנהיר אנפוי מלכא לקבלה) ר' יוֹסֵי אָמַר, דְּכָל אִינּוּן מְשָׁחִין, דַּהֲווֹ נַגְדִּין, מָשִׁיךְ מַלְכָּא קַדִּישָׁא לְקַבְּלָהּ, בְּגִינִי כַּךְ מְשַׁבְּחָא לֵיהּ מַטְרוֹנִיתָא.","אָמַר רִבִּי יְהוּדָה, אִי הָכִי, אֲמַאי כְּתִיב מֹשֶׁה וּבְנִי יִשְׂרָאֵל, וְהָא מַטְרוֹנִיתָא בַּעְיָא לְשַׁבְּחָא. אֶלָּא, זַכָּאָה חוּלָקֵיהוֹן דְּמֹשֶׁה וְיִשְׂרָאֵל, דְּאִינּוּן הֲווֹ יַדְעִין לְשַׁבְּחָא לְמַלְכָּא, בְּגִין מַטְרוֹנִיתָא כְּדְקָא יֵאוֹת, בְּגִין דְּכָל הַהוּא חֵילָא וּגְבוּרָה דִּילָהּ, יָרְתָא מִן מַלְכָּא.","ר' חִיָּיא פָּתַח וְאָמַר, (איכה ב׳:י״ט) קוּמִי רוֹנִּי בַּלַּיְלָה לְרֹאשׁ אַשְׁמוּרוֹת. קוּמִי רוֹנִּי: דָּא כְּנֶסֶת יִשְׂרָאֵל. בַּלַּיְלָה: בְּגָלוּתָא. ר' יוֹסֵי אָמַר, בַּלַּיְלָה: בְּזִמְנָא דְּהִיא שַׁלְטָא וּמִתְּעָרָא, לְרֹאשׁ אַשְׁמוּרוֹת, בְּרֹאשׁ מִבָּעֵי לֵיהּ. אֶלָּא לְרֹאשׁ, כְּמָה דִּכְתִּיב, (בראשית מ״ז:ל״א) עַל רֹאשׁ הַמִּטָּה. וְאוֹקִימְנָא, רֹאשׁ הַמִּטָּה, דָּא יְסוֹד. אוּף הָכָא לְרֹאשׁ, דָּא יְסוֹד, דְּמַטְרוֹנִיתָא מִתְבָּרְכָא בֵּיהּ. רֹאשׁ אַשְׁמוּרוֹת: דָּא הוּא רֵישָׁא, דְּנֶצַח וְהוֹד.","ר' יוֹסֵי אָמַר, דָּא הוּא רִישָׁא דְּכִתְרֵי מַלְכָּא וְסִיּוּמָא. רִבִּי אַבָּא אָמַר, לְרֹאשׁ אַשְׁמְרוֹת כְּתִיב חָסֵר, וְדָא הוּא רֵישָׁא, רֹאשׁ הַמִּטָּה. וְכֹלָּא בְּמַלְכָּא קַדִּישָׁא עִלָּאָה אִתְּמַר, וְדָא הוּא לַיְיָ'.","רִבִּי יֵיסָא אָמַר, הַשִּׁירָה הַזֹּאת לַיְיָ', דָּא הוּא נַהֲרָא דְּנָפִיק מֵעֵדֶן, דְּכָל מִשְׁחָא וּרְבוּ נָפִיק מִנֵּיהּ, לְאַדְלְקָא בּוּצִינִין. וּמַשְׁמַע לְבָתַר דִּכְתִּיב אָשִׁירָה לַיְיָ', דָּא הוּא מַלְכָּא קַדִּישָׁא עִלָּאָה, וְעַל דָּא לָא כְּתִיב אָשִׁירָה לּוֹ.","וַיֹּאמְרוּ לֵאמֹר, לְדָרֵי דָּרִין, בְּגִין דְּלָא יִתְנְשֵׁי מִנַּיְיהוּ לְעָלְמִין. דְּכָל מַאן דְּזָכֵי לְהַאי שִׁירָתָא בְּהַאי עָלְמָא, זָכֵי לָהּ בְּעָלְמָא דְּאָתֵי, וְזָכֵי לְשַׁבְּחָא בָּהּ בְּיוֹמוֹי דְּמַלְכָּא מְשִׁיחָא, בְּחֶדְוָותָא דְּכְּנְסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב לֵאמֹר, לֵאמֹר בְּהַהוּא זִמְנָא. לֵאמֹר בְּאַרְעָא קַדִּישָׁא, בְּזִמְנָא דְּשָׁרוּ יִשְׂרָאֵל בְּאַרְעָא. לֵאמֹר בְּגָלוּתָא. לֵאמֹר בְּפוּרְקָנָא דִּלְהוֹן דְּיִשְׂרָאֵל. לֵאמֹר לְעָלְמָא דְּאָתֵי.","אָשִׁירָה לַיְיָ' נָשִׁיר מִבָּעֵי לֵיהּ, מַאי אָשִׁירָה. אֶלָּא בְּגִין דַּהֲווֹ מְשַׁבְּחָן תּוּשַׁבַּחְתָּא דְּמַטְרוֹנִיתָא. (בעו לשבחא) לַיְיָ': דָּא מַלְכָּא קַדִּישָׁא. כִּי גָאֹה גָּאָה (קמה): דְּסָלִיק וְאִתְעַטָּר בְּעִטְרוֹי, לְאַפָּקָא בִּרְכָּאן וְחֵילִין וּגְבוּרָאן, לְאַסָּקָא בְּכֹלָּא. כִּי גָאֹה גָּאָה: גָאֹה בְּהַאי עָלְמָא, גָּאָה בְּעָלְמָא דְּאָתֵי. כִּי גָאֹה בְּהַהוּא זִמְנָא, גָּאָה, בְּגִין דְּיִתְעֲטָּר בְּעִטְּרוֹי בְּחֶדְוָותָא שְׁלֵימוּתָא.","סוּס וְרוֹכְבוֹ רָמָה בַּיָּם, שׁוּלְטָנוּתָא דִּלְתַתָּא, וְשׁוּלְטָנוּתָא דִּלְעֵילָּא דַּאֲחִידָן בְּהוּ, אִתְמְסָרוּ בְּהַהוּא יַמָּא רַבָּא, וְשֻׁלְטָנוּתָא רַבָּא לְמֶעְבַּד בְּהוּ נוּקְמִין. וְתָנֵינָן, לָא עָבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא לְתַתָּא, עַד דְּיַעֲבֵיד בְּשׁוּלְטָנֵיהוֹן לְעֵילָּא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.","רָמָה בַּיָּם, אָמַר ר' יְהוּדָה, בֵּיהּ בְּלֵילְיָא, אִתְּעַר גְּבוּרָא תַּקִּיפָא, דִּכְתִּיב בֵּיהּ וַיּוֹלֶךְ יְיָ' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה כָּל הַלַּיְלָה. (ס\"א דאתער ביה גבורה תקיפא) בְּהַהוּא זִמְנָא, בָּעָאת מַטְרוֹנִיתָא מִן מַלְכָּא, כָּל אִינּוּן אֹכְלוֹסִין דִּלְתַתָּא, וְכָל אִינּוּן שׁוּלְטָנִין דִּלְעֵילָּא, דְּיִתְמַסְּרוּן בִּידָהָא. וְכֻלְּהוּ אִתְמְסָרוּ בִּידָהָא, לְמֶעְבַּד בְּהוּ נוּקְמִין, הֲדָא הוּא דִכְתִיב סוּס וְרוֹכְבוֹ רָמָה בַּיָּם. בַּיָּם סְתָם, לְעֵילָּא וְתַתָּא.","(שמות ט״ו:ב׳) עָזִּי וְזִמְרָת יָהּ. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים קל״ט:ה׳) אָחוֹר וְקֹדֶם צַרְתָּנִי וַתָּשֶׁת עָלַי כַּפֶּכָה. כַּמָּה אִצְטְרִיכוּ בְּנֵי נָשָׁא לְיַקָרָא לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד בָּרָא עָלְמָא, אִסְתָּכַּל בֵּיהּ בָּאָדָם לְמֶהוֵי שַׁלִּיט עַל כֹּלָּא. (נ\"א למהוי שלים בכלא ואתברי דו פרצופין) וַהֲוָה דָּאמֵי לְעִלָּאִין וְתַתָּאִין. נָחַת לֵיהּ בִּדְמוּת יַקִּירָא, וְחָמוּ לֵיהּ בִּרְיָין, כְּדֵין אִתְכְּנָשׁוּ לְגַבֵּיהּ, וְסָגִידוּ לָקֳבְלֵיהּ, וְאֵימָתָא וְדַחֲלָא נָפְלַת עָלַיְיהוּ מִדַּחַלְתֵּיהּ, הֲדָא הוּא דִכְתִיב, (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם."],[[0,"שירתא דמטרוניתא לקב\"ה וכו':","היא שירה של המטרוניתא, שהיא המלכות, אל הקב\"ה, למדנו, כל אדם שאומר שירה זו בכל יום, ומכוון בה, זוכה לאמרו לעתיד לבא. כי יש בה עולם העבר, ויש בה עולם הבא, ויש בה קשרי האמונה, ויש בה ימי מלך המשיח. ונתלים עליה כל התשבחות האחרות שאומרים העליונים והתחתונים."],[1,"השירה, שיר זה וכו':","שואל. כתוב, השירה לשון נקבה, שיר זה היה צריך לומר, לשון זכר. ומשיב. אלא היא שירה שהמטרוניתא משבחת אל המלך, שהוא ז\"א. ומשה ממטה למעלה אמר. מן המלכות אל ז\"א. וע\"כ אומר שירה, לשון נקבה. וכבר בארוה. \u0003לה',\u0004 היא שרה לה' משום שהמלך האיר לה פנים. ר' יוסי אמר, כל אלו השמנים, דהיינו האורות, שהיו נמשכים, משך לה המלך הקדוש, משום זה שבחה לו המטרוניתא."],[2,"אמר ר' יהודה וכו':","אר\"י, אם כן, שהיא שירת המטרוניתא אל המלך, למה כתוב, משה ובני ישראל, והרי המטרוניתא צריכה לשבח. ומשיב, אלא אשרי חלקם של משה וישראל, שהם היו יודעים לשבח אל המלך בשביל המטרוניתא כראוי, משום שכל כח וגבורה שלה ירשה מן המלך."],[3,"ר' חייא פתח וכו':","רח\"פ ואמר, קומי רוני בלילה לראש אשמורות. קומי רוני, זו כנסת ישראל, שהיא המלכות. \u0003בלילה,\u0004 היינו בגלות. ר' יוסי אומר, \u0003בלילה,\u0004 היינו בזמן שהיא שולטת ומתעוררת. כי המלכות שולטת בלילה. \u0003לראש אשמורות,\u0004 בראש, היה צריך לומר. ומשיב, אלא, לראש, הוא כמ\"ש על ראש המטה. והעמדנו, ראש המטה, זהו יסוד. אף כאן, לראש, זהו יסוד, שהמטרוניתא מתברכת בו. \u0003ראש אשמורות,\u0004 זהו ראש של נצח והוד. שהוא יסוד."],[4,"ר' יוסי אמר וכו':","זהו ראש של כתרי המלך והסיום. שמבחינת ט\"ס דאור ישר דז\"א הוא התחתון המסיים. ומבחינת ט\"ס דאור חוזר דז\"א המאירים ממטה למעלה, נחשב היסוד לכתר דאו\"ח (כמ\"ש בפמ\"ס דף ל\"א ד\"ה ומתחילה ע\"ש) וכיון שהוא ראש הספירות דאו\"ח, ע\"כ קורא אותו הכתוב לראש אשמורות. ר' אבא אמר לראש אשמרות כתוב, חסר \u0003ו',\u0004 שרומזת על מלכות, וזה היסוד הוא ראש אליה, כמו שנקרא ראש המטה. והכל במלך הקדוש העליון נאמר. שהוא ז\"א, דהיינו יסוד דז\"א. וזה הוא שנאמר, השירה הזאת \u0003לה'\u0004, דהיינו ליסוד דז\"א."],[5,"ר' ייסא אמר וכו':","ר\"א, השירה הזאת לה', זה הוא הנהר, שהיא בינה, היוצא מעדן, שהיא חכמה, דהיינו בינה שיצאה מראש דא\"א, שכל השמן והגדלות, דהיינו כל המוחין שבזו\"ן ובי\"ע, יוצאים ממנו. וזה נשמע מהכתוב שלאחריו, שכתוב, אשירה לה', שזה הוא מלך הקדוש העליון, דהיינו ז\"א, ועל כן לא כתוב, אשירה לו, כי לה' הקודם, שבשירה הזאת לה', היא בינה ולא ז\"א."],[6,"ויאמרו לאמר:","היינו לאמר לדורי דורות, כדי שלא ישכח מהם לעולם. כי כל מי שזכה לשירה הזו בעולם הזה, זוכה בה בעולם הבא, וזוכה לשבח בה בימיו של מלך המשיח בשמחת כנסת ישראל בהקב\"ה. שכתוב \u0003לאמר,\u0004 שפירושו, לאמר, באותו הזמן, לאמר, בארץ הקדושה בזמן שישבו ישראל בארץ, לאמר, בגלות, לאמר, בגאולתם של ישראל, לאמר, לעולם הבא."],[7,"אשירה לה':","שואל, נשיר היה צריך לומר, מהו שאומר אשירה. ומשיב. אלא משום שהיו משבחים תשבחות המטרוניתא. כנ\"ל, ע\"כ כתוב אשירה בלשון יחיד. \u0003לה'\u0004 זהו המלך הקדוש, שהוא ז\"א. \u0003כי גאה גאה,\u0004 היינו שעלה והתעטר בעטרותיו, להוציא ברכות וכחות וגבורות להתעלות בכל. \u0003כי גאה גאה,\u0004 גאה בעולם הזה, גאה בעולם הבא. כי גאה באותו זמן, גאה, כדי שיתעטר אח\"כ בעטרותיו בשמחה שלמה."],[8,"סוס ורוכבו רמה בים:","היינו הממשלה של מטה, שהיא סוס, והממשלה של מעלה שהם נאחזים בה, שהיא רוכבו, שתיהן נמסרו בים הגדול ההוא והממשלה הגדולה, לעשות בהם נקמות. ולמדנו, אין הקב\"ה עושה דין למטה עד שיעשה בממשלתם של מעלה, ז\"ש, יפקוד ה' על צבא המרום במרום, ועל מלכי האדמה על האדמה."],[9,"רמה בים:","אמר ר' יהודה, בו בלילה התעוררה גבורה חזקה, שכתוב בה, ויולך ה' את הים ברוח קדים עזה כל הלילה. באותו זמן בקשה המטרוניתא מן המלך כל אלו המוני המצרים של מטה וכל אלו השרים של מעלה, שימסרו בידיה. וכולם נמסרו בידיה לעשות בהם נקמות. ז\"ש סוס ורוכבו רמה בים. בים כתוב סתם, ויורה בין בים שלמעלה ובין בים שלמטה."],[10,"עזי וזמרת יה:","ר' חייא פתח ואמר, אחור וקדם צרתני ותשת עלי כפכה. כמה צריכים בני אדם לכבד את הקב\"ה, משום שהקדוש ברוך הוא, כשברא העולם, הסתכל באדם שיהיה מושל על הכל. והיה דומה לעליונים ותחתונים. הוריד אותו לעולם בדמות יקרה, וראו אותו הבריות, אז התקבצו והשתחוו לפניו, ואימה ופחד נפלה עליהם מיראתו. ז\"ש ומוראכם וחתכם יהיה על כל חית השדה ועל כל עוף השמים."]],[[0,"","שִׁירָה שֶׁל הַגְּבִירָה לַקָּדוֹשׁ-בָּרוּךְ- הוּא. שָׁנִינוּ, כָּל אָדָם שֶׁאוֹמֵר שִׁירָה זוֹ בְּכָל יוֹם וּמְכַוֵּן בָּהּ, זוֹכֶה לְאָמְרָהּ לֶעָתִיד לָבֹא, שֶׁהֲרֵי יֵשׁ בָּהּ עוֹלָם שֶׁעָבַר, וְיֵשׁ בָּהּ עוֹלָם הַבָּא, וְיֵשׁ בָּהּ קִשְׁרֵי הָאֱמוּנָה, וְיֵשׁ בָּהּ יְמוֹת מֶלֶךְ הַמָּשִׁיחַ, וּתְלוּיִים עָלֶיהָ (אות למעלה) כָּל אוֹתָן תִּשְׁבָּחוֹת אֲחֵרוֹת שֶׁאוֹמְרִים עֶלְיוֹנִים וְתַחְתּוֹנִים."],[1,"","הַשִּׁירָה, ?, שִׁיר זֶה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא הַשִּׁירָה שֶׁמְּשַׁבַּחַת הַגְּבִירָה לַמֶּלֶךְ. וּמֹשֶׁה אָמַר מִלְּמַטָּה לְמַעְלָה, וַהֲרֵי פֵּרְשׁוּהָ. לַה' - מִשּׁוּם שֶׁהַמֶּלֶךְ מֵאִיר לָהּ פָּנִים (שמאירים פני המלך כנגדה). רַבִּי יוֹסֵי אָמַר, כָּל אוֹתָם שְׁמָנִים שֶׁהָיוּ שׁוֹפְעִים, מָשַׁךְ הַמֶּלֶךְ הַקָּדוֹשׁ כְּנֶגְדָּהּ, מִשּׁוּם כָּךְ מְשַׁבַּחַת אוֹתוֹ הַגְּבִירָה."],[2,"","אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, לָמָּה כָּתוּב מֹשֶׁה וּבְנֵי יִשְׂרָאֵל, וַהֲרֵי הַגְּבִירָה צְרִיכָה לְשַׁבֵּחַ? אֶלָּא אַשְׁרֵי חֶלְקָם שֶׁל מֹשֶׁה וְיִשְׂרָאֵל, שֶׁהֵם הָיוּ יוֹדְעִים לְשַׁבֵּחַ אֶת הַמֶּלֶךְ בִּשְׁבִיל הַגְּבִירָה כָּרָאוּי, מִשּׁוּם שֶׁכָּל אוֹתוֹ כֹּחַ וּגְבוּרָה שֶׁלָּהּ יָרְשָׁה מִן הַמֶּלֶךְ."],[3,"","רַבִּי חִיָּיא פָּתַח וְאָמַר, (איכה ב) קוּמִי רֹנִּי בַלַּיְלָה לְרֹאשׁ אַשְׁמֻרוֹת. קוּמִי רֹנִּי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. בַּלַּיְלָה - בַּגָּלוּת. רַבִּי יוֹסֵי אָמַר, בַּלַּיְלָה - בִּזְמַן שֶׁשּׁוֹלֶטֶת וּמִתְעוֹרֶרֶת. לְרֹאשׁ אַשְׁמֻרוֹת?! בְּרֹאשׁ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לְרֹאשׁ, כַּכָּתוּב (בראשית מז) עַל רֹאשׁ הַמִּטָּה. וּבֵאַרְנוּ, רֹאשׁ הַמִּטָּה זֶה יְסוֹד. אַף כָּאן לְרֹאשׁ - זֶה יְסוֹד, שֶׁהַגְּבִירָה מִתְבָּרֶכֶת בּוֹ. רֹאשׁ אַשְׁמֻרוֹת - זֶהוּ רֹאשׁ שֶׁל נֶצַח וְהוֹד."],[4,"","רַבִּי יוֹסֵי אָמַר, זֶהוּ רֹאשׁ שֶׁל כִּתְרֵי הַמֶּלֶךְ וְהַסִּיּוּם. רַבִּי אַבָּא אָמַר, לְרֹאשׁ אַשְׁמֻרוֹת כָּתוּב חָסֵר, וְזֶהוּ הָרֹאשׁ, רֹאשׁ הַמִּטָּה. וְהַכֹּל נֶאֱמַר בַּמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְזֶהוּ לַה'."],[5,"","רַבִּי יֵיסָא אָמַר, הַשִּׁירָה הַזֹּאת לַה' - זֶהוּ הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן, שֶׁכָּל שֶׁמֶן וּמִשְׁחָה יוֹצְאִים מִמֶּנּוּ לְהַדְלִיק מְנוֹרוֹת. וּמַשְׁמָע אַחַר כָּךְ שֶׁכָּתוּב אָשִׁירָה לַּה' - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן, וְעַל זֶה לֹא כָתוּב אָשִׁירָה לּוֹ."],[6,"","וַיֹּאמְרוּ לֵאמֹר - (זהו) לְדוֹרֵי דוֹרוֹת, כְּדֵי שֶׁלֹּא יִשְׁתַּכַּח מֵהֶם לְעוֹלָמִים. שֶׁכָּל מִי שֶׁזּוֹכֶה לַשִּׁירָה הַזּוֹ בָּעוֹלָם הַזֶּה, זוֹכֶה לָהּ בָּעוֹלָם הַבָּא, וְזוֹכֶה לְשַׁבֵּחַ בָּהּ בִּימוֹת מֶלֶךְ הַמָּשִׁיחַ בְּחֶדְוַת כְּנֶסֶת יִשְׂרָאֵל בַּקָּדוֹשׁ- בָּרוּךְ-הוּא, שֶׁכָּתוּב לֵאמֹר - לֵאמֹר בְּאוֹתוֹ זְמַן. לֵאמֹר בָּאָרֶץ הַקְּדוֹשָׁה, בִּזְמַן שֶׁשָּׁכְנוּ יִשְׂרָאֵל בָּאָרֶץ. לֵאמֹר בַּגָּלוּת. לֵאמֹר בִּגְאֻלַּת יִשְׂרָאֵל. לֵאמֹר לָעוֹלָם הַבָּא."],[7,"","אָשִׁירָה לַּה'?! נָשִׁיר הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אָשִׁירָה? אֶלָּא מִשּׁוּם שֶׁהָיוּ מְשַׁבְּחִים אֶת תִּשְׁבַּחַת הַגְּבִירָה. (הצטרכו לשבח) לַּה' - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ. כִּי גָאֹה גָּאָה (קמה) - שֶׁעָלָה וְהִתְעַטֵּר בְּעַטְרוֹתָיו לְהוֹצִיא בְרָכוֹת וְכֹחוֹת וּגְבוּרוֹת לְהִתְעַלּוֹת בַּכֹּל. כִּי גָאֹה גָּאָה - גָּאֹה בָּעוֹלָם הַזֶּה, גָּאָה לָעוֹלָם הַבָּא. כִּי גָאֹה בְּאוֹתוֹ זְמַן, גָּאָה כְּדֵי שֶׁיִּתְעַטֵּר בְּעַטְרוֹתָיו בְּחֶדְוָה שְׁלֵמָה."],[8,"","סוּס וְרֹכְבוֹ רָמָה בַיָּם - הַשִּׁלְטוֹן שֶׁלְּמַטָּה וְהַשִּׁלְטוֹן שֶׁלְּמַעְלָה שֶׁאֲחוּזִים בָּהֶם, נִמְסְרוּ לְאוֹתוֹ הַיָּם הַגָּדוֹל וְהַשַּׁלִּיט הַגָּדוֹל לַעֲשׂוֹת בָּהֶם נְקָמוֹת. וְשָׁנִינוּ, לֹא עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין לְמַטָּה, עַד שֶׁיַּעֲשֶׂה בְּשַׁלִּיטֵיהֶם לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה."],[9,"","רָמָה בַיָּם - אָמַר רַבִּי יְהוּדָה, בּוֹ בַּלַּיְלָה הִתְעוֹרְרָה גְבוּרָה חֲזָקָה, שֶׁכָּתוּב בּוֹ וַיּוֹלֶךְ ה' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה כָּל הַלַּיְלָה. (שהתעוררה בו גבורה חזקה) בְּאוֹתוֹ זְמַן בִּקְשָׁה הַמַּלְכָּה מִן הַמֶּלֶךְ אֶת כָּל אוֹתָם אוּכְלוּסִים שֶׁלְּמַטָּה וְכָל אוֹתָם שַׁלִּיטִים שֶׁלְּמַעְלָה שֶׁיִּמָּסְרוּ בְיָדֶיהָ, וְכֻלָּם נִמְסְרוּ לְיָדֶיהָ לַעֲשׂוֹת בָּהֶם נְקָמוֹת. זֶהוּ שֶׁכָּתוּב סוּס וְרֹכְבוֹ רָמָה בַיָּם. בַּיָּם סְתָם, לְמַעְלָה וּלְמַטָּה."],[10,"","עָזִּי וְזִמְרָת יָהּ. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קלט) אָחוֹר וָקֶדֶם צַרְתָּנִי וַתָּשֶׁת עָלַי כַּפֶּכָה. כַּמָּה הִצְטָרְכוּ בְּנֵי אָדָם לְכַבֵּד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכַּאֲשֶׁר בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִסְתַּכֵּל עַל הָאָדָם לִהְיוֹת שַׁלִּיט עַל הַכֹּל, (להיות שלם בכל, ונברא בשני פרצופים) וְהָיָה דוֹמֶה לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. הוֹרִיד אוֹתוֹ בִּדְמוּת מְכֻבֶּדֶת, וְרָאוּ אוֹתוֹ הַבְּרִיּוֹת. אָז הִתְכַּנְּסוּ אֵלָיו וְהִשְׁתַּחֲווּ לְפָנָיו, וּפַחַד וְאֵימָה נָפְלוּ עֲלֵיהֶם מִפַּחְדּוֹ. זֶהוּ שֶׁכָּתוּב (בראשית ט) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם."]]],[["עַיְילֵיהּ לְגִנְתֵּיהּ דְּנָטַע, לְנַטְרֵיהּ לְמֶהֱוֵי לֵיהּ חֵדוּ עַל חִדוּ, וּלְאִשְׁתַּעְשְׁעָ בֵּיהּ. עָבֵד לֵיהּ טְרוֹצְטְבוּלִין מְחַפְּיָין בְּאַבְנֵי יְקָר, וּמַלְאָכִין עִלָּאִין חַדָּאן קָמֵיהּ. לְבָתַר פָּקִיד לֵיהּ עַל אִילָנָא חַד וְלָא קָאִים בְּפִקּוּדָא דְּמָארֵיהּ.","אַשְׁכַּחְנָא בְּסִפְרָא דְּחֲנוֹךְ, דִּלְבָתַר דְּסָלִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַחְמֵי לֵיהּ כָּל גִּנְזַיָּיא דְּמַלְכָּא, עִלָּאֵי וְתַתָּאֵי, אַחְמֵי לֵיהּ אִילָנָא דְּחַיֵּי, וְאִילָנָא דְּאִתְפְּקַד עָלֵיהּ אָדָם, וְאַחְמֵי לֵיהּ דּוּכְתֵּיהּ דְּאָדָם בְּגִנְתָּא דְּעֵדֶן. וְחָמָא, דְּאִלְמָלֵי נָטִיר אָדָם פִּקּוּדָא דָּא, יָכִיל לְקַיְּימָא תָּדִירָא, וּלְמֶהֱוֵי תָּדִירָא תַּמָּן. הוּא לָא נָטַר פִּקּוּדָא דְּמָארֵיהּ, נָפַק בְּדִימוֹס וְאִתְעֲנָשׁ.","רִבִּי יִצְחָק אָמַר, אָדָם דּוּ פַּרְצוּפִין אִתְבְּרֵי, וְהָא אוֹקִימְנָא, (בראשית ב׳:כ״א) וַיִּקַּח אַחַת מִצַּלְעוֹתָיו, נְסָרוֹ הַקָדוֹשׁ בָּרוּךְ הוּא וְאִתְעָבִידוּ תְּרֵין, מִמִּזְרָח וּמִמַּעֲרָב, הֲדָא הוּא דִּכְתִּיב, (תהילים קל״ט:ה׳) אָחוֹר וְקֶדֶם צַרְתָּנִי. אָחוֹר דָּא מַעֲרָב, וְקֶדֶם דָּא מִזְרָח.","ר' חִיָּיא אָמַר, מַה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, תַּקִּין לְהַהוּא נוּקְבָּא וְשַׁכְלִיל שְׁפִירוּתָהּ עַל כֹּלָּא, וְעַיְילָהּ לְאָדָם, הֲדָא הוּא דִכְתִיב וַיִּבֶן יְיָ' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה. תָּא חֲזֵי, מַה כְּתִיב לְעֵילָּא, וַיִּקַּח אַחַת מִצַּלְעוֹתָיו. מַאי אַחַת. כְּמָה דְאַתְּ אָמֵר (שיר השירים ו׳:ט׳) אַחַת הִיא יוֹנָתִי תַּמָּתִי אַחַת הִיא לְאִמָּהּ. מִצַּלְעוֹתָיו: מִסִּטְרוֹי. כְּמָה דְאַתְּ אָמֵר, (שמות כ״ו:כ׳) וּלְצֶלַע הַמִּשְׁכָּן.","ר' יְהוּדָה אָמַר, קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמְתָא עִלָּאָה יָהַב בֵּיהּ בְּאָדָם, וְכָלִיל בֵּיהּ חָכְמְתָא וְסָכְלְתָנוּ, לְמִנְדַּע כֹּלָּא. מֵאָן אֲתָר יָהַב בֵּיהּ נִשְׁמְתָא. ר' יִצְחָק אָמַר, מֵאֲתָר דִּשְׁאַר נִשְׁמָתִין קַדִּישִׁין קָא אַתְיָין.","ר' יְהוּדָה אָמַר, מֵהָכָא. דִּכְתִּיב, (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, מַאן הָאָרֶץ. מֵהַהוּא אֲתָר דְּמַקְדְּשָׁא אִשְׁתְּכַח בֵּיהּ. נֶפֶשׁ חַיָּה, נֶפֶשׁ חַיָּה סְתָם, דָּא נַפְשָׁא דְּאָדָם קַדְמָאָה דְּכֹלָּא.","ר' חִיָּיא אָמַר, אָדָם הֲוָה יָדַע חָכְמְתָא עִלָּאָה, יַתִּיר מִמַּלְאֲכֵי עִלָּאֵי, וַהֲוָה מִסְתַּכֵּל בְּכֹלָּא, וְיָדַע וְאִשְׁתְּמוֹדָע לְמָארֵיהּ, יַתִּיר מִכָּל שְׁאַר בְּנֵי עָלְמָא. בָּתַר דְּחָב, אַסְתִּימוּ מִנֵיהּ מַבּוּעֵי דְּחָכְמְתָא, מַה כְּתִיב (נ\"א ממדז דכתיב) (בראשית ג׳:כ״ג) וַיְשַׁלְּחֵהוּ יְיָ' אֱלהִים מִגַּן עֵדֶן לַעֲבוֹד אֶת הָאֲדָמָה.","ר' אַבָּא אָמַר, אָדָם הָרִאשׁוֹן מִדְּכַר וְנוּקְבָּא אִשְׁתְּכַח, הֲדָא הוּא דִכְתִיב, (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵינוּ, וְעַל דָּא, דְּכַר וְנוּקְבָּא אִתְעָבִידוּ כַּחֲדָא, וְאִתְפְּרָשׁוּ לְבָתַר. וְאִי תֵּימָא, הָא דְּאָמַר הָאֲדָמָה אֲשֶׁר לֻקַּח מִשָׁם. הָכִי הוּא וַדַּאי, וְדָא הִיא נוּקְבָּא, וְקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתָּתַּף עִמָּהּ, וְדָא הוּא דְּכָר וְנוּקְבָּא, וְכֹלָּא הוּא מִלָּה חֲדָא.","ר' יוֹסֵי אָמַר, עָזִּי וְזִמְרָת יָהּ, אִינּוּן דִּכְלִילָן דָּא בְּדָא וְלָא (נ' ע\"ב) אִתְפָּרְשָׁאן דָּא מִן דָּא וּלְעָלְמִין אִינּוּן בַּחֲבִיבוּתָא, בִּרְעוּתָא חֲדָא, דְּמִתַּמָּן אִשְׁתְּכָחוּ (נ\"א אתמשכו) מְשִׁיכָן דְּנַחֲלִין וּמַבּוּעִין לְאִסְתַּפְּקָא כֹּלָּא, וּלְבָרְכָא כֹּלָּא, לָא כְּדִיבוּ מֵימֵי מַבּוּעִין, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ח:י״א) וּכְמוֹצָא מַיִם אֲשֶׁר לא יְכַזְּבוּ מֵימָיו וְעַל דָּא וַיְהִי לִי לִישׁוּעָה, דִּבְגִינֵי כַּךְ, מַלְכָּא קַדִּישָׁא מָשִׁיךְ וְאַחֲסִין לְתַתָּא, וְאִתְּעַר יְמִינָא לְמֶעְבַּד נִסִּין.","זֶה אֵלִי וְאַנְוֵהוּ. דָּא צַדִּיק, דְּמִנֵּיהּ נָפְקִין בִּרְכָּאן בְּזִוּוּג. וְאַנְוִהוּ: בְּהַהוּא אֲתָר דַּחֲבִיבוּתָא אִשְׁתְּכַח בֵּיהּ, וְדָא הוּא מַקְדְּשָׁא. אֱלהֵי אָבִי וַאֲרוֹמְמֶנְהוּ, מֹשֶׁה קָאָמַר דָּא, לְגַבֵּי אֲתָר דְּלֵוָאֵי אַתְיָין מֵהַהוּא סִטְרָא וְעַל דָּא (הוה) שְׁלֵימוּתָא דְּכֹלָּא הוּא בְּהַהוּא אֲתָר. (נ\"א בהאי קרא)","ר' יִצְחָק אָמַר, וַיְהִי לִי לִישׁוּעָה, דָּא מַלְכָּא קַדִּישָׁא, וְהָכִי הוּא. וּמְנָלָן. מִקְרָא אַחֲרִינָא אַשְׁכַּחְנָא לֵיהּ, דִּכְתִּיב, (ישעיהו י״ב:ב׳) כִּי עָזִּי וְזִמְרָת יָהּ יְיָ' וַיְהִי לִי לִישׁוּעָה, מִמַּשְׁמַע דְּקָאָמַר יְיָ' וַיְהִי לִי לִישׁוּעָה, דָּא מַלְכָּא קַדִּישָׁא."],[[0,"עייליה לגנתיה דנטע וכו':","הכניסו אל הגן שנטע לשמרו, להיות לו שמחה על שמחה, ולהשתעשע בו. עשה לו חופה מכוסה באבני יקר, ומלאכים העליונים שמחים לפניו. אחר כך צוה אותו על אילן אחד שלא יאכל ממנו, ולא עמד במצות אדונו."],[1,"אשכחנא בספרא דחנוך וכו':","מצאתי בספר של חנוך. שלאחר שהעלה אותו, את חנוך, והראה לו כל אוצרות המלך העליונים והתחתונים, הראה לו עץ החיים, ואת העץ שנצטוה עליו אדם, והראה לו מקומו של אדם בגן עדן. וראה, שאם היה שמר אדם מצוה זו, של עץ הדעת, היה יכול לחיות תמיד, ולהיות תמיד שם. הוא לא שמר מצות אדונו, יצא לדין ונענש."],[2,"ר' יצחק אמר וכו':","רי\"א, אדם בשני פנים נברא, וכן בארוה, ויקח אחת מצלעותיו, נסרו הקב\"ה ונעשו שנים, ממזרח וממערב, אדם ממזרח וחזה ממערב. ז\"ש אחור וקדם צרתני. אחור זה מערב, וקדם זה מזרח."],[3,"ר' חייא אמר וכו':","רח\"א, מה עשה הקב\"ה תקן אותה הנקבה ושכלל יפיה על כל, והביאה לאדם. ז\"ש, ויבן ה' אלקים את הצלע וגו'. בוא וראה, מה כתוב למעלה, ויקח אחת מצלעותיו. מהו אחת. הוא כמש\"א, אחת היא יונתי תמתי אחת היא לאמה. שהיא המלכות. \u0003מצלעותיו,\u0004 פירושו מצדדיו. כמש\"א ולצלע המשכן. כי נלקחה מצד שמאל."],[4,"ר' יהודה אמר וכו':","רי\"א הקב\"ה נתן נשמה עליונה באדם, והכליל בה חכמה ותבונה לדעת הכל. שואל, מאיזה מקום נתן בו נשמה. ר' יצחק אמר, ממקום ששאר הנשמות באות, דהיינו בינה, שאור הבינה נקרא נשמה."],[5,"ר' יהודה אמר מהכא וכו':","רי\"א, מכאן, שכתוב, תוצא הארץ נפש חיה. שואל, מאיזה מקום בארץ. ומשיב, מאותו מקום שהמקדש נמצא בו, כי הארץ היא מלכות, ומקום המקדש הוא בינה שבה. נפש חיה. אומר נפש חיה סתם, והכתוב אינו מפרש, נפש של מי. ואומר, זהו נפש של אדם הראשון מכל. פירוש. אור הנפש הוא אור המלכות, אבל נמשך מבינה שבה, וע\"כ אומר שנמשך ממקום המקדש, שהיא בינה שבה."],[6,"ר' חייא אמר וכו':","רח\"א, אדם היה יודע חכמה עליונה יותר ממלאכים העליונים, והיה מסתכל בכל וידע והכיר אדונו יותר מכל שאר בני העולם. אחר שחטא, נסתמו ממנו מעינות החכמה. מה כתוב, וישלחהו ה' אלקים מגן עדן לעבוד את האדמה."],[7,"ר' אבא אמר וכו':","רא\"א, אדם הראשון יצא מזכר ונקבה, דהיינו זו\"ן, ז\"ש ויאמר אלקים נעשה אדם בצלמנו כדמותנו, וע\"כ, גם אדם נעשו זכר ונקבה ביחד, ואח\"כ נפרדו זה מזה. ואם תאמר, הרי אמר, האדמה אשר לקח משם. ולא מזו\"ן העליונים. ומשיב כן הוא ודאי. שנלקח מן האדמה, וזו היא נוקבא דז\"א והקב\"ה, דהיינו ז\"א, נשתתף עמה. וזה זכר ונקבה שאמרנו. והכל הוא דבר אחד."],[8,"ר' יוסי אמר וכו':","רי\"א, עזי וזמרת יה, היינו אלו הכלולים זה בזה, ואינם נפרדים זה מזה, ולעולם הם באהבה, ברצון אחד, שהם או\"א הנקראים \u0003י\"ה.\u0004 שמשם נמצאים זרמי הנחלים והמעינות להספיק לכל, ולברך הכל, ואינם מכזבים מימי המעינות האלו. ז\"ש וכמוצא מים אשר לא יכזבו מימיו. ועל כן, \u0003ויהי לי לישועה,\u0004 שבשביל זה מושך המלך הקדוש ומנחיל למטה, והימין מתעורר לעשות נסים."],[9,"זה אלי ואנוהו:","זהו צדיק, דהיינו יסוד, שממנו יוצאים ברכות בזווג. \u0003ואנוהו,\u0004 באותו מקום שנמצא בו אהבה, וזה הוא בית המקדש. \u0003אלקי אבי וארוממנהו.\u0004 משה אמר זה אל המקום שהלוים באים מאותו הצד, דהיינו צד שמאל. וע\"כ כיון שמשה אמר על צד ההיא וארוממנהו, נמצא בו שלמות הכל. כי וארוממנהו פירושו, שמכליל אותו בצד ימין. שזהו כל השלמות."],[10,"ר' יצחק אמר וכו':","רי\"א, ויהי לי לישועה, זהו המלך הקדוש, שהוא ז\"א. וכך הוא. ומאין זה. מכתוב אחר מצאתי זה, שכתוב, כי עזי וזמרת יה הוי\"ה ויהי לי לישועה. משמע ממה שאומר, \u0003הויה\u0004 ויהי לי לישועה, שזהו המלך הקדוש הנקרא הויה. דהיינו ז\"א."]],[[0,"","הִכְנִיס אוֹתוֹ לְגַנּוֹ לְשָׁמְרוֹ, לִהְיוֹת לוֹ שִׂמְחָה עַל שִׂמְחָה וּלְהִשְׁתַּעֲשֵׁעַ בּוֹ. עָשָׂה לוֹ חֻפָּה מְכֻסָּה בַּאֲבָנִים יְקָרוֹת, וּמַלְאָכִים עֶלְיוֹנִים שְׂמֵחִים לְפָנָיו. אַחַר כָּךְ צִוָּה אוֹתוֹ עַל עֵץ אֶחָד, וְלֹא עָמַד בְּמִצְוַת רִבּוֹנוֹ."],[1,"","מָצָאנוּ בְּסִפְרוֹ שֶׁל חֲנוֹךְ, שֶׁלְּאַחַר שֶׁהֶעֱלָה אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְהֶרְאָה לוֹ אֶת כָּל גִּנְזֵי הַמֶּלֶךְ, עֶלְיוֹנִים וְתַחְתּוֹנִים, הֶרְאָה לוֹ אֶת עֵץ הַחַיִּים וְהָעֵץ שֶׁהִצְטַוָּה עָלָיו אָדָם, וְהֶרְאָה לוֹ מְקוֹמוֹ שֶׁל אָדָם בְּגַן עֵדֶן. וְרָאָה, שֶׁאִלְמָלֵא שָׁמַר אָדָם מִצְוָה זוֹ, יָכוֹל לַעֲמֹד תָּמִיד וְלִהְיוֹת שָׁם תָּמִיד. הוּא לֹא שָׁמַר מִצְוַת רִבּוֹנוֹ - יָצָא בְּדִימוֹס וְנֶעֱנַשׁ."],[2,"","רַבִּי יִצְחָק אָמַר, אָדָם נִבְרָא דּוּ-פַרְצוּפִים, וַהֲרֵי בֵּאַרְנוּ, (שם ב) וַיִּקַּח אַחַת מִצַּלְעֹתָיו - נִסְּרוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא וְנַעֲשׂוּ שְׁנַיִם, מִמִּזְרָח וּמִמַּעֲרָב. זֶהוּ שֶׁכָּתוּב (תהלים קלט) אָחוֹר וָקֶדֶם צַרְתָּנִי. אָחוֹר זֶה מַעֲרָב. וָקֶדֶם זֶה מִזְרָח."],[3,"","רַבִּי חִיָּיא אָמַר, מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? תִּקֵּן אוֹתָהּ נְקֵבָה, וְשִׁכְלֵל אֶת יָפְיָהּ עַל הַכֹּל, וְהִכְנִיסָהּ לָאָדָם. זֶהוּ שֶׁכָּתוּב וַיִּבֶן ה' אֱלֹהִים אֶת הַצֵּלָע אֲשֶׁר לָקַח מִן הָאָדָם לְאִשָּׁה. בּא רְאֵה מַה כָּתוּב לְמַעְלָה? וַיִּקַּח אַחַת מִצַּלְעֹתָיו. מַה זֶּה אַחַת? כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) אַחַת הִיא יוֹנָתִי תַמָּתִי אַחַת הִיא לְאִמָּהּ. מִצַּלְעֹתָיו - מִצְּדָדָיו, כְּמוֹ שֶׁנֶּאֱמַר (שמות כו) וּלְצֶלַע הַמִּשְׁכָּן."],[4,"","רַבִּי יְהוּדָה אָמַר, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן נְשָׁמָה עֶלְיוֹנָה בָּאָדָם, וְכָלַל בָּהּ חָכְמָה וְהַשְׂכֵּל כְּדֵי לָדַעַת הַכֹּל. מֵאֵיזֶה מָקוֹם נָתַן בּוֹ נְשָׁמָה? רַבִּי יִצְחָק אָמַר, מִמָּקוֹם שֶׁשְּׁאָר הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת בָּאוֹת."],[5,"","רַבִּי יְהוּדָה אָמַר, מִכָּאן, שֶׁכָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה. מִי זוֹ הָאָרֶץ? מֵאוֹתוֹ מָקוֹם שֶׁהַמִּקְדָּשׁ נִמְצָא בּוֹ. נֶפֶשׁ חַיָּה - נֶפֶשׁ חַיָּה סְתָם, זוֹ נֶפֶשׁ שֶׁל אָדָם הָרִאשׁוֹן שֶׁל הַכֹּל."],[6,"","רַבִּי חִיָּיא אָמַר, אָדָם הָיָה יוֹדֵעַ חָכְמָה עֶלְיוֹנָה יוֹתֵר מִמַּלְאֲכֵי הַשָּׁרֵת, וְהָיָה מִסְתַּכֵּל בַּכֹּל, וְיוֹדֵעַ וְנוֹדָע לְרִבּוֹנוֹ יוֹתֵר מִכָּל שְׁאָר בְּנֵי הָעוֹלָם. לְאַחַר שֶׁחָטָא נִסְתְּמוּ מִמֶּנּוּ מַעְיְנוֹת הַחָכְמָה. מַה כָּתוּב? (ממה שכתוב) (שם ג) וַיְשַׁלְּחֵהוּ ה' אֱלֹהִים מִגַּן עֵדֶן לַעֲבֹד אֶת הָאֲדָמָה."],[7,"","רַבִּי אַבָּא אָמַר, אָדָם הָרִאשׁוֹן מִזָּכָר וּנְקֵבָה נִמְצָא, זֶהוּ שֶׁכָּתוּב (שם א) וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. וְעַל זֶה זָכָר וּנְקֵבָה נַעֲשׂוּ כְּאֶחָד, וְנִפְרְדוּ אַחַר כָּךְ. וְאִם תֹּאמַר, זֶה שֶׁאָמַר הָאֲדָמָה אֲשֶׁר לֻקַּח מִשָּׁם - כָּךְ הוּא וַדַּאי, וְזוֹהִי הַנְּקֵבָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁתַּתֵּף עִמָּהּ, וְזֶהוּ זָכָר וּנְקֵבָה, וְהַכֹּל דָּבָר אֶחָד."],[8,"","רַבִּי יוֹסֵי אָמַר, עָזִּי וְזִמְרָת יָהּ, אוֹתָם הַכְּלוּלִים זֶה בָּזֶה וְלֹא נִפְרָדִים זֶה מִזֶּה, וּלְעוֹלָמִים הֵם בַּחֲבִיבוּת, בְּרָצוֹן אֶחָד, שֶׁמִּשָּׁם נִמְצָאוֹת (נמשכו) מְשִׁיכוֹת הַנְּחָלִים וְהַמַּעְיָנוֹת לְסַפֵּק לַכֹּל וּלְבָרֵךְ אֶת הַכֹּל, לֹא מְכַזְּבִים מֵימֵי הַמַּעְיָנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נה) וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו, וְעַל זֶה וַיְהִי לִי לִישׁוּעָה, שֶׁבִּשְׁבִיל כָּךְ הַמֶּלֶךְ הַקָּדוֹשׁ מוֹשֵׁךְ וּמוֹרִישׁ לְמַטָּה, וּמִתְעוֹרֵר הַיָּמִין לַעֲשׂוֹת נִסִּים."],[9,"","זְהִ אֵלִי וְאַנְוֵהוּ - זֶה צַדִּיק, שֶׁמִּמֶּנּוּ יוֹצְאוֹת בְּרָכוֹת בְּזִוּוּג. וְאַנְוֵהוּ - בְּאוֹתוֹ מָקוֹם שֶׁנִּמְצֵאת בּוֹ חֲבִיבוּת, וְזֶהוּ הַמִּקְדָּשׁ. אֱלֹהֵי אָבִי וַאֲרֹמֲמֶנְהוּ - מֹשֶׁה אָמַר אֶת זֶה לַמָּקוֹם שֶׁהַלְוִיִּם בָּאִים מֵאוֹתוֹ צַד, וְעַל זֶה (היה) שְׁלֵמוּת הַכֹּל הוּא בְּאוֹתוֹ מָקוֹם (בזה הפסוק)."],[10,"","רַבִּי יִצְחָק אָמַר, וַיְהִי לִי לִישׁוּעָה - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ, וְכָךְ הוּא. וּמִנַּיִן לָנוּ? מִקְרָא אַחֵר מָצָאנוּ לוֹ, שֶׁכָּתוּב כִּי עָזִּי וְזִמְרָת יָהּ ה' וַיְהִי לִי לִישׁוּעָה. מִמַּשְׁמָע שֶׁאָמַר ה' וַיְהִי לִי לִישׁוּעָה - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ."]]],[["(שמות ט״ו:ב׳) עָזִּי וְזִמְרָת יָהּ וְגוֹ', ר' חִזְקִיָּה פָּתַח וְאָמַר, בְּהַאי קְרָא דִּכְתִּיב, (משלי י״ז:י״ז) בְּכָל עֵת אוֹהֵב הָרֵעַ וְאָח לְצָרָה יִוָּלֵד. בְּכָל עֵת אוֹהֵב הָרֵעַ, דָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב בֵּיהּ (משלי כ״ז:י׳) רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב.","וְאָח לְצָרָה יִוָּלֵד, בְּשַׁעֲתָא דִּיעִיקוּן לָךְ שַׂנְאָךְ, קוּדְשָׁא בְּרִיךְ הוּא מַה אָמַר, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בְּךָ, דְּיִשְׂרָאֵל, אִקְרוּן אַחִים וְרֵעִים לְקוּדְשָׁא בְּרִיךְ הוּא. יִוָּלֵד מַהוּ, וְכִי הַשְׁתָּא יִוָּלֵד. אֶלָּא בְּשַׁעֲתָא דְּעַקְתָּא יִוָּלֵד בְּעָלְמָא, אָח יְהֵא לָקֳבְלָךְ, לְשֵׁזָבָא לָךְ מִכָּל אִינּוּן דְּעָקִין לָךְ.","רִבִּי יְהוּדָה אָמַר, יִוָּלֵד: דְּמַלְכָּא קַדִּישָׁא יִתְּעַר בְּהַאי עֹז, לְנַקְמָא לָךְ מֵאוּמִין, לְיַנְקָא לָךְ מֵאִימָא, בְּהַהוּא סִטְרָא, כְּמָה דְאַתְּ אָמֵר, עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה. לְאִתְּעָרָא גְּבוּרָאן לָקֳבֵל אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.","ר' יֵיסָא פָּתַח וְאָמַר, כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְרַחֲמָא, לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא לֵית לֵיהּ פּוּלְחָנָא לְקוּדְשָׁא בְּרִיךְ הוּא, (אלא) (כמה) רְחִימוּתָא. וְכָל מַאן דְּרָחִים לֵיהּ, וְעָבִיד פּוּלְחָנָא בִּרְחִימוּתָא, קָארֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא רְחִימָא. אִי הָכִי, בְּמָאי אוֹקִימְנָא הָנִי קְרָאֵי, רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב. וּכְתִיב (משלי כ״ה:י״ז) הוֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ.","אֶלָּא הָא אוּקְמוּהָ חַבְרַיָּיא, הַאי קְרָא (ס\"א בעולות ושלמים והאי בחטאות ואשמות וכתיב וכו') בְּעוֹלוֹת כְּתִיב. הַשְׁתָּא, רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב, לְמִפְלַח לֵיהּ, וּלְאִתְדַּבְּקָא בֵּיהּ, וּלְמֶעְבַּד פִּקּוּדוֹי. אַל תַּעֲזוֹב וַדַּאי. וְהָא דְּאִתְּמַר הוֹקַר רַגְלְךָ מִבֵּית רֵעֶךָ. כְּלוֹמַר הוֹקַר יִצְרְךָ, דְּלָא יִרְתַּח לָקֳבְלָךְ, וְלָא יִשְׁלוֹט בָּךְ, וְלַא תַּעֲבֵיד הִרְהוּרָא אַחֲרָא. מִבֵּית רֵעֶךָ, מַאן בֵּית רֵעֶךָ. דָּא נִשְׁמְתָא קַדִּישָׁא, דְּאָעִיל בָּהּ רֵעֶךָ וְיָהָבָהּ בְּגַוָּךְ.","וְעַל דָּא פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְרַחֲמָא לֵיהּ בְּכֹלָּא, כְּמָה דִּכְתִּיב, (דבהם ו) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ. זֶה אֵלִי וְאַנְוֵהוּ, דְּכָל יִשְׂרָאֵל חָמוּ עַל יַמָּא, מַה דְּלָא חָמָא יְחֶזְקֵאל נְבִיאָה, וַאֲפִילּוּ אִינּוּן עוּבָּרֵי דְּבִמְעֵי אִמְּהוֹן, הֲווֹ חָמָאן וּמְשַׁבְּחָן לְקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ הֲווֹ אַמְרִין זֶה אֵלִי וְאַנְוֵהוּ אֱלֹהֵי אָבִי וַאֲרוֹמְמֶנְהוּ, כְּמָה דְאַתְּ אָמֵר אֱלֹהֵי אַבְרָהָם.","אָמַר רִבִּי יוֹסֵי, אִי הָכִי אֲמַאי וַאֲרוֹמְמֶנְהוּ, דְּהָא אֱלֹהֵי אַבְרָהָם לְעֵילָּא הוּא. אָמַר לֵיהּ, אֲפִילּוּ הָכִי אִצְטְרִיךְ, וְכֹלָּא חַד מִלָּה, וַאֲרוֹמְמֶנְהוּ בְּכֹלָּא, לְאַכְלְלָא, מַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא רַבָּא, דְּהָא הוּא פֻּלְחָנָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא.","ר' יְהוּדָה הֲוָה יָתִיב קָמֵיהּ דְּר' שִׁמְעוֹן, וְהוּא קָארֵי, כְּתִיב (ישעיהו נ״ב:ח׳) קוֹל צוֹפַיִךְ נָשְׂאוּ קוֹל יַחְדָּיו יְרַנֵּנוּ. קוֹל צוֹפַיִךְ, מַאן אִינּוּן צוֹפַיִךְ. אֶלָּא אִלֵּין אִינּוּן דִּמְצָפָאן, אֵימָתַי יְרַחֵם קוּדְשָׁא בְּרִיךְ הוּא, לְמִבְנֵי בֵּיתֵיהּ. נָשְׂאוּ קוֹל, יִשְּׂאוּ קוֹל מִבָּעֵי לֵיהּ, מַאי נָשְׂאוּ קוֹל. אֶלָּא, כָּל בַּר נָשׁ דְּבָכֵי, וְאָרִים קַלֵיהּ עַל חָרְבַּן בֵּיתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, זָכֵי לְמָה דִּכְתִּיב לְבָתַר יַחְדָּיו יְרַנֵּנוּ. וְזָכֵי לְמֵחֱמֵי לֵיהּ בְּיִשּׁוּבָא בְּחֶדְוָותָא.","בְּשׁוּב יְיָ' צִיּוֹן, (אמר ליה) בְּשׁוּב יְיָ' אֶל צִיּוֹן מִבָּעֵי לֵיהּ, מַאי בְּשׁוּב יְיָ' צִיּוֹן אֶלָּא בְּשׁוּב יְיָ' צִיּוֹן וַדַּאי. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְחֲרִיב יְרוּשָׁלַ ם לְתַתָּא, וּכְנֶסֶת יִשְׂרָאֵל אִתְתְּרָכַת, סָלִיק מַלְכָּא קַדִּישָׁא לְצִיּוֹן, וְאַנְגִיד לֵיהּ לָקֳבְלֵיהּ, בְּגִין דִּכְנֶסֶת יִשְׂרָאֵל (ויקרא ע\"ה) אִתְתְּרָכַת. (השתא דאתגליא כנסת ישראל סליק ליה לגביה) (ויצא קס\"ב ע\"ב) וְכַד תִּתְהַדָּר כְּנֶסֶת יִשְׂרָאֵל לְאַתְרָהּ, כְּדֵין יֵתוּב מַלְכָּא קַדִּישָׁא לְצִיּוֹן לְאַתְרֵיהּ, לְאִזְדַּוְּוגָא חַד בְּחַד, וְדָא הוּא בְּשׁוּב יְיָ' צִיּוֹן. וּכְדֵין זְמִינִין יִשְׂרָאֵל לְמֵימָר, זֶה אֵלִי וְאַנְוִהוּ. וּכְתִיב, זֶה יְיָ' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ, בִּישׁוּעָתוֹ וַדַּאי.","(שמות ט״ו:ג׳) יְיָ' אִישׁ מִלְחָמָה יְיָ' שְׁמוֹ. רִבִּי אַבָּא פָּתַח (במדבר כ״א:י״ד) עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ' אֶת וָהֵב בְּסוּפָה וְאֶת הַנְּחָלִים אַרְנוֹן. כַּמָה אִית לָן לְאִסְתַּכְּלָא בְּפִתְגָּמֵי אוֹרַיְיתָא, כַּמָה אִית לָן לְעַיְּינָא בְּכָל מִלָּהָא, דְּלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, דְּלָא אִתְרְמִיזָא בִּשְׁמָא קַדִּישָׁא עִלָּאָה, וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, דְּלֵית בָּהּ כַּמָּה רָזִין, כַּמָּה טַעֲמִין, כַּמָּה שָׁרָשִׁין, כַּמָּה עֲנָפִין."],[[0,"עזי וזמרת יה וגו':","ר' חזקיה פתח ואמר במקרא הזה. בכל עת אוהב הרע ואח לצרה יולד. בכל עת אוהב הרע, זה הקב\"ה, שכתוב בו רעך ורע אביך אל תעזוב."],[1,"ואח לצרה יולד:","בשעה שיציקו לך שנאך, הקב\"ה מהו אומר, למען אחי ורעי אדברה נא שלום בך. וישראל נקראים אחים ורעים להקב\"ה. \u0003יולד\u0004 מהו, וכי עתה יולד בשעת הצרה. ומשיב. אלא בשעת הצרה יולד בעולם מי שיהיה לך לאח, להצילך מכל אלו המציקים לך."],[2,"ר' יהודה אמר וכו':","רי\"א, \u0003יולד,\u0004 פירושו, שהמלך הקדוש יתעורר בעז הזה, לנקום בעדך מן האומות, ולהניק אותך מאימא, שהיא בינה, בצד הזה, של השמאל. כמש\"א עזי וזמרת יה ויהי לי לישועה. לעורר גבורות כנגד האומות עכו\"ם."],[3,"ר' ייסא פתח וכו':","ר\"י פתח ואמר, כמה יש לאדם לאהוב את הקב\"ה, כי אין עבודה לפני הקב\"ה אלא אהבה. וכל מי שאוהב אותו ועושה עבודה באהבה, קורא אותו הקב\"ה אוהב. ומקשה, א\"כ איך אפשר להעמיד אלו הכתובים, כתוב, רעך ורע אביך אל תעזוב. וכתוב הוקר רגלך מבית רעך."],[4,"אלא הא אוקמוה וכו':","ומשיב. אלא כבר בארוה החברים שמקרא זה, רעך ורע אביך אל תעזוב, כתוב בעולות. אבל בחמאות ואשמות נאמר הוקר רגלך מבית רעך (עי' חגיגה ז' ע\"א) ועתה נבאר רעך ורע אביך אל תעזוב, אל תעזוב לעבוד אותו ולהדבק בו ולעשות מצותיו. אל תעזוב ודאי. ומה שנאמר, הוקר רגלך מבית רעך, כלומר, \u0003הוקר\u0004 יצרך, שלא ירתיח כנגדך, ולא ישלוט בך, ולא תעלה מחשבה זרה. \u0003מבית רעך,\u0004 מי הוא בית רעך, זהו הנשמה הקדושה שהכניס בך רעך ונתנה בתוכך."],[5,"ועל דא פולחנא וכו':","ועל כן עבודת הקב\"ה, היא לאהוב אותו בכל שיתנהג עמך, כמ\"ש, ואהבת את ה' אלקיך. זה אלי ואנוהו, שכל ישראל ראו על הים מה שלא ראה יחזקאל הנביא. ואפילו העוברים שבמעי אמם היו רואים ומשבחים להקב\"ה, וכולם היו אומרים, זה אלי ואנוהו אלקי אבי וארוממנהו. אלקי אבי, הוא כמש\"א אלקי אברהם."],[6,"א\"ר יוסי וכו':","אר\"י, אם כן למה כתוב, וארוממנהו. הרי אלקי אברהם הוא למעלה, ואין צורך לרומם אותו. כלומר, אלקי יצחק, שהוא קו שמאל, צריכים לרוממו ולא קו ימין. אמר לו, אפילו כן, צריכים לרוממו. והכל דבר אחד, וארוממנהו בכל הצדדים, לכלול גם מי שיודע ליחד את השם הקדוש הגדול, שגם הוא צריך לרומם אותו, כי זה הוא עבודה עליונה של הקב\"ה."],[7,"ר' יהודה הוה וכו':","ר\"י היה יושב לפני ר\"ש והוא קורא, כתוב, קול צופיך נשאו קול יחדיו ירננו. \u0003קול צופיך,\u0004 מי הם צופיך, ומשיב, אלא אלו הם המצפים מתי ירחם הקב\"ה לבנות ביתו. \u0003נשאו קול,\u0004 שואל, ישאו קול היה צריך לומר, מהו נשאו קול. ומשיב, אלא כל אדם הבוכה ומרים קולו על חורבן בית הקב\"ה, זוכה למה שכתוב אחר כך, \u0003יחדיו ירננו,\u0004 וזוכה לראותו בישוב בשמחה."],[8,"בשוב ה' ציון:","שואל, בשוב ה' אל ציון היה צריך לומר, מהו בשוב ה' ציון. ומשיב, בשוב ה' ציון ודאי. בוא וראה, בשעה שנחרבה ירושלים של מטה וכנסת ישראל, שהיא המלכות, הגלתה, עלה המלך הקדוש, שהוא ז\"א, לציון, שהוא יסוד דמלכות, ונאנח כנגדה, משום שכנסת ישראל הגלתה. וכשתחזור כנסת ישראל למקומה, אז ישוב המלך הקדוש לציון, למקומו, להזדווג אחד באחד. וזהו שכתוב, בשוב ה' ציון, ולא לציון, כי ה' ציון יורה על זווג ה' עם ציון. ואז עתידים ישראל לומר, זה אלי ואנוהו. וכתוב, זה ה' קוינו לו נגילה ונשמחה בישועתו. בישועתו ודאי, דהיינו בישועה של ה' שחזר לציון."],[9,"ה' איש מלחמה ה' שמו:","ר' אבא פתח. על כן יאמר בספר מלחמות ה' את והב בסופה, ואת הנחלים ארנון. כמה יש לנו להסתכל בדברי תורה, כמה יש לנו לעיין בכל דבר, שאין לך דבר בתורה, שאינו נרמז בשם הקדוש העליון. ואין לך דבר בתורה, שאין בו כמה סודות, כמה טעמים, כמה שרשים, כמה ענפים."]],[[0,"","עָזִּי וְזִמְרָת יָהּ וְגוֹ'. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, בְּפָסוּק זֶה שֶׁכָּתוּב (משלי יז) בְּכָל עֵת אֹהֵב הָרֵעַ וְאָח לְצָרָה יִוָּלֵד, בְּכָל עֵת אֹהֵב הָרֵעַ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בּוֹ רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזֹב."],[1,"","וְאָח לְצָרָה יִוָּלֵד - בְּשָׁעָה שֶׁיָּצִיקוּ לְךְ שׂוֹנְאֶיךְ, מָה אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא? (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ, שֶׁיִּשְׂרָאֵל נִקְרָאִים אַחִים וְרֵעִים לַקָבָּ\"ה. יִוָּלֵד מַה זֶּה? וְכִי עַכְשָׁו יִוָּלֵד? אֶלָּא בְּשָׁעָה שֶׁנּוֹלֶדֶת צָרָה בָּעוֹלָם, יִהְיֶה אָח כְּנֶגְדְּךְ לְהַצִּיל אוֹתְךְ מִכָּל אוֹתָם שֶׁמְּצִיקִים לְךְ."],[2,"","רַבִּי יְהוּדָה אָמַר, יִוָּלֵד - שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ יִתְעוֹרֵר בָּעֹז הַזֶּה לִנְקֹם לְךְ מֵהָאֻמּוֹת, לְהֵינִיק לְךְ מֵהָאֵם בְּאוֹתוֹ צַד, כְּמוֹ שֶׁנֶּאֱמַר עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה. לְעוֹרֵר גְּבוּרוֹת כְּנֶגֶד אֻמּוֹת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת."],[3,"","רַבִּי יֵיסָא פָּתַח וְאָמַר, כַּמָּה יֵשׁ לָאָדָם לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי אֵין לְךְ עֲבוֹדָה לַקָּדוֹשׁ- בָּרוּךְ-הוּא (אלא) (כמו) אֶלָּא אַהֲבָה, וְכָל מִי שֶׁאוֹהֵב אוֹתוֹ וְעוֹשֶׂה עֲבוֹדָתוֹ בְּאַהֲבָה, קוֹרֵא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא אָהוּב. אִם כָּךְ, בַּמֶּה בֵּאַרְנוּ פְסוּקִים אֵלּוּ - רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזֹב, וְכָתוּב (משלי כה) הֹקַר רַגְלְךְ מִבֵּית רֵעֶךְ?"],[4,"","אֶלָּא, הֲרֵי בֵּאֲרוּהָ הַחֲבֵרִים, פָּסוּק זֶה (בעולות ושלמים, וזה בחטאות ואשמות, וכתוב וכו') נִכְתָּב בְּעוֹלוֹת. עַכְשָׁו, רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזב, לַעֲבֹד אוֹתוֹ וּלְהִדָּבֵק בּוֹ וְלַעֲשׂוֹת מִצְווֹתָיו. אַל תַּעֲזֹב, וַדַּאי. וְזֶה שֶׁנֶּאֱמַר הֹקַר רַגְלְךְ מִבֵּית רֵעֶךְ. כְּלוֹמַר, הוֹקַר יִצְרְךְ שֶׁלֹּא יִרְתַּח כְּנֶגְדְּךְ וְלֹא יִשְׁלֹט בְּךְ, וְלֹא תַעֲשֶׂה הִרְהוּר אַחֵר. מִבֵּית רֵעֶךְ, מִי זֶה בֵּית רֵעֶךְ? זוֹ הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁהִכְנִיס בְּךְ רֵעֶךְ וְנָתַן אוֹתָהּ בְּתוֹכְךְ."],[5,"","וְעַל זֶה עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא - לֶאֱהֹב אוֹתוֹ בַּכֹּל, כְּמוֹ שֶׁכָּתוּב (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ. זֶה אֵלִי וְאַנְוֵהוּ - שֶׁכָּל יִשְׂרָאֵל רָאוּ עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא, וַאֲפִלּוּ אוֹתָם הָעֻבָּרִים שֶׁבִּמְעֵי אִמָּם הָיוּ רוֹאִים וּמְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכֻלָּם הָיוּ אוֹמְרִים זֶה אֵלִי וְאַנְוֵהוּ אֱלֹהֵי אָבִי וַאֲרֹמֲמֶנְהוּ, כְּמוֹ שֶׁנֶּאֱמַר אֱלֹהֵי אַבְרָהָם."],[6,"","אָמַר רַבִּי יוֹסֵי, אִם כָּךְ, לָמָּה וַאֲרֹמֲמֶנְהוּ, שֶׁהֲרֵי אֱלֹהֵי אַבְרָהָם הוּא לְמַעְלָה? אָמַר לוֹ, אֲפִלּוּ כָּךְ צָרִיךְ, וְהַכֹּל דָּבָר אֶחָד, וַאֲרֹמֲמֶנְהוּ בַּכֹּל, לְהַכְלִיל מִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ הַגָּדוֹל, שֶׁהֲרֵי זוֹהִי עֲבוֹדָה עֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","רַבִּי יְהוּדָה הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן, וְהוּא קוֹרֵא, כָּתוּב (ישעיה נב) קוֹל צֹפַיִךְ נָשְׂאוּ קוֹל יַחְדָּו יְרַנֵּנוּ. קוֹל צֹפַיִךְ, מִי הֵם צֹפַיִךְ? אֶלָּא אֵלֶּה הֵם שֶׁמְּצַפִּים מָתַי יְרַחֵם הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת אֶת בֵּיתוֹ. נָשְׂאוּ קוֹל? יִשְׂאוּ קוֹל הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה נָשְׂאוּ קוֹל? אֶלָּא כָּל אָדָם שֶׁבּוֹכֶה וּמֵרִים קוֹלוֹ עַל חֻרְבַּן בֵּיתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, זוֹכֶה לְמַה שֶּׁכָּתוּב אַחַר כָּךְ - יַחְדָּו יְרַנֵּנוּ, וְזוֹכֶה לִרְאוֹתוֹ מְיֻשָּׁב בְּחֶדְוָה."],[8,"","בְּשׁוּב ה' צִיּוֹן?! הָיָה צָרִיךְ לִהְיוֹת בְּשׁוּב ה' אֶל צִיּוֹן! מַה זֶּה בְּשׁוּב ה' צִיּוֹן? אֶלָּא בְּשׁוּב ה' צִיּוֹן וַדַּאי. בֹּא רְאֵה, בְּשָׁעָה שֶׁחָרְבָה יְרוּשָׁלַיִם לְמַטָּה וּכְנֶסֶת יִשְׂרָאֵל גֹּרְשָׁה, עָלָה הַמֶּלֶךְ הַקָּדוֹשׁ לְצִיּוֹן, וְנֶאֱנַח כְּנֶגְדּוֹ, מִשּׁוּם שֶׁכְּנֶסֶת יִשְׂרָאֵל גֹּרְשָׁה, (עתה שגתגלתה כנסת ישראל, מעלה אותה אליו) וּכְשֶׁתַּחֲזֹר כְּנֶסֶת יִשְׂרָאֵל לִמְקוֹמָהּ, אָז יָשׁוּב הַמֶּלֶךְ הַקָּדוֹשׁ לְצִיּוֹן לִמְקוֹמוֹ לְהִזְדַּוֵּג אֶחָד בְּאֶחָד, וְזֶהוּ בְּשׁוּב ה' צִיּוֹן. וְאָז עֲתִידִים יִשְׂרָאֵל לוֹמַר זֶה אֵלִי וְאַנְוֵהוּ, וְכָתוּב זֶה ה' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ, בִּישׁוּעָתוֹ וַדַּאי."],[9,"","ה' אִישׁ מִלְחָמָה ה' שְׁמוֹ. רַבִּי אַבָּא פָּתַח, (במדברכא) עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' אֶת וָהֵב בְּסוּפָה וְאֶת הַנְּחָלִים אַרְנוֹן. כַּמָּה יֵשׁ לָנוּ לְהִסְתַּכֵּל בְּדִבְרֵי הַתּוֹרָה, כַּמָּה יֵשׁ לָנוּ לְעַיֵּן בְּכָל דְּבָרֶיהָ, שֶׁאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁלֹּא נִרְמָז בַּשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ כַּמָּה סוֹדוֹת, כַּמָּה טְעָמִים, כַּמָּה שָׁרָשִׁים, כַּמָּה עֲנָפִים."]]],[["הָכָא אִית לְאִסְתַּכְּלָא, עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ', וְכִי סֵפֶר מִלְחֲמוֹת יְיָ', אָן הוּא. אֶלָּא הָכִי אִתְּעָרוּ חַבְרַיָּיא, כָּל מַאן דְּאַגָּח קְרָבָא בְּאוֹרַיְיתָא, זָכֵי לְאַסְגָּאָה שְׁלָמָא בְּסוֹף מִלּוֹי. כָּל קְרָבִין דְּעָלְמָא, קְטָטָה וְחֻרְבָּנָא. וְכָל קְרָבִין דְּאוֹרַיְיתָא, שְׁלָמָא וּרְחִימוּתָא, הֲדָא הוּא דִכְתִיב עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ' אֶת וָהֵב בְּסוּפָה, כְּלוֹמַר, אַהֲבָה בְּסוּפָה. דְּלֵית לָךְ אַהֲבָה וּשְׁלָמָא בַּר מֵהַאי.","תּוּ קַשְׁיָא בְּאַתְרֵיהּ. עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמוֹת יְיָ', בְּתוֹרַת מִלְחֲמוֹת יְיָ' מִבָּעֵי לֵיהּ, מַאי בְּסֵפֶר. אֶלָּא רָזָא עִלָּאָה הוּא, אֲתָר אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִקְרֵי סֵפֶר (נ\"א ומספר) כְּמָה דְאַתְּ אָמֵר, (ישעיה לה) דִּרְשׁוּ מֵעַל סֵפֶר יְיָ' וּקְרָאוּ. דְּכָל חֵילִין וּגְבוּרָן דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא, בְּהַהוּא סֵפֶר תַּלְיָין, (נ\"א ומתמן נפקין","את והב בסופה. מאן והב, אלא כל אינון חילין, וכל אינון גבוראן דעביד קודשא בריך הוא, בההוא ספר תליין.) וְכַד אַגָּח קוּדְשָׁא בְּרִיךְ הוּא קְרָבוֹי, בְּחַד אֲתָר דְּאִיהוּ בְּסוֹפָא דְּדַרְגִּין, וְאִקְרֵי וָהֵב. כְּמָה דְאַתְּ אָמֵר (משלי ל׳:ט״ו) לַעֲלוּקָה שְׁתֵּי בָּנוֹת הַב הַב. בְּסוּפָה: בְּסוֹף דַּרְגִּין אִשְׁתְּכַח. בְּסוּפָה: יָם סוֹף אִתְקְרֵי, יָם דְּאִיהוּ סוֹף לְכָל דַּרְגִּין.","וְאֶת הַנְּחָלִים אַרְנוֹן וְעִם נַחְלַיָיא דְּאִשְׁתָּכְחוּ וְאַתְנֶגִידוּ. לְגַבֵּיה, מֵהַהוּא אֲתָר עִלָּאָה, דְּאִקְרֵי אַרְנוֹן. מַאי אַרְנוֹן, זִוּוּגָא עִלָּאָה דַּחֲבִיבוּתָא, דְּלָא (נ' ע\"ב) מִתְפָּרְשָׁאן לְעָלְמִין, כְּמָה דְּאַתְּ אָמֵר (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. וּבְדָא, מִשְׁתָּרְשָׁן שָׁרָשׁוֹי, וְאִתְרְבִיאוּ עֲנָפָיו, לְאוֹשָטָא קְרָבוֹי בְּכָל אֲתָר, לְאוֹשָטָא חֵילִין וּגְבוּרָאן, וּלְאִתְחֲזָאָה שׁוּלְטָנָא רַבָּא וְיַקִּירָא דְּכֹלָּא.","תָּא חֲזֵי, כַּד מִתְעָרִין גְּבוּרָאן וּקְרָבִין דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּמָּה גַּרְדִּינֵי טְהִירִין, מִתְעָרִין לְכָל עִיבָר, כְּדֵין שַׁנְּנָן רוּמְחִין, וְסַיְיפִין, וּמִתְעָרִין גְּבוּרָאן, וְיַמָּא אִתְרְגִישַׁת וְגַלְגַּלּוֹי סַלְּקִין וְנַחְתִּין, וְאַרְבִין דְּאַזְלִין וְשָׁאטָן בְּיַמָּא, לְכָל עִיבָר מִסְתַּלְּקִין. שִׁנָּנָא קְרָבָא (נ\"א חרבא) בְּאַבְנִי בַּלִּסְטְרָאוֹת, מָארֵי דְּרוֹמְחִין וְסַיְיפִין, כְּדֵין (תהילים מ״ה:ו׳) חִצֶּיךָ שְׁנוּנִים (נ\"א מתערין לאושטא קרבין בכל אתר ולאושטא חילין וגבוראן לכל עיבר כדין ימא אתרגישת וגלגלוי סלקין וארבין דאזלין ושאטין נחתין וסלקין וזעפא אשתכח. כדין מתערין מגיחי קרבא באבני בלסטראין מארי דרומחין וסייפין גירין וקשתין כמה דאת אמר חציך שנונים) וְקוּדְשָׁא בְּרִיךְ הוּא אִתְתָּקִיף בְּחֵילוֹי, וּלְאִתְעֲרָא קְרָבָא. וַוי לְאִינוּן דְּמַלְכָּא קַדִּישָׁא יִתְעָר עָלַיְיהוּ קְרָבָא. כְּדֵין כְּתִיב, יְיָ' אִישׁ מִלְחָמָה.","וּמֵהָכָא, וּמֵאִינּוּן אַתְוָון, וּמֵהַאי קְרָא, נָפְקִין טוּרֵי קְרָבָא לְאִינוּן חַיָּיבַיָּא, לְאִילֵּין מָארֵי דְּבָבוּ דְּחָבוּ לְקוּדְשָׁא בְּרִיךְ הוּא. וְאַתְוָון אִתְגַּלְּיָין לְאִינוּן מָארֵי קְשׁוֹט, וְהָא אִתְפָּרְשָׁן מִלִּין וְהָא אִתְּמַר.","יְיָ' אִישׁ מִלְחָמָה יְיָ' שְׁמוֹ. כֵּיוָן דִּכְתִּיב יְיָ' אִישׁ מִלְחָמָה, לָא יְדַעְנָא דַּיְיָ' שְׁמוֹ. אֶלָּא, כְּמָה דִּכְתִּיב, (בראשית י״ט:כ״ד) וַיְיָ' הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ מֵאֵת יְיָ' מִן הַשָּׁמָיִם. וְכֹלָּא בְּהַאי סֵפֶר תַּלְיָין, כְּמָה דְאַתְּ אָמֵר (איוב כ׳:כ״ז) יְגַלּוּ שָׁמַיִם עֲוֹנוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. (ועל דא)","תָּא חֲזֵי, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר קְרָבָא בְּעָלְמָא, עִלָּאֵי וְתַתָּאֵי אִתְעַקְּרוּ מֵאַתְרַיְיהוּ, כְּמָה דְּאוֹקִימְנָא הֲדָא הוּא דִכְתִיב מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. וּלְזִמְנָא דְּאָתֵי, זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַגָּחָא קְרָבָא עִלָּאָה וְתַקִּיפָא בַּעֲמַמְיָא, בְּגִין לְאוֹקְרָא שְׁמֵיהּ, הֲדָא הוּא דִכְתִיב (זכריה י״ד:ג׳) וְיָצָא יְיָ' וְנִלְחַם בַּגּוֹיִם הָהֵם כַּיּוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב וּכְתִיב (יחזקאל ל״ח:כ״ג) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְנוֹדַעְתִּי וְגוֹ'. (מרכבות פרעה וחילו ירה בים. כד אתער קודשא בריך הוא קרבא כדין אתערו דרגין עלאין ודרגין תתאין דלתתא וכדין מרכבות פרעה וחילו ירה בים)","ר' יְהוּדָה פָּתַח וְאָמַר, (תהילים ע״ז:י״ז) רָאוּךָ מַּיִם אֱלֹהִים רָאוּךָ מַּיִם יָחִילוּ וְגוֹ', בְּשַׁעֲתָא דְּעָבְרוּ יִשְׂרָאֵל יַת יַמָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמַלְאָכָא דִּי מְמָנָא עַל יַמָּא, פָּלִיג מֵימָךְ. אֲמַר לֵיהּ לָמָּה. אֲמַר לֵיהּ בְּגִין דְּבָנַי יַעַבְרוּן בְּגַוָּוךְ. אָמַר לֵיהּ, פּוּרְקָנָא דְּקִיטְנָא קְשׁוֹט. מַאי שְׁנָא אִלֵּין מֵאִלֵּין.","אֲמַר לֵיהּ עַל תְּנַאי דָּא, עֲבָדִית לְיַמָּא כַּד בָּרָאתִי עָלְמָא. מַה עָבִיד קוּדְשָׁא בְּרִיךְ הוּא, אִתְּעַר גְּבוּרְתָּא דִּילֵיהּ, וְאִתְקְמָטוּ מַיָּא. הֲדָא הוּא דִכְתִיב רָאוּךָ מַּיִם אֱלהִים רָאוּךָ מַּיִם יָחִילוּ. אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, קְטוֹל כָּל אִינּוּן אֹכְלוֹסִין, לְבָתַר אַרְמִי לוֹן לְבַר. לְבָתַר חָפֵי יַמָּא עָלַיְיהוּ, הֲדָא הוּא דִכְתִיב מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם.","אָמַר רִבִּי אֶלְעָזָר, פּוּק חָמֵי כַּמָּה רְתִיכִין עָבֵד קוּדְשָׁא בְּרִיךְ הוּא לְעֵילָּא, כַּמָּה אֹכְלוֹסִין, כַּמָּה חַיָּילִין, וְכֻלְּהוּ קְשִׁירִין אִלֵּין בְּאִלֵּין. (והא אוליפנא) כֻּלְּהוּ רְתִיכִין אִלֵּין לְאִלֵּין, דַּרְגִּין עַל דַּרְגִּין, וּמִסִּטְרָא דִּשְׂמָאלָא מִתְעָרִין רְתִיכִין (נ\"א דלא) קַדִּישִׁין שַׁלִּיטִין. וְכֻלְּהוּ דַּרְגִּין יְדִיעָן לְעֵילָּא."],[[0,"הכא אית לאסתכלא וכו':","כאן יש להסתכל. שכתוב, על כן יאמר בספר מלחמות ה'. שואל, וכי ספר מלחמות ה' איפא הוא. ומשיב אלא כן העירו החברים. כל מי שעורך מלחמה בתורה, זוכה להרבות שלום בסוף דבריו. כל המלחמות שבעולם הם מריבות וחורבן, וכל המלחמות של תורה הם שלום ואהבה. ז\"ש, על כן יאמר בספר מלחמות ה'. דהיינו מלחמות של תורה. \u0003את והב בסופה,\u0004 כלומר, אהבה בסופה. שאין לך אהבה ושלום חוץ מזה."],[1,"תו קשיא באתריה וכו':","שוב הקושיא במקומה. שכתוב, ע\"כ יאמר בספר מלחמות ה', ואם סובב על מלחמות שבתורה, בתורת מלחמות ה' היה צריך לומר, מהו בספר. ומשיב, אלא סוד עליון הוא. מקום יש להקב\"ה, שנקרא ספר. שהוא מלכות. כש\"א, דרשו מעל ספר ה' וקראו. שכל הכחות וגבורות שעושה הקב\"ה, בספר ההוא תלוים ומשם יוצאים."],[2,"את והב בסופה:","שואל, מי הוא והב. ומשיב, אלא כל אלו הכחות וכל אלו הגבורות שעושה הקב\"ה, בספר ההוא תלוים, שהוא המלכות. וכשעורך הקב\"ה מלחמותיו, הוא במקום אחד שהוא סוף המדרגות, ונקרא \u0003והב.\u0004 כמש\"א, לעלוקה שתי בנות הב הב. שהם מקום העונשים שמתחת המלכות, \u0003בסופה,\u0004 פירושו בסוף המדרגות הוא נמצא. בסופה, ים סוף נקראת המלכות. דהיינו ים שהוא סוף לכל המדרגות."],[3,"ואת הנחלים ארנון:","פירושו, ועם הנחלים שנמצאו ונמשכו לו, אל המלכות, שה\"ס ואת והב בסופה, ממקום ההוא העליון, שנקרא \u0003ארנון.\u0004 מהו ארנון. הוא זווג עליון של אהבה, שאינו נפרד לעולם, שהם זווג או\"א עלאין, וכמו שאתה אומר, ונהר יוצא מעדן, שנהר היא בינה ועדן הוא חכמה, המכונים או\"א. כי ארנון, הוא אותיות אור נון, דהיינו האור של נון שערי בינה. ובזה משתרשים שרשיו ומתגדלים ענפיו, של המלכות, לעשות מלחמות בכל מקום, ולעשות כחות וגבורות. ולהראות ממשלה גדולה ויקרה מכל."],[4,"ת\"ח כד מתערין וכו':","בוא וראה, כשמתעוררים גבורות ומלחמות של הקב\"ה, כמה בעלי הדין מתעוררים לכל צד, אז רמחים ה\"ס דינים דצד ימין וחרבות שנונים הם דינים דצד שמאל, מעוררים גבורות, והים מתרגש, וגליו עולים ויורדים, והאניות ההולכות ושטות בים, מסתלקות לכל צד. המלחמה שנונה באבני בלסטראות, בעלי רומח וחרב, אז כתוב, חציך שנונים. והקב\"ה מתתקף בכחותיו לעורר מלחמה. אוי לאלו, שהמלך הקדוש מעורר עליהם מלחמה. אז כתוב, ה' איש מלחמה."],[5,"ומהכא ומאינון אתוון וכו':","ומכאן, מהפסוק, ה' איש מלחמה, ומאלו האותיות, ומכתוב הזה, יוצאים שורות בעלי מלחמה לאלו הרשעים לאלו השונאים שחטאו להקב\"ה. וסוד האותיות מתגלים לאלו בעלי האמת, והדברים מתבארים ומתפרשים, וכבר למדנו זה."],[6,"ה' איש מלחמה ה' שמו:","שואל, כיון שכתוב, ה' איש מלחמה איני יודע שה' שמו. ומשיב, אלא כמ\"ש, וה' המטיר על סדום וגו' מאת ה' מן השמים. אשר \u0003וה'\u0004 פירושו הויה ובית דינו, שהוא המלכות, וע\"כ כתוב אח\"כ מאת ה'. אף כאן, ה' איש מלחמה, היינו הויה. ה' שמו, היינו המלכות. כי הכל תלוי בספר הזה, שהוא המלכות. כמש\"א. יגלו שמים עונו, היינו ז\"א שנקרא שמים. וארץ מתקוממה לו, היינו המלכות שנקראת ארץ."],[7,"ת\"ח בשעתא דאתער וכו':","בוא וראה, בשעה שהקב\"ה מעורר מלחמה בעולם, העליונים והתחתונים, דהיינו האומות שלמטה, ושריהם שלמעלה, נעקרים ממקומם כמו שהעמדנו. ז\"ש, מרכבות פרעה וחילו ירה בים. ולעתיד לבא, עתיד הקב\"ה לעשות מלחמה גדולה וחזקה בעמים, כדי להוקיר את שמו. ז\"ש, ויצא ה' ונלחם וגו'. וכתוב, והתגדלתי והתקדשתי ונודעתי וגו'."],[8,"ר' יהודה פתח וכו':","רי\"פ ואמר, ראוך מים אלקים ראוך מים יחילו וגו'. בשעה שעברו ישראל את הים, אמר הקב\"ה למלאך הממונה על הים, חלוק את מימיך. אמר לו למה. אמר לו כדי שבני יעברו בתוכך. אמר לו, פריקת החשבון הוא אמת, פירוש, סליחת החטאים הוא אמת, כי הקב\"ה סולח ומוחל עונות, אבל מה ההפרש בין אלו לאלו, אם אתה מוחל לישראל, מחול ג\"כ למצרים. פורקנא, פירושו פריקה, מלשון ופרקת עולו (בראשית כ\"ז מ'). קינטא, פירושו חשבון, מלשון קונטא לא מחיק (ירושלמי ב\"ב י')."],[9,"א\"ל על תנאי וכו':","אמר לו הקב\"ה על תנאי הזה עשיתי את הים בשעה שבראתי את העולם. דהיינו על תנאי שיהיה נקרע בשביל ישראל. מה עשה הקב\"ה העיר את הגבורה שלו ונקמטו המים. ז\"ש ראוך מים אלקים ראוך מים יחילו. אמר לו הקב\"ה לשר של ים, הרוג כל אלו ההמונים ואחר כך תשליך אותם לחוץ. לאח\"כ כסה עליהם הים. ז\"ש, מרכבות פרעה וחילו ירה בים."],[10,"אמר ר' אלעזר וכו':","אר\"א, צא וראה, כמה מרכבות עשה הקב\"ה למעלה, כמה המונים, כמה צבאות, וכולם קשורים אלו באלו, כולם הם מרכבות אלו לאלו, שכל תחתון מרכבה לעליונו, הם מדרגות על מדרגות. ומצד שמאל נמשכות מרכבות שולטות שאינם קדושות. וכולם הם מדרגות ידועות למעלה."]],[[0,"","כָּאן יֵשׁ לְהִסְתַּכֵּל, עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' - וְכִי סֵפֶר מִלְחֲמוֹת ה' הֵיכָן הוּא? אֶלָּא כָּאן הִתְעוֹרְרוּ הַחֲבֵרִים, שֶׁכָּל מִי שֶׁעוֹרֵךְ קְרָב בַּתּוֹרָה, זוֹכֶה לְהַרְבּוֹת שָׁלוֹם בְּסוֹף דְּבָרָיו. כָּל הַקְּרָבוֹת שֶׁבָּעוֹלָם - קְטָטָה וְחֻרְבָּן, וְכָל הַקְּרָבוֹת שֶׁל הַתּוֹרָה - שָׁלוֹם וְאַהֲבָה. זֶהוּ שֶׁכָּתוּב עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' וְאֶת וָהֵב בְּסוּפָה, כְּלוֹמַר, אַהֲבָה בְּסוֹפָהּ. שֶׁאֵין לְךְ אַהֲבָה וְשָׁלוֹם פְּרָט לָזֶה."],[1,"","עוֹד קָשֶׁה בִּמְקוֹמוֹ. עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה' - בְּתוֹרַת מִלְחֲמוֹת ה' הָיָה צָרִיךְ לִהְיוֹת! מַהוּ בְּסֵפֶר? אֶלָּא סוֹד עֶלְיוֹן הוּא. מָקוֹם יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁנִּקְרָא סֵפֶר (ומספר), כְּמוֹ שֶׁנֶּאֱמַר דִּרְשׁוּ מֵעַל סֵפֶר ה' וּקְרָאוּ. שֶׁכָּל הַכֹּחוֹת וְהַגְּבוּרוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, תְּלוּיִים בְּאוֹתוֹ סֵפֶר, (ומשם יוצאים."],[2,"","את והב בסופה ובו) וּכְשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵךְ אֶת קְרָבוֹתָיו, בְּמָקוֹם אֶחָד שֶׁהוּא בְּסוֹף הַדְּרָגוֹת, וְנִקְרָא וָהֵב, כְּמוֹ שֶׁנֶּאֱמַר (משליל) לַעֲלוּקָה שְׁתֵי בָנוֹת הַב הַב. בְּסוּפָה - נִמְצָא בְּסוֹף הַדְּרָגוֹת. בְּסוּפָה - נִקְרֵאת יַם סוּף, יָם שֶׁהוּא סוֹף הַדְּרָגוֹת."],[3,"","וְאֶת הַנְּחָלִים אַרְנוֹן, וְעִם הַנְּחָלִים שֶׁנִּמְצְאוּ וְנִמְשְׁכוּ לוֹ מֵאוֹתוֹ מָקוֹם עֶלְיוֹן שֶׁנִּקְרָא אַרְנוֹן. (מהו ארנון, ') זִוּוּג עֶלְיוֹן שֶׁל חֲבִיבוּת, שֶׁלֹּא נִפְרָדִים לְעוֹלָמִים, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן. וּבָזֶה נִשְׁרָשִׁים שָׁרָשָׁיו וּמִתְרַבִּים עֲנָפָיו, לְהוֹשִׁיט קְרָבוֹתָיו בְּכָל מָקוֹם, לְהוֹשִׁיט כֹּחוֹת וּגְבוּרוֹת, וּלְהַרְאוֹת שִׁלְטוֹן גָּדוֹל וְנִכְבָּד שֶׁל הַכֹּל."],[4,"","בֹּא רְאֵה, כְּשֶׁמִּתְעוֹרְרוֹת הַגְּבוּרוֹת וְהַקְּרָבוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כַּמָּה בַּעֲלֵי דִין מִתְעוֹרְרִים לְכָל עֵבֶר, וְאָז רְמָחִים שְׁנוּנִים וַחֲרָבוֹת, וּמְעוֹרְרִים גְּבוּרוֹת, וְהַיָּם מִתְרַגֵּשׁ, וְגַלָּיו עוֹלִים וְיוֹרְדִים, וְהָאֳנִיּוֹת שֶׁהוֹלְכוֹת וְשָׁטוֹת בַּיָּם, מִסְתַּלְּקוֹת לְכָל עֵבֶר. קְרָב (חרב) שָׁנוּן בְּאַבְנֵי בַּלִּסְטְרָאוֹת, בַּעֲלֵי רְמָחִים וַחֲרָבוֹת. אָז (תהלים מא) חִצֶּיךְ שְׁנוּנִים (מתעוררים להושיט קרבות בכל מקום ולהושיט כחות וגבורות לכל עבר, ואז הים מתרגש וגליו עולים, והאניות שהולכות ושטות יורדות ועולות, והזעף נמצא. ואז מתעוררים עורכי הקרב באבני בליסטראות, בעלי רמחים וחרבות, חצים וקשתות, כמו שגאמר חציך שנונים), וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְחַזֵּק בְּכֹחוֹ וּלְעוֹרֵר קְרָב. אוֹי לְאוֹתָם שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ יְעוֹרֵר עֲלֵיֶם קְרָב. אָז כָּתוּב ה' אִישׁ מִלְחָמָה."],[5,"","וּמִכָּאן, וּמֵאוֹתָן אוֹתִיּוֹת, וּמִפָּסוּק זֶה, יוֹצְאִים הָרֵי קְרָבוֹת לְאוֹתָם רְשָׁעִים, לְאוֹתָם בַּעֲלֵי מְרִיבָה שֶׁחָטְאוּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהָאוֹתִיּוֹת מִתְגַּלּוֹת לְאוֹתָם בַּעֲלֵי אֱמֶת, וַהֲרֵי הַדְּבָרִים הִתְפָּרְשׁוּ וַהֲרֵי נִתְבָּאֵר."],[6,"","ה' אִישׁ מִלְחָמָה ה' שְׁמוֹ. כֵּיוָן שֶׁכָּתוּב ה' אִישׁ מִלְחָמָה, לֹא יָדַעְנוּ שֶׁה' שְׁמוֹ? אֶלָּא, כְּמוֹ שֶׁכָּתוּב (בראשית יט) וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מִן הַשָּׁמָיִם. וְהַכֹּל תָּלוּי בַּסֵּפֶר הַזֶּה, כַּנֶּאֱמַר (איובב) יְגַלּוּ שָׁמַיִם עֲונוֹ וְאֶרֶץ מִתְקוֹמָמָה לוֹ. (ועל זה)."],[7,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר קְרָב בָּעוֹלָם, נֶעֱקָרִים מִמְּקוֹמָם עֶלְיוֹנִים וְתַחְתּוֹנִים, כְּמוֹ שֶׁבֵּאַרְנוּ, זֶהוּ שֶׁכָּתוּב מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. וְלֶעָתִיד לָבא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲרֹךְ קְרָב עֶלְיוֹן וְחָזָק בָּעַמִּים כְּדֵי לְכַבֵּד אֶת שְׁמוֹ. זֶהוּ שֶׁכָּתוּב (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב, וְכָתוּב (יחזקאל לח) וְהִתְגַּדִּלְתִּי וְהִתְקַדִּשְׁתִּי וְנוֹדַעְתִּי וְגוֹ'. (מרכבת פרעה וחילו ירה בים. כאשר יעורר הקדוש ברוך הוא קרב, אז יתעוררו דרגות עליונות ודרגות תחתונות שלמטה, ואז מרכבת פרעה וחילו ירה בים)."],[8,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים עז) רָאוּךְ מַּיִם אֱלֹהִים רָאוּךְ מַּיִם יָחִילוּ וְגוֹ'. בְּשָׁעָה שֶׁעָבְרוּ יִשְׂרָאֵל אֶת הַיָּם, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַמַּלְאָךְ הַמְמֻנֶּה עַל הַיָּם: חַלֵּק מֵימֶיךְ! אָמַר לוֹ: לָמָּה? אָמַר לוֹ: כְּדֵי שֶׁבָּנַי יַעַבְרוּ בְתוֹכְךְ. אָמַר לוֹ: מִדַּת הַגְּאֻלָּה הִיא אֱמֶת, אֲבָל מַה שּׁוֹנִים אֵלֶּה מֵאֵלֶּה?"],[9,"","עַל תְּנַאי זֶה עָשִׂיתִי אֶת הַיָּם כְּשֶׁבָּרָאתִי אֶת הָעוֹלָם. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? עוֹרֵר אֶת גְּבוּרָתוֹ וְנִקְמְטוּ הַמַּיִם. זֶהוּ שֶׁכָּתוּב רָאוּךְ מַּיִם אֱלֹהִים רָאוּךְ מַּיִם יָחִילוּ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: הֲרֹג אֶת כָּל הָאוּכְלוּסִים הַלָּלוּ, וְאַחַר כָּךְ זְרֹק אוֹתָם הַחוּצָה, אַחַר כָּךְ כַּסֵּה הַיָּם עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם."],[10,"","אָמַר רַבִּי אֶלְעָזָר, צֵא רְאֵה כַּמָּה מֶרְכָּבוֹת עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, כַּמָּה אוּכְלוּסִים, כַּמָּה חֲיָלוֹת, וְכֻלָּם קְשׁוּרִים אֵלּוּ בְּאֵלּוּ, (והרילמדנו) כָּל הַמֶּרְכָּבוֹת אֵלּוּ לְאֵלּוּ, דְּרָגוֹת עַל דְּרָגוֹת, וּמִצַּד הַשְּׂמֹאל מִתְעוֹרְרוֹת מֶרְכָּבוֹת (שלא) קְדוֹשׁוֹת שֶׁשּׁוֹלְטוֹת, וְכֻלָּן דְּרָגוֹת יְדוּעוֹת לְמַעְלָה."]]],[["וְהָא אִתְּעַרְנָא בִּבְכוֹר פַּרְעֹה, דְּהוּא דַּרְגָּא חַד, דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא (דרגא דיליה נ\"א חיליה) וְתָבַר לֵיהּ מְשׁוּלְשֶׁלֵיהּ תַּקִּיפָא, (ודרגא דיליה) תְּחוֹת שׁוּלְטָנֵיהּ, כַּמָּה רְתִיכִין וְכַמָּה חַיָּילִין דְּקוּזְמִיטִין מִסְּטָר שְׂמָאלָא, מִנְּהוֹן אֲחִידָן בַּאֲתָר עִלָּאָה דְּשׁוּלְטָנוּתָא דִּלְהוֹן, וּמִנְהוֹן אֲחִידָן בְּמַלְכוּתָא דִּלְעֵילָּא. מִנְּהוֹן אֲחִידָן בָּתַר אַרְבַּע כָּרְסֶוָון (ס\"א חיון), (נ\"א רחיין) כְּמָה דְּאִתְּמַר.","וְכֻלְּהוּ אִתְמְסָרוּ בִּידֵיהּ, בְּדִינָא דְּמַלְכוּתָא, דְּאִקְרֵי יַמָּא רַבָּא, לְתַבְרָא לוֹן מִדַּרְגֵּיהוֹן, וְכַד אִינּוּן אִתְּבָּרוּ לְעֵילָּא, כָּל אִינּוּן דִּלְתַתָּא אִתְּבָּרוּ, וְאִתְאֲבִידוּ בְּיַמָּא תַּתָּאָה. הֲדָא הוּא דִכְתִיב, מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. בַיָּם סְתָם.","וּמִבְחַר שָׁלִישָׁיו טֻבְּעוּ בְיַם סוּף. וּמִבְחַר שָׁלִישָׁיו, הָא אִתְּמַר, וְשָׁלִישִׁים עַל כֻּלּוֹ, כֻּלְּהוּ דַּרְגִּין תְּרֵין וְחָד. אִלֵּין עַל אִלֵּין. כְּגַוְונָא עִלָּאָה הָכִי אִתְעָבִידוּ. וְכֻלְּהוּ אִתְמְסָרוּ בִּידָהָא, לְאִתָּבְּרָא מִשּׁוּלְטָנִיהוֹן, אִלֵּין וְאִלֵּין.","תָּא חֲזֵי, הָא אִתְּמַר דְּכֻלְּהוּ עֶשֶׂר מָחָאן דְּעָבַד קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם, כֹּלָּא הֲוָה יְדָא חֲדָא, דִּשְׂמָאלָא אַכְלִיל בִּימִינָא. דְּעֶשֶׂר אֶצְבְּעָן כְּלִילָן דָּא בְּדָא, לָקֳבֵל עֶשֶׂר אֲמִירָן, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְקְרֵי בְּהוּ לְבָתַר. לָקֳבְלֵיהּ דְּכֹלָּא הַאי דְּיַמָּא, תַּקִּיף וְרַב וְשַׁלִּיטָא. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ח׳:כ״ג) וְהָאַחֲרוֹן הִכְבִּיד. הֲדָא הוּא דִכְתִיב מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם וְגוֹ'. וּלְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְקַטְּלָא אֹכְלוֹסִין וְקוּזְתוּרְנָטִין וְקוֹנְטְירִיסִין וְקָלַטְירוֹלְסִין דֶּאֱדוֹם הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה.","(שמות ט״ו:ד׳) מַרְכְּבוֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. רִבִּי יִצְחָק פָּתַח, (ירמיהו י׳:י״ג) לְקוֹל תִּתּוֹ הֲמוֹן מַיִם בַּשָּׁמַיִם וַיַעֲלֶה נְשִׂיאִים מִקְּצֵה הָאָרֶץ בְּרָקִים לַמָּטָר עָשָׂה וַיּוֹצֵא רוּחַ מֵאוֹצְרוֹתָיו. הָא תָּנִינָן, שִׁבְעָה רְקִיעִין עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, וּבְכָל רְקִיעָא וּרְקִיעָא כֹּכָבִין קְבִיעִין, וְרַהֲטִין בְּכָל רְקִיעָא וּרְקִיעָא, וּלְעֵילָּא מִכֻּלְּהוּ עֲרָבוֹת.","וְכָל רְקִיעָא וּרְקִיעָא בְּהִלּוּכוֹ מָאתַן שְׁנִין, וְרוּמֵיהּ חֲמֵשׁ מְאָה שְׁנִין. וּבֵין רְקִיעָא וּרְקִיעָא, חֲמֵשׁ מְאָה שְׁנִין. וְהַאי עֲרָבוֹת הִלּוּכוֹ בְּאוֹרְכֵיהּ, אֶלֶף וַחֲמֵשׁ מֵאָה שְׁנִין. וּפוּתְיֵהּ, אֶלֶף וַחֲמֵשׁ מֵאָה שְׁנִין, וּמִזִּיוָא דִּילֵיהּ, נָהֲרִין כָּל אִינּוּן רְקִיעִין.","וְהָא תָּנֵינָן, לְעֵילָּא מֵעֲרָבוֹת, רָקִיעַ דְּחַיּוֹת. פַּרְסוֹת דְּחַיּוֹת קַדִּישִׁין וְרוּמְהוֹן, כְּכֻלְּהוּ. לְעֵילָּא מִנְּהוֹן קַרְסוּלַיִן דְּחַיּוֹת כְּכֻלְּהוּ. שׁוֹקֵי הַחַיּוֹת, כְּכֻלְּהוּ. אַרְכּוּבִין דְּחַיּוֹת, כְּכֻלְּהוּ. יַרְכִין דְּחַיּוֹת, כְּכֻלְּהוּ. עַגְבֵי דְּחַיּוֹת, כְּכֻלְּהוּ. וְגוּפָא דְּחַיּוֹת כְּכֻלְּהוּ. גַּדְפַּיְיהוּ, כְּכֻלְּהוּ. וְצַוָּארַיְהוּ, כְּכֻלְּהוּ. רָאשֵׁי הַחַיּוֹת, כְּכֻלְּהוּ. מַאי כְּכֻלְּהוּ. כָּקֳבְלֵי כֻּלְּהוּ.","וְכַל שַׁיְיפָא וְשַׁיְיפָא דִּבְחַיּוֹת, לָקֳבֵל שִׁבְעָה תְּהוֹמִין, וְלָקֳבֵל שִׁבְעָה הֵיכָלִין וְלָקֳבֵל מֵאַרְעָא לִרְקִיעָא. וְלָקֳבֵל מֵרְקִיעָא לִרְקִיעָא, וְשִׁיעוּרָא דְּכֻלְּהוּ וְרוּמְהוֹן עֶשְׂרִין וַחֲמִשָּׁה אַלְפִין חוּלָקִין, מִשִּׁיעוּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא.","וְעוֹד רְקִיעָא חַד לְעֵילָּא, מִן קַרְנֵי הַחַיּוֹת, דִּכְתִּיב, (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ. מִלְּרַע כַּמָּה רְתִיכִין, בִּימִינָא וּשְׂמָאלָא.","מִתְּחוֹת יַמָּא שָׁרָאן כֻּלְּהוּ נוּנֵי יַמָּא, וְשָׁטָאן, אִתְכְּנָפוּ בְּזָוִיהוֹן אַרְבַּע, נַחְתִּין בְּדַרְגַּיְיהוּ, וְכֻלְּהוּ רְתִיכִין אִקְרוּן בִּשְׁמָהָן. מִתְּחוֹת אִלֵּין, אַזְלִין וְשָׁאטִין אִינּוּן זְעִירִין, דַּרְגִּין עַל דַּרְגִּין, דִּכְתִּיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. וְהָא אוֹקִימְנָא מִלֵּי.","מִסְּטָר שְׂמָאלָא תַּתָּאָה, קוּזְמִיטָא סִטְרָא אַחֲרָא וְאֲחִידָן מֵאִינּוּן דִּלְעֵילָּא, וְנַחְתּוּ לְאִתָּבְּרָא מֵחֵילָא תַּקִּיפָא קַדִּישָׁא. כְּמָה דְּאוֹקִימְנָא, מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ וְגוֹ'.","(שמות ט״ו:ו׳) יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ. אָמַר רַבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּצַפְרָא נָהִיר, וְאַיַּלְתָּא קַיְּימָא בְּקִיּוּמָהּ, אִתְעַבְּרַת בְּסִטְרָהָא, וְעָאלַת בְּמָאתָן הֵיכָלִין דְּמַלְכָּא. בַּר נָשׁ דְּאִשְׁתַּדַּל בְּפַלְגוּת לֵילְיָא בְּאוֹרַיְיתָא, בְּשַׁעֲתָא דְּאִתְּעַר רוּחָא דְּצָפוֹן, (ס\"א ותיאובתא דאילתא) וְכַאִיבַת אַיַּלָתָּא לְאִתְּעָרָא בְּעָלְמָא, אָתֵי עִמָּהּ לְקַיְּימָא קֹדֶם מַלְכָּא, בְּשַׁעֲתָא דְּנָהִיר צַפְרָא (ס\"א וההוא בר נש צלי צלותיה וליחד שמיה קדישא כדקא יאות) מַשְׁכִין עָלֵיהּ חַד חוּטָא דְּחֶסֶד. (ק\"ל ע\"ב)"],[[0,"והא אתערנא בבכור וכו':","והרי הערנו בבכור פרעה שהוא מדרגה אחת, שהרגה הקב\"ה ושברה מן השלשלת שלה החזקה. תחת ממשלתה, כמה מרכבות וכמה צבאות של גבורים מצד שמאל. מהם אחוזים במקום עליון של ממשלתם, ומהם אחוזים במלכות שלמעלה, מהם אחוזים תחת ארבע החיות. כמו שלמדנו."],[1,"וכלהו אתמסרו בידיה וכו':","וכולם נמסרו בידיה של דין המלכות, שנקרא ים הגדול, לשבור אותם ממדרגתם. וכשאלו נשברו מלמעלה, כל אלו שלמטה נשברו ונאבדו בים התחתון. ז\"ש, מרכבות פרעה וחילו ירה בים. בים סתם. שיורה הן על ים שלמעלה לשרים שלהם והן ים שלמטה למצרים התחתונים."],[2,"ומבחר שלישיו טבעו בים סוף:","ומבחר שלישיו כבר נתבאר. \u0003ושלישים על כולו,\u0004 כל המדרגות היו שתים ואחת מלמעלה, אלו על אלו, כעין של מעלה כך נעשו. וכולם נמסרו בידיה של המלכות, לשברם מממשלתם אלו ואלו. העליונים והתחתונים."],[3,"ת\"ח הא אתמר וכו':","בוא וראה, הרי למדנו, שכל עשר המכות שעשה הקב\"ה במצרים, הכל היה יד אחד, כי יד השמאל היתה כלולה בימין, ועשר אצבעות היו כלולות זו בזו, כנגד עשרה מאמרות, שהקב\"ה נקרא בהם אחר כך. וכנגד כולם היה זה של הים חזק וגדול ושליט. כמש\"א והאחרון הכביד. ז\"ש מרכבות פרעה וחילו ירה בים וגו'. ולעתיד לבא עתיד הקב\"ה להרוג המונים וקוזתורנתין וקונטיריסין וקלטירולסין, היינו שמות של שרים ומושלים של אדום. זה שאמר מי זה בא מאדום וגו'."],[4,"מרכבות פרעה וחילו וגו':","ר' יצחק פתח, לקול תתו המון מים וגו'. הרי למדנו, שבעה רקיעים, כנגד חג\"ת נהי\"מ, עשה הקב\"ה, ובכל רקיע ורקיע ככבים קבועים, דהיינו מדרגות מבחי', ושוב. וככבים רצים בכל רקיע ורקיע, דהיינו מדרגות מבחינת, רצוא, ולמעלה מכולם ערבות, שהוא הג\"ר של הרקיעים."],[5,"וכל רקיעא ורקיעא וכו':","וכל רקיע ורקיע בהלוכו הוא מאתים שנה, ורומו חמש מאות שנים. בין רקיע לרקיע חמש מאות שנים. וערבות הזה, הלוכו באורך, אלף וחמש מאות שנים. וברחב אלף וחמש שנים. ומהזיו שלו מאירים כל אלו הרקיעים."],[5,"","פירוש. הרקיעים כולם הם בחי' גוף, שהוא ו\"ק רוח נפש. וערבות, הוא הראש של גוף הזה, שיש בו ג\"ר. וההילוך ברקיע יורה על שיעור מדרגתו. והרום שבו יורה על שורשו. וע\"כ הרום של כל הרקיעים הם חמש מאות שנה, יורה על המשכם מחג\"ת נ\"ה דבינה, כי אמא עד הוד אתפשטותה ולא יותר. וכל ספירה שלה היא במספר מאה. וע\"כ הם חמש מאות שנה. וז\"ש ורומיה חמש מאות שנין. אבל הלוכו, דכל רקיע, שיורה על שיעור מדרגתו, הלא אין שם אלא ב' ספירות רוח נפש, שהם ב' מאות. וז\"ש, \u0003וכל רקיעא ורקיעא בהלוכו מאתן שנין.\u0004 אבל רקיע העליון ערבות, שיש בו ג\"ר, ונמשכים מאבא, שספירותיו בסוד אלפים. נמצא הלוכו ג' אלפים שנה. וז\"ש, \u0003והאי ערבות הלוכו באורכיה אלף ות\"ק שנין, ופותיה אלף ות\"ק שנין.\u0004"],[5,"","ומה שאומר, \u0003בין רקיעא ורקיעא חמש מאות שנין.\u0004 הוא, כי עצם הרקיע, הוא סוד סיום החדש דצמצום ב'. והוא בספירת סוד, שהוא הנושא למסך הזה (כמ\"ש באורך לעיל בראשית א' דף ס\"ח ד\"ה חמש רקיעין עש\"ה). וכיון שכל ספירה כלול מז\"ס ע\"כ יש בכל ספירה רקיע ביסוד שלה, עש\"ה, ולפיכך נמצא שבין רקיע לרקיע יש ה\"ס חג\"ת נ\"ה, כי אחר כל רקיע מתחיל ספירת החסד עד ההוד, וביסוד עומד רקיע האחר. ואלו ה\"ס הם ה' מאות שנה מצד הבינה. וז\"ש \u0003בין רקיעא לרקיעא חמש מאות שנה.\u0004"],[6,"והא תנינן, לעילא וכו':","והרי למדנו, למעלה מערבות הוא רקיע של החיות, שם ארבע חיות, אריה שור נשר ואדם. הפרסות של חיות הקדושות ורום שלהם, הוא ככולם שמתחתיהם, כי העליון כולל בתוכו כל התחתונים ממנו. למעלה מהם, קרסולים של החיות, והם ככולם שלמטה מהם. שוקים של החיות ככולם שלמטה. ארכובים של החיות ככולם שלמטה. ירכים של החיות ככולם שלמטה. עגבים של החיות ככולם שלמטה. וגופא דחיות ככולם שלמטה. הכנפים ככולם שלמטה. וצוארם ככולם שלמטה. ראשי החיות ככולם שלמטה. חושב כאן עשר בחינות כנגד עשר ספירות. שואל מהו ככולם. ומשיב, שחשובים כנגד כולם שלמטה מהם."],[7,"וכל שייפא ושייפא וכו':","וכל אבר ואבר מן החיות, הוא כנגד שבעה תהומות, שהם המסכים שבמלכיות. וכנגד שבעה היכלות, שה\"ס ז' מלכיות. וכנגד מארץ לרקיע, שהוא יסוד. וכנגד מרקיע לרקיע, שהם חג\"ת נ\"ה כנ\"ל. ושיעור כולם וגבהם, עשרים וחמשה אלף חלקים משיעור הקב\"ה. כמו שהעמדנו."],[7,"","פירוש. שכל בחינות שבבי\"ע הן בחינות מהחזה ולמטה דז\"א, כי בחינת הפרסא המסיימת האצילות, ה\"ס המלכות דז\"א שעמדה בצמצום א' בנקודה דעוה\"ז, ועלתה במקום חצי בינה דז\"א וסיימה שם האצילות. וחצי בינה התחתונה ותו\"מ דז\"א יצאו לחוץ מפרסא, ומהם נבנים כל הבחינות שבבי\"ע עד לגמר התקון, שגם הם יחזרו ויתחברו לז\"א ויהיו אצילות. וזהו אמרו \u0003ושיעורא דכלהו ורומהון,\u0004 שאע\"פ שאומר שכל שייפא ושייפא מן החיות כלול מז' ספירות דהיינו גם מחזה ולמעלה, אמנם שיעור כולם וגבהם בשיעור הקב\"ה שהוא ז\"א דאצילות אין בהם מבחינת מחזה ולמעלה כלום, אלא רק חצי ת\"ת ונו\"ה שלו שמחזה ולמטה, שהם \u0003עשרים וחמשה.\u0004 כי ספירות דז\"א הן כל אחת במספר עשרה. ולהיותם מתוקנים בסוד ארבע חיות, שמתגלה בהם החכמה, הם בבחינת \u0003אלפין,\u0004 שספירות החכמה במספר אלפין. והם עשרים וחמשה אלפין. וז\"ש, \u0003ושיעורא דכלהו ורומהון עשרין וחמשה אלפין חולקין משיעורא דקב\"ה.\u0004 שהוא ז\"א דאצילות. ואין בהם מבחינת מחזה ולמעלה דקב\"ה כלום."],[8,"ועוד רקיעא חד וכו':","ועוד יש רקיע אחד למעלה מן קרני החיות. שכתוב ודמות על ראשי החיות רקיע. מלמטה מאותו רקיע יש כמה מרכבות בימין ושמאל."],[9,"מתחות ימא שראן וכו':","מתחת הים, שהוא המלכות, שורים כל דגי הים ושטים מתאספים בארבע זויותיהם, שהם חו\"ג תו\"מ, ויורדים במדרגתם, דהיינו שמאירים ממעלה למטה, וכל המרכבות נקראים בשמותם. וכ\"ז הוא בחינת מחזה ולמעלה של הים, ששם סוד חיות גדולות. מתחת אלו, הולכים אלו הקטנים מדרגות על מדרגות. שהם בחינת מחזה ולמטה של הים הנקראים חיות קטנות, שכתוב, זה הים גדול ורחב ידים שם רמש ואין מספר חיות קטנות עם גדולות. והרי העמדנו הדברים."],[10,"מסטר שמאלא תתאה וכו':","מצד שמאל התחתון, נמצאים ממשלת צד האחר, כי זה לעומת זה עשה האלקים. וכנגד כל מה שיש בבי\"ע דקדושה יש בצד האחר, ואחוזים באלו שלמעלה, שיונקים מקדושה. ועתה בקריעת ים סוף, ירדו להשבר מכח החזק של הקדושה. כמו שהעמדנו, מרכבות פרעה וחילו וגו'."],[11,"ימינך ה' נאדרי בכח:","אמר ר' שמעון בשעה שהבקר מאיר, שה\"ס אור החסדים דז\"א, והאילה, שהיא המלכות, עומדת בקיומה. מתמלאת הצד שלה, כי השמאל, שהוא הצד שלה, מתלבש אז בחסדים, ומתמלאה הארתה. ונכנסת במאתים היכלות של המלך, שה\"ס קו ימין, שאין בו אלא כתר וחכמה, שכל אחד במס' מאה והם מאתיים. והמלכות אחר שנשלמה ונתמלאה, מקו שמאל, היא נכללת כולה בימין, שה\"ס ר' היכלות. אדם שעסק בחצות לילה בתורה, בשעה שנתעורר רוח הצפון, דהיינו השמאל, וחשקה של אילה הזו להתעורר בעולם, להשפיע, הוא בא עמה לעמוד לפני המלך. ובשעה שהאיר הבוקר מושכים עליו חוט של חסד."]],[[0,"","וַהֲרֵי בֵּאַרְנוּ בִּבְכוֹר פַּרְעֹה, שֶׁהוּא אַחַת הַדְּרָגוֹת שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא (דרגהשלו, נ\"אחילותיו) וְשָׁבַר אוֹתוֹ מִשַּׁלְשַׁלְתּוֹ הַחֲזָקָה, (ודרגתו) תַּחַת שִׁלְטוֹנוֹ כַּמָּה מֶרְכָּבוֹת וְכַמָּה חֲיָלוֹת שֶׁל גִּבּוֹרִים מִצַּד הַשְּׂמֹאל, מֵהֶם אֲחוּזִים בְּמָקוֹם עֶלְיוֹן שֶׁל הַשִּׁלְטוֹן שֶׁלָּהֶם, וּמֵהֶם אֲחוּזִים בַּמַּלְכוּת הָעֶלְיוֹנָה. מֵהֶם אֲחוּזִים אַחַר אַרְבָּעָה כִּסְאוֹת (החיות) (רחים), כְּמוֹ שֶׁנֶּאֱמַר."],[1,"","וְכֻלָּם נִמְסְרוּ בְיָדוֹ, בְּדִין הַמַּלְכוּת, שֶׁנִּקְרֵאת הַיָּם הַגָּדוֹל, לִשְׁבֹּר אוֹתָם מִדַּרְגָּתָם. וּכְשֶׁנִּשְׁבָּרִים לְמַעְלָה, כָּל אוֹתָם שֶׁלְּמַטָּה נִשְׁבָּרִים וְנֶאֱבָדִים בַּיָּם הַתַּחְתּוֹן. זֶהוּ שֶׁכָּתוּב מַרְכְּבת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. בַּיָּם סְתָם."],[2,"","וּמִבְחַר שָׁלִשָׁיו טֻבְּעוּ בְיַם סוּף. וּמִבְחַר שָׁלִשָׁיו, הֲרֵי נִתְבָּאֵר, וְשָׁלִשִׁם עַל כֻּלּוֹ. כָּל הַדְּרָגוֹת - שְׁנַיִם וְאֶחָד. אֵלֶּה עַל אֵלֶּה. כְּגוֹן עֶלְיוֹן כָּךְ נַעֲשׂוּ. וְכֻלָּם נִמְסְרוּ בְיָדֶיה לְהִשָּׁבֵר מִשִּׁלְטוֹנָם אֵלֶּה וָאֵלֶּה."],[3,"","בֹּא רְאֵה, הֲרֵי נֶאֱמַר שֶׁכָּל עֶשֶׂר הַמַּכּוֹת שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמִצְרַיִם, הַכֹּל הָיָה יָד אַחַת, שֶׁהַשְּׂמֹאל כְּלוּלָה בַּיָּמִין. שֶׁעֶשֶׂר הָאֶצְבָּעוֹת כְּלוּלוֹת זוֹ בָּזוֹ, כְּנֶגֶד עֶשֶׂר אֲמִירוֹת שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בָהֶם אַחַר כָּךְ. כְּנֶגְדּוֹ שֶׁל הַכֹּל זֶה שֶׁל הַיָּם חָזָק וְגָדוֹל וְשׁוֹלֵט, כְּמוֹ שֶׁנֶּאֱמַר וְהָאַחֲרוֹן הִכְבִּיד. זֶהוּ שֶׁכָּתוּב מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם וְגוֹ'. וְלֶעָתִיד לָבא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲרֹג אוּכְלוּסִים וְקוּזְתוּרְנָטִין וְקוֹנְטִירִיסִין וְקָלְטִירוֹלְסִין שֶׁל אֱדוֹם. זֶהוּ שֶׁכָּתוּב (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה."],[4,"","מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ יָרָה בַיָּם. רַבִּי יִצְחָק פָּתַח, (ירמיהי) לְקוֹל תִּתּוֹ הֲמוֹן מַיִם בַּשָּׁמַיִם וַיַּעֲלֶה נְשִׂאִים מִקְצֵה הָאָרֶץ בְּרָקִים לַמָּטָר עָשָׂה וַיּוֹצֵא רוּחַ מֵאֹצְרֹתָיו. הֲרֵי שָׁנִינוּ, שִׁבְעָה רְקִיעִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבְכָל רָקִיעַ וְרָקִיעַ כּוֹכָבִים קְבוּעִים שֶׁרָצִים בְּכָל רָקִיעַ וְרָקִיעַ, וּמֵעַל כֻּלָּם עֲרָבוֹת."],[5,"","וְכָל רָקִיעַ וְרָקִיעַ הִלּוּכוֹ מָאתַיִם שָׁנָה, וְרוּמוֹ חֲמֵשׁ מֵאוֹת שָׁנָה, וּבֵין רָקִיעַ לְרָקִיעַ חֲמֵשׁ מֵאוֹת שָׁנָה. וְהָעֲרָבוֹת הַזֶּה הִלּוּכוֹ בְּאָרְכּוֹ אֶלֶף וַחֲמֵשׁ מֵאוֹת שָׁנָה, וְרָחְבּוֹ אֶלֶף וַחֲמֵשׁ מֵאוֹת שָׁנָה, וּמִזִּיווֹ מְאִירִים כָּל אוֹתָם רְקִיעִים."],[6,"","וַהֲרֵי שָׁנִינוּ, מֵעַל לָעֲרָבוֹת רְקִיעַ הַחַיּוֹת. הַפְּרָסוֹת שֶׁל הַחַיּוֹת הַקְּדוֹשׁוֹת וְרוּמָם - כְּכֻלָּם. מֵעֲלֵיהֶם קַרְסֻלֵּי הַחַיּוֹת כְּכֻלָּם. שׁוֹקֵי הַחַיּוֹת כְּכֻלָּם. אַרְכֻּבֵּי הַחַיּוֹת כְּכֻלָּם. יַרְכֵי הַחַיּוֹת כְּכֻלָּם. עַגְבֵי הַחַיּוֹת כְּכֻלָּם. וְגוּף הַחַיּוֹת כְּכֻלָּם. כַּנְפֵיהֶם כְּכֻלָּם, וְהַצַּוָּאר שֶׁלָּהֶם כְּכֻלָּם. רָאשֵׁי הַחַיּוֹת כְּכֻלָּם. מַה זֶּה כְּמוֹ כֻלָּם? כְּנֶגֶד כֻּלָּם."],[7,"","וְכָל אֵיבָר וְאֵיבָר שֶׁבַּחַיּוֹת כְּנֶגֶד שִׁבְעָה תְהוֹמוֹת, וּכְנֶגֶד שִׁבְעָה הֵיכָלוֹת, וּכְנֶגֶד מִן הָאָרֶץ לָרָקִיעַ, וּכְנֶגֶד מֵרָקִיעַ לְרָקִיעַ, וְהַשִּׁעוּר שֶׁל כֻּלָּם וְרוּמָם עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף חֲלָקִים מִשִּׁעוּרוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁבֵּאַרְנוּ."],[8,"","וְעוֹד רָקִיעַ אֶחָד לְמַעְלָה מִן קַרְנֵי הַחַיּוֹת, שֶׁכָּתוּב (יחזקאל א) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ. מִלְּמַטָּה כַּמָּה מֶרְכָּבוֹת, בְּיָמִין וּבִשְׂמֹאל."],[9,"","מִתַּחַת לַיָּם שְׁרוּיִים כָּל דְּגֵי הַיָּם וְשָׁטִים, מִתְכַּנְּסִים בְּאַרְבַּע בְּזִיוָם, יוֹרְדִים בְּדַרְגוֹתֵיהֶם, וְכָל הַמֶּרְכָּבוֹת נִקְרָאוֹת בְּשֵׁמוֹת. מִתַּחַת אֵלֶּה הוֹלְכִים וְשָׁטִים אוֹתָם קְטַנִּים, דְּרָגוֹת עַל דְּרָגוֹת, שֶׁכָּתוּב (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם שָׁם רֶמֶשׂ וְאֵין מִסְפָּר חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת. וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים."],[10,"","מִצַד שְׂמֹאל הַתַּחְתּוֹן מֶמְשֶׁלֶת הַצַּד הָאַחֵר, וַאֲחוּזִים מֵאוֹתָם שֶׁלְּמַעְלָה, וְיָרְדוּ לְהִשָּׁבֵר מִכֹּחַ הֶחָזָק הַקָּדוֹשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ מַרְכְּבֹת פַּרְעֹה וְחֵילוֹ וְגוֹ'."],[11,"","יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ. אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁהַבֹּקֶר מֵאִיר וְהָאַיֶּלֶת עוֹמֶדֶת בִּמְקוֹמָהּ, מִתְעַבֶּרֶת בְּצִדָּהּ, וְנִכְנֶסֶת לְמָאתַיִם הֵיכָלוֹת שֶׁל הַמֶּלֶךְ. הָאָדָם שֶׁמִּשְׁתַּדֵּל בַּחֲצוֹת הַלַּיְלָה בַּתּוֹרָה, בְּשָׁעָה שֶׁמִּתְעוֹרֶרֶת רוּחַ צָפוֹן (ותשוקת האילת) וְכוֹאֶבֶת הָאַיֶּלֶת לְהִתְעוֹרֵר בָּעוֹלָם, בָּא עִמָּהּ לַעֲמֹד לִפְנֵי הַמֶּלֶךְ, בְּשָׁעָה שֶׁמֵּאִיר הַבֹּקֶר (ואותו אדם מתפלל תפלתו וליחד השם הקדוש כראוי) מוֹשְׁכִים עָלָיו חוּט שֶׁל חֶסֶד."]]],[["מִסְתַּכֵּל בִּרְקִיעָא, שַׁרְיָא עָלֵיהּ נְהִירוּ דְּסָכְלְתָנוּ דְּדַעְתָּא קַדִּישָׁא, וּמִתְעַטֵּר בֵּיהּ בַּר נָשׁ, וְדָחֲלִין מִנֵּיהּ כֹּלָּא. כְּדֵין הַאי בַּר נָשׁ אִקְרֵי בְּרָא לְקוּדְשָׁא בְּרִיךְ הוּא, בַּר הֵיכָלָא דְּמַלְכָּא. עָאל בְּכָל תַּרְעוֹי, לֵית דְּיִמְחֵי בִּידֵיהּ.","בְּשַׁעֲתָא דְּקָרֵי לְהֵיכָלָא דְּמַלְכָּא, עָלֵיהּ כְּתִיב, (תהילים קמ״ה:י״ח) קָרוֹב יְיָ' לְכָל קוֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאוּהוּ בֶאֱמֶת. מַאי בֶאֱמֶת. כְּמָה דְּאוֹקִימְנָא, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב, דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא בִּצְלוֹתֵיהּ (נ\"א בעלמא) כְּדְקָא יֵאוֹת. וְדָא פּוּלְחָנָא דְּמַלְכָּא (נ\"א דשמא) קַדִּישָׁא.","וּמַאן דְּיָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, אוֹקִים אוּמָא יְחִידָא בְּעָלְמָא, דִּכְתִּיב, (שמואל ב ז׳:כ״ג) וּמִי כְעַמְּךָ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. וְעַל דָּא אוֹקִימְנָא, כָּל כֹּהֵן דְּלָא יָדַע לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, לָאו פּוּלְחָנִיהּ פּוּלְחָנָא. דְּהָא כֹּלָּא בֵּיהּ תַּלְיָא, פּוּלְחָנָא עִלָּאָה, וּפוּלְחָנָא תַּתָּאָה. וּבָעֵי לְכַוְּונָא לִבָּא וּרְעוּתָא, בְּגִין דְּיִתְבָּרְכוּן עִלָּאֵי וְתַתָּאֵי.","כְּתִיב (ישעיהו א׳:י״ב) כִּי תָבֹאוּ לֵרָאוֹת פָּנָי. כָּל בַּר נָשׁ דְּאָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא, וְלָא אִתְכַּוָון בֵּיהּ בְּלִבָּא וּרְעוּתָא וּדְחִילוּ, בְּגִין דְּיִתְבָּרְכוּן בֵּיהּ עִלָּאֵי וְתַתָּאֵי, רָמָאן לֵיהּ צְלוֹתֵיהּ לְבַר, וְכֹלָּא מַכְרִיזֵי עָלֵיהּ לְבִישׁ. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי עָלֵיהּ כִּי תָבֹאוּ לֵרָאוֹת פָּנָי.","כִּי תָבוֹאוּ לִרְאוֹת מִבָּעֵי לֵיהּ, מַאי לֵרָאוֹת פָּנָי. אֶלָּא כָּל אִינּוּן אַנְפִּין דְּמַלְכָּא, טְמִירִין בְּעִמְקָא (נ\"א באתר) לְבָתַר חֲשׁוֹכָא (ס\"א ישת חשך סתרו וכל וכו') וְכָל אִינּוּן דְּיַדְעִין לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת מִתְבַקְעִין כָּל אִינּוּן כּוֹתָלֵי חֲשׁוֹכָא, וְאַנְפִּין דְּמַלְכָּא אִתְחַזְיָין, וְנָהֲרִין לְכֹלָּא. וְכַד אִינּוּן אִתְחַזְיָין וְנָהֲרִין, מִתְבָּרְכִין כֹּלָּא עִלָּאִין וְתַתָּאִין. כְּדֵין בִּרְכָּאן אִשְׁתְּכָחוּ בְּכֻלְּהוּ עָלְמִין, וּכְדֵין כְּתִיב לֵרָאוֹת פָּנָי.","מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם, מַאי קָא מַיְירֵי. אֶלָּא מַאן דְּאָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא עִלָּאָה, בָּעֵי לְיַחֲדָא מִסִּטְרָא דְּזֹאת. כְּמָה דִּכְתִּיב, (ויקרא ט״ז:ג׳) בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. בְּגִין דְּיִזְדַּוְּוגֻן כַּחֲדָא, אִינּוּן תְּרֵין: צַדִּיק וְצֶדֶק, בְּזִוּוּגָא חֲדָא. בְּגִין דְּיִתְבָּרְכוּן כֹּלָּא מִנַּיְיהוּ וְאִלֵּין אִקְרוּן חֲצֵרֶךָ, כְּמָה דִּכְתִּיב, (תהילים ס״ה:ה׳) אֲשְׁרֵי תִּבְחַר וּתְקָרֵב יִשְׁכֹּן חֲצֵרֶךָ.","וְאִי אִיהוּ אָתֵי לְיַחֲדָא שְׁמָא קַדִּישָׁא, וְלָא יִתְכַּוָּון בֵּיהּ בִּרְעוּתָא דְּלִבָּא, בִּדְחִילוּ וּרְחִימוּ. קוּדְשָׁא בְּרִיךְ הוּא אָמַר, מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם רְמוֹס חֲצֵרָי. זֹאת וַדַּאי, דְּהָא לא אִשְׁתְּכַח בְּהוּ בִּרְכָּאן. וְלָא דַּי דְּלָא אִשְׁתְּכָחוּ בְּהוּ בִּרְכָּאן, אֶלָּא דְּשַׁרְיָא בְּהוּ דִּינָא וְאִשְׁתְּכַח דִּינָא בְּכֹלָּא.","תָּא חֲזֵי, יְמִינָא דְּקוּדְשָׁא בְּרִיךְ הוּא, מִנֵּיהּ מִתְעָרִין כָּל נְהִירוּ, כָּל בִּרְכָּאן, וְכָל חִדוּ. בֵּיהּ כָּלִיל שְׂמָאלָא כְּמָה דְּאִית בְּבַר נָשׁ יְמִינָא וּשְׂמָאלָא, וּשְׂמָאלָא אִתְכְּלִיל בִּימִינָא, וִימִינָא הוּא כָּלִיל כֹּלָּא. וְכַד אִתְּעַר יְמִינָא שְׂמָאלָא אִתְּעַר עִמֵּיהּ, דְּהָא בֵּיהּ אָחִיד וְאִתְכְּלִיל.","וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּאָרִים בַּר נָשׁ יְדֵיהּ בִּצְלוֹתָא, מְכַוְּון בְּאֶצְבְּעָן דִּילֵיהּ לְעֵילָּא. כְּמָה דִּכְתִּיב, (שמות י״ז:י״א) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. דְּהָא (פ\"ז ע\"א) בִּימִינָא תַּלְיָא כֹּלָּא. וּכְתִיב (ויקרא ט׳:כ״ב) וַיִשָּׂא אַהֲרֹן אֶת יָדָו, וּכְתִיב חָסֵר. וּכְדֵין אִתְכְּוַון לְבָרְכָה לְעֵילָּא.","וְקוּדְשָׁא בְּרִיךְ הוּא לָאו הָכִי, בְּשַׁעֲתָא דְּאָרִים יְמִינָא לְעֵילָּא, וַוי לְהוּ לְתַתָּאֵי, דְּהָא כָּל סִיַּיעְתָּא וְכָל בִּרְכָּאן אִסְתָּלִיקוּ מִנַּיְיהוּ. מְנָלָן. דִּכְתִּיב נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ. מַאי נָטִיתָ יְמִינְךָ. כְּתַרְגּוּמוֹ, אֲרִימַת יְמִינְךָ. מִיָּד תִּבְלָעֵמוֹ אָרֶץ. וְכַד יְמִינָא אִשְׁתְּכַח, שְׂמָאלָא אִשְׁתְּכַח עִמֵּיהּ, וּכְדֵין לָא שַׁלְטִין דִּינִין בְּעָלְמָא, מַאי טַעְמָא, בְּגִין דִּימִינָא אִשְׁתְּכַח עִמֵּיהּ. וְאִי יְמִינָא אִסְתַּלָּקַת, הָא שְׂמָאלָא אִזְדַּמְּנַת, כְּדֵין דִּינִין מִתְעָרִין בְּעָלְמָא, וְדִינָא שַׁרְיָא בְּכֹלָּא.","רַבִּי שִׁמְעוֹן כַּד הֲוָה מָטֵי לְהַאי קְרָא, הֲוָה בָּכֵי, דִּכְתִּיב, (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ. וְכִי אֶפְשָׁר דְּהֵשִׁיב אָחוֹר יְמִינוֹ. אֶלָּא בְּגִין דְּאַקְדִּים שְׂמָאלָא לְנַחְתָּא בְּעָלְמָא, וִימִינָא אִשְׁתַּאֲרַת בַּאֲתָר אַחֲרָא."],[[0,"מסתכל ברקיעא וכו':","מסתכל ברקיע, דהיינו שמקבל מרקיע, שהוא יסוד דז\"א, שורה עליו אור התבונה של דעת הקדוש, והאדם מתעטר בו, שמשיג ג\"ר. והכל מפחדים ממנו. אז נקרא אדם הזה בן להקב\"ה, בן היכל המלך שהיא המלכות, דהיינו בן לזו\"ן. נכנס בכל שעריו של המלך ואין מי שימחה בידו."],[1,"בשעתא דקרי להיכלא וכו':","בשעה שקורא אל היכל המלך, כתוב עליו, קרוב ה' לכל קוראיו לכל אשר יקראוהו באמת. מהו באמת. הוא כמו שהעמדנו הכתוב, תתן אמת ליעקב, שפירושו, שיודע ליחד את השם הקדוש בתפלתו כראוי. וזהו עבודת המלך הקדוש."],[2,"ומאן דידע ליחדא וכו':","ומי שיודע ליחד את השם הקדוש כראוי, מקים אומה יחידה בעולם. שכתוב, ומי כעמך ישראל גוי אחד בארץ. וע\"כ העמדנו, כל כהן שאינו יודע ליחד השם הקדוש כראוי, אין עבודתו עבודה. כי הכל תלוי בו בכהן, הן עבודה העליונה, שהיא יחוד השם, והן עבודה התחתונה של הקרבנות. והוא צריך לכוון לבו ורצונו כדי שיתברכו העליונים ותחתונים."],[3,"כתיב כי תבאו וגו':","כתוב, כי תבאו לראות פני. כי כל אדם שבא ליחד את השם הקדוש, ולא כיון בה בלב ורצון ויראה, כדי שיתברכו בו עליונים ותחתונים, משליכים תפלתו לחוץ. והכל מכריזים עליו רע. והקב\"ה קורא עליו כי תבאו לראות פני."],[4,"כי תבאו וכו':","שואל, כי תבאו לראות היה צריך לומר, מהו לראות פני. ומשיב, אלא כל אלו הפנים של המלך, דהיינו הארת חכמה, בסו\"ה חכמת אדם תאיר פניו, גנוזים בעומק אחר החושך, שה\"ס הדינים שבקו שמאל, וכל אלו היודעים ליחד את השם הקדוש כראוי, מתבקעים כל אלו כותלי החשך, ופני המלך נראים ומאירים לכל. וכשהם נראים ומאירים, מתברכים כולם העליונים והתחתונים אז נמצאות ברכות בכל העולמות, ואז כתוב, \u0003לראות פני.\u0004"],[5,"מי בקש זאת מידכם:","שואל, מה רוצה הכתוב לומר. ומשיב, אלא כל מי שבא ליחד את השם הקדוש העליון צריך ליחד מצד \u0003זאת\u0004 שהיא המלכות, כמ\"ש, ב \u0003זאת\u0004 יבא אהרן אל הקדש, כדי שיזדווגו יחד אלו השנים, צדיק שהוא יסוד, וצדק שהוא המלכות, בזווג אחד, כדי שהכל יתברכו מהם. ואלו השנים נקראים \u0003חצרך,\u0004 כמ\"ש, אשרי תבחר ותקרב ישכון חצרך."],[6,"ואי איהו אתי וכו':","ואם הוא בא ליחד השם הקדוש, ואינו מכוון ברצון הלב, ביראה ואהבה, הקב\"ה אמר, מי בקש \u0003זאת\u0004 מידכם רמוס חצרי, \u0003זאת\u0004 ודאי, כי לא נמצא ברכות, בצדיק וצדק הנקראים חצרי, ולא די שלא נמצא בהם ברכות, אלא ששורה בהם דין, ונמצא הכל בדין."],[7,"ת\"ח ימינא דקב\"ה וכו':","בוא וראה, הימין של הקב\"ה, שהוא החסד, מתעוררים ממנו, כל אור, כל ברכות, וכל שמחה. בו כלול השמאל. כמו שיש באדם ימין ושמאל, והשמאל נכלל בימין, והימין כולל הכל, וכשנתעורר הימין, השמאל מתעורר עמו, כי בו אחוז ונכלל."],[8,"ות\"ח בשעתא וכו':","ובוא וראה, בשעה שאדם מרים ידיו בתפלתו, מכוון באצבעותיו למעלה. כמ\"ש, והיה כאשר ירים משה ידו וגבר ישראל. כי בימין תלוי הכל. וכתוב, וישא אהרן את ידיו, וכתוב, ידו חסר \u0003י',\u0004 שיורה על יד אחת הימין, ואז נתכוון לברך למעלה."],[9,"וקב\"ה לאו הכי וכו':","והקב\"ה אינו כן. בשעה שהקב\"ה מרים ימינו למעלה, אוי להם לתחתונים, כי כל עזרה וכל ברכה נסתלקו מהם. מאין לנו זה, שכתוב, נטית ימינך תבלעמו ארץ. מהו נטית ימינך. הוא כתרגומו, ארימת ימינך. מיד תבלעמו ארץ. וכשנמצא הימין, נמצא עמו גם השמאל, ואם הימין מסתלק, מזדמן השמאל, ואז דינין מתעוררים בעולם, ודין שורה בכל."],[10,"ר\"ש כד הוה וכו':","ר' שמעון, כשהיה מגיע למקרא הזה, היה בוכה. שכתוב, השיב אחור ימינו. וכי אפשר שישיב אחור ימינו. ומשיב, אלא מחמת שהקדים השמאל לרדת בעולם נשאר הימין במקום אחר. דהיינו באחור."]],[[0,"","מִסְתַּכֵּל בָּרָקִיעַ, שׁוֹרֶה עָלָיו אוֹר הַהַשְׂכָּלָה שֶׁל דַּעַת הַקְּדוֹשָׁה, וּמִתְעַטֵּר בּוֹ הָאָדָם, וְכֻלָּם פּוֹחֲדִים מִמֶּנּוּ. אָז הָאָדָם הַזֶּה נִקְרָא בֵּן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, בֶּן הֵיכַל הַמֶּלֶךְ. נִכְנָס לְכָל שְׁעָרָיו, וְאֵין מוֹחֶה בְּיָדוֹ."],[1,"","בְּשָׁעָה שֶׁקּוֹרֵא לְהֵיכַל הַמֶּלֶךְ, כָּתוּב עָלָיו (תהלים קמה) קָרוֹב ה' לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת. מַה זֶּה בֶּאֱמֶת? כְּמוֹ שֶׁבֵּאַרְנוּ, (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב, שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ בִּתְפִלָּתוֹ (בעולם) כָּרָאוּי, וְזוֹ עֲבוֹדָתוֹ שֶׁל (השם) הַמֶּלֶךְ הַקָּדוֹשׁ."],[2,"","וּמִי שֶׁיּוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, מַעֲמִיד אֻמָּה יְחִידָה בָּעוֹלָם, שֶׁכָּתוּב (שמואל ב ז) וּמִי כְעַמְּךְ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ. וְעַל זֶה בֵּאַרְנוּ, כָּל כֹּהֵן שֶׁלֹּא יוֹדֵעַ לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, אֵין עֲבוֹדָתוֹ עֲבוֹדָה, שֶׁהֲרֵי הַכֹּל תָּלוּי בּוֹ, עֲבוֹדָה עֶלְיוֹנָה וַעֲבוֹדָה תַחְתּוֹנָה. וְצָרִיךְ לְכַוֵּן לֵב וְרָצוֹן כְּדֵי שֶׁיִּתְבָּרְכוּ עֶלְיםנִים וְתַחְתּוֹנִים."],[3,"","כָּתוּב (ישעיה א) כִּי תָבֹאוּ לֵרָאוֹת פָּנָי. כָּל אָדָם שֶׁבָּא לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְלֹא מִתְכַּוֵּן בּוֹ בַּלֵּב וְרָצוֹן וְיִרְאָה כְּדֵי שֶׁיִּתְבָּרְכוּ בוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, זוֹרְקִים אֶת תְּפִלָּתוֹ הַחוּצָה, וְכֻלָּם מַכְרִיזִים עָלָיו לְרַע. וְהַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא עָלָיו, כִּי תָבֹאוּ לֵרָאוֹת פָּנָי."],[4,"","כִּי תָבאוּ לִרְאוֹת הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה לֵרָאוֹת פָּנָי? אֶלָּא כָּל פְּנֵי הַמֶּלֶךְ הַלָּלוּ גְּנוּזִים בְּעֹמֶק (במקום) אַחַר הַחֲשֵׁכָה (ישתחשך סתרו וכל וכו'), וְכָל אוֹתָם שֶׁיּוֹדְעִים לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי מִתְבַּקְּעִים כָּל אוֹתָם כָּתְלֵי הַחֲשֵׁכָה, וּפְנֵי הַמֶּלֶךְ נִרְאִים וּמְאִירִים לַכֹּל. וּכְשֶׁהֵם נִרְאִים וּמְאִירִים, כָּל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים מִתְבָּרְכִים, וְאָז נִמְצָאוֹת בְּרָכוֹת בְּכָל הָעוֹלָמוֹת, וְאָז כָּתוּב לֵרָאוֹת פָּנָי."],[5,"","מִי בִקֵּשׁ זֹאת מִיֶּדְכֶם, מַה זֶּה אוֹמֵר? אֶלָּא מִי שֶׁבָּא לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, צָרִיךְ לְיַחֵד מִצַּד שֶׁל זאת, כְּמוֹ שֶׁכָּתוּב (ויקרא טז) בזאת יבא אהרן אל הקדש. כדי שיזדוגו כאחד אותם השנים, צדיק וצדק בזווג אחד, כדי שיתברכו הכל מהם, ואלה נקראים חצריך, ככתוב (תהלים סה) אשרי תבחר ותקרב ישכן חצריך."],[6,"","וְאִם הוּא בָּא לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, וְלֹא מִתְכַּוֵּן בּוֹ בִּרְצוֹן הַלֵּב, בְּיִרְאָה וְאַהֲבָה - הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, מִי בִקֵּשׁ זאת מִיֶּדְכֶם רְמֹס חֲצֵרָי. זֹאת וַדַּאי, שֶׁהֲרֵי לֹא נִמְצָא בָהֶם בְּרָכוֹת. וְלֹא דַי שֶׁלֹּא נִמְצָא בָהֶם בְּרָכוֹת, אֶלָּא שֶׁשָּׁרוּי בָהֶם הַדִּין וְנִמְצָא דִּין בַּכֹּל."],[7,"","בֹּא רְאֵה, מִימִינוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרְרִים כָּל הָאוֹרוֹת, כָּל הַבְּרָכוֹת וְכָל שִׂמְחָה. בּוֹ כָּלוּל הַשְּׂמֹאל, כְּמוֹ שֶׁיֵּשׁ בָּאָדָם יָמִין וּשְׂמֹאל, וְהַשְּׂמֹאל נִכְלָל בַּיָּמִין, וְהַיָּמִין כּוֹלֵל אֶת הַכֹּל. וּכְשֶׁמִּתְעוֹרֵר הַיָּמִין, מִתְעוֹרֵר עִמּוֹ הַשְּׂמֹאל, שֶׁהֲרֵי בּוֹ הוּא אָחוּז וְכָלוּל."],[8,"","וּבֹא רְאֵה, בְּשָׁעָה שֶׁאָדָם מֵרִים אֶת יָדָיו בַּתְּפִלָּה וּמְכַוֵּן בְּאֶצְבְּעוֹתָיו לְמַעְלָה, כַּכָּתוּב (שמות יז) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. שֶׁהֲרֵי בַּיָּמִין הַכֹּל תָּלוּי, וְכָתוּב (ויקראט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו, וְכָתוּב חָסֵר, וְאָז מִתְכַּוֵּן לְבָרֵךְ לְמַעְלָה."],[9,"","וְהַקָּדוֹשׁ בָּרוּךָ הוּא לֹא כָּךְ - בְּשָׁעָה שֶׁמֵּרִים יָמִין לְמַעְלָה, אוֹי לַתַּחְתּוֹנִים! שֶׁהֲרֵי כָּל הַסִּיּוּעַ, וְכָל הַבְּרָכוֹת מִסְתַּלְּקִים מֵהֶם. מִנַּיִן לָנוּ? שֶׁכָּתוּב נָטִיתָ יְמִינְךְ תִּבְלָעֵמוֹ אָרֶץ. מַה זֶּה נָטִיתָ יְמִינְךְ? כְּתַרְגּוּמוֹ, הֵרַמְתָּ יְמִינְךְ. מִיָּד תִּבְלָעֵמוֹ אָרֶץ. וּכְשֶׁיָּמִין נִמְצֵאת, הַשְּׂמֹאל נִמְצָא עִמּוֹ, וְאָז לֹא שׁוֹלְטִים הַדִּינִים בָּעוֹלָם. מָה הַטַּעַם? מִשּׁוּם שֶׁהַיָּמִין נִמְצָא עִמּוֹ, וְאִם הַיָּמִין מִסְתַּלֶּקֶת, הֲרֵי מִזְדַּמֶּנֶת הַשְּׂמֹאל, וְאָז מִתְעוֹרְרִים דִּינִים בָּעוֹלָם, וְהַדִּין שָׁרוּי בַּכֹּל."],[10,"","כְּשֶׁרַבִּי שִׁמְעוֹן הָיָה מַגִּיעַ לַפָּסוּק הַזֶּה, הָיָה בּוֹכֶה, שֶׁכָּתוּב (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ. וְכִי אֶפְשָׁר שֶׁהֵשִׁיב אָחוֹר יְמִינוֹ? אֶלָּא מִשּׁוּם שֶׁהִקְדִּים הַשְּׂמֹאל לָרֶדֶת לָעוֹלָם, וְהַיָּמִין נִשְׁאֲרָה בְּמָקוֹם אַחֵר."]]],[["אָמַר רַבִּי שִׁמְעוֹן, כְּתִיב (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבָד. וְהָא אוֹקִימְנָא מִלֵּי, הַצַּדִּיק נֶאֱבַד לָא כְּתִיב, אֶלָּא הַצַּדִּיק אָבָד. מִכָּל אִינּוּן אַנְפֵּי מַלְכָּא, לָא אִשְׁתְּכַח דְּאָבַד, אֶלָּא צַדִּיק. אָבַד בִּתְרֵי סִטְרֵי: חַד, דְּלָא שָׁרָאן בֵּיהּ בִּרְכָּאן, כַּד בְּקַדְמִיתָא. וְחַד, דְּאִתְרְחִיקַת מִנֵּיהּ בַּת זוּגֵיהּ דְּהִיא כְּנֶסֶת יִשְׂרָאֵל. אִשְׁתְּכַח, דְּצַדִּיק אָבַד יַתִּיר מִכֹּלָּא. וּלְזִמְנָא דְּאָתֵי כְּתִיב, (זכריה ט׳:ט׳) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלַ ם הִנֵּה מַלְכֵּךְ יָבֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. צַדִּיק וּמוֹשִׁיעַ לָא כְּתִיב, אֶלָּא צַדִּיק וְנוֹשָׁע הוּא. הוּא נוֹשָׁע וַדַּאי. וְהָא אִתְּמַר.","(שמות ט״ו:ו׳) יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ. מַאי נֶאְדָּרִי, נֶאְדָּר מִבָּעֵי לֵיהּ. אֶלָּא, בְּשַׁעֲתָא דִּשְׂמָאלָא אַתְיָא לְאִזְדַּוְּוגָא בִּימִינָא, כְּדֵין כְּתִיב נֶאְדָּרִי (ס\"א בכח, תרי, ולעולם וכו') תִּרְעַץ, וּלְעוֹלָם הָכִי הוּא בְּגִין דִּשְׂמָאלָא אִשְׁתְּכַח בִּימִינָא, וְאִתְכְּלִיל בֵּיהּ.","אָמַר רִבִּי שִׁמְעוֹן, כְּמָה דְּאוֹקִימְנָא הָכִי הוּא, דְּבַר נָשׁ אִשְׁתְּכַח דְּאִתְפְּלַג. מַאי טַעְמָא. בְּגִין לְקַבְּלָא עִמֵּיהּ בַּת זוּגֵיהּ, דְּיִתְעֲבִידוּ חַד גּוּפָא מַמָּשׁ. כַּד יְמִינְךָ, אִשְׁתְּכַח דְּאִתְפְּלַג. מַאי טַעְמָא. בְּגִין לְקַבְּלָא עִמֵּיהּ שְׂמָאלָא. וְהָכִי הוּא כֹּלָּא, חַד בְּחַד. וְעַל דָּא, בְּחַד מָחֵי וּמַסֵּי, הֲדָא הוּא דִכְתִיב יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.","תָּא חֲזֵי, שִׁירָתָא דָּא אִתְּמַר, עַל הַהוּא זִמְנָא, וְעַל זִמְנָא דְּאָתֵי, בְּיוֹמֵי דְּיִתְּעַר מַלְכָּא מְשִׁיחָא, דִּכְתִּיב, יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב, רָעַצְתְּ לָא כְּתִיב, אֶלָּא תִּרְעַץ. מַה כְּתִיב בְּקַדְמִיתָא, (איכה א׳:י״ג) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב, בְּהַהוּא זִמְנָא, הִיא תִּרְעַץ אוֹיֵב לְזִמְנָא דְּאָתֵי.","וְכֹלָּא הָכִי הוּא, תַּהֲרוֹס קָמֶיךָ, הָרַסְתָּ לָא כְּתִיב, אֶלָּא תַּהֲרוֹס. תְּשַׁלַּח חֲרוֹנְךָ יֹאכְלֵמוֹ כַּקַּשׁ, כֹּלָּא לְזִמְנָא דְּאָתֵי. יְמִינְךָ יְיָ' נֶאְדָּרִי בַּכֹּחַ, בְּזִמְנָא דָּא, בְּעָלְמָא דֵּין. יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב, בְּזִמְנָא דְּמַלְכָּא מְשִׁיחָא. וּבְרוֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ, לְבִיאַת גּוֹג וּמָגוֹג. תְּשַׁלַּח חֲרוֹנְךָ יֹאכְלֵמוֹ כַּקַּשׁ, לִתְחִיַּית הַמֵּתִים. דִּכְתִּיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְשֵׁינֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם.","בְּהַהוּא זִמְנָא, אָמַר רִבִּי שִׁמְעוֹן, זַכָּאִין אִינּוּן דְּיִשְׁתַּאֲרוּן בְּעָלְמָא, וּמַאן אִינּוּן. תָּא חֲזֵי, לָא יִשְׁתְּאַר מִבְּנִי עָלְמָא, בַּר אִינּוּן גְּזִירִין, דְּקַבִּילוּ אָת קַיָּימָא קַדִּישָׁא, וְעָאלוּ בְּקַיְּימָא קַדִּישָׁא, בְּאִינּוּן תְּרֵין חוּלָקִין, כְּמָה דְּאוֹקִימְנָא. וְהוּא נָטִיר לֵיהּ לְהַהוּא קַיָּים, וְלָא עַיְילֵיהּ בְּאֲתָר דְּלָא אִצְטְרִיךְ, אִלֵּין אִינּוּן דְּיִשְׁתַּאֲרוּן, וְיִכָּתְבוּן לְחַיֵּי עָלְמָא.","מְנָלָן. דִּכְתִּיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לְחַיִּים בִּיְרוּשָׁלַ ם. מַשְׁמַע הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם, דְּכָל מַאן דְּאִתְגְּזַר, בְּאִלֵּין תְּרֵין דַּרְגִּין עָאל. וְאִי נָטִיר לְהַהוּא קַיָּים כַּדְקָא חֲזֵי, וְיִזְדְּהַר בֵּיהּ, עָלֵיהּ כְּתִיב הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַ ם. אִלֵּין יִשְׁתַּאֲרוּן בְּהַהוּא זִמְנָא, וָבֹהוּ זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְחָדְתָּא עָלְמָא, וּלְמֵחדֵי בְּהוּ. עַל הַהוּא זִמְנָא כְּתִיב, (תהילים ק״ד:ל״א) יְהִי כְבוֹד יְיָ' לְעוֹלָם יִשְׂמַח יְיָ' בְּמַעֲשָׂיו.","ר' חִיָּיא הֲוָה אָזִיל לְגַבֵּי רִבִּי אֶלְעָזָר, אַשְׁכָּחֵיהּ, דְּהֲוָה יָתִיב לְגַבֵּיהּ דְּרִבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוּנְיָיא חָמוּי. עַד דְּזָקִיף רֵישֵׁיהּ, חָמָא לֵיהּ לְרִבִּי חִיָּיא, אָמַר, (ישעיהו י״ט:כ״ד-כ״ה) בַּיּוֹם הַהוּא יִהְיֶה יִשְׂרָאֵל שְׁלִישִׁיָּה לְמִצְרַיִם וּלְאַשּׁוּר בְּרָכָה בְּקֶרֶב הָאָרֶץ אֲשֶׁר בֵּרַכוֹ יְיָ' צְבָאוֹת לֵאמֹר בָּרוּךְ עַמִּי מִצְרַיִם וּמַעֲשֵׂה יָדַי אַשּׁוּר וְנַחֲלָתִי יִשְׂרָאֵל, וְכִי אַשּׁוּר וּמִצְרַיִם קְרִיבִין אִינּוּן לְקוּדְשָׁא בְּרִיךְ הוּא?","אֶלָּא, עַל גָּלוּתָא דְּיִסְקוּן מִמִּצְרַיִם וּמֵאַשּׁוּר אִתְּמַר, וְאִי אִתְּמַר עַל מִצְרַיִם וְעַל אַשּׁוּר, עַל אִינּוּן חֲסִידִין דִּלְהוֹן, דְּאַהַדְרוּ בְּתִיּוּבְתָּא, וְאִשְׁתַּאֲרוּן לְמִפְלַח לְיִשְׂרָאֵל וּלְמַלְכָּא מְשִׁיחָא, דִּכְתִּיב, (תהילים ע״ב:י״א) וְיִשְׁתַּחֲווּ לוֹ כָּל מְלָכִים. וּכְתִיב, (ישעיהו מ״ט:כ״ג) וְהָיוּ מְלָכִים אוֹמְנַיִךְ וְגוֹ'.","אֲמַר לֵיהּ, מַאי דִּכְתִּיב, (משלי ג׳:י״ז) דְּרָכֶיהּ דַּרְכֵי נֹעַם אֲמַר לֵיהּ כַּמָּה טִפְּשִׁין כו' בְּנֵי עָלְמָא, דְּלָא יַדְעִין וְלָא מַשְׁגִּיחִין בְּמִלּוֹי דְּאוֹרַיְיתָא, דְּהָא מִלִּין דְּאוֹרַיְיתָא (נ\"א כמה רזין עלאין אית בהו) אִינּוּן אָרְחָא לְמִזְכֵּי בְּהַהוּא נֹעַם יְיָ' דִּכְתִּיב דְּרָכֶיהּ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דַּרְכֵי נֹעַם וַדַּאי. מַאי נֹעַם. כְּמָה דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ', וְהָא אוּקְמוּהָ, בְּגִין (נ\"א כך) דְּאוֹרַיְיתָא, וְאָרְחוֹי, מֵהַהוּא נֹעַם אַתְיָין, וְאִינּוּן אָרְחִין פְּרִישָׁן בֵּיהּ, וְעַל דָּא דְּרָכֶיהּ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם.","אָמַר רִבִּי חִיָּיא, תָּנִינָן, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב אוֹרַיְיתָא לְיִשְׂרָאֵל, נָפַק נְהוֹרָא מֵהַהוּא נֹעַם, וְאִתְעַטָּר בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וּמֵהַהוּא נֹעַם אַבְהִיקוּ זִיוָון דְּכֻלְּהוּ עָלְמִין דְּכֻלְּהוּ רְקִיעִין, דְּכֻלְּהוּ כִּתְרִין. עַל הַהִיא שַׁעֲתָא כְּתִיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלמֹה וְגוֹ'."],[[0,"אר\"ש כתיב הצדיק וכו':","א\"ר שמעון, כתוב, הצדיק אבד, והעמדנו הדברים, הצדיק נאבד, לא כתוב, אלא הצדיק אבד. ומשיב, מכל אלו פני המלך לא נמצא שנאבד אלא צדיק, שהוא יסוד, אבד, בב' הצדדים, א' שאינו שורה בו ברכות כבתחילה. וא' שבת זוגו נתרחקה ממנו, שהיא כנסת ישראל, דהיינו המלכות, נמצא שהצדיק אבד יותר מכולם, ולעתיד לבא כתוב, גילי מאד וגו' הנה מלכך יבא לך צדיק ונושע הוא. צדיק ומושיע לא כתוב, אלא צדיק ונושע הוא, הוא נושע ודאי שחזרה אליו בת זוגו. וכבר למדנו."],[1,"ימינך ה' נאדרי בכח:","מהו נאדרי, נאדר היה צריך לומר. ומשיב, אלא בשעה שהשמאל בא להזדווג בימין אז כתוב נאדרי, תרעץ אויב. ולעולם כך הוא, שמזדווג בימין, משום שהשמאל נמצא בימין ונכלל בו."],[2,"אמר רבי שמעון וכו':","אר\"ש, כמו שהעמדנו כן הוא. שהרי האדם נמצא שנחלק, כלומר שהוא רק חצי גוף, וחציו הב' היא הנקבה. מהו הטעם, כדי שיקבל אחר כך את בת זוגו ויעשו גוף אחד ממש. כך \u0003ימינך,\u0004 נמצא שנחלק, שהוא רק חצי גוף, מהו הטעם. כדי שיקבל עמו השמאל. והכל כך הוא אחד באחד, ועל כן ביד אחד מכה ומרפא, וע\"כ כתוב ימינך ה' תרעץ אויב."],[2,"","פירוש. כי הימין נמשך מנקודת החולם, שפירושו שעלתה המלכות לבינה של המדרגה, ונשארו כו\"ח במדרגה ובינה ותו\"מ נפלו למדרגה התחתונה. ואלו כו\"ח שנשארו במדרגה ה\"ס נקודת החולם וה\"ס הימין, ואלו בינה ותו\"מ שנפלו מן המדרגה ה\"ס השמאל ונקודת השורק. הרי שהימין הוא רק חצי גוף, והשמאל הוא חציו האחר. (עי' לעיל ב\"א דף ט\"ו ד\"ה ההיא נקודה). וז\"ש, כך \u0003ימינך אשתכח דאתפלג\u0004 דהיינו בעת עלית המלכות לבינה, שכו\"ח שנשארו ה\"ס ימין ובינה ותו\"מ שנפלו ה\"ס שמאל. \u0003בגין לקבלא שמאלא,\u0004 כדי שיקבל אח\"כ השמאל ותשלם מדרגתו. וז\"ש \u0003והכי הוא כלא חד בחד,\u0004 שכל ענין הזווגים של אחד באחד, הם כך, שהיו תחילה ב' פלגי דגופא ואח\"כ מזדווגים."],[3,"ת\"ח שירתא דא וכו':","בוא וראה, שירה זו נאמר, על אותו הזמן ולעתיד לבא, בזמן שיתעורר מלך המשיח. שכתוב, ימינך ה' תרעץ אויב, רעצת, שהוא לשון עבר, לא כתוב, אלא תרעץ, שהוא לשון עתיד, הרי שהיא לעתיד לבא. מה כתוב בתחילה, בגלות, השיב אחור ימינו, מפני אויב, בזמן ההוא, לעתיד לבא, היא תרעץ אויב."],[4,"וכלא הכי הוא וכו':","והכל כך הוא, תהרוס קמיך. הרסת לא כתוב אלא תהרוס. וכן תשלח חרונך וגו'. הכל לעתיד לבא. ימינך ה' נאדרי בכח, הוא בזמן הזה בעולם הזה. ימינך ה' תרעץ אויב, הוא בזמן מלך המשיח. וברוב גאונך תהרוס קמיך, הוא לביאת גוג ומגוג. תשלח חרונך יאכלמו כקש, הוא לתחיית המתים. שכתוב, ורבים מישיני אדמת עפר יקוצו וגו'."],[5,"בההוא זמנא אמר וכו':","בזמן ההוא, אמר ר\"ש, אשריהם שישארו בעולם. ומי הם. בוא וראה, לא ישאר בעולם חוץ מאלו הנמולים, שקבלו אות ברית הקדוש, ובאו בברית הקדוש בב' החלקים, דהיינו מילה ופריעה, כמו שהעמדנו. והוא שומר לברית ההוא, ולא הכניסו במקום שלא צריך. אלו הם שישארו ויכתבו לחיי עולם."],[6,"מנלן, דכתיב וכו':","מאין לנו זה. הוא, כי כתוב והיה הנשאר בציון והנותר בירושלים קדוש יאמר לו וגו'. משמע מן הנשאר בציון והנותר בירושלים שכל מי שנמול נכנס באלו ב' המדרגות ציון וירושלים. ואם שומר לברית ההוא כראוי, ונזהר בו, עליו כתוב, הנשאר בציון והנותר בירושלים, אלו ישארו בזמן ההוא, ובהם עתיד הקב\"ה לחדש העולם ולשמוח בהם, על זמן ההוא כתוב, יהי כבוד ה' לעולם ישמח ה' במעשיו."],[7,"ר' חייא הוה וכו':","ר\"ח היה הולך לר' אלעזר, מצאו שהיה יושב אצל ר' יוסי בר\"ש בן לקוניא חמיו. בעוד שהיה מרים את ראשו, ראה את ר' חייא, אמר ביום ההוא יהיה ישראל שלישיה למצרים ולאשור וגו' ברוך עמי מצרים ומעשה ידי אשור ונחלתי ישראל. שואל, וכי אשור ומצרים קרובים הם להקב\"ה."],[8,"אלא על גלותא וכו':","ומשיב, אלא על בני הגלות שיעלו ממצרים ומאשור, נאמר. ואם נאמר על מצרים ועל אשור עצמם, הוא, על החסידים שבהם, שחזרו בתשובה, ונשארו לעבוד את ישראל ומלך המשיח. שכתוב, וישתחוו לו כל מלכים. וכתוב, והיו מלכים אומניך וגו'."],[9,"א\"ל מאי דכתיב וכו':","אמר לו, מהו שכתוב, דרכיה דרכי נעם. א\"ל, כמה טפשים הם בני העולם, שאינם יודעים ואינם משגיחים בדברי תורה, שהרי דברי תורה הם הדרך לזכות בנעם ה' ההוא, שכתוב, דרכיה דרכי נעם וכל נתיבותיה שלום. דרכי נעם ודאי. שואל, מהו נעם. ומשיב, הוא כמ\"ש, לחזות בנעם ה' שהיא בינה, והעמדנוהו משום שהתורה ודרכיה באים מנעם ההוא, והדרכים האלו מתפרשים בו. ועל זה, דרכיה דרכי נעם וכל נתיבותיה שלום."],[10,"א\"ר חייא תנינן וכו':","אר\"ח, למדנו, בשעה שהקב\"ה נתן התורה לישראל, יצא אור מנעם ההוא, שהוא בינה, ונעטר בו הקב\"ה, שהוא ז\"א. דהיינו שקבל ג\"ר ממנה, המכונים עטרה. ומנעם ההוא הבריק הזיו של כל העולמות, של כל הרקיעים, ושל כל הכתרים. על אותה שעה כתוב, צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו וגו', המלך שלמה הוא ז\"א, אמו היא בינה, עטרה, הוא ג\"ר."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (ישעיה נו) הַצַּדִּיק אָבָד. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, לֹא כָתוּב הַצַּדִּיק נֶאֱבַד, אֶלָּא הַצַּדִּיק אָבָד. מִכָּל אוֹתָם פְּנֵי הַמֶּלֶךְ לֹא נִמְצָא שֶׁאָבַד אֶלָּא צַדִּיק. אָבַד בִּשְׁנֵי צְדָדִים: אֶחָד - שֶׁלֹּא שׁוֹרוֹת בּוֹ בְּרָכוֹת כְּבַתְּחִלָּה, וְאֶחָד - שֶׁהִתְרַחֲקָה מִמֶּנּוּ בַּת זוּגוֹ שֶׁהִיא כְּנֶסֶת יִשְׂרָאֵל. נִמְצָא שֶׁהַצַּדִּיק אָבַד יוֹתֵר מִכֹּל, וְלֶעָתִיד לָבֹא כָּתוּב (זכריה ט) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלם הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. צַדִּיק וּמוֹשִׁיעַ לֹא כָתוּב, אֶלָּא צַדִּיק וְנוֹשָׁע הוּא. הוּא נוֹשָׁע וַדַּאי, וַהֲרֵי זֶה נִתְבָּאֵר."],[1,"","יְמִינְךָ ה' נֶאְדָּרִי בַּכֹּחַ. מַה זֶּה נֶאְדָּרִי? הָיָה צָרִיךְ לִהְיוֹת נֶאְדָּר! אֶלָּא בְּשָׁעָה שֶׁשְּׂמֹאל בָּא לְהִזְדַּוֵּג בַּיָּמִין, אָז כָּתוּב נֶאְדָּרִי, תִּרְעַץ, (בכח, שנים, ולעולם וכו') וּלְעוֹלָם זֶה כָּךְ, מִשּׁוּם שֶׁשְּׂמֹאל נִמְצָא בְּיָמִין וְנִכְלָל בּוֹ."],[2,"","אָמַר רַבִּי שִׁמְעוֹן, כְּמוֹ שֶׁבֵּאַרְנוּ - כָּךְ זֶה, שֶׁאָדָם נִמְצָא שֶׁנֶּחֱלַק. מָה הַטַּעַם? כְּדֵי לְקַבֵּל עִמּוֹ בַּת זוּגוֹ שֶׁיֵּעָשׂוּ גוּף אֶחָד מַמָּשׁ. כְּשֶׁיְּמִינְךְ, נִמְצָא שֶׁנֶּחֱלַק. מָה הַטַּעַם? כְּדֵי לְקַבֵּל עִמּוֹ שְׂמֹאל. וְכָךְ זֶה הַכֹּל, אֶחָד בְּאֶחָד. וְעַל זֶה בְּאֶחָד מַכֶּה וּמְרַפֵּא. זֶהוּ שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב."],[3,"","בֹּא רְאֵה, שִׁירָה זוֹ נֶאֶמְרָה עַל אוֹתוֹ זְמַן וְעַל הַזְּמַן שֶׁיָּבא לֶעָתִיד, בַּיָּמִים שֶׁיִּתְעוֹרֵר מֶלֶךְ הַמָּשִׁיחַ, שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. לֹא כָתַב רָעַצְתָּ, אֶלָּא תִּרְעַץ. מַה כָּתוּב בַּתְּחִלָּה? (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ מִפְּנֵי אוֹיֵב. בְּאוֹתוֹ זְמַן הִיא תִּרְעַץ אוֹיֵב לֶעָתִיד לָבֹא."],[4,"","וְהַכֹּל כָּךְ הוּא. תַּהֲרֹס קָמֶיךְ - לֹא כָתוּב הָרַסְתָּ, אֶלָּא תַּהֲרֹס. תְּשַׁלַּח חֲרֹנְךְ יֹאכְלֵמוֹ כַּקַּשׁ. הַכֹּל לֶעָתִיד לָבא. יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ - בַּזְּמַן הַזֶּה, בָּעוֹלָם הַזֶּה. יְמִינְךְ ה' תִּרְעַץ אוֹיֵב - בִּזְמַן מֶלֶךְ הַמָּשִׁיחַ. וּבְרֹב גְּאֹנְךְ תַּהֲרֹס קָמֶיךְ - לְבִיאַת גּוֹג וּמָגוֹג. תְּשַׁלַּח חֲרֹנְךְ יֹאכְלֵמוֹ כַּקַּשׁ - לִתְחִיַּת הַמֵּתִים, שֶׁכָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְאֵלֶּה לַחֲרָפוֹת וּלְדִרְאוֹן עוֹלָם."],[5,"","בְּאוֹתוֹ זְמַן, אָמַר רַבִּי שִׁמְעוֹן, אַשְׁרֵי אוֹתָם שֶׁיִּשָּׁאֲרוּ בָּעוֹלָם. וּמִי הֵם? בּא רְאֵה, לֹא יִשָּׁאֲרוּ בָּעוֹלָם רַק אוֹתָם מְהוּלִים, שֶׁקִּבְּלוּ אוֹת בְּרִית הַקָּדוֹשׁ, וְנִכְנְסוּ לַבְּרִית הַקָּדוֹשׁ בְּאוֹתָם שְׁנֵי חֲלָקִים, כְּמוֹ שֶׁבֵּאַרְנוּ, והוּא שׁוֹמֵר אֶת אוֹתוֹ הַבְּרִית וְלֹא מַכְנִיסוֹ לְמָקוֹם שֶׁלֹּא צָרִיךְ. אֵלֶּה הֵם יִשָּׁאֲרוּ וְיִכָּתְבוּ לְחַיֵּי עוֹלָם."],[6,"","מִנַּיִן לָנוּ? שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלם. מַשְׁמָע הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַם, שֶׁכָּל מִי שֶׁנִּמּוֹל, בִּשְׁתֵּי הַדְּרָגוֹת הַלָּלוּ נִכְנָס. וְאִם שׁוֹמֵר אוֹתוֹ בְּרִית כָּרָאוּי וְיִזָּהֵר בּוֹ, עָלָיו כָּתוּב הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם. אֵלּוּ יִשָּׁאֲרוּ לְאוֹתוֹ זְמַן, וּבָהֶם עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵּשׁ אֶת הָעוֹלָם וְלִשְׂמֹחַ בָּהֶם. עַל אוֹתוֹ זְמַן כָּתוּב, (תהלים קד) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו."],[7,"","רַבִּי חִיָּיא הָיָה הוֹלֵךְ לְרַבִּי אֶלְעָזָר. מְצָאוֹ שֶׁהָיָה יוֹשֵׁב אֵצֶל רַבִּי יוֹסֵי בְּרַבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא חָמִיו. עַד שֶׁהֵרִים רֹאשׁוֹ, רָאָה אֶת רַבִּי חִיָּיא. אָמַר, (ישעיה יט) בַּיּוֹם הַהוּא יִהְיֶה יִשְׂרָאֵל שְׁלִישִׁיָּה לְמִצְרַיִם וּלְאַשּׁוּר בְּרָכָה בְּקֶרֶב הָאָרֶץ אֲשֶׁר בֵּרְכוֹ ה' צְבָאוֹת לֵאמֹר בָּרוּךְ עַמִּי מִצְרַיִם וּמַעֲשֵׂה יָדַי אַשּׁוּר וְנַחֲלָתִי יִשְׂרָאֵל. (וכי אשור ומצרים הם קרובים לקדוש'ברוך' הוא,"],[8,"","אלא, על הגלות שתעלה ממצרים ומאשור זה נאמר. ואם נאמר על מצרים ועל אשור על אותם חסידים שלהם שחזרו בתשובה ונשארו לעבד את ישראל ואת מלך המשיח, שכתוב (תהלים עב) וישתחוו לו כל מלכים, וכתוב והיו מלכים אמניך וגו'."],[9,"","אמר לו, מה זה שכתוב דרכיה דרכי נעם? אמר לו, כמה טפשים) בְּנֵי הָעוֹלָם שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים בְּדִבְרֵי תוֹרָה, שֶׁהֲרֵי דִּבְרֵי תוֹרָה (כמה סודות עליוניםישבהם) הֵם דֶּרֶךְ לִזְכּוֹת בְּאוֹתוֹ נֹעַם ה', שֶׁכָּתוּב דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם. דַּרְכֵי נֹעַם וַדַּאי. מַה זֶּה נֹעַם? כְּמוֹ שֶׁכָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה', וַהֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם (כך) שֶׁהַתּוֹרָה וּדְרָכֶיהָ בָּאִים מֵאוֹתוֹ נֹעַם, וְאוֹתָן דְּרָכִים מְפֹרָשׁוֹת בָּהּ, וְעַל זֶה דְּרָכֶיהָ דַּרְכֵי נֹעַם וְכָל נְתִיבוֹתֶיהָ שָׁלוֹם."],[10,"","אָמַר רַבִּי חִיָּיא, שָׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן תּוֹרָה לְיִשְׂרָאֵל, יָצָא אוֹר מֵאוֹתוֹ נֹעַם, וְהִתְעַטֵּר בּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמֵאוֹתוֹ נֹעַם הִבְהִיקוּ זִיוָם שֶׁל כָּל הָעוֹלָמוֹת, שֶׁל כָּל הָרְקִיעִים, שֶׁל כָּל הַכְּתָרִים. עַל אוֹתָהּ שָׁעָה כָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ'."]]],[["וְהַהִיא שַׁעֲתָא דְּאִתְבְּנֵי מַקְדְּשָׁא, אִתְעַטָּר קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא עֲטָּרָה, וְיָתִיב בְּכֻרְסְיָיא דִּילֵיהּ, וְאִתְעַטָּר בַּעֲטְרוֹי. וּמֵהַהוּא זִמְנָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, לָא אִתְעַטָּר קוּדְשָׁא בְּרִיךְ הוּא בַּעֲטְרוֹי, וְהַהוּא נֹעַם אִתְטָמַּר וְאִתְגְּנִיז.","אָמַר רִבִּי אֶלְעָזָר, בְּשַׁעֲתָא דְּעָאל מֹשֶׁה בְּגוֹ עֲנָנָא, כְּמָה דִּכְתִּיב, (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, כְּבַר נָשׁ דְּהֲוָה אָזִיל בַּאֲתָר דְּרוּחָא. אִיעְרַע בֵּיהּ חַד (ויקרא ע\"ח ע\"ב) מַלְאָכָא רַבְרְבָא, וְתָאנָא, קְמוּאֵ\"ל שְׁמֵיהּ. וְהוּא מְמָנָא עַל תְּרֵיסָר אַלְפִין מְמָנָן שְׁלִיחָן. בָּעָא לְאִזְדַּוְּוגָא בֵּיהּ בְּמֹשֶׁה, פָּתַח מֹשֶׁה פּוּמֵיהּ, (בראשית ט\"ז ע\"א) בִּתְרֵיסַר אַתְוָון גְּלִיפָן דִּשְׁמָא קַדִּישָׁא דְּאוֹלִיף לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בַּסְּנֶה, וְאִתְרְחַק מִנֵּיהּ תְּרֵיסַר אַלְפִין פַּרְסִין, וַהֲוָה אָזַל מֹשֶׁה בַּעֲנָנָא, וְעֵינוֹי מְלַהֲטָן כְּגוּמְרִין דְּאֶשָּׁא.","עַד דְּאִיעֲרַע בֵּיהּ חַד מַלְאָכָא, רַבְרְבָא וְיַקִּירָא מִן קַדְמָאָה, וְתָאנָא הֲדַרְנִיאֵ\"ל שְׁמֵיהּ, וְהוּא עִלָּאָה עַל שְׁאַר מַלְאָכִין, אֶלֶף וְשִׁתִּין רִבּוֹא פַּרְסִין, וְקָלֵיהּ אָזִיל בְּמָאתָן אֶלֶף רְקִיעִין, דְּמִסְתַּחֲרָאן בְּאֶשָּׁא חִיוָּורָא. כֵּיוָן דְּחָמָא לֵיהּ מֹשֶׁה, לָא יָכִיל לְמַלְּלָא. בָּעָא לְמִשְׁדֵּי גַּרְמֵיהּ מִגּוֹ עֲנָנָא.","אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה, וְכִי אַנְתְּ הוּא דְּאַסְגִּית מִלִּין עִמִּי בַּסְּנֶה, דְּבָעִית לְמִנְדַּע רָזָא דִּשְׁמָא קַדִּישָׁא, וְלָא דָּחַלְתְּ. וְהַשְׁתָּא אַתְּ דָּחִיל מֵחָד מִשַּׁמָּשַׁי. כֵּיוָן דִּשְׁמַע מֹשֶׁה קַלֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, אִתְתַּקַּף. פָּתַח פּוּמֵיהּ, בְּע\"ב אַתְוָון דִּשְׁמָא עִלָּאָה, כֵּיוָן דִּשְׁמַע הֲדַרְנִי\"אֵל אַתְוָון דִּשְׁמָא קַדִּישָׁא, מִפּוּמֵיהּ דְּמֹשֶׁה, אִזְדַּעְזָע. קָרִיב לְגַבֵּיהּ, אֲמַר לֵיהּ, זַכָּאָה חוּלָקָךְ מֹשֶׁה, דְּאִתְגְלֵי לָךְ, מַה דְּלָא אִתְגְּלֵי לְמַלְאֲכֵי עִלָּאֵי.","וַהֲוָה אָזִיל עִמֵּיהּ, עַד דְּמָטוּ לְאֶשָּׁא תַּקִּיפָא, דְּחָד מַלְאָכָא דִּי שְׁמֵיהּ סַנְדַּלְפוֹן. וְתָאנָא, סַנְדַּלְפוֹן עִלָּאָה הוּא עַל שְׁאַר חַבְרוֹי, חֲמֵשׁ מְאָה שְׁנִין. וְהוּא קָאִים בָּתַר פַּרְגּוֹדָא דְּמָארֵיהּ, וְקָשֵׁר לֵיהּ כִּתְרִין, מִבָּעוּתֵיהוֹן (בראשית קס\"ז ע\"ב) דִּצְלוֹתָא דְּיִשְׂרָאֵל. וּבְשַׁעֲתָא דְּמָטֵי הַאי כֶּתֶר לְרֵישֵׁיהּ דְּמַלְכָּא קַדִּישָׁא, הוּא מְקַבֵּל צְלוֹתֵהוֹן דְּיִשְׂרָאֵל. וְכֻלְּהוּ חַיָּילִין וְאֻכְלוֹסִין מִזְדַּעְזְעִין, וְנָהֲמִין וְאַמְרִין, בְּרִיךְ יְקָרָא דַּיְיָ' מֵאֲתַר בֵּית שְׁכִינְתֵּיהּ.","אֲמַר לֵיהּ הֲדַרְנִיאֵל לְמֹשֶׁה, מֹשֶׁה, לֵית אֲנָא יָכִיל לִמְהַךְ עִמָּךְ, דְּלָא יוֹקִיד לִי אֶשָּׂא תַּקִּיפָא דְּסַנְדַּלְפוֹן. בֵּיהּ שַׁעֲתָא אִזְדַּעְזָע מֹשֶׁה, עַד דְּאַתְקִיף בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּמֹשֶׁה, וְאוֹתְבֵיהּ קָמֵיהּ, וְאוֹלִיף לֵיהּ אוֹרַיְיתָא. וְחָפָא לֵיהּ לְמֹשֶׁה, בְּהַהוּא נְהוֹרָא וְזִיוָא דְּהַהוּא נֹעַם, וַהֲווּ אַנְפּוֹי דְּמֹשֶׁה נְהִירִין בְּכָל אִינּוּן רְקִיעִין. וְכָל חֵילָא דִּשְׁמַיָּא הֲווֹ מִזְדַּעְזְעִין קָמֵיהּ, בְּשַׁעֲתָא דְּהֲוָה נָחִית בְּאוֹרַיְיתָא.","כֵּיוָן דְּחָבוּ יִשְׂרָאֵל לְתַתָּא, נָטַל קוּדְשָׁא בְּרִיךְ הוּא (נ\"א ממשה) אֶלֶ\"ף חוּלָקִין מֵהַהוּא זִיוָא. בֵּיהּ שַׁעֲתָא, בָּעוּ מַלְאָכִין עִלָּאִין, וְכָל אִינּוּן אֹכְלוֹסִין, לְאוֹקְדָא לְמֹשֶׁה, בְּשַׁעֲתָא דְּאֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא (שמות ל״ב:ז׳) לֵךְ רֵד כִּי שִׁחֵת עַמְּךָ. אִזְדַּעְזָע מֹשֶׁה, וְלָא יָכִיל לְמַלְּלָא, עַד דְּאַסְגֵּי בִּצְלוֹתִין וּבָעוּתִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.","אֲמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה, אַתְקִיף בְּכוּרְסְיָיא דִּילִי, עַד דְּגָעַר קוּדְשָׁא בְּרִיךְ הוּא בְּכָל אִינּוּן אֹכְלוֹסִין, בְּכָל אִינּוּן חַיָּילִין, וְאַתְקִיף מֹשֶׁה בִּתְרֵין לוּחִין דְּאַבְנִין, וְאָחִית לוֹן לְתַתָּא. וְדָא הוּא דִּכְתִּיב, (משלי כ״א:כ״ב) עִיר גִּבּוֹרִים עָלָה חָכָם וַיוֹרֶד עֹז מִבְטֶחָה. וּמֵהַהוּא זִיוָא דְּאִשְׁתְּאַר בֵּיהּ, הֲווֹ מַבְהִיקִין אַנְפּוֹי דְּמֹשֶׁה. וּמַה בְּהַאי דְּאִשְׁתְּאַר בֵּיהּ לָא הֲוֵי יַכְלִין לְאִסְתַּכְּלָא בְּאַנְפּוֹי, בְּהַהוּא דְּאִסְתַּלָּק מִינֵּיהּ עַל אַחַת כַּמָּה וְכַמָּה.","ר' חִיָּיא אָמַר, יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ, דָּא אוֹרַיְיתָא. וְעַל דָּא, יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב. דְּלֵית מִלָּה בְּעָלְמָא דְּיִתְבַּר חֵילֵיהוֹן דְּעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, בַּר בְּשַׁעֲתָא דְּיִשְׂרָאֵל מִתְעַסְּקִין בְּאוֹרַיְיתָא. דְּכָל זְמָן דְּיִשְׂרָאֵל מִתְעַסְּקִין בְּאוֹרַיְיתָא, יְמִינָא אִתְתְּקַף, וְאִתְּבַּר חֵילָא וְתּוּקְפָּא דְּעוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. וּבְגִינֵי כַּךְ אוֹרַיְיתָא אִקְרִית עֹז, כְּמָה דְאַתְּ אָמֵר (תהילים כ״ט:י״א) יְיָ' עֹז לְעַמּוֹ יִתֵּן.","וּבְשַׁעֲתָא דְּיִשְׂרָאֵל לָא מִתְעַסְּקִין בְּאוֹרַיְיתָא שְׂמָאלָא אִתְתָּקַף, וְאִתְתָּקַף חֵילֵיהוֹן דְעוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְשַׁלְטִין עָלַיְיהוּ, וְגַזְרִין עָלַיְיהוּ גִּזְרִין, דְּלָא יַכְלִין לְמֵיקָם בְּהוּ. וְעַל דָּא אִתְגְּלִיאוּ בְּנִי יִשְׂרָאֵל, וְאִתְבָּדָרוּ בֵּינִי עַמְמַיָּא."],[[0,"וההיא שעתא דאתבני וכו':","ובשעה ההוא שנבנה בית המקדש, נעטר הקב\"ה בעטרה ההוא, וישב בכסא שלו, שהוא המלכות, ונעטר בעטרותיו. ומאותו זמן שנחרב בית המקדש, לא נעטר הקב\"ה בעטרותיו, ונעם ההיא שהוא אור הבינה, נתכסה ונגנז."],[1,"אמר ר' אלעזר וכו':","אר\"א, בשעה שמשה נכנס בתוך הענן, כמ\"ש ויבא משה בתוך הענן. כאדם ההולך במקום הרוח, פגש בו מלאך גדול אחד. ולמדנו ששמו קמואל, והוא ממונה על י\"ב אלפים ממונים שליחים. רצה להתחבר בו במשה. פתח משה פיו, בי\"ב אותיות חקוקות של השם הקדוש, שלמד אותו הקב\"ה בסנה, והתרחק ממנו י\"ב אלף פרסאות. והיה הולך משה בענן, ועיניו לוהטות כגחלי אש."],[1,"","פירוש. נודע, שבכל מדרגה יש בה נרנח\"י. וכשבא משה למדרגת קבלת התורה בשביל ישראל, היה צריך להשיג את הנרנח\"י של מדרגה ההוא. גם נודע שתפקיד המלאכים הוא לעזור את הנשמות שישיגו מה שצריכים. וכן מלאכים אלו שלפנינו, באו לעזור למשה שישיג את הנרנח\"י הגדולים הללו."],[1,"","והנה בחינת נפש רוח, השיג משה על ידי הענן עצמו. וז\"ש \u0003דעאל משה בגו עננא וכו' כבר נש דהוה אזיל באתר דרוחא.\u0004 כלומר, שהענן היה לו למקום השגת אור הרוח. שה\"ס ו\"ק בחסרון ג\"ר. וכדי לעזרו להשגת ג\"ר, נגלה לו המלאך \u0003קמואל,\u0004 שהוא ממונה \u0003על י\"ב אלפין ממנין שליחין,\u0004 שה\"ס אור ג\"ר המקובל ע\"י ג' קוין בד' פנים חו\"ב תו\"מ שהם י\"ב, ולהיותם ממשיכים חכמה, הם במספר אלפים. וי\"ב אלפים אלו, ממונים שליחים לעזור לנשמה להשגת ג\"ר. וז\"ש, \u0003בעא לאזדווגא ביה במשה,\u0004 שרצה להתחבר עמו, ומיד השיג משה הג\"ר דנשמה, הנק' פה. וז\"ש \u0003פתח משה פומיה,\u0004 שזכה לאור הנשמה, המכונה פתחון פה, \u0003בי\"ב אתוון גליפין דשמא קדישא דאוליף ליה קב\"ה בסנה.\u0004 כי אלו י\"ב אתוון גליפין שקבל משה בסנה היו ג\"כ בחינת אור הנשמה לפי המדרגה שלו אז. ונודע שאור הנשמה דוחה חכמה ומתדבק בחסדים, בסו\"ה כי חפץ חסד הוא. וע\"כ דחה משה את המלאך קמואל הממשיך ג\"ר בהארת חכמה, והתדבק באור החסדים. וז\"ש \u0003ואתרחיק מניה י\"ב אלפין פרסין.\u0004 כלומר י\"ב פנים דנשמה, העומדים בשליטת אור החסדים, דוחים י\"ב פנים העומדים בשליטת החכמה, הנק' אלפים. וז\"ש שהתרחק ממנו י\"ב אלפים פרסאות. מחמת חשקו לחסדים. וז\"ש \u0003והוה אזיל משה בעננא,\u0004 כלומר שחזר להתדבק בבחינת אור הרוח שבענן. \u0003ועינוי מלהטן כגומרין דאשא,\u0004 כי לא הוכר הארת הג\"ר בעיניו, מחמת שהתדבק בקומת הרוח, שיש שם דינים דמסך דבחי\"א, הנקראים גחלי אש."],[2,"עד דאיערע ביה וכו':","עד שפגש בו מלאך אחד, גדול ויקר מן הראשון. ולמדנו הדרניאל שמו. והוא עליון על שאר המלאכים, אלף וששים רבוא פרסאות, וקולו הולך במאתים אלף רקיעים המסתובבים באש לבנה. כיון שראה אותו משה לא יכול לדבר, רצה להפיל עצמו מתוך הענן."],[3,"א\"ל קב\"ה, משה וכו':","אמר לו הקב\"ה, משה, וכי אתה הוא שהרבית דברים עמי בסנה, שרצית לדעת הסוד של השם הקדוש, ולא פחדת, ועתה, אתה מפחד מפני אחד ממשמשי. כיון ששמע משה קולו של הקב\"ה נתחזק. פתח פיו בע\"ב אתוון של השם העליון. כיון ששמע הדרניאל האותיות של השם הקדוש מפי משה, נזדעזע. קרב אליו, א\"ל, אשרי חלקך משה, שנגלה לך מה שלא נגלה למלאכים עליונים."],[3,"","פירוש. כי אחר שהשיג בעזרת קמואל מוחין דנשמה. היה צריך להשיג עתה מוחין דחיה. ונשלח לו לעזרה המלאך הדרניאל. וז\"ש, \u0003עד דאיערע ביה חד מלאכא רברבא ויקירא מן קדמאה,\u0004 כדי לעזור לו במוחין דחיה היותר חשובים. ומפרש גדלות ג' הקוין שלו. ונודע שהחכמה הוא במספר אלף, והחסדים הם במספר רבוא, וז\"ש \u0003והוא עלאה על שאר מלאכין,\u0004 דהיינו שחשיבותו הוא \u0003אלף וס\"ר פרסין.\u0004 ס\"ר פרסין בימינו, שהם חסדים הנמשכים משש ספירות תחתוניות דעתיק שספירותיו בסוד עשרה רבוא. והם ששים רבוא. ובשמאלו אלף, שה\"ס החכמה שמספרה אלף. \u0003וקליה,\u0004 שהוא קו אמצעי המכונה קול, \u0003אזיל במאתן אלף רקיעים,\u0004 שהם הרקיעים דאו\"א עלאין, אלף רקיעים לאבא ואלף רקיעים לאמא, \u0003דמסתחראן באשא חוורא,\u0004 כי או\"א עלאין, הם בבחינת \u0003אוירא דכיא.\u0004 שה \u0003י'\u0004 אינה יוצאת מ \u0003אויר\u0004 שלהם, ובהם מתוקן המנעולא, שה\"ס המלכות דמדת הדין שנקראת אש. אלא מתוך שאו\"א עלאין הם תמיד בסוד כי חפץ חסד הוא אין האש הזה פוגם אצלם כלום, וע\"כ נקרא \u0003אש לבנה.\u0004 כלומר שאין בו פגם משהו. (כמ\"ש ב\"ב דף כ' ד\"ה בראשית ע\"ש) וקולו של הדרניאל שהוא קו אמצעי שלו ממשיך האוירא דכיא הזה דאו\"א עלאין."],[3,"","וז\"ש \u0003כיון דחמא ליה משה, לא יכיל למללא,\u0004 דהיינו מחמת הפחד דאשא חוורא, שראה בו שה\"ס מלכות דמדת הדין. שמפחד הזה לא יכול לשמש עם הג\"ר דנשמה שלו, הנקראים \u0003דבור.\u0004 ולא עוד, אלא אפילו קומת רוח שהיה לו מכח הענן, לא יכול לשמש עמה, מטעם היותה ממלכות הממותקת בבינה. וז\"ש \u0003בעא למשדי גרמיה מגו עננא,\u0004 כי המלכות דמדת הדין שראה, פגמה מדרגת הענן, שהיתה ממלכות דמדת הרחמים. ואז נגלה לו קולו של הקב\"ה, שהוא ז\"א, שקול הזה ממתיק כל הדינים. וז\"ש \u0003כיון דשמע משה קלא דקב\"ה אתתקף.\u0004 ואז, בעזרתו של הדרניאל, המשיך המוחין דחיה, וז\"ש \u0003פתח פומיה בע\"ב אתוון דשמא עלאה\u0004 שהשיג פתחון פה, שה\"ס ג\"ר, מסוד ע\"ב. וכששמע הדרניאל, שכבר משך מוחין דע\"ב נתחבר עמו. וז\"ש, \u0003כיון דשמע הדרניאל וכו' קריב לגביה.\u0004"],[4,"והוה אזיל עמיה וכו':","והיה הולך עמו עד שהגיע לאשא תקיפא של מלאך אחד ששמו סנדלפון. ולמדנו סנדלפון גבוה על שאר חביריו, חמש מאות שנים. והוא עומד אחר הפרגוד של אדונו, וקושר לו כתרים מבקשותיהם של תפלות ישראל. ובשעה שמגיע כתר הזה לראש המלך הקדוש, הוא מקבל תפלות ישראל. וכל הצבאות וההמונים מזדעזעים ונוהמים ואומרים, ברוך כבוד ה' ממקום בית שכינתו."],[5,"א\"ל הדרניאל למשה וכו':","אמר לו הדרניאל למשה, משה, איני יכול ללכת עמך, מפחד שלא ישרוף אותי אש החזק של סנדלפון. בו בשעה נזדעזע משה, עד שהחזיק הקב\"ה במשה, והושיבו לפניו, ולימד אותו תורה. וכסה את משה באור ההוא והזיו של אותו הנעם, והיה פני משה מאירים בכל הרקיעים. וכל צבאות השמים היו מזדעזעים לפניו, בשעה שהיה יורד עם התורה."],[5,"","פירוש. סנדלפון עומד בראש עולם הבריאה מתחת המסך של המלכות דאצילות. וז\"ש והוא קאים בתר פרגודא דמאריה. ומקבל שם מהארת חג\"ת נ\"ה דבינה המאירים שם. וספירות דבינה הם במספר מאות וע\"כ הם ה' מאות. וז\"ש \u0003עלאה הוא על שאר חברוי חמש מאות שנה.\u0004 והוא מעלה מ\"ן לצורך זווג המלכות עם ז\"א, מתפלות ישראל. וז\"ש, \u0003וקשר ליה כתרין מבעותהון של ישראל,\u0004 ובשעת הזווג מתקבלות תפלתם, וז\"ש, \u0003ובשעתא דמטי האי כתר לרישיה דמלכא קדישא הוא מקבל צלותהון דישראל.\u0004 ולהיות עמידתו תחת המסך דמלכות נבחן בו אש חזק, מדינים שבמסך דמלכות וז\"ש, \u0003אמר לו הדרניאל וכו' דלא יוקיד לי אשא תקיפא דסנדלפון.\u0004 ואז נזדעזע משה \u0003עד דאתקיף ביה קב\"ה במשה ואותביה קמיה ואוליף ליה אורייתא.\u0004 ויש כאן סוד גדול. כי בכל פעם שנזדעזע משה מחמת אשא תקיפא דסנדלפון, החזיק בו הקב\"ה ולמד עמו תורה, עד שלימדו הקב\"ה כל התורה והמצוה, שבגמר גילוים זכה משה לאור היחידה."],[6,"כיון דחבו ישראל וכו':","כיון שחטאו ישראל למטה לקח הקב\"ה ממשה אלף חלקים מאותו הזיו. בו בשעה רצו מלאכים העליונים וכל ההמונים לשרוף את משה, דהיינו בשעה שאמר לו הקב\"ה לך רד כי שחת עמך. נזדעזע משה ולא יכול לדבר, עד שהרבה בקשות ותפלות לפני הקב\"ה."],[7,"א\"ל קב\"ה משה וכו':","א\"ל הקב\"ה: משה, אחוז בכסא שלי. עד שגער הקב\"ה בכל אלו ההמונים, בכל אלו הצבאות, ואז אחז משה בשני לוחות אבנים והורידם למטה. וז\"ש עיר גבורים עלה חכם וירד עז מבטחה. ומזיו ההוא שנשאר בו היו מבריקים פניו של משה. ומה בזה שנשאר בו לא יכלו להסתכל בפניו, במה שנסתלק ממנו על אחת כמה וכמה שלא יכלו להסתכל."],[8,"ר' חייא אמר וכו':","רח\"א, ימינך ה' נאדרי בכח, זהו התורה, שמאדירה את הימין, וע\"כ, ימינך ה' תרעץ אויב. כי אין דבר בעולם שישבור כחם של עמים עכו\"ם, כמו בשעה שישראל עוסקים בתורה. שכל זמן שישראל עוסקים בתורה מתחזק הימין, ונשבר כחם ועוזם של העמים עכו\"ם. ומשום זה נקראת התורה \u0003עוז,\u0004 כמש\"א ה' עוז לעמו יתן."],[9,"ובשעתא דישראל לא וכו':","ובשעה שישראל אינם עוסקים בתורה, מתחזק השמאל, ומתחזק כחם של העמים עכו\"ם, שיונקים מן השמאל, ושולטים עליהם, על ישראל, וגוזרים עליהם גזירות שאינם יכולים לעמוד בהם. ועל זה נגלו בני ישראל ונתפזרו בין האומות."]],[[0,"","וְאוֹתָהּ שָׁעָה שֶׁנִּבְנָה הַמִּקְדָּשׁ, הִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ עֲטָרָה, וְיָשַׁב בְּכִסְאוֹ וְהִתְעַטֵּר בְּעַטְרוֹתָיו. וּמֵאוֹתוֹ זְמַן שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, לֹא הִתְעַטֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַטְרוֹתָיו, וְאוֹתוֹ נֹעַם הִתְכַּסָּה וְנִגְנַז."],[1,"","אָמַר רַבִּי אֶלְעָזָר, בְּשָׁעָה שֶׁנִּכְנַס מֹשֶׁה לְתוֹךְ הֶעָנָן, כַּכָּתוּב (שמות כד) וַיָּבא מֹשֶׁה בְּתוֹךְ הֶעָנָן, כְּאָדָם שֶׁהָיָה הוֹלֵךְ בְּמָקוֹם שֶׁל רוּחַ, וּפָגַשׁ בּוֹ מַלְאָךְ גָּדוֹל אֶחָד. וְשָׁנִינוּ שֶׁשְּׁמוֹ קְמוּאֵ\"ל, וְהוּא מְמֻנֶּה עַל שְׁנֵים עָשָׂר אֶלֶף מְמֻנִּים שְׁלִיחִים. רָצָה לְהִזְדַּוֵּג בְּמֹשֶׁה. פָּתַח מֹשֶׁה פִּיו בִּשְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת חֲקוּקוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁלִּמֵּד אוֹתוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּסְּנֶה, וְהִתְרַחֵק מִמֶּנּוּ שְׁתֵּים עֶשְׂרֵה אֶלֶף פַּרְסוֹת, וְהָיָה מֹשֶׁה הוֹלֵךְ בֶּעָנָן, וְעֵינָיו לוֹהֲטוֹת כְּגַחֲלֵי אֵשׁ."],[2,"","עַד שֶׁפָּגַשׁ בּוֹ מַלְאָךְ אֶחָד גָּדוֹל וְנִכְבָּד מִן הַקֹּדֶם, וְשָׁנִינוּ שֶׁשְּׁמוֹ הֲדַרְנִיאֵ\"ל, וְהוּא עֶלְיוֹן עַל כָּל שְׁאָר הַמַּלְאָכִים אֶלֶף וְשִׁשִּׁים רִבּוֹא פַּרְסוֹת, וְקוֹלוֹ הוֹלֵךְ בְּמָאתַיִם אֶלֶף רְקִיעִים שֶׁמֻּקָּפִים בְּאֵשׁ לְבָנָה. כֵּיוָן שֶׁרָאָהוּ מֹשֶׁה, לֹא יָכֹל לְדַבֵּר. רָצָה לִזְרֹק אֶת עַצְמוֹ מִתּוֹךְ הֶעָנָן."],[3,"","אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, וְכִי אַתָּה שֶׁהִרְבִּיתָ דְּבָרִים עִמִּי בַּסְּנֶה, שֶׁרָצִיתָ לָדַעַת אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ וְלֹא פָחַדְתָּ, וְעַכְשָׁו אַתָּה פּוֹחֵד מֵאֶחָד מִשַּׁמָּשַׁי? כֵּיוָן שֶׁשָּׁמַע מֹשֶׁה אֶת קוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא, הִתְחַזֵּק. פָּתַח פִּיו בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת הַשֵּׁם הָעֶלְיוֹן. כֵּיוָן שֶׁשָּׁמַע הֲדַרְנִיאֵ\"ל אֶת אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ מִפִּי מֹשֶׁה, הִזְדַּעֲזַע. קָרַב אֵלָיו וְאָמַר לוֹ: אַשְׁרֵי חֶלְקְךְ, מֹשֶׁה, שֶׁהִתְגַּלָּה לְךְ מַה שֶּׁלֹּא הִתְגַּלָּה לַמַּלְאָכִים הָעֶלְיוֹנִים."],[4,"","וְהָיָה הוֹלֵךְ עִמּוֹ, עַד שֶׁהִגִּיעוּ לְאֵשׁ חֲזָקָה שֶׁל מַלְאָךְ אֶחָד שֶׁשְּׁמוֹ סַנְדַּלְפוֹ\"ן. וְשָׁנִינוּ, סַנְדַּלְפוֹן עֶלְיוֹן הוּא עַל שְׁאָר חֲבֵרָיו חֲמֵשׁ מֵאוֹת שָׁנָה, וְהוּא עוֹמֵד אַחַר הַפַּרְגּוֹד שֶׁל רִבּוֹנוֹ, וְקוֹשֵׁר לוֹ כְּתָרִים מִבַּקָּשׁוֹתֵיהֶם שֶׁל הַתְּפִלָּה שֶׁל יִשְׂרָאֵל. וּבְשָׁעָה שֶׁמַּגִּיעַ הַכֶּתֶר הַזֶּה לְרֹאשׁ הַמֶּלֶךְ הַקָּדוֹשׁ, הוּא מְקַבֵּל אֶת תְּפִלּוֹת יִשְׂרָאֵל, וְכָל הַחֲיָלוֹת וְהַהֲמוֹנִים מִזְדַּעְזְעִים, וְנוֹהֲמִים וְאוֹמְרִים: בָּרוּךְ כְּבוֹד ה' מִמְּקוֹם בֵּית שְׁכִינָתוֹ."],[5,"","אָמַר לוֹ הֲדַרְנִיאֵל לְמֹשֶׁה, מֹשֶׁה, אֵינֶנִּי יָכוֹל לָלֶכֶת עִמְּךְ, שֶׁלֹּא תִשְׂרֹף אוֹתִי הָאֵשׁ הַחֲזָקָה שֶׁל סַנְדַּלְפוֹן. בְּאוֹתָהּ שָׁעָה הִזְדַּעֲזַע מֹשֶׁה, עַד שֶׁהֶחֱזִיק הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמֹשֶׁה, וְהוֹשִׁיבוֹ לְפָנָיו וְלִמֵּד אוֹתוֹ תּוֹרָה. וְכִסָּה אֶת מֹשֶׁה בְּאוֹתוֹ אוֹר וְזִיו שֶׁל אוֹתוֹ נֹעַם, וְהָיוּ פָנָיו שֶׁל מֹשֶׁה מְאִירִים בְּכָל אוֹתָם הָרְקִיעִים, וְכָל חֵיל הַשָּׁמַיִם הָיוּ מִזְדַּעְזְעִים לְפָנָיו בְּשָׁעָה שֶׁהָיָה מוֹרִיד תּוֹרָה."],[6,"","כֵּיוָן שֶׁחָטְאוּ יִשְׂרָאֵל לְמַטָּה, נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא (ממשה) אֶלֶף חֲלָקִים מֵאוֹתוֹ זִיו. בְּאוֹתָהּ שָׁעָה רָצוּ מַלְאָכִים עֶלְיוֹנִים, וְכָל אוֹתָם הֲמוֹנִים, לִשְׂרֹף אֶת מֹשֶׁה בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לב) לֶךְ רֵד כִּי שִׁחֵת עַמְּךְ. הִזְדַּעֲזַע מֹשֶׁה וְלֹא יָכֹל לְדַבֵּר, עַד שֶׁהִרְבָּה בִּתְפִלּוֹת וּבַקָּשׁוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[7,"","אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, הַחֲזֵק בְּכִסְאִי! עַד שֶׁגָּעַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל אוֹתָם הֲמוֹנִים וּבְכָל אוֹתָם חֲיָלוֹת, וְהֶחֱזִיק מֹשֶׁה בִּשְׁנֵי לוּחוֹת הָאֲבָנִים, וְהוֹרִיד אוֹתָם לְמַטָּה, וְזֶהוּ שֶׁכָּתוּב (משלי כא) עִיר גִּבֹּרִים עָלָה חָכָם וַיֹּרֶד עֹז מִבְטֶחָה. וּמֵאוֹתוֹ זִיו שֶׁנִּשְׁאַר בּוֹ, הָיוּ פְּנֵי מֹשֶׁה מַבְהִיקִים. וּמַה בְּאוֹתוֹ שֶׁנִּשְׁאַר בּוֹ לֹא הָיוּ יְכוֹלִים לְהִסְתַּכֵּל בְּפָנָיו - בְּאוֹתוֹ שֶׁהִסְתַּלֵּק מִמֶּנּוּ עַל אַחַת כַּמָּה וְכַמָּה."],[8,"","רַבִּי חִיָּיא אָמַר, יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ - זוֹ הַתּוֹרָה. וְעַל זֶה יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. שֶׁאֵין דָּבָר בָּעוֹלָם שֶׁיִּשְׁבֹּר כֹּחָם שֶׁל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת פְּרָט לְשָׁעָה שֶׁיִּשְׂרָאֵל מִתְעַסְּקִים בַּתּוֹרָה. שֶׁכָּל זְמַן שֶׁיִּשְׂרָאֵל מִתְעַסְּקִים בַּתּוֹרָה, הַיָּמִין מִתְחַזֵּק, וְנִשְׁבָּר כֹּחַ וְתֹקֶף שֶׁל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וְלָכֵן הַתּוֹרָה נִקְרֵאת עֹז, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כט) ה' עֹז לְעַמּוֹ יִתֵּן."],[9,"","וּבְשָׁעָה שֶׁיִּשְׂרָאֵל לֹא מִתְעַסְּקִים בַּתּוֹרָה - מִתְחַזֵּק הַשְּׂמֹאל, וּמִתְחַזֵּק כֹּחַ שֶׁל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְשׁוֹלְטִים עֲלֵיהֶם, וְגוֹזְרִים עֲלֵיהֶם גְּזֵרוֹת שֶׁלֹּא יְכוֹלִים לַעֲמֹד בָּהֶם, וְעַל זֶה הֻגְלוּ בְּנֵי יִשְׂרָאֵל וְהִתְפַּזְּרוּ בֵּין הָעַמִּים."]]],[["דְּהָא הוּא דִּכְתִּיב (ירמיהו ט׳:י״ב) עַל מָה אָבְדָה הָאָרֶץ וְגוֹ', וַיֹּאמֶר יְיָ' עַל עָזְבָם אֶת תּוֹרָתִי. דְּהָא כָּל זִמְנָא דְּיִשְׂרָאֵל יִשְׁתַּדְּלוּן בְּאוֹרַיְיתָא, אִתְּבַר חֵילָא וְתּוּקְפָּא דְּכָל עוֹבְדֵי עֲבוֹדַה זָרָה, הֲדָא הוּא דִכְתִיב יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב. אָמַר רִבִּי אֶלְעָזָר, וַדַּאי הָכִי הוּא, דְּכָל זִמְנָא דְּקָלֵיהוֹן דְּיִשְׂרָאֵל, אִשְׁתְּמַע בְּבָתֵּי כְּנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְכוּ', כְּמָה דְּתַנִּינָא (בראשית כ״ז:כ״ב) הַקּוֹל קוֹל יַעֲקֹב, וְאִי לָאו הַיָּדַיִם יְדֵי עֵשָׂו, וְהָא אוֹקִימְנָא.","(שמות ט״ו:ז׳) וּבְרֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ. ר' חִזְקִיָּה פָּתַח וְאָמַר, (תהילים י׳:א׳) לָמָּה יְיָ' תַּעֲמוֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה, בְּשַׁעֲתָא דְּחוֹבֵי עָלְמָא גָּרְמוּ, קוּדְשָׁא בְּרִיךְ הוּא סָלִיק לְעֵילָּא לְעֵילָּא, וּבְנֵי נָשָׁא צַוְוחִין וְנַחְתִּין דִּמְעִין, וְלֵית מַאן דְּיִשְׁגַּח עָלַיְיהוּ. מַאי טַעְמָא. בְּגִין דְּאִיהוּ סָלִיק לְעֵילָּא לְעֵילָּא, וּתְשׁוּבָה אִתְמָנַּע מִנַּיְיהוּ, כְּדֵין כְּתִיב, וּבְרֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ.","ר' יִצְחָק אָמַר, הַאי קְרָא, בְּשַׁעֲתָא דְּאִתְלָבַשׁ קוּדְשָׁא בְּרִיךְ הוּא גָּאוּתָא, עַל עֲמַמְיָא דְּיִתְכַּנְּשׁוּן עָלֵיהּ, כְּמָה דִּכְתִּיב, (תהילים ב׳:ב׳) וְרוֹזְנִים נוֹסְדוּ יַחַד עַל יְיָ' וְעַל מְשִׁיחוֹ. וְתָאנָא זְמִינִין אִינּוּן שִׁבְעִין קַסְטוֹרִין מִכָּל עִיבָר, (נ\"א עמין) לְאִתְכַּנְּשָׁא בְּהַהוּא זִמְנָא בְּאוֹכְלוֹסִין דְּכָל עָלְמָא, וּלְמֶעְבַּד קְרָבָא עַל יְרוּשָׁלַ ם קַרְתָּא קַדִּישָׁא, וּלְאַחֲדָא עֵיטִין עָלֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. וּמַאי אַמְרֵי, נוֹקִים עַל פַּטְרוֹנָא בְּקַדְמִיתָא, וּלְבָתַר עַל עַמֵּיהּ, וְעַל הֵיכָלֵיהּ.","כְּדֵין זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְחַיְּיכָא עָלַיְיהוּ. דִּכְתִּיב, (תהילים ב׳:ד׳) יוֹשֵׁב בַּשָׁמַיִם יִשְׂחַק יְיָ' יִלְעַג לָמוֹ. בְּהַהוּא זִמְנָא יִלְבַּשׁ קוּדְשָׁא בְּרִיךְ הוּא גָּאוּותָא עָלַיְיהוּ, וִישֵׁיצִינוּן מִן עָלְמָא, כְּמָה דִּכְתִּיב, (זכריה י״ד:י״ב) וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף יְיָ' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלַ ם הָמֵק בְּשָׂרוֹ וְהוּא עוֹמֵד עַל רַגְלָיו.","רִבִּי אַבָּא אָמַר מִשְּׁמֵיהּ דְּרַב יֵיסָא סָבָא, וְהָכִי אָמַר רַבִּי שִׁמְעוֹן, זַמִין קוּדְשָׁא בְּרִיךְ הוּא לְאַחֲיָיא לְכָל אִינּוּן מַלְכִין, דְּעָקוּ לְיִשְׂרָאֵל וְלִיְרוּשָׁלַ ם, לְאַנְדְּרִיאָנוּס, לְלוּפִינוֹס, וּנְבוּכַדְנֶצַר, וּלְסַנְחֵרִיב, וּלְכָל שְׁאַר מַלְכֵי עַמִּין, דְּחָרִיבוּ בֵּיתֵיהּ, וּלְשַׁלְּטָאָה לוֹן כְּקַדְמִיתָא, וְיִתְכָּנְּשׁוּן עִמְּהוֹן שְׁאַר עַמִּין, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְפָּרְעָא מִנַּיְיהוּ בְּאִתְגַּלְּיָיא, סַחֲרָנֵי יְרוּשָׁלַם. הֲדָא הוּא דִכְתִיב, וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף יְיָ' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלַ ם. אֲשֶׁר יִצְבְּאוּ לָא כְּתִיב, אֶלָּא אֲשֶׁר צָבְאוּ. כְּדֵין כְּתִיב, וּבְרֹב גְּאוֹנְךָ תַּהֲרוֹס קָמֶיךָ, וְדָא לְזִמְנָא דְּאָתָא מְשִׁיחָא, כְּתִיב, וְשִׁירָתָא דָּא שִׁירָתָא דְּעָלְמִין הִיא.","(שמות ט״ו:ח׳) וּבְרוּחַ אַפֶּיךָ נֶעֶרְמוּ מַיִם, בְּהַהוּא זִמְנָא. וּבְגִין כַּךְ אִית בְּהַהוּא זִמְנָא, וּלְזִמְנָא דְּמַלְכָּא מְשִׁיחָא, וּלְזִמְנָא דְּגוֹג וּמָגוֹג. נִצְּבוּ כְּמוֹ נֵד, לְזִמְנָא דְּעָלְמָא דְּאָתֵי, דְּאִיהוּ חֶדְוָותָא דְּכָל עָלְמִין.","(שמות ט״ו:ט׳) אָמַר אוֹיֵב אֶרְדּוֹף אַשִּׂיג אֲחַלֵּק שָׁלָל. אָמַר אוֹיֵב, דָּא הַהוּא מְמָנָא רַבְרְבָא עַל מִצְרָאֵי, בְּשַׁעֲתָא דְּאִתְיְהִיב לֵיהּ שֻׁלְטָנוּתָא עַל יִשְׂרָאֵל, חָשִׁיב דְּיֵשֵׁיצִינוּן תְּחוֹת שֻׁלְטָנֵיהּ. אֶלָּא דְּדָכַר קוּדְשָׁא בְּרִיךְ הוּא טוּרֵי עָלְמָא, דַּהֲווֹ מְגִינִּין עָלַיְיהוּ. וְלָא תֵּימָא דָּא בִּלְחוֹדוֹי, אֶלָּא כָּל אִינּוּן רַבְרְבִין דִּמְמָנָן עַל כָּל עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וְכַד אִתְיְיהִיב לְהוּ רְשׁוּתָא וְשֻׁלְטָנוּתָא עַל יִשְׂרָאֵל, כֻּלְּהוּ בָּעָאן דִּישֵׁיצוּן יִשְׂרָאֵל תְּחוֹתַיְיהוּ.","וְעַל דָּא, אִינּוּן עַמִּין דִּתְחוֹת שׁוּלְטָנֵיהוֹן דְּאִינּוּן מְמָנָן, כֻּלְּהוּ גַּזְירִין גְּזִרִין לְשֵׁיצָאָה לוֹן, אֶלָּא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּכַר טוּרֵי עָלְמָא, וְאָגִין עָלַיְיהוּ. וְכַד חָמָא מֹשֶׁה דָּא, שָׁרָא לְשַׁבְּחָא לְקוּדְשָׁא בְּרִיךְ הוּא, וְאָמַר מִי כָמוֹכָה בָּאֵלִים יְיָ'.","אָמַר רַבִּי שִׁמְעוֹן, אִילָנָא חַד רַבְרְבָא עִלָּאָה, תַּקִּיפָא, בֵּיהּ אִתְּזָנוּ עִלָּאִין וְתַתָּאִין. וְהוּא אִתְּחַם בִּתְרֵיסַר תְּחוּמִין, אִתְתָּקַּף בְּאַרְבַּע סִטְרֵי עָלְמָא, דְאִסְתָחֲרָאן (נ\"א דאתחברן) בְּדוּכְתַּיְיהוּ. שִׁבְעִין עֲנָפִין סַלְּקִין בְּגַוֵּיהּ, וְאִתְּזָנוּ מִנֵּיהּ, בְּעִקַר שָׁרְשׁוֹי יַנְקִין אִינּוּן סַחֲרָנֵיהּ, וְאִינּוּן עֲנָפִין דְּמִשְׁתַּכְחִין בְּאִילָנָא.","כַּד מָטֵי עִדַן שֻׁלְטָנֵיהּ דְּכָל עֲנָפָא וַעֲנָפָא, כֻּלְּהוּ בָּעָאן לְשֵׁיצָאָה כֹּלָּא גּוּפָא דְּאִילָנָא, דְּאִיהוּ עִקָרָא דְּכֻלְּהוּ עֲנָפִין, הַהוּא דְּשָׁלִיט עָלַיְיהוּ, וְיִשְׂרָאֵל אֲחִידָן בֵּיהּ. כַּד מָטָא עָלַיְיהוּ שֻׁלְטָנוּתָא דְּהַהוּא גּוּפָא דְּאִילָנָא, חוּלָקָא דְּיִשְׂרָאֵל. בָּעֵי לְנַטְרָא לוֹן, וּלְמֵיהַב שְׁלָמָא בְּכֻלְּהוּ. וְעַל דָּא שִׁבְעִים פָּרֵי הֶחָג, לְמִיהַב שְׁלָמָא לְשִׁבְעִין עֲנָפִין דִּבְגוֹ אִילָנָא."],[[0,"הדא הוא דכתיב וכו':","ז\"ש, על מה אבדה הארץ וגו' ויאמר ה' על עזבם את תורתי. כי כל זמן שישראל עוסקים בתורה, נשבר כחם ועוזם של כל עובדי ע\"ז, ז\"ש ימינך ה' תרעץ אויב. א\"ר אלעזר, ודאי כן הוא, כמו שלמדנו, שכל זמן שקולם של ישראל נשמע בבתי כנסיות ובבתי מדרשות, הקול קול יעקב, ואם לא הידים ידי עשו. וכבר בארנו."],[1,"וברב גאונך תהרוס קמיך:","ר' חזקיה פתח ואמר, למה ה' תעמוד ברחוק וגו'. בשעה שעונות העולם גורמים, הקב\"ה עולה למעלה למעלה, ובני אדם צועקים ומורידים דמעות, ואין מי שישגיח עליהם. מהו הטעם. משום שהקב\"ה נסתלק למעלה למעלה, ונמנע מהם התשובה. אז כתוב, וברב גאונך תהרוס קמיך."],[2,"ר' יצחק אמר וכו':","רי\"א, מקרא זה, הוא, בשעה שהקב\"ה מתלבש בגאות על העמים שיתאספו עליו. כמ\"ש ורוזנים נוסדו יחד על ה' ועל משיחו. ולמדנו, עתידים ע' שרי צבאות להתאסף מכל צד בעת ההיא עם הצבאות של כל העולם, ולעשות מלחמה על ירושלים עיר הקדושה ולאחוז בעצות על הקב\"ה. ומהו אומרים. נקום על המגין מתחילה, ואח\"כ על עמו ועל היכלו."],[3,"כדין זמין קב\"ה וכו':","אז עתיד הקב\"ה לצחוק עליהם, שכתוב יושב בשמים ישחק ה' ילעג למו. בזמן ההיא ילבוש הקב\"ה גאות עליהם, ויכלה אותם מן העולם. כמ\"ש וזאת תהיה המגפה וגו'."],[4,"ר' אבא אמר וכו':","רא\"א משמו של ר' ייסא סבא, וכן אמר ר' שמעון, עתיד הקב\"ה להחיות כל אלו המלכים שהצירו את ישראל וירושלים, דהיינו לאנדיאנוס ללופינוס, ונבוכדנצר, ולסנחריב, ולכל שאר מלכי העולם, שהחריבו ביתו, ויתן להם ממשלה כמתחילה, ויאספו עמהם שאר העמים וילחמו על ירושלים, ועתיד הקב\"ה להפרע מהם בגלוי סביב ירושלים. וז\"ש וזאת תהיה המגפה אשר יגוף ה' את כל העמים אשר צבאו על ירושלים. אשר יצבאו לא כתוב, אלא אשר צבאו, לשון עבר, כי סובב על נבוכדנצר וכו' שכבר צבאו. אז כתוב, וברב גאונך תהרס קמיך. וזה כתוב, לזמן שיבא המשיח, ושירה זו, שירת עולם היא."],[5,"וברוח אפיך נערמו מים:","היינו באותו זמן. ועל כך, יש זה באותו זמן, ובזמן מלך המשיח, ובזמן של גוג ומגוג. נצבו כמו נד, הוא לזמן העולם הבא, שהוא שמחת כל העולמות."],[6,"אמר אויב ארדוף אשיג וגו':","אמר אויב, זהו הממונה הגדול של מצרים. בשעה שניתנה לו הממשלה על ישראל, חשב לכלותם תחת ממשלתו, אלא שזכר הקב\"ה הרי העולם, שהם האבות, שהיו מגינים עליהם. ולא תאמר שזה בלבד רצה לכלותם, אלא כל אלו השרים הממונים על כל העמים עכו\"ם, כשניתן להם רשות וממשלה על ישראל, רוצים כולם לכלות ישראל תחתם."],[7,"ועל דא אינון וכו':","ועל כן אלו העמים שהם תחת שליטתם של אלו הממונים, כולם גוזרים גזרות לכלות את ישראל. אלא הקב\"ה זוכר הרי העולם, שהם האבות, ומגין עליהם. וכשראה משה את זה, התחיל לשבח את הקב\"ה, ואמר מי כמוכה באלים ה'."],[8,"אמר ר\"ש אילנא וכו':","אר\"ש, אילן אחד גדול עליון וחזק, הוא ז\"א, בו נזונים עליונים ותחתונים. ומוגבל בי\"ב גבולי אלכסון, שהם ד' ספירות חו\"ג תו\"מ שבכל אחד ג' קוין. (כמ\"ש בפ' לך דף ז' ד\"ה גו נטיען ע\"ש) מתחזק בד' רוחות העולם, שהם חו\"ג תו\"מ, המתחברים במקומם. ע' ענפין שהם ע' שרים הממונים על ע' אומות העולם. עולים בתוכו ונזונים ממנו. מעיקר שרשיו יונקים הם מסביב. והם ענפים הנמצאים באילן."],[9,"כד מטי עדן וכו':","כשמגיע עת הממשלה לכל ענף וענף, כולם רוצים לכלות לגמרי את גוף האילן, שהוא העיקר של כל הענפים, והוא השולט על ישראל ואחוזים בו. וכשמגיע עליהם הממשלה של גוף האילן, שהוא חלקם של ישראל. הוא רוצה לשמרם, ולתת שלום בכולם. ועל זה מקריבים ע' פרי החג לתת שלום לע' ענפים שבתוך האילן, שהם ע' שרים של אומות העולם."]],[[0,"","זֶהוּ זֶה שֶׁכָּתוּב, עַל מָה אָבְדָה הָאָרֶץ וְגוֹ', וַיֹּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי. שֶׁהֲרֵי כָּל זְמַן שֶׁיִּשְׂרָאֵל יִשְׁתַּדְּלוּ בַּתּוֹרָה, נִשְׁבָּר כֹּחַ וְתָקְפָּם שֶׁל עוֹבְדֵי עֲבוֹדָה זָרָה, זֶהוּ שֶׁכָּתוּב יְמִינְךְ ה' תִּרְעַץ אוֹיֵב. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא, שֶׁכָּל זְמַן שֶׁקּוֹלָם שֶׁל יִשְׂרָאֵל נִשְׁמָע בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְכוּ', כְּמוֹ שֶׁשָּׁנִינוּ (בראשית כז) הַקֹּל קוֹל יַעֲקֹב. וְאִם לֹא, אָז הַיָּדַיִם יְדֵי עֵשָׂו, וַהֲרֵי בֵּאַרְנוּ."],[1,"","וּבְרֹב גְּאוֹנְךְ תַּהֲרֹס קָמֶיךְ. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (תהלים י) לָמָה ה' תַּעֲמֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה. בְּשָׁעָה שֶׁחֲטָאֵי הָעוֹלָם גּוֹרְמִים, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹלֶה לְמַעְלָה לְמַעְלָה, וּבְנֵי אָדָם צוֹוְחִים וּמוֹרִידִים דְּמָעוֹת וְאֵין מִי שֶׁיַּשְׁגִּיחַ עֲלֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא עוֹלֶה לְמַעְלָה לְמַעְלָה, וְנִמְנַעַת מֵהֶם תְּשׁוּבָה, וְאָז כָּתוּב וּבְרֹב גְּאוֹנְךְ תַּהֲרֹס קָמֶיךְ."],[2,"","רַבִּי יִצְחָק אָמַר, פָּסוּק זֶה, בְּשָׁעָה שֶׁמִּתְלַבֵּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַאֲוָה עַל הָעַמִּים שֶׁיִּתְכַּנְּסוּ עָלָיו, כְּמוֹ שֶׁכָּתוּב (שם ב) וְרוֹזְנִים נוֹסְדוּ יָחַד עַל ה' וְעַל מְשִׁיחוֹ. וְלָמַדְנוּ, עֲתִידִים הֵם שִׁבְעִים שָׂרֵי צְבָאוֹת מִכָּל עֵבֶר (עמים) לְהִתְכַּנֵּס בְּאוֹתוֹ זְמַן בַּהֲמוֹנִים מִכָּל הָעוֹלָם, וְלַעֲשׂוֹת קְרָב עַל יְרוּשָׁלַיִם עִיר הַקֹּדֶשׁ, וְלֶאֱחֹז עֵצוֹת עַל הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמָה אוֹמְרִים? נַעֲמֹד עַל הַפַּטְרוֹן בַּהַתְחָלָה, וְאַחַר כָּךְ עַל עַמּוֹ וְעַל הֵיכָלוֹ."],[3,"","אָז עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִצְחֹק עֲלֵיהֶם, שֶׁכָּתוּב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק ה' יִלְעַג לָמוֹ. בְּאוֹתוֹ זְמַן יִלְבַּשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא גַּאֲוָה עֲלֵיהֶם, וְיַשְׁמִיד אוֹתָם מִן הָעוֹלָם, כַּכָּתוּב (זכריה יד) וְזאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף ה' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלִם הָמֵק בְּשָׂרוֹ וְהוּא עֹמֵד עַל רַגְלָיו."],[4,"","רַבִּי אַבָּא אָמַר מִשְּׁמוֹ שֶׁל רַב יֵיסָא סָבָא, וְכָךְ אָמַר רַבִּי שִׁמְעוֹן, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת אֶת כָּל אוֹתָם הַמְּלָכִים שֶׁהֵצִיקוּ לְיִשְׂרָאֵל וְלִירוּשָׁלַיִם, אֶת אַנְדְּרִיאָנוּס, לְלוּפִינוֹס, וּנְבוּכַדְנֶצַּר, וּלְסַנְחֵרִיב, וּלְכָל שְׁאָר מַלְכֵי הָעַמִּים שֶׁהֶחֱרִיבוּ בֵיתוֹ, וּלְהַשְׁלִיט אוֹתָם כְּבַתְּחִלָּה, וְיִתְכַּנְּסוּ עִמָּהֶם שְׁאָר הָעַמִּים. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִפָּרַע מֵהֶם בְּגָלוּי סְבִיב יְרוּשָׁלַיִם. זֶהוּ שֶׁכָּתוּב וְזאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף ה' אֶת כָּל הָעַמִּים אֲשֶׁר צָבְאוּ עַל יְרוּשָׁלם. אֲשֶׁר יִצְבְּאוּ לֹא כָתוּב, אֶלָּא אֲשֶׁר צָבְאוּ. אָז כָּתוּב וּבְרֹב גְּאוֹנְךְ תַּהֲרֹס קָמֶיךְ. וְזֶה לִזְמַן שֶׁיָּבֹא הַמָּשִׁיחַ כָּתוּב, וְשִׁירָה זוֹ הִיא שִׁירַת הָעוֹלָמִים."],[5,"","וּבְרוּחַ אַפֶּיךְ נֶעֶרְמוּ מַיִם - בְּאוֹתוֹ זְמַן. וּמִשּׁוּם כָּךְ יֵשׁ בְּאוֹתוֹ זְמַן, וְלִזְמַנּוֹ שֶׁל מֶלֶךְ הַמָּשִׁיחַ, וְלִזְמַן גּוֹג וּמָגוֹג. נִצְּבוּ כְמוֹ נֵד - לִזְמַן שֶׁל עוֹלָם הַבָּא, שֶׁהִיא חֶדְוַת כָּל הָעוֹלָמוֹת."],[6,"","אָמַר אוֹיֵב אֶרְדּף אַשִּׂיג אֲחַלֵּק שָׁלָל. אָמַר אוֹיֵב - זֶה אוֹתוֹ מְמֻנֶּה גָּדוֹל עַל הַמִּצְרִים, בְּשָׁעָה שֶׁנִּתָּן לוֹ שִׁלְטוֹן עַל יִשְׂרָאֵל, חָשַׁב שֶׁיַּשְׁמִיד אוֹתָם תַּחַת שִׁלְטוֹנוֹ, אֶלָּא שֶׁזָּכַר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָרֵי הָעוֹלָם שֶׁהָיוּ מְגִנִּים עֲלֵיהֶם. וְאַל תֹּאמַר זֶה לְבַדּוֹ, אֶלָּא כָּל אוֹתָם גְּדוֹלִים שֶׁמְּמֻנִּים עַל עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. וּכְשֶׁנִּתְּנָה לָהֶם רְשׁוּת וְשִׁלְטוֹן עַל יִשְׂרָאֵל, כֻּלָּם רוֹצִים לְהַשְׁמִיד אֶת יִשְׂרָאֵל תַּחְתֵּיהֶם."],[7,"","וְעַל זֶה, אוֹתָם עַמִּים שֶׁתַּחַת אוֹתָם הַשַּׁלִּיטִים הַמְמֻנִּים, כֻּלָּם גּוֹזְרִים גְּזֵרוֹת לְהַשְׁמִיד אוֹתָם, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אֶת הָרֵי הָעוֹלָם, וּמֵגֵן עֲלֵיהֶם. וּכְשֶׁרָאָה אֶת זֶה מֹשֶׁה, הִתְחִיל לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְאָמַר, מִי כָמֹכָה בָּאֵלִם ה'."],[8,"","אָמַר רַבִּי שִׁמְעוֹן, עֵץ גָּדוֹל אֶחָד עֶלְיוֹן וְחָזָק, בּוֹ נִזּוֹנוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְהוּא מֻתְחָם בִּשְׁנֵים עָשָׂר תְּחוּמִים, הִתְחַזֵּק בְּאַרְבָּעָה צִדְדֵי הָעוֹלָם שֶׁהִסְתּוֹבְבוּ (שהתחברו) בִמְקוֹמָם. שִׁבְעִים עֲנָפִים עוֹלִים בְּתוֹכוֹ וְנִזּוֹנִים מִמֶּנּוּ, בְּעִקַּר שָׁרָשָׁיו יוֹנְקִים הֵם סְבִיבוֹ, וְאוֹתָם הָעֲנָפִים שֶׁנִּמְצָאִים בָּעֵץ."],[9,"","כְּשֶׁמַּגִּיעַ שִׁלְטוֹנוֹ שֶׁל כָּל עָנָף וְעָנָף, כֻּלָּם רוֹצִים לְהַשְׁמִיד אֶת כָּל גּוּף הָעֵץ שֶׁהוּא עִקָּר שֶׁל כָּל הָעֲנָפִים, אוֹתוֹ שֶׁשּׁוֹלֵט עֲלֵיהֶם, וְיִשְׂרָאֵל אֲחוּזִים בּוֹ. כְּשֶׁמַּגִּיעַ עֲלֵיהֶם הַשִּׁלְטוֹן שֶׁל אוֹתוֹ גּוּף הָעֵץ, הַחֵלֶק שֶׁל יִשְׂרָאֵל, הוּא רוֹצֶה לִשְׁמֹר אוֹתָם וְלָתֵת שָׁלוֹם בְּכֻלָּם, וְעַל זֶה שִׁבְעִים פָּרִים שֶׁל חַג הַסֻּכּוֹת, לָתֵת שָׁלוֹם לְשִׁבְעִים עֲנָפִים שֶׁבְּתוֹךְ הָעֵץ."]]],[["וְעַל דָּא מִי כָמוֹכָה בָּאֵלִים יְיָ'. (מאי באלים. אילנא. כמה דאת אמרז, (ישעיהו א׳:כ״ט) כי יבושו מאילים אשר חמדתם. דהוא אילנא, דהוו פלחין לחד דפוסא, דמחקקין בגויה. ואקרי אלים אילנא) מִי כָּמֹכָה דְּיַעֲבֵיד כְּעוֹבָדָךְ וִירַחֵם עַל כֹּלָּא. מִי כָּמֹכָה בְּכָל הַהוּא סַחֲרָנֵיהּ דְּאִילָנָא דְּאַף עַל גַּב דְּאִיהוּ שַׁלְטָא, נָטִיר לְכֹלָּא, נָטִיר לְכָל שְׁאַר, וְלָא בַּעְיָא לְמֶעְבַּד עִמְּהוֹן גְּמִירָא. מִי כָּמֹכָה נְאְדָּר בַּקֹּדֶשׁ, בְּהַהוּא חֵילָא עִלָּאָה דְּאִקְרֵי קֹדֶשׁ. נֶאְדָּר בַּקֹּדֶשׁ מַמָּשׁ, וְאִקְרֵי כֹּחַ יְיָ' נֹעַם יְיָ', וְהָא אוֹקִימְנָא מִילֵי.","(שמות ט״ו:י״א) מִי כָּמֹכָה בָּאֵלִים יְיָ'. ר' יוֹסֵי פָּתַח (קהלת א׳:י״ד) רָאִיתִי אֶת כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ וְהִנִּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ. שְׁלֹמֹה מַלְכָּא, דְּאִסְתַּלָּק בְּחָכְמְתָא יְתֵירָא עַל כָּל בְּנֵי עָלְמָא, הֵיךְ אָמַר דְּכָל עוֹבָדִין הֶבֶל וּרְעוּת רוּחַ. יָכוֹל אַף מַעֲשֵׂה הַצְּדָקָה, וְהָא כְּתִיב (ישעיהו ל״ב:י״ז) וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם. אֶלָּא הָא אוּקְמוּהָ, כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ כְּתִיב. שָׁאנִי מַעֲשֵׂה הַצְּדָקָה, דְּאִיהוּ לְעֵילָּא מִן שִׁמְשָׁא.","וְהִנֵּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ, מַאי קָא מַיְירֵי. אִי תֵּימָא הַכֹּל הֶבֶל כְּמָה דְּאוֹקִימְנָא, דְּאִיהוּ בְּרָזָא דְּחָכְמְתָא, כְּמָה דְאַתְּ אָמֵר הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת, וְאִינּוּן הֲבָלִים קִיּוּמָא דְּעָלְמָא דִּלְעֵילָּא וְתַתָּא. מַאי תֵּימָא בְּהַאי, דִּכְתִּיב הָכָא, הַכֹּל הֶבֶל וּרְעוּת רוּחַ. (והא מלתא דא תחת השמש כתיב)","אֶלָּא הָכִי אוּקְמוּהָ, וְהָכִי הוּא. תָּא חֲזֵי, בְּשַׁעֲתָא דְּעוֹבָדִין מִתְכַּשְּׁרָן לְתַתָּא, וּבַר נָשׁ אִשְׁתַּדַּל בְּפוּלְחָנָא דְּמַלְכָּא קַדִּישָׁא, הַהוּא מִלָּה דְּעָבִיד, הֶבֶל אִתְעָבִיד מִינֵּיהּ לְעֵילָּא. וְלֵית לָךְ הֶבֶל, דְּלֵית לֵיהּ קָלָא, דְּסָלִיק וְאִתְעַטָּר לְעֵילָּא, וְאִתְעָבִיד סַנֵּיגוֹרָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.","וְכָל אִינּוּן עוֹבָדִין דְּאִשְׁתַּדַּל בְּהוּ בַּר נָשׁ, דְּלָאו אִינּוּן פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הַהוּא מִלָּה דְּעָבִיד, הַבָל יִתְעֲבִיד מִינֵּיהּ, וְאַזְלָא וְשָׁאטַת בְּעָלְמָא. וְכַד נַפְקַת נִשְׁמָתֵיהּ דְּבַר נָשׁ, הַהוּא הֶבֶל מְגַלְגְּלָא לֵיהּ בְּעָלְמָא, כְּאַבְנָא בְּקוּסְפִיתָא, כְּמָה דִּכְתִּיב, (שמואל א כ״ה:כ״ט) וְאֶת נֶפֶשׁ אוֹיְבֶיךָ יְקַלְעֶנָּה בְּתוֹךְ כַּף הַקָּלַע.","מַאי יְקַלְעֶנָּה. הַהוּא הֶבֶל דִּמְגַלְגֵּל לֵיהּ סַחֲרָנֵיהּ בְּעָלְמָא, כְּדֵין כָּל מִלִּין דְּמִתְעַבְּדִין (ואינון דתחות שמשא) דְּלָאו אִינּוּן פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הֶבֶל יִתְעֲבִיד מִנַּיְיהוּ, אִיהוּ תְּבִירָא דְּרוּחָא, דְּמִתָּבַּר לְרוּחָא דְּסָלִיק וְנָחִית וּמִתְגַּלְגֵּל בְּעָלְמָא, הֲדָא הוּא דִכְתִיב הֶבֶל וּרְעוּת רוּחַ.","אֲבָל הַהִיא מִלָּה דְּאִיהִי פּוּלְחָנָא דְּמָרֵיהּ דָּא סָלִיק (אקרי) לְעֵילָּא מִן שִׁמְשָׁא, וְאִתְעָבִיד מִנֵּיהּ הֶבֶל קַדִּישָׁא, וְדָא הוּא זַרְעָא דְּזָרַע בַּר נָשׁ בְּהַהוּא עָלְמָא, וּמַה שְּׁמֵיהּ. צְדָקָה. דִּכְתִּיב, (הושע י׳:י״ב) זִרְעוּ לָכֶם לִצְדָקָה.","הַאי מֵדֲבַּר לֵיהּ לְבַר נָשׁ, כַּד תִּיפּוּק נִשְׁמָתֵיהּ מִינֵּיהּ, וְסַלְּקָא לָהּ בְּאַתְרָא דְּכָבוֹד דִּלְעֵילָּא אִשְׁתְּכַח לְאִתְצַרְרָא בִּצְרוֹרָא דְּחַיֵּי, הֲדָא הוּא דִכְתִיב, (ישעיה כח) וְהָלַךְ לְפָנֶיךָ צִדְקֶךָ בְּגִין לְדַבְּרָא לָךְ, לְסַלְּקָא לָךְ, (מן אתר) לַאֲתָר דְּאִקְרֵי כְּבוֹד יְיָ'. דִּכְתִּיב, (ישעיה כח) כְּבוֹד יְיָ' יַאַסְפֶךָ.","כָּל אִינּוּן נִשְׁמָתִין, דְּהַהוּא הֶבֶל קַדִּישָׁא מֵדֲבַּר לְהוּ, הַהוּא דְּאִקְרֵי כְּבוֹד יְיָ', כָּנִישׁ לוֹן בְּגַוֵּיהּ, וְאִתְצְרִירָן בֵּיהּ. (הדא הוא דכתיב כבוד ה' יאספך) וְדָא אִקְרֵי נַיְיחָא דְּרוּחָא. אֲבָל אַחֲרָא וּרְעוּת רוּחַ אִקְרֵי. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּכָל עוֹבָדֵיהוֹן לְעֵילָּא מִן שִׁמְשָׁא וְזַרְעִין זַרְעָא דִּצְדָקָה, לְמִזְכֵּי לוֹן לְעָלְמָא דְּאָתֵי, וְעַל דָּא כְּתִיב (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה.","אָמַר רִבִּי שִׁמְעוֹן, תָּא חֲזֵי, בְּקַדְמִיתָא כַּד אִתְבְּנִי בֵּי מַקְדְּשָׁא לְתַתָּא, לָא אִתְבְּנִי אֶלָּא בְּדִינָא וְרוּגְזָא, כְּמָה דִּכְתִּיב, (ירמיהו ל״ב:ל״א) כִּי עַל אַפִּי וְעַל חֲמָתִי וְגוֹ' בְּגִין דִּבַאֲתָר דְּדִינָא שַׁרְיָא. לְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִבְנֵי לֵיהּ, וּלְאַתְקְנָא לֵיהּ בְּדַרְגָּא אַחֲרָא עִלָּאָה דְּאִקְרֵי צְדָקָה, דִּכְתִּיב, (ישעיהו נ״ד:י״ד) בִּצְדָקָה תִּכּוֹנָנִי. בְּגִין כַּךְ אִתְקַיָּים, (ביה) וּשְׁמֵיהּ מַמָּשׁ צֶדֶק יִתְקְרֵי. מְנָלָן. דִּכְתִּיב, (ירמיהו כ״ג:ו׳) וְזֶה שְׁמוֹ אֲשֶׁר יִקְרֵאוֹ יְיָ' צִדְקֵנוּ."],[[0,"ועל דא מי וכו':","ועל זה נאמר מה כמוכה באלים ה'. מהו באלים. אילן, כמש\"א כי יבושו מאלים אשר חמדתם. שהוא אילן שהיו עובדים לצורה אחת שהיתה חקוקה בתוכו. מי כמוכה שיעשה כמעשיך וירחם על כל. מי כמוכה בכל סביבות האילן, שאע\"פ ששולט שומר את הכל שומר לכל השאר, ואינו רוצה לעשות עמהם כליה, כמו שהם היו רוצים בזמן שליטתם. מי כמוכה נאדר בקדש. היינו שנאדר בכח העליון שנקרא קדש. נאדר בקדש ממש. שהם המוחין דבינה. ונקרא כח ה', נעם ה'. והרי העמדנו הדברים."],[1,"מי כמוכה באלים ה':","ר' יוסי פתח, ראיתי את כל המעשים וגו' הבל ורעות רוח, שואל, שלמה המלך, שעלה בחכמתו יותר על כל בני העולם, איך אמר, שכל המעשים הם הבל ורעות רוח. יכול, אף מעשה הצדקה הוא הבל ורעות רוח, הלא כתוב, והיה מעשה הצדקה שלום. ומשיב. אלא, הרי העמדנו, כל המעשים אשר נעשו תחת השמש כתוב, ומשונה הוא מעשה הצדקה, שהוא למעלה מן השמש."],[2,"והנה הכל הבל ורעות רוח:","שואל מה פירושו. אם תאמר, הכל הבל פירושו כמו שהעמדנו, שהיא בסוד החכמה כמש\"א, הבל הבלים אמר קהלת והבלים אלו הם קיום עולם העליון ותחתון. (כנ\"ל בא ד' מ\"א אות קמ\"ג) מהו תאמר בזה שכתוב כאן, הנה הבל ורעות רוח."],[3,"אלא הכי אוקמוה וכו':","אלא כך העמדנו, וכך הוא. בוא וראה, בשעה שהמעשים טובים בעולם, והאדם עוסק בעבודת המלך הקדוש, הנה דבר ההוא שעושה נעשה ממנו הבל למעלה. ואין לך הבל, שאין לו קול שעולה למעלה ונעשה סנגור לפני הקב\"ה."],[4,"וכל אינון עובדין וכו':","וכל אלו המעשים, שעוסק בהם האדם ואינם עבודת הקב\"ה, דבר ההוא שעשה נעשה ממנו הבל, והולך ומשוטט בעולם. וכשיוצאת נשמתו, הבל ההוא מגלגל אותו בעולם, כאבן בכף הקלע. כמ\"ש, ואת נפש אויביך יקלענה בתוך כף הקלע."],[5,"מאי יקלענה:","שואל מהו יקלענה. ומשיב, הבל ההוא מגלגל אותו סביב בעולם. אז, כל הדברים שנעשים ואינם עבודת הקב\"ה, נעשה מהם הבל, שהוא שבירת הרוח שמשבר את הרוח, העולה ויורד ומתגלגל בעולם. ז\"ש הבל ורעות רוח."],[6,"אבל ההיא מלה וכו':","אבל דבר ההוא שהוא עבודת רבונו, זה עולה למעלה מן השמש, ונעשה ממנו הבל קדוש, וזה הוא זרע שזורע האדם בעולם ההוא, ומה שמו. צדקה. שכתוב, זרעו לכם לצדקה."],[7,"האי מדבר ליה וכו':","זה מנהיג את האדם כשנשמתו יצאה ממנו, ומעלה אותו במקום הכבוד למעלה, ונמצא לצרור אותו בצרור החיים. ז\"ש והלך לפניך צדקך. כדי לנהוג אותך, ולהעלותך למקום שנקרא כבוד ה', שהוא המלכות, שכתוב, וכבוד ה' יאספך."],[8,"כל אינון נשמתין וכו':","כל אלו הנשמות, שהבל ההוא הקדוש מנהיג אותם, ההוא שנקרא כבוד ה', מאספם בתוכו ונצררים בו. ואז הוא נחת רוח. אבל הבל האחר, שאינו עבודת הקב\"ה, נקרא, ורעות רוח. אשריהם הצדיקים שכל מעשיהם הם למעלה מן השמש, דהיינו עבודת הקב\"ה, וזורעים זרע הצדקה לזכות אותם לעולם הבא. ועל זה כתוב, וזרחה לכם שמש יראי שמי שמש צדקה."],[9,"אמר ר' שמעון וכו':","אר\"ש, בוא וראה, בתחילה כשנבנה בית המקדש למטה, לא נבנה אלא בדין ורגז, כמ\"ש, כי על אפי ועל חמתי וגו'. משום שהוא במקום שהדין שורה. לעתיד לבא, עתיד הקב\"ה לבנות אותו ולתקנו במדרגה אחרת עליונה, הנקראת צדקה. שהיא מלכות המתוקנת, שכתוב, בצדקה תכונני. משום זה יתקיים ולא יחרב עוד. ושמו ממש יקרא צדק. מאין לנו. שכתוב, וזה שמו אשר יקראו ה' צדקינו."]],[[0,"","וְעַל זֶה מִי כָמֹכָה בָּאֵלִם ה'. (מה זה באלים, העץ, כמו שנאמר (ישעיה א) כי יבשו מאילים אשר חמדתם. שאותו עץ שהיו עובדים לדפוס אחד שהיה חקוקבתוכו, ונקרא אילים עץ) מִי כָמֹכָה שֶׁיַּעֲשֶׂה כְּמַעֲשֶׂיךְ וִירַחֵם עַל הַכֹּל. מִי כָמֹכָה בְּכָל אוֹתוֹ סְבִיב הָעֵץ, שֶׁאַף עַל גַּב שֶׁהוּא שׁוֹלֵט - שׁוֹמֵר אֶת הַכֹּל, שׁוֹמֵר אֶת כָּל הַשְּׁאָר, וְלֹא רוֹצֶה לַעֲשׂוֹת עִמָּהֶם כִּלָּיוֹן. מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ - בְּאוֹתוֹ כֹּחַ עֶלְיוֹן שֶׁנִּקְרָא קֹדֶשׁ, נֶאְדָּר בַּקֹּדֶשׁ מַמָּשׁ, וְנִקְרָא כֹּחַ ה' נֹעַם ה', וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים."],[1,"","מִי כָמֹכָה בָּאֵלִם ה'. רַבִּי יוֹסֵי פָּתַח, (קהלת א) רָאִיתִי אֶת כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ וְהִנֵּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ. שְׁלֹמֹה הַמֶּלֶךְ שֶׁהִתְעַלָּה בְּחָכְמָה יְתֵרָה עַל כָּל בְּנֵי הָעוֹלָם, אֵיךְ אָמַר שֶׁכָּל הַמַּעֲשִׂים הֵם הֶבֶל וּרְעוּת רוּחַ? יָכוֹל אַף מַעֲשֵׂה הַצְּדָקָה? וַהֲרֵי כָּתוּב (ישעיה לב) וְהָיָה מַעֲשֵׂה הַצְּדָקָה שָׁלוֹם? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, כָּתוּב כָּל הַמַּעֲשִׂים אֲשֶׁר נַעֲשׂוּ תַּחַת הַשָּׁמֶשׁ. שׁוֹנֶה מַעֲשֵׂה הַצְּדָקָה, שֶׁהוּא לְמַעְלָה מִן הַשֶּׁמֶשׁ."],[2,"","וְהִנֵּה הַכֹּל הֶבֶל וּרְעוּת רוּחַ, מַה זֶּה אוֹמֵר? אִם תֹּאמַר הַכֹּל הֶבֶל כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהוּא בְּסוֹד הַחָכְמָה, כְּמוֹ שֶׁנֶּאֱמַר הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת. וְאוֹתָם הֲבָלִים קִיּוּם שֶׁל הָעוֹלָם שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה. מַה תֹּאמַר בָּזֶה שֶׁכָּתוּב כָּאן הַכֹּל הֶבֶל וּרְעוּת רוּחַ? (והרי דבר זה תחת השמש כתוב)."],[3,"","אֶלָּא כָּךְ פֵּרְשׁוּהָ וְכָךְ הוּא. בֹּא רְאֵה, בְּשָׁעָה שֶׁהַמַּעֲשִׂים מֻכְשָׁרִים לְמַטָּה וְאָדָם מִשְׁתַּדֵּל בַּעֲבוֹדַת הַמֶּלֶךְ הַקָּדוֹשׁ - מֵאוֹתוֹ דָּבָר שֶׁעוֹשֶׂה, נַעֲשֶׂה מִמֶּנּוּ הֶבֶל לְמַעְלָה, וְאֵין לְךְ הֶבֶל שֶׁאֵין לוֹ קוֹל שֶׁעוֹלֶה וּמִתְעַטֵּר לְמַעְלָה, וְנַעֲשֶׂה סָנֵגוֹר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[4,"","וְכָל אוֹתָם מַעֲשִׂים שֶׁמִּשְׁתַּדֵּל בָּהֶם הָאָדָם שֶׁאֵינָם עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא - מֵאוֹתוֹ דָּבָר שֶׁעוֹשֶׂה, נַעֲשֶׂה מִמֶּנּוּ הֶבֶל, וְהוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם. וּכְשֶׁיּוֹצֵאת נִשְׁמַת הָאָדָם, אוֹתוֹ הֶבֶל מְגַלְגֵּל אוֹתוֹ בָּעוֹלָם כְּאֶבֶן בְּכַף הַקֶּלַע, כַּכָּתוּב (שמואל א כה) וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע."],[5,"","מַהוּ יְקַלְּעֶנָּה? אוֹתוֹ הֶבֶל שֶׁמְּגַלְגֵּל אוֹתוֹ סְבִיבוֹ בָּעוֹלָם, וְאָז כָּל הַדְּבָרִים שֶׁנַּעֲשִׂים (ואותם שתחת השמים) שֶׁאֵינָם עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, נַעֲשֶׂה מֵהֶם הֶבֶל, שֶׁהוּא שִׁבְרוֹן רוּחַ, שֶׁמְּשַׁבֵּר אֶת הָרוּחַ שֶׁעוֹלָה וְיוֹרֶדֶת וּמִתְגַּלְגֶּלֶת בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב הֶבֶל וּרְעוּת רוּחַ."],[6,"","אֲבָל אוֹתוֹ דָּבָר שֶׁהוּא עֲבוֹדַת רִבּוֹנוֹ, זֶה עוֹלֶה (נקרא) מֵעַל לַשֶּׁמֶשׁ, וְנַעֲשֶׂה מִמֶּנּוּ הֶבֶל קָדוֹשׁ, וְזֶהוּ הַזֶּרַע שֶׁזָּרַע הָאָדָם בְּאוֹתוֹ עוֹלָם, וּמַה שְּׁמוֹ? צְדָקָה, שֶׁכָּתוּב (הושע י) זִרְעוּ לָכֶם לִצְדָקָה."],[7,"","זְהִ מַה שֶּׁמַּנְהִיג אֶת הָאָדָם, כְּשֶׁתֵּצֵא מִמֶּנּוּ נִשְׁמָתוֹ, וְעוֹלָה לָהּ לְמָקוֹם שֶׁל כָּבוֹד שֶׁלְּמַעְלָה נִמְצָא לְהִצָּרֵר בִּצְרוֹר הַחַיִּים. זֶהוּ שֶׁכָּתוּב (ישעיהנח) וְהָלַךְ לְפָנֶיךְ צִדְקֶךְ, כְּדֵי לְהַנְהִיג אוֹתְךְ, לְהַעֲלוֹת אוֹתְךְ (ממקום) לְמָקוֹם שֶׁנִּקְרָא כְּבוֹד ה', שֶׁכָּתוּב כְּבוֹד ה' יַאַסְפֶךְ."],[8,"","כָּל אוֹתָן נְשָׁמוֹת שֶׁאוֹתוֹ הֶבֶל קָדוֹשׁ מַנְהִיג אוֹתָן, אוֹתוֹ שֶׁנִּקְרָא כְּבוֹד ה' כּוֹנֵס אוֹתָן לְתוֹכוֹ וְנִצְרָרוֹת בּוֹ. (זהו שכתוב כבוד ה' יאספך) וְזֶה נִקְרָא נַחַת רוּחַ. אֲבָל הָאַחֵר נִקְרָא רְעוּת רוּחַ. אַשְׁרֵי הַצַּדִּיקִים שֶׁכָּל מַעֲשֵׂיהֶם מֵעַל לַשֶּׁמֶשׁ, וְזוֹרְעִים זֶרַע שֶׁל צְדָקָה לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא, וְעַל זֶה כָּתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה."],[9,"","אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, בַּתְּחִלָּה כְּשֶׁנִּבְנָה בֵּית הַמִּקְדָּשׁ לְמַטָּה, לֹא נִבְנָה אֶלָּא בְּדִין וְרֹגֶז, כַּכָּתוּב (ירמיה לב) כִּי עַל אַפִּי וְעַל חֲמָתִי וְגוֹ', מִשּׁוּם שֶׁבִּמְקוֹם הַדִּין שָׁרוּי. לֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת אוֹתוֹ וּלְהַתְקִינוֹ בְּדַרְגָּה אַחֶרֶת עֶלְיוֹנָה שֶׁנִּקְרֵאת צְדָקָה, שֶׁכָּתוּב (ישעיה נד) בִּצְדָקָה תִּכּוֹנָנִי. מִשּׁוּם כָּךְ יִתְקַיֵּם (בו), וּשְׁמוֹ מַמָּשׁ יִקָּרֵא צֶדֶק. מִנַּיִן לָנוּ? שֶׁכָּתוּב (ירמיה כג) וְזֶה שְּׁמוֹ אֲשֶׁר יִקְרְאוֹ ה' צִדְקֵנוּ."]]],[["(שמות ט״ו:י״ב) נָטִיתָ יְמִינְךָ תִּבְלָעֵמוֹ אָרֶץ. הָא אִתְּמַר, אֲרִימַת יְמִינְךָ. אָמַר רִבִּי יִצְחָק, הָא אִתְּעָרוּ בֵּיהּ חַבְרַיָּיא, דְּכַד אַפִּיק קוּדְשָׁא בְּרִיךְ הוּא לְמִצְרָאֵי מֵתִין מִתְּחוֹת מַיָּא, אָמַר לְאַרְעָא, כָּנִישׁ לוֹן בְּגַוָּוךְ, וְלָא בָּעָאת, עַד דְּאוֹשִׁיט קוּדְשָׁא בְּרִיךְ הוּא יְמִינָא לְקַבְּלָהּ, וְאוּמֵי לָהּ, כְּדֵין בְּלָעַתְינוּן אַרְעָא, הֲדָא הוּא דִכְתִיב תִּבְלָעֵמוֹ אָרֶץ. אָמַר ר' אֶלְעָזָר, נָטִיתָ יְמִינְךָ: לְאַפְרְשָׁא לָהּ מִשְּׂמָאלָא וּכְדֵין אִתְעָבִיד בְּהוּ דִּינָא.","(שמות ט״ו:י״ג) נָחִיתָ בְּחַסְדְּךָ עַם זוּ גָּאָלְתָּ, כְּמָה דִּכְתִּיב, (תהלים מה) כִּי יְמִינְךָ וּזְרוֹעֲךָ וְאוֹר פָּנְיךָ כִּי רְצִיתָם. כִּי יְמִינְךָ: דָּא גְּדוֹלָה. נֵהַלְתָּ בְעָזְּךָ, דָּא דִּכְתִּיב וּזְרוֹעֲךָ, דָּא גְּבוּרָה. אֶל נְוֵה קָדְשֶׁךָ, דָּא דִּכְתִּיב, וְאוֹר פָּנְיךָ כִּי רְצִיתָם, דָּא צַדִּיק. וְכֻלְּהוּ מִשְׁתַּכְּחֵי בִּקְרָא.","(שמות ט״ו:ט״ז) תִּפּוֹל עֲלֵיהֶם אֵימָתָה וָפַחַד. אֵימָתָה, אֵימָה מִבָּעֵי לֵיהּ, מַאי אֵימָתָה. דְּהָא לֵית לָךְ אָת אוֹ מִלָּה חֲדָא בְּאוֹרַיְיתָא, דְּלָא אִית בָּהּ רָזִין עִלָּאִין. מַאי אֵימָתָה. אָמַר רִבִּי שִׁמְעוֹן, כְּלוֹמַר דְּחִילוּ דִּשְׁכִינְתָּא.","כְּהַאי גַּוְונָא, (שמות ט״ו:י״ז) תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךָ וְגוֹ', תְּבִאֵמוֹ וְתִטָּעֵמוֹ, תְּבִאֵם וְתִטָּעֵם מִבָּעֵי לֵיהּ, מַאי תְּבִאֵמוֹ. אֶלָּא רוּחָא דְּקוּדְשָׁא אָמַר, עַל אִינּוּן דָּרָא בַּתְרָאָה, דְּגָזַר יְהוֹשֻׁעַ, וְאִתְגַּלְיָא בְּהוּ גִּלּוּיָא דִּרְשִׁימָא קַדִּישָׁא דִּשְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּאִלֵּין אֲחִידָן בֵּיהּ בְּו', וְאִלֵּין אִתְחֲזִיאוּ לְמֵירַת אַרְעָא. כְּמָה דִּכְתִּיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. דְּכָל מַאן דְּאִתְגְּזַר, וְאִתְגַּלְיָא בֵּיהּ רְשִׁימָא קַדִּישָׁא, וְנָטִיר לֵיהּ, אִקְרֵי צַדִּיק, בְּגִין, כַּךְ, לְעוֹלָם יִירְשׁוּ אָרֶץ.","וְעַל דָּא תְּבִאֵמוֹ, ו' יְתֵירָה, תְּבִיאֵמוֹ לְאִינוּן דַּאֲחִידָן בְּו'. וְתִטָּעֵמוֹ כְּמָה דְאַתְּ אָמֵר נִצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. לְאִינוּן דַּאֲחִידָן בְּו', וּלְאִינּוּן בַּתְרָאֵי, אִתְּעַר מִלָּה. וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת זְעֵירָא בְּאוֹרַיְיתָא, דְּלֵית בָּהּ רָזִין עִלָּאִין, וְטַעֲמִין קַדִּישִׁין, זַכָּאָה חוּלָקֵיהוֹן דְּיַדְעִין בְּהוּ.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא לְמִבְנֵי מַקְדְּשָׁא לְתַתָּא, כְּגַוְונָא דְּבֵי מַקְדְּשָׁא דִּלְעֵילָּא, כְּמָה דְאַתְּ אָמֵר, מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ'. דְּאִצְטְרִיךְ לְמִבְנֵי בֵּי מַקְדְּשָׁא לְתַתָּא, וּלְצַלָּאָה בְּגַוֵּיהּ צְלוֹתָא בְּכָל יוֹמָא, לְמִפְלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דְּהָא צְלוֹתָא אִקְרֵי עֲבוֹדָה.","וְהַהוּא בֵּי כְּנִשְׁתָּא, אִצְטְרִיךְ לְמִבְנֵי לֵיהּ בִּשְׁפִירוּ סַגְיָא, וּלְאַתְקְנָא לֵיהּ בְּכָל תִּקּוּנִין, דְּהָא בֵּי כְּנִשְׁתָּא דִּלְתַתָּא, קַיְּימָא לָקֳבֵל בֵּי כְּנִשְׁתָּא דִּלְעֵילָּא.","בֵּית הַמִקְדָּשׁ לְתַתָּא, אִיהוּ קָאִים כְּגַוְונָא דְּבֵית הַמִּקְדָּשׁ דִּלְעֵילָּא, דְּקָאִים דָּא לָקֳבֵל דָּא. וְהַהוּא בֵּי מַקְדְּשָׁא, כָּל תִּקּוּנוֹי, וְכָל פּוּלְחָנוֹי, וְכָל אִינּוּן מָאנִין, וְשַׁמָּשִׁין, כֻּלְּהוּ אִינּוּן כְּגַוְונָא דִּלְעֵילָּא. מַשְׁכְּנָא דְּקָא עָבֵד מֹשֶׁה בְּמַדְבְּרָא, כֹּלָּא הֲוָה כְּגַוְונָא דִּלְעֵילָּא.","בֵּי מַקְדְּשָׁא דְּבָנָא שְׁלמֹה מַלְכָּא, הוּא בֵּי נַיְיחָא כְּגַוְונָא עִלָּאָה, בְּכָל אִינּוּן תִּקּוּנִין, לְמֶהֱוֵי בְּתִקּוּנָא דִּלְעֵילָּא, בֵּי נַיְיחָא וְאַחֲסַנְתָּא. הָכִי בֵּי כְּנִשְׁתָּא, אִצְטְרִיךְ בְּכָל תִּקּוּנֵי שַׁפִּירוּ, לְמֶהֱוֵי כְּגַוְונָא עִלָּאָה, לְמֶהֱוֵי בֵּית צְלוֹתָא, לְאַתְקְנָא תִּקּוּנִין בִּצְלוֹתָא, כְּמָה דְּאוּקְמוּהָ.","וְהַהוּא בֵּי מַקְדְּשָׁא דְּלֶיהֱוִי בֵּיהּ (רנ\"א ע\"א) חַלּוֹנוֹת, דִּכְתִּיב, (דניאלו) וְכַוִּון פְּתִיחָן. כְּגַוְונָא דִּלְעֵילָּא, וְעַל דָּא (שיר השירים ב׳:ט׳) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים. וְאִי תֵּימָא אֲפִילּוּ בְּחַקְלָא, בְּגִין דְּרוּחָא לֶהֱוֵי סָלִיק. לָאו הָכִי, דְּהָא אֲנָן צְרִיכִין בַּיִת וְלֵיכָּא. לְאִשְׁתַּכְּחָא בַּיִת לְתַתָּא, כְּגַוְונָא דְּבַיִת עִלָּאָה, לְנַחְתָּא דִּיּוּרָא עִלָּאָה לְדִיּוּרָא תַּתָּאָה."],[[0,"נטית ימינך תבלעמו ארץ:","הוקשה לו, הלא הימין פועל חסד. ואומר. הרי למדנו שפירושו הרימות ידך. ונשאר השמאל לבדו ועשה דין. (כנ\"ל אות רסד) אמר ר' יצחק, הרי העירו בה החברים, כשהוציא הקב\"ה את המצרים מתים מתחת המים, אמר לארץ, אסוף אותם בתוכך. ולא רצתה עד שהושיט הקב\"ה את הימין כנגדה, והשביע אותה, אז בלעתם הארץ. ז\"ש תבלעמו ארץ. ר' אלעזר אומר, נטית ימינך, פירושו, להפריד אותה מן השמאל, ואז נעשה הדין בשמאל."],[1,"נחית בחסדך עם זו גאלת וגו':","הוא כמו שכתוב, כי ימינך וזרועך ואור פניך כי רציתם. \u0003כי ימינך\u0004 זה גדולה, דהיינו חסד. \u0003נהלת בעזך,\u0004 זהו שכתוב, \u0003וזרועך,\u0004 זהו גבורה. \u0003אל נוה קדשך,\u0004 זהו שכתוב, \u0003ואור פניך כי רציתם,\u0004 זהו צדיק, שהוא יסוד. וכולם נמצאים בכתוב. כל שש הספירות. כי חסד וגבורה כוללים ת\"ת. ויסוד כולל נו\"ה."],[2,"תפול עליהם אימתה ופחד:","שואל אימתה, היה צריך לומר אימה, מהו אימתה. שהרי אין לך אות או מלה אחת בתורה, שאין בה סודות עליונים. וא\"כ, מהו אימתה. אמר ר' שמעון, כלומר, אימת השכינה. והוא כמו אימת ה' שהיא השכינה."],[3,"כהאי גוונא תביאמו וגו':","כעין זה, תביאמו ותטעמו בהר נחלתך וגו', היה צריך לומר תביאם ותטעם, מהו תביאמו. ומשיב, אלא רוח הקודש אמר, על הדור האחרון שמל יהושע, ונגלה בהם הגילוי של הרשימה הקדושה משמו של הקב\"ה, והם אחוזים בו, שהוא ז\"א, והם ראוים לרשת הארץ, כמ\"ש, ועמך כולם צדיקים לעולם יירשו ארץ. כי כל מי שנמול, ונגלה בו הרשימה הקדושה, ושומר אותו נקרא צדיק, ומשום זה לעולם יירשו ארץ."],[4,"וע\"ד תביאמו וכו':","וע\"כ תביאמו, עם \u0003ו'\u0004 יתירה, שפירושו, תביאמו לאלו שאחוזים ב \u0003ו'\u0004. ותטעמו, כש\"א נצר מטעי וגו', לאותם שנאחזים ב \u0003ו',\u0004 שהוא ז\"א. ולאלו האחרונים שבימי יהושע, רומז הדבר. ואין לך מלה בתורה, או אות קטן בתורה, שאין בה סודות עליונים וטעמים קדושים, אשרי חלקם של היודעים בהם."],[5,"פקודא למבני מקדשא וכו':","מצוה, לבנות בית המקדש של מטה כעין בית המקדש של מעלה. כמש\"א מכון לשבתך פעלת ה'. כי צריך לבנות בית המקדש למטה ולהתפלל בתוכו תפלה בכל יום, לעבוד את הקב\"ה, כי תפלה נקרא עבודה."],[6,"וההוא בי כנשתא וכו':","ובית הכנסת ההוא, צריכים לבנותו ביופי גדול ולתקן אותו בכל התיקונים. כי בית הכנסת למטה עומד כנגד בית הכנסת שלמעלה."],[7,"בית המקדש לתתא וכו':","בית המקדש למטה עומד כעין בית המקדש שלמעלה. שעומדים זה כנגד זה. ובית המקדש ההוא, כל תקוניו, וכל עבודותיו, וכל אלו הכלים, והמשמשים, כולם הם כעין של מעלה. המשכן שעשה משה במדבר, היה הכל כעין של מעלה."],[8,"בי מקדשא דבנה וכו':","בית המקדש שבנה שלמה המלך, הוא בית מנוחה. כעין העליון הוא בכל התקונים שבו, להיות בתקון העליון בית מנוחה ונחלה. כך בית הכנסת צריך להיות בכל תקוני היופי כעין העליון, להיות בית תפלה, לתקן תקונים בתפלה, כמו שהעמידו."],[9,"וההוא בי מקדשא וכו':","ובית המקדש ההוא צריך שיהיה בו חלונות, שכתוב, וכוון פתיחן. כעין של מעלה. וע\"ז, משגיח מן החלונות מציץ מן החרכים. ואם תאמר אפילו בשדה יש להתפלל. משום שעולה שם רוח. אינו כן, כי אנו צריכים בית, ואינו. שצריך להמצא בית למטה כעין בית העליון, שהוא המלכות, להוריד דייר העליון, שהוא השכינה, לדייר התחתון, לבני אדם."]],[[0,"","נָטִיתָ יְמִינְךְ תִּבְלָעֵמוֹ אָרֶץ. הֲרֵי נֶאֱמַר שֶׁהֵרַמְתָּ יְמִינְךְ. אָמַר רַבִּי יִצְחָק, הֲרֵי הִתְעוֹרְרוּ בוֹ הַחֲבֵרִים, שֶׁכַּאֲשֶׁר הוֹצִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַמִּצְרִים מִתַּחַת לַמַּיִם, אָמַר לָאָרֶץ: כַּנְּסִי אוֹתָם לְתוֹכֵךְ. וְלֹא רָצְתָה. עַד שֶׁהוֹשִׁיט הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְמִינוֹ כְּנֶגְדָּהּ וְהִשְׁבִּיעַ אוֹתָהּ, אָז בָּלְעָה אוֹתָם הָאֲדָמָה. זֶהוּ שֶׁכָּתוּב תִּבְלָעֵמוֹ אָרֶץ. אָמַר רַבִּי אֶלְעָזָר, נָטִיתָ יְמִינְךְ - לְהַפְרִידָהּ מִן הַשְּׂמֹאל, וְאָז נַעֲשֶׂה בָּהֶם דִּין."],[1,"","נָחִיתָ בְחַסְדְּךְ עַם זוּ גָּאָלְתָּ, כְּמוֹ שֶׁכָּתוּב (תהלים מד) כִּי יְמִינְךְ וּזְרוֹעֲךְ וְאוֹר פָּנֶיךְ כִּי רְצִיתָם. כִּי יְמִינְךְ - זוֹ גְדוֹלָה. נֵהַלְתָּ בְעָזְךְ - זֶה שֶׁכָּתוּב וּזְרוֹעֲךְ, זוֹ גְבוּרָה. אֶל נְוֵה קָדְשֶׁךְ - זֶה שֶׁכָּתוּב וְאוֹר פָּנֶיךְ כִּי רְצִיתָם, זֶה צַדִּיק. וְכֻלָּם נִמְצָאִים בַּכָּתוּב."],[2,"","תִּפֹּל עֲלֵיהֶם אֵימָתָה וָפַחַד. אֵימָתָה? אֵימָה הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֵימָתָה, שֶׁהֲרֵי אֵין לְךְ אוֹת אוֹ מִלָּה אַחַת בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים? מַה זֶּה אֵימָתָה? אָמַר רַבִּי שִׁמְעוֹן, כְּלוֹמַר יִרְאַת הַשְּׁכִינָה."],[3,"","כְּמוֹ זֶה תְּבִאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךְ וְגוֹ'. תְּבִאֵמוֹ וְתִטָּעֵמוֹ? תְּבִיאֵם וְתִטָּעֵם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה תְּבִאֵמוֹ? אֶלָּא רוּחַ הַקֹּדֶשׁ אוֹמֶרֶת עַל אוֹתוֹ הַדּוֹר הָאַחֲרוֹן שֶׁמָּל יְהוֹשֻׁעַ וְהִתְגַּלָּה בָּהֶם גִּלּוּי שֶׁל הָרֹשֶׁם הַקָּדוֹשׁ שֶׁל שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵלֶּה אֲחוּזִים בְּו', וְאֵלֶּה רְאוּיִים לָרֶשֶׁת אֶת הָאָרֶץ, כַּכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. שֶׁכָּל מִי שֶׁנִּמּוֹל וְהִתְגַּלָּה בּוֹ רֹשֶׁם הַקָּדוֹשׁ וְשׁוֹמֵר אוֹתוֹ, נִקְרָא צַדִּיק. מִשּׁוּם כָּךְ, לְעוֹלָם יִירְשׁוּ אָרֶץ."],[4,"","וְעַל זֶה תְּבִאֵמוֹ, ו' יְתֵרָה. תְּבִאֵמוֹ לְאוֹתָם הָאֲחוּזִים בְּו' (תפארת). וְתִטָּעֵמוֹ, כַּנֶּאֱמַר נֵצֶר מַטָּעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. לְאוֹתָם שֶׁאֲחוּזִים בְּו', וּלְאוֹתָם אַחֲ רוֹנִים הִתְעוֹרֵר הַדָּבָר. וְאֵין לְךְ דָּבָר בַּתּוֹרָה אוֹ אוֹת קְטַנָּה בַּתּוֹרָה שֶׁאֵין בָּהּ סוֹדוֹת עֶלְיוֹנִים וּטְעָמִים קְדוֹשִׁים. אַשְׁרֵי חֶלְקָם שֶׁל הַיּוֹדְעִים בָּהֶם."],[5,"","מִצְוָה לִבְנוֹת בֵּית מִקְדָּשׁ לְמַטָּה כְּמוֹ בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה, כְּמוֹ שֶׁנֶּאֱמַר מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. שֶׁצָּרִיךְ לִבְנוֹת בֵּית מִקְדָּשׁ לְמַטָּה וּלְהִתְפַּלֵּל בְּתוֹכוֹ תְּפִלָּה בְּכָל יוֹם, לַעֲבוֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהֲרֵי תְּפִלָּה נִקְרֵאת עֲבוֹדָה."],[6,"","וְאוֹתוֹ בֵּית הַכְּנֶסֶת צָרִיךְ לִבְנוֹתוֹ בְּיֹפִי רַב וּלְתַקְּנוֹ בְּכָל הַתִּקּוּנִים, שֶׁהֲרֵי בֵּית הַכְּנֶסֶת שֶׁלְּמַטָּה עוֹמֵד כְּנֶגֶד בֵּית הַכְּנֶסֶת שֶׁלְּמַעְלָה."],[7,"","בֵּית הַמִּקְדָּשׁ לְמַטָּה הוּא עוֹמֵד כְּמוֹ בֵּית הַמִּקְדָּשׁ שֶׁלְּמַעְלָה, שֶׁעוֹמֵד זֶה כְּנֶגֶד זֶה. וְאוֹתוֹ בֵּית מִקְדָּשׁ, כָּל תִּקּוּנָיו וְכָל עֲבוֹדוֹתָיו וְכָל אוֹתָם כֵּלִים וְשַׁמָּשִׁים, כֻּלָּם הֵם כְּמוֹ שֶׁלְּמַעְלָה. הַמִּשְׁכָּן שֶׁעָשָׂה מֹשֶׁה בַּמִּדְבָּר, הַכֹּל הָיָה כְּמוֹ שֶׁלְּמַעְלָה."],[8,"","בֵּית הַמִּקְדָּשׁ שֶׁבָּנָה שְׁלֹמֹה הַמֶּלֶךְ, הוּא בֵּית מְנוּחָה כְּדֻגְמָא עֶלְיוֹנָה בְּכָל אוֹתָם תִּקּוּנִים, לִהְיוֹת בְּתִקּוּן שֶׁלְּמַעְלָה בֵּית מְנוּחָה וִירֻשָּׁה. כָּךְ בֵּית הַכְּנֶסֶת צָרִיךְ בְּכָל תִּקּוּנֵי הַיֹּפִי, לִהְיוֹת כְּדֻגְמָא עֶלְיוֹנָה, לִהְיוֹת בֵּית תְּפִלָּה, לְתַקֵּן תִּקּוּנִים בַּתְּפִלָּה, כְּמוֹ שֶׁבֵּאֲרוּהָ."],[9,"","וְאוֹתוֹ בֵּית מִקְדָּשׁ שֶׁיִּהְיוּ בוֹ חַלּוֹנוֹת, שֶׁכָּתוּב (דניאל ו) חַלּוֹנוֹת פְּתוּחִים. כְּמוֹ שֶׁלְּמַעְלָה. וְעַל זֶה (שיר ב) מַשְׁגִּיחַ מִן הַחַלּוֹנוֹת מֵצִיץ מִן הַחֲרַכִּים. וְאִם תֹּאמַר, אֲפִלּוּ בַּשָּׂדֶה, כְּדֵי שֶׁהָרוּחַ תִּהְיֶה עוֹלָה? לֹא כָּךְ, שֶׁהֲרֵי אָנוּ צְרִיכִים בַּיִת, וְאֵין לְהִמָּצֵא בַּיִת לְמַטָּה כְּמוֹ בַּיִת עֶלְיוֹן, לְהוֹרִיד דִּיּוּר עֶלְיוֹן לְדִיּוּר תַּחְתּוֹן."]]],[["וְתוּ דְּהַהוּא צְלוֹתָא, וְהַהוּא רוּחָא, אִצְטְרִיךְ לְסַלְּקָא, וְּלְנָפְקָא מִגּוֹ עָאקוּ, בְּאֹרַח מֵישָׁר, לָקֳבֵל יְרוּשָׁלַם. וְעַל דָּא כְּתִיב, (תהילים קי״ח:ה׳) מִן הַמֵּצַר קָרָאתִי יָהּ, דְּאִצְטְרִיךְ אֲתָר דָּחִיק בְּעָאקוּ, לְשַׁדְּרָא בְּגַוֵּיהּ הַהוּא רוּחָא, דְּלָא יִסְטֵי לִימִינָא וְלִשְׂמָאלָא. וּבְחַקְלָא לָא יָכִיל קָלָא לְשַׁדְּרָא לֵיהּ הָכִי, דְּהָא כְּגַוְונָא דָּא קָלָא דְּשׁוֹפָר, אִתְדַּחְיָיא לְבַר בְּאֹרַח מֵישָׁר, מִגּוֹ אֲתָר דָּחִיק, וְאָזִיל וּבָקַע רְקִיעִין, וְסָלִיק בִּסְלִיקוּ, לְאַתְּעָרָא רוּחָא לְעֵילָּא.","וְאִי תֵּימָא, הָא כְּתִיב, (בראשית כ״ד:ס״ג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה. שָׁאנֵי יִצְחָק, דְּמִלָּה אַחֲרָא הֲוָה בֵּיהּ, מַה דְּלָא הֲוָה בְּכָל עָלְמָא. וְתוּ דְּהַאי קְרָא לָאו לְהָכִי אָתָא, דְּוַדַּאי בַּשָּׂדֶה אַחֵר לָא הֲוָה מְצַלֵּי וְהָא אוֹקִימְנָא. (ע\"כ רעיא מהימנא).","תַּנְיָא אָמַר רִבִּי אַבָּא, זַכָּאָה חוּלָקֵיהוֹן, דְּאִינּוּן דְּזַכָּאן לְמֵימָר שִׁירָתָא דָּא בְּהַאי עָלְמָא, דְּזַכָּאן לְמֵימָר לָהּ בְּעָלְמָא דְּאָתֵי. וְשִׁירָתָא דָּא, אִתְבְּנֵי בְּעֶשְׂרִין וּתְרֵין אַתְוָון קַדִּישִׁן גְּלִיפָן, וּבְעֶשֶׂר אֲמִירָן, וְכֹלָּא אִתְרְשִׁים בִּשְׁמָא קַדִּישָׁא, וְכֹלָּא שְׁלֵימוּתָא דִּשְׁמָא קַדִּישָׁא, וְהָא אִתְּעַרְנָא מִלֵּי.","אָמַר רִבִּי שִׁמְעוֹן, בְּהַהִיא שַׁעֲתָא דַּהֲווֹ קַיְימִין יִשְׂרָאֵל עַל יַמָּא, וַהֲווּ אַמְרֵי שִׁירָתָא, אִתְגְּלֵי קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, וְכָל רְתִיכוֹי וְחֵילוֹי, בְּגִין דְּיִנְדְּעוּן לְמַלְכֵּיהוֹן, דְּעָבַד לוֹן כָּל אִינּוּן נִסִּין וּגְבוּרָאן, וְכָל חַד וְחַד יָדַע וְאִסְתַּכַּל, מַה דְּלָא יָדְעוּ וְאִסְתַּכָּלוּ שְׁאַר נְבִיאֵי עָלְמָא.","דְּאִי תֵּימָא דְּלָא יָדְעִין וְלָא אִדְבָּקוּ חָכְמְתָא עִלָּאָה, מִן שִׁירָתָא דָּא תֶּחמֵי, דְּכֻלְּהוּ בְּחָכְמְתָא אִסְתַּכָּלוּ, וְיָדְעוּ מִלִּין וְאָמְרוּ. דְּאִי לָאו הָכִי, אֵיךְ אָמְרוּ כֻּלְּהוּ מִלִּין אֲחְדִין, דְּלָא סָטוּ אִלֵּין מֵאִלֵּין, וּמַה דְּאָמַר דָּא, אָמַר דָּא, וְלָא אַקְדִּים מִלָּה דָּא, לְמִלָּה דָּא, אֶלָּא כֻּלְּהוּ בְּשִׁקּוּלָא חֲדָא, וְרוּחָא דְּקוּדְשָׁא בְּפוּמָא דְּכָל חַד וְחַד, וּמִלִּין אִתְּמָרוּ כֻּלְּהוּ כְּאִלּוּ נָפְקִין מִפּוּמָא חַד. אֶלָּא וַדַּאי כּוּלְּהוּ בְּחָכְמְתָא עִלָּאָה אִסְתַּכָּלוּ, וְיָדְעוּ מִילִין עִלָּאִין, וְרוּחָא דְּקוּדְשָׁא בְּפוּם כָּל חַד וְחַד.","וַאֲפִילּוּ אִינּוּן דְּבִמְעֵי אִמְּהוֹן, הֲווֹ אַמְרֵי שִׁירָתָא כֻּלְּהוּ כַּחֲדָא, וַהֲווּ חָמָאן כֻּלְּהוּ, מַה דְּלָא חָמָא יְחֶזְקֵאל נְבִיאָה. וְעַל כַּךְ הֲווֹ כֻּלְּהוּ מִסְתַּכְּלֵי, כְּאִלּוּ חָמָאן עֵינָא בְּעֵינָא. וְכַד סִיְּימוּ מִלִּין, כֻּלְּהוּ מִתְבַּסְּמָאן בְּנַפְשַׁיְיהוּ, וְתָּאָבוֹן לְמֵחֱמֵי וּלְאִסְתַּכְּלָא, וְלָא הֲווֹ בָּעָאן לְנַטְלָא מִתַּמָּן, מִסְּגִיאוּת תִּיאוּבְתָּא.","בְּהַהִיא שַׁעֲתָא, אָמַר מֹשֶׁה לְקוּדְשָׁא בְּרִיךְ הוּא, בָּנַיִךְ מִסְּגִיאוּת תִּיאוּבְתָּא לְאִסְתַּכְּלָא בָּךְ, לָא בָּעָאן לְנַטְלָא מִן יַמָּא. מַה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, אַסְתִּים יְקָרֵיהּ לְבַר לְמַדְבְּרָא, וְתַמָּן אִתְגְּלֵי וְלָא אִתְגְּלֵי. אָמַר לוֹן מֹשֶׁה לְיִשְׂרָאֵל, כַּמָּה (ס\"א זמנין לנטלא מתמן, ולא בעי') זִמְנִין אֲמֵינָא לְנַטְלָא מִתַּמָּן וְלָא בָּעִיתוּן עַד דִּי אַחְזֵי לוֹן זִיוָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּמַדְבְּרָא, וּמִיַּד הֲווֹ תָּאָבִין,","וְלָא נַטְלוּ, עַד דְּאָחִיד בְּהוּ מֹשֶׁה וְאַחְמֵי לוֹן זִיוָא יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא בְּמַדְבְּרָא, כְּדֵין מִסְּגִיאוּת תִּיאוּבְתָּא וּרְעוּתָא לְאִסְתַּכְּלָא, אַנְטִיל לוֹן מֹשֶׁה, הֲדָא הוּא דִכְתִיב וַיַסַּע מֹשֶׁה אֶת יִשְׂרָאֵל מִיָּם סוּף וַיֵּצְאוּ אֶל מִדְבַּר שׁוּר. מַאי מִדְבַּר שׁוּר. מַדְבְּרָא, דַּהֲווֹ בָּעָאן לְאִסְתַּכְּלָא בֵּיהּ, זִיוָא יְקָרָא דְּמַלְכָּא קַדִּישָׁא, וְעַל דָּא אִקְרֵי מִדְבַּר שׁוּר: אִסְתַּכְּלוּתָא שָׁם.","(שמות ט״ו:כ״ב) וַיֵּלְכוּ שְׁלֹשֶׁת יָמִים בַּמִּדְבָּר וְלֹא מָצְאוּ מָיִם. וְאֵין מַיִם אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (ישעיהו נ״ה:א׳) הוֹי כָּל צָמֵא לְכוּ לַמַּיִם. אָמַר רִבִּי יֵיסָא, וְכִי מַאן יָהַב לְהוּ אוֹרַיְיתָא הָכָא, וְהָא עַד כְּעַן לָא אִתְיְהִיבַת לוֹן אוֹרַיְיתָא.","אָמַר רִבִּי אֶלְעָזָר, אִינּוּן נָפְקוּ לְמַדְבְּרָא לְאִסְתַּכְּלָא, קוּדְשָׁא בְּרִיךְ הוּא נָטַל זִיוָא יְקָרָא דִּילֵיהּ מִתַּמָּן, וְאִינּוּן אָזְלוּ לְאִסְתַּכְּלָא (לקודשא בריך הוא) בֵּיהּ, וְלָא אַשְׁכְּחוּהוּ. וְאוֹלִיפְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא תּוֹרָה אִקְרֵי, וְאֵין מַיִם אֶלָּא תּוֹרָה, וְאֵין תּוֹרָה אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא.","אָמַר רִבִּי שִׁמְעוֹן, עַד דַּהֲווֹ אַזְלֵי בְּמַדְבְּרָא, אִתְגְּלֵי עָלַיְיהוּ רְשׁוּתָא אַחֲרָא, דִּשְׁאַר עַמִּין, הַהוּא דְּשָׁלִיט בְּמַדְבְּרָא, וְאִעֲרָעוּ בְּהוּ תַּמָּן. חָמוּ יִשְׂרָאֵל, דְּלָא הֲוָה הַהוּא זִיוָא יְקָרָא דְּמַלְכֵּיהוֹן, הֲדָא הוּא דִּכְתִּיב, וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה. מַאי טַעְמָא. כִּי מָרִים הֵם, לָא אִתְבְּסָם נַפְשַׁיְיהוּ כְּקַדְמִיתָא. וְלא עוֹד אֶלָּא דְּאָתֵי לְקַטְרְגָא עָלַיְיהוּ."],[[0,"ותו, דההוא צלותא וכו':","ועוד, שתפלה ההיא ורוח ההוא, צריך לעלות ולצאת מן המצר בדרך ישר כנגד ירושלים. וע\"ז כתוב, מן המצר קראתי יה. שצריך מקום צר בצרה, לשלוח בתוכו רוח ההוא, שלא יטה לימין ולשמאל. ובשדה אין הקול יכול לשלוח לו כך. כי כעין זה הוא קול שופר, שנדחה לחוץ בדרך ישר מתוך מקום צר, והולך ובוקע רקיעים, ועולה בעליה לעורר רוח שלמעלה."],[1,"ואי תימא הא וכו':","ואם תאמר הרי כתוב, ויצא יצחק לשוח בשדה. הרי שמתפללים בשדה. ומשיב משונה הוא יצחק, שדבר אחר היה בו מה שלא היה בכל העולם. שהיה אחד מן האבות. ועוד, שמקרא זה אינו בא לכך להתיר להתפלל בשדה, כי ודאי שבשדה אחר לא היה מתפלל וכבר בארנו. (לעיל בא אות קנ\"ה) ששדה זה היה השדה אשר קנה אברהם. (ע\"כ רעיא מהימנא)."],[2,"תניא א\"ר אבא וכו':","למדנו, אר\"א אשרי חלקם של הזוכים לומר שירה זו בעולם הזה וזוכים לאמרה בעולם הבא. ושירה זו נבנה בכ\"ב אותיות קדושות חקוקות, ובעשרה מאמרות, והכל נרשם בשם הקדוש, והכל שלמות השם הקדוש. והערנו הדברים."],[3,"א\"ר שמעון וכו':","אר\"ש, בשעה ההיא שהיו עומדים ישראל על הים, והיו אומרים שירה, נגלה עליהם הקב\"ה וכל מרכבותיו וצבאיו, כדי שידעו את מלכם, שעשה להם כל אלו הנסים והגבורות, וכל אחד ואחד ידע והסתכל מה שלא ידעו והסתכלו שאר נביאי העולם."],[4,"דאי תימא דלא וכו':","כי אם תאמר שלא היו יודעים ולא השיגו חכמה עליונה, משירה זו תראה שכולם הסתכלו בחכמה, וידעו הדברים ואמרו. שאם לא כן, איך אמרו כולם מלות אחדות, שלא נטו אלו מאלו, ומה שאמר זה אמר זה, ולא הקדים מלה זו למלה זו, אלא כולם אמרו במשקל אחד, ורוח הקדש היה בפי כל אחד ואחד, והמלות נאמרו כולם כאלו יצאו מפה אחד. אלא ודאי כולם בחכמה עליונה הסתכלו, וידעו דברים עליונים, ורוח הקודש בפי כל אחד ואחד."],[5,"ואפילו אינון דבמעי וכו':","ואפילו אלו שבמעי אמם, היו אומרים שירה כולם כאחד. והיו רואים כולם מה שלא ראה יחזקאל הנביא. ועל כך היו כולם מסתכלים, כאלו ראו עין בעין. וכשגמרו הדברים, כולם מתבשמים בעצמם, וחושקים לראות ולהסתכל ולא היו רוצים לנסוע משם מרוב השתוקקות."],[6,"בההיא שעתא אמר וכו':","בשעה ההיא, אמר משה להקב\"ה, בניך מרוב השתוקקות להסתכל בך אינם רוצים לנסוע מן הים. מה עשה הקב\"ה, הסתים כבודו בחוץ במדבר, ושם נגלה ואינו נגלה. אמר להם משה לישראל, כמה פעמים אמרתי שתסעו משם ולא רציתם, עד שהראיתי לכם זיו כבוד הקב\"ה במדבר. ומיד היו חושקים."],[7,"ולא נטלו עד וכו':","ולא נסעו עד שאחז בהם משה, והראה להם זיו כבוד הקב\"ה במדבר, אז מרוב השתוקקות ורצון להסתכל הסיע אותם משה. ז\"ש ויסע משה את ישראל מים סוף ויצאו אל מדבר שור. מהו מדבר שור. הוא מדבר שהיו רוצים שם להסתכל בו בזיו כבוד המלך הקדוש, ועל כן נקרא מדבר שור. שפירושו הסתכלות שם."],[8,"וילכו שלשת וגו' ולא מצאו מים:","אין מים אלא תורה, שנאמר הוי כל צמא לכו למים. אמר ר' ייסא, וכי מי נתן להם התורה כאן. והרי עד עתה לא ניתנה להם התורה."],[9,"אמר רבי אלעזר וכו':","אר\"א, הם יצאו למדבר להסתכל, והקב\"ה לקח זיו הכבוד משם, והם הלכו להסתכל בו, ולא מצאו אותו. ולמדנו שהקב\"ה נקרא תורה, וע\"כ אין מים אלא תורה, ואין תורה אלא הקב\"ה."],[10,"אמר רבי שמעון וכו':","אר\"ש, בעוד שהיו הולכין במדבר, נגלה עליהם רשות אחר של שאר העמים, דהיינו אותו שהוא שולט במדבר ופגע בהם שם, ראו ישראל שלא היה ההוא, זיו כבוד מלכם, ז\"ש, ויבואו מרתה ולא יכלו לשתות מים ממרה, מה הטעם, כי מרים הם, לא נתבשם נפשם כבתחילה. ולא עוד אלא שבא לקטרג עליהם."]],[[0,"","וְעוֹד, שֶׁאוֹתָה תְּפִלָּה וְאוֹתָהּ רוּחַ צְרִיכִים לַעֲלוֹת וְלָצֵאת מִתּוֹךְ מְצוּקָה בְּדֶרֶךְ יְשָׁרָה כְּנֶגֶד יְרוּשָׁלַיִם. וְעַל זֶה כָּתוּב מִן הַמֵּצַר קָרָאתִי יָהּ. שֶׁצָּרִיךְ מָקוֹם דָּחוּק בַּצָּרָה לִשְׁלֹחַ בְּתוֹכוֹ אוֹתָהּ רוּחַ שֶׁלֹּא יִסְטֶה יָמִינָה אוֹ שְׂמֹאלָה. וּבְשָׂדֶה לֹא יָכוֹל הַקּוֹל לְשַׁלֵּחַ אוֹתוֹ כָּךְ, שֶׁהֲרֵי כְּמוֹ זֶה קוֹל הַשּׁוֹפָר נִדְחֶה הַחוּצָה בְּדֶרֶךְ יָשָׁר מִתּוֹךְ מָקוֹם דָּחוּק, וְהוֹלֵךְ וּבוֹקֵעַ רְקִיעִים, וְעוֹלֶה בַּעֲלִיָּה לְעוֹרֵר רוּחַ שֶׁלְּמַעְלָה."],[1,"","וְאִם תֹּאמַר, הֲרֵי כָּתוּב (בראשית כד) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה? שׁוֹנֶה יִצְחָק, שֶׁדָּבָר אַחֵר הָיָה בּוֹ מַה שֶּׁלֹּא הָיָה בְּכָל הָעוֹלָם. וְעוֹד, שֶׁפָּסוּק זֶה לֹא לָזֶה הוּא בָּא, שֶׁוַּדַּאי בַּשָּׂדֶה לֹא הָיָה מִתְפַּלֵּל, וַהֲרֵי בֵּאַרְנוּ. (ע\"כ רעיא מהימנא)"],[2,"","שָׁנִינוּ, אָמַר רַבִּי אַבָּא, אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁזַּכָּאִים לוֹמַר שִׁירָה זוֹ בָּעוֹלָם הַזֶּה, שֶׁזַּכָּאִים לְאָמְרָהּ לָעוֹלָם הַבָּא. וְשִׁירָה זוֹ נִבְנְתָה בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת קְדוֹשׁוֹת חֲקוּקוֹת וּבְעֶשֶׂר אֲמִירוֹת, וְהַכֹּל נִרְשָׁם בַּשֵּׁם הַקָּדוֹשׁ, וְהַכֹּל שְׁלֵמוּת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, וַהֲרֵי עוֹרַרְנוּ הַדְּבָרִים."],[3,"","אָמַר רַבִּי שִׁמְעוֹן, בְּאוֹתָהּ שָׁעָה שֶׁהָיוּ עוֹמְדִים יִשְׂרָאֵל עַל הַיָּם וְאוֹמְרִים שִׁירָה, הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם, וְכָל מַרְכְּבוֹתָיו וְחֵילוֹתָיו, כְּדֵי שֶׁיַּכִּירוּ אֶת מַלְכָּם שֶׁעָשָׂה לָהֶם כָּל אוֹתָם נִסִּים וּגְבוּרוֹת, וְכָל אֶחָד וְאֶחָד יָדַע וּהִתְבּוֹנֵן מַה שֶּׁלֹּא יָדְעוּ וְהִתְבּוֹנְנוּ שְׁאָר נְבִיאֵי הָעוֹלָם."],[4,"","שֶׁאִם תֹּאמַר שֶׁלֹּא יָדְעוּ וְלֹא הִדְבִּיקוּ הִשִּׂיגוּ חָכְמָה הָעֶלְיוֹנָה - מִן הַשִּׁירָה הַזּוֹ תִּרְאֶה שֶׁכֻּלָּם הִסְתַּכְּלוּ בַּחָכְמָה וְיָדְעוּ דְבָרִים וְאָמְרוּ. שֶׁאִם לֹא כָּךְ, אֵיךְ אָמְרוּ כֻלָּם מִלִּים אֲחִידוֹת שֶׁלֹּא סָטוּ אֵלֶּה מֵאֵלֶּה, וּמַה שֶּׁאָמַר זֶה - אָמַר זֶה, וְלֹא הִקְדִּים מִלָּה זוֹ לְמִלָּה זוֹ, אֶלָּא כֻּלָּם בְּמִשְׁקָל אֶחָד, וְרוּחַ הַקֹּדֶשׁ בְּפִי כָּל אֶחָד וְאֶחָד, וְכָל הַדְּבָרִים נֶאֶמְרוּ כְּאִלּוּ יָצְאוּ מִפֶּה אֶחָד? אֶלָּא וַדַּאי כֻּלָּם בַּחָכְמָה הָעֶלְיוֹנָה הִסְתַּכְּלוּ, וְיָדְעוּ דְבָרִים עֶלְיוֹנִים, וְרוּחַ הַקֹּדֶשׁ בְּפִי כָּל אֶחָד וְאֶחָד."],[5,"","וַאֲפִלּוּ אוֹתָם שֶׁבִּמְעֵי אִמָּם הָיוּ כֻלָּם כְּאֶחָד אוֹמְרִים שִׁירָה, וְהָיוּ כֻלָּם רוֹאִים מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל הַנָּבִיא, וְעַל כָּךְ הָיוּ כֻלָּם מִסְתַּכְּלִים כְּאִלּוּ רוֹאִים עַיִן בְּעַיִן. וּכְשֶׁסִּיְּמוּ הַדְּבָרִים, כֻּלָּם מְבֻשָּׂמִים בְּנַפְשָׁם וּתְאֵבִים לִרְאוֹת וּלְהִסְתַּכֵּל, וְלֹא הָיוּ רוֹצִים לִנְסֹעַ מִשָּׁם מֵרֹב הִשְׁתּוֹקְקוּת."],[6,"","בְּאוֹתָהּ שָׁעָה אָמַר מֹשֶׁה לַקָּדוֹשׁ- בָּרוּךְ-הוּא: בָּנֶיךְ לֹא רוֹצִים לִנְסֹעַ מִן הַיָּם מֵרֹב הִשְׁתּוֹקְקוּת לְהִסְתַּכֵּל בְּךְ. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? הִסְתִּיר אֶת כְּבוֹדוֹ הַחוּצָה לַמִּדְבָּר, וְשָׁם הִתְגַּלָּה וְלֹא הִתְגַּלָּה. אָמַר לָהֶם מֹשֶׁה לְיִשְׂרָאֵל: כַּמָּה (פעמים לנסע משם, ולא רצו) פְעָמִים אָמַרְתִּי לִנְסֹעַ מִשָּׁם וְלֹא רְצִיתֶם? עַד שֶׁהֶרְאָה לָהֶם זִיו כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּדְבָּר, וּמִיָּד הָיוּ תְאֵבִים."],[7,"","וְלֹא נָסְעוּ, עַד שֶׁאָחַז בָּהֶם מֹשֶׁה וְהֶרְאָה לָהֶם זִיו כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמִּדְבָּר. אָז מֵרֹב תְּשׁוּקָה וְרָצוֹן לְהִסְתַּכֵּל הִסִּיעַ אוֹתָם מֹשֶׁה. זֶהוּ שֶׁכָּתוּב וַיַּסַּע מֹשֶׁה אֶת יִשְׂרָאֵל מִיַּם סוּף וַיֵּצְאוּ אֶל מִדְבַּר שׁוּר. מַה זֶּה מִדְבַּר שׁוּר? מַנְהִיג שֶׁהָיוּ רוֹצִים לְהִסְתַּכֵּל בּוֹ, זִיו כְּבוֹדוֹ שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, וְעַל זֶה נִקְרָא מִדְבַּר שׁוּר - שָׁם הִסְתַּכְּלוּת."],[8,"","וַיֵּלְכוּ שְׁלֹשֶׁת יָמִים בַּמִּדְבָּר וְלֹא מָצְאוּ מָיִם. וְאֵין מַיִם אֶלָּא תּוֹרָה, שֶׁנֶּאֱמַר (ישעיה נה) הוֹי כָּל צָמֵא לְכוּ לַמַּיִם. אָמַר רַבִּי יֵיסָא, וְכִי מִי נָתַן לָהֶם כָּאן תּוֹרָה, וַהֲרֵי עַד עַכְשָׁו לֹא נִתְּנָה לָהֶם תּוֹרָה?"],[9,"","אָמַר רַבִּי אֶלְעָזָר, הֵם יָצְאוּ לַמִּדְבָּר לְהִסְתַּכֵּל, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל זִיו כְּבוֹדוֹ מִשָּׁם, וְהֵם הָלְכוּ לְהִסְתַּכֵּל (לקדוש'ברוך'הוא) בּוֹ וְלֹא מָצְאוּ אוֹתוֹ. וְלָמַדְנוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא תּוֹרָה, וְאֵין מַיִם אֶלָּא תּוֹרָה, וְאֵין תּוֹרָה אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא."],[10,"","אָמַר רַבִּי שִׁמְעוֹן, עַד שֶׁהָיוּ הוֹלְכִים בַּמִּדְבָּר, הִתְגַּלָּה עֲלֵיהֶם רָשׁוּת אַחֶרֶת שֶׁל שְׁאָר הָעַמִּים, אוֹתוֹ שֶׁשּׁוֹלֵט בַּמִּדְבָּר, וּפָגַשׁ בָּהֶם שָׁם. רָאוּ יִשְׂרָאֵל שֶׁזֶּה לֹא הָיָה אוֹתוֹ זִיו כְּבוֹד מַלְכָּם. זֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתֹּת מַיִם מִמָּרָה. מָה הַטַּעַם? כִּי מָרִים הֵם. לֹא הִתְבַּשְּׂמָה נַפְשָׁם כְּבַתְּחִלָּה. וְלֹא עוֹד, אֶלָּא שֶׁבָּא לְקַטְרֵג עֲלֵיהֶם."]]],[["מַה כְּתִיב, וְיִצְעַק אֶל יְיָ' וַיּוֹרֵהוּ יְיָ' עֵץ, וְאֵין עֵץ אֶלָּא תּוֹרָה, דִּכְתִּיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְאֵין תּוֹרָה, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי אַבָּא אָמַר, אֵין עֵץ אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (דברים כ׳:י״ט) כִּי הָאָדָם עֵץ הַשָּׂדֶה, עֵץ הַשָּׂדֶה וַדַּאי, דָּא עֵץ שָׂדֶה דְּתַפּוּחִין קַדִּישִׁין. וְכַד אִתְגְּלֵי זִיו יְקָרָא דְּמַלְכֵּהוֹן עָלַיְיהוּ, כְּדֵין וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם. מַאי וַיִּמְתְּקוּ הַמָּיִם. דְּקַטֵּיגוֹרָא אִתְעָבִיד סַנֵּיגוֹרָא.","אָמַר רִבִּי אַבָּא, תָּא חֲזֵי בְּקַדְמִיתָא כַּד עָאלוּ יִשְׂרָאֵל בְּקַיָימָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא עָאלוּ כְּדְקָא יֵאוֹת. מַאי טַעֲמָא. בְּגִין דְּאִתְגְּזָרוּ וְלָא אִתְפְּרָעוּ, וְלָא אִתְגַּלְּיָיא רְשִׁימָא קַדִּישָׁא. כֵּיוָן דְּמָטוּ הָכָא, מַה כְּתִיב, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. תַּמָּן עָאלוּ יִשְׂרָאֵל בִּתְרֵין חוּלָקִין קַדִּישִׁין, בְּהַהוּא גִּלּוּיָא דְּאִתְגַּלְיָא רְשִׁימָא דִּלְהוֹן, וְאִקְרוּן חֹק וּמִשְׁפָּט. חֹק: כְּמָה דְּאַתְּ אָמַר (משלי כא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. וּמִשְׁפָּט: כְּמָה דְּאִתְּמַר (תהילים פ״א:ה׳) מִשְׁפַּט לֵאלֹהֵי יַעֲקֹב. וְשָׁם נִסָּהוּ, בְּהַהוּא אָת קַדִּישָׁא.","כְּמָה דְאַתְּ אָמֵר, כִּי חֹק לְיִשְׂרָאֵל הוּא. בְּסִפְרָא דְּרַב יִיִבָא סָבָא, אָמַר מִלָּה עַל הַהוּא חוּטְרָא קַדִּישָׁא. (שמות ט״ו:כ״ו) וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל יְיָ' אֱלֹהֶיךָ. וַיֹּאמֶר, מַאי וַיֹּאמֶר. לָא כְּתִיב מַאן קָאָמַר דָּא. אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אָמַר. רִבִּי חִזְקִיָּה אָמַר, שַׁמְעֵינָן (נ\"א משמע) אֲמִירָה סְתָם, מֵאֲמִירָה סְתָם. דִּכְתִּיב, (שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל יְיָ'. אָמַר, לָא כְּתִיב מַאן קָאָמַר. אוּף הָכָא וַיֹּאמֶר סְתָם, וְלָא כְּתִיב מַאן קָאָמַר.","אָמַר רִבִּי יוֹסֵי, מַשְׁמַע דִּכְתִּיב, וְיִצְעַק אֶל יְיָ' וַיּוֹרֵהוּ יְיָ' עֵץ, מֵהָכָא מַשְׁמַע וַיֹּאמֶר, וּמַשְׁמַע מַאן אָמַר מִלָּה. לְקוֹל יְיָ' אֱלהֶיךָ, לְקוֹלִי מִבָּעֵי לֵיהּ. אֶלָּא לְהַהוּא קוֹל דְּעָאלוּ בֵּיהּ.","אָמַר רִבִּי אַבָּא, בָּתַר דְּאִתְגַּלְיָא בְּהוּ רְשִׁימָא קַדִּישָׁא, עָאלוּ בִּתְרֵין חוּלָקִין קַדִּישִׁין, כְּמָה דְּאִתְּמַר, וְכֵיוָן דְּעָאלוּ בְּאִלֵּין תְּרֵין, עָאלוּ בְּאִלֵּין תְּרֵין חוּלָקִין אַחֲרָנִין, דְּכַד יִסְתַּלְּקוּן בְּאִלֵּין תְּרֵין אַחֲרָנִין, יִתְחַבְּרוּן בְּאִלֵּין, וְלָא מִמַּנְעֵי בִּרְכָּאן, וּבְּגִין כָּךְ, בְּאִלֵּין מָטוּ בִּרְכָּאן, (ובגיני כך באלין מטין) עַד מַלְכָּא קַדִּישָׁא.","וּמֵאַתְרֵיהּ דִּקְרָא אִשְׁתְּמַע מִלָּה, דִּכְתִּיב, וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע. וַיֹּאמֶר: דָּא מַלְכָּא קַדִּישָׁא. וּמַאי קָאָמַר, אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל יְיָ' אֱלהֶיךָ, כְּמָה דְאַתְּ אָמֵר (דברים ד׳:כ״ד) כִּי יְיָ' אֱלֹהֶיךָ אֵשׁ אוֹכְלָה הוּא, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה: דָּא צַדִּיק. וְהַאֲזַנְתָּ לְמִצְוֹתָיו: דָּא נְצַח. וְשָׁמַרְתָּ כָּל חֻקָּיו: דָּא הוֹד. כֵּיוָן דְּעָאלוּ בְּאִלֵּין, הָא מָטוּ לְמַלְכָּא קַדִּישָׁא. לְבָתַר מַה כְּתִיב, כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְּמִצְרַיִם לא אָשִׂים עָלֶיךָ כִּי אֲנִי יְיָ' רוֹפְאֶךָ. כִּי אֲנִי יְיָ': דָּא מַלְכָּא קַדִּישָׁא.","אִשְׁתְּמַע, דְּכָל מַאן דְּנָטִיר לְהַאי רְשִׁימָא קַדִּישָׁא, מִנֵיהּ סָלִיק עַד מַלְכָּא קַדִּישָׁא עִלָּאָה. מַאי מַשְׁמַע. מַשְׁמַע אִינּוּן תְּרֵין, דְּאִתְכְּנַשׁ בְּהוּ זַרְעָא, וּמָשַׁח רְבוּת קוּדְשָׁא, דְּשַׁדְיָין לֵיהּ בְּפוּם אָמָה, (ועל דא) אִתְקַשָּׁרוּ כַּחֲדָא, וּמַלְכָּא עִלָּאָה עָלַיְיהוּ, וְאִתְקַשָּׁרוּ בֵּיהּ. וְעַל כַּךְ, מַאן דְּעָאל בְּאִלֵּין תְּרֵין, וְנָטִיר לוֹן, אִתְקָשָּׁר בִּתְרֵין אַחֲרָנִין, וְעָאל בְּהוּ, וּכְדֵין מָטֵי לְמַלְכָּא קַדִּישָׁא.","אָמַר רִבִּי יִצְחָק, וַדַּאי מַאן דְּזָכֵי בְּצַדִיק, זָכֵי בְּנֶצַח וְהוֹד, וְאִלֵּין אִינּוּן תְּלָתָא, דְּאִתְבָּרְכָא בְּהוּ כְּנֶסֶת יִשְׂרָאֵל. וּמַאן דְּזָכוּ בְּהוּ, זָכֵי בְּמַלְכָּא קַדִּישָׁא, וְעָאל בְּכֻלְּהוּ אַרְבְּעָה.","וְלָקֳבְלֵי אַרְבְּעָה אִלֵּין, נְטִירוּ לְהַאי רְשִׁימָא קַדִּישָׁא, מֵאַרְבַּע מִלִּין: נְטִירוּ דִּכְנְסֶת יִשְׂרָאֵל, אִסְתַּמְּרוּתָא דְּנִדָּה. נְטִירוּ דְּצַדִּיק, אִסְתַּמְּרוּתָא דְּשִׁפְחָה. נְטִירוּ דְּנֶצַח, אִסְתַּמְּרוּתָא דְּבַת עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. נְטִירוּ דְּהוֹד, אִסְתַּמְּרוּתָא דְּזוֹנָה. וְעַל דָּא לְקוֹל יְיָ' אֱלהֶיךָ, דָּא כְּנֶסֶת יִשְׂרָאֵל.","בַּמֶּה זָכָאן יִשְׂרָאֵל לְקַבְּלָא אַפֵּי שְׁכִינְתָּא, בְּאִסְתַּמְּרוּתָא מִן נִדָּה. וְעַל דָּא כְּתִיב, (ויקרא י״ח:י״ט) וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ. מַאי לְגַלּוֹת עֶרְוָתָהּ דָּא כְּנֶסֶת יִשְׂרָאֵל. וּבְהַאי אֲחִידָן וּמִתְקַשְּׁרָן מִלִּין אַחֲרָנִין, דִּכְנֶסֶת יִשְׂרָאֵל אִתְקַשְּׁרַת בְּהוּ. וְהָא אוּקְמוּהָ מִלֵּי."],[[0,"מה כתיב ויצעק וגו':","מה כתוב, ויצעק אל ה' ויורהו ה' עץ. ואין עץ אלא תורה, שכתוב, עץ חיים היא למחזיקים בה. ואין תורה אלא הקב\"ה. ר' אבא אמר, אין עץ אלא הקב\"ה, שכתוב, כי האדם עץ השדה. עץ השדה ודאי, זהו עץ שדה דתפוחין קדישין. כלומר, שדה זו היא מלכות. עץ השדה, זה ז\"א בעלה. וכשנגלה זיו כבוד המלך עליהם, אז וישלך אל המים וימתקו המים. מהו וימתקו המים, היינו שהקטיגור נעשה סניגור."],[0,"","פירוש. שהוקשה לו כיון שויורהו ה' עץ, היינו הקב\"ה, וחזר עליהם זיו כבודו, א\"כ למה לו עוד להשליך אותו אל המים, ועוד, הרי מים ג\"כ הקב\"ה כנ\"ל. וז\"ש שקטיגור נעשה סניגור. כיון שהס\"א שהיתה במים קטרג עליהם כנ\"ל. ועתה נעשה סנגור."],[1,"אמר רבי אבא וכו':","אר\"א, בוא וראה, בתחילה כשנכנסו ישראל בברית הקב\"ה, לא נכנסו כראוי. מה הטעם. משום שמלו ולא פרעו, ולא נגלה הרושם הקדוש. כיון שהגיעו כאן למרה, מה כתוב, שם שם לו חק ומשפט ושם נסהו. שפירושו, שם נכנסו ישראל בשני חלקים הקדושים, מלכות ויסוד שזכו בהם ע\"י מילה ופריעה, בגילוי ההוא שנגלה הרושם שלהם ונקראו חק ומשפט. חק, זה מלכות, כש\"א ותתן טרף לביתה וחק לנערותיה. שסובב על המלכות ורומז על מילה ומשפט, כמ\"ש משפט לאלקי יעקב. שהוא יסוד רומז להמוחין המתגלים ע\"י הפריעה, הנקרא משפט. \u0003ושם נסהו\u0004 היינו באות הזה הקדוש. שמפני היותו חק, שייך נסיון. כמ\"ש כי חק לישראל הוא. בספר ר' ייבא סבא אמר דבר על מטה ההוא הקדוש, שעליו נאמר, ויורהו ה' עץ."],[2,"ויאמר אם שמוע וגו':","כתוב ויאמר, מהו ויאמר, לא כתוב מי אמר זה. אלא הקב\"ה אמר. ר' חזקיה אמר, אנו למדים אמירה סתם מאמירה סתם. שכתוב, ואל משה אמר עלה אל ה'. ושם פירושו המלכות, שאם היה הקב\"ה היה צריך לומר, עלה אלי. אף כאן פירושו המלכות."],[3,"אמר ר' יוסי וכו':","משמע משכתוב מקודם לכן, ויצעק אל ה', ויורהו ה' עץ. מכאן משמע פירושו של ויאמר, שמשמע מי אמר מלה זו. דהיינו ג\"כ הקב\"ה. \u0003לקול ה' אלקיך,\u0004 לקולי היה צריך לומר. ומשיב, שפירושו לקול הזה שנכנסו בו, על ידי המילה, שהוא קול המלכות. וע\"כ לא נאמר לקולי."],[4,"אמר ר' אבא וכו':","אר\"א, אחר שנגלה בהם רושם הקדוש, נכנסו בב' חלקים הקדושים כמו שלמדנו (לעיל אות שכ\"ח) שהם יסוד ומלכות. ע\"י מילה זכו למלכות, וע\"י פריעה ליסוד. וכיון שנכנסו באלו השנים, נכנסו גם באלו ב' חלקים האחרים, שהם נצח והוד, כי כשיתעלו בב' האחרים, נצח והוד, יתחברו באלו, יסוד ומלכות. ולא ימנעו ברכות שיסוד ישפיע למלכות. ומשום זה, יגיעו באלו עד המלך הקדוש. שהוא ז\"א."],[5,"ומאתריה דקרא וכו':","וממקום הכתוב נשמע הדבר. שכתוב, ויאמר אם שמוע תשמע. \u0003ויאמר,\u0004 זה המלך הקדוש. ומהו אמר, אם שמע תשמע \u0003לקול ה' אלקיך,\u0004 הוא כש\"א, כי ה' אלקיך אש אוכלה הוא, שהיא כנסת ישראל, דהיינו המלכות. \u0003והישר\u0004 בעיניו תעשה, זהו צדיק שנקרא ישר. \u0003והאזנת למצותיו,\u0004 זהו נצח. \u0003ושמרת כל חוקיו,\u0004 זהו הוד. כיון שנכנסו באלו מלכות ויסוד ונצח והוד. הרי הגיעו למלך הקדוש, שהוא תפארת, שמקומו אחר נצח. וע\"כ לאח\"כ מה כתוב, כל המחלה אשר שמתי במצרים לא אשים עליך כי אני ה' רופאך. \u0003כי אני ה'\u0004 זהו המלך הקדוש שהוא ת\"ת."],[6,"אשתמע דכל מאן וכו':","נשמע, שכל מי ששומר הרושם הקדוש הזה, שהוא מילה, עולה ממנו עד המלך הקדוש העליון. שואל, מה משמעות הדברים. ומשיב, שמשמע, שאלו השנים, נצח והוד, שמתקבץ בהם הזרע לברכה, ושמן משחת קדש שיורים אותו בפי האמה, שהוא יסוד, נתקשרו יחד, והמלך העליון, ת\"ת, עליהם, ונקשרו בו. ועל כך, מי שנכנס באלו השנים יסוד ומלכות ע\"י מילה ופריעה, ושומר אותם, נקשר בשנים אחרים, נצח והוד, ונכנס בהם, ואז מגיע למלכא קדישא, שהוא ת\"ת."],[7,"א\"ר יצחק וכו':","אר\"י, ודאי מי שזכה בצדיק, שהוא יסוד, זכה בנצח והוד, מפני שיסוד כולל בתוכו נו\"ה, והם שלשה שנתברכה בהם כנסת ישראל שהיא מלכות. ומי שזכה בהם זכה במלך הקדוש, שהוא ת\"ת, ונכנס בכל הארבע ספירות, ת\"ת נצח הוד יסוד מלכות."],[8,"ולקבלי ארבעה אלין וכו':","וכנגד ארבע אלו יש שמירה להרושם הקדוש, מארבעה דברים: שמירה דכנסת ישראל, שהיא מלכות, הוא שמירה מנדה, שמירה של הצדיק, שהוא יסוד, הוא שמירה משפחה. שמירה של נצח, הוא שמירה מבת עכו\"ם. שמירה של הוד הוא שמירה מזונה. ועל זה \u0003לקול ה' אלקיך,\u0004 זהו כנסת ישראל שהיא מלכות. שנכנסו בה על ידי המילה."],[9,"במה זכאן ישראל וכו':","במה זוכים ישראל לקבל פני השכינה. הוא, על ידי שמירה מנדה. ועל זה כתוב, ואל אשה בנדת טומאתה לא תקרב לגלות ערותה. שואל, מהו, לגלות ערותה. ומשיב, זהו \u0003כנסת ישראל.\u0004 כלומר שלא יפגום בה. ובזה אחוזים ומתקשרים דברים אחרים שכנסת ישראל נקשרת בהם. וכבר העמדנו הדברים."]],[[0,"","מַה כָּתוּב? וַיִּצְעַק אֶל ה' וַיּוֹרֵהוּ ה' עֵץ, וְאֵין עֵץ אֶלָּא תּוֹרָה, שֶׁכָּתוּב (משליג) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְאֵין תּוֹרָה אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי אַבָּא אָמַר, אֵין עֵץ אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דבריםכ) כִּי הָאָדָם עֵץ הַשָּׂדֶה, עֵץ הַשָּׂדֶה וַדַּאי, זֶה עֵץ שָׂדֶה שֶׁל תַּפּוּחִים קְדוֹשִׁים (מלכות). וּכְשֶׁהִתְגַּלָּה זִיו כְּבוֹד מַלְכָּם עֲלֵיהֶם, אָז וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם. מַה זֶּה וַיִּמְתְּקוּ הַמָּיִם? שֶׁקָּטֵגוֹר נַעֲשָׂה סָנֵגוֹר."],[1,"","אָמַר רַבִּי אַבָּא, בּא רְאֵה, בַּתְּחִלָּה כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל לַבְּרִית שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא נִכְנְסוּ כָּרָאוּי, מָה הַטַּעַם? כִּי נִמּוֹלוּ וְלֹא נִפְרְעוּ, וְלֹא הִתְגַּלָּה הָרֹשֶׁם הַקָּדוֹשׁ. כֵּיוָן שֶׁהִגִּיעוּ לְכָאן מַה כָּתוּב? שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט. שָׁם נִכְנְסוּ יִשְׂרָאֵל לִשְׁנֵי חֲלָקִים קְדוֹשִׁים בְּאוֹתוֹ גִּלּוּי שֶׁהִתְגַּלָּה הָרֹשֶׁם שֶׁלָּהֶם, וְנִקְרְאוּ חֹק וּמִשְׁפָּט. חֹק - כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. וּמִשְׁפָּט - כְּמוֹ שֶׁנֶּאֱמַר מִשְׁפָּט לֵאלֹהֵי יַעֲקֹב. וְשָׁם נִסָּהוּ - בְּאוֹתוֹ אוֹת קֹדֶשׁ,"],[2,"","כְּמוֹ שֶׁנֶּאֱמַר כִּי חֹק לְיִשְׂרָאֵל הוּא. בְּסִפְרוֹ שֶׁל רַבִּי יֵיבָא סָבָא אָמַר הַדָּבָר עַל אוֹתוֹ מַטֶּה קָדוֹשׁ. וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל ה' אֱלֹהֶיךְ. וַיֹּאמֶר, מַה זֶּה וַיֹּאמֶר? לֹא כָתוּב מִי אָמַר אֶת זֶה. אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר. רַבִּי חִזְקִיָּה אָמַר, שָׁמַעְנוּ (משמע) אֲמִירָה סְתָם מֵאֲמִירָה סְתָם, שֶׁכָּתוּב (שמות כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. אָמַר, לֹא כָתוּב מִי אָמַר. אַף כָּאן וַיֹּאמֶר סְתָם, וְלֹא כָתוּב מִי אָמַר."],[3,"","אָמַר רַבִּי יוֹסֵי, מַשְׁמָע שֶׁכָּתוּב וַיִּצְעַק אֶל ה' וַיּוֹרֵהוּ ה' עֵץ, מִכָּאן מַשְׁמָע וַיֹּאמֶר, וּמַשְׁמָע מִי אָמַר דָּבָר זֶה. לְקוֹל ה' אֱלֹהֶיךְ? לְקוֹלִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא לְאוֹתוֹ קוֹל שֶׁנִּכְנְסוּ בוֹ."],[4,"","אָמַר רַבִּי אַבָּא, אַחַר שֶׁהִתְגַּלָּה בָּהֶם רֹשֶׁם הַקָּדוֹשׁ, נִכְנְסוּ בִּשְׁנֵי חֲלָקִים קְדוֹשִׁים, כְּמוֹ שֶׁנֶּאֱמַר, וְכֵיוָן שֶׁנִּכְנְסוּ בִּשְׁנֵי אֵלֶּה, נִכְנְסוּ בִּשְׁנֵי הַחֲלָקִים הָאֲחֵרִים הַלָּלוּ, שֶׁכַּאֲשֶׁר יַעֲלוּ בִּשְׁנֵי הָאֲחֵרִים הַלָּלוּ, יִתְחַבְּרוּ בְּאֵלֶּה וְלֹא יִמָּנְעוּ הַבְּרָכוֹת, וְלָכֵן בְּאֵלֶּה מַגִּיעוֹת הַבְּרָכוֹת (ומשום כך באלה מגיעים) עַד הַמֶּלֶךְ הַקָּדוֹשׁ."],[5,"","וּמִמְּקוֹמוֹ שֶׁל הַכָּתוּב נִשְׁמָע הַדָּבָר, שֶׁכָּתוּב וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע. וַיֹּאמֶר - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ. וּמָה אָמַר? אִם שָׁמוֹעַ תִּשְׁמַע לְקוֹל ה' אֱלֹהֶיךְ, כְּמוֹ שֶׁנֶּאֱמַר כִּי ה' אֱלֹהֶיךְ אֵשׁ אוֹכְלָה הוּא - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה - זֶה צַדִּיק. וְהַאֲזַנְתָּ לְמִצְותָיו - זֶה נֶצַח. וְשָׁמַרְתָּ כָּל חֻקָּיו - זֶה הוֹד. כֵּיוָן שֶׁנִּכְנְסוּ בְאֵלֶּה, הֲרֵי הִגִּיעוּ לַמֶּלֶךְ הַקָּדוֹשׁ. אַחַר כָּךְ מַה כָּתוּב? כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְמִצְרַיִם לֹא אָשִׂים עָלֶיךְ כִּי אֲנִי ה' רֹפְאֶךְ. כִּי אֲנִי ה' - זֶה הַמֶּלֶךְ הַקָּדוֹשׁ."],[6,"","נִשְׁמָע, שֶׁכָּל מִי שֶׁשּׁוֹמֵר אֶת הָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה, מִמֶּנּוּ עוֹלֶה עַד הַמֶּלֶךְ הַקָּדוֹשׁ הָעֶלְיוֹן. מַה מַּשְׁמָע? מַשְׁמָע אוֹתָם שְׁנַיִם שֶׁהִתְכַּנֵּס בָּהֶם הַזֶּרַע, וְשֶׁמֶן מִשְׁחַת קֹדֶשׁ, שֶׁשּׁוֹפְכִים אוֹתוֹ בְּפִי הָאָמָה, (ועל זה) נִקְשְׁרוּ כְאֶחָד, וְהַמֶּלֶךְ הָעֶלְיוֹן עֲלֵיהֶם, וְנִקְשְׁרוּ בוֹ. וְעַל כָּךְ, מִי שֶׁנִּכְנָס בִּשְׁנֵי אֵלֶּה וְשׁוֹמֵר אוֹתָם, נִקְשָׁר בִּשְׁנֵי הָאֲחֵרִים וְנִכְנָס בָּהֶם, וְאָז מַגִּיעַ לַמֶּלֶךְ הַקָּדוֹשׁ."],[7,"","אָמַר רַבִּי יִצְחָק, וַדַּאי מִי שֶׁזּוֹכֶה בְּצַדִּיק, זוֹכֶה בְּנֶצַח וְהוֹד וּשְׁלֹשֶׁת אֵלֶּה, שֶׁהִתְבָּרְכָה בָּהֶם כְּנֶסֶת יִשְׂרָאֵל. וּמִי שֶׁזּוֹכֶה בָּהֶם, זוֹכֶה בַּמֶּלֶךְ הַקָּדוֹשׁ, וְנִכְנָס בְּכָל הָאַ רְבָּעָה."],[8,"","וּכְנֶגֶד אַרְבָּעָה אֵלּוּ שְׁמִירָה לָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה מֵאַרְבָּעָה דְבָרִים: שְׁמִירָה שֶׁל כְּנֶסֶת יִשְׂרָאֵל - שְׁמִירָה שֶׁל נִדָּה. שְׁמִירָה שֶׁל צַדִּיק - שְׁמִירָה שֶׁל שִׁפְחָה. שְׁמִירָה שֶׁל נֶצַח - שְׁמִירָה שֶׁל בַּת עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת. שְׁמִירָה שֶׁל הוֹד - שְׁמִירָה שֶׁל זוֹנָה. וְעַל זֶה לְקוֹל ה' אֱלֹהֶיךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל."],[9,"","בַּמֶּה זוֹכִים יִשְׂרָאֵל לְקַבֵּל פְּנֵי שְׁכִינָה? בִּשְׁמִירָה מִנִּדָּה, וְעַל זֶה כָּתוּב (ויקרא יח) וְאֶת אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ. מַה זֶּה לְגַלּוֹת? זוֹ כְּנֶסֶת יִשְׂרָאֵל, וּבָזֶה אֲחוּזִים וְנִקְשָׁרִים דְּבָרִים אֲחֵרִים שֶׁכְּנֶסֶת יִשְׂרָאֵל נִקְשֶׁרֶת בָּהֶם. וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים."]]],[["וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה: דָּא צַדִּיק. כְּמָה דִּכְתִּיב, (תהלים לה) עֵינֵי יְיָ' אֶל צַדִּיקִים, לְאִסְתַּמְּרָא מִשִּׁפְחָה. וְהָא אוֹקִימְנָא מִלֵּי. דִּכְתִּיב, (משלי ל׳:כ״ג) וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, דְּגָרִים לַצַּדִּיק דְּאִתְדַּבָּק בְּשִׁפְחָה. וְהַאֲזַנְתָּ לְמִצְוֹתָיו: דָּא נֶצַח, לְאִסְתַּמְּרָא (דלא שקר ביה) דְּלָא יֵעוּל רְשִׁימָא דָּא בְּבַת אֵל נֵכָר, וְלא יְשַׁקֵּר בֵּיהּ בְּנֶצַח. דִּכְתִּיב, (שמואל א ט״ו:כ״ט) וְגַם נְצַח יִשְׂרָאֵל לא יְשַׁקֵּר. וּמַאן דְּנָטִיר הַאי, קִיֵּים מִצְוֹתָיו, דִּכְתִּיב, (שמות לה) כִּי לא תִשְׁתַּחֲוֶה לְאֵל אַחֵר. וְשָׁמַרְתָּ כָּל חֻקָּיו: דָּא הוֹד, לְאִסְתַּמְּרָא מִן זוֹנָה.","וְאַזְלָא הָא, כְּמָה דְּתָנֵינָן, אָמַר רִבִּי יְהוּדָה, מַאי דִּכְתִּיב (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֶךְ גִּבּוֹר הוֹדְךָ וַהֲדָרֶךָ. אֶלָּא, כָּל מַאן דִּמְזָרֵז גַּרְמֵיהּ, וְשַׁוֵּי דְּחִילוּ דְּחַרְבָּא שִׁנָּנָא תַּקִּיפָא לָקֳבְלֵיהּ. עַל יָרֶךְ, מַאי עַל יָרֶךְ. דָּא רְשִׁימָא קַדִּישָׁא. כְּמָה דְאַתְּ אָמֵר, (בראשית כ״ד:ב׳) שִׂים נָא יָדְךָ תַּחַת יְרֵכִי.","דָּבָר אַחֵר חֲגוֹר חַרְבְּךָ, כְּלוֹמַר, זָרֵז וְאַתְקִיף יִצְרְךָ בִּישָׁא, דְּאִיהוּ חַרְבְּךָ. עַל יָרֶךְ, עַל הַהוּא רְשִׁימָא קַדִּישָׁא לְנַטְרָא לֵיהּ. וְאִי נָטַר לֵיהּ, כְּדֵין אִקְרֵי גִּבּוֹר, וְקוּדְשָׁא בְּרִיךְ הוּא אַלְבִּישׁ לֵיהּ בִּלְבוּשׁוֹי, וּמַאן לְבוּשׁוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. הוֹד וְנֶצַח. (נ\"א והדר) דִּכְתִּיב, (תהילים ק״ד:א׳) הוֹד וְהָדָר לָבָשְׁתָּ. אוּף הָכָא הוֹדְךָ וַהֲדָרֶךָ, וּכְדֵין אִתְדַּבַּק בַּר נָשׁ בְּמַלְכָּא קַדִּישָׁא כְּדְקָא יֵאוֹת.","מִכָּאן וּלְהָלְאָה, כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְּמִצְרַיִם לא אָשִׂים עָלֶיךָ כִּי אֲנִי יְיָ' רוֹפְאֶךָ. דָּא מַלְכָּא קַדִּישָׁא, וְעַל דָּא אַזְהַר לוֹן עַל הַהוּא מִלָּה מַמָּשׁ, דְּיָהַב וְרָשִׁים בְּהוּ, וְלָא יַתִּיר וְעַד כְּעַן לָא אִתְיְיהִיבַת לְהוּ אוֹרַיְיתָא, אֶלָּא כֵּיוָן דִּכְתִּיב, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, מִיָּד וַיֹּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע וְגוֹ'.","תָּא חֲזֵי, כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַזְהָרָא לְיִשְׂרָאֵל, עַל אוֹרַיְיתָא, בְּכַמָּה מִלִּין מָשִׁיךְ לְהוּ, בְּכַמָּה מְשִׁיכָן דַּחֲבִיבוּתָא, כְּבַר נָשׁ דְּמָשִׁיךְ בְּרֵיהּ לְבֵי רַב. וְתָּא חֲזֵי, לָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַב לְהוּ אוֹרַיְיתָא, עַד דְּקָרִיבוּ בַּהֲדֵיהּ. וּבַמֶּה קְרִיבוּ בַּהֲדֵיהּ, בְּגִלּוּיָא דִּרְשִׁימָא דָּא, כְּמָה דְּאִתְּמַר.","אָמַר ר' יְהוּדָה, לָא קְרִיבוּ יִשְׂרָאֵל לְטוּרָא דְּסִינַי, עַד דְּעָאלוּ בְּחוּלָקָא דְּצַדִּיק, וְזָכוּ בֵּיהּ. מְנָלָן, דִּכְתִּיב, (שמות י״ט:א׳) בַּיּוֹם הַזֶּה בָּאוּ מִדְבָּר סִינַי, בַּיּוֹם הַזֶּהִ מַמָּשׁ פרשת המן קִוִּינוּ לוֹ וגוֹ'.","\u0003[פרשת המן]\u0004 (שמות ט״ז:ד׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'. הַאי קְרָא אוֹקִימְנָא לֵיהּ, בְּשַׁעֲתָא דְּבַר נָשׁ שָׁכִיב בְּבֵי מַרְעֵיהּ, הָא אִתְּפַס בְּאַטְרוֹנְיָא דְּמַלְכָּא, רֵישֵׁיהּ בְּקוּלְרָא, רַגְלוֹי בְּכוּפְסִירִין, (ס\"א בטפסרא) כַּמָּה חֵילִין נַטְרִין לֵיהּ, מֵהַאי גִּיסָא, וּמֵהַאי גִּיסָא. שַׁיְיפוֹי כֻּלְּהוּ בְּדוֹחֲקָא, מַגִּיחִין אִלֵּין בְּאִלֵּין. מֵיכְלָא אִתְעָדֵי מִנֵּיהּ.","בְּהַהוּא זִמְנָא, פַּקְדִין עָלֵיהּ אַפּוֹטְרוֹפָא, לְמֵילַף עָלֵיהּ זְכוּת קָמֵי מַלְכָּא, דִּכְתִּיב, (איוב ל״ג:כ״ג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף. בְּהַהִיא שַׁעֲתָא, זַכָּאָה חוּלָקֵיהּ דְּבַּר נָשׁ דְּעָאל עָלֵיהּ, וְאוֹלִיף לֵיהּ אָרְחָא, לְשֵׁיזָבוּתֵיהּ מִן דִּינָא. הֲדָא הוּא דִכְתִיב אַשְׁרֵי מַשְׂכִּיל אֶל דָּל.","וְהֵיךָ יָכִיל לְשֵׁזָבָא לֵיהּ, לְמֵילַף לֵיהּ אָרְחוֹי דְּחַיֵּי, לְאָתָבָא לְקָמֵי מָארֵיהּ, כְּדֵין אִתְעָבִיד אַפּוֹטְרוֹפוֹסָא עָלֵיהּ לְעֵילָּא. מַאי אַגְרֵיהּ. בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'. דָּבָר אַחֵר, אַשְׁרֵי מַשְׂכִּיל אֶל דָּל, כַּמָּה תַּקִּיפָא אַגְרָא דְּמִסְכְּנָא, קָמֵי קוּדְשָׁא בְּרִיךְ הוּא.","אָמַר רִבִּי חִיָּיא, תָּוַוהְנָא עַל הַאי קְרָא דִּכְתִּיב, (תהילים ס״ט:ל״ד) כִּי שׁוֹמֵעַ אֶל אֶבְיוֹנִים יְיָ', וְכִי אֶל אֶבְיוֹנִים שׁוֹמֵעַ וְלֹא לְאַחֲרָא. אָמַר רִבִּי שִׁמְעוֹן, בְּגִין דְּאִינּוּן קְרִיבִין יַתִּיר לְמַלְכָּא, דִּכְתִּיב, (תהילים נ״א:י״ט) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלהִים לא תִבְזֶה. וְלֵית לָךְ בְּעָלְמָא, דְּאִיהוּ תָּבִיר לִבָּא כְּמִסְכְּנָא. תּוּ אָמַר רִבִּי שִׁמְעוֹן, תָּא חֲזֵי, כָּל אִינּוּן בְּנִי עָלְמָא, אִתְחַזְיָין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּגוּפָא וְנַפְשָׁא, וּמִסְכְּנָא לָא אִתְחָזֵי אֶלָּא בְּנַפְשָׁא בִּלְחוֹדוֹי, וְקוּדְשָׁא בְּרִיךְ הוּא קָרִיב לְנַפְשָׁא יַתִּיר מִגּוּפָא."],[[0,"והישר בעיניו תעשה:","זהו \u0003צדיק,\u0004 שהוא יסוד, כמ\"ש עיני ה' אל צדיקים, להשמר משפחה. והרי העמדנו הדברים, שכתוב, ושפחה כי תירש גבירתה, פירושו שגורם לצדיק להתדבק בשפחה. \u0003והאזנת למצותיו,\u0004 זהו נצח, להשמר שלא יכניס רושם הזה בבת אל נכר, ולא ישקר בו בנצח. שכתוב וגם נצח ישראל לא ישקר. ומי ששומר זה, את הברית הקדוש, מקיים מצותיו, שכתוב, כי לא תשתחוה לאל אחר. \u0003ושמרת כל חוקיו,\u0004 זהו \u0003הוד,\u0004 להשמר מן זונה."],[1,"ואזלא הא כמה וכו':","וזה הולך כמו שלמדנו. א\"ר יהודה, מה שכתוב, חגור חרבך על ירך גבור הודך והדרך. אלא, כל מי שמזרז עצמו, ומשים פחד חרב שנונה החזקה, שהיא מלכות, כנגדו, \u0003על ירך,\u0004 מהו על ירך. היינו על רושם הקדוש הזה לשמור אותו. כמש\"א, שים נא ידך תחת ירכי."],[2,"ד\"א חגור חרבך וכו':","פירוש אחר על חגור חרבך. כלומר, זרז את עצמך, והתקף יצרך הרע, שהוא חרבך, \u0003על ירך,\u0004 על רושם הקדוש ההוא לשמור אותו. ואם שומר אותו אז נקרא גבור. והקב\"ה מלביש אותו בלבושיו, ומי הוא לבושיו של הקב\"ה. זה הוא הוד ונצח. שכתוב, הוד והדר לבשת. אף כאן, הודך והדרך. ואז מתדבק האדם בהמלך הקדוש כראוי."],[3,"מכאן ולהלאה כל וכו':","מכאן ולהלאה כל המחלה וגו' \u0003כי אני ה' רופאך.\u0004 זהו המלך הקדוש. ועל כן הזהיר אותם על דבר ההוא ממש שנתן ורשם בהם, שהוא ברית המילה ולא יותר. ואמת הוא שעד עתה לא ניתנה להם התורה, אלא כיון שכתוב, שם שם לו חק ומשפט, שהם מילה ופריעה, מיד, ויאמר אם שמוע תשמע וגו' שהמדובר הוא בד' שמירות של הברית הקדוש, כמבואר, ומיושב קושיא הנ\"ל שבאות שמ\"ה."],[4,"תא חזי כד וכו':","בוא וראה, כשרצה הקב\"ה להזהיר את ישראל על התורה, בכמה דברים משך אותם בכמה משיכות של אהבה, כאדם המושך את בנו לבית הספר. ובוא וראה, לא רצה הקב\"ה לתת להם התורה עד שנתקרבו אליו, ובמה נתקרבו אליו. בגילוי של הרושם הזה, שהיא ברית מילה, כמו שלמדנו."],[5,"אמר ר' יהודה וכו':","אר\"י, לא קרבו ישראל להר סיני, עד שנכנסו בחלק של הצדיק, דהיינו ברית מילה, וזכו בו. מאין לנו זה. כי כתוב, ביום הזה באו מדבר סיני ביום הזה ממש בדיוק. שהוא יסוד הנקרא \u0003זה.\u0004 וכתוב, ואמר ביום ההוא הנה אלקינו \u0003זה\u0004 קוינו לו וגו'."],[6,"ויאמר ה' אל משה הנני ממטיר וגו':","ר' יהודה פתח ואמר, אשרי משכיל אל דל וגו'. מקרא זה העמדנוהו, בשעה שאדם שוכב בבית חליו, הוא נתפש לשליטים של המלך, ראשו בשלשלת, רגליו באזיקים, כמה חילים שומרים אותו מצד זה ומצד זה, שלא יברח, אבריו כולם במיצר, ולוחמים אלו באלו, אכילה הוסרה ממנו."],[7,"בההוא זמנא פקדין וכו':","בזמן ההוא פוקדים עליו מליץ, ללמד עליו זכות לפני המלך. שכתוב, אם יש עליו מלאך מליץ אחד מני אלף. בשעה ההיא, אשרי חלקו של אדם, שנכנס אליו ומלמדו דרך להצילו מן הדין. ז\"ש אשרי משכיל אל דל."],[8,"והיך יכיל לשזבא וכו':","שואל, ואיך יכול להציל את החולה. ומשיב, שילמד אותו דרך החיים לשוב לפני אדונו. אז נעשה מליץ עליו למעלה והוא נצול. מה שכרו. הוא, ביום רעה ימלטהו ה'. פירוש אחר, אשרי משכיל אל דל. מפני שכמה תקיף הוא שכר של העוזר לדל לפני הקב\"ה."],[9,"א\"ר חייא תווהנא וכו':","אר\"ח תמיהני על מקרא הזה, שכתוב, כי שומע אל אביונים ה'. וכי אל אביונים שומע ולא לאחר. אמר רבי שמעון משום שהם קרובים יותר אל המלך, שכתוב לב נשבר ונדכה אלקים לא תבזה. ואין לך בעולם, שהוא לב שבור, כמו אביון. עוד א\"ר שמעון, בוא וראה, כל בני העולם נראים לפני הקב\"ה בגוף ונפש, ועני אינו נראה לפני הקב\"ה אלא בנפש לבד, כי גופו שבור, והקב\"ה קרוב לנפש יותר מלגוף."]],[[0,"","וְהַיָּשָׁר בְּעֵינָיו תַּעֲשֶׂה - זֶה צַדִּיק, כְּמוֹ שֶׁכָּתוּב (תהליםלד) עֵינֵי ה' אֶל צַדִּיקִים, לְהִשָּׁמֵר מִשִּׁפְחָה. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, שֶׁכָּתוּב וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ, שֶׁגּוֹרֵם לַצַּדִּיק שֶׁיִּדְבַּק בְּשִׁפְחָה. וְהַאֲזַנְתָּ לְמִצְותָיו - זֶה נֶצַח, לְהִשָּׁמֵר (שלא ישקר בו) שֶׁלֹּא יַכְנִיס רֹשֶׁם זֶה בְּבַת אֵל נֵכָר, וְלֹא יְשַׁקֵּר בְּנֶצַח, שֶׁכָּתוּב (שמואל א טו) וְגַם נֶצַח יִשְׂרָאֵל לֹא יְשַׁקֵּר. וּמִי שֶׁשּׁוֹמֵר אֶת זֶה, קִיֵּם מִצְווֹתָיו, שֶׁכָּתוּב (שמותלד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר. וְשָׁמַרְתָּ כָּל חֻקָּיו - זֶה סוֹד, לְהִשָּׁמֵר מִן זוֹנָה."],[1,"","וְזְהִ הוֹלֵךְ כְּמוֹ שֶׁשָּׁנִינוּ. אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר הוֹדְךְ וַהֲדָרֶךְ. אֶלָּא, כָּל מִי שֶׁמְּזָרֵז אֶת עַצְמוֹ וְשָׂם אֶת פַּחַד הַחֶרֶב הַשְּׁנוּנָה הַחֲזָקָה כְּנֶגְדּוֹ, עַל יָרֵךְ - מַה זֶּה עַל יָרֵךְ? זֶהוּ הָרֹשֶׁם הַקָּדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית כד) שִׂים נָא יָדְךְ תַּחַת יְרֵכִי."],[2,"","דָּבָר אַחֵר חֲגוֹר חַרְבְּךְ - כְּלוֹמַר, זָרֵז וּתְקֹף אֶת הַיֵּצֶר הָרָע שֶׁלְּךְ, שֶׁהוּא חַרְבְּךְ, עַל יָרֵךְ, עַל אוֹתוֹ רֹשֶׁם קָדוֹשׁ לִשְׁמֹר אוֹתוֹ. וְאִם שָׁמַר אוֹתוֹ אָז נִקְרָא גִּבּוֹר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַלְבִּישׁ אוֹתוֹ בִּלְבוּשָׁיו. וּמַהוּ לְבוּשׁ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא? הוֹד וְנֶצַח (והדר), שֶׁכָּתוּב (תהלים קד) הוֹד וְהָדָר לָבָשְׁתָּ. אַף כָּאן הוֹדְךְ וַהֲדָרֶךְ. וְאָז נִדְבָּק הָאָדָם בַּמֶּלֶךְ הַקָּדוֹשׁ כָּרָאוּי."],[3,"","מִכָּאן וָהָלְאָה - כָּל הַמַּחֲלָה אֲשֶׁר שַׂמְתִּי בְמִצְרַיִם לֹא אָשִׂים עָלֶיךְ כִּי אֲנִי ה' רֹפְאֶךְ. זֶה הַמֶּלֶךְ הַקָּדוֹשׁ. וְעַל זֶה הִזְהִיר אוֹתָם עַל אוֹתוֹ דָבָר מַמָּשׁ, שֶׁנָּתַן וְרָשַׁם בָּהֶם וְלֹא יוֹתֵר. וְעַד עַכְשָׁו לֹא נִתְּנָה לָהֶם תּוֹרָה. אֶלָּא כֵּיוָן שֶׁכָּתוּב, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, מִיָּד - וַיּאמֶר אִם שָׁמוֹעַ תִּשְׁמַע וְגוֹ'."],[4,"","בֹּא רְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַזְהִיר אֶת יִשְׂרָאֵל עַל הַתּוֹרָה, בְּכַמָּה דְבָרִים מָשַׁךְ אוֹתָם, בְּכַמָּה מְשִׁיכוֹת שֶׁל חֲבִיבוּת, כְּאָדָם שֶׁמּוֹשֵׁךְ בְּנוֹ לְבֵית הָרַב. וּבֹא רְאֵה, לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָתֵת לָהֶם תּוֹרָה עַד שֶׁקָּרְבוּ אֵלָיו. וּבַמֶּה קָרְבוּ אֵלָיו? בַּגִּלּוּי שֶׁל הָרֹשֶׁם הַזֶּה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[5,"","אָמַר רַבִּי יְהוּדָה, לֹא קָרְבוּ יִשְׂרָאֵל לְהַר סִינַי, עַד שֶׁנִּכְנְסוּ בַּחֵלֶק שֶׁל צַדִּיק וְזָכוּ בוֹ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמות יט) בַּיּוֹם הַזֶּה בָּאוּ מִדְבַּר סִינָי. בַּיּוֹם הַזֶּה מַמָּשׁ דַּוְקָא. וְכָתוּב (ישעיה כה) וְאָמַר בַּיּוֹם הַהוּא הִנֵּה אֱלֹהֵינוּ זֶה קִוִּינוּ לוֹ וְגוֹ'."],[6,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. פָּסוּק זֶה פֵּרְשׁוּהוּ, בְּשָׁעָה שֶׁאָדָם שׁוֹכֵב בְּבֵית חָלְיוֹ, הֲרֵי נִתְפָּס בְּבֵית הַסֹּהַר שֶׁל הַמֶּלֶךְ - רֹאשׁוֹ בְּקוֹלָר, רַגְלָיו בַּאֲזִיקִים (בדפוס), כַּמָּה חֲיָלוֹת שׁוֹמְרִים אוֹתוֹ מִצַּד זֶה וּמִצַּד זֶה, כָּל אֵיבָרָיו בְּדחַק נִלְחָמִים אֵלֶּה בְּאֵלֶּה, הָאֹכֶל הָעֳבַר מִמֶּנּוּ."],[7,"","בְּאוֹתוֹ הַזְּמַן מְמַנִּים עָלָיו אַפּוֹטְרוֹפּוֹס לְלַמֵּד עָלָיו זְכוּת לִפְנֵי הַמֶּלֶךְ, שֶׁכָּתוּב אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף. בְּאוֹתָהּ שָׁעָה אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁנִּכְנָס אֵלָיו וּמְלַמֵּד אוֹתוֹ דֶּרֶךְ לְהִנָּצֵל מִן הַדִּין. זֶהוּ שֶׁכָּתוּב אַשְׁרֵי מַשְׂכִּיל אֶל דָּל."],[8,"","וְאֵיךָ יָכוֹל לְהַצִּיל אוֹתוֹ? לְלַמְּדוֹ דֶּרֶךְ הַחַיִּים לָשׁוּב לִפְנֵי אֲדוֹנוֹ, אָז נַעֲשֶׂה אַפּוֹטְרוֹפּוֹס עָלָיו לְמַעְלָה. וּמַה שְּׂכָרוֹ? בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'. דָּבָר אַחֵר אַשְׁרֵי מַשְׂכִּיל אֶל דָּל - כַּמָּה חָזָק הַשָּׂכָר שֶׁל הֶעָנִי לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[9,"","אָמַר רַבִּי חִיָּיא, תָּמַהְתִּי עַל הַפָּסוּק הַזֶּה שֶׁכָּתוּב (שם סט) כִּי שּמֵעַ אֶל אֶבְיוֹנִים ה', וְכִי אֶל אֶבְיוֹנִים שׁוֹמֵעַ וְלֹא לְאַחֵר? אָמַר רַבִּי שִׁמְעוֹן, מִשּׁוּם שֶׁהֵם קְרוֹבִים יוֹתֵר לַמֶּלֶךְ, שֶׁכָּתוּב (שם נא) לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה, וְאֵין לְךְ בָּעוֹלָם שֶׁהוּא שְׁבוּר לֵב כְּמוֹ הֶעָנִי. עוֹד, אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה, כָּל אוֹתָם בְּנֵי הָעוֹלָם נִרְאִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגוּף וָנֶפֶשׁ, וְהֶעָנִי לֹא נִרְאֶה אֶלָּא בַּנֶּפֶשׁ לְבַדָּהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב לַנֶּפֶשׁ יוֹתֵר מִלַּגּוּף."]]],[["מִסְכְּנָא חַד הֲוָה בִּשְׁבִבוּתֵיהּ דְּר' יֵיסָא, וְלָא הֲוָה מַאן דְּאַשְׁגַּח בֵּיהּ, וְהוּא הֲוָה אַכְסִיף, וְלָא תַּקִּיף בִּבְנֵי נָשָׁא, יוֹמָא חַד חָלַּשׁ, עָאל עָלֵיהּ רִבִּי יֵיסָא, שָׁמַע חַד קָלָא דְּאָמַר, טִילְקָא טִילְקָא, הָא נַפְשָׁא פַּרְחָא גַּבָּאי, וְלָא מָטוּ יוֹמוֹי. וַוי לִבְנִי מָתֵיהּ דְּלָא אִשְׁתְּכַח בְּהוּ דְּיָתִיב נַפְשֵׁיהּ לְגַבֵּיהּ. קָם רִבִּי יֵיסָא, שַׁדֵּי בְּפוּמֵיהּ, מַיָּא דְּגַרְגְּרִין, אַפוּתָא דְּקוּנְטָא (ס\"א דקופתא) אִתְבְּזַע זִיִעָא בְּאַנְפּוֹי, וְתָב רוּחֵיהּ לְגַבֵּיהּ.","לְבָתַר אָתָא וְשָׁאִיל לֵיהּ, אָמַר חַיֶּיךָ רִבִּי, נַפְשָׁא נַפְקַת מִנַּאי, וּמָטוּ לָהּ קָמֵי כּוּרְסְיָיא דְּמַלְכָּא, וּבָעָת לְאִשְׁתַּאֲרָא תַּמָּן, אֶלָּא דְּבָעָא קוּדְשָׁא בְּרִיךְ הוּא לְזַכָּאָה לָךְ, וְאַכְרִיזוּ עָלָךְ, זַמִּין הוּא רִבִּי (ויקרא ע\"ט ע\"א וקמ\"ד ע\"א) יֵיסָא, לְסַלְּקָא רוּחֵיהּ, וּלְאִתְקְשְּׁרָא בְּחַד אִדְרָא קַדִּישָׁא דִּזְמִינִין חַבְרַיָּיא לְאִתְּעָרָא בְּאַרְעָא, וְהָא אַתְקִינוּ תְּלַת כֻּרְסְיָאן, דְּקַיְימִן לָךְ וּלְחַבְרָךְ. מֵהַהוּא יוֹמָא הֲווֹ מַשְׁגִּיחִין בֵּיהּ בְּנֵי מָתֵיהּ.","תּוּ, מִסְכְּנָא אַחֲרָא אַעְבָר קָמֵיהּ דְּר' יִצְחָק, וַהֲוָה בִּידֵיהּ פְּלַג מְעָה דְּכֶסֶף. אָמַר לֵיהּ לְרִבִּי יִצְחָק, אַשְׁלִים לִי וְלִבְנַי וְלִבְנָתַי נַפְשָׁאָן. אָמַר לֵיהּ וְהֵיךְ אַשְׁלִים נַפְשַׁיְיכוּ, דְּהָא לָא אִשְׁתְּכַח גַּבָּאי בַּר פְּלַג מְעָה. אָמַר לֵיהּ, בְּדָא אַשְׁלִימְנָא, בִּפְלַג אַחֲרָא דְּאִית גַּבָּאי, אַפְקֵיהּ וְיָהֲבֵיהּ לֵיהּ.","אַחְזִיאוּ לֵיהּ בְּחֶלְמֵיהּ, דְּהֲוָה אַעְבָר בִּשְׂפָתָא דְּיַמָּא רַבָּא, וּבָעָאן לְמִשְׁדְּיֵיהּ בְּגַוֵּויהּ, (ויחי רי\"ח ע\"א) חָמָא לְרִבִּי שִׁמְעוֹן, דְּהֲוָה אוֹשִׁיט יְדוֹי לָקֳבְלֵיהּ, וְאָתֵי הַהוּא מִסְכְּנָא וְאַפְקֵיהּ, וְיָהֲבֵיהּ בִּידוֹי דְּרִבִּי שִׁמְעוֹן, וְאִשְׁתֵּזִיב. כַּד אִתְּעַר, נָפַל בְּפוּמֵיהּ, הַאי קְרָא, (תהילים מ״א:ב׳) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ יְיָ'.","וְתָא חֲזֵי, כָּל יוֹמָא וְיוֹמָא, נָטִיף טַלָּא מֵעַתִּיקָא קַדִּישָׁא לִזְעֵיר אַפִּין, וּמִתְבָּרְכָאן כָּל חֲקַל תַּפּוּחִין קַדִּישִׁין. וּמֵהַהוּא טַלָּא אַנְגִּיד לְאִינוּן דִּלְתַתָּא, וּמַלְאָכִין קַדִּישִׁין אִתְּזָנוּ מִנֵּיהּ, כָּל חַד וְחַד כְּפוּם מֵיכָלֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ע״ח:כ״ה) לֶחֶם אַבִּירִים אָכַל אִישׁ, וּמֵהַהוּא מְזוֹנָא אָכְלוּ יִשְׂרָאֵל בְּמַדְבְּרָא.","אָמַר רִבִּי שִׁמְעוֹן, כַּמָּה בְּנֵי נָשָׁא מִתְּזָנִין בְּהַאי זִמְנָא מִנֵּיהּ, וּמַאן אִינּוּן. אִלֵּין חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, יוֹמֵי וְלֵילֵי. וְכִי סַלְּקָא דַּעְתָּךְ מֵהַהוּא מְזוֹנָא מַמָּשׁ. לָא. אֶלָּא כְּעֵין הַהוּא מְזוֹנָא מַמָּשׁ, דְּשָׁקִיל עַל חַד תְּרֵין.","תָּא חֲזֵי, יִשְׂרָאֵל כַּד עָאלוּ וְאִתְדְּבָקוּ בְּמַלְכָּא קַדִּישָׁא, בְּגִין גִּלּוּיָא דִּרְשִׁימָא קַדִּישָׁא, כְּדֵין זָכוּ לְמֵיכַל נַהֲמָא אַחֲרָא עִלָּאָה, יַתִּיר מִמַּה דְּהֲוָה בְּקַדְמִיתָא. בְּקַדְמִיתָא כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, עָאלוּ בְּנָהֲמָא, דְּאִקְרֵי מַצָּה, וְהַשְׁתָּא זָכוּ, וְעָאלוּ לְמֵיכַל נַהֲמָא אַחֲרָא עִלָּאָה יַתִּיר, מֵאֲתָר עִלָּאָה, דִּכְתִּיב הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. מִן הַשָּׁמָיִם מַמָּשׁ. וּבְהַהוּא זִמְנָא אִשְׁתְּכַח לְהוּ לְיִשְׂרָאֵל. מֵאֲתָר דָּא. חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, מֵאֲתָר אַחֲרָא עִלָּאָה יַתִּיר אִתְּזָנוּ. מַאי הוּא. כְּמָה דִּכְתִּיב, (קהלת ז׳:י״ב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. אֲתָר עִלָּאָה יַתִּיר.","אֲמַר לֵיהּ ר' אֶלְעָזָר, אִי הָכִי, אֲמַאי חַלְשָׁא נַפְשַׁיְיהוּ יַתִּיר מִשְּׁאָר בְּנֵי עָלְמָא, דְּהָא שְׁאַר בְּנֵי נָשָׁא, בְּחֵילָא וְתּוּקְפָּא יַתִּיר אִתְחָזוּן לְאִשְׁתַּכְּחָא. (ס\"א אינון יתיר) אָמַר לֵיהּ יֵאוֹת שָׁאִילְתָּא.","תָּא חֲזֵי, כָּל מְזוֹנִי דִּבְנֵי עָלְמָא מִלְּעֵילָּא קָא אַתְיָין. הַהוּא מְזוֹנָא דְּאָתֵי מִן שְׁמַיָּא וְאַרְעָא, דָּא מְזוֹנָא דְּכָל עָלְמָא, וְהוּא מְזוֹנָא דְּכוֹלָא, וְהוּא מְזוֹנָא גַּס וְעָב. וְהַהוּא מְזוֹנָא דְּאָתֵי יַתִּיר מֵעֵילָּא, הוּא מְזוֹנָא יַתִּיר דָּקִיק, קָאַתְיַא מֵאֲתָר דְּדִינָא אִשְׁתְּכַח, וְדָא הוּא מְזוֹנָא דְּאַכְלוּ יִשְׂרָאֵל כַּד נָפְקוּ מִמִּצְרַיִם. (יתיר דקיקא) מְזוֹנָא דְּאִשְׁתְּכַח לְהוּ לְיִשְׂרָאֵל, בְּהַהוּא זִמְנָא בְּמַדְבְּרָא, מֵאֲתָר עִלָּאָה דְּאִקְרֵי שָׁמַיִם, הוּא מְזוֹנָא יַתִּיר דְּקִיקָא, דְּעָיִיל יַתִּיר לְנַפְשָׁא מִכֹּלָּא, וּמִתְפְּרַשׁ יַתִּיר מִגּוּפָא, וְאִקְרֵי לֶחֶם אַבִּירִים.","מְזוֹנָא עִלָּאָה יַתִּיר מִכֹּלָּא, הוּא מְזוֹנָא דְּחַבְרַיָּיא, אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּאַכְלֵי מְזוֹנָא דְּרוּחָא וְנִשְׁמְתָא, וְלָא אַכְלֵי מְזוֹנָא דְּגוּפָא כְּלָל, וְהַיְינוּ מֵאֲתָר עִלָּאָה יַקִּירָא עַל כֹּלָּא, וְאִקְרֵי חָכְמָה. בְּגִינֵי כַּךְ חָלִישׁ גּוּפָא דְּחַבְרַיָּיא, יַתִּיר מִבְּנֵי עָלְמָא, דְּהָא לָא אַכְלֵי מְזוֹנָא דְּגוּפָא כְּלָל. וְאַכְלֵי מְזוֹנָא דְּרוּחָא וְנִשְׁמְתָא, מֵאֲתָר רְחִיקָא עִלָּאָה, יַקִּירָא מִכֹּלָּא. וּבְגִינֵי כַּךְ הַהוּא מְזוֹנָא דָּקִיק מִן דְּקִיקָא, יַתִּיר מִכֹּלָּא. זַכָּאָה חוּלָקֵיהוֹן, הֲדָא הוּא דִכְתִיב, (קהלת ז׳:י״ב) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. זַכָּאָה חוּלָקָא דְּגוּפָא, דְּיָכִיל לְאִתְּזָנָא בִּמְזוֹנָא דְּנַפְשָׁא."],[[0,"מסכנא חד הוה וכו':","עני אחד היה בשכנות של ר' ייסא. ולא היה מי שישגיח עליו. והוא היה מתבייש, ולא התקיף בני אדם. יום אחד היה חולה, נכנס אליו ר' ייסא, שמע קול אחד, שאמר צדק צדק, היינו שמסר דין לשמים, הנפש פורחת ממני ועוד לא הגיע הזמן, אוי לבני העיר, שלא נמצא בהם מי שישיב נפשו אליו. קם רבי ייסא נתן בפיו מי תאנים ומדה של יין מרוקח. בקע זיעה בפניו ושב רוחו אליו."],[1,"לבתר אתא ושאיל וכו':","אחר כך בא ושאל לו. אמר, חייך רבי, הנפש יצאה ממני, והגיעה לפני כסא המלך, ורצתה להשאר שם, אלא שרצה הקב\"ה לזכותך, והכריזו עליך, עתיד הוא ר' ייסא להעלות רוחו, ולהתקשר באדרא קדושה אחת, היינו באדרא רבא, ולא באדרא זוטא. שעתידים החברים להעיר בארץ, והתקינו שלשה כסאות העומדים לך ולחבירך, ר' יוסי ברבי יעקב ור' חזקיה. שיצאו נשמתם באדרא זו, (כמ\"ש בזוהר נשא דף קמ\"ד ע\"א ע\"ש) מיום ההוא והלאה, היו משגיחים עליו בני עירו."],[2,"תו מסכנא אחרא וכו':","עוד, עני אחר עבר לפני ר' יצחק והיה בידו חצי מעה כסף, אמר לו לר' יצחק, השלם לי ולבנותי את נפשינו. אמר לו ואיך אשלים את נפשכם, שהרי אין אצלי רק חצי מעה. אמר לו, בזה אשלים אני בחצי מעה אחרת שיש אצלי. הוציאה ונתן לו."],[3,"אתחזיאו ליה בחלמיה וכו':","הראו לו בחלומו, שהיה עובר בשפת ים הגדול, ורצו להשליכו בתוכו. ראה את ר' שמעון שהושיט ידו כנגדו, ובא עני ההוא, והוציאו ונתנו בידיו של ר' שמעון וניצל. כשהקיץ, נפל בפיו מקרא הזה, אשרי משכיל אל דל ביום רעה ימלטהו ה'."],[4,"ותא חזי כל וכו':","ובוא וראה, בכל יום ויום נוטף טל של עתיקא קדישא לזעיר אנפין, ומתברכת כל שדה התפוחים הקדושים, שהיא מלכות, ומטל ההוא נמשך לאלו שלמטה, ומלאכים הקדושים נזונים ממנו כל אחד לפי אכלו. ז\"ש לחם אבירים אכל איש. דהיינו הטל הנ\"ל שהוא לחם מלאכים. וממזון ההוא אכלו בני ישראל במדבר. שהוא המן."],[5,"אמר ר' שמעון וכו':","כמה בני אדם נזונים בזמן הזה ממנו. ומי המה. אלו הם החברים העוסקים בתורה ימים ולילות. וכי יעלה על דעתך ממזון ההוא ממש, שישראל אכלו במדבר, לא אלא כעין מזון ההוא ממש, ששקול פי שנים, על המן שאכלו ישראל במדבר."],[6,"תא חזי ישראל וכו':","בוא וראה, ישראל, כשבאו והתדבקו במלך הקדוש, בשביל הגילוי של הרושם הקדוש, של המילה, זכו אז לאכול לחם אחר עליון יותר, ממה שהיה בתחילה, בתחילה כשיצאו ישראל ממצרים, באו בלחם שנק' מצה, שהוא מלכות, ועתה זכו ונכנסו לאכול לחם אחר עליון יותר, ממקום עליון, שכתוב, הנני ממטיר לכם לחם מן השמים, מן השמים ממש. שהוא ז\"א. ובזמן ההוא, נמצא להם לישראל ממקום הזה. החברים העוסקים בתורה, ממקום אחר עליון יותר, נזונים. מה הוא. הוא כמו שכתוב, החכמה תחיה בעליה, שהוא מקום עליון יותר, מז\"א."],[7,"א\"ל ר' אלעזר וכו':","א\"ל ר\"א, אם כן, למה נחלש נפשם של העוסקים בתורה, יותר משאר בני העולם, שהרי שאר בני אדם נראים שנמצאים ביותר כח ועצמה מעוסקים בתורה. אמר לו, יפה שאלת."],[8,"תא תזי, כל וכו':","בוא וראה, כל מזון של בני העולם בא מלמעלה. מזון ההוא שבא מן שמים וארץ הוא מזון של כל העולם, והוא מזון הכל, והוא מזון גס ועבה, ומזון ההוא שבא ממקום עליון יותר, והוא מזון יותר דק, בא ממקום שהדין נמצא, דהיינו ממלכות, וזה הוא מזון שאכלו ישראל בצאתם ממצרים. דהיינו מצה. מזון שנמצא לישראל בזמן ההוא במדבר ממקום עליון הנקרא שמים, שהוא ז\"א, הוא מזון יותר דק, שנכנס יותר לנפש, מכל מזון אחר, ונפרד יותר מן הגוף, ונקרא לחם אבירים. דהיינו מן."],[9,"מזונא עלאה יתיר וכו':","מזון היותר עליון מכל, הוא מזון החברים, אלו העוסקים בתורה, שהם אוכלים מזון של הרוח והנשמה ואינם אוכלים מזון הגוף כלל, והיינו ממקום עליון היקר מכל, הנקרא חכמה, משום זה חלש גופם של החברים יותר מבני העולם, שהרי אינם אוכלים מזון הגוף כלל, ואוכלים רק מזון הרוח והנשמה, ממקום רחוק העליון היקר מכל. שהוא חכמה, שהיא רחוקה, כמ\"ש אמרתי אחכמה והיא רחוקה וגו'. ומשום זה מזון ההוא הוא דק מן הדק יותר מכל, אשרי חלקם. ז\"ש והחכמה תחיה בעליה. אשרי חלקו של גוף, שיכול להיות נזון במזון הנפש."]],[[0,"","עָנִי אֶחָד הָיָה בִּשְׁכֵנוּתוֹ שֶׁל רַבִּי יֵיסָא, וְלֹא הָיָה מִי שֶׁיַּשְׁגִּיחַ בּוֹ, וְהוּא הָיָה מִתְבַּיֵּשׁ וְלֹא הִפְצִיר בִּבְנֵי אָדָם. יוֹם אֶחָד נֶחֱלַשׁ, נִכְנַס עָלָיו רַבִּי יֵיסָא. שָׁמַע קוֹל אֶחָד שֶׁאוֹמֵר: צֶדֶק צֶדֶק, הֲרֵי נֶפֶשׁ פּוֹרַחַת אֵלַי וְלֹא הִגִּיעוּ יָמָיו! אוֹי לִבְנֵי עִירוֹ שֶׁלֹּא נִמְצָא בָהֶם שֶׁיָּשִׁיב נַפְשׁוֹ אֵלָיו! קָם רַבִּי יֵיסָא וְשָׁפַךְ בְּפִיו מַיִם שֶׁל גְּרוֹגָרוֹת עִם מִדָּה שֶׁל יַיִן רָקוּחַ. בַּקְּעָה זֵעָה בְּפָנָיו, וְשָׁב רוּחוֹ אֵלָיו."],[1,"","לְאַחַר בָּא וְשָׁאַל אוֹתוֹ. אָמַר: חַיֶּיךְ רַבִּי, נַפְשִׁי יָצְאָה מִמֶּנִּי וְהֵבִיאוּ אוֹתָהּ לִפְנֵי כִּסֵּא הַמֶּלֶךְ, וְרָצְתָה לְהִשָּׁאֵר שָׁם, אֶלָּא שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְזַכּוֹת אוֹתְךְ, וְהִכְרִיזוּ עָלֶיךְ: עָתִיד הוּא רַבִּי יֵיסָא לְהַעֲלוֹת רוּחוֹ וּלְהִתְקַשֵּׁר בְּחֶדֶר אֶחָד קָדוֹשׁ שֶׁעֲתִידִים הַחֲבֵרִים לְעוֹרֵר בָּאָרֶץ. וַהֲרֵי תִּקְּנוּ שְׁלֹשָׁה כִּסְאוֹת שֶׁעוֹמְדִים לְךְ וְלַחֲבֵרֶיךְ. מֵאוֹתוֹ הַיּוֹם הָיוּ מַשְׁגִּיחִים בּוֹ בְּנֵי עִירוֹ."],[2,"","עוֹד, עָנִי אֶחָד אַחֵר עָבַר לִפְנֵי רַבִּי יִצְחָק, וְהָיָה בְּיָדוֹ חֲצִי מָעָה כֶּסֶף. אָמַר לְרַבִּי יִצְחָק: הַשְׁלֵם לִי וּלְבָנַי וְלִבְנוֹתַי אֶת נַפְשׁוֹתֵינוּ. אָמַר לוֹ: וְאֵיךְ אַשְׁלִים לְנַפְשׁוֹתֵיכֶם, שֶׁהֲרֵי לֹא נִמְצָא אֶצְלִי כִּי אִם חֲצִי מָעָה? אָמַר לוֹ: בָּזֶה אֲנִי אַשְׁלִים בַּחֲצִי מָעָה שֶׁיֵּשׁ אֶצְלִי. הוֹצִיאָהּ וְנָתַן לוֹ."],[3,"","הֶרְאוּ לוֹ בַּחֲלוֹמוֹ, שֶׁהָיָה עוֹבֵר עַל שְׂפַת הַיָּם הַגָּדוֹל וְרָצוּ לִזְרֹק אוֹתוֹ לְתוֹכוֹ, רָאָה אֶת רַבִּי שִׁמְעוֹן שֶׁהוֹשִׁיט יָדוֹ כְּנֶגְדּוֹ, וּבָא אוֹתוֹ עָנִי וְהוֹצִיאוֹ, וּנְתָנוֹ בִּידֵי רַבִּי שִׁמְעוֹן וְנִצַּל. כְּשֶׁהִתְעוֹרֵר, נָפַל בְּפִיו פָּסוּק זֶה, (תהלים מא) אַשְׁרֵי מַשְׂכִּיל אֶל דָּל בְּיוֹם רָעָה יְמַלְּטֵהוּ ה'."],[4,"","וּבֹא רְאֵה, כָּל יוֹם וָיוֹם נוֹטֵף טַל מֵהָעַתִּיק הַקָּדוֹשׁ לִזְעֵיר אַנְפִּין, וּמִתְבָּרְכִים כָּל שְׂדֵה הַתַּפּוּחִים הַקְּדוֹשִׁים, וּמֵאוֹתוֹ טַל נִשְׁפָּע לְאֵלּוּ שֶׁלְּמַטָּה, וּמִמֶּנּוּ נִזּוֹנִים מַלְאָכִים קְדוֹשִׁים, כָּל אֶחָד וְאֶחָד כְּפִי מַאֲכָלוֹ. זֶהוּ שֶׁכָּתוּב (שם עח) לֶחֶם אַבִּירִים אָכַל אִישׁ, וּמֵאוֹתוֹ מָזוֹן אָכְלוּ יִשְׂרָאֵל בַּמִּדְבָּר."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, כַּמָּה בְּנֵי אָדָם נִזּוֹנִים בַּזְּמַן הַזֶּה מִמֶּנּוּ, וּמִי הֵם? אֵלּוּ הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת. וְכִי יַעֲלֶה עַל דַּעְתְּךְ מֵאוֹתוֹ מָזוֹן מַמָּשׁ? לֹא, אֶלָּא כְּעֵין אוֹתוֹ מָזוֹן מַמָּשׁ שֶׁשָּׁקוּל עַל אֶחָד פִּי שְׁנַיִם."],[6,"","בֹּא רְאֵה, כְּשֶׁנִּכְנְסוּ יִשְׂרָאֵל וְנִדְבְּקוּ בַּמֶּלֶךְ הַקָּדוֹשׁ מִשּׁוּם גִּלּוּי שֶׁל הָרֹשֶׁם הַקָּדוֹשׁ, אָז זָכוּ לֶאֱכֹל לֶחֶם אַחֵר עֶלְיוֹן יוֹתֵר מִמַּה שֶּׁהָיָה בַּתְּחִלָּה. בַּתְּחִלָּה, כְּשֶׁיָּצְאוּ מִמִּצְרַיִם, נִכְנְסוּ לְלֶחֶם שֶׁנִּקְרָא מַצָּה, וְכָעֵת זָכוּ וְנִכְנְסוּ לֶאֱכֹל לֶחֶם אַחֵר יוֹתֵר עֶלְיוֹן, מִמָּקוֹם עֶלְיוֹן, שֶׁכָּתוּב הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. מִן הַשָּׁמַיִם מַמָּשׁ. וּבְאוֹתוֹ זְמַן הוּא נִמְצָא לָהֶם לְיִשְׂרָאֵל מִמָּקוֹם זֶה. חֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, נִזּוֹנוּ מִמָּקוֹם אַחֵר יוֹתֵר עֶלְיוֹן, וּמַהוּ? כַּכָּתוּב (קהלת ז) הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. מָקוֹם יוֹתֵר עֶלְיוֹן."],[7,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, אִם כָּךְ, לָמָּה חָלְשָׁה נַפְשָׁם יוֹתֵר מִשְּׁאָר בְּנֵי הָעוֹלָם, שֶׁהֲרֵי שְׁאָר בְּנֵי הָעוֹלָם בְּכֹחַ וְחֹזֶק יָתֵר נִרְאִים לְהִמָּצֵא (הם יותר) ? אָמַר לוֹ, יָפֶה שָׁאַלְתָּ."],[8,"","בֹּא רְאֵה, כָּל מְזוֹנוֹתֵיהֶם שֶׁל בְּנֵי הָעוֹלָם בָּאִים מִלְמַעְלָה. אוֹתוֹ מָזוֹן שֶׁבָּא מִן הַשָּׁמַיִם וְהָאָרֶץ, זֶה מָזוֹן שֶׁל כָּל הָעוֹלָם, וְהוּא מָזוֹן שֶׁל הַכֹּל, וְהוּא מָזוֹן גַּס וְעָב. וְאוֹתוֹ מָזוֹן שֶׁבָּא יוֹתֵר מִלְמַעְלָה, הוּא מָזוֹן יוֹתֵר דַּקִּיק, שֶׁבָּא מִמָּקוֹם שֶׁנִּמְצָא הַדִּין, וְזֶהוּ הַמָּזוֹן שֶׁאָכְלוּ יִשְׂרָאֵל כְּשֶׁיָּצְאוּ מִמִּצְרַיִם. (יותר דקיק) הַמָּזוֹן שֶׁנִּמְצָא לָהֶם לְיִשְׂרָאֵל בְּאוֹתוֹ זְמַן בַּמִּדְבָּר, מִמָּקוֹם עֶלְיוֹן שֶׁנִּקְרָא שָׁמַיִם, הוּא מָזוֹן יוֹתֵר דַּקִּיק, שֶׁנִּכְנַס יוֹתֵר לַנֶּפֶשׁ מֵהַכֹּל, וְנִפְרַד יוֹתֵר מֵהַגּוּף, וְנִקְרָא לֶחֶם אַבִּירִים."],[9,"","הַמָּזוֹן הַיּוֹתֵר עֶלְיוֹן מֵהַכֹּל הוּא מְזוֹן הַחֲבֵרִים, אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁאוֹכְלִים מָזוֹן שֶׁל רוּחַ וּנְשָׁמָה, וְלֹא אוֹכְלִים מְזוֹן הַגּוּף כְּלָל, וְהַיְינוּ מִמָּקוֹם עֶלְיוֹן נִכְבָּד עַל הַכֹּל, וְנִקְרָא חָכְמָה. לָכֵן חַלָּשׁ גּוּף הַחֲבֵרִים יוֹתֵר מִבְּנֵי הָעוֹלָם, שֶׁהֲרֵי לֹא אוֹכְלִים מְזוֹן הַגּוּף כְּלָל, וְאוֹכְלִים מָזוֹן שֶׁל רוּחַ וּנְשָׁמָה מִמָּקוֹם רָחוֹק עֶלְיוֹן נִכְבָּד מֵהַכֹּל. וְלָכֵן אוֹתוֹ מָזוֹן דַּקִּיק מִן הַדַּקִּיק יוֹתֵר מֵהַכֹּל. אַשְׁרֵי חֶלְקָם. זֶהוּ שֶׁכָּתוּב הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. אַשְׁרֵי חֶלְקוֹ שֶׁל הַגּוּף שֶׁיָּכוֹל לְהִזּוֹן בִּמְזוֹן הַנֶּפֶשׁ."]]],[["אֲמַר לֵיהּ ר' אֶלְעָזָר, וַדַּאי הָכִי הוּא. אֲבָל בְּהַאי זִמְנָא, אֵיךְ אִשְׁתַּכְּחֵי מְזוֹנֵי אִלֵּין. אֲמַר לֵיהּ וַדַּאי יֵאוֹת שָׁאִילְתָּא. תָּא חֲזֵי, וְדָא הוּא בְּרִירוּ דְּמִלָּה, מְזוֹנָא קַדְמָאָה, הוּא מְזוֹנָא דְּכָל עָלְמָא, הַהוּא דְּאַתְיָא מִן שְׁמַיָּא וְאַרְעָא, וְהוּא מְזוֹנָא דְּגוּפָא. (ס\"א דכלא)","מְזוֹנָא דְּהוּא עִלָּאָה מִנֵּיהּ, הַהוּא דְּאִיהוּ דְּקִיקָא יַתִּיר, וְאָתָא מֵאֲתָר דְּדִינָא שַׁרְיָא, דְּאִקְרֵי צֶדֶק, וְדָא הוּא מְזוֹנָא דְּמִסְכְּנֵי. וְרָזָא דְּמִלָּה, מַאן דְּאַשְׁלִים לְמִסְכְּנָא, אַשְׁלִים לֵיהּ אָת חַד, וְאִתְעָבִיד צְדָקָה, וְרָזָא דָּא (משלי י״א:י״ז) גּוֹמֵל נַפְשׁוֹ אִישׁ חֶסֶד. גְּמִילוּת חֲסָדִים מַשְׁמַע, דְּהָא בְּדִינָא שַׁרְיָא, וְאַשְׁלִים לֵיהּ חֶסֶד, כְּדֵין הוּא רַחֲמֵי.","מְזוֹנָא עִלָּאָה יַתִּיר מֵאִלֵּין, הוּא מְזוֹנָא עִלָּאָה וְיַקִּירָא, מֵאֲתָר דְּאִקְרֵי שָׁמַיִם, וְהוּא דָּקִיק מִכֻּלְּהוּ, וְהוּא מְזוֹנָא דִּבְנֵי מַרְעֵי, הֲדָא הוּא דִכְתִיב, (תהילים מ״א:ד׳) יְיָ' יִסְעָדֶנּוּ עַל עֶרֶשׂ דְּוָי כָּל מִשְׁכָּבוֹ הָפַכְתָּ בְחָלְיוֹ. יְיָ', דַּיְיקָא, מַאי טַעְמָא. בְּגִין דְּהָנֵי בְּנֵי מַרְעֵי, לָא אִתְּזְנֵי אֶלָּא בְּהַהוּא דְּקוּדְשָׁא בְּרִיךְ הוּא מַמָּשׁ. (ומאי איהו, חלב ודם. הדא הוא דכתיב (יחזקאל מה) להקריב לי חלב ודם. ודא הוא מזונא מאתר דאקרי שמים, והוא יקירא ועילאה דקיק מכלא)","מְזוֹנָא עִלָּאָה קַדִּישָׁא וְיַקִּירָא דָּא הוּא מְזוֹנֵי דְּרוּחִין וְנִשְׁמָתִין, וְהוּא מְזוֹנָא דַּאֲתָר רְחִיקָא עִלָּאָה, (ס\"א מההוא אתר דאקרי נועם יי'.)","וְיַקִּירָא מִכֹּלָּא, הוּא מְזוֹנָא דְּחַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְהוּא מְזוֹנָא דְּאָתֵי מֵחָכְמָה עִלָּאָה. מַאי טַעְמָא מֵאֲתָר דָּא. בְּגִין דְּאוֹרַיְיתָא נַפְקָא (בראשית מ\"ז ע\"ב, ויקרא קפ\"ו ע\"ב וקצ\"ב ע\"ב) מֵחָכְמָה עִלָּאָה, וְאִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, עַיְילֵי בְּעִקָרָא דְּשָׁרְשָׁהָא, וְעַל דָּא, מְזוֹנָא דִּלְהוֹן, מֵהַהוּא אֲתָר עִלָּאָה קַדִּישָׁא קָא אַתְיָא.","אָתָא ר' אֶלְעָזָר, וְנָשִׁיק יְדוֹי. אָמַר, זַכָּאָה חוּלָקִי דְּקָאִימְנָא בְּמִלִּין אִלֵּין. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, דְּזָכֵי לוֹן בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, דִּכְתִּיב, (דברים ל׳:כ׳) כִּי הוּא חַיֶּיךָ וְאוֹרֶךְ יָמֶיךָ.","(שמות ט״ז:ד׳) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רִבִּי יוֹסֵי פָּתַח, (תהילים קמ״ה:ט״ז) פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. מַה כְּתִיב לְעֵילָּא, עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ. כָּל אִינּוּן בְּנִי עָלְמָא, מְצַפָּאן וְזַקְפָאן עַיְינִין לְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין כַּךְ, (ס\"א אבל) כָּל אִינּוּן בְּנֵי מְהֵימָנוּתָא בָּעָאן (ס\"א אצטריכן למבעי) בְּכָל יוֹמָא וְיוֹמָא, לְשָׁאָלָא מְזוֹנַיְיהוּ מִּקוּדְשָׁא בְּרִיךְ הוּא, וּלְצַלָּאָה צְלוֹתֵהוֹן עָלֵיהּ.","מַאי טַעְמָא. בְּגִין דְּכָל מַאן דִּמְצַלֵי צְלוֹתֵיהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל מְזוֹנֵיהּ, גָּרִים דְּיִתְבָּרֵךְ כָּל יוֹמָא עַל יְדוֹי, הַהוּא אִילָנָא דְּמָזוֹן דְּכֹלָּא בֵּיהּ. (וטעמא דמלה (תהילים ס״ח:כ׳) ברוך ה' יום יום) וְאַף עַל גַּב דְּאִשְׁתְּכַח עִמֵּיהּ, בָּעֵי לְמִשְׁאַל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּלְצַלָּאָה צְלוֹתָא עַל מְזוֹנָא כָּל יוֹמָא, בְּגִין דְּיִשְׁתְּכָחוּ עַל יְדוֹי בִּרְכָּאן כָּל יוֹמָא וְיוֹמָא לְעֵילָּא, וְדָא הוּא בָּרוּךְ יְיָ' יוֹם יוֹם.","ועַל דָּא, לָא לִבָעֵי לֵיהּ לֶאֱינָשׁ לְבַשְּׁלָא מְזוֹנָא, מִן יוֹמָא לְיוֹמָא אַחֲרִינָא, דְּלָא לְעַכֵּב יוֹמָא לְיוֹמָא אַחֲרָא. הֲדָא הוּא דִכְתִיב וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ, דַּיְיקָא. בַּר מֵעֶרֶב שַׁבָּת לְשַׁבָּת, כְּמָה דְּאוֹקִימְנָא. וּכְדֵין אִשְׁתְּכַח קוּדְשָׁא בְּרִיךְ הוּא מָלֵא בִּרְכָּאן בְּכָל יוֹמָא. וּכְדֵין כְּתִיב פּוֹתֵחַ אֶת יָדֶךָ וְגוֹ'. מַאי רָצוֹן. הַהוּא רָצוֹן דְּאִשְׁתְּכַח מֵעַתִּיקָא קַדִּישָׁא, וְנָפִיק מִנֵּיהּ רָצוֹן, לְאִשְׁתַּכְּחָא מְזוֹנֵי לְכֹלָּא. וּמַאן דְּשָׁאִיל מְזוֹנֵי בְּכָל יוֹמָא וְיוֹמָא, הַהוּא אִקְרֵי בְּרָא מְהֵימָנָא, בְּרָזָא דִּבְגִינֵיהּ מִשְׁתַּכְחָן בִּרְכָּאן לְעֵילָּא.","ר' אַבָּא פָּתַח וְאָמַר, (תהילים קמ״ז:י״א) רוֹצֶה יְיָ' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ, כַּמָּה אִית לְהוּ לִבְנֵי נָשָׁא לְמֵהַךְ בְּאָרְחוֹי דְּמַלְכָּא קַדִּישָׁא, וּלְמֵהַךְ בְּאָרְחוֹי דְּאוֹרַיְיתָא, בְּגִין דְּיִשְׁתַּכְּחוּן בִּרְכָּאן לְכֻלְּהוּ, לְעִלָּאֵי וּלְתַתָּאֵי.","דְּתַנְיָא, מַאידִּכְתִּיב, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. אֶתְפָּאָר ודַּאי. מַאי מַשְׁמַע. דִּבְגִין יִשְׂרָאֵל לְתַתָּא, קוּדְשָׁא בְּרִיךְ הוּא מִתְפָּאַר לְעֵילָּא. וּמַאי פְּאֵרָא דִּילֵיהּ. דְּאִתְחַבָּשׁ בִּתְפִילִין, דְּמִתְחַבְּרָא גַּוְונִי לְאִתְפָּאַרָא."],[[0,"אמר ליה ר' אלעזר וכו':","א\"ל ר\"א, ודאי כך הוא, אבל בזמן הזה איך נמצאים מזונות אלו. אמר לו, ודאי יפה שאלת. בוא וראה, וזה הוא בירורו של הדבר. מזון הראשון, הוא מזון של כל העולם, ההוא שבא משמים וארץ. והוא מזון הגוף."],[1,"מזונא דהוא עליאה וכו':","מזון שהוא עליון ממנו, ההוא, שהוא יותר דק, בא ממקום שהדין שורה, הנקרא צדק. שהיא מלכות, וזה הוא מזון של עניים, דהיינו מצה הנקרא לחם עוני, וסוד הדבר, מי שהשלים את העני, משלים לו אות אחת על צדק, ונעשה צדקה. וז\"ס גומל נפשו איש חסד, גמילות חסדים יורה, ששורה בדין והשלים אותו עם חסד, אז הוא רחמים."],[2,"מזונא עלאה יתיר וכו':","מזון עליון יותר מאלו, הוא מזון עליון ויקר ממקום שנקרא שמים, שהוא ז\"א, דהיינו מן שאכלו ישראל במדבר. והוא דק יותר מכולם. והוא מזון של חולים. ז\"ש ה' יסעדנו על ערש דוי כל משכבו הפכת בחליו, ה' הוא בדיוק, שהוא ז\"א. מהו הטעם, משום שאלו החולים אינם ניזונים אלא במזון ההוא של הקב\"ה ממש. דהיינו ז\"א."],[3,"מזונא עלאה קדישא וכו':","מזון עליון קדוש ויקר, זה הוא מזון של רוחות ונשמות, והוא מזון של מקום רחוק העליון. שהוא בינה שחזרה להיות חכמה. שעליה נאמר אמרתי אחכמה והיא רחוקה ממני. ממקום ההוא שנקרא נועם ה'. דהיינו בינה שחזרה לחכמה."],[4,"ויקירא מכלא הוא וכו':","ויקר מכולם הוא המזון שהחברים העוסקים בתורה אוכלים אותו, והוא מזון הבא מחכמה עליונה, שהוא חכמה ממש. מה הטעם שבא ממקום הזה. הוא משום שהתורה יוצאת מחכמה העליונה, ואלו העוסקים בתורה נכנסים בעיקר השרשים, וע\"כ המזון שלהם, ממקום ההוא העליון הקדוש בא."],[5,"אתא ר' אלעזר וכו':","בא ר' אלעזר ונשק ידיו של ר\"ש אביו. אמר אשרי חלקי שעמדתי בדברים אלו, אשרי חלקם של הצדיקים העוסקים בתורה ימים ולילות, שמזכה אותם בעולם הזה ובעולם הבא. שכתוב, כי הוא חייך ואורך ימיך."],[6,"הנני ממטיר לכם לחם וגו':","ר' יוסי פתח, פותח את ידיך ומשביע לכל חי רצון. מה כתוב למעלה, עיני כל אליך ישברו. כל בני העולם מצפים ונושאים עיניהם אל הקב\"ה, משום זה, כל אלו בעלי האמונה צריכים בכל יום ויום לבקש מזונם מהקב\"ה, ולהתפלל תפלתם עליו."],[7,"מ\"ט בגין וכו':","שואל, מהו הטעם. ואומר, משום שכל מי שמתפלל תפלתו אל הקב\"ה על מזונותיו, גורם שיתברך על ידיו כל יום, אילן ההוא שמזון הכל בו. ואע\"פ שנמצא עמו מזון, צריך לבקש עליו לפני הקב\"ה ולהתפלל תפלתו על מזון כל יום, כדי שימצאו על ידו ברכות למעלה, בכל יום ויום. וזהו ברוך ה' יום יום."],[8,"ועל דא לא לבעי וכו':","וע\"כ, אין אדם צריך לבשל מזונות מיום ליום אחר, שלא לעכב מיום ליום אחר. ז\"ש ויצא העם ולקטו דבר יום ביומו. יום ביומו, הוא מדויק, חוץ מערב שבת לשבת, כמו שהעמדנו. ואז נמצא הקב\"ה מלא ברכות בכל יום. ואז כתוב, פותח את ידיך ומשביע לכל חי רצון. מהו רצון. היינו רצון ההוא שנמצא מעתיקא קדישא, שהוא כתר, ויוצא ממנו רצון שיהיה נמצא מזון לכל. ומי שמבקש על מזון בכל יום ויום, ההוא נקרא בן נאמן, בן, שבשבילו נמצא ברכות למעלה."],[9,"ר' אבא פתח וכו':","רא\"פ ואמר, רוצה ה' את יראיו המיחלים לחסדו, כמה יש לבני אדם ללכת בדרכיו של המלך הקדוש, וללכת בדרכיה של התורה, כדי שימצאו ברכות לכולם לעליונים ולתחתונים."],[10,"דתניא מאי דכתיב וכו':","שלמדנו, מה שכתוב, ישראל אשר בך אתפאר. אתפאר ודאי. מה פירושו. הוא משום שבשביל ישראל למטה, שמעלים מ\"ן, הקב\"ה מתפאר למעלה ומה פאר שלו, שמניח תפלין, פירוש, ע\"י המן שישראל מעלים יוצאים מוחין לז\"א שנקראים תפילין, שמתחבר בהם צבעים להתפאר. כי ד' פרשיות ה\"ס ג' צבעים לבן אדום ירוק, והם מתחברים בסוד ג' קוים, להאיר בכל השלמות."]],[[0,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, וַדַּאי כָּךְ הוּא. אֲבָל בַּזְּמַן הַזֶּה אֵיךְ נִמְצָאִים מְזוֹנוֹת אֵלוּ? אָמַר לוֹ, וַדַּאי שֶׁיָּפֶה שָׁאַלְתָּ. בּא רְאֵה, וְזֶהוּ בֵּרוּר הַדָּבָר, מָזוֹן רִאשׁוֹן הוּא מָזוֹן שֶׁל כָּל הָעוֹלָם, אוֹתוֹ שֶׁבָּא מִשָּׁמַיִם וָאָרֶץ, וְהוּא מְזוֹן הַגּוּף (של הכל)."],[1,"","מָזוֹן שֶׁהוּא יוֹתֵר עֶלְיוֹן מִמֶּנּוּ, אוֹתוֹ שֶׁהוּא יוֹתֵר דַּקִּיר, וּבָא מִמָּקוֹם שֶׁהַדִּין שָׁרוּי, שֶׁנִּקְרָא צֶדֶק, וְזֶהוּ מְזוֹן הָעֲנִיִּים. וְסוֹד הַדָּבָר - מִי שֶׁמַּשְׁלִים לֶעָנִי, מַשְׁלִים לוֹ אוֹת אַחַת וְנַעֲשֶׂה צְדָקָה, וְסוֹד זֶה - (משלי יא) גֹּמֵל נַפְשׁוֹ אִישׁ חָסֶד. גְּמִילוּת חֲסָדִים מַשְׁמָע, שֶׁהֲרֵי בְּדִין שָׁרוּי, וְהִשְׁלִים לוֹ חֶסֶד, אָז הוּא רַחֲמִים."],[2,"","מָזוֹן יוֹתֵר עֶלְיוֹן מֵאֵלֶּה, הוּא מָזוֹן עֶלְיוֹן וְנִכְבָּד מִמָּקוֹם שֶׁנִּקְרָא שָׁמַיִם, וְהוּא דַּקִּיק מִכֻּלָּם, וְהוּא מָזוֹן שֶׁל חוֹלִים. זֶהוּ שֶׁכָּתוּב (תהלים מא) ה' יִסְעָדֶנּוּ עַל עֶרֶשׂ דְּוָי כָּל מִשְׁכָּבוֹ הָפַכְתָּ בְחָלְיוֹ. ה' דַּוְקָא. מָה הַטַּעַם? מִשּׁוּם שֶׁהַחוֹלִים הַלָּלוּ אֵינָם נִזּוֹנִים אֶלָּא בְּאוֹתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מַמָּשׁ. (ומהו, ' חלב ודם. זהו שכתוב (יחזקאל מד) להקריב לי חלב ודם. וזהו מזון ממקום שגקרא שמים, והוא נכבד ועליון, דקיק מהכל)."],[3,"","מָזוֹן עֶלְיוֹן קָדוֹשׁ וְנִכְבָּד זֶהוּ מְזוֹנוֹת שֶׁל רוּחוֹת וּנְשָׁמוֹת, וְהוּא מָזוֹן שֶׁל מָקוֹם רָחוֹק עֶלְיוֹן, (מאותו מקום שגקרא נעם ה')."],[4,"","וְהַנִּכְבָּד מֵהַכֹּל הוּא מְזוֹן הַחֲבֵרִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, וְהוּא מָזוֹן שֶׁבָּא מֵחָכְמָה עֶלְיוֹנָה. מָה הַטַּעַם מִמָּקוֹם זֶה? מִשּׁוּם שֶׁתּוֹרָה יָצְאָה מֵחָכְמָה עֶלְיוֹנָה, וְאוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה נִכְנָסִים בְּעִקַּר שָׁרָשֶׁיהָ, וְלָכֵן מְזוֹנָם בָּא מֵאוֹתוֹ מָקוֹם קָדוֹשׁ עֶלְיוֹן."],[5,"","בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ. אָמַר, אַשְׁרֵי חֶלְקִי שֶׁעָמַדְתִּי בַּדְּבָרִים הַלָּלוּ! אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת, שֶׁזּוֹכִים לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (דברים ל) כִּי הוּא חַיֶּיךְ וְאֹרֶךְ יָמֶיךְ."],[6,"","הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם. רַבִּי יוֹסֵי פָּתַח, (תהליםקמה) פּוֹתֵחַ אֶת יָדֶךְ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן. מַה כָּתוּב לְמַעְלָה? עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ. כָּל אוֹתָם בְּנֵי הָעוֹלָם מְצַפִּים וְזוֹקְפִים עֵינַיִם לַקָּדוֹשׁ- בָּרוּךְ-הוּא, וְלָכֵן (אבל) כָּל אוֹתָם בְּנֵי הָאֱמוּנָה מְבַקְשִׁים (צריכיםלבקש) בְּכָל יוֹם וָיוֹם לִשְׁאֹל אֶת מְזוֹנָם מִן הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְפַּלֵּל תְּפִלּוֹתֵיהֶם עָלָיו."],[7,"","מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ לַקָּדוֹשׁ-בָּרוּךְ- הוּא עַל מְזוֹנוֹ, גּוֹרֵם שֶׁיִּתְבָּרֵךְ כָּל הַיּוֹם עַל יָדוֹ אוֹתוֹ הָאִילָן שֶׁמְּזוֹן כֻּלָּם בּוֹ. (וטעם הדבר (תהלים סח) ברוך ה' יום יום) וְאַף עַל גַּב שֶׁנִּמְצָא עִמּוֹ, צָרִיךְ לְבַקֵּשׁ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִתְפַּלֵּל תְּפִלָּה עַל הַמָּזוֹן בְּכָל יוֹם, כְּדֵי שֶׁיִּמָּצְאוּ עַל יָדוֹ בְּרָכוֹת כָּל יוֹם וָיוֹם לְמַעְלָה, וְזֶהוּ (שם סח) בָּרוּךְ ה' יוֹם יוֹם."],[8,"","וְעַל זֶה לֹא צָרִיךְ לָאָדָם לְבַשֵּׁל מָזוֹן מִיּוֹם לְיוֹם אַחֵר, שֶׁלֹּא לְעַכֵּב יוֹם לְיוֹם אַחֵר. זֶהוּ שֶׁכָּתוּב וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ דַּוְקָא, חוּץ מֵעֶרֶב שַׁבָּת לְשַׁבָּת, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאָז נִמְצָא הַקָּדוֹשׁ בָּרוּךְ הוּא מָלֵא בְּרָכוֹת בְּכָל יוֹם, וְאָז כָּתוּב פּוֹתֵחַ אֶת יָדֶךְ וְגוֹ'. מָה זֶה רָצוֹן? אוֹתוֹ רָצוֹן שֶׁנִּמְצָא מֵהָעַתִּיק הַקָּדוֹשׁ, וְיוֹצֵא מִמֶּנּוּ רָצוֹן לְהַמְצִיא מָזוֹן לַכֹּל. וּמִי שֶׁשּׁוֹאֵל מְזוֹנוֹת בְּכָל יוֹם וָיוֹם, הַהוּא נִקְרָא בֵּן נֶאֱמָן, בְּסוֹד שֶׁבִּשְׁבִילוֹ נִמְצָאִים בְּרָכוֹת לְמַעְלָה."],[9,"","רַבִּי אַבָּא פָּתַח וְאָמַר, (שם קמז) רוֹצֶה ה' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. כַּמָּה יֵשׁ לִבְנֵי אָדָם לָלֶכֶת בְּדַרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְלָלֶכֶת בְּדַרְכֵי הַתּוֹרָה כְּדֵי שֶׁיִּמָּצְאוּ בְרָכוֹת לְכֻלָּם, לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים."],[10,"","שֶׁלָּמַדְנוּ, מַה שֶּׁכָּתוּב (ישעיה מט) יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר, וַדַּאי אֶתְפָּאָר. מַה מַּשְׁמִיעַ? שֶׁבִּשְׁבִיל יִשְׂרָאֵל לְמַטָּה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְפָּאֵר לְמַעְלָה. וּמָה הַפְּאֵר שֶׁלּוֹ? שֶׁמֵּנִיחַ תְּפִלִּין, שֶׁמִּתְחַבְּרִים הַגְּוָנִים לְהִתְפָּאֵר."]]],[["תָּאנָא, רוֹצֶה יְיָ' אֶת יְרֵאָיו, רוֹצֶה יְיָ' בִּירֵאָיו מִבָּעֵי לֵיהּ. מַאי רוֹצֶה יְיָ' אֶת יְרֵאָיו, אֶלָּא רוֹצֶה יְיָ' אֶת יְרֵאָיו, כְּלוֹמַר, אַפִּיק הַאי רָצוֹן, וּמִתְרָעֵי (נ\"א ואתידע) בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, לִירֵאָיו דְּדָחֲלִין לֵיהּ. וּמַאן אִינּוּן יְרֵאָיו דְּאַפִּיק לוֹן הַאי רָצוֹן. הָדַר וְאָמַר, אֶת הַמְיַחֲלִים לְחַסְדּוֹ, אִינּוּן דִּמְצָפָאן וּמְחַכָּאן בְּכָל יוֹמָא וְיוֹמָא, לְמִבָּעֵי מְזוֹנַיְיהוּ מִן קוּדְשָׁא בְּרִיךְ הוּא, מַשְׁמַע דִּכְתִּיב אֶת הַמְיַחֲלִים לְחַסְדּוֹ.","רִבִּי יֵיסָא סָבָא, לָא אַתְקִין סְעוּדָתָא בְּכָל יוֹמָא, עַד דְּבָעָא בָּעוּתֵיהּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, עַל מְזוֹנֵי. אָמַר, לָא נַתְקִין סְעוּדָתָא, עַד דְּתִתְיְהִיב מִבֵּי מַלְכָּא. לְבָתַר דְּבָעֵי בָּעוּתֵיהּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, הֲוָה מְחַכֶּה שַׁעֲתָא חֲדָא, אָמַר הָא עִידָן דְּתִתְיְהִיב מִבֵּי מַלְכָּא, מִכָּאן וּלְהָלְאָה אַתְקִינוּ סְעוּדָתָא. וְדָא הוּא אָרְחָא, דְּאִינּוּן דַּחֲלֵי קוּדְשָׁא בְּרִיךְ הוּא, דַּחֲלֵי חַטָּאָה.","אִינּוּן חַיָּיבַיָּא דְּאַזְלִין עֲקִימִין בְּאָרְחֵי אוֹרַיְיתָא, מַה כְּתִיב בְּהוּ. (ישעיהו ה׳:י״א) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדֹּפוּ. וְעַל דָּא רוֹצֶה יְיָ' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. לְחַסְדּוֹ דַּיְיקָא. (ס\"א ובהא) אִשְׁתְּמוֹדְעָן אִינּוּן בְּנֵי מְהֵימָנוּתָא בְּכָל יוֹמָא וְיוֹמָא, הֲדָא הוּא דִּכְתִּיב, וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ קָאָמַר, וְלֹא דְּבַר יוֹם לְיוֹם אַחֵר.","וְכָל כַּךְ לָמָּה. לְמַעַן אֲנַסֶּנּוּ הֲיֵלֶךְ בְּתוֹרָתִי אִם לא בְּכָאן אִשְׁתְּמוֹדְעָן אִינּוּן בְּנֵי מְהֵימָנוּתָא, דְּכָל יוֹמָא וְיוֹמָא אִינּוּן אַזְלֵי בְּאֹרַח מֵישָׁר בְּאוֹרַיְיתָא. רִבִּי יִצְחָק אָמַר מֵהָכָא, (משלי י״ג:כ״ה) צַדִּיק אוֹכֵל לְשׂוֹבַע נַפְשׁוֹ, בָּתַר דְּשָׂבַע נַפְשֵׁיהּ מִלְּצַלֵּי וּלְמִקְרֵי בְּאוֹרַיְיתָא.","רִבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, עַד לָא יָהַב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, אַבְחִין בֵּין אִינּוּן בְּנִי מְהֵימָנוּתָא, וּבֵין אִינּוּן חַיָּיבַיָּא דְּלָאו אִינּוּן בְּנִי מְהֵימָנוּתָא, וְלָא קַיְימִין בְּאוֹרַיְיתָא. וּבַמֶּה אַבְחִין לוֹן. בַּמָּן. כְּמָה דְּאִתְּמַר אֲנַסֶּנּוּ. וְכָל אִינּוּן דְּאִשְׁתְּכָחוּ דְּאִינּוּן בְּנֵי מְהֵימָנוּתָא, רָשִׁים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בִּרְשִׁימוּ דְּכִתְרָא דְּחֶסֶ\"ד, כְּמָה דְאַתְּ אָמֵר הַמְיַחֲלִים לְחַסְדּוֹ, וְעַל דָּא לְמַעַן אֲנַסֶּנּוּ. וְכָל אִינּוּן דְּלָא מִשְׁתַּכְּחֵי בְּנִי מְהֵימָנוּתָא, אַעְדֵּי מִנַּיְיהוּ כִּתְרָא עִלָּאָה דָּא. וּמָנָא אַכְרִיז וְאָמַר, (משלי י״ג:כ״ה) וּבֶטֶן רְשָׁעִים תֶחְסַר. וְעִם כָּל דָּא לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לא הֶחְסִיר.","תָּאנָא, בְּהַהוּא שַׁעֲתָא אִשְׁתְּלִימוּ יִשְׂרָאֵל לְתַתָּא, כְּגַוְונָא דִּלְעֵילָּא, כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (שמות ט״ו:כ״ז) וַיָּבוֹאוּ אֵלִימָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינוֹת מַיִם וְשִׁבְעִים תְּמָרִים וְגו'. וְאִתְתָּקַּף אִילָנָא קַדִּישָׁא, בִּתְרֵיסַר תְּחוּמִין, בְּאַרְבַּע סִטְרֵי עָלְמָא. וְאִתְתָּקַּף בְּשִׁבְעִין עַנְפִין, וְכֹלָּא כְּגַוְונָא דִּלְעֵילָּא.","בְּהַהִיא שַׁעֲתָא, נָטִיף טַלָּא קַדִּישָׁא, מֵעַתִּיקָא סְתִימָאָה, וּמַלְיָא לְרֵישֵׁיהּ דִּזְעֵיר אַנְפִּין, אֲתָר דְּאִקְרֵי שָׁמַיִם. וּמֵהַהוּא טַלָּא דִּנְהוֹרָא עִלָּאָה קַדִּישָׁא, הֲוָה נָגִיד וְנָחִית מָנָא לְתַתָּא. וְכַד הֲוָה נָחִית, הֲוָה מִתְפְּרַשׁ גְּלִידִין גְּלִידִין, וְאַקְרִישׁ לְתַתָּא. הֲדָא הוּא דִּכְתִּיב דַּק כַּכְּפוֹר עַל הָאָרֶץ.","כָּל אִינּוּן בְּנֵי מְהֵימָנוּתָא, נַפְקֵי וְלַקְטֵי, וּמְבָרְכָאן שְׁמָא קַדִּישָׁא עָלֵיהּ. וְהַהוּא מָנָא, הֲוָה סָלִיק רֵיחִין דְּכָל בּוּסְמִין דְּגִנְתָּא דְּעֵדֶן, דְּהָא בֵּיהּ אִתְמְשַׁךְ וְנָחִית לְתַתָּא. שַׁוְיֵהּ לְקַמֵיהּ, בְּכָל טַעֲמָא דְּאִיהוּ בָּעֵי, הָכִי טָעִים לֵיהּ, וּמְבָרֵךְ לְמַלְכָּא קַדִּישָׁא עִלָּאָה.","וּכְדֵין מִתְבָּרֵךְ בְּמֵעוֹי, וַהֲוָה מִסְתַּכֵּל וְיָדַע לְעֵילָּא, וְאִסְתָּכֵי בְּחָכְמָה עִלָּאָה, וְעַל דָּא אִקְרוּן דּוֹר דֵּעָה. וְאִלֵּין הֲווֹ בְּנֵי מְהֵימָנוּתָא, וּלְהוֹן אִתְיְהִיבַת אוֹרַיְיתָא לְאִסְתַּכְּלָא בָּהּ, וּלְמִנְדַּע אָרְחָהָא.","וְאִינּוּן דְּלָא אִשְׁתְּכָחוּ בְּנִי מְהֵימָנוּתָא, מַה כְּתִיב בְּהוּ, (במדבר י״א:ח׳) שָׁטוּ הָעָם וְלָקְטוּ. מַאי שָׁטוּ. שְׁטוּתָא הֲווֹ נַסְבֵּי לְגַרְמַיְיהוּ, בְּגִין דְּלָא הֲווֹ בְּנֵי מְהֵימָנוּתָא. מַה כְּתִיב בְּהוּ. וְטָחֲנוּ בָרֵחַיִם אוֹ דָכוּ בַּמְּדוֹכָה וְגוֹ'. מַאן אַטְרַח לוֹן כָּל הַאי. אֶלָּא דְּאִינּוּן לָא הֲווֹ בְּנֵי מְהֵימָנוּתָא."],[[0,"תאנא רוצה וכו':","למדנו. רוצה ה' את יראיו. שואל, רוצה ה' ביראיו היה צריך לומר. מהו, רוצה ה' את יראיו. ומשיב, אלא רוצה ה' את יראיו, כלומר, הוציא רצון הזה ורצה בו את יראיו היראים ממנו. ומי הם היראים שהוציא להם הרצון הזה, חזר ואמר, את המיחלים לחסדו, דהיינו אלו המצפים ומחכים בכל יום ויום לבקש מזונם מן הקב\"ה. זה משמע, משכתוב, המיחלים לחסדו."],[1,"ר' ייסא סבא וכו':","רי\"ס, לא התקין סעודתו בכל יום עד שהתפלל תפלתו לפני הקב\"ה על מזונות. אמר לא נתקן הסעודה עד שתהיה נתונה מבית המלך. אחר שהתפלל תפלתו לפני הקב\"ה, היה מחכה שעה אחת, אמר, כבר הזמן שניתנה מבית המלך, מכאן ולהלאה התקינו הסעודה. וזהו הדרך של יראי הקב\"ה יראי חטא."],[2,"אינון חייביא דאזלין וכו':","אלו הרשעים ההולכים עקלקלות בדרכי התורה, מה כתוב בהם, הוי משכימי בבוקר שכר ירדופו. וע\"ז, רוצה ה' את יראיו המיחלים לחסדו. לחסדו, הוא בדיוק. ובזה ניכרים אלו בני האמונה בכל יום ויום. ז\"ש ויצאו העם ולקטו דבר יום ביומו, יום ביומו אמר, ולא דבר יום ליום אחר."],[3,"וכל כך למה וכו':","שואל, וכל כך למה. ואומר, שהוא למען אנסנו הילך בתורתי אם לא. בכאן, דהיינו באכילה, ניכרים אלו בני האמונה, שבכל יום ויום הם הולכים בדרך הישר בתורה. ר' יצחק אמר, מכאן, צדיק אוכל לשובע נפשו. פירושו אחר שהשביע נפשו בתפילה ובקריאה בתורה הוא אוכל."],[4,"רבי שמעון אמר וכו':","רש\"א, בוא וראה, עד שלא נתן הקב\"ה התורה לישראל, הבחין בין אלו בני האמונה ובין הרשעים שאינם בני אמונה, ואינם רוצים בתורה. ובמה הבחין אותם במן. כמו שנאמר, \u0003אנסנו.\u0004 וכל אלו הנמצאים שהם בני אמונה, רשם אותו הקב\"ה ברושם של ספירת החסד. כמש\"א, המיחלים לחסדו. וע\"כ למען אנסנו. וכל אלו שאינם נמצאים בני אמונה הסיר מהם ספירה עליונה הזו. והמן הכריז ואמר, ובטן רשעים תחסר, ועם כל זה לא העדיף המרבה והממעיט לא החסיר."],[5,"תאנא בההוא שעתא וכו':","למדנו, בשעה ההוא נשלמו ישראל למטה כעין של מעלה, כמו שהעמדנו, שכתוב, ויבואו אלימה ושם שתים עשרה עינות מים ושבעים תמרים וגו'. שפירושו, שנתחזק האילן הקדוש, שהוא ז\"א, בי\"ב גבולים, בד' צדדי העולם, חו\"ג תו\"מ, כלומר, בג' קוין בכל צד מד' צדדי העולם, חו\"ג תו\"מ, והם י\"ב גבולים שה\"ס שתים עשרה עינות מים. ונתחזק בע' ענפים, שהם ע' שרים, שה\"ס ע' תמרים, והכל כעין של מעלה."],[6,"בההיא שעתא נטיף וכו':","בשעה ההיא. נוטף טל הקדוש, דהיינו שפע המכונה טל, מעתיקא סתימאה, שהוא כתר, וממלא את ראשו של ז\"א, המקום שנקרא שמים, ומטל ההוא של אור העליון הקדוש, היה נמשך ויורד המן למטה. וכשהיה יורד היה מתפזר כמו קרומים קרומים ונקרש למטה. ז\"ש דק ככפור על הארץ."],[7,"כל אינון בני וכו':","כל אלו בני האמונה יוצאים ולוקטים ומברכים עליו את השם הקדוש. ומן ההוא היה מעלה ריחות של כל הבשמים שבגן עדן, כי בו נמשך ויורד למטה. כשמשימו לפניו, כל טעם שהיה רוצה לטעום טעם אותו. ומברך למלך הקדוש העליון."],[8,"וכדין מתברך במעוי וכו':","ואז המן מתברך במעיו, והיה מסתכל וידע למעלה וצפה בחכמה עליונה, ועל זה הם נקראים דור דעה. ואלו היו בני אמונה, ולהם ניתנה התורה להסתכל בה, ולדעת דרכיה."],[9,"ואינון דלא אשתכחו וכו':","ואלו שלא נמצאו בני אמונה, מה כתוב בהם, שטו העם ולקטו. מהו שטו, שטות היו לוקחים לעצמם, משום שלא היו בני אמונה, מה כתוב בהם, וטחנו ברחים או דכו במדוכה וגו'. מי הטריח אותם כל כך. אלא שהם לא היו בני אמונה."]],[[0,"","שָׁנִינוּ, רוֹצֶה ה' אֶת יְרֵאָיו, רוֹצֶה ה' בִּירֵאָיו הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה רוֹצֶה ה' אֶת יְרֵאָיו? אֶלָּא רוֹצֶה ה' אֶת יְרֵאָיו, כְּלוֹמַר, מוֹצִיא אֶת הָרָצוֹן הַזֶּה, וּמִתְרַצֶּה (ומתידע) בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לִירֵאָיו הַיְרֵאִים מִמֶּנּוּ. וּמִי הֵם הַיְרֵאָיו הָאֵלֶּה שֶׁמּוֹצִיא לָהֶם אֶת הָרָצוֹן הַזֶּה? חָזַר וְאָמַר אֶת הַמְיַחֲלִים לְחַסְדּוֹ, אוֹתָם הַמְצַפִּים וּמְחַכִּים בְּכָל יוֹם וָיוֹם לְבַקֵּשׁ מְזוֹנָם מִן הַקָּדוֹשׁ בָּרוּךְ הוּא, מַשְׁמָע שֶׁכָּתוּב אֶת הַמְיַחֲלִים לְחַסְדּוֹ."],[1,"","רַבִּי יֵיסָא סָבָא לֹא הִתְקִין סְעוּדָה בְּכָל יוֹם עַד שֶׁבִּקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל מְזוֹנוֹת. אָמַר, לֹא נַתְקִין סְעוּדָה עַד שֶׁתִּנָּתֵן מִבֵּית הַמֶּלֶךְ. אַחַר שֶׁבִּקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה מְחַכֶּה שָׁעָה אַחַת, וְאָמַר: הֲרֵי זְמַן שֶׁנִּתָּן מִבֵּית הַמֶּלֶךְ, מִכָּאן וָהָלְאָה הַתְקִינוּ הַסְּעוּדָה! וְזוֹהִי הַדֶּרֶךְ שֶׁל אוֹתָם יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, יִרְאֵי חֵטְא."],[2,"","אוֹתָם הָרְשָׁעִים שֶׁהוֹלְכִים עֲקֻמִּים בְּדַרְכֵי הַתּוֹרָה, מַה כָּתוּב בָּהֶם? (ישעיה ה) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדֹּפוּ. וְעַל זֶה רוֹצֶה ה' אֶת יְרֵאָיו אֶת הַמְיַחֲלִים לְחַסְדּוֹ. דַּוְקָא לְחַסְדּוֹ. (ובזה) נוֹדָעִים בְּנֵי הָאֱמוּנָה בְּכָל יוֹם וָיוֹם. זֶהוּ שֶׁכָּתוּב וְיָצָא הָעָם וְלָקְטוּ דְּבַר יוֹם בְּיוֹמוֹ. יוֹם בְּיוֹמוֹ אָמַר, וְלֹא דְּבַר יוֹם לְיוֹם אַחֵר."],[3,"","וְכָל כָּךְ לָמָּה? לְמַעַן אֲנַסֶּנּוּ הֲיֵלֵךְ בְּתוֹרָתִי אִם לֹא. בְּכָאן נוֹדָעִים אוֹתָם בְּנֵי הָאֱמוּנָה, שֶׁכָּל יוֹם וָיוֹם הוֹלְכִים בְּדֶרֶךְ יְשָׁרָה בַּתּוֹרָה. רַבִּי יִצְחָק אָמַר מִכָּאן, (משלי יג) צַדִּיק אֹכֵל לְשּבַע נַפְשׁוֹ - אַחַר שֶׁהִשְׂבִּיעַ נַפְשׁוֹ מִלְּהִתְפַּלֵּל וְלִקְרֹא בַּתּוֹרָה."],[4,"","רַבִּי שִׁמְעוֹן אָמַר, בֹּא רְאֵה, עַד שֶׁלֹּא נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹרָה לְיִשְׂרָאֵל, הִבְחִין בֵּין אוֹתָם בְּנֵי הָאֱמוּנָה לְבֵין אוֹתָם רְשָׁעִים שֶׁאֵינָם בְּנֵי אֱמוּנָה וְלֹא עוֹמְדִים בַּתּוֹרָה. וּבַמָּה הִבְחִין בָּהֶם? בַּמָּן, כְּמוֹ שֶׁנֶּאֱמַר אֲנַסֶּנּוּ. וְכָל אוֹתָם שֶׁנִּמְצְאוּ שֶׁהֵם בְּנֵי הָאֱמוּנָה, רָשַׁם אוֹתָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרֹשֶׁם שֶׁל כֶּתֶר הַחֶסֶ\"ד, כְּמוֹ שֶׁנֶּאֱמַר הַמְיַחֲלִים לְחַסְדּוֹ, וְעַל זֶה לְמַעַן אֲנַסֶּנּוּ. וְכָל אוֹתָם שֶׁלֹּא נִמְצְאוּ בְּנֵי אֱמוּנָה, הֶעֱבִיר מֵהֶם הַכֶּתֶר הָעֶלְיוֹן הַזֶּה, וְהַמָּן הִכְרִיז וְאָמַר, וּבֶטֶן רְשָׁעִים תֶּחְסָר. וְעִם כָּל זֶה, לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לֹא הֶחְסִיר."],[5,"","שָׁנִינוּ, בַּשָּׁעָה הַהִיא נִשְׁלְמוּ יִשְׂרָאֵל לְמַטָּה כְּדֻגְמָא שֶׁל מַעְלָה, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (שמות טו) וַיָּבאוּ אֵילִמָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינֹת מַיִם וְשִׁבְעִים תְּמָרִים וְגוֹ'. וְהִתְחַזֵּק הָאִילָן הַקָּדוֹשׁ בִּשְׁנֵים עָשָׂר תְּחוּמִים, בְּאַרְבָּעָה צִדְדֵי הָעוֹלָם, וְהִתְחַזֵּק בְּשִׁבְעִים עֲנָפִים, וְהַכֹּל כַּדֻּגְמָא שֶׁל מַעְלָה."],[6,"","בְּאוֹתָהּ שָׁעָה נָטַף טַל קָדוֹשׁ מֵהָעַתִּיק הַנִּסְתָּר, וּמִלֵּא אֶת רֹאשׁוֹ שֶׁל זְעֵיר אַנְפִּין, מָקוֹם שֶׁנִּקְרָא שָׁמַיִם. וּמֵאוֹתוֹ טַל שֶׁל אוֹר עֶלְיוֹן קָדוֹשׁ הָיָה שׁוֹפֵעַ וְיוֹרֵד מָן לְמַטָּה, וּכְשֶׁהָיָה יוֹרֵד, הָיָה נִפְרָד גְּלִידִים גְּלִידִים, וְנִקְרָשׁ לְמַטָּה. זֶהוּ שֶׁכָּתוּב דַּק כַּכְּפֹר עַל הָאָרֶץ."],[7,"","כָּל אוֹתָם בְּנֵי אֱמוּנָה יוֹצְאִים וְלוֹקְטִים, וּמְבָרְכִים עָלָיו אֶת הַשֵּׁם הַקָּדוֹשׁ, וְאוֹתוֹ מָן הָיָה מַעֲלֶה רֵיחוֹת שֶׁל כָּל הַבְּשָׂמִים שֶׁל גַּן עֵדֶן, שֶׁהֲרֵי מִמֶּנּוּ נִמְשַׁךְ וְיָרַד לְמַטָּה. שָׂם אוֹתוֹ לְפָנָיו, וּבְכָל טַעַם שֶׁרָצָה - הָיָה טוֹעֵם אוֹתוֹ, וּמְבָרֵךְ אֶת הַמֶּלֶךְ הַקָּדוֹשׁ."],[8,"","וְאָז מִתְבָּרֵךְ בְּמֵעָיו, וְהָיָה מִסְתַּכֵּל וְיוֹדֵעַ לְמַעְלָה, וּמִסְתַּכֵּל בַּחָכְמָה הָעֶלְיוֹנָה, וְעַל זֶה הָיָה נִקְרָא דּוֹר דֵּעָה. וְאֵלֶּה הָיוּ בְּנֵי אֱמוּנָה, וְלָהֶם נִתְּנָה תּוֹרָה לְהִסְתַּכֵּל בָּהּ וְלָדַעַת דְּרָכֶיהָ."],[9,"","וְאוֹתָם שֶׁלֹּא נִמְצְאוּ בְּנֵי אֱמוּנָה, מַה כָּתוּב בָּהֶם? (במדבר יב) שָׁטוּ הָעָם וְלָקְטוּ. מַה זֶּה שָׁטוּ? שְׁטוּת הָיוּ לוֹקְחִים לְעַצְמָם, מִשּׁוּם שֶׁלֹּא הָיוּ בְּנֵי אֱמוּנָה. מַה כָּתוּב בָּהֶם? וְטָחֲנוּ בָרֵחַיִם אוֹ דָכוּ בַּמְּדכָה וְגוֹ'. מִי הִטְרִיחַ אוֹתָם לְכָל זֶה? אֶלָּא שֶׁהֵם לֹא הָיוּ בְּנֵי אֱמוּנָה."]]],[["כְּגַוְונָא דָּא, אִינּוּן דְּלָא מְהֵימְנֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, לָא בָּעָאן לְאִסְתַּכְּלָא בְּאָרְחוֹי, וְאִינּוּן בָּעָאן לְאַטְרְחָא גַּרְמַיְיהוּ כָּל יוֹמָא בָּתַר מְזוֹנָא, יְמָמָא וְלֵילֵי, דִּלְמָא לָא סָלִיק בִּידַיְיהוּ פִּתָּא דְּנַהֲמָא. מַאן גָּרִים לוֹן הַאי. בְּגִין דְּלָאו אִינּוּן בְּנֵי מְהֵימָנוּתָא.","אוּף הָכָא, שָׁטוּ הָעָם וְלָקְטוּ, שָׁטוּ בִּשְׁטּוּתָא דְּגַרְמַיְיהוּ, וּבָעָאן לְאַטְרְחָא עָלֵיהּ, הֲדָא הוּא דִּכְתִּיב, וְטָחֲנוּ בָרֵחַיִם. בָּתַר כָּל טִרְחָא דָּא, לָא סָלִיק בִּידַיְיהוּ, אֶלָּא דִּכְתִּיב וְהָיָה טַעְמוֹ כְּטַעַם לְשַׁד הַשָּׁמֶן. וְלָא יַתִּיר. מַאן גָּרִים לוֹן הַאי, בְּגִין דְּלָא הֲווֹ בְּנֵי מְהֵימָנוּתָא.","אָמַר רִבִּי יוֹסֵי, מַאי לְשַׁד הַשָּׁמֶן. אִיכָּא דְּאַמְרֵי, דְּלִישׁ בְּמִשְׁחָא, כְּתַרְגּוּמוֹ. וְאִיכָּא דְּאַמְרֵי, מַה הַשֵּׁד אִתְחֲזָר לְכַמָּה גַּוְונִין, אוּף מָנָא, אִתְחֲזָר לְכַמָּה גַּוְונִין. רִבִּי יְהוּדָה אָמַר, לְשַׁד הַשָּׁמֶן, יְנִיקָא דְּמִשְׁחָא.","רִבִּי יִצְחָק אָמַר, אִישׁ לְפִי אָכְלוֹ לָקָטוּ. וְכִי מַאן דְּאָכִיל קִמְעָא, לָקִיט קִמְעָא, וּמַאן דְּאָכִיל יַתִּיר, לָקִיט יַתִּיר, וְהָא כְּתִיב לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לא הֶחְסִיר. אֶלָּא לְפוּם אִינּוּן דְּאַכְלִין לַקְטִין. מַשְׁמַע אָכְלוֹ, מַאן דְּהֲוָה אָכִיל לֵיהּ, וּבְגִינֵי כָּךְ לָא כְּתִיב אֲכִילָתוֹ.","מַאי קָא מַיְירֵי. אָחִיד בַּר נָשׁ בְּעַבְדָּא, אוֹ בְּאָמָתָא, וְאָמַר דְּהוּא דִּילֵיהּ. אָתָא חַבְרֵיהּ, וְאָמַר, הַאי עַבְדָּא דִּילִי הוּא. קְרִיבוּ לְקַמֵיהּ דְּמֹשֶׁה לְדִינָא, אָמַר לוֹן כַּמָּה נַפְשָׁאָן בְּבֵיתֶךָ, וְכַמָּה נַפְשָׁאָן בְּבֵיתֵיהּ דְּדֵין, אָמַר כַּךְ וְכָךְ. וְהַהוּא שַׁעֲתָא אָמַר לוֹן מֹשֶׁה, לָקָטוּ מָחָר, וְכָל חַד מִנַּיְיכוּ יֵיתֵי לְגַבָּאי. לְמָחָר, נָפְקוּ וְלָקְטוּ, וְאַתְיָין קָמֵי מֹשֶׁה, שַׁוְויָין קָמֵיהּ מָנָא, הֲוָה מָדִיד לֵיהּ. אִי הַהוּא עַבְדָּא דְּדֵין, אַשְׁכַּח הַהוּא עוֹמְרָא דְּעַבְדָּא, בְּהַאי מָנָא. דְּהָא חַד עוֹמְרָא לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתֵיהּ. מָדִיד לְדֵין, וְאִשְׁתְּכַח חַסְרָא, הַהוּא מֵיכְלָא דְּעַבְדָּא, בְּהַהוּא מָנָא דִּילֵיהּ, וְחַד עוֹמְרָא לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתֵיהּ. אָמַר עַבְדָּא דְּדֵין הוּא, הֲדָא הוּא דִכְתִיב אִישׁ לְפִי אָכְלוֹ לָקָטוּ וּכְתִיב עֹמֶר לַגֻּלְגֹּלֶת מִסְפַּר נַפְשֹׁתֵיכֶם.","אָמַר ר' (נ\"א ייסא) חִיָּיא, כְּתִיב, (שמות ט״ז:ו׳-ז׳) עֶרֶב וִידַעְתֶּם כִּי יְיָ' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד יְיָ'. עֶרֶב וִידַעְתֶּם, בְּמַאי יִנְדְּעוּן. אֶלָּא הָכִי תָּאנָא, בְּכָל יוֹמָא וְיוֹמָא אִשְׁתְּכָחוּ נִימוּסֵי קוּדְשָׁא בְּרִיךְ הוּא. בְּצַפְרָא, אִתְּעַר חֶסֶד בְּעָלְמָא. בְּהַהוּא זִמְנָא דְּאִקְרֵי עֶרֶב, תַּלְיָא דִּינָא בְּעָלְמָא, וְהָא אוּקְמוּהָ, דִּבְגִינֵי כַּךְ, יִצְחָק תִּקֵּן תְּפִלַּת הַמִּנְחָה. (מאי קא מיירי) וְעַל דָּא, עֶרֶב וִידַעְתֶּם, כַּד אִתְּעַר דִּינָא בְּעָלְמָא, תִּנְדְּעוּן, דִּבְהַהוּא דִּינָא אַפִּיק יְיָ' יַתְכוֹן מִמִּצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד יְיָ' דְּהָא בְּהַהוּא זִמְנָא אִתְּעַר חֶסֶד בְּעָלְמָא וְיִתֵּן לְכוּ לְמֵיכַל.","ר' חִיָּיא אָמַר אִיפְּכָא, מַה כְּתִיב לְעֵילָּא, בְּשִׁבְתֵּנוּ עַל סִיר הַבָּשָׂר וְגוֹ'. בֵּיהּ שַׁעֲתָא, אִתְּעַר עֶרֶב, דְּהַהוּא זִמְנָא דְּאִתְּעַר דִּינָא, אִתְּעַר נָמֵי חֶסֶד בְּעָלְמָא. הֲדָא הוּא דִכְתִיב, וִידַעְתֶּם כִּי יְיָ' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרָיִם. תִּנְדְּעוּן הַהוּא חֶסֶד דְּעָבַד עִמְּכוֹן, בְּזִמְנָא דְּדִינָא וְאַפִּיק יַתְכוֹן מֵאַרְעָא דְּמִצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד יְיָ', כְּבוֹד יְיָ' הָא יְדִיעַ. וְכָּל כַּךְ לָמָּה. בִּשְׁמוֹעַ יְיָ' אֶת תְּלֻנּוֹתֵיכֶם וְגוֹ'.","אָמַר ר' יֵיסָא, לָא שָׁנֵי קוּדְשָׁא בְּרִיךְ הוּא נִימוּסוֹי, בַּר דְּאִינּוּן חַיָּיבֵי עָלְמָא שַׁנְיָין לוֹן, וּמְהַפְּכֵי רַחֲמֵי לְדִינָא, כְּמָה דְּאִתְּמַר.","תָּאנֵי ר' אֶלְעָזָר, מֵהַאי מָנָא זְמִינִין צַדִּיקַיָּיא לְמֵיכַל לְעָלְמָא דְּאָתֵי, וְאִי תֵּימָא בְּהַאי גַּוְונָא. לָא. אֶלָּא יַתִּיר, דְּלָא הֲוָה כֵּן לְעָלְמִין. מַאי אִיהוּ. כְּמָה דְּאוֹקִימְנָא דִּכְתִּיב, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ' וּלְבַקֵּר בְּהֵיכָלוֹ. וּכְתִיב (ישעיהו ס״ד:ג׳) עַיִן לא רָאָתָה אֱלהִים זוּלָתְךָ וְגוֹ'.","(שמות ט״ז:כ״ט) רְאוּ כִּי יְיָ' נָתַן לָכֶם הַשַּׁבָּת. ר' חִזְקִיָּה פָּתַח (תהילים ק״ל:א׳) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'. שִׁיר הַמַּעֲלוֹת סָתַם, וְלָא פָּרִישׁ מַאן אָמָרוּ. אֶלָּא שִׁיר הַמַּעֲלוֹת, דִּזְמִינִין כָּל בְּנֵי עָלְמָא לְמֵימַר, דְּזַמִּין הַאי שִׁיר לְמֵימְרֵיהּ לְדָרֵי עָלְמָא."],[[0,"כגוונא דא וכו':","כעין זה אלו שאינם מאמינים בהקב\"ה, אינם רוצים להסתכל בדרכיו, והם רוצים להטריח עצמם כל יום אחר מזון, ימים ולילות, מפחד, אולי לא יעלה בידם פת לחם. מי גרם להם זה, משום שאינם בני אמונה."],[1,"אוף הכא שטו וכו':","אף כאן שטו העם ולקטו, שטו בשטות של עצמם, ורצו להטריח עליו, ז\"ש, וטחנו ברחים. ואחר כל טרחה הזאת לא עלה בידם, אלא כמו שכתוב, והיה טעמו כטעם לשד השמן. ולא יותר. מי גרם להם זה, משום שלא היו בני אמונה."],[2,"אמר ר' יוסי וכו':","מהו לשד השמן. יש אומרים שנלוש בשמן. כתרגומו. ויש אומרים. מה השד משתנה לכמה אפנים, אף המן משתנה לכמה טעמים. דהיינו כל טעם שהיו רוצים היו טועמים בו. ר' יהודה אמר, לשד השמן פירושו יניקה של שמן."],[3,"ר' יצחק אמר וכו':","רי\"א, איש לפי אכלו לקטו. שואל, וכי מי שאוכל מעט לקט מעט ומי יותר לקט יותר, והרי כתוב, לא העדיף המרבה והממעיט לא החסיר. ומשיב, אלא לפי האוכלים לקטו. זה משמע משכתוב, אכלו, דהיינו מי שאוכל אותו, ומשום זה לא כתוב, איש לפי אכילתו."],[4,"מאי קא מיירי וכו':","שואל, מה מלמדנו זה, שכל אחד לקט לפי האוכלים. ומשיב, אם אחז בעבד או באמה, ואומר ששלו הוא, וחברו בא ואמר שלי הוא, קרבו לפני משה לדין, אמר להם, כמה נפשות בביתך וכמה נפשות בביתו של זה. אמר כך וכך. ואותה שעה, אמר להם משה, לקטו מחר, וכל אחד יבא אצלי. למחר יצאו ולקטו ובאו לפני משה, שמו לפניו כלי והיה מודד אותו, אם עבד ההוא של זה, נמצא העומר של העבד באותו כלי, כי היה עומר אחד לכל נפש ונפש מביתו. מדד לזה ונמצא חסר האוכל של העבד בכלי שלו, והיה עומר אחד לכל נפש ונפש מביתו אז אמר העבד הוא של זה. ז\"ש, איש לפי אכלו לקטו. וכתוב, עמר לגלגלת מספר נפשותיכם."],[5,"אמר ר' ייסא וכו':","אר\"י, כתוב, ערב וידעתם כי ה' הוציא אתכם מארץ מצרים ובקר וראיתם את כבוד ה'. שואל, ערב וידעתם, במה ידעו ומשיב, אלא כך למדנו. בכל יום ויום נמצאו, מנהגי הקב\"ה, בבוקר נעור החסד בעולם, ובזמן ההוא שנקרא ערב, תלוי הדין בעולם, וכן העמדנוהו, שיצחק תיקן תפלת המנחה. ויצחק הוא גבורה. ועל כן ערב וידעתם, כשיתעורר הדין בעולם, תדעו, שבדין הזה הוציא ה' אתכם ממצרים. ובוקר וראיתם את כבוד ה', כי בזמן ההוא החסד נעור בעולם, ויתן לכם לאכול."],[6,"ר' חייא אמר וכו':","רח\"א להיפך. מה כתוב למעלה בשבתנו על סיר הבשר וגו'. בו בשעה נתעורר הערב, דהיינו הדין. ובזמן ההוא שנתעורר הדין נתעורר גם החסד בעולם, ז\"ש, וידעתם כי ה' הוציא אתכם מארץ מצרים תדעו את החסד ההוא שעשה עמכם בזמן הדין, והוציא אתכם מארץ מצרים. ובוקר וראיתם את כבוד ה'. כבוד ה' הרי ידוע, שהיא המלכות. וכל כך למה. בשמוע ה' את תלונותיכם."],[7,"אמר ר' ייסא לא וכו':","אר\"י לא שינה הקב\"ה מנהגיו, שיאיר החסד בערב, כמו שאמר ר' חייא, חוץ, שאלו רשעי עולם משנים אותו, ומהפכים הרחמים לדין. כמו שלמדנו."],[8,"תאני ר' אלעזר וכו':","תאני ר' אלעזר, ממן ההוא, עתידים הצדיקים לאכול לעולם הבא. ואם תאמר, באפן ההוא שאכלו ישראל במדבר. לא כן, אלא יותר מהם, שלא היה בשלמות ההוא לעולם, מה הוא. הוא כמו שהעמדנו, לחזות בנועם ה' ולבקר בהיכלו. וכתוב, עין לא ראתה אלקים זולתך."],[9,"ראו כי ה' נתן לכם השבת:","ר' חזקיה פתח, שיר המעלות ממעמקים קראתיך ה'. שואל, שיר המעלות סתם, ואינו מפרש מי אמרו. ואומר. אלא שיר המעלות, פירושו, שעתידים כל בני העולם לומר זה, כי שיר הזה עתיד לאמרו לדורות עולם."]],[[0,"","כְּמוֹ זֶה אוֹתָם שֶׁלֹּא מַאֲמִינִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, לֹא רוֹצִים לְהִסְתַּכֵּל בִּדְרָכָיו, וְהֵם רוֹצִים לְהַטְרִיחַ אֶת עַצְמָם כָּל יוֹם אַחַר מָזוֹן יוֹם וָלַיְלָה, אוּלַי לֹא יַעֲלֶה בְיָדָם פַּת לֶחֶם. מִי גָרַם לָהֶם אֶת זֶה? מִשּׁוּם שֶׁאֵינָם בְּנֵי אֱמוּנָה."],[1,"","אַף כָּאן, שָׁטוּ וְלָקְטוּ - שָׁטוּ בַּשְּׁטוּת שֶׁל עַצְמָם, וְרוֹצִים לְהַטְרִיחַ עָלָיו. זֶהוּ שֶׁכָּתוּב וְטָחֲנוּ בָרֵחַיִם. אַחַר כָּל הַטִּרְחָה הַזּוֹ לֹא עָלָה בִידֵיהֶם, אֶלָּא שֶׁכָּתוּב וְהָיָה טַעְמוֹ כְּטַעַם לְשַׁד הַשָּׁמֶן, וְלֹא יוֹתֵר. מִי גָרַם לָהֶם אֶת זֶה? מִשּׁוּם שֶׁלֹּא הָיוּ בְּנֵי אֱמוּנָה."],[2,"","אָמַר רַבִּי יוֹסֵי, מַה זֶּה לְשַׁד הַשָּׁמֶן? יֵשׁ אוֹמְרִים, שֶׁהָיָה נִלּוֹשׁ בְּשֶׁמֶן כְּתַרְגּוּמוֹ. וְיֵשׁ אוֹמְרִים, מָה הַשָּׁד מִתְהַפֵּךְ לְכַמָּה גְוָנִים, אַף הַמָּן מִתְהַפֵּךְ לְכַמָּה גְוָנִים. רַבִּי יְהוּדָה אָמַר, לְשַׁד הַשָּׁמֶן - יְנִיקַת הַשֶּׁמֶן."],[3,"","רַבִּי יִצְחָק אָמַר, אִישׁ לְפִי אָכְלוֹ לָקָטוּ - וְכִי מִי שֶׁאוֹכֵל מְעַט לוֹקֵט מְעַט, וּמִי שֶׁאוֹכֵל יוֹתֵר לוֹקֵט יוֹתֵר? וַהֲרֵי כָּתוּב לֹא הֶעְדִּיף הַמַּרְבֶּה וְהַמַּמְעִיט לֹא הֶחְסִיר? אֶלָּא לְפִי אוֹתָם שֶׁאוֹכְלִים, לוֹקְטִים. מַשְׁמָע אָכְלוֹ - מִי שֶׁהָיָה אוֹכֵל אוֹתוֹ. וּמִשּׁוּם כָּךְ לֹא כָתוּב אֲכִילָתוֹ."],[4,"","מַה זֶּה אוֹמֵר? אָחַז אָדָם בְּעֶבֶד אוֹ בְּאָמָה וְאָמַר שֶׁהוּא שֶׁלּוֹ. בָּא חֲבֵרוֹ וְאָמַר: עֶבֶד זֶה הוּא שֶׁלִּי! קָרְבוּ לִפְנֵי מֹשֶׁה לְדִין. אָמַר לָהֶם: כַּמָּה נְפָשׁוֹת בְּבֵיתְךְ, וְכַמָּה נְפָשׁוֹת בְּבֵיתוֹ שֶׁל זֶה? אָמַר כָּךְ וְכָךְ. וְאוֹתָהּ שָׁעָה אָמַר לָהֶם מֹשֶׁה: לִקְטוּ מָחָר, וְכָל אֶחָד יָבֹא אֵלַי. לְמָחָר יָצְאוּ וְלָקְטוּ, וּבָאוּ לִפְנֵי מֹשֶׁה. שָׂמוּ לְפָנָיו אֶת הַמָּן, וְהָיָה מוֹדֵד אוֹתוֹ. אִם אוֹתוֹ עֶבֶד שֶׁל זֶה - מָצָא אֶת אוֹתוֹ הָעֹמֶר שֶׁל הָעֶבֶד בַּמָּן הַזֶּה, שֶׁהֲרֵי עֹמֶר אֶחָד לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתוֹ. מָדַד לָזֶה - וְנִמְצָא חָסֵר אוֹתוֹ מַאֲכַל הָעֶבֶד בַּמָּן שֶׁלּוֹ, וְעֹמֶר אֶחָד לְכָל נֶפֶשׁ וְנֶפֶשׁ מִבֵּיתוֹ. אָמַר וּפָסַק: הָעֶבֶד שֶׁל זֶה הוּא! זֶהוּ שֶׁכָּתוּב אִישׁ לְפִי אָכְלוֹ לָקָטוּ. וְכָתוּב עֹמֶר לַגֻּלְגֹּלֶת מִסְפַּר נַפְשֹׁתֵיכֶם."],[5,"","אָמַר רַבִּי (ייסא) חִיָּיא, כָּתוּב עֶרֶב וִידַעְתֶּם כִּי ה' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרָיִם וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד ה'. עֶרֶב וִידַעְתֶּם, בַּמֶּה יֵדְעוּ? אֶלָּא כָּךְ שָׁנִינוּ, בְּכָל יוֹם וָיוֹם נִמְצְאוּ הַנְהָגוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא - בַּבֹּקֶר הִתְעוֹרֵר חֶסֶד בָּעוֹלָם. בְּאוֹתוֹ זְמַן שֶׁנִּקְרָא עֶרֶב, תָּלוּי הַדִּין בָּעוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ שֶׁלָּכֵן יִצְחָק תִּקֵּן תְּפִלַּת הַמִּנְחָה. (מה זה אומר) וְעַל זֶה עֶרֶב וִידַעְתֶּם. כְּשֶׁמִּתְעוֹרֵר דִּין בָּעוֹלָם, תֵּדְעוּ שֶׁבְּאוֹתוֹ דִין הוֹצִיא אֶתְכֶם ה' מִמִּצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד ה', שֶׁהֲרֵי בְּאוֹתוֹ זְמַן מִתְעוֹרֵר חֶסֶד וְיִתֵּן לָכֶם לֶאֱכֹל."],[6,"","רַבִּי חִיָּיא אָמַר הַהֵפֶךְ. מַה כָּתוּב לְמַעְלָה? בְּשִׁבְתֵּנוּ עַל סִיר הַבָּשָׂר וְגוֹ'. בְּאוֹתָהּ שָׁעָה הִתְעוֹרֵר עֶרֶב. שֶׁאוֹתוֹ זְמַן שֶׁמִּתְעוֹרֵר דִּין, מִתְעוֹרֵר גַּם חֶסֶד בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב וִידַעְתֶּם כִּי ה' הוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם. תֵּדְעוּ אוֹתוֹ חֶסֶד שֶׁעָשָׂה עִמָּכֶם בִּזְמַן הַדִּין וְהוֹצִיא אֶתְכֶם מֵאֶרֶץ מִצְרַיִם. וּבֹקֶר וּרְאִיתֶם אֶת כְּבוֹד ה', כְּבוֹד ה' הֲרֵי יָדוּעַ, וְכָל כָּךְ לָמָּה? בִּשְׁמֹעַ ה' אֶת תְּלֻנֹּתֵיכֶם וְגוֹ'."],[7,"","אָמַר רַבִּי יֵיסָא, לֹא מְשַׁנֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְהָגוֹתָיו, רַק שֶׁאוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם מְשַׁנִּים אוֹתָם וּמְהַפְּכִים רַחֲמִים לְדִין, כְּמוֹ שֶׁנִּתְבָּאֵר."],[8,"","שָׁנָה רַבִּי אֶלְעָזָר, מֵהַמָּן הַזֶּה עֲתִידִים הַצַּדִּיקִים לֶאֱכֹל לָעוֹלָם הַבָּא. וְאִם תֹּאמַר כְּמוֹ זֶה? לֹא! אֶלָּא יוֹתֵר. שֶׁלֹּא הָיָה כָּךְ לְעוֹלָמִים. מַהוּ? כְּמוֹ שֶׁבֵּאַרְנוּ שֶׁכָּתוּב (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ, וְכָתוּב (ישעיה סב) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'."],[9,"","רְאוּ כִּי ה' נָתַן לָכֶם הַשַּׁבָּת. רַבִּי חִזְקִיָּה פָּתַח, (תהלים קל) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךְ ה'. שִׁיר הַמַּעֲלוֹת, סָתַם וְלֹא פֵרַשׁ מִי אֲמָרוֹ. אֶלָּא שִׁיר הַמַּעֲלוֹת שֶׁעֲתִידִים לוֹמַר כָּל בְּנֵי הָעוֹלָם, שֶׁעָתִיד הַשִּׁיר הַזֶּה לְהֵאָמֵר אוֹתוֹ לְדוֹרוֹת עוֹלָם."]]],[["וּמַאי הוּא מִמַּעֲמַקִּים קְרָאתִיךָ. הָכִי תָּאנָא, כָּל מַאן דִּמְצַלֵי צְלוֹתָא קָמֵי מַלְכָּא קַדִּישָׁא, בָּעֵי לְמִבָּעֵי בָּעוּתֵיהּ, וּלְצַלָּאָה (ויקרא ע\"א) מֵעִמְקָא דְּלִבָּא, בְּגִין דְּיִשְׁתְּכַח לִבֵּיהּ שְׁלִים בְּקוּדְשָׁא בְּרִיךְ הוּא, וִיכַוֵּין לִבָּא וּרְעוּתָא. וּמִי אָמַר דָּוִד הָכִי, וְהָא כְּתִיב, (תהילים קי״ט:י׳) בְּכָל לִבִּי דְּרַשְׁתִּיךָ. וְדָא קְרָא סַגִּי, מַאי בָּעֵי מִמַּעֲמַקִּים.","אֶלָּא הָכִי תָּאנָא, כָּל בַּר נָשׁ דְּבָעֵי בָּעוּתֵיהּ קָמֵי מַלְכָּא, בָּעֵי לְכַוְּונָא דַּעְתָּא (נ\"א לבא) וּרְעוּתָא, מֵעִיקָּרָא דְּכָל עִקָרִין, לְאַמְשָׁכָא בִּרְכָּאן מֵעִמְקָא דְּבֵירָא, (נ\"א דכלא) בְּגִין דְּיַנְגִּיד בִּרְכָּאן מִמַּבּוּעָא דְּכֹלָּא. וּמַאי הוּא. הַהוּא אֲתָר דְּנָפִיק מִנֵּיהּ, וְאִשְׁתְּכַח מִנֵּיהּ, הַהוּא נָהָר, דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. וּכְתִיב (תהילים מ״ו:ה׳) נָהָר פְּלָגָיו יְשַׂמְחוּ עִיר אֱלהִים. וְדָא אִקְרֵי מִמַּעֲמַקִּים. (מ\"ט ע\"א) עִמְקָא דְּכֹלָּא, עִמְקָא דְּבֵירָא, דְּמַבּוּעִין נָפְקִין וְנַגְדִּין לְבָרְכָא כֹּלָּא. וְדָא הוּא שֵׁרוּתָא לְאַמְשָׁכָא בִּרְכָּאן מֵעֵילָּא לְתַתָּא.","אָמַר רִבִּי חִזְקִיָּה, (בראשית רל\"ד ע\"א, ויקרא רפ\"ה א' ב', רצ\"ז ע\"ב) כַּד עַתִּיקָא סְתִימָאָה דְּכָל סְתִימִין, בָּעֵי לְזַמְנָא בִּרְכָּאן לְעָלְמִין, אַשְׁרֵי כֹּלָּא, וְאַכְלִיל כֹּלָּא, בְּהַאי עֲמִיקָא עִלָּאָה, וּמֵהָכָא שָׁאִיב וְאִתְנְגִיד בֵּירָא (נ\"א נהרא) דְּנַחֲלִין וּמַבּוּעִין אִתְנְגִידוּ מִנֵּיהּ, וּמִתְשַׁקְיָין מִנֵּיהּ כֻּלְּהוּ. וּמַאן דִּמְצַלֵי צְלוֹתֵיהּ, בָּעֵי לְכַוְּונָא לִבָּא וּרְעוּתָא, לְאַמְשָׁכָא בִּרְכָּאן מֵהַהוּא עֲמִיקָא דְּכֹלָּא, בְּגִין דְּיִתְקַבַּל צְלוֹתֵיהּ, וְיִתְעֲבִיד רְעוּתֵיהּ.","וַיֹּאמֶר מֹשֶׁה אֲלֵיהֶם אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בֹּקֶר. אָמַר רִבִּי יְהוּדָה, בְּכָל יוֹמָא וְיוֹמָא, מִתְבָּרֵךְ עָלְמָא מֵהַהוּא יוֹמָא עִלָּאָה, דְּהָא כָּל שִׁיתָא יוֹמִין מִתְבָּרְכָאן מִיּוֹמָא שְׁבִיעָאָה. וְכָל יוֹמָא יָהִיב מֵהַהוּא בְּרָכָה דְּקַבִּיל בְּהַהוּא יוֹמָא דִּילֵיהּ.","וְעַל דָּא מֹשֶׁה אָמַר, אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בֹּקֶר. מַאי טַעְמָא. בְּגִין דְּלָא יָהִיב, וְלָא יוֹזִיף יוֹמָא דָּא לְחַבְרֵיהּ, אֶלָּא כָּל חַד וְחַד שָׁלִיט בִּלְחוֹדוֹי, בְּהַהוּא יוֹמָא דִּילֵיהּ. דְּהָא לָא שָׁלִיט יוֹמָא בְּיוֹמָא דְּחַבְרֵיהּ.","בְּגִינֵי כַּךְ, כָּל אִינּוּן (נ\"א אמר רבי יהודה כל יומא ויומא מתברך מההוא יומא עילאה יומא שביעאה ומתברכן כל שיתא יומין כל חד וחד בלחודוי וכל יומא יהיב ביומא דיליה מההוא ברכה דקביל מההוא יומא עילאה ועל דא משה אמר איש אל יותר ממנו עד בקר דהא לא שליט יומא ביומא דלאו דיליה וכל אינון) חֲמִשָּׁא יוֹמִין שַׁלִּיטִין בְּיוֹמַיְיהוּ, וְאִשְׁתְּכַח בֵּיהּ, מַה דְּקַבִּילוּ, וְיוֹמָא שְׁתִיתָאָה אִשְׁתְּכַח בֵּיהּ יַתִּיר. וְאַזְלָא הָא, כְּהָא דְּאָמַר רִבִּי אֶלְעָזָר, מַאי דִּכְתִּיב יוֹם הַשִּׁשִּׁי, וְלָא אִתְּמַר הָכִי בְּכָל שְׁאַר יוֹמִין. אֶלָּא הָכִי אוּקְמוּהָ, הַשִּׁשִּׁי. דְּאִזְדַּוְּוגָא (דאזדמנא) בֵּיהּ מַטְרוֹנִיתָא. לְאַתְקְנָא פָּתוֹרָא לְמַלְכָּא, וּבְּגִין כָּךְ, אִשְׁתְּכָחוּ בֵּיהּ תְּרֵין חוּלָקִין, חַד לְיוֹמֵיהּ, וְחַד לְתִקּוּנָא, בְּחֶדְוָותָא דְּמַלְכָּא בְּמַטְרוֹנִיתָא.","וְהַהוּא לֵילְיָא, חֶדְוָותָא דְּמַטְרוֹנִיתָא בְּמַלְכָּא, וְזִוּוּגָא דִּלְהוֹן, וּמִתְבָּרְכָאן כָּל שִׁיתָא יוֹמִין, כָּל חַד וְחַד בִּלְחוֹדוֹי. בְּגִין כַּךְ, בָּעֵי בַּר נָשׁ לְסַדְּרָא פָּתוֹרֵיהּ בְּלֵילְיָא דְּשַׁבְּתָא, בְּגִין דְּשָׁארִי עָלֵיהּ בִּרְכָּאן מִלְּעֵילָּא, וּבִרְכָּתָא לָא אִשְׁתְּכַח עַל פָּתוֹרָא רֵיקַנְיָא, (וההוא ליליא חדותא דמטרוניתא במלכא וזווגא דלהון) בְּגִין כָּךְ, תַּלְמִידֵי חֲכָמִים דְּיַדְעִין רָזָא דָּא, זִוּוּגָא דִּלְהוֹן מְעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת.","רְאוּ כִּי יְיָ' נָתַן לָכֶם הַשַּׁבָּת, מַאי שַׁבָּת. יוֹמָא דְּבֵיהּ נַיְיחִין שְׁאַר יוֹמִין, וְהוּא כְּלָלָא דְּכָל אִינּוּן שִׁיתָא אַחֲרָנִין, וּמִנֵּיהּ מִתְבָּרְכִין. רִבִּי יֵיסָא אָמַר, וְכֵן נָמֵי כְּנֶסֶת יִשְׂרָאֵל אִקְרֵי שַׁבָּת, בְּגִין דְּאִיהִי בַּת זוּגוֹ, וְדָא הִיא כַּלָּה. דִּכְתִּיב (שמות ל״א:י״ד) וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם. לָכֶם וְלָא לִשְׁאַר עַמִּין, הֲדָא הוּא דִכְתִיב, (שמות ל״א:י״ד) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וְדָא הִיא אַחֲסָנַת יְרוּתַת עָלְמִין לְיִשְׂרָאֵל. וְעַל דָּא, כְּתִיב (ישעיהו נ״ח:י״ג) אִם תָּשִׁיב מִשַּׁבָּת רַגְלְךָ וְגוֹ' וּבְאַתְרִיהּ אוֹקִימְנָא מִלֵּי.","כְּתִיב אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ בַּיּוֹם הַשְּׁבִיעִי. מִמְּקוֹמוֹ. תָּנֵינָן, מֵהַהוּא מָקוֹם דְּאִתְחָזֵי לְמֵהַךְ. וְרָזָא דְּמִלָּה דִּכְתִּיב, (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ' מִמְּקוֹמוֹ, וְדָא אִיהוּ מָקוֹם. וְדָא אִיהוּ רָזָא דִּכְתִּיב, (שמות ג׳:ה׳) כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. אֲתָר יְדִיעָא קָרֵינָן לֵיהּ מָקוֹם דְּאִשְׁתְּמוֹדְעָא יְקָרָא עִלָּאָה.","וּבְגִין כַּךְ, אַזְהָרוּתָא לְבַר נָשׁ, דְּקָא מִתְעַטְּרָא בְּעִטּוּרָא קַדִּישָׁא דִּלְעֵילָּא, דְּלָא יִפּוּק מִנֵּיהּ בְּפוּמֵיהּ מִלּוּלָא (ע\"א ע\"ב) דְּחוֹל, בְּגִין דְּאִי יִפּוּק מִנֵּיהּ, קָא מְחַלֵּל יוֹמָא דְּשַׁבְּתָא, בִּידוֹי בְּעוֹבַדְתָּא. בְּרַגְלוֹי, לְמֵהַךְ לְבַר מִתְּרֵין אַלְפִין אַמִּין. כָּל אִלֵּין חִלּוּלָא דְּשַׁבְּתָא אִינּוּן."],[[0,"ומאי הוא ממעמקים וכו':","שואל, ומה פירושו של ממעמקים קראתיך. ומשיב. כך למדנו. כל מי שמתפלל תפלתו לפני המלך הקדוש, צריך לבקש בקשותיו ולהתפלל מעומק הלב, כדי שימצא לבו שלם בהקב\"ה ויכוין לבו ורצונו. וז\"ש ממעמקים קראתיך. שואל, וכי אמר דוד כך, והרי כתוב, בכל לבי דרשתיך. ומקרא זה די, להתפלל בכל לב, ולמה צריך ממעמקים."],[1,"אלא הכי תאנא וכו':","ומשיב. אלא כך למדנו, כל אדם שמבקש בקשתו לפני המלך, צריך שיכוון דעתו ורצונו לשורש השרשים, להמשיך ברכות מעומק הבור, כדי שיזלו ברכות ממעין של כל. ומה הוא, הוא מקום ההוא שיוצא ממנו ונמצא ממנו אותו הנהר, שהוא חכמה סתימאה, שכתוב ונהר יוצא מעדן. שעדן הוא חכמה, ונהר היא בינה, והיינו בינה שיצאה לחוץ מראש א\"א, שהוא חכמה סתימאה. (עי' לעיל בהקס\"ה דף ז' ד\"ה ותמן) וכתוב, נהר פלגיו ישמחו עיר האלקים וזהו נקרא ממעמקים. עומק כל, עומק הבור שמעיינות יוצאים ונמשכים ממנו לברך כל. וזה הוא ההתחלה להמשיך ברכות מלמעלה למטה."],[2,"אמר ר' חזקיה וכו':","ר\"ח מפרש דבריו, ואמר, כשעתיקא סתימאה מכל סתומים רוצה לזמן ברכות לעולם, השרה הכל והכליל הכל בעומק העליון ההוא, שהוא חכמה סתימאה דא\"א מבחינת מה שהבינה יוצאת ממנו לחוץ, ומכאן שואב ונמשך נהר, שהוא בינה, שנחלים ומעינות יוצאים ממנו, שהם המוחין, ונשקים הכל ממנו, שכל המוחין של זו\"ן ובי\"ע נמשכים משם. ומי שמתפלל תפלתו, צריך לכוון לבו ורצונו להמשיך ברכות מעומק של הכל הזה, כדי שתתקבל תפלתו ויעשה רצונו."],[3,"ויאמר משה אליהם וגו':","א\"ר יהודה בכל יום ויום מתברך העולם מיום ההוא העליון, כי כל ששה ימים מתברכים מיום השביעי, וכל יום נותן מברכה ההיא שקבל ביום ההוא שלו."],[4,"ועל דא משה אמר וכו':","וע\"כ אמר משה, איש אל יותר ממנו עד בוקר. מהו הטעם. משום שאינו נותן ואינו שואל יום זה לחבירו, אלא כל אחד ואחד שולט בלבדו ביום ההוא שלו, כי יום אינו שולט ביום של חבירו."],[5,"בגיני כך כל וכו':","משום זה, כל אלו חמשה הימים שולטים ביומם, ונמצא בהם מה שקבלו, ויום הששי נמצא בו יותר. וזה הולך, כמו שאמר ר' אלעזר. מה שכתוב, יום הששי עם \u0003ה'\u0004 מה שלא כתוב כן בשאר הימים. אלא כך העמידוהו, הששי עם ה', יורה, שנתחברה בו המטרוניתא, הנקראת ה' שהיא מלכות, לתקן שלחן אל המלך, ומשום זה יש בו ב' חלקים, א' מיומו עצמו, ואחד, מתקון שמחת המלך במטרוניתא."],[6,"וההוא ליליא חדוותא וכו':","ולילה ההוא, שמחת המטרוניתא במלך וזווג שלהם, ומתברכים כל ששה ימים כל אחד ואחד בלבדו. משום זה, צריך האדם לסדר שלחנו בליל שבת, משום ששורה עליו ברכות מלמעלה, וברכה אינה נמצאת על שלחן ריקן. משום זה, תלמידי חכמים שיודעים סוד הזה, זווגם הוא מערב שבת לערב שבת."],[7,"ראו כי ה' נתן לכם השבת:","שואל מהו שבת. ואומר, הוא יום שבו נחים שאר הימים, והוא כלל של כל אלו ששה ימים האחרים, וממנו הם מתברכים. ר' ייסא אמר, וכן גם כנסת ישראל, נקראת שבת, שהיא בת זוגו של שבת. וזו היא כלה. שכתוב, ושמרתם את השבת כי קדוש היא לכם. לכם ולא לשאר העמים. ז\"ש, ביני ובין בני ישראל. וזה הוא נחלת ירושת עולמים לישראל. וע\"כ כתוב, אם תשיב משבת רגלך וגו'. ובמקומו העמדנו הדברים."],[8,"אל יצא איש ממקומו וגו':","למדנו, שפירושו, ממקום ההוא שראוי ללכת, דהיינו מחוץ לכל העיר. וסוד הדבר. שכתוב, ברוך כבוד ה' ממקומו. שהוא המלכות. וזה הוא מקום. וזה הוא סוד שכתוב, כי המקום אשר אתה עומד עליו אדמת קדש היא. הוא מקום ידוע שקוראים לו מקום, שנודע בכבוד העליון. דהיינו מלכות."],[9,"ובגין כך אזהרותא וכו':","ומשום זה, אזהרה הוא לאדם, המתעטר בעטור הקדוש שלמעלה, ביום השבת, שלא יצא מפיו דבור של חול, משום שאם יצא ממנו, דבור של חול, הוא מחלל יום השבת. חילול שבת בידיו, הוא בעשית מלאכה. ברגליו, הוא ללכת חוץ מאלפים אמה. כל אלו הם חלול שבת."]],[[0,"","וּמַהוּ מִמַּעֲמַקִּים קְרָאתִיךְ? כָּךְ שָׁנִינוּ, כָּל מִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, צָרִיךְ לְבַקֵּשׁ בַּקָּשָׁתוֹ וּלְהִתְפַּלֵּל מֵעֹמֶק הַלֵּב כְּדֵי שֶׁיִּמָּצֵא לִבּוֹ שָׁלֵם עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וִיכַוֵּן לֵב וְרָצוֹן. וְהַאִם דָּוִד אָמַר כָּךְ, וַהֲרֵי כָּתוּב בְּכָל לִבִּי דְּרַשְׁתִּיךְ, וּפָסוּק זֶה מַסְפִּיק? מַה צָּרִיךְ מִמַּעֲמַקִּים?"],[1,"","אֶלָּא כָּךְ שָׁנִינוּ, כָּל אָדָם שֶׁמְּבַקֵּשׁ בַּקָּשָׁתוֹ לִפְנֵי הַמֶּלֶךְ, צָרִיךְ לְכַוֵּן דַּעְתּוֹ (לבו) וּרְצוֹנוֹ מֵעִקָּר שֶׁל כָּל הָעִקָּרִים לִמְשֹׁךְ בְּרָכוֹת מֵעֹמֶק הַבְּאֵר (של הכל), כְּדֵי שֶׁיַּשְׁפִּיעַ בְּרָכוֹת מֵהַמַּעְיָן שֶׁל הַכֹּל, וּמַהוּ? אוֹתוֹ מָקוֹם שֶׁיּוֹצֵא מִמֶּנּוּ וְנִמְצָא מִמֶּנּוּ אוֹתוֹ נָהָר, שֶׁכָּתוּב (בראשיתב) וְנָהָר יֹצֵא מֵעֵדֶן, וְכָתוּב (תהלים מו) נָהָר פְּלָגָיו יְשַׂמְּחוּ עִיר אֱלֹהִים. וְזֶה נִקְרָא מִמַּעֲמַקִּים. עֹמֶק הַכֹּל, עֹמֶק הַבְּאֵר שֶׁמַּעְיָנוֹת יוֹצְאִים וְשׁוֹפְעִים לְבָרֵךְ אֶת הַכֹּל, וְזוֹהִי הָרֵאשִׁית לִמְשֹׁךְ בְּרָכוֹת מִמַּעְלָה לְמַטָּה."],[2,"","אָמַר רַבִּי חִזְקִיָּה, כְּשֶׁהָעַתִּיק, נִסְתָּר שֶׁל הַנִּסְתָּרִים, רוֹצֶה לְזַמֵּן בְּרָכוֹת לָעוֹלָמוֹת, מַשְׁרֶה אֶת הַכֹּל, וּמַכְלִיל אֶת הַכֹּל בָּעֹמֶק הָעֶלְיוֹן הַזֶּה, וּמִכָּאן שׁוֹאֵב וְנִשְׁפָּע בְּאֵר (נהר) שֶׁנְּחָלִים וּמַעְיָנוֹת נִשְׁפָּעִים מִמֶּנּוּ, וְכֻלָּם נִשְׁקִים מִמֶּנּוּ. וּמִי שֶׁמִּתְפַּלֵּל תְּפִלָּתוֹ, צָרִיךְ לְכַוֵּן לִבּוֹ וּרְצוֹנוֹ לִמְשֹׁךְ בְּרָכוֹת מֵאוֹתוֹ עֹמֶק שֶׁל הַכֹּל כְּדֵי שֶׁתִּתְקַבֵּל תְּפִלָּתוֹ וְיַעֲשֶׂה רְצוֹנוֹ."],[3,"","וַיֹּאמֶר מֹשֶׁה אֲלֵהֶם אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בּקֶר. אָמַר רַבִּי יְהוּדָה, בְּכָל יוֹם וָיוֹם מִתְבָּרֵךְ הָעוֹלָם מֵאוֹתוֹ יוֹם הָעֶלְיוֹן, שֶׁהֲרֵי כָּל שֵׁשֶׁת הַיָּמִים מִתְבָּרְכִים מִיּוֹם הַשְּׁבִיעִי, וְכָל יוֹם נוֹתֵן מֵאוֹתָהּ בְּרָכָה שֶׁקִּבֵּל מֵאוֹתוֹ יוֹם שֶׁלּוֹ."],[4,"","וְעַל זֶה אָמַר מֹשֶׁה, אִישׁ אַל יוֹתֵר מִמֶּנּוּ עַד בֹּקֶר. מָה הַטַּעַם? כְּדֵי שֶׁלֹּא יִתֵּן וְלֹא יַלְוֶה יוֹם זֶה לַחֲבֵרוֹ, אֶלָּא כָּל אֶחָד וְאֶחָד שׁוֹלֵט לְבַדּוֹ בְּאוֹתוֹ יוֹם שֶׁלּוֹ, שֶׁהֲרֵי לֹא שׁוֹלֵט יוֹם בַּיּוֹם שֶׁל חֲבֵרוֹ."],[5,"","מִשּׁוּם כָּךְ כָּל אוֹתָם (אמר רבי יהודה, כליוםויוםמתברך מאותויום עליון, יוםהשביעי, ומתברכים כל ששה הימים כל אחד ואחד בפני עצמו, וכל יום נותן ביום שלו מאותה ברכה שקבל מאותו יום עליון, ועל זה אמר משה, איש אל יותר ממגו עד בקר, שהרי לא שולט יום ביום שלא שלו, וכל אותם) חֲמִשָּׁה יָמִים שׁוֹלְטִים בַּיָּמִים שֶׁלָּהֶם, וְנִמְצָא בּוֹ מַה שֶּׁקִּבְּלוּ, וּבַיּוֹם הַשִּׁשִּׁי נִמְצָא יוֹתֵר. וְזֶה הוֹלֵךְ כְּפִי מַה שֶּׁאָמַר רַבִּי אֶלְעָזָר, מַה שֶּׁכָּתוּב יוֹם הַשִּׁשִּׁי וְלֹא נֶאֱמַר כָּךְ בְּכָל שְׁאָר הַיָּמִים - אֶלָּא כָּךְ פֵּרְשׁוּהָ, הַשִּׁשִּׁי - שֶׁהִזְדַּוְּגָה (שהזדמנה) בּוֹ הַגְּבִירָה לְהַתְקִין שֻׁלְחָן לַמֶּלֶךְ. וְלָכֵן נִמְצְאוּ בוֹ שְׁנֵי חֲלָקִים - אֶחָד לְיוֹמוֹ, וְאֶחָד לְתִקּוּן בְּשִׂמְחַת הַמֶּלֶךְ בַּגְּבִירָה."],[6,"","וְאוֹתוֹ לַיְלָה שִׂמְחַת הַגְּבִירָה בַּמֶּלֶךְ וְזִוּוּגָם, וּמִתְבָּרְכִים כָּל שֵׁשֶׁת הַיָּמִים, כָּל אֶחָד וְאֶחָד לְבַדּוֹ, וְלָכֵן צָרִיךְ אָדָם לְסַדֵּר שֻׁלְחָנוֹ בְּלֵיל הַשַּׁבָּת, כְּדֵי שֶׁיִּשְׁרוּ עָלָיו בְּרָכוֹת מִלְמַעְלָה, וּבְרָכָה לֹא נִמְצֵאת עַל שֻׁלְחָן רֵיק. (ואותו לילה שמחתה של הגבירה במלך וזווגם) לָכֵן תַּלְמִידֵי חֲכָמִים שֶׁיּוֹדְעִים סוֹד זֶה, זִוּוּגָם מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת."],[7,"","רְאוּ כִּי ה' נָתַן לָכֶם הַשַּׁבָּת. מַה זֶּה שַׁבָּת? יוֹם שֶׁבּוֹ נָחִים שְׁאָר הַיָּמִים, וְהוּא כְּלָל שֶׁל כָּל אוֹתָם שֵׁשֶׁת הָאֲחֵרִים, וּמִמֶּנּוּ הֵם מִתְבָּרְכִים. רַבִּי יֵיסָא אָמַר, וְכֵן גַּם כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת שַׁבָּת, מִשּׁוּם שֶׁהִיא בַּת זוּגוֹ, וְזוֹהִי כַּלָּה, שֶׁכָּתוּב (שמות לא) וּשְׁמַרְתֶּם אֶת הַשַּׁבָּת כִּי קֹדֶשׁ הִיא לָכֶם. לָכֶם וְלֹא לִשְׁאָר הָעַמִּים. זֶהוּ שֶׁכָּתוּב (שם) בֵּינִי וּבֵין בְּנֵי יִשְׂרָאֵל. וְזוֹהִי נַחֲלַת יְרֻשַּׁת עוֹלָמִים לְיִשְׂרָאֵל. וְלָכֵן כָּתוּב (ישעיה נח) אִם תָּשִׁיב מִשַּׁבָּת רַגְלְךְ וְגוֹ', וּבִמְקוֹמוֹ בֵּאַרְנוּ אֶת הַדְּבָרִים."],[8,"","כָּתוּב אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ בַּיּוֹם הַשְּׁבִיעִי. מִמְּקוֹמוֹ - שָׁנִינוּ, מֵאוֹתוֹ מָקוֹם שֶׁרָאוּי לָלֶכֶת, וְסוֹד הַדָּבָר - שֶׁכָּתוּב (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ, וְזֶהוּ מָקוֹם, וְזֶהוּ סוֹד הַכָּתוּב, כִּי הַמָּקוֹם אֲשֶׁר אַתָּה עוֹמֵד עָלָיו אַדְמַת קֹדֶשׁ הוּא. מָקוֹם יָדוּעַ קוֹרְאִים לוֹ מָקוֹם שֶׁנּוֹדָע הַכָּבוֹד הָעֶלְיוֹן."],[9,"","וְלָכֵן אַזְהָרָה לָאָדָם שֶׁמִּתְעַטֵּר בְּעִטּוּר קָדוֹשׁ שֶׁלְּמַעְלָה, שֶׁלֹּא יֵצֵא מִפִּיו דִּבּוּר שֶׁל חֹל, מִשּׁוּם שֶׁאִם יֵצֵא מִמֶּנּוּ, הוּא מְחַלֵּל אֶת יוֹם הַשַּׁבָּת, בְּיָדוֹ - בְּמַעֲשֶׂה, וּבְרַגְלָיו - לָלֶכֶת מִחוּץ לְאַלְפַּיִם אַמָּה. כָּל אֵלּוּ הֵם חִלּוּל שַׁבָּת."]]],[["אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ, דָּא אִיהוּ אֲתָר יַקִּירָא דִּקְדוּשָּׁה, דְּהָא לְבַר מִנֵּיהּ, אֱלהִים אֲחֵרִים נִינְהוּ. בָּרוּךְ כְּבוֹד יְיָ', דָּא כָּבוֹד דִּלְעֵילָּא. מִמְּקוֹמוֹ, דָּא כָּבוֹד דִּלְתַתָּא. דָּא אִיהוּ רָזָא דַּעֲטָּרָא דְּשַׁבָּת, בְּגִין כַּךְ אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ. זַכָּאָה חוּלָקֵיהּ מַאן דְּזָכֵי לִיקָרָא דְּשַׁבְּתָא זַכָּאָה אִיהוּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","(שמות י״ז:ה׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה עֲבוֹר לִפְנֵי הָעָם וְגוֹ'. רִבִּי חִיָיא פָּתַח, (תהלים לה) חוֹנֶה מַלְאַךְ יְיָ' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בִּיקָרֵיהוֹן, יַתִּיר עַל דִּילֵיהּ. תָּא חֲזֵי, כַּמָּה אִינּוּן בְּנֵי עָלְמָא, דִּמְחָרְפֵי וּמְגַדְּפֵי לְעֵילָּא, כְּגוֹן סַנְחֵרִיב חֵרֵף וְגִדֵּף, וְאָמַר (מלכים ב י״ח:ל״ה) מִי בְּכָל אֱלהֵי הָאֲרָצוֹת וְגוֹ'. וְקוּדְשָׁא בְּרִיךְ הוּא מָחִיל, וְלָא תָּבַע מִנִּיהּ. כֵּיוָן דְּאוֹשִׁיט יְדֵיהּ עַל חִזְקִיָּה, מַה כְּתִיב (מלכים ב י״ט:ל״ה) וַיֵּצֵא מַלְאַךְ יְיָ' וַיַּךְ בְּמַחֲנִה אַשּׁוּר וְגוֹ'.","יָרָבְעָם בֶּן נְבָט הֲוָה פָּלַח לְעֲבוֹדָה זָרָה, וּמְקָטַר לָהּ, וּמְזָבַח לָהּ, וְקוּדְשָׁא בְּרִיךְ הוּא לָא תָּבַע מִנֵּיהּ. וְכַד אָתָא עִדוֹ נְבִיאָה, וְאִתְנַבֵּי עָלֵיהּ, וְאוֹשִׁיט יָרָבְעָם יְדָא לְקָבְלֵיהּ, מַה כְּתִיב (מלכים א י״ג:ד׳) וַתִּיבַשׁ יָדוֹ וְגוֹ', וְלֹא יָכֹל לַהֲשִׁיבָהּ אֵלָיו. (ועל דפלח לעבודה זרה לא תבע ליה קודשא בריך הוא)","פַּרְעֹה חֵרֵף וְגִדֵּף, וְאָמַר (שמות ה) מִי יְיָ' וְגוֹ'. וְקוּדְשָׁא בְּרִיךְ הוּא לָא תָּבַע מִנֵּיהּ, עַד דְּסָרִיב בְּהוּ בְּיִשְׂרָאֵל, דִּכְתִּיב, (שמות ט׳:י״ז) עוֹדְךָ מִסְתּוֹלֵל בְּעַמִּי. (שמות ט׳:י״ז) הִנֵּה יַד יְיָ' הוֹיָה בְּמִקְנְךְ וְגוֹ', וְכֵן בְּכָל אֲתָר, קוּדְשָׁא בְּרִיךְ הוּא תָּבַע עֶלְבּוֹנָא דְּצַדִּיקַיָּיא יַתִּיר עַל דִּילֵיהּ.","הָכָא מֹשֶׁה, אָמַר עוֹד מְעַט וּסְקָלוּנִי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה לָאו עִידָּן הוּא לְמִתְבַּע עֶלְבּוֹנָךְ, אֶלָּא עֲבוֹר לִפְנֵי הָעָם, וְאַחְמֵי מַאן יוֹשִׁיט יְדוֹי לָקֳבְלָךְ, וְכִי בִּרְשׁוּתַיְיהוּ אַתְּ קָאִים, אוֹ בִּרְשׁוּתִי.","וּמַטְּךָ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאוֹר קַח בְּיָדְךָ וְהָלָכְתָּ. מַאי טַעְמָא. מִשּׁוּם דִּמְחַקֵּק בַּנִּסִּין הֲוָה, וּשְׁמָא קַדִּישָׁא עִלָּאָה רְשִׁימָא בֵּיהּ. בְּקַדְמִיתָא נָחָשׁ, כְּמָה דְּאִתְּמַר, (משלי ל׳:י״ט) דֶּרֶךְ נָחָשׁ עֲלֵי צוּר. נָחָשׁ, הָא אִתְיְדַע דְּאִתְּעַר צוּר. (נ\"א ואתמר צור) בְּאָן אֲתָר אִתְגְּלֵי, הָכָא אִתְגְּלֵי דִּכְתִּיב הִנְנִי עוֹמֵד לְפָנֶיךָ שָׁם עַל הַצּוּר. וּמַאן צוּר. כְּמָה דְאַתְּ אָמֵר (דברים לכ) הַצּוּר תָמִים פָּעֳלוֹ, וְתַמָּן יָדַע מֹשֶׁה הֵיךְ קָאִים נָחָשׁ עָלֵי צוּר. וְהָא אוֹקִימְנָא מִלֵּי.","אָמַר רִבִּי יְהוּדָה, אִי לִישְׁתִּיק קְרָא יֵאוֹת שָׁאִילְתָּא. אֶלָּא הָא כְּתִיב, וְהִכִּיתָ בַצּוּר וַיָּצְאוּ מִמֶּנּוּ מַיִם. אָמַר לֵיהּ, וַדַּאי הָכִי הוּא, דְּלֵית לָךְ כָּל שְׁמָא וּשְׁמָא, מֵאִינּוּן שְׁמָהָן קַדִּישִׁין דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא עָבֵד נִסִּין וּגְבוּרָאן, וְאַפִּיק כֹּלָּא דְּאִצְטְרִיךְ לְעָלְמָא, כָּל שֶׁכֵּן לְאַפָּקָא הָכָא מַיָּא.","אֲמַר לֵיהּ, אִי הָכִי, הָא כְּתִיב, (תהילים ע״ח:כ׳) הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. מַאן מָחֵי לִשְׁמֵיהּ. אֲמַר לֵיהּ, פַּטִּישָׁא חֲרִיפָא, בְּקִטְרוֹי יְדִיעַ, וְאַתְּ שָׁאִיל דָּא. אֶלָּא תָּא חֲזֵי, בְּכָל אֲתָר צוּר גְּבוּרָה, וְכַד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְמַחֲאָה, אוֹ לְאַלְקָאָה, אִתְּעַר גְּבוּרָה דָּא וְהַהוּא גְּבוּרָה מָחֵי וְלָקֵי, וְדָא הוּא דִּכְתִּיב, הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. וְאִי לָאו דְּאִתְּעַר צוּר, וְלָקֵי בְּאֲתָר דְּאִצְטְרִיךְ, לָא נַבִיעִין מַיָּא.","אֲמַר לֵיהּ, אִי הָכִי, הָא כְּתִיב, (דברים ל״ב:י״ח) צוּר יְלָדְךָ תֶּשִׁי. וְתָנֵינָן מַאי תֶּשִׁי, כְּלוֹמַר חַלָּשְׁת לֵיהּ. אֲמַר לֵיהּ וַדַּאי הָכִי הוּא, דְּאִלְמָלֵי יִנְדְּעוּן חַיָּיבַיָּא, דְּהַאי צוּר זְמִינָא לְאִתְּעָרָא לָקֳבְלַיְיהוּ, וּלְאַלְקָאָה לוֹן, יִמָּנְעוּן מִלְּמֵיחָב קָמֵיהּ, אֶלָּא חַלְשָׁא אִיהִי בְּעֵינַיְיהוּ, הוֹאִיל וְלָא מִסְתַּכְּלֵי בָּהּ, וְלָא מִסְתַּכְּלֵי בְּאֹרְחַיְּיהוּ (ס\"א בכרסייהו) וְעַל דָּא צוּר יְלָדְךָ תֶּשִׁי.","ר' אַבָּא אָמַר, אִית צוּר, וְאִית צוּר, מִסִּטְרָא דְּצוּר עִלָּאָה, נָפַק צוּר אַחֲרָא. וּמַאי צוּר עִלָּאָה. צוּר דְּכָל צוּרִים. וּמַאי אִיהוּ, הַהוּא דְּאוֹלִידַת לְיִשְׂרָאֵל, דִּכְתִּיב צוּר יְלָדְךָ תֶּשִׁי. דְּהָא מִסִּטְרָא דְּצוּר עִלָּאָה דִּלְעֵילָּא, נָפְקָא צוּר אַחֲרָא. מִסִּטְרָא דְּאִימָא, נָפְקָא גְּבוּרָה.","וְאַזְלָא הָא כְּהָא דְּאָמַר רִבִּי אֶלְעָזָר, כְּתִיב (תהילים ק״ו:ב׳) מִי (פ\"ג ע\"א) יְמַלֵּל גְּבוּרוֹת יְיָ'. מַאי גְּבוּרוֹת יְיָ'. לְאַכְלְלָא אִימָא עִלָּאָה דְּכֹלָּא, דְּאַף עַל גַּב דְּלָאו אִיהִי דִּינָא, מִסִּטְרָהָא אִשְׁתְּכַח, דְּהָא מִסִּטְרָהָא גְּבוּרָה אִשְׁתְּכַח, וּבְגִינֵי כַּךְ צוּר עִלָּאָה אִקְרֵי. (דברים ל״ב:י״ח) וַתִּשְׁכַּח אֵל מְחוֹלְלֶךָ, דָּא נְהִירוּ דְּאַבָּא. מַאי נִיהוּ. חֶסֶד עִלָּאָה, דְּאִיהוּ נְהִירוּ דְּאַבָּא."],[[0,"אל יצא איש ממקומו:","זה הוא מקום יקר של הקדושה, כי לחוץ ממנו, אלהים אחרים הם. ברוך כבוד ה', זה הוא כבוד שלמעלה, דהיינו מלכות שמחזה ולמעלה. ממקומו, זהו כבוד שלמטה, דהיינו מלכות שמחזה ולמטה, זה היא סוד של העטרה של שבת שנק' מקום, משום זה אל יצא איש ממקומו. כי לחוץ ממנו אלהים אחרים הוא. אשרי חלקו מי שזכה ליקר השבת. אשרי הוא בעולם הזה ובעולם הבא."],[1,"ויאמר ה' אל משה עבור וגו':","ר' חייא פתח, חונה מלאך ה' סביב ליראיו ויחלצם. אשרי הם הצדיקים, שהקב\"ה רוצה בכבודם יותר מעל שלו. בוא וראה, כמה הם בני העולם, שמחרפים ומגדפים למעלה, דהיינו סנחריב חרף וגדף ואמר, מי בכל אלהי הארצות וגו', והקב\"ה מחל ולא נשה ממנו. כיון שהושיט ידו על חזקיה, מה כתוב. ויצא מלאך ה' ויך במחנה אשור וגו'."],[2,"ירבעם בן נבט וכו':","ירבעם בן נבט, היה עובד עבודה זרה ומקטר לה, ומזבח לה, והקב\"ה לא נשה ממנו. וכשבא עדו הנביא והתנבא עליו, וירבעם הושיט ידו כנגדו, מה כתוב, ותיבש ידו וגו', ולא יכול להשיבה אליו."],[3,"פרעה חרף וכו':","פרעה חרף וגדף ואמר, מי ה'. והקב\"ה לא נשה ממנו, עד שמיאן לשלח את ישראל, שכתוב, עודך מסתולל בעמי. אם מאן אתה לשלח וגו'. הנה יד ה' הויה במקנך. וכן בכל מקום, הקב\"ה נושה בעד פגיעה בכבוד הצדיקים יותר מעל שלו."],[4,"הכא משה אמר וכו':","כאן אמר משה, עוד מעט וסקלוני. אמר לו הקב\"ה, משה, אין עתה הזמן לנשות פגיעה בכבודך, אלא עבור לפני העם, ונראה מי יושיט ידו כנגדך. וכי ברשותם אתה עומד או ברשותי."],[5,"ומטך אשר וגו' קח בידך והלכת:","מהו הטעם. משום שחקוק בנסים היה, ושם הקדוש העליון היה רשום בו. בתחילה נהפך המטה לנחש. שה\"ס יסוד דז\"א דקטנות. כמו שלמדנו, דרך נחש עלי צור. נחש, הרי נודע שמעורר הצור, שהוא מלכות באיזה מקום נגלה הקב\"ה. כאן נגלה, שכתוב, הנני עומד לפניך על הצור. ומי צור. הוא כמש\"א, הצור תמים פעלו, שהוא מלכות, ושם ידע משה איך עומד הנחש עלי צור. וכבר העמדנו הדברים."],[6,"א\"ר יהודה וכו':","אר\"י, אם היה שותק הכתוב ולא אמר יותר היה יפה. השאלה הוא, אלא הרי כתוב, והכית בצור ויצאו ממנו מים. וכי זה נוהג אצל שם הקדוש. אמר ליה ודאי כך הוא. כי אין לך כל שם ושם מהשמות הקדושים של הקב\"ה, שלא יעשה נסים וגבורות, ומוציא כל מה שצריך לעולם, כל שכן כאן להוציא מים."],[7,"א\"ל אי הכי וכו':","אמר לו, אם כן, הרי כתוב, הכה צור ויזובו מים, מי מכה לשמו. א\"ל, פטיש מחודד ניכר בהכאותיו, כלומר איש חריף יודע להקשות, ואתה שואל זה. אלא בוא וראה, בכל מקום צור הוא גבורה, כלומר מלכות כשהיא בבחינת גבורה, וכשרוצה הקב\"ה, שהוא ז\"א, להכות או להעניש מתעורר גבורה זו, וגבורה ההיא מכה ומעניש. וזהו שכתוב, הן הכה צור וגו' שפירושו שהצור הכה. ואם לא שנתעורר הצור והכה במקום שצריך, לא היו נובעים מים."],[8,"א\"ל אי הכי וכו':","אמר לו אם כן, הרי כתוב צור ילדך תשי. ולמדנו, מהו תשי. החלשת אותו. שלא יתכן זה אצל שם. א\"ל, ודאי שכן הוא. כי אם היו יודעים הרשעים, כי הצור עתיד להתעורר כנגדם ולהענישם, היו מונעים מלחטא לפניו. אלא חלשה היא בעיניהם, משום שאינם מסתכלים בה, והיא אינה מסתכלת בדרכיהם להענישם תיכף. ועל זה נאמר צור ילדך תשי."],[9,"ר' אבא אמר וכו':","רא\"א, יש צור ויש צור, מצד צור העליון יוצא צור אחר. ומהו צור העליון. הוא צור של כל הצורים, ומי הוא, היא שהולידה את ישראל, שהוא ז\"א. שכתוב צור ילדך תשי. דהיינו בינה שהולידה את ישראל. כי מצד צור העליון של מעלה, יוצא צור אחר, מצד אמא שהיא בינה, יוצאת גבורה, שהיא המלכות."],[10,"ואזלא הא כהא דאמר וכו':","וזה הולך כמו שאמר ר' אלעזר. דא\"ר אלעזר כתוב, מי ימלל גבורות ה'. מהו גבורות ה'. הוא לכלול את אמא עלאה דכלא, שהיא בינה, שאע\"פ, שהיא עצמה אינה דין, מצדה נמצא הדין, כי מצדה נמצא גבורה, שהיא מלכות הממותקת בבינה, ומשום זה נקראת צור העליון. ותשכח אל מחוללך, זהו אור אבא. מה הוא. הוא חסד עליון שהוא אור אבא."]],[[0,"","אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ - זֶהוּ מָקוֹם נִכְבָּד שֶׁל קְדֻשָּׁה, שֶׁהֲרֵי מִחוּצָה לוֹ הֵם אֱלֹהִים אֲחֵרִים. בָּרוּךְ כְּבוֹד ה' - זֶהוּ כָּבוֹד שֶׁלְּמַעְלָה. מִמְּקוֹמוֹ - זֶה כָּבוֹד שֶׁלְּמַטָּה. זֶהוּ סוֹד עֲטֶרֶת הַשַּׁבָּת, וְלָכֵן אַל יֵצֵא אִישׁ מִמְּקוֹמוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה לְכַבֵּד אֶת הַשַּׁבָּת. אַשְׁרָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה עֲבֹר לִפְנֵי הָעָם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (תהלים לד) חֹנֶה מַלְאַךְ ה' סָבִיב לִירֵאָיו וַיְחַלְּצֵם. אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם יוֹתֵר עַל שֶׁלּוֹ. בֹּא רְאֵה כַּמָּה הֵם בְּנֵי הָעוֹלָם שֶׁמְּחָרְפִים וּמְגַדְּפִים לְמַעְלָה, כְּמוֹ שֶׁסַּנְחֵרִיב חֵרֵף וְגִדֵּף וְאָמַר (מלכים ב יח) מִי בְּכָל אֱלֹהֵי הָאֲרָצוֹת וְגוֹ'. וְהַקָּדוֹשׁ בָּרוּךְ הוּא מָחַל וְלֹא תָבַע מִמֶּנּוּ. כֵּיוָן שֶׁהוֹשִׁיט אֶת יָדוֹ עַל חִזְקִיָּה, מַה כָּתוּב? (שם יט) וַיֵּצֵא מַלְאַךְ ה' וַיַּךְ בְּמַחֲנֵה אַשּׁוּר וְגוֹ'."],[2,"","יָרָבְעָם בֶּן נְבָט הָיָה עוֹבֵד לַעֲבוֹדָה זָרָה וּמְקַטֵּר לָהּ וְזוֹבֵחַ לָהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא תָבַע מִמֶּנּוּ. וּכְשֶׁבָּא עִדּוֹ הַנָּבִיא וְהִתְנַבֵּא עָלָיו, וְהוֹשִׁיט יָרָבְעָם אֶת יָדוֹ כְּנֶגְדּוֹ - מַה כָּתוּב? (שם א יג) וַתִּיבַשׁ יָדוֹ וְגוֹ', וְלֹא יָכֹל לַהֲשִׁיבָהּ אֵלָיו. (ועלשעבדלעבודהזרהלא תבע אותו הקדוש ברוך הוא)."],[3,"","פַּרְעֹה חֵרֵף וְגִדֵּף, וְאָמַר (שמות ה) מִי ה' וְגוֹ', וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא תָבַע מִמֶּנּוּ, עַד שֶׁסֵּרַב לְיִשְׂרָאֵל, שֶׁכָּתוּב (שם ט) עוֹדְךְ מִסְתּוֹלֵל בְּעַמִּי, (שם) הִנֵּה יַד ה' הוֹיָה בְּמִקְנְךְ וְגוֹ'. וְכֵן בְּכָל מָקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹבֵעַ אֶת עֶלְבּוֹן הַצַּדִּיקִים יוֹתֵר עַל שֶׁלּוֹ."],[4,"","כָּאן מֹשֶׁה אָמַר (שם יז) עוֹד מְעַט וּסְקָלוּנִי. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, אֵינוֹ זְמַן לִתְבֹּעַ אֶת עֶלְבּוֹנְךְ, אֶלָּא עֲבֹר לִפְנֵי הָעָם, וְנִרְאֶה מִי יוֹשִׁיט יָדוֹ כְּנֶגְדְּךְ. וְכִי בִּרְשׁוּתָם אַתָּה עוֹמֵד, אוֹ בִּרְשׁוּתִי?"],[5,"","וּמַטְךָ אֲשֶׁר הִכִּיתָ בּוֹ אֶת הַיְאֹר קַח בְּיָדְךְ וְהָלָכְתָּ. מָה הַטַּעַם? מִשּׁוּם שֶׁהָיָה חָקוּק בְּנִסִּים, וְרָשׁוּם בּוֹ הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן. בַּתְּחִלָּה לְנָחָשׁ, כְּמוֹ שֶׁנֶּאֱמַר (משליכט) דֶּרֶךְ נָחָשׁ עֲלֵי צוּר. נָחָשׁ, הֲרֵי נוֹדָע שֶׁמְּעוֹרֵר צוּר. (ונאמר צור) בְּאֵיזֶה מָקוֹם הִתְגַּלָּה? כָּאן הוּא הִתְגַּלָּה, שֶׁכָּתוּב הִנְנִי עֹמֵד לְפָנֶיךְ שָּׁם עַל הַצּוּר. וּמַה זֶּה צוּר? כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) הַצּוּר תָּמִים פָּעֳלוֹ. וְשָׁם יָדַע מֹשֶׁה אֵיךְ עוֹמֵד נָחָשׁ עֲלֵי צוּר. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים."],[6,"","אָמַר רַבִּי יְהוּדָה, אִם הָיָה הַכָּתוּב שׁוֹתֵק - יָפֶה שָׁאַלְתָּ. אֶלָּא הֲרֵי כָּתוּב, וְהִכִּיתָ בַצּוּר וְיָצְאוּ מִמֶּנּוּ מַיִם. אָמַר לוֹ, וַדַּאי כָּךְ הוּא, שֶׁאֵין לְךְ כָּל שֵׁם וְשֵׁם מֵאוֹתָם שֵׁמוֹת קְדוֹשִׁים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא עוֹשֶׂה נִסִּים וּגְבוּרוֹת וּמוֹצִיא כָּל מַה שֶּׁצָּרִיךְ לָעוֹלָם, כָּל שֶׁכֵּן לְהוֹצִיא כָּאן מַיִם."],[7,"","אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. מִי מַכֶּה אֶת שְׁמוֹ? אָמַר לוֹ, פַּטִּישׁ חָרִיף יָדוּעַ בְּהַכָּאוֹתָיו, וְאַתָּה שׁוֹאֵל אֶת זֶה? אֶלָּא בּא רְאֵה, בְּכָל מָקוֹם צוּר זֶה גְּבוּרָה, וּכְשֶׁרוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכּוֹת אוֹ לְהַלְקוֹת, מִתְעוֹרֶרֶת גְּבוּרָה זוֹ, וְאוֹתָהּ הַגְּבוּרָה מַכָּה וּמַלְקָה. וְזֶהוּ הַכָּתוּב (תהלים עח) הֵן הִכָּה צוּר וַיָּזוּבוּ מַיִם. וְאִם לֹא שֶׁמִּתְעוֹרֵר צוּר וּמַלְקֶה בְּמָקוֹם שֶׁצָּרִיךְ - לֹא נוֹבְעִים מַיִם."],[8,"","אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב (דברים לב) צוּר יְלָדְךְ תֶּשִׁי. וְשָׁנִינוּ, מַה זֶּה תֶּשִׁי? כְּלוֹמַר הֶחֱלַשְׁתָּ אוֹתוֹ. אָמַר לוֹ, וַדַּאי כָּךְ זֶה, שֶׁאִלְמָלֵא יָדְעוּ הָרְשָׁעִים שֶׁהַצּוּר הַזֶּה עָתִיד לְהִתְעוֹרֵר כְּנֶגְדָּם וּלְהַלְקוֹת אוֹתָם, יִמָּנְעוּ מִלַּחֲטֹא לְפָנָיו, אֶלָּא חַלָּשׁ הוּא בְּעֵינֵיהֶם, הוֹאִיל וְאֵינָם מִתְבּוֹנְנִים בּוֹ וְלֹא מִסְתַּכְּלִים בְּדַרְכֵיהֶם (בכסאותיהם), וְעַל זֶה צוּר יְלָדְךְ תֶּשִׁי."],[9,"","רַבִּי אַבָּא אָמַר, יֵשׁ צוּר וְיֵשׁ צוּר. מִצַּד הַצּוּר הָעֶלְיוֹן יוֹצֵא צוּר אַחֵר. וּמַה זֶּה צוּר הָעֶלְיוֹן? צוּר שֶׁל כָּל הַצּוּרִים. וּמַהוּ? אוֹתוֹ שֶׁהוֹלִיד אֶת יִשְׂרָאֵל, שֶׁכָּתוּב צוּר יְלָדְךְ תֶּשִׁי. שֶׁהֲרֵי מִצַּד שֶׁל הַצּוּר הָעֶלְיוֹן שֶׁלְּמַעְלָה יוֹצֵא צוּר אַחֵר. מִצַּד הָאֵם יוֹצֵאת גְּבוּרָה."],[10,"","וְזְה הוֹלֵךְ כְּמוֹ מַה שֶּׁאָמַר רַבִּי אֶלְעָזָר. כָּתוּב (תהלים קו) מִי יְמַלֵּל גְּבוּרוֹת ה'. מַה זֶּה גְּבוּרוֹת ה '? לְהַכְלִיל אֶת הָאֵ ם הָעֶלְיוֹנָה שֶׁל הַכֹּל. שֶׁאַף עַל גַּב שֶׁאֵינָהּ דִּין, נִמְצָא מִצִּדָּהּ, שֶׁהֲרֵי הַגְּבוּרָה נִמְצֵאת מִצִּדָּהּ, וְלָכֵן נִקְרֵאת הַצּוּר הָעֶלְיוֹן. (דברים לב) וַתִּשְׁכַּח אֵל מְחֹלֲלֶךְ - זֶה אוֹר שֶׁל אַבָּא. מַה הוּא? חֶסֶד עֶלְיוֹן, שֶׁהוּא אוֹר שֶׁל אַבָּא."]]],[["תּוּ אָמַר רִבִּי אַבָּא, מַיִם בְּכָל מָקוֹם, הָא יְדִיעָא, וְקוּדְשָׁא בְּרִיךְ הוּא בְּהַאי צוּר אִתְּעַר לְאַרְקָא מַיָּא, דְּהָא לָא אִתְחָזֵי, (אלא מגדולה) וְדָא הוּא אָת וְנִיסָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא שָׁבַח דָּוִד וְאָמַר, (תהילים קי״ד:ח׳) הַהֹפְכִי הַצּוּר אֲגַם מָיִם וְגוֹ'. וּמַשְׁמַע הַהֹפְכִי, דְּהָא לָאו אָרְחוֹי דְּצוּר בְּכַךְ.","וְעַל דָּא, בְּצוּר עִלָּאָה, אַפִּיק מַיָּא מֵאֲתָר דִּלְתַתָּא. וּמַה שְׁמֵיהּ דְּהַהוּא דִּלְתַתָּא. סֶלַע. דִּכְתִּיב, (במדבר כ׳:ח׳) וְהוֹצֵאתָ לָהֶם מַיִם מִן הַסֶּלַע. וּבַמֶּה אַפִּיק הַאי סֶלַע מַיָּא. בְּחֵילָא דְּצוּר דִּלְעֵילָּא.","רַבִּי שִׁמְעוֹן אָמַר, (דברים ל״ב:ד׳) הַצּוּר תָמִים פָּעֳלוֹ מַאי מַשְׁמַע הַצּוּר תָמִים פָּעֳלוֹ. דְּאִתְהַפָּךְ צוּר, לְמֶעְבַּד פָּעֳלוֹ דְּתָמִים. וּמַאי אִיהוּ. אַבְרָהָם. דִּכְתִּיב בֵּיהּ (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. וְדָא הוּא הַהֹפְכִי הַצּוּר אֲגַם מָיִם, וּמַשְׁמַע תָמִים פָּעֳלוֹ, וְדָא אַבְרָהָם.","בְּשַׁעֲתָא דָּא, אִתְהַדַּר הַצּוּר, תָמִים. בְּשַׁעֲתָא אַחֲרָא תִּנְיָינָא, כַּד (אתענש) בָּעָא מֹשֶׁה לְאַפָּקָא מַיָּא בְּהַאי צוּר, בְּחוֹבַיְיהוּ דְּיִשְׂרָאֵל, לָא אִתְהַדַּר תָמִים, כְּקַדְמִיתָא. בֵּיהּ זִמְנָא, אִתְרָעַם מֹשֶׁה וְאָמַר, צוּר יְלָדְךָ תֶּשִׁי. כְּלוֹמַר, חַלָּשְׁת לֵיהּ מִמַּה דְּהֲוָה בְּקַדְמִיתָא, דִּבְגִינָךְ לָא אִשְׁתְּכַח תָּמִים הַשְׁתָּא, וְאִתְעָבִיד (ביה) דִּינָא, מַה דְּלָא הֲוָה בְּיוֹמֵי יְלָדְךָ, כְּלוֹמַר עוּלֵימָךְ.","אָמַר רִבִּי אַבָּא, מַאי דִּכְתִּיב הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן. וְכִי טִפְּשִׁין הֲווֹ יִשְׂרָאֵל דְּלָא יַדְעֵי מִלָּה דָּא, וְהָא חָמוּ שְׁכִינְתָּא קָמַיְיהוּ, וַעֲנֵנִי כָּבוֹד עָלַיְיהוּ דְּסַחְרוֹן לוֹן, וְאִינּוּן אָמְרוּ הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן, גּוּבְרִין דְּחָמוּ זִיו יְקָרָא דְּמַלְכֵּיהוֹן עַל יַמָּא, וְתָנֵינָן, רָאָתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל, אִינּוּן אִשְׁתְּכָחוּ טִפְּשִׁין, וְאָמְרוּ הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן.","אֶלָּא (נשא קכ\"ט ע\"א) הָכִי קָאָמַר רַבִּי שִׁמְעוֹן, בָּעוּ לְמִנְדַּע, בֵּין עַתִּיקָא סְתִימָאָה דְּכָל סְתִימִין, דְּאִקְרֵי אַיִן. וּבֵין זְעֵיר אַפִּין דְּאִקְרֵי יְיָ'. וְעַל דָּא, לָא כְּתִיב הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם לא, כְּמָה דִּכְתִּיב הֲיֵלֶךְ בְּתוֹרָתִי אִם לֹא. אֶלָּא הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן.","אִי הָכִי אֲמַאי אִתְעַנְשׁוּ. אֶלָּא עַל דַּעֲבִידוּ פִּרוּדָא, וַעֲבִידוּ בְּנִסְיוֹנָא, דִּכְתִּיב וְעַל נַסּוֹתָם אֶת יְיָ'. אָמְרוּ יִשְׂרָאֵל, אִי הַאי נִשְׁאַל בְּגַוְונָא חַד. וְאִי הַאי נִשְׁאַל בְּגַוְונָא אַחֲרָא. וְעַל דָּא מִיָּד וַיָּבֹא עֲמָלֵק.","(שמות י״ז:ח׳) וַיָּבֹא עֲמָלֵק וַיִּלָּחֶם עִם יִשְׂרָאֵל בִּרְפִידִים. רִבִּי יוֹסֵי פָּתַח, (ישעיהו ל״ב:כ׳) (ו' ע\"א) אַשְׁרֵיכֶם זוֹרְעֵי עַל כָּל מָיִם מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר. אַשְׁרֵיכֶם זוֹרְעֵי עַל כָּל מָיִם, תַּמָּן תָּנִינָן, כַּמָּה מַיִם וְכַמָּה מַיִם מִשְׁתַּכְּחִין. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּלֵית זַרְעָא לְהוּ, אֶלָּא עַל הַמַּיִם, דִּכְתִּיב וְיַּחֲנוּ שָׁם עַל הַמָּיִם, אִינּוּן דַּהֲווֹ תְּחוֹת עַנְפֵי אִילָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","דְּתַנְיָא, אִילָנָא אִית לְקוּדְשָׁא בְּרִיךְ הוּא, וְהוּא אִילָנָא רַבְרְבָא וְתַקִּיפָא, וּבֵיהּ אִשְׁתְּכַח מְזוֹנָא לְכֹלָּא. וְהוּא אִתְּחַם בִּתְרֵיסַר תְּחוּמִין, בְּמַתְקְלָא, וְאִתְתַּקַּף בְּאַרְבַּע רוּחֵי עָלְמָא. וְע' עַנְפִּין אֲחִידָן בֵּיהּ וְיִשְׂרָאֵל מִשְׁתַּכְּחֵי בְּגוּפָא דְּהַהוּא אִילָנָא. וְאִינּוּן שִׁבְעִין עַנְפִּין סַחֲרָנָא דִּלְהוֹן.","וְהַיְינוּ דִּכְתִּיב, וַיָּבֹאוּ אֵלִימָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינוֹת מַיִם וְשִׁבְעִים תְּמָרִים, וְהָא אוּקְמוּהָ, וְאִתְּמַר בְּכַמָּה אֲתָר. מַאי וְיַּחֲנוּ שָׁם עַל הַמָּיִם. אֶלָּא בְּהַהוּא זִמְנָא, שָׁלִיטוּ עַל אִינּוּן מַיָּא, דְּאִינּוּן תְּחוֹת עַנְפִּין דְּאִילָנָא, דְּאִקְרוּן (תהילים קכ״ד:ה׳) הַמַּיִם הַזֵּידוֹנִים. וְעַל דָּא אַשְׁרֵיכֶם זוֹרְעֵי עַל כָּל מָיִם.","מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר, אִינּוּן תְּרֵין כִּתְרֵי שְׂמָאלָא, דַּאֲחִידָן בְּהוּ עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, דְּאִקְרוּן שׁוֹר וַחֲמוֹר. וְהַיְינוּ דִּכְתִּיב, (בראשית לכ) וַיְהִי לִי שׁוֹר וַחֲמוֹר. בְּגִין דְּלָבָן חַכִּים הֲוָה בַּחֲרָשִׁין וּבְאִינּוּן כִּתְרִין תַּתָּאִין, וּבְאִינּוּן בָּעָא לְאוֹבָדָא לְיַעֲקֹב, כְּמָה דִּכְתִּיב, (דברים כ״ו:ה׳) אַרָמִי אוֹבֵד אָבִי, וְהָא אִתְּמַר. וּכְשֶׁיִּשְׂרָאֵל זַכָּאִין, מְשַׁלְּחֵי לְהוּ, וְלָא יַכְלֵי לְשַׁלְּטָאָה עָלַיְיהוּ, הֲדָא הוּא דִכְתִיב מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר דְּלָא שַׁלְטֵי בְּהוּ."],[[0,"תו אמר ר' אבא וכו':","עוד אר\"א, מים, בכל מקום שכתוב, הוא נודע, שרומז על אור חסד. והקב\"ה נתעורר בצור הזה, שהוא דין, להשפיע מים, שהוא חסד, שהרי אין זה ראוי לצאת אלא מחסד. וזה הוא אות ונס של הקב\"ה, שצור שהוא דין השפיע חסדים. ועל זה שבח דוד ואמר, ההפכי הצור אגם מים וגו'. ומשמע ההפכי, שהפך אותו מדין לחסד. כי אין דרך צור בזה להשפיע חסד."],[1,"ועל דא בצור וכו':","ועל זה, בצור העליון, שהוא בינה, הוציא מים ממקום שלמטה, ממלכות ומה שמו של ההוא של מטה, \u0003סלע.\u0004 שכתוב, והוצאת להם מים מן הסלע. ובמה הוציא סלע הזה מים, הוא בכח של צור העליון, שהוא בינה."],[2,"ר\"ש אמר הצור וכו':","רש\"א, הצור תמים פעלו. מהו הפירוש של צור תמים פעלו, הוא, שנהפך הצור לעשות פעלו דתמים, ומי הוא, אברהם, שהוא חסד, שכתוב בו, התהלך לפני והיה תמים. וזה הוא ההפכי הצור אגם מים, שנהפך ממעשה הדין למעשה החסד. ומשמע שתמים פעלו, דהיינו חסד, וזה אברהם. שהוא חסד."],[3,"בשעתא דא אתהדר וכו':","בשעה זו חזר הצור להיות תמים. בשעה אחרת, שניה, כשרצה משה להוציא מים מצור הזה, בעונותיהם של ישראל לא חזר לתמים כבתחילה. בו בזמן התרעם משה, ואמר, צור ילדך תשי. כלומר החלשת אותו ממה שהיה בתחילה. שבשבילך לא נמצא תמים עתה, ונעשה דין, מה שלא היה כן בימי ילדך, כלומר, בימי נעוריך."],[4,"א\"ר אבא וכו':","אר\"א, מה שכתוב, היש ה' בקרבנו אם אין. וכי שוטים היו ישראל, שלא ידעו דבר זה. והרי ראו השכינה לפניהם, וענני כבוד עליהם שסובבים אותם, והם אמרו, היש ה' בקרבנו אם אין. אנשים שראו זיו יקר מלכם על הים. ולמדנו, ראתה שפחה על הים, מה שלא ראה יחזקאל. הם נמצאו שוטים, ואמרו, היש ה' בקרבנו אם אין."],[5,"אלא הכי קאמר וכו':","ומשיב, אלא כך אמר ר שמעון, רצו לדעת בין עתיקא הסתום מכל סתומים, שהוא כתר, שנקרא \u0003אין,\u0004 ובין ז\"א, שנקרא הויה. ועל כן לא כתוב, אם יש ה' בקרבנו אם לא, כמ\"ש, אם ילך בתורתי אם לא אלא היש ה' בקרבנו אם \u0003אין.\u0004"],[6,"אי הכי אמאי וכו':","שואל, א\"כ למה נענשו. ומשיב, אלא על שעשו פירוד בין עתיקא לז\"א, ועשו בנסיון, שכתוב ועל נסותם את ה', אמרו ישראל אם זה בקרבנו נשאל באפן אחד, ואם זה, נשאל באפן אחר. וע\"כ מיד ויבא עמלק."],[7,"ויבא עמלק וילחם וגו':","ר' יוסי פתח, אשריכם זורעי על כל מים משלחי רגל השור וחמור. אשריכם זורעי על כל מים. שם למדנו. כמה מים וכמה מים נמצאים, שיש כמה מיני אורות, דהיינו מים מתוקים דקדושה ויש מים המרים ומים הזדונים אשרי הם ישראל, שאין זרע להם אלא על המים, דהיינו להכניע כל מיני מים דס\"א, שכתוב ויחנו שם על המים. היינו על אלו המים שהיו תחת ענפי האילן של הקב\"ה. שהם מים זדונים, כמ\"ש לפנינו."],[8,"דתניא אילנא אית וכו':","שלמדנו, שיש אילן להקב\"ה, שהיא בינה, והוא אילן גדול וחזק, שהוא ז\"א, ובו נמצא מזונות לכל. והוא מוגבל בי\"ב גבולים, דהיינו ג' קוין לכל אחד מחו\"ג תו\"מ, שהם י\"ב. ומתחזק בד' רוחות העולם, שהם חו\"ג תו\"מ. וע' ענפים אחוזים בו. שהם ע' השרים של ע' האומות. וישראל נמצאים בגוף של האילן הזה, וע' ענפין הם מסביב להם, מסביב לישראל האחוזים בגוף האילן."],[9,"והיינו דכתיב ויבואו וגו':","והיינו שכתוב, ויבואו אלימה ושם שתי עשרה עינות מים ושבעים תמרים, וכבר בארנו, ולמדנו בכמה מקומות. מהו ויחנו שם על המים. אלא באותו זמן שלטו ישראל על אלו המים, שהם תחת ענפי האילן, הנקראים המים הזדונים. ועל זה כתוב, אשריכם זורעי על כל מים. דהיינו להכניע כל מיני מים דס\"א."],[10,"משלחי רגל השור והחמור:","הם ב' כתרים של השמאל, שנאחזים בהם העמים עכו\"ם, הנקראים שור וחמור. והיינו שכתוב, ויהי לי שור וחמור. משום שלבן חכם היה בכשפים ובאלו כתרים התחתונים, ובאלו, שור וחמור, רצה לאבד את יעקב, כמ\"ש ארמי אובד אבי. וכבר למדנו. וכשישראל זוכים משלחים אותם, ואינם יכולים לשלוט עליהם. ז\"ש משלחי רגל השור והחמור. שאינם שולטים בהם."]],[[0,"","עוֹד אָמַר רַבִּי אַבָּא, מַיִם בְּכָל מָקוֹם, הֲרֵי יָדוּעַ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעוֹרֵר בַּצּוּר הַזֶּה לְהוֹרִיק מַיִם, שֶׁהֲרֵי לֹא רָאוּי (אלא מגדלה), וְזֶהוּ אוֹת וָנֵס שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְעַל זֶה שִׁבַּח דָּוִד וְאָמַר, (תהלים קיד) הַהֹפְכִי הַצּוּר אֲגַם מָיִם וְגוֹ'. וּמַשְׁמָע הַהֹפְכִי, שֶׁהֲרֵי אֵין דֶּרֶךְ הַצּוּר בְּכָךְ."],[1,"","וְעַל זֶה בַּצּוּר הָעֶלְיוֹן הוֹצִיא מַיִם מִמָּקוֹם שֶׁלְּמַטָּה. וּמַה שְּׁמוֹ שֶׁל אוֹתוֹ שֶׁלְּמַטָּה? סֶלַע, שֶׁכָּתוּב וְהוֹצֵאתָ לָהֶם מַיִם מִן הַסֶּלַע. וּבַמָּה הוֹצִיא הַסֶּלַע הַזֶּה מַיִם? בְּכֹחַ הַצּוּר שֶׁלְּמַעְלָה."],[2,"","רַבִּי שִׁמְעוֹן אָמַר, הַצּוּר תָּמִים פָּעֳלוֹ, מַה מַּשְׁמָעוֹ שֶׁל הַצּוּר תָּמִים פָּעֳלוֹ? שֶׁהִתְהַפֵּךְ הַצּוּר לַעֲשׂוֹת פָּעֳלוֹ שֶׁל תָּמִים. וּמִיהוּ הַתָּמִים? אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. וְזֶהוּ הַהֹפְכִי הַצּוּר אֲגַם מָיִם, וּמַשְׁמָע תָּמִים פָּעֳלוֹ, וְזֶה אַבְרָהָם."],[3,"","בְּשָׁעָה זוֹ הוֹפֵךְ הַצּוּר לְתָמִים. בְּשָׁעָה שְׁנִיָּה אַחֶרֶת, כְּשֶׁרָצָה (כשגענש) מֹשֶׁה לְהוֹצִיא מַיִם בַּצּוּר הַזֶּה, בַּחֲטָאֵי יִשְׂרָאֵל לֹא חָזַר לְתָמִים כְּמוֹ בַּהַתְחָלָה. בְּאוֹתוֹ זְמַן הִתְרַעֵם מֹשֶׁה וְאָמַר, צוּר יְלָדְךְ תֶּשִׁי. כְּלוֹמַר, הֶחֱלַשְׁתָּ אוֹתוֹ מִמַּה שֶּׁהָיָה בַּתְּחִלָּה, שֶׁבִּשְׁבִילְךְ לֹא נִמְצָא עַכְשָׁו תָּמִים, וְנַעֲשֶׂה (בו) דִּין, מַה שֶּׁלֹּא הָיָה בִּימֵי יְלָדְךְ, כְּלוֹמַר עֲלוּמֶיךְ."],[4,"","אָמַר רַבִּי אַבָּא, מַה זֶּה שֶׁכָּתוּב הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן? וְכִי הָיוּ יִשְׂרָאֵל טִפְּשִׁים שֶׁלֹּא יָדְעוּ דָּבָר זֶה, וַהֲרֵי רָאוּ שְׁכִינָה לִפְנֵיהֶם וְעַנְנֵי כָבוֹד עֲלֵיהֶם, שֶׁמַּקִּיפִים אוֹתָם, וְהֵם אוֹמְרִים הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן? אֲנָשִׁים שֶׁרָאוּ אֶת זִיו כְּבוֹד מַלְכָּם עַל הַיָּם, וְלָמַדְנוּ שֶׁרָאֲתָה שִׁפְחָה עַל הַיָּם מַה שֶּׁלֹּא רָאָה יְחֶזְקֵאל, הֵם נִמְצְאוּ טִפְּשִׁים וְאָמְרוּ הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן?"],[5,"","אֶלָּא כָּךְ אָמַר רַבִּי שִׁמְעוֹן, רָצוּ לָדַעַת בֵּין הָעַתִּיק הַנִּסְתָּר שֶׁל כָּל הַנִּסְתָּרִים שֶׁנִּקְרָא אַיִן, וּבֵין זְעֵיר אַנְפִּין שֶׁנִּקְרָא ה', וְלָכֵן לֹא כָתוּב הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם לֹא, כַּכָּתוּב הֲיֵלֵךְ בְּתוֹרָתִי אִם לֹא, אֶלָּא - הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן."],[6,"","אִם כָּךְ, לָמָּה נֶעֶנְשׁוּ? אֶלָּא מִשּׁוּם שֶׁעָשׂוּ פֵרוּד, וְעָשׂוּ בְנִסָּיוֹן, שֶׁכָּתוּב וְעַל נַסֹּתָם אֶת ה'. אָמְרוּ יִשְׂרָאֵל, אִם זֶה - נִשְׁאַל בְּגָוֶן אֶחָד, וְאִם זֶה - נִשְׁאַל בְּגָוֶן אַחֵר. וְלָכֵן מִיָּד - וַיָּבֹא עֲמָלֵק."],[7,"","וַיָּבֹא עֲמָלֵק וַיִּלָּחֶם עִם יִשְׂרָאֵל בִּרְפִידִם. רַבִּי יוֹסֵי פָּתַח, (ישעיה לב) אַשְׁרֵיכֶם זרְעֵי עַל כָּל מָיִם מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר. אַשְׁרֵיכֶם זרְעֵי עַל כָּל מָיִם - שָׁם שָׁנִינוּ כַּמָּה מַיִם וְכַמָּה מַיִם נִמְצָאִים. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁאֵין לָהֶם זֶרַע אֶלָּא עַל הַמַּיִם, שֶׁכָּתוּב וַיַּחֲנוּ שָׁם עַל הַמָּיִם. אוֹתָם שֶׁהָיוּ תַּחַת עַנְפֵי הָאִילָן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[8,"","שֶׁשָּׁנִינוּ, יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא אִילָן, וְהוּא אִילָן גָּדוֹל וְחָזָק, וּבוֹ נִמְצָא מָזוֹן לַכֹּל, וְהוּא נִתְחָם בִּשְׁנֵים עָשָׂר תְּחוּמִים, בְּמִשְׁקָל, וּמִתְחַזֵּק בְּאַרְבַּע רוּחוֹת הָעוֹלָם. וְשִׁבְעִים עֲנָפִים אֲחוּזִים בּוֹ, וְיִשְׂרָאֵל נִמְצָאִים בַּגּוּף שֶׁל אוֹתוֹ הָאִילָן, וְאוֹתָם שִׁבְעִים עֲנָפִים מַקִּיפִים אוֹתָם."],[9,"","וְהַיְנוּ שֶׁכָּתוּב, וַיָּבֹאוּ אֵילִמָה וְשָׁם שְׁתֵּים עֶשְׂרֵה עֵינֹת מַיִם וְשִׁבְעִים תְּמָרִים, וַהֲרֵי פֵּרְשׁוּהָ, וְנִתְבָּאֵר בְּכַמָּה מְקוֹמוֹת. מַה זֶּה וַיַּחֲנוּ שָׁם עַל הַמָּיִם? אֶלָּא בְּאוֹתוֹ זְמַן שָׁלְטוּ עַל אוֹתָם הַמַּיִם, שֶׁהֵם תַּחַת הָעֲנָפִים שֶׁל הָאִילָן, שֶׁנִּקְרָאִים הַמַּיִם הַזֵּדוֹנִים. וְלָכֵן אַשְׁרֵיכֶם זרְעֵי עַל כָּל מָיִם."],[10,"","מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר - אוֹתָם שְׁנֵי כִּתְרֵי הַשְּׂמֹאל שֶׁהָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת אֲחוּזִים בָּהֶם, שֶׁנִּקְרָאִים שׁוֹר וַחֲמוֹר, וְהַיְנוּ מַה שֶּׁכָּתוּב וַיְהִי לִי שׁוֹר וַחֲמוֹר. מִשּׁוּם שֶׁלָּבָן הָיָה חָכָם בִּכְשָׁפִים וּבְאוֹתָם כְּתָרִים תַּחְתּוֹנִים, וּבָהֶם רָצָה לְהַאֲבִיד אֶת יַעֲקֹב, כַּכָּתוּב אֲרַמִּי אֹבֵד אָבִי, וַהֲרֵי נֶאֱמַר. וּכְשֶׁיִּשְׂרָאֵל צַדִּיקִים, מְשַׁלְּחִים אוֹתָם, וְלֹא יְכוֹלִים לִשְׁלֹט עֲלֵיהֶם. זֶהוּ שֶׁכָּתוּב מְשַׁלְּחֵי רֶגֶל הַשּׁוֹר וְהַחֲמוֹר, שֶׁלֹּא שׁוֹלְטִים בָּהֶם."]]],[["אָמַר רִבִּי אַבָּא, כַּד מִזְדַּוְּוגֵי כַּחֲדָא, לָא יַכְלֵי בְּנֵי עָלְמָא לְמֵיקָם בְּהוּ, וְעַל דָּא כְּתִיב (דברים כ״ב:י׳) לא תַחֲרוֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו. יַחְדָּיו דַּיְיקָא. וְתָנֵינָן, לָא יָהִיב אִינִישׁ דּוּכְתָּא לְזִינִין בִּישִׁין, דְּהָא בְּעוֹבָדָא דְּבַּר נָשׁ (לתתא), אִתְּעַר מַה דְּלָא אִצְטְרִיךְ. וְכַד מִזְדַּוְּוגֵי כַּחֲדָא, (לא יכלין למיקם בהו. מבין סטרא דלהון נפיק) מִתְּקִיפוּתָא דִּלְהוֹן דְּאִקְרֵי כֶּלֶב, וְדָא חֲצִיפָא מִכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, (שמות י״א:ז׳) וּלְכָל בְּנֵי יִשְׂרָאֵל לא יֶחרַץ כֶּלֶב לְשׁוֹנוֹ. (נ\"א מתקיפותא דלהון אפיק ההוא דאקרי כלב, ודא חציפא מכלהו) אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַתּוּן אֲמַרְתּוּן, הֲיֵשׁ יְיָ' בְּקִרְבֵּנוּ אִם אָיִן, הֲרֵי אֲנִי מוֹסֵר אֶתְכֶם לַכֶּלֶב. מִיָּד וַיָּבֹא עֲמָלֵק.","ר' יְהוּדָה אָמַר, (במדבר כ״ד:כ׳) רֵאשִׁית גּוֹיִם עֲמָלֵק וְאַחֲרִיתוֹ עֲדֵי אוֹבֵד. וְכִי רֵאשִׁית גּוֹיִם עֲמָלֵק, וַהֲלֹא כַּמָּה לִישָׁנִין וְעַמִּין וְאוּמִין הֲווֹ בְּעָלְמָא, עַד לָא אָתָא עֲמָלֵק.","אֶלָּא, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, דְּחִילוּ וְאֵימָתָא נָפְלָה עַל כָּל עַמִּין דְּעָלְמָא מִיִּשְׂרָאֵל, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:י״ד) שָׁמְעוּ עַמִּים יִרְגָּזוּן חִיל אָחַז יוֹשְבֵי פְּלָשֶׁת. וְלָא הֲווֹ עַמָּא דְּלָא הֲוָה דָּחִיל מִגְּבוּרָאן עִלָּאִין דְּקוּדְשָׁא בְּרִיךְ הוּא, וַעֲמָלֵק לָא הֲוָה דָּחִיל, הֲדָא הוּא דִכְתִיב, וְלֹא יָרֵא אֱלהִים. לָא דָּחִיל לְמִקְרַב לְגַבָּךְ. וְעַל דָּא רֵאשִׁית גּוֹיִם.","(עמלק הוי קדמאה) דְּאָתוּ לְאַגָּחָא קְרָבָא בְּיִשְׂרָאֵל עֲמָלֵק הֲוָה. וּבְגִינֵי כַּךְ וְאַחֲרִיתוֹ עֲדֵי אוֹבֵד, דִּכְתִּיב כִּי מָחֹה אֶמְחֶה אֶת זֵכֶר עֲמָלֵק. וּכְתִיב, (דברים כ״ה:י״ט) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק, הֲדָא הוּא דִכְתִיב וְאַחֲרִיתוֹ עֲדֵי אוֹבֵד. עֲדֵי אָבְדוֹ מִבָּעֵי לֵיהּ. אֶלָּא עַד דְּיֵיתֵי קוּדְשָׁא בְּרִיךְ הוּא וְיֹאבַד לֵיהּ, (כלומר עד דקודשא בריך הוא יהא אובד ליה) דִּכְתִּיב כִּי מָחֹה אֶמְחֶה וְגוֹ'. אָמַר ר' אֶלְעָזָר, תָּא חֲזֵי, אַף עַל גַּב דְּהַצּוּר תָמִים פָּעֳלוֹ, וְעָבִיד עִמְּהוֹן חֶסֶד לְאַפָּקָא לוֹן מַיָּא, לָא שָׁבַק דִּידֵיהּ, דְּהָא כְּתִיב וַיָּבֹא עֲמָלֵק.","ר' אַבָּא פָּתַח וְאָמַר, (קהלת ה׳:י״ב) יֵשׁ רָעָה חוֹלָה רָאִיתִי תַּחַת הַשָּׁמֶשׁ. כַּמָּה בְּנֵי נָשָׁא אֲטִימִין לִבָּא, בְּגִין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. יֵשׁ רָעָה חוֹלָה, וְכִי יֵשׁ רָעָה דְּהִיא חוֹלָה, וְיֵשׁ רָעָה דְּלָאו הִיא חוֹלָה. אֶלָּא וַדַּאי יֵשׁ רָעָה חוֹלָה, דְּתָנֵינָן, מִסִּטְרָא דִּשְׂמָאלָא, נַפְקֵי כַּמָּה גַּרְדִּינִי נִימּוּסִין, דְּבַקְעָן בַּאֲוִירָא.","וְכַד בַּעְיָין לְמֵיפַק, אַזְלִין וְאִשְׁתַּאֲבִין בְּנוּקְבָא דִּתְהוֹמָא רַבָּה, לְבָתַר נָפְקִין וּמִתְחַבְּרָן כַּחֲדָא, וּבְקָעִין אֲוִירִין, וְשָׁאטִין בְּעָלְמָא, וּמִתְקָרְבִין לְגַבַּיְיהוּ דִּבְנֵי נָשָׁא, וְכָל חַד אִקְרֵי רָעָה, כְּמָה דְאַתְּ אָמֵר (תהילים צ״א:י׳) לא תְאוּנֶּה אֵלֶיךָ רָעָה. מַאי לא תְאוּנֶּה. בְּגִין דְּאַתְיָא בְּתַסְקוּפָא עַל בְּנִי נָשָׁא.","חוֹלָה אֲמַאי הִיא חוֹלָה. כַּד שַׁרְיָא הַאי עַל בְּנֵי נָשָׁא, עָבִיד לוֹן קַמְצָנִין מִמָּמוֹנֵיהוֹן, אַתְיָין גַּבָּאי צְדָקָה גַּבֵּיהּ, הִיא מָחָאת בִּידֵיהּ. אֲמַר לֵיהּ לֹא תִּיפּוּק מִדִּידָךְ. אַתְיָין מִסְכְּנֵי, הִיא מָחָאת בִּידֵיהּ. אָתֵי הוּא לְמֵיכַל מִמָּמוֹנֵיהּ, מָחָאת בִּידֵיהּ, בְּגִין לְנַטְרָא לֵיהּ לְאָחֳרָא. וּמִן יוֹמָא דְּשַׁרְיָא עָלֵיהּ דְּבַר נָשׁ, הִיא חוֹלָה, כְּהַאי שָׁכִיב מֵרַע דְּלָא אָכִיל וְלָא שְׁתֵּי. וְעַל דָּא הִיא רָעָה חוֹלָה.","וּשְׁלמֹה מַלְכָּא צָוַוח בְּחָכְמְתָא וְאָמַר, (קהלת ו׳:ב׳) אִישׁ אֲשֶׁר יִתֵּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ'. הַאי קְרָא, לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ, כְּתִיב אִישׁ אֲשֶׁר יִתֵּן לוֹ הָאֱלהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ', מַאי וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכוֹל מִמֶּנּוּ. אִי הָכִי, לָאו בִּרְשׁוּתֵיהּ הוּא דְּבַּר נָשׁ.","אֶלָּא, אִי כְּתִיב וְלֹא יַעַזְבֶנוּ הָאֱלהִים לֶאֱכוֹל מִמֶּנּוּ, הֲוֵינָא אָמַר הָכִי. אֶלָּא וְלא יַשְׁלִיטֶנּוּ, דִּבְגִין דְּהוּא הֵימְנֵיהּ לְהַהִיא רָעָה, וְאָחִיד בָּהּ. קוּדְשָׁא בְּרִיךְ הוּא לָא שַׁלְטֵיהּ עָלֵיהּ, לְאִתְבָּרָאָה תְּחוֹתֵיהּ, עַל דְּהוּא אִתְרְעֵי בָּהּ, וְאָחִיד בָּהּ.","וְכָל אָרְחוֹי כִּשְׁכִיב מֵרַע, דְּלָא אָכִיל וְלָא שְׁתֵי, וְלָא קָרִיב לְמָמוֹנֵיהּ, וְלָא אַפִּיק מִינֵּיהּ, וְנָטִיר לֵיהּ עַד דְּהוּא יִפּוּק מֵעָלְמָא, וְיֵיתֵי אַחֲרָא, וְיִטּוֹל לֵיהּ, דְּהוּא בְּעָלָיו.","וּשְׁלמֹה מַלְכָּא צָוַוח וְאָמַר, (קהלת ה׳:י״ב) עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. מַאן בְּעָלָיו. דָּא אַחֲרָא דְּיָרִית לֵיהּ. וְלָמָּה זָכָה הַאי אַחֲרָא לְמֶהֱוֵי בְּעָלָיו דְּהַהוּא עֻתְרָא. בְּגִין דְּהַאי הֵימִין לְהַהִיא רָעָה, וְאִתְּרָעֵי בָּה (הדא הוא דכתיב לרעתו בשביל ההוא רע) וְאִתְדָבַּק בָּה. בְּגִין כָּךְ, הַאי אַחֲרָא דְּלָא אִתְדַּבָּק בְּהַהִיא רָעָה, זָכָה (האי) לְמֶהֱוֵי בְּעָלָיו דְּהַהוּא עֻתְרָא הֲדָא הוּא דִכְתִיב לְרָעָתוֹ, כְּלוֹמַר בְּגִין רָעָתוֹ דְּהֲוָה מִתְדָּבַק בָּהּ, רָוַוח לֵיהּ הַאי."],[[0,"א\"ר אבא וכו':","אמר ר' אבא, כשמזדווגים יחד, לא יכלו בני העולם לעמוד בהם. ועל זה כתוב, לא תחרוש בשור וחמור יחדיו. יחדיו הוא בדיוק. ולמדנו. לא יתן אדם מקום למינים הרעים. כי במעשה האדם מתעורר מה שלא צריך. וכשמזדווגים יחד, לא היה אפשר לעמוד בהם. מבין הצד שלהם, ויצא מעצמותם קליפה אחת שנקרא כלב. וזה עז פנים יותר מכולם. ז\"ש ולכל בני ישראל לא יחרץ כלב לשונו. אמר הקב\"ה אתם אמרתם, היש ה' בקרבנו אם אין, הרי אני מוסר אתכם לכלב. מיד, ויבא עמלק."],[1,"ר' יהודה אמר וכו':","רי\"א, ראשית גוים עמלק ואחריתו עדי אובד, שואל, וכי ראשית גוים עמלק, והלא כמה לשונות ועמים ואומות היו בעולם מטרם שבא עמלק."],[2,"אלא כד נפקי וכו':","ומשיב, אלא, כשיצאו ישראל ממצרים, פחד ואימה של ישראל נפל על כל עמי העולם. ז\"ש, שמעו עמים ירגזון וגו'. ולא היה עם שלא היה ירא מגבורות עליונות של הקב\"ה, ועמלק לא היה ירא. ז\"ש ולא ירא אלקים. לא ירא לקרב אליך, ועל כן הוא ראשית גוים."],[3,"קדמאה דאתו לאגחא וכו':","הראשון שבא לעשות מלחמה בישראל היה עמלק. ומשום זה, ואחריתו עדי אובד. שכתוב, כי מחה אמחה את זכר עמלק. וכתוב, תמחה את זכר עמלק. ז\"ש ואחריתו עדי אובד. שואל, עדי אבדו, היה צריך לומר, ומשיב, אלא עד שיבא הקב\"ה ויאבד אותו. שכתוב, כי מחה אמחה וגו'. אר\"א, בוא וראה, אע\"פ שהצור תמים פעלו, ועשה עמהם חסד להוציא להם מים, לא עזב את שלו. שהרי כתוב, ויבא עמלק."],[4,"ר' אבא פתח וכו':","רא\"פ, ואמר יש רעה חולה ראיתי תחת השמש. כמה בני אדם הם אטומי הלב, משום שאינם עוסקים בתורה. \u0003יש רעה חולה,\u0004 שואל וכי יש רעה שהיא חולה ויש רעה שאינו חולה. ואומר, אלא ודאי יש רעה חולה, שלמדנו, מצד שמאל יוצאים כמה בעלי הדין הבוקעים באויר."],[5,"וכד בעיין למיפק וכו':","וכשרוצים לצאת, הולכים ונבלעים בנקב תהום הגדול, ואח\"כ יוצאים ומתחברים יחד ובוקעים אוירים, ומשוטטים בעולם, ומתקרבים אל בני אדם, וכל אחד נקרא רעה, כמש\"א, לא תאונה אליך רעה. משום שבאים בעלילה על בני אדם."],[5,"","פירוש. יש תהומא זוטא, והיא נאחזת במלכות דמדת הדין. ויש תהומא רבא, והיא נאחזת במלכות דמדת הרחמים הממותקת בבינה. והנה בעלי הדין הנ\"ל נמשכים ממלכות דמדת הדין, ומקורם בתהומא זוטא, אלא שרוצים להאחז בנשמות הבאים ממלכות הממותקת בבינה, ע\"כ הם נבלעים תחילה ונשאבים בתהומא רבא."],[5,"","וז\"ש \u0003וכד בעיין למיפק,\u0004 כשרוצים לצאת ולהזיק, \u0003אזלין ואשתאבין בנוקבא דתהומא רבא,\u0004 כדי שיכלו להזיק הנשמות הבאים ממלכות הממותקת, \u0003ובקעין אוירין ושאטין בעלמא,\u0004 היינו שמכניסים \u0003י'\u0004 באור של הנשמות ונעשה מן אור אויר (כנ\"ל ב\"ב דף צ\"ח ד\"ה פירוש ע\"ש) ומדרגת הנשמה נבקעת, שבינה ותו\"מ שלה נופלים ממנו כמ\"ש שם. וז\"ש, \u0003וכל חד אקרי רעה וגו' בגין דאתיין בתסקופא על בני נשא,\u0004 כי מצד שורת הדין אינם יכולים להזיק רק הנשמות הנמשכות ממלכות דמדת הדין, אלא מחמת שנשאבו בנוקבא דתהומא רבא, מזיקים גם לנשמות דמלכות הממותקת שזהו עלילה בעלמא."],[6,"חולה, אמאי היא וכו':","שואל, רעה חולה, למה היא חולה. ומשיב, כשהיא שורה על בני אדם עושה אותם קמצנים מכספם. באים גבאי צדקה אליו, היא מוחה בידו, אומרת לו, אל תוציא כלום משלך. באים עניים, היא מוחה בידו, בא לאכול מכספו, היא מוחה בידו, כדי לשמור הכסף לאחר. ומיום שהיא שורה על האדם, היא חולה כמו שוכב מחמת חליו, שאינו אוכל ואינו שותה. וע\"כ היא רעה חולה."],[7,"ושלמה מלכא צווח וכו':","ושלמה המלך, צעק בחכמה, ואמר, איש אשר יתן לו האלקים עושר ונכסים וכבוד וגו'. מקרא זה, אין ראשו סופו ואין סופו ראשו, שכתוב איש אשר יתן לו האלקים עושר וגו', א\"כ מהו ולא ישליטנו האלקים לאכול ממנו. א\"כ אינו ברשותו של אדם ולא נתן לו האלקים כלום."],[8,"אלא אי כתיב וכו':","ומשיב, אלא אם היה כתוב, ולא יעזבנו האלקים לאכול ממנו, הייתי אומר כך, שלא נתן לו כלום, אלא כתוב, ולא ישליטנו, שהיא משום שהאמין ל \u0003רעה\u0004 ההיא ונאחז בה. א\"כ הוא עצמו גרם לו זה, הקב\"ה לא השליט אותה, שהאדם יהיה נברא תחת שליטתה, אלא שהוא עצמו רצה בה ואחז בה."],[9,"וכל ארחוי כשכיב מרע וכו':","וכל דרכיו הוא כשוכב מחמת חליו, שאינו אוכל, ואינו שותה, אינו קרב לכספו, ואינו מוציא ממנו, ושומר אותו, עד שנפטר מן העולם, ובא אחר ולוקח אותו שהוא בעליו."],[10,"ושלמה מלכא וכו':","ושלמה המלך צעק ואמר, עשר שמור לבעליו לרעתו. מי הוא בעליו. הוא האחר שירש אותו. ולמה זכה האחר להיות בעליו של אותו עושר. הוא משום שזה האמין ל \u0003רעה\u0004 הזו ורצה בה, והתדבק בה. משום זה האחר שלא התדבק ברעה הזו, זכה להיות בעליו של אותו עושר. ז\"ש, \u0003לרעתו,\u0004 כלומר, משום רעתו שהתדבק בה, הרויח אותו האחר."]],[[0,"","אָמַר רַבִּי אַבָּא, כְּשֶׁהֵם מִזְדַּוְּגִים כְּאֶחָד, לֹא יְכוֹלִים בְּנֵי הָעוֹלָם לַעֲמֹד בָּהֶם, וְלָכֵן כָּתוּב לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו. יַחְדָּו דַּוְקָא. וְשָׁנִינוּ, לֹא יִתֵּן אָדָם מָקוֹם לְמִינִים רָעִים, שֶׁהֲרֵי בְּמַעֲשֵׂה הָאָדָם (למטה) מִתְעוֹרֵר מַה שֶּׁלֹּא צָרִיךְ, וּכְשֶׁמִּזְדַּוְּגִים כְּאֶחָד, (לא יכולים לעמד בהם. מבין הצד שלהם יוצאת) מֵהַתַּקִּיפוּת שֶׁלָּהֶם קְלִפָּה שֶׁנִּקְרֵאת כֶּלֶב, וְזוֹ הַחֲצוּפָה מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב (שמות יא) וּלְכָל בְּנֵי יִשְׂרָאֵל לֹא יֶחֱרַץ כֶּלֶב לְשׁוֹנוֹ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתֶּם אֲמַרְתֶּם הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן - הֲרֵי אֲנִי מוֹסֵר אֶתְכֶם לַכֶּלֶב. מִיָּד - וַיָּבֹא עֲמָלֵק."],[1,"","רַבִּי יְהוּדָה אָמַר, (במדברכב) רֵאשִׁית גּוֹיִם עֲמָלֵק וְאַחֲרִיתוֹ עֲדֵי אֹבֵד. וְכִי רֵאשִׁית גּוֹיִם עֲמָלֵק, וַהֲלֹא כַּמָּה לְשׁוֹנוֹת וְעַמִּים וְאֻמּוֹת הָיוּ בָּעוֹלָם עַד שֶׁלֹּא בָא עֲמָלֵק?!"],[2,"","אֶלָּא, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, פַּחַד וְאֵימָה נָפְלוּ עַל כָּל הָעַמִּים שֶׁל הָעוֹלָם מִיִּשְׂרָאֵל, זֶהוּ שֶׁכָּתוּב שָׁמְעוּ עַמִּים יִרְגָּזוּן חִיל אָחַז יֹשְׁבֵי פְּלָשֶׁת. וְלֹא הָיָה עַם שֶׁלֹּא הָיָה פּוֹחֵד מֵהַגְּבוּרוֹת הָעֶלְיוֹנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וַעֲמָלֵק לֹא הָיָה פּוֹחֵד. זֶהוּ שֶׁכָּתוּב וְלֹא יָרֵא אֱלֹהִים. לֹא פָחַד לִקְרַב אֵלֶיךְ. וְלָכֵן רֵאשִׁית גּוֹיִם."],[3,"","(עמלק היו הראשונים) שֶׁבָּאוּ לַעֲרֹךְ קְרָב בְּיִשְׂרָאֵל הָיָה עֲמָלֵק, וְלָכֵן וְאַחֲרִיתוֹ עֲדֵי אֹבֵד, שֶׁכָּתוּב כִּי מָחֹה אֶמְחֶה אֶת זֵכֶר עֲמָלֵק. וְכָתוּב תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. זֶהוּ שֶׁכָּתוּב וְאַחֲרִיתוֹ עֲדֵי אֹבֵד. עֲדֵי אָבְדוֹ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא עַד שֶׁיָּבא הַקָּדוֹשׁ בָּרוּךְ הוּא וִיאַבֵּד אוֹתוֹ, (כלומר, עד שהקדוש ברוך הוא יאבד אותו) שֶׁכָּתוּבּ כִּי מָחֹה אֶמְחֶה וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, בֹּא רְאֵה, אַף עַל גַּב שֶׁהַצּוּר תָּמִים פָּעֳלוֹ וְעָשָׂה עִמָּהֶם חֶסֶד לְהוֹצִיא לָהֶם מַיִם, לֹא עָזַב אֶת שֶׁלּוֹ, שֶׁהֲרֵי כָּתוּב וַיָּבֹא עֲמָלֵק."],[4,"","רַבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ו) יֵשׁ רָעָה חוֹלָה רָאִיתִי תַּחַת הַשָּׁמֶשׁ. כַּמָּה בְּנֵי הָאָדָם אֲטוּמֵי לֵב, מִשּׁוּם שֶׁלֹּא מִשְׁתַּדְּלִים בַּתּוֹרָה. יֵשׁ רָעָה חוֹלָה - וְכִי יֵשׁ רָעָה שֶׁהִיא חוֹלָה וְיֵשׁ רָעָה שֶׁאֵינָהּ חוֹלָה? אֶלָּ וַדַּאי שֶׁיֵּשׁ רָעָה חוֹלָה, שֶׁשָּׁנִינוּ, מִצַּד הַשְּׂמֹאל יוֹצְאִים כַּמָּה בַּעֲלֵי דִין הַבּוֹקְעִים בָּאֲוִיר."],[5,"","וּכְשֶׁרוֹצִים לָצֵאת, הוֹלְכִים וְנִשְׁאָבִים בְּנֶקֶב תְּהוֹם רַבָּה. אַחַר כָּךְ יוֹצְאִים וּמִתְחַבְּרִים כְּאֶחָד, וּבוֹקְעִים אֲוִירִים וּמְשׁוֹטְטִים בָּעוֹלָם וּמִתְקָרְבִים לִבְנֵי אָדָם, וְכָל אֶחָד נִקְרָא רָעָה, כְּמוֹ שֶׁנֶּאֱמַר (תהליםצא) לֹא תְאֻנֶּה אֵלֶיךְ רָעָה. מַה זֶּה לֹא תְאֻנֶּה? מִשּׁוּם שֶׁבָּאִים בְּתַחְבּוּלוֹת עַל בְּנֵי אָדָם."],[6,"","חוֹלָה - לָמָּה הִיא חוֹלָה? כְּשֶׁזּוֹ שׁוֹרָה עַל בְּנֵי אָדָם, עוֹשָׂה אוֹתָם קַמְּצָנִים מִמָּמוֹנָם. בָּאִים גַּבָּאֵי צְדָקָה אֵלָיו - הִיא מוֹחָה בְּיָדוֹ וְאוֹמֶרֶת לוֹ אַל תּוֹצִיא מִשֶּׁלְּךְ. בָּאִים הָעֲנִיִּים - הִיא מוֹחָה בְּיָדוֹ. בָּא הוּא לֶאֱכֹל מִמָּמוֹנוֹ - הִיא מוֹחָה בְּיָדוֹ, כְּדֵי לִשְׁמֹר אוֹתוֹ לְאַחֵר. וּמִיּוֹם שֶׁשְּׁרוּיָה עַל הָאָדָם, הִיא חוֹלָה, כְּמוֹ הַגּוֹסֵס הַזֶּה שֶׁאֵינוֹ אוֹכֵל וְאֵינוֹ שׁוֹתֶה, וְלָכֵן הִיא רָעָה חוֹלָה."],[7,"","וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ בְּחָכְמָה וְאוֹמֵר, (קהלת ו) אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ'. הַפָּסוּק הַזֶּה, אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ. כָּתוּב אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְכָבוֹד וְגוֹ'. מַה זֶּה וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ? אִם כָּךְ, הוּא אֵינוֹ בִּרְשׁוּת הָאָדָם?"],[8,"","אֶלָּא אִם כָּתוּב וְלֹא יַעַזְבֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ - הָיִינוּ אוֹמְרִים כָּךְ. אֶלָּא (כתוב) וְלֹא יַשְׁלִיטֶנּוּ, שֶׁבִּגְלַל שֶׁהֶאֱמִין לְאוֹתָהּ רָעָה וְאָחַז בָּהּ, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הִשְׁלִיטוֹ עָלֶיהָ לְשָׁבְרָהּ תַּחְתָּיו עַל שֶׁהוּא רָצָה בָּהּ וְאָחַז אוֹתָהּ."],[9,"","וְכָל דְּרָכָיו כְּמוֹ גּוֹסֵס, שֶׁלֹּא אוֹכֵל וְלֹא שׁוֹתֶה וְלֹא מִתְקָרֵב לְמָמוֹנוֹ וְלֹא מוֹצִיא מִמֶּנּוּ, וְשׁוֹמֵר אוֹתוֹ עַד אוֹתוֹ יוֹם שֶׁיֵּצֵא מִן הָעוֹלָם, וְיָבא אַחֵר וְיִטֹּל אוֹתוֹ, שֶׁהוּא בְּעָלָיו."],[10,"","וּשְׁלֹמֹה הַמֶּלֶךְ צוֹוֵחַ וְאוֹמֵר, (שם ה) עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ. מִי זֶה בְּעָלָיו? זֶה הָאַחֵר שֶׁיּוֹרֵשׁ אוֹתוֹ. וְלָמָּה זֶה זָכָה לִהְיוֹת בְּעָלָיו שֶׁל אוֹתוֹ הָעֹשֶׁר? מִשּׁוּם שֶׁזֶּה הֶאֱמִין לְאוֹתָהּ רָעָה וְהִתְרַצָּה בָּהּ (זהו שכתוב לרעתו, בשביל אותה רעה) וְדָבַק בָּהּ, וְלָכֵן הָאַחֵר הַזֶּה שֶׁלֹּא נִדְבַּק בְּאוֹתָהּ רָעָה, זָכָה (זה) לִהְיוֹת הַבְּעָלִים שֶׁל אוֹתוֹ הָעֹשֶׁר. זֶהוּ שֶׁכָּתוּב לְרָעָתוֹ, כְּלוֹמַר, מִשּׁוּם רָעָתוֹ שֶׁהָיָה נִדְבָּק בָּהּ, הִרְוִיחַ לוֹ זֶה."]]],[["דָּבָר אַחֵר יֵשׁ רָעָה חוֹלָה, הַאי מַאן דְּיָתִיב בְּחוּלָקָא טָבָא, בְּבֵית אֲבוֹי, וְהוּא אָזִיל לָקֳבֵל אֲבוֹי, בְּתַסְקוּפֵי מִלִּין, הָא אִתְדְּבַק בְּהַהוּא רָעָה חוֹלָה, כְּבַר נָשׁ שָׁכִיב מֵרַע דְּכָל אָרְחוֹי בְּתַסְקוּפָא, דָּא בְּעֵינָא, וְדָא לָא בְּעֵינָא, וּבְגִין הַאי עוּתְרָא אִתְדָּבַּק בַּר נָשׁ בְּרָעָה חוֹלָה, וְאִתְעֲנָשׁ בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, וְדָא הוּא עוֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ.","כַּךָ יִשְׂרָאֵל, קוּדְשָׁא בְּרִיךְ הוּא נָטִיל לוֹן עַל גַּדְפֵּי נִשְׁרִין, אַסְחַר לוֹן בַּעֲנָנִי יְקָרָא, שְׁכִינְתֵּיהּ נָטִיל קָמַיְיהוּ, נָחַת לוֹן מָנָא לְמֵיכַל, אַפִּיק לוֹן מַיָּיא מְתוּקִין, וְאִינּוּן הֲווֹ אַזְלִין עִמֵּיהּ בְּתַסְקוּפִין. מִיַּד וַיָּבֹא עֲמָלֵק.","(שמות י״ז:ח׳) וַיָּבֹא עֲמָלֵק, אָמַר רִבִּי שִׁמְעוֹן, רָזָא דְּחָכְמְתָא הָכָא, מִגִּזְרַת דִּינָא קַשְׁיָא, קָא אַתְיָא קְרָבָא דָּא. וּקְרָבָא דָּא אִשְׁתְּכַח לְעֵילָּא וְתַתָּא. וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, דְּלָא אִית בָּהּ רָזִין עִלָּאִין דְּחָכְמְתָא, דְּמִתְקַשְּׁרִין בִּשְׁמָא קַדִּישָׁא. כִּבְיָכוֹל, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כַּד יִשְׂרָאֵל אִינּוּן זַכָּאִין לְתַתָּא, אִתְגַּבָּר חֵילָא דִּילִי עַל כֹּלָּא. וְכַד לָא אִשְׁתְּכָחוּ זַכָּאִין, כִּבְיָכוֹל, מַתִּישִׁין חֵילָא דִּלְעֵילָּא, וְאִתְגַּבַּר חֵילָא דְּדִינָא קַשְׁיָא.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּחָבוּ יִשְׂרָאֵל לְתַתָּא, מַה כְּתִיב, וַיָּבֹא עֲמָלֵק וַיִּלָּחֶם עִם יִשְׂרָאֵל, אָתָא לְקַטְרְגָא דִּינָא בְּרַחֲמֵי. דְּכֹלָּא אִשְׁתְּכַח לְעֵילָּא וְתַתָּא. בִּרְפִידִים: בְּרָפוּי יָדַיִם, דְּרָפוּ יְדֵיהוֹן מֵאוֹרַיְיתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאוֹקִימְנָא. אָמַר ר' יְהוּדָה, תְּרֵי זִמְנֵי אַגָּח קְרָבָא עֲמָלֵק בְּיִשְׂרָאֵל, חַד הָכָא. וְחַד דִּכְתִּיב, (במדבר י״ד:מ״ה) וַיֵּרֶד הָעֲמָלֵקֵי וְהַכְּנַעֲנִי וְגוֹ'.","אָמַר ר' שִׁמְעוֹן, לְעֵילָּא וְתַתָּא. קִטְרוּגָא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה, לְעֵילָּא, כְּמָה דְּאִתְּמַר. לְתַתָּא בְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה, דַּהֲווֹ נַסְבֵּי לְגַבְרֵי, וְגַזְרֵי לוֹן עָרְלָתָא (ס\"א אתא) דִּרְשִׁימָא קַדִּישָׁא, וְנַטְלֵי לְהוּ וְאַרְמוּ לוֹן לְעֵילָּא, וְאַמְרֵי טוֹל לָךְ מַה דְּאִתְרְעִית. וְעַל כָּל פָּנִים דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה (כל קובלנא כלא) (ס\"א קבלא) כֹּלָּא.","(שמות י״ז:ט׳) וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בָּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק. וְכִי מַה חָמָא מֹשֶׁה, דְּסָלִיק גַּרְמֵיהּ, מֵהַאי קְרָבָא קַדְמָאָה דְּקוּדְשָׁא בְּרִיךְ הוּא פָּקִיד. אֶלָּא מֹשֶׁה זַכָּאָה חוּלָקֵיהּ, דְּאִסְתַּכַּל וְיָדַע עִקָרָא דְּמִלָּה. אָמַר מֹשֶׁה, אֲנָא אַזְמִין גַּרְמִי לְהַהוּא קְרָבָא דִּלְעֵילָּא, וְאַנְתְּ יְהוֹשֻׁעַ זַמִּין גַּרְמָךְ לְקָרְבָא דִּלְתַתָּא.","וְהַיְינוּ דִּכְתִּיב, וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל: יִשְׂרָאֵל דִּלְעֵילָּא. וּבְגִין כַּךְ סָלִיק מֹשֶׁה גַּרְמֵיהּ מִקְּרָבָא דִּלְתַתָּא, בְּגִין לְאִזְדָּרְזָא בִּקְרָבָא דִּלְעֵילָּא, וְיִתְנְצַח עַל יְדוֹי.","אָמַר ר' שִׁמְעוֹן, וְכִי קַלָהּ הִיא בְּעֵינֶיךָ, קְרָבָא דָּא דַּעֲמָלֵק. תָּא חֲזֵי, מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, עַד הַהוּא זִמְנָא, וּמֵהַהוּא זִמְנָא, עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא, וַאֲפִילּוּ בְּיוֹמוֹי דְּגוֹג וּמָגוֹג, לָא יִשְׁתְּכַּח כְּוָותֵיהּ. לָאו בְּגִין חַיָּילִין תַּקִּיפִין וְסַגִּיאִין, אֶלָּא בְּגִין דִּבְכָל סִטְרִין דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה.","וַיֹּאמֶר מֹשֶׁה אַל יְהוֹשֻׁעַ, אֲמַאי לִיהוֹשֻׁעַ, וְלָא לְאָחֳרָא, וְהָא בְּהַהוּא זִמְנָא רַבְיָא הֲוָה, דִּכְתִּיב, (שמות ל״ג:י״א) וִיהוֹשֻׁעַ בִּן נוּן נַעַר, וְכַמָּה הֲווֹ בְּיִשְׂרָאֵל תַּקִּיפִין מִנֵּיהּ. אֶלָּא מֹשֶׁה בְּחָכְמְתָא אִסְתָּכַּל וְיָדַע. מַאי חָמָא. חָמָא לסמאל דְּהֲוָה נָחִית מִסִּטְרָא דִּלְעֵילָּא, לְסַיְּיעָא לַעֲמָלֵק לְתַתָּא. אָמַר מֹשֶׁה, וַדַּאי קְרָבָא הָכָא תַּקִּיפָא אִתְחָזִיִ.","יְהוֹשֻׁעַ בְּהַהוּא זִמְנָא בְּדַרְגָּא עִלָּאָה יַתִּיר אִשְׁתְּכַח. אִי תֵּימָא דִּבְשְׁכִינְתָּא אִשְׁתְּכַח בְּהַהוּא זִמְנָא לָאו הָכִי, דְּהָא בְּמֹשֶׁה אִתְנְסִיבַת וְאִתְאַחֲדַת, אִשְׁתְּכַח יְהוֹשֻׁעַ דְּאִתְאַחֲד לְתַתָּא מִינָּהּ. וּבַמֶּה. אָמַר ר' שִׁמְעוֹן, בְּהַהוּא אֲתָר, דְּאִתְקְרֵי נַעַ\"ר.","וְהַיְינוּ דְּאָמַר רִבִּי יְהוּדָה, מַאי דִּכְתִּיב, (ישעיהו ל״ג:כ׳) עֵינֶיךָ תִּרְאֶינָה יְרוּשָׁלַ ם נָוְה שַׁאֲנָן אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדוֹתָיו לָנֶצַח. יְרוּשָׁלַ ם: יְרוּשָׁלַ ם דִּלְעֵילָּא, דְּאִקְרֵי אֹהֶל בַּל יִצְעָן, דְּלָא יִשְׁתְּכַּח יַתִּיר לְמֵהַךְ בְּגָלוּתָא, וְדָא הוּא רָזָא דִּכְתִּיב, וִיהוֹשֻׁעַ בִּן נוּן נַעַר. נַעַר וַדַּאי. לא יָמִישׁ מִתּוֹךְ הָאֹהֶל, הַהוּא דְּאִקְרֵי אֹהֶל בַּל יִצְעָן. מְלַמֵּד דִּבְכָל יוֹמָא וְיוֹמָא, הֲוָה יָנִיק מִשְׁכִינְתָּא, כְּמָה דְּהַהוּא נַעַר דִּלְעֵילָּא, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל, וְיָנִיק מִנֵּיהּ תָּדִירָא. כַּךְ הַאי נַעַר דִּלְתַתָּא לא יָמִישׁ מִתּוֹךְ הָאֹהֶל, וְיָנִיק מִנָּהּ תָּדִירָא."],[[0,"ד\"א יש רעה חולה וכו':","הוא, מי שיושב בחלק טוב בבית אביו, והוא הולך כנגד אביו בעלילות דברים, הוא מתדבק ברעה חולה הזו, כאדם השוכב מחמת חליו, שכל דרכיו בעלילה, שאומר זה אני רוצה וזה איני רוצה. ומשום עושר הזה, התדבק האדם ברעה חולה, ונענש בעולם הזה, ובעולם הבא. וזהו עושר שמור לבעליו לרעתו."],[1,"כך ישראל וכו':","כך ישראל, הקב\"ה לקחם על כנפי נשרים והקיף אותם בענני כבוד, השכינה נסעה לפניהם, הוריד להם את המן לאכול, הוציא להם מים מתוקים, והם הלכו עמו בעלילה. מיד ויבא עמלק."],[2,"ויבא עמלק וכו':","אמר ר' שמעון סוד החכמה כאן. מגזרת דין הקשה באה מלחמה זו, ומלחמה זו נמצא למעלה ולמטה. ואין לך דבר בתורה, שלא יהיה בו סודות עליונים של החכמה, שמתקשרים בשם הקדוש. כביכול, אמר הקב\"ה, כשישראל הם צדיקים למטה, מתגבר כחי על כל, וכשאינם נמצאים צדיקים, כביכול, מתישים כח שלמעלה, ומתגבר הכח של דין הקשה."],[3,"ת\"ח בשעתא וכו':","בוא וראה, בשעה שחטאו ישראל למטה, מה כתוב, ויבא עמלק וילחם עם ישראל. בא לקטרג דין על רחמים. שהוא המלחמה שלו למעלה. כי הכל נמצא למעלה ולמטה, \u0003ברפידים,\u0004 פירושו ברפיון ידים, שרפו ידיהם מתורת הקב\"ה, כמו שהעמדנו א\"ר יהודה בשתי פעמים עשה עמלק מלחמה בישראל, אחד כאן, ואחד, שכתוב, וירד העמלקי והכנעני וגו'."],[4,"אמר ר' שמעון וכו':","אמר ר\"ש למעלה ולמטה, היתה מלחמת עמלק, למעלה, היה הקטרוג על הקב\"ה, כמו שלמדנו. למטה, ג\"כ היה בהקב\"ה, שהיו לוקחים אנשים וחותכים להם הערלה של הרושם הקדוש, ולקחו אותם וזרקו למעלה, ואמרו, קח לך מה שרצית ועל כל פנים כלפי הקב\"ה היתה כל המלחמה."],[5,"ויאמר משה אל יהושע וגו':","שואל, וכי מה ראה משה, שסילק את עצמו ממלחמה הראשונה הזו של הקב\"ה. ומשיב, אלא, משה, אשרי חלקו, שהסתכל וידע שורש הדבר. אמר משה, אני אזמין את עצמי למלחמה זו שלמעלה, ואתה יהושע, זמן אותך למלחמה שלמטה."],[6,"והיינו דכתיב וכו':","והיינו שכתוב, והיה כאשר ירים משה ידו וגבר ישראל. היינו ישראל של מעלה, שהוא ז\"א, ומשום זה, סילק משה את עצמו ממלחמה שלמטה, כדי להזדרז במלחמה שלמעלה, ותהיה מנוצחת על ידו."],[7,"אמר ר' שמעון וכו':","אר\"ש, וכי קלה היא בעיניך מלחמה זו של עמלק, בוא וראה, מיום שנברא העולם עד זמן ההוא, ומזמן ההוא עד שיבא מלך המשיח, ואפילו בימי גוג ומגוג, לא תהיה נמצא כמוה. ולא משום שהיו חילים גבורים ומרובים, אלא משום שבכל הצדדים של הקב\"ה היתה."],[8,"ויאמר משה אל יהושע וכו':","שואל, למה ליהושע ולא לאחר. והרי בזמן ההוא היה נער. שכתוב, ויהושע בן נון נער, וכמה היו בישראל חזקים ממנו. ומשיב, אלא משה הסתכל בחכמה וידע. מה ראה. ראה את סמאל שהיה יורד בצד של מעלה לעזור את עמלק למטה, אמר משה, ודאי מלחמה חזקה, נראה כאן."],[9,"יהושע בההוא זמנא וכו':","יהושע בזמן ההוא, היה נמצא במדרגה עליונה ביותר. אם תאמר שנמצא בהשכינה בזמן ההוא. אינו כן, כי במשה נלקחה והתאחדה, נמצא שיהושע התאחד למטה מן השכינה. ובמה. א\"ר שמעון, במקום ההוא שנקרא נער. שהוא מטטרון."],[10,"והיינו דא\"ר יהודה וכו':","והיינו שאמר ר\"י, מה שכתוב, עיניך תראינה ירושלים נוה שאנן אהל בל יצען וגו'. ירושלים, היינו ירושלים של מעלה, שנקרא אהל בל יצען, שפירושו, שלא תמצא יותר ללכת בגלות. וזה הוא סוד, ויהושע בן נון נער, נער ודאי, להיותו דבוק בנער העליון, מטטרון, לא ימיש מתוך האהל, היינו מההוא שנקרא אהל בל יצען שהוא השכינה, מלמד, שבכל יום ויום, היה יונק מן השכינה, כמו שנער ההוא העליון, לא ימיש מתוך האהל, ויונק ממנה תמיד. כך ההוא נער שלמטה, שהוא יהושע, לא ימיש מתוך האהל ויונק ממנו תמיד."]],[[0,"","דָּבָר אַחֵר יֵשׁ רָעָה חוֹלָה - זֶה מִי שֶׁיּוֹשֵׁב בְּחֵלֶק טוֹב, בְּבֵית אָבִיו, וְהוּא הוֹלֵךְ כְּנֶגֶד אָבִיו בַּעֲלִילוֹת דְּבָרִים, זֶה נִדְבָּק בְּאוֹתָהּ רָעָה חוֹלָה, כְּאָדָם גּוֹסֵס, שֶׁכָּל דְּרָכָיו בַּעֲלִילוֹת: זֶה אֲנִי רוֹצֶה, וְאֶת זֶה אֵינִי רוֹצֶה. וּמִשּׁוּם הָעֹשֶׁר הַזֶּה נִדְבָּק הָאָדָם בְּרָעָה חוֹלָה, וְנֶעֱנָשׁ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְזֶהוּ עֹשֶׁר שָׁמוּר לִבְעָלָיו לְרָעָתוֹ."],[1,"","כָּךָ יִשְׂרָאֵל. הַקָּדוֹשׁ בָּרוּךְ הוּא נָטַל אוֹתָם עַל כַּנְפֵי נְשָׁרִים, הִקִּיפָם בְּעַנְנֵי כָבוֹד, נָסְעָה שְׁכִינָתוֹ לִפְנֵיהֶם, הוֹרִיד לָהֶם מָן לֶאֱכֹל, הוֹצִיא לָהֶם מַיִם מְתוּקִים, וְהֵם הָיוּ הוֹלְכִים עִמּוֹ בַּעֲלִילוֹת. מִיָּד - וַיָּבא עֲמָלֵק."],[2,"","וַיָּבֹא עֲמָלֵק - אָמַר רַבִּי שִׁמְעוֹן, סוֹד הַחָכְמָה כָּאן. מִגְּזֵרַת הַדִּין הַקָּשֶׁה בָּא הַקְּרָב הַזֶּה. וְהַקְּרָב הַזֶּה נִמְצָא לְמַעְלָה וּלְמַטָּה. וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁאֵין בּוֹ סוֹדוֹת עֶלְיוֹנִים שֶׁל חָכְמָה שֶׁנִּקְשָׁרִים לַשֵּׁם הַקָּדוֹשׁ. כִּבְיָכוֹל אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: כְּשֶׁיִּשְׂרָאֵל צַדִּיקִים לְמַטָּה, מִתְגַּבֵּר הַכֹּחַ שֶׁלִּי עַל הַכֹּל. וּכְשֶׁלֹּא נִמְצָאִים צַדִּיקִים, כִּבְיָכוֹל מַתִּישִׁים הַכֹּחַ שֶׁלְּמַעְלָה, וּמִתְגַּבֵּר הַכֹּחַ שֶׁל הַדִּין הַקָּשֶׁה."],[3,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁחָטְאוּ יִשְׂרָאֵל לְמַטָּה, מַה כָּתוּב? וַיָּבֹא עֲמָלֵק וַיִּלָּחֵם עִם יִשְׂרָאֵל. בָּא לְקַטְרֵג הַדִּין נֶגֶד הָרַחֲמִים, שֶׁהַכֹּל נִמְצָא לְמַעְלָה וּלְמַטָּה. בִּרְפִידִם - בְּרִפּוּי יָדַיִם, שֶׁרָפוּ יְדֵיהֶם מִתּוֹרַת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּפִי שֶׁבֵּאַרְנוּ. אָמַר רַבִּי יְהוּדָה, פַּעֲמַיִם נִלְחַם עֲמָלֵק בְּיִשְׂרָאֵל; פַּעַם אַחַת כָּאן, וְאַחַת שֶׁכָּתוּב (במדבר יד) וַיֵּרֶד הָעֲמָלֵקִי וְהַכְּנַעֲנִי וְגוֹ'."],[4,"","אָמַר רַבִּי שִׁמְעוֹן, לְמַעְלָה וּלְמַטָּה הָיָה קִטְרוּג שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה - כְּמוֹ שֶׁנִּתְבָּאֵר. לְמַטָּה הָיָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, שֶׁהָיוּ לוֹקְחִים אֲנָשִׁים וְגוֹזְרִים אֶת הָעָרְלָה (האות) שֶׁל הָרֹשֶׁם הַקָּדוֹשׁ, וְלוֹקְחִים אוֹתָם וְזוֹרְקִים אוֹתָם לְמַעְלָה וְאוֹמְרִים: קַח לְךְ מַה שֶּׁרָצִיתָ! וְעַל כָּל פָּנִים הַכֹּל הָיָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (הקבלנה)."],[5,"","וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בְּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק. וְכִי מָה רָאָה מֹשֶׁה שֶׁסִּלֵּק עַצְמוֹ מֵהַקְּרָב הָרִאשׁוֹן שֶׁצִּוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא? אֶלָּא מֹשֶׁה, אַשְׁרֵי חֶלְקוֹ, שֶׁהִתְבּוֹנֵן וְיָדַע אֶת עִקַּר הַדָּבָר. אָמַר מֹשֶׁה, אֲנִי אַזְמִין עַצְמִי לְאוֹתוֹ קְרָב שֶׁלְּמַעְלָה, וְאַתָּה יְהוֹשֻׁעַ הַזְמֵן עַצְמְךְ לַקְּרָב שֶׁלְּמַטָּה."],[6,"","וְהַיְנוּ מַה שֶּׁכָּתוּב, וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. יִשְׂרָאֵל שֶׁלְּמַעְלָה. וְלָכֵן סִלֵּק מֹשֶׁה אֶת עַצְמוֹ מֵהַקְּרָב שֶׁלְּמַטָּה, כְּדֵי לְהִזְדַּוֵּג בַּקְּרָב שֶׁלְּמַעְלָה וְיִהְיֶה נִצָּחוֹן עַל יָדוֹ."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, וְכִי קַל הוּא בְּעֵינֶיךְ הַקְּרָב הַזֶּה שֶׁל עֲמָלֵק? בּא רְאֵה, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם עַד לְאוֹתוֹ זְמַן, וּמֵאוֹתוֹ זְמַן עַד שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ, וַאֲפִלּוּ בִּימֵי גוֹג וּמָגוֹג, לֹא יִמָּצֵא כָּמוֹהוּ. לֹא בִּשְׁבִיל הַחֲיָלוֹת הַחֲזָקִים וְהָרַבִּים, אֶלָּא מִשּׁוּם שֶׁבְּכָל הַצְּדָדִים שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה."],[8,"","וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ, לָמָּה לִיהוֹשֻׁעַ וְלֹא לְאַחֵר, וַהֲרֵי בְּאוֹתוֹ זְמַן הָיָה נַעַר, שֶׁכָּתוּב (שמות לג) וִיהוֹשֻׁעַ בִּן נוּן נַעַר, וְהָיוּ בְיִשְׂרָאֵל חֲזָקִים מִמֶּנּוּ? אֶלָּא שֶׁמֹּשֶׁה הִתְבּוֹנֵן בַּחָכְמָה וְיָדַע. מָה הוּא רָאָה? רָאָה אֶת סמא\"ל שֶׁהָיָה יוֹרֵד מֵהַצַּד שֶׁלְּמַעְלָה לְסַיֵּעַ לַעֲמָלֵק שֶׁלְּמַטָּה. אָמַר מֹשֶׁה, וַדַּאי נִרְאֶה כָּאן קְרָב קָשֶׁה."],[9,"","יְהוֹשֻׁעַ בְּאוֹתוֹ זְמַן נִמְצָא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה. אִם תֹּאמַר שֶׁנִּמְצָא בְּאוֹתוֹ זְמַן בַּשְּׁכִינָה - לֹא כָּךְ! שֶׁהֲרֵי בְּמֹשֶׁה נִלְקְחָה וְנֶאֶחְזָה. נִמְצָא שֶׁיְּהוֹשֻׁעַ נֶאֱחַז לְמַטָּה מִמֶּנָּה, וּבַמֶּה? בְּאוֹתוֹ מָקוֹם שֶׁנִּקְרָא נַעַ\"ר."],[10,"","וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (ישעיהלג) עֵינֶיךְ תִרְאֶינָה יְרוּשָׁ לם נָוֶה שַׁאֲנָן אֹהֶל בַּל יִצְעָן בַּל יִסַּע יְתֵדתָיו לָנֶצַח. יְרוּשָׁלם - יְרוּשָׁלַיִם שֶׁלְּמַעְלָה, שֶׁנִּקְרֵאת אֹהֶל בַּל יִצְעָן, שֶׁלֹּא תִמָּצֵא יוֹתֵר לָלֶכֶת לַגָּלוּת. וְזֶהוּ סוֹד הַכְּתוּב וִיהוֹשֻׁעַ בִּן נוּן נַעַר. וַדַּאי נַעַר. לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל, אוֹתוֹ שֶׁנִּקְרָא אֹהֶל בַּל יִצְעָן. מְלַמֵּד שֶׁבְּכָל יוֹם וָיוֹם הָיָה יוֹנֵק מֵהַשְּׁכִינָה כְּמוֹ אוֹתוֹ הַנַּעַר שֶׁלְּמַעְלָה, לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל, וְיוֹנֵק מִמֶּנָּה תָּמִיד. כָּךְ נַעַר זֶה שֶׁלְּמַטָּה לֹא יָמִישׁ מִתּוֹךְ הָאֹהֶל וְיוֹנֵק מִמֶּנָּה תָּמִיד."]]],[["בְּגִין כַּךְ, כַּד חָמָא מֹשֶׁה, לסמאל, נָחִית לְסַיְּיעָא לַעֲמָלֵק, אָמַר מֹשֶׁה, וַדַּאי הַאי נַעַר יְקוּם לָקֳבְלֵיהּ, וְיִשְּׁלוֹט עָלֵיהּ, לְנַצְּחָא לֵיהּ. מִיַּד וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בָּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק, דִּילָךְ הַאי קְרָבָא דִּלְתַתָּא, וַאֲנָא אִזְדָּרֵז לִקְרָבָא דִּלְעֵילָּא. בָּחַר לָנוּ אֲנָשִׁים, זַכָּאִין בְּנֵי זַכָּאִין, דְּיִתְחֲזוּן לְמֵהַךְ עִמָּךְ.","אָמַר רַבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּנָפִיק יְהוֹשֻׁעַ נַעַר. אִתְּעַר נַעַר דִּלְעֵילָּא, וְאִתְתָּקַּן בְּכַמָּה תִּיקּוּנִין בְּכַמָּה זַיְינִין, דְּאַתְקִינַת לֵיהּ אִמֵיהּ, לִקְרָבָא דָּא, לְנַקְמָא נוּקְמָא דִּבְרִית. וְהַיְינוּ דִּכְתִּיב, (ויקרא כ״ו:כ״ה) חֶרֶב נוֹקֶמֶת נְקַם בְּרִית, וְדָא הוּא רָזָא דִּכְתִּיב, וַיַּחֲלשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. לְפִי חֶרֶב וַדַּאי, וְלָא לְפוּם רוּמְחִין וְזַיְינִין, אֶלָּא בַּחֶרֶב וַדַּאי הִיא, הַאי דְּאִקְרֵי חֶרֶב נוֹקֶמֶת נְקַם בְּרִית.","וּמֹשֶׁה אִתְתָּקַּן לִקְרָבָא דִּלְעֵילָּא, וִידֵי מֹשֶׁה כְּבֵדִים: כְּבֵדִים מַמָּשׁ, יַקִּירִין, קַדִּישִׁין, לָא אִסְתַאְבָן לְעָלְמִין. יְקִרִין דְּאִתְחָזוּן לְאַגָּחָא בְּהוּ קְרָבָא דִּלְעֵילָּא. וַיִקְחוּ אֶבֶן וַיָּשִׂימוּ תַחְתָּיו וַיֵּשֶׁב עָלֶיהָ, בְּגִין דְּיִשְׂרָאֵל שַׁרְיָין בְּצַעֲרָא, וִיהֵא עִמְּהוֹן בְּצַעֲרֵיהוֹן.","וְאַהֲרֹן וְחוּר תָּמְכוּ בְיָדָיו מִזֶּה אֶחָד וּמִזֶּה אֶחָד וַיְהִי יָדָיו אֱמוּנָה וְגוֹ', מַאי תָּמְכוּ בְיָדָיו. אֱמוּנָה. (אמונה, מהימנותא ודא) וְכִי עַל דְּאַהֲרֹן וְחוּר תְּמִיכוּ לִידוֹי, הֲווֹ יְדוֹי אֱמוּנָה. אֶלָּא, מֹשֶׁה כֹּלָּא בְּחָכְמְתָא עָבִיד מַה דְּעָבִיד. אַהֲרֹן וְחוּר, דָּא מִסִּטְרָא דִּילֵיהּ, וְדָא מִסִּטְרָא דִּילֵיהּ, וְיָדוֹי בְּאֶמְצָעִיתָא, וְעַל דָּא וַיְהִי יָדָיו אֱמוּנָה, מְהֵימָנוּתָא. אַהֲרֹן בְּגִין דְּיִתְּעַר סִטְרָא דִּילֵיהּ, (חוקת קל\"א ע\"ב) וְחוּר בְּגִין דְּיִתְּעַר סִטְרָא דִּילֵיהּ, וַהֲווּ אֲחִידָן בִּידוֹי מִכָּאן וּמִכָּאן, דְּאִשְׁתַּכְחָא סִיוּעָא דִּלְעֵילָּא.","(שמות י״ז:י״א) וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל. כַּאֲשֶׁר יָרִים: דְּזָקִיף יְמִינָא עַל שְׂמָאלָא, וְאִתְכָּוַּון בִּפְרִישׁוּ דְּיָדוֹי. וְגָבַר יִשְׂרָאֵל: יִשְׂרָאֵל דִּלְעֵילָּא. וְכַאֲשֶׁר יָנִיחַ יָדוֹ וְגָבַר עֲמָלֵק, בְּשַׁעֲתָא דְּיִשְׂרָאֵל לְתַתָּא, מִשְׁתַּכְּכִין מִצְּלוֹתָא, לָא יַכְלִין יְדֵי מֹשֶׁה לְמֵיקָם בִּזְקִיפוּ, וְגָבַר עֲמָלֵק. מִכָּאן אוֹלִיפְנָא, אַף עַל גַּב דְּכַהֲנָא פָּרִישׂ יְדוֹי, בְּקָרְבְּנָא, לְתַקְּנָא גַּרְמֵיהּ בְּכֹלָּא, יִשְׂרָאֵל בַּעְיָין לְאִשְׁתַּכְּחָא בִּצְלוֹתְהוֹן, עִמֵּיהּ.","תָּאנָא, בִּקְרָבָא דָּא דַּעֲמָלֵק, אִשְׁתְּכָחוּ עִלָּאִין וְתַתָּאִין, וְעַל דָּא, וַיְהִי יָדָיו אֱמוּנָה, בְּהֵימְנוּתָא כַּדְקָא חֲזֵי. וַיְהִי יָדָיו אֱמוּנָה. וַיִּהְיוּ יָדָיו מִבָּעֵי לֵיהּ. אֶלָּא, בְּגִין דְּתַלְיָא כֹּלָּא בִּימִינָא, כְּתִיב וַיְהִי. וּכְתִיב יָדָיו, בְּגִין דְּהוּא עִקָרָא דְּכֹלָּא. וּכְתִיב, (שמותטו) יְמִינְךָ יְיָ' נְאְדָּרִי בַּכֹּחַ יְמִינְךָ יְיָ' תִּרְעַץ אוֹיֵב.","(שמות י״ז:י״ד) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה כְּתֹב זֹאת זִכָּרוֹן בְּסֵפֶר וְגוֹ'. תָּא חֲזֵי, מַה כְּתִיב לְעֵילָּא, וַיַּחֲלוֹשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. וַיַּחֲלשׁ, וַיַּהֲרוֹג מִבָּעֵי לֵיהּ. אֶלָּא, וַיַּחֲלשׁ, כְּמָה דְּאִתְּמַר, (ישעיהו י״ד:י״ב) חוֹלֵשׁ עַל גּוֹיִם. יְהוֹשֻׁעַ הֲוָה חוֹלֵשׁ עָלַיְיהוּ, וְהַהוּא חֶרֶב נוֹקֶמֶת נְקַם בְּרִית קָטִיל לוֹן, דִּכְתִּיב לְפִי חָרֶב כְּמָה דְּאִתְּמַר.","כְּתֹב זֹאת זִכָּרוֹן, זֹאת דַּיְקָא. וְשִׂים בְּאָזְנֵי יְהוֹשֻׁעַ, דְּהָא הוּא זָמִין לְקָטְלָא מַלְכִין אַחֲרָנִין. כִּי מָחֹה אֶמְחֶה. מָחֹה: לְעֵילָּא. אֶמְחֶה: לְתַתָּא. זֵכֶר, דּוּכְרָנָא דִּלְעֵילָּא וְתַתָּא.","אָמַר רִבִּי יִצְחָק, כְּתִיב כִּי מָחֹה אֶמְחֶה, וּכְתִיב (דברים כ״ה:י״ט) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. אֶלָּא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַתּוּן מָחוּן דּוּכְרָנֵיהּ לְתַתָּא, וַאֲנָא אֶמְחֶה דּוּכְרָנֵיהּ לְעֵילָּא.","אָמַר רִבִּי יוֹסֵי, עֲמָלֵק עַמִּין אַחֲרָנִין אַייתִין עִמֵּיהּ, וְכֻלְּהוּ דְּחִילוּ לְקָרְבָא בְּהוּ בְּיִשְׂרָאֵל, בַּר אִיהוּ. וּבְגִין כַּךְ, יְהוֹשֻׁעַ הֲוָה חוֹלֵשׁ עָלַיְיהוּ. רִבִּי יֵיסָא אָמַר, וַיַּחֲלֹשׁ יְהוֹשֻׁעַ, דְּתָבַר חֵילָא דִּלְהוֹן מִלְּעֵילָּא.","(שמות י״ז:ט״ו) וַיִּבֶן מֹשֶׁה מִזְבֵּחַ וַיִּקְרָא שְׁמוֹ יְיָ' נִסִּי. וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, לָקֳבֵל הַהוּא דִּלְעֵילָּא. וַיִּקְרָא שְׁמוֹ הַהוּא מֹשֶׁה (נ\"א דההוא מזבח) יְיָ' נִסִּי. מַאי יְיָ' נִסִּי. בְּגִין דְּאַנְקִים נִקְמָתָא דְּהַהוּא רְשִׁימָא קַדִּישָׁא דְּיִשְׂרָאֵל, וּמֵהַהוּא זִמְנָא אִתְקְרֵי, חֶרֶב נוֹקֶמֶת נְקַם בְּרִית."],[[0,"בגין כך, כד וכו':","משום זה כאשר ראה משה את סמאל, שיורד לעזור לעמלק, אמר משה, ודאי נער הזה יקום כנגדו, וישלוט עליו לנצח אותו. מיד ויאמר משה אל יהושע בחר לנו וגו'. שלך הוא מלחמה הזו שלמטה, ואני אזדרז למלחמה שלמעלה. בחר לנו אנשים. היינו צדיקים בני צדיקים, שיהיו ראוים ללכת עמך."],[1,"אר\"ש בשעתא וכו':","א\"ר שמעון, בשעה שיצא יהושע נער, התעורר נער העליון, מטטרון, והתתקן בכמה תקונים בכמה כלי זיין, שהתקינה לו אמו, שהיא השכינה, למלחמה זו, לנקום נקם ברית. והיינו שכתוב, חרב נוקמת נקם ברית. וזהו סוד שכתוב, ויחלוש יהושע את עמלק ואת עמו לפי חרב. לפי חרב ודאי, ולא לפי רמחים וכלי זיין, אלא בחרב, ודאי היא, זו שנקרא, חרב נוקמת נקם ברית."],[2,"ומשה אתתקן לקרבא וכו':","ומשה התתקן למלחמה של מעלה. וידי משה כבדים. כבדים ממש, מכובדים קדושים לא נטמאו לעולם. מכובדים, שראוים לעשות בהם מלחמה שלמעלה. ויקחו אבן וישימו תחתיו וישב עליה. היינו משום שישראל שרוים בצער ויהיה עמהם בצער שלהם."],[3,"ואהרן וחור תמכו בידיו וגו':","שואל. מהו תמכו בידיו, אמונה, וכי בשביל שאהרן וחור תמכו בידיו, היו ידיו אמונה. ומשיב, אלא הכל בחכמה עשה משה מה שעשה, אהרן וחור, זה מצד שלו שהוא ימין, וזה מצד שלו שהוא שמאל, וידיו של משה באמצע בקו אמצעי, וע\"כ, ויהי ידיו אמונה, נאמנים, אהרן, כדי שיתעורר מצד שלו שהוא ימין, וחור, כדי שיתעורר מצד שלו, שהוא שמאל. והיו אוחזים בידיו מכאן ומכאן, כדי שתמצא עזרה של מעלה."],[4,"והיה כאשר ירים משה וגו':","כאשר ירים, פירושו שהרים ימין על שמאל, והיה מתכוון בזה כשפרש את ידיו, ואז וגבר ישראל. ישראל של מעלה, שהוא ז\"א, וכאשר יניח ידו וגבר עמלק, היינו בשעה שישראל שלמטה משתככים מתפלה, לא יכלו ידי משה לקום ולהיות זקופים, וגבר עמלק. מכאן למדנו, אע\"פ שהכהן פורש ידיו בקרבן לתקן עצמו בכל, צריכים ישראל להמצא עמו בתפלתו."],[5,"תאנא בקרבא דא וכו':","למדנו, במלחמה זו של עמלק, נמצאו עליונים ותחתונים, וע\"כ ויהי ידיו אמונה, דהיינו באמונה כראוי. שואל, ויהי ידיו אמונה, ויהיו ידיו היה צריך לומר. ומשיב, משום שהכל תלוי ביד ימין, ע\"כ כתוב ויהי, וכתוב ידיו, ללמד שהימין הוא עיקר הכל. וכתוב, ימינך ה' נאדרי בכח ימינך ה' תרעץ אויב."],[6,"ויאמר וגו' כתוב זאת זכרון וגו':","בוא וראה, מה כתוב למעלה, ויחלוש יהושע את עמלק ואת עמו לפי חרב. שואל, ויחלוש ויהרוג היה צריך לומר. ומשיב, אלא ויחלש, הוא כמו שלמדנו, חולש על גוים. יהושע היה חולש עליהם, וההיא חרב נוקמת נקם ברית הרג אותם, שכתוב, לפי חרב. כמו שלמדנו."],[7,"כתוב זאת זכרון:","זאת היא בדיוק, שהוא שם המלכות, \u0003ושים באזני יהושע.\u0004 כי הוא עתיד להרוג מלכים אחרים, דהיינו ל\"א מלכים. \u0003כי מחה אמחה.\u0004 מחה, הוא למעלה, אמחה למטה. \u0003זכר,\u0004 היינו זכר שלמעלה ושלמטה."],[8,"אמר ר' יצחק וכו':","אר\"י, כתוב, כי מחה אמחה, שמשמע שהקב\"ה ימחה, וכתוב תמחה את זכר עמלק, שמשמע שאנו צריכים למחות אותו. ומשיב, אלא אמר הקב\"ה, אתם תמחו את זכר עמלק שלמטה, ואני אמחה את זכר עמלק שלמעלה."],[9,"אמר ר' יוסי וכו':","אר\"י עמלק, עמים אחרים באו עמו, וכולם היו מתיראים לקרב אל ישראל חוץ ממנו. ומשום זה, היה חולש עליהם יהושע. ר' ייסא אמר, ויחלוש יהושע, ששבר כחם מלמעלה."],[10,"ויבן משה מזבח וגו' ה' נסי:","ויבן משה מזבח, כנגד מזבח העליון. ויקרא שמו של מזבח ההוא העליון, ה' נסי. מהו ה' נסי. היינו משום שנקם נקמת רושם הקדוש ההוא של ישראל. ובזמן ההוא היה נקרא, חרב נוקמת נקם ברית ומשה קרא לו ה' נסי."]],[[0,"","לָכֵן, כְּשֶׁרָאָה מֹשֶׁה אֶת סמא\"ל יוֹרֵד לְסַיֵּעַ לַעֲמָלֵק, אָמַר מֹשֶׁה, וַדַּאי נַעַר זֶה יָקוּם כְּנֶגְדּוֹ וְיִשְׁלֹט עָלָיו לְנַצֵּחַ אוֹתוֹ. מִיָּד - וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ בְּחַר לָנוּ אֲנָשִׁים וְצֵא הִלָּחֵם בַּעֲמָלֵק. שֶׁלְּךְ הַקְּרָב הַזֶּה שֶׁלְּמַטָּה, וַאֲנִי אֶזְדָּרֵז לַקְּרָב שֶׁלְּמַעְלָה. בְּחַר לָנוּ אֲנָשִׁים - צַדִּיקִים בְּנֵי צַדִּיקִים, שֶׁרְאוּיִים לָלֶכֶת עִמְּךְ."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁיָּצָא יְהוֹשֻׁעַ נַעַר, הִתְעוֹרֵר הַנַּעַר שֶׁלְּמַעְלָה וְהִתְתַּקֵּן בְּכַמָּה תִּקּוּנִים, בְּכַמָּה כְּלֵי זַיִן שֶׁהִתְקִינָה לוֹ אִמּוֹ לַקְּרָב הַזֶּה לִנְקֹם אֶת נִקְמַת הַבְּרִית, וְהַיְנוּ מַה שֶּׁכָּתוּב (ויקרא כו) חֶרֶב נֹקֶמֶת נְקַם בְּרִית. וְזֶהוּ סוֹד הַכָּתוּב וַיַּחֲלֹשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. לְפִי חֶרֶב וַדַּאי, וְלֹא לְפִי רְמָחִים וּכְלֵי זַיִן, אֶלָּא בַּחֶרֶב וַדַּאי הִיא, זוֹ שֶׁנִּקְרֵאת חֶרֶב נֹקֶמֶת נְקַם בְּרִית."],[2,"","וּמֹשֶׁה הִתְתַּקֵּן לַקְּרָב שֶׁלְּמַעְלָה. וִידֵי מֹשֶׁה כְּבֵדִים, כְּבֵדִים מַמָּשׁ, נִכְבָּדִים, קְדוֹשִׁים, שֶׁלֹּא נִטְמְאוּ לְעוֹלָמִים. נִכְבָּדִים שֶׁרְאוּיִים לַעֲרֹךְ בָּהֶם קְרָב שֶׁלְּמַעְלָה. וַיִּקְחוּ אֶבֶן וַיָּשִׂימוּ תַחְתָּיו וַיֵּשֶׁב עָלֶיהָ, מִשּׁוּם שֶׁיִּשְׂרָאֵל שְׁרוּיִים בְּצַעַר, וִיהֵא עִמָּהֶם בְּצַעֲרָם."],[3,"","וְאַהֲרֹן וְחוּר תָּמְכוּ בְיָדָיו מִזֶּה אֶחָד וּמִזֶּה אֶחָד וַיְהִי יָדָיו אֱמוּנָה וְגוֹ'. מַה זֶּה תָּמְכוּ בְיָדָיו? אֱמוּנָה. (אמונה, אמונה ודאי) וְכִי עַל שֶׁאַהֲרֹן וְחוּר תָּמְכוּ אֶת יָדָיו, הָיוּ יָדָיו אֱמוּנָה? אֶלָּא מֹשֶׁה עָשָׂה הַכֹּל בְּחָכְמָה מַה שֶּׁעָשָׂה. אַהֲרֹן וְחוּר - זֶה מִצִּדּוֹ וְזֶה מִצִּדּוֹ, וְיָדָיו בָּאֶמְצַע, וְלָכֵן וַיְהִי יָדָיו אֱמוּנָה, אֱמוּנָה. אַהֲרֹן כְּדֵי שֶׁיִּתְעוֹרֵר הַצַּד שֶׁלּוֹ, וְחוּר כְּדֵי שֶׁיִּתְעוֹרֵר הַצַּד שֶׁלּוֹ, וְהָיוּ אוֹחֲזִים בְּיָדָיו מִכָּאן וּמִכָּאן, שֶׁיִּמָּצֵא סִיּוּעַ שֶׁלְּמַעְלָה. וְהָיָה כַּאֲשֶׁר יָרִים מֹשֶׁה יָדוֹ וְגָבַר יִשְׂרָאֵל."],[4,"","כַּאֲשֶׁר יָרִים - שֶׁזָּקַף יָמִין עַל שְׂמֹאל, וְהִתְכַּוֵּן בִּפְרִישַׂת יָדָיו. וְגָבַר יִשְׂרָאֵל - יִשְׂרָאֵל שֶׁלְּמַעְלָה (תפארת). וְכַאֲשֶׁר יָנִיחַ יָדוֹ וְגָבַר עֲמָלֵק - בְּשָׁעָה שֶׁיִּשְׂרָאֵל לְמַטָּה שׁוֹכְכִים בִּתְפִלָּתָם, לֹא יְכוֹלִים יְדֵי מֹשֶׁה לַעֲמֹד בִּזְקִיפוּת, וְגָבַר עֲמָלֵק. מִכָּאן לָמַדְנוּ, אַף עַל פִּי שֶׁהַכֹּהֵן פּוֹרֵס אֶת יָדָיו בַּקָּרְבָּן כְּדֵי לְתַקֵּן אֶת עַצְמוֹ בַּכֹּל - יִשְׂרָאֵל צְרִיכִים לְהִמָּצֵא עִמּוֹ בִּתְפִלּוֹתֵיהֶם."],[5,"","שָׁנִינוּ, בַּקְּרָב הַזֶּה שֶׁל עֲמָלֵק, נִמְצְאוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְלָכֵן וַיְהִי יָדָיו אֱמוּנָה, בֶּאֱמוּנָה כָּרָאוּי. וַיְהִי יָדָיו אֱמוּנָה, וַיִּהְיוּ יָדָיו הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא מִשּׁוּם שֶׁהַכֹּל תָּלוּי בַּיָּמִין כָּתוּב וַיְהִי. וְכָתוּב יָדָיו מִשּׁוּם שֶׁהוּא עִקַּר הַכֹּל. וְכָתוּב (שמות טו) יְמִינְךְ ה' נֶאְדָּרִי בַּכֹּחַ יְמִינְךְ ה' תִּרְעַץ אוֹיֵב."],[6,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה כְּתֹב זאת זִכָּרוֹן בַּסֵּפֶר וְגוֹ'. בּא רְאֵה מַה כָּתוּב לְמַעְלָה? וַיַּחֲלֹשׁ יְהוֹשֻׁעַ אֶת עֲמָלֵק וְאֶת עַמּוֹ לְפִי חָרֶב. וַיַּחֲלֹשׁ? וַיַּהֲרֹג הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא וַיַּחֲלֹשׁ כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יד) חוֹלֵשׁ עַל גּוֹיִם. יְהוֹשֻׁעַ הָיָה חוֹלֵשׁ עֲלֵיהֶם, וְאוֹתָהּ חֶרֶב נֹקֶמֶת נְקַם בְּרִית הוֹרֶגֶת אוֹתָם, שֶׁכָּתוּב לְפִי חָרֶב, כְּמוֹ שֶׁנִּתְבָּאֵר."],[7,"","כְּתֹב זאת זִכָּרוֹן, זאת דַּוְקָא. וְשִׂים בְּאָזְנֵי יְהוֹשֻׁעַ, שֶׁהֲרֵי הוּא עָתִיד לַהֲרֹג מְלָכִים אֲחֵרִים. כִּי מָחֹה אֶמְחֶה, מָחֹה - לְמַעְלָה, אֶמְחֶה - לְמַטָּה. זֵכֶר - זִכָּרוֹן שֶׁל מַעְלָה וּמַטָּה."],[8,"","אָמַר רַבִּי יִצְחָק, כָּתוּב כִּי מָחֹה אֶמְחֶה, וְכָתוּב (דבריםכה) תִּמְחֶה אֶת זֵכֶר עֲמָלֵק. אֶלָּא, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתֶּם מְחוּ אֶת זִכְרוֹנוֹ לְמַטָּה, וַאֲנִי אֶמְחֶה אֶת זִכְרוֹנוֹ לְמַעְלָה."],[9,"","אָמַר רַבִּי יוֹסֵי, עֲמָלֵק הֵבִיא עִמּוֹ עַמִּים אֲחֵרִים, וְכֻלָּם פָּחֲדוּ לִקְרַב לְיִשְׂרָאֵל חוּץ מִמֶּנּוּ, וְלָכֵן יְהוֹשֻׁעַ הָיָה חוֹלֵשׁ עֲלֵיהֶם. רַבִּי יֵיסָא אָמַר, וַיַּחֲלֹשׁ יְהוֹשֻׁעַ, שֶׁשָּׁבַר אֶת כֹּחָם מִלְמַעְלָה. וַיִּבֶן מֹשֶׁה מִזְבֵּחַ וַיִּקְרָא שְׁמוֹ ה' נִסִּי."],[10,"","וַיִּבֶן מֹשֶׁה מִזְבֵּחַ - כְּנֶגֶד אוֹתוֹ שֶׁלְּמַעְלָה. וַיִּקְרָא שְׁמוֹ - אוֹתוֹ מֹשֶׁה (אותו מזבח) - ה' נִסִּי. מַה זֶּה ה' נִסִּי? מִשּׁוּם שֶׁנָּקַם אֶת נִקְמַת אוֹתוֹ רֹשֶׁם הַקָּדוֹשׁ שֶׁל יִשְׂרָאֵל. וּמֵאוֹתוֹ הַזְּמַן נִקְרָא חֶרֶב נֹקֶמֶת נְקַם בְּרִית."]]],[["רִבִּי יוֹסֵי אָמַר, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, מִזְבַּח לְכַפְּרָא עָלַיְיהוּ. וַיִּקְרָא שְׁמוֹ. שְׁמוֹ דְּמַאן. אָמַר רִבִּי חִיָּיא שְׁמֵיהּ דְּמַדְבְּחָא הַהוּא. יְיָ' נִסִּי: כְּמָה דְאַתְּ אָמֵר, וְשָׁם נִסָּהוּ. וְכֹלָּא מִלָּה חַד, עַל דְּאִתְפְּרָעוּ יִשְׂרָאֵל, וְאִתְגַּלְיָיא הַהוּא אָת קַיָּימָא, רְשִׁימָא קַדִּישָׁא. מִכָּאן אוֹלִיפְנָא, דְּכֵיוָן דְּאִתְגְּזַר בְּרֵיהּ דְּבַר נָשׁ, וְאִתְגַּלְיָיא בֵּיהּ אָת רְשִׁימָא קַדִּישָׁא קַיָּימָא. הַהוּא אִקְרֵי מִזְבֵּחַ לְכַפְּרָא עָלֵיהּ. וּמַה שְׁמֵיהּ. יְיָ' נִסִּי.","כְּגַוְונָא דָּא יַעֲקֹב, בְּנָהּ מַדְבְּחָא, דִּכְתִּיב, (בראשית ל״ג:כ׳) וַיַּצֶּב שָׁם מִזְבֵּחַ וַיִּקְרָא לוֹ אֵל אֱלהֵי יִשְׂרָאֵל. לְמַאן. לְהַהוּא אֲתָר דְּאִקְרֵי מִזְבֵּחַ. וּמַאן שְׁמֵיהּ. אֵל אֱלֹהֵי יִשְׂרָאֵל.","אָמַר רִבִּי יוֹסֵי, מַאי דִּכְתִּיב, (שמות כ״ד:י׳) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְגוֹ'. וְכִי מַאן יָכִיל לְמֵחמֵי לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְהָא כְּתִיב (שמות ל״ג:כ׳) כִּי לא יִרְאַנִי הָאָדָם וָחָי. וְהָכָא אָמַר וַיִּרְאוּ אֶלָּא דְּאִתְגַּלְיָא קֶשֶׁת עָלַיְיהוּ בִּגְוָונִין נְהִירִין, וְהָכִי תָּנֵינָן, כָּל מַאן דְּאִסְתַּכַּל בַּקֶּשֶׁת, כְּמַאן דְּמִסְתַּכַּל בַּשְּׁכִינָה, וּלְאִסְתַּכְּלָא בִּשְׁכִינְתָּא אָסִיר.","וְעַל דָּא, אָסִיר לֵיהּ לְאִינִישׁ, לְאִסְתַּכְּלָא בְּאֶצְבְּעַיְיהוּ דְּכַהֲנֵי, בְּשַׁעֲתָא דְּפַרְסֵי יְדַיְיהוּ. אָסוּר לְאִסְתַּכְּלָא בַּקֶּשֶׁת. מַאן קֶשֶׁת. אָמַר רִבִּי אַבָּא, בַּקֶּשֶׁת סְתָם אָמַר לֵיהּ מַאי בַּקֶּשֶׁת סְתָם אֲמַר לֵיהּ בַּקֶּשֶׁת דִּלְעֵילָּא, וּבַקֶּשֶׁת דִּלְתַתָּא.","בַּקֶּשֶׁת דִּלְעֵילָּא, בִּגְוָונוֹי. דְּכָל מַאן דְּיִסְתַּכַּל בִּגְוָונוֹי, כְּאִילּוּ אִסְתַּכַּל בְּאֲתָר דִּלְעֵילָּא, וְאָסִיר לְאִסְתַּכְּלָא בֵּיהּ, דְּלָא יַעֲבִיד קְלָנָא בִּשְׁכִינְתָּא. קֶשֶׁת דִּלְתַתָּא מַאי הִיא. הַהוּא אָת קַיָּימָא, דְּאִתְרְשִׁים בֵּיהּ בְּבַר נָשׁ, דְּכָל מַאן דְּיִסְתַּכַּל בֵּיהּ, עָבִיד קְלָנָא לְעֵילָּא.","אָמַר רִבִּי יִצְחָק, אִי הָכִי וְהָכְתִיב (בראשית כ״ד:ב׳) שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, דְּהֲוָה אוֹמֵי לֵיהּ בְּהַאי אָת. אֲמַר לֵיהּ, אֲנַח לְהוּ לַאֲבָהָן דְּעָלְמָא, דְּלֵית אִינּוּן כִּשְׁאַר בְּנֵי עָלְמָא. וְעוֹד, שִׂים נָא יָדְךָ תַּחַת יְרֵכִי כְּתִיב, וְלָא כְּתִיב רְאֵה תַּחַת יְרֵכִי, בְּגִין כָּךְ אָסִיר לְאִסְתַּכְּלָא בַּקֶּשֶׁת סְתָם, כְּמָה דְּתָנֵינָן.","תָּאנָא, וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל, דְּאִתְגַּלְיָא קֶשֶׁת עָלַיְיהוּ, בִּגְוָונִין שַׁפִּירִין נְהִירִין, מְלַהֲטָן לְכָל עִיבָר, מַשְׁמַע דִּכְתִּיב, אֵת אֱלֹהֵי יִשְׂרָאֵל וְלָא כְּתִיב וַיִּרְאוּ אֱלהֵי יִשְׂרָאֵל. אָמַר רִבִּי יוֹסֵי, נְהוֹרָא דְּבוּצִינָא דִּשְׁכִינְתָּא. וּמַאי נִיהוּ. הַהוּא דְּאִקְרֵי נַעַר, דִּמְשַׁמֵּשׁ לִשְׁכִינְתָּא, בְּמַקְדְּשָׁא. וּבְגִין כַּךְ, אֵת דַּיְיקָא.","וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, דְּאִתְרְשִׁים בֵּיהּ תְּחוֹת דּוּכְתֵּיהּ, חַד לְבֵינָתָא מֵאִינּוּן לְבֵנִין דַּהֲווֹ בָּנִין בְּמִצְרַיִם, דְּתָנֵינָן, אִתְּתָא חֲדָא אוֹלִידַת בְּמִצְרַיִם, וַהֲוָה אָתִין סַרְכֵי פַּרְעֹה, וְעָאלַת לֵיהּ בְּחַד לְבֵינָתָא, וְאָתָא פַּס יְדָא וְאָחִיד לֵיהּ, וְאִתְרְשִׁים תְּחוֹת רַגְלוֹי דִּשְׁכִינְתָּא, וְקַיְּימָא קָמֵיהּ, עַד דְּאִתּוֹקַד בֵּי מַקְדְּשָׁא דִּלְתַתָּא, דִּכְתִּיב, (איכה ב׳:א׳) וְלא זָכַר הֲדוֹם רַגְלָיו.","ר' חִיָּיא אָמַר, לִבְנַת הַסַּפִּיר: נְהִירוּתָא דְּסַפִּיר, קַלְדִיטֵי בְּקַנְדִיטֵי גְּלִיפִין עִלָּאִין דִּלְעֵילָּא, דְּמִתְלַהֲטָא לְשִׁבְעִין וּתְרֵין עִבְרִי, הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ד:י״א) וִיסַדְתִּיךְ בַּסַּפִּירִים. (שמות כ״ד:י׳) וּכְעֶצֶם הַשָּׁמַיִם. מַאי עֶצֶם הַשָּׁמַיִם. אָמַר רִבִּי אַבָּא, מָה עֶצֶם הַשָּׁמַיִם, גְּלִיפָא בְּשִׁבְעִין וּתְרֵין עֲנָפִין, פַּרְחִין מְלַהֲטָן בְּכָל עִיבָר. אוּף הָכָא, חֵיזוּ דְּהַהוּא עֶצֶם הַשָּׁמַיִם כְּחֵיזוּ שְׁמַיָּא מַמָּשׁ. רִבִּי יְהוּדָה אָמַר, כֹּלָּא אִתְרְשִׁים בְּהַהוּא נְהִירוּ, דְּחֵיזוּ דְּמִתְגַּלְפָא מִסִּטְרָא דִּשְׁכִינְתָּא.","אָמַר רִבִּי חִזְקִיָּה, אִי הָכִי, וְהָא שִׁתִּין אִינּוּן, בְּסַחֲרָנִיהּ דִּשְׁכִינְתָּא, דִּכְתִּיב, (שיר השירים ג׳:ז׳) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. אֲמַר לֵיהּ הָכִי הוּא וַדַּאי. אֶלָּא אִינּוּן שִׁתִּין, אִתְנְהִירוּ בִּתְרֵיסַר תְּחוּמִין, וְלָא אַעְדִּיאוּ מִסָּחֲרָנוּתָהָּא לְעָלְמִין. דְּתָנֵינָן, תְּרֵיסַר תְּחוּמִין, גְּלִיפִין עִלָּאִין, בְּמַתְקְלָא סְלִיקוּ, בְּאִילָנָא קַדִּישָׁא רַבָּא וְתַקִּיף. וְכֻלְּהוּ נְהִירִין בְּמַטְרוֹנִיתָא, כַּד אִתְחַבְּרַת בְּמַלְכָּא. וְדָא הוּא עֶצֶם הַשָּׁמַיִם, עֶצֶם הַשָּׁמַיִם מַמָּשׁ. וְכָל אִינּוּן נְהִירִין שְׁבִילִין, מְנָהֲרִין בֵּיהּ, בִּנְהִירוּ דְּמַטְרוֹנִיתָא.","וְתָאנָא, נְהִירוּ דְּאִלֵּין שִׁתִּין, דְּסָחֲרָנָהָא, רְשִׁימִין בֵּיהּ בְּהַהוּא נַעַ\"ר, וְקָרֵינָן לְהוּ שִׁתִּין פּוּלְסֵי דְּנוּרָא, דְּאִתְלָבַּשׁ בְּהוּ מִסְּטָר דִּשְׁכִינְתָּא, מִתְלַהֲטָן בְּדִינָא, הֲדָא הוּא דִכְתִיב שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ."],[[0,"ר' יוסי אמר וכו':","רי\"א, ויבן משה מזבח, היינו מזבח לכפר על ישראל. ויקרא שמו, שמו של מי, אמר ר' חייא שמו של מזבח ההוא. ה' נסי הוא כש\"א ושם נסהו. שפירושו התעלות, והכל דבר אחד, שנתעלו על שנתפרעו ישראל, ונגלה בהם אות ברית ההוא, רושם הקדוש. (כנ\"ל אות שמ\"ט) מכאן למדנו, כיון שנמול בנו של אדם ונגלה בו אות ברית רושם הקדוש, בן ההוא נקרא מזבח לכפר עליו. ומה שמו ה' נסי."],[1,"כגוונא דא יעקב וכו':","כעין זה יעקב בנה מזבח. שכתוב, ויצב שם מזבח ויקרא לו אל אלקי ישראל. למי קרא. לאותו מקום שנקרא מזבח, דהיינו המלכות. ומה שמו. אל אלקי ישראל."],[2,"אמר ר' יוסי וכו':","אר\"י, מה שכתוב ויראו את אלקי ישראל וגו'. שואל, מי יכול לראות את הקב\"ה, והרי כתוב, כי לא יראני האדם וחי, וכאן אמר ויראו. ומשיב, אלא שנגלה עליהם הקשת בצבעים מאירים, שהיא השכינה המקבלת מג' גוונין לבן אדום ירוק. וכך למדנו, כל מי שמסתכל בקשת, כמו שמסתכל בשכינה, ואסור להסתכל בשכינה."],[3,"ועל דא אסיר וכו':","וע\"כ, אסור לו לאדם להסתכל באצבעותיהם של הכהנים בשעה שפורשים כפיהם. אסור להסתכל בקשת. שואל, מהו קשת. א\"ר אבא בקשת סתם. אמר לו, מהו בקשת סתם. א\"ל הן בקשת של מעלה, והן בקשת שלמטה."],[4,"בקשת דלעילא בגוונוי וכו':","ומפרש דבריו. בקשת שלמעלה שאסור להסתכל היינו בצבעיו. לבן אדום ירוק, שה\"ס ג' קוין המאירים בהשכינה. שכל מי שמסתכל בצבעיו, כאלו מסתכל במקום עליון, ואסור להסתכל בו, שלא ינהג בזיון בהשכינה. קשת שלמטה מהו. הוא, אות ברית ההוא, שנרשם בו באדם, שכל מי שמסתכל בו, נוהג בזיון למעלה."],[5,"אמר ר' יצחק וכו':","אר\"י, אם כן, והרי כתוב, שים נא ידך תחת ירכי, שהשביע אותו באות הזה. אמר לו הנח להם לאבות העולם, שהם אינם כשאר בני העולם. ועוד, שים נא ידך תחת ירכי, כתוב, ולא כתוב, ראה תחת ירכי. משום זה, אסור להסתכל בקשת סתם. כמו שלמדנו."],[6,"תאנא ויראו וכו':","למדנו, ויראו את אלקי ישראל, שנגלה עליהם הקשת בצבעים יפים, מאירים, לוהטים לכל צד. שהיא השכינה. זה משמע, שכתוב \u0003את\u0004 אלקי ישראל ולא כתוב, ויראו אלקי ישראל והשכינה נקראת \u0003את.\u0004 אמר ר' יוסי, היינו האור של מאור השכינה, ומי הוא, ההוא שנקרא נער, דהיינו מטטרון, המשמש את השכינה בבית המקדש. ומשום זה, \u0003את\u0004 הוא מדויק. כי הוא שם השכינה, הכוללת מטטרון משמשה."],[7,"ותחת רגליו כמעשה לבנת הספיר:","כי נרשם בו תחת מקומו, לבנה אחת, מאלו הלבנים שהיו בונים במצרים. שלמדנו, אשה אחת הולידה במצרים, והיו באים שרי פרעה, להשליכו לנהר, והכניסה אותו במקום לבנה אחת שבבנין. ובאה פיסת יד ואחז בו, ונרשם תחת רגליו של השכינה. ועמדה לפניו, עד שנשרף בית המקדש שלמטה. שכתוב, ולא זכר הדום רגליו. שהיא לבנת הספיר הנ\"ל."],[8,"ר' חייא אמר וכו':","רח\"א, לבנת הספיר, פירושו אור של ספיר, מפתחות יין הרקח, דהיינו המסך הממותק בבינה המכונה מפתחא לעיל (בהקסה\"ז אות מ\"ב) שהוא פותח המוחין הנקראים יין הרקח. חקיקות עליונות שלמעלה הלוהטים לע\"ב צדדים, כי ממסך דמפתחא מתגלה השם ע\"ב, ז\"ש ויסדתיך בספירים. \u0003וכעצם השמים.\u0004 מהו עצם השמים. אר\"א, מה עצם השמים, שהוא ז\"א, חקוק בע\"ב ענפים פורחים לכל צד, דהיינו שם ע\"ב המאיר הן בחכמה והן בחסדים. אף כאן המראה של עצם השמים ההוא, הוא כמראה השמים ממש, שהוא ז\"א. רבי יהודה אמר הכל נרשם באור ההוא של המראה הנחקק מצד השכינה. \u0003קלדיטי\u0004 פירושו מפתחות כמו אקלידי (חולין צ\"ד:) \u0003קנדיטי\u0004 פירושו יין הרקח כמו קנדיטון (פסיקתא בחדש)."],[9,"אמר רבי חזקיה וכו':","אר\"ח, א\"כ, הרי ששים הם מסביב השכינה, שכתוב, ששים גבורים סביב לה, א\"ל כן הוא ודאי, אלא אלו הששים האירו מן י\"ב הגבולים שבז\"א, ולא סרו מסביב השכינה לעולם. שלמדנו י\"ב גבולים חקוקים עליונים עלו במשקל באילן הגדול והחזק, שה\"ס ג' קוין המאירים בד' רוחות חו\"ג תו\"מ, שהם י\"ב, וכולם מאירים במטרוניתא, שהיא השכינה, כאשר מתחברת בהמלך שהוא ז\"א. עצם השמים ממש, שמקבלת כל מה שיש בשמים, שהוא ז\"א, וכל אלו האורות והשבילים מאירים בו באור השכינה."],[10,"ותאנא, נהירו דאלין וכו':","ולמדנו האור של אלו ששים גבורים שמסביב השכינה רשומים בו בנער ההוא מטטרון. ואנו קורים אותם ששים הכאות של אש, שהתלבש בהם מצד השכינה לוהטים בדין. ז\"ש ששים גבורים סביב לה."]],[[0,"","רַבִּי יוֹסֵי אָמַר, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, מִזְבֵּחַ לְכַפֵּר עֲלֵיהֶם. וַיִּקְרָא שְׁמוֹ, שֶׁל מִי? אָמַר רַבִּי חִיָּיא, שְׁמוֹ שֶׁל אוֹתוֹ מִזְבֵּחַ. ה' נִסִּי, כְּמוֹ שֶׁנֶּאֱמַר וְשָׁם נִסָּהוּ. וְהַכֹּל דָּבָר אֶחָד, עַל שֶׁיִּשְׂרָאֵל נִפְרְעוּ וְהִתְגַּלָּה אוֹתוֹ אוֹת בְּרִית הָרֹשֶׁם הַקָּדוֹשׁ. מִכָּאן לָמַדְנוּ, שֶׁכֵּיוָן שֶׁנִּמּוֹל בְּנוֹ שֶׁל אָדָם וְהִתְגַּלָּה בּוֹ הָרֹשֶׁם הַקָּדוֹשׁ שֶׁל הַבְּרִית, הוּא נִקְרָא מִזְבֵּחַ לְכַפֵּר עָלָיו, וּמַה שְּׁמוֹ? ה' נִסִּי."],[1,"","כְּמוֹ זֶה יַעֲקֹב בָּנָה מִזְבֵּחַ, שֶׁכָּתוּב (בראשית לג) וַיַּצֶּב שָׁם מִזְבֵּחַ וַיִּקְרָא לוֹ אֵל אֱלֹהֵי יִשְׂרָאֵל. לְמִי? לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא מִזְבֵּחַ. וּמַה שְּׁמוֹ? אֵל אֱלֹהֵי יִשְׂרָאֵל."],[2,"","אָמַר רַבִּי יוֹסֵי, מַה שֶּׁכָּתוּב (שמות כד) וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְגוֹ', וְכִי מִי יָכוֹל לִרְאוֹת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי כָּתוּב (שם לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, וְכָאן אָמַר וַיִּרְאוּ? אֶלָּא שֶׁהִתְגַּלְּתָה עֲלֵיהֶם הַקֶּשֶׁת בִּגְוָנִים מְאִירִים. וְכָךְ שָׁנִינוּ, כָּל מִי שֶׁמִּסְתַּכֵּל בַּקֶּשֶׁת, כְּמִי שֶׁמִּסְתַּכֵּל בַּשְּׁכִינָה, וְאָסוּר לְהִסְתַּכֵּל בַּשְּׁכִינָה."],[3,"","וְעַל זֶה אָסוּר לְאָדָם לְהִסְתַּכֵּל בְּאֶצְבְּעוֹת הַכֹּהֲנִים בְּשָׁעָה שֶׁפּוֹרְשִׂים יְדֵיהֶם. אָסוּר לְהִסְתַּכֵּל בַּקֶּשֶׁת. אֵיזוֹ קֶשֶׁת? אָמַר רַבִּי אַבָּא, בְּקֶשֶׁת סְתָם. אָמַר לוֹ, מַה זֶּה בְּקֶשֶׁת סְתָם? אָמַר לוֹ, בַּקֶּשֶׁת שֶׁלְּמַעְלָה, וּבַקֶּשֶׁת שֶׁלְּמַטָּה."],[4,"","בַּקֶּשֶׁת שֶׁלְּמַעְלָה, בִּגְוָנֶיהָ. שֶׁכָּל מִי שֶׁמִּסְתַּכֵּל בִּגְוָנֶיהָ, כְּאִלּוּ מִסְתַּכֵּל בְּמָקוֹם עֶלְיוֹן, וְאָסוּר לְהִסְתַּכֵּל בּוֹ, שֶׁלֹּא יַעֲשֶׂה קָלוֹן בַּשְּׁכִינָה. קֶשֶׁת שֶׁלְּמַטָּה מַהִי? אוֹתוֹ אוֹת הַבְּרִית שֶׁנִּרְשָׁם בָּאָדָם, שֶׁל מִי שֶׁמִּסְתַּכֵּל בּוֹ, עוֹשֶׂה קָלוֹן לְמַעְלָה."],[5,"","אָמַר רַבִּי יִצְחָק, אִם כָּךְ, הֲרֵי כָּתוּב (בראשית כד) שִׂים נָא יָדְךְ תַּחַת יְרֵכִי, שֶׁהָיָה מַשְׁבִּיעַ אוֹתוֹ בָּאוֹת הַזֶּה. אָמַר לוֹ, הָנַח לַאֲבוֹת הָעוֹלָם, שֶׁאֵינָם כִּשְׁאָר בְּנֵי הָעוֹלָם. וְעוֹד, שִׂים נָא יָדְךְ תַּחַת יְרֵכִי כָּתוּב, וְלֹא כָתוּב רְאֵה תַּחַת יְרֵכִי. לָכֵן אָסוּר לְהִסְתַּכֵּל בַּקֶּשֶׁת סְתָם, כְּמוֹ שֶׁשָּׁנִינוּ."],[6,"","לָמַדְנוּ, וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל, שֶׁהִתְגַּלְּתָה עֲלֵיהֶם הַקֶּשֶׁת בַּגְּוָנִים הַיָּפִים מְאִירִים, לוֹהֲטִים לְכָל עֵבֶר, מַשְׁמָע שֶׁכָּתוּב וַיִּרְאוּ אֵת אֱלֹהֵי יִשְׂרָאֵל וְלֹא כָתוּב וַיִּרְאוּ אֱלֹהֵי יִשְׂרָאֵל. אָמַר רַבִּי יוֹסֵי, אוֹר הַמְּנוֹרָה שֶׁל הַשְּׁכִינָה, וּמַה הוּא? אוֹתוֹ שֶׁנִּקְרָא נַעַר, שֶׁמְּשַׁמֵּשׁ אֶת הַשְּׁכִינָה בַּמִּקְדָּשׁ, וְלָכֵן \"אֵת\" דַּוְקָא."],[7,"","וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר, שֶׁנִּרְשַׁם בּוֹ תַּחַת מְקוֹמוֹ לְבֵנָה אַחַת מֵאוֹתָם לְבֵנִים שֶׁהָיוּ בּוֹנִים בְּמִצְרַיִם, שֶׁשָּׁנִינוּ, אִשָּׁה אַחַת הוֹלִידָה בְּמִצְרַיִם, וְהָיוּ בָּאִים שָׂרֵי פַרְעֹה, וְהִכְנִיסָה אוֹתוֹ בִּלְבֵנָה אַחַת, וּבָא פַּס יָד וְאָחַז אוֹתוֹ, וְנִרְשַׁם תַּחַת רַגְלֵי הַשְּׁכִינָה, וְעוֹמֵד לְפָנָיו, עַד שֶׁנִּשְׂרַף בֵּית הַמִּקְדָּשׁ שֶׁלְּמַטָּה, שֶׁכָּתוּב (איכה ב) וְלֹא זָכַר הֲדם רַגְלָיו."],[8,"","רַבִּי חִיָּיא אָמַר, לִבְנַת הַסַּפִּיר - אוֹר הַסַּפִּיר, מַפְתְּחוֹת יֵין הָרֶקַח חִקּוּקִים עֶלְיוֹנִים שֶׁל מַעְלָה שֶׁלּוֹהֲטִים לְשִׁבְעִים וּשְׁנַיִם עֲבָרִים, זֶהוּ שֶׁכָּתוּב (ישעיה נד) וִיסַדְתִּיךְ בַּסַּפִּירִים. וּכְעֶצֶם הַשָּׁמַיִם, מַה זֶּה כְּעֶצֶם הַשָּׁמַיִם? אָמַר רַבִּי אַבָּא, מָה (שמות כד) עֶצֶם הַשָּׁמַיִם חָקוּק בְּשִׁבְעִים וּשְׁנַיִם עֲנָפִים פּוֹרְחִים לוֹהֲטִים לְכֵל עֵבֶר, אַף כָּאן הַמַּרְאֶה שֶׁל אוֹתוֹ עֶצֶם הַשָּׁמַיִם כְּמַרְאֵה הַשָּׁמַיִם מַמָּשׁ. רַבִּי יְהוּדָה אָמַר, הַכֹּל נִרְשָׁם בְּאוֹתוֹ הָאוֹר שֶׁל מַרְאֶה שֶׁנֶּחְקָק מִצַּד הַשְּׁכִינָה."],[9,"","אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ, וַהֲרֵי הֵם שִׁשִּׁים סְבִיב הַשְּׁכִינָה, שֶׁכָּתוּב (שיר ג) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. אָמַר לוֹ, כָּךְ הוּא וַדַּאי, אֶלָּא אוֹתָם שִׁשִּׁים מְאִירִים בִּשְׁנֵים עָשָׂר תְּחוּמִים, וְלֹא זָזִים מִסְּבִיבָהּ לְעוֹלָמִים. שֶׁשָּׁנִינוּ, שְׁנֵים עָשָׂר תְּחוּמִים חִקּוּקִים עֶלְיוֹנִים עָלוּ בְּמִשְׁקָל, בְּעֵץ קָדוֹשׁ גָּדוֹל וְחָזָק, וְכֻלָּם מְאִירִים בַּגְּבִירָה, כְּשֶׁמִּתְחַבֶּרֶת בַּמֶּלֶךְ. וְזֶהוּ עֶצֶם הַשָּׁמַיִם, עֶצֶם הַשָּׁמַיִם מַמָּשׁ. וְכָל אוֹתָם הַשְּׁבִילִים הַמְּאִירִים, מְאִירִים בּוֹ בְּאוֹר הַגְּבִירָה."],[10,"","וְשָׁנִינוּ, הָאוֹר שֶׁל הַשִּׁשִּׁים הַלָּלוּ שֶׁסְּבִיבָהּ, רְשׁוּמִים בּוֹ בְּאוֹתוֹ נַעַ\"ר, וְקוֹרְאִים לָהֶם שִׁשִּׁים מַכּוֹת אֵשׁ, שֶׁמִּתְלַבֵּשׁ בָּהֶם מִצַּד הַשְּׁכִינָה, לוֹהֲטִים בְּדִין. זֶהוּ שֶׁכָּתוּב שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ."]]],[["תָּאנָא, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ כְּמָה דַּאֲמֵינָא. וַיִּקְרָא שְׁמוֹ ה' נִסִּי. ה' נִסִּי מַמָּשׁ. אֲמַאי. בְּגִין דַּעֲמָלֵק נָטַל כָּל אִינּוּן דַּהֲווֹ גְּזִירִין, וְלָא אִתְפְּרָעוּ, וְגָזַר לוֹן וְשָׁדֵי לְהוּ לְעֵילָּא, וְאָמַר טוֹל מַה דְּאִתְרְעִית בֵּיהּ. בֵּיהּ שַׁעֲתָא מַה כְּתִיב. וַיֹּאמֶר כִּי יַד עַל כֵּס יָהּ מִלְחָמָה לַה' בַּעֲמָלֵק מִדֹּר דֹּר. מִדֹּר דֹּר חֲסֵרִין, מִדִּיּוּרִין דִּלְעֵילָּא, וּמִדִּיּוּרִין דִּלְתַתָּא.","אָמַר רִבִּי יְהוּדָה, בְּכָל דָּרָא וְדָרָא, בְּכָל דָּרִין דְּאַתְיָין לְעָלְמָא, לֵית לָךְ דָּר דְּלֵית בְּהוּ מֵהַהוּא זַרְעָא בִּישָׁא, וקוּדְשָׁא בְּרִיךְ הוּא אֲגַח בְּהוּ קְרָבָא. (ר' יצחק אמר מדירותא דלתתא לדיורא דלעילא) וְעָלַיְיהוּ כְּתִיב (תהילים ק״ד:ל״ה) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וְגוֹ'. מִן הָאָרֶץ: בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי. בֵּיהּ זִמְנָא כְּתִיב, בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ."],[[0,"תאנא ויבן משה וכו':","למדנו, ויבן משה מזבח כמו שבארנו. ויקרא שמו ה' נסי. ה' נסי ממש. שלה' היה הנס. למה. משום שעמלק לקח כל אלו שהיו נמולים ולא פרעו, וחתך אותם וזרק אותם כלפי מעלה, ואמר קח מה שרצית בו. בה בשעה מה כתוב, ויאמר כי יד על כס יה מלחמה לה' בעמלק מדר דר. מדר דר חסרים \u0003ו',\u0004 ללמד שדורות אלו שיש בהם מלחמה בעמלק, חסרים מדיורים שלמעלה, שאין השם שלם ואין הכסא שלם, וחסרים מדיורים שלמטה, שאין שלמות לתחתונים."],[1,"א\"ר יהודה וכו':","אר\"י, בכל דור ודור, בכל הדורות הבאים לעולם, אין לך דור שאין בהם מזרע הרע ההוא של עמלק, והקב\"ה עושה בהם מלחמה. ועליהם כתוב, יתמו חטאים מן הארץ וגו'. מן הארץ, היינו בעולם הזה ובעולם הבא. בו בזמן כתוב, ברכי נפשי את ה' הללויה."]],[[0,"","שָׁנִינוּ, וַיִּבֶן מֹשֶׁה מִזְבֵּחַ, כְּמוֹ שֶׁאָמַרְנוּ. וַיִּקְרָא שְׁמוֹ ה' נִסִּי, ה' נִסִּי מַמָּשׁ. לָמָּה? מִשּׁוּם שֶׁעֲמָלֵק לָקַח כָּל אוֹתָם מְהוּלִים שֶׁלֹּא נִפְרְעוּ, וּמָל אוֹתָם וְזָרַק אוֹתָם לְמַעְלָה, וְאָמַר: טֹל מַה שֶּׁרָצִיתָ בּוֹ. בְּאוֹתָהּ שָׁעָה מַה כָּתוּב? וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַה' בַּעֲמָלֵק מִדֹּר דֹּר. מִדֹּר דֹּר חֲסֵרִים, מֵהַדַּיָּרִים שֶׁל מַעְלָה וּמֵהַדַּיָּרִים שֶׁל מַטָּה."],[1,"","אָמַר רַבִּי יְהוּדָה, בְּכָל דּוֹר וָדוֹר, בְּכָל הַדּוֹרוֹת שֶׁבָּאִים לָעוֹלָם, אֵין לְךְ דּוֹר שֶׁאֵין בּוֹ מֵאוֹתוֹ זֶרַע רַע, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹרֵךְ בָּהֶם קְרָב. רַבִּי יִצְחָק אָמַר (מהדיור שלמטה לדיור שלמעלה), וַעֲלֵיהֶם כָּתוּב (תהלים קד) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וְגוֹ'. מִן הָאָרֶץ - בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. בְּאוֹתוֹ זְמַן כָּתוּב, בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ."]]]]};
